SECTION "bank0",ROM0[$61]

DisableLCD:
    xor a
    ld [$ff0f],a
    ld a,[$ffff]
    ld b,a
    res 0,a
    ld [$ffff],a
.waitVBlank
    ld a,[$ff44]
    cp $91
    jr nz,.waitVBlank
    ld a,[$ff40]
    and a,$7f    ; res 7,a
    ld [$ff40],a
    ld a,b
    ld [$ffff],a
    ret

EnableLCD:
    ld a,[$ff40]
    set 7,a
    ld [$ff40],a
    ret

CleanLCD_OAM:
    xor a
    ld hl,wOAMBuffer
    ld b,$a0
.loop
    ld [hli],a
    dec b
    jr nz,.loop
    ret

ResetLCD_OAM:
    ld a,$a0
    ld hl,wOAMBuffer
    ld de,$0004
    ld b,$28
.loop
    ld [hl],a
    add hl,de
    dec b
    jr nz,.loop
    ret

FarCopyData:
; copy bc bytes of data from a:hl to de
    ld [$CEE9],a ; save future bank # for later
    ld a,[H_LOADEDROMBANK] ; get current bank #
    push af
    ld a,[$CEE9] ; get future bank #,switch
    call RoutineForRealGB
    call CopyData
    pop af       ; okay,done,time to switch back
    jr RoutineForRealGB

CopyData:
; copy bc bytes of data from hl to de
    ld a,[hli]
    ld [de],a
    inc de
    dec bc
    ld a,c
    or b
    jr nz,CopyData
    ret

CheckIfThisIsInAGBC:
    ld [wFlagGameBoyColor],a
    cp $11
    jr nz,.NotGBC
    ld a,BANK(InizializzaParametriGBC)
    call RoutineForRealGB
    call InizializzaParametriGBC
    xor a
    call RoutineForRealGB
.NotGBC
    jp Start

PostVBlankHandler:
    ld a,[wFlagGameBoyColor]
    cp $11
    ret nz ; NotGBC
    ld a,BANK(FF47toColor)
    call RoutineForRealGB
    jp FF47toColor

FakeGiveItem:
    ld a,b
    ld [$d11e],a
    jp HackForGetItemName

RoutineForRealGB:
    ld [H_LOADEDROMBANK],a
    push af
    and a
    jr nz,.NotZero
    inc a
.NotZero
    ld [$2000],a
    pop af
    ret

SECTION "romheader",ROM0[$100]
    jp CheckIfThisIsInAGBC

SECTION "start",ROM0[$150]

Start:
    xor a
    ld [$cf1a],a ; same value ($00) either way
    jp InitGame

; this function directly reads the joypad I/O register
; it reads many times in order to give the joypad a chance to stabilize
; it saves a result in [$fff8] in the following format
; (set bit indicates pressed button)
; bit 0 - A button
; bit 1 - B button
; bit 2 - Select button
; bit 3 - Start button
; bit 4 - Right
; bit 5 - Left
; bit 6 - Up
; bit 7 - Down
ReadJoypadRegister:
    ld a,%00100000 ; select direction keys
    ld c,$00
    ld [rJOYP],a
    ld a,[rJOYP]
    ld a,[rJOYP]
    ld a,[rJOYP]
    ld a,[rJOYP]
    ld a,[rJOYP]
    ld a,[rJOYP]
    cpl ; complement the result so that a set bit indicates a pressed key
    and a,%00001111
    swap a ; put direction keys in upper nibble
    ld b,a
    ld a,%00010000 ; select button keys
    ld [rJOYP],a
    ld a,[rJOYP]
    ld a,[rJOYP]
    ld a,[rJOYP]
    ld a,[rJOYP]
    ld a,[rJOYP]
    ld a,[rJOYP]
    ld a,[rJOYP]
    ld a,[rJOYP]
    ld a,[rJOYP]
    ld a,[rJOYP]
    cpl ; complement the result so that a set bit indicates a pressed key
    and a,%00001111
    or b ; put button keys in lower nibble
    ld [H_JOYPADSTATE],a ; save joypad state
    ld a,%00110000 ; unselect all keys
    ld [rJOYP],a
    ret

; function to update the joypad state variables
; output:
; [H_NEWLYRELEASEDBUTTONS] = keys released since last time
; [H_NEWLYPRESSEDBUTTONS] = keys pressed since last time
; [H_CURRENTPRESSEDBUTTONS] = currently pressed keys
GetJoypadState:
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,BANK(_GetJoypadState)
    call RoutineForRealGB
    call _GetJoypadState
    pop af
    jp RoutineForRealGB

RestoreChangedBlocks:
    ld a,[W_CURMAP]
    ld hl,wChangedBlocksMapId
    cp [hl]
    ld [hli],a
    jr nz,.MapChange
    ld a,[hli] ; wChangedBlocksNum
    and a
    ret z
    ld b,a
.loop
    ld a,[hli] ; H
    ld d,a
    ld a,[hli] ; L
    ld e,a
    ld a,[hli] ; ID
    ld [de],a
    dec b
    jr nz,.loop
    ret
.MapChange
    ld a,[hl] ; wChangedBlocksNum
    and a
    push af
    xor a
    ld bc,3 * 15 + 1
    call FillMemory
    pop af
    ret

LoadTileBlockMapAndRedrawMapView:
    BANKSWITCH RunMapGraphicalScript
    call LoadTileBlockMap
    ret z ; If No Tile to Restore
    PREDEF_JUMP RedrawMapView

BackupNearPlayerTiles:
    ld bc,Tile_A_OFFSET
    call .ReadAndWrite
    ld bc,Tile_B_OFFSET
    call .ReadAndWrite
    ld bc,Tile_C_OFFSET
    call .ReadAndWrite
    ld bc,Tile_D_OFFSET
    call .ReadAndWrite
    ld bc,Tile_E_OFFSET
    call .ReadAndWrite
    ld bc,Tile_F_OFFSET
    call .ReadAndWrite
    ld bc,Tile_G_OFFSET
    call .ReadAndWrite
    ld bc,Tile_H_OFFSET
    call .ReadAndWrite
    ld bc,Tile_I_OFFSET
    call .ReadAndWrite
    ld bc,Tile_J_OFFSET
    call .ReadAndWrite
    ld bc,Tile_K_OFFSET
    call .ReadAndWrite
    ld bc,Tile_L_OFFSET
    call .ReadAndWrite
    ld bc,Tile_M_OFFSET
    call .ReadAndWrite
    ld bc,Tile_N_OFFSET
    call .ReadAndWrite
    ld bc,Tile_O_OFFSET
    call .ReadAndWrite
    ld bc,Tile_P_OFFSET
    call .ReadAndWrite
    ld bc,Tile_Q_OFFSET
    call .ReadAndWrite
    ld bc,Tile_R_OFFSET
    call .ReadAndWrite
    ld bc,Tile_S_OFFSET
    call .ReadAndWrite
    ld bc,Tile_T_OFFSET
.ReadAndWrite
    push hl
    add hl,bc
    ld a,[hl]
    pop hl
    ld [de],a
    inc de
    ret

GetDirectionOffset:
    ld a,[$c109] ; Direction
    and a ; D_DOWN
    jr z,.down
    cp D_UP
    jr z,.up
    cp D_LEFT
    jr z,.left
    ld a,COLL_RIGHT
    ld e,COLL_RIGHT_OFFSET
    ret
.down
    ld a,COLL_DOWN
    ld e,COLL_DOWN_OFFSET
    ret
.up
    ld a,COLL_UP
    ld e,COLL_UP_OFFSET
    ret
.left
    ld a,COLL_LEFT
    ld e,COLL_LEFT_OFFSET
    ret

TestPhysicalSpecial:
    PREDEF TestPhysicalSpecial_
    ld a,b
    and a
    ret

; Input $D11E = Pokemon ID
; Output a    = Pokedex ID
IndexToPokedexAndRestoreD11E:
    push de
    push bc
    push hl
    ld hl,$d11e
    ld b,[hl]
    push hl
    PREDEF IndexToPokedex
    pop hl
    ld a,[hl]
    ld [hl],b
    pop hl
    pop bc
    pop de
    ret

GoodCopyVideoDataDouble:
    ld a,[rLCDC]
    bit 7,a ; is the LCD enabled?
    jp nz,CopyVideoDataDouble ; if LCD is on,transfer during V-blank
    ld a,b
    push hl
    push de
    ld h,0
    ld l,c
    add hl,hl
    add hl,hl
    add hl,hl
    add hl,hl
    ld b,h
    ld c,l
    pop hl
    pop de
    jp FarCopyDataDouble ; if LCD is off,transfer all at once

PlayCryAndDecreaseSkillEnergy:
    call CheckAndDecreaseSkillEnergy
    ld a,[wSkillMonID]
    call GetCryData ; get cry data
    call PlaySound ; play sound
    xor a
    ld [wSkillMonID],a
    ret

CheckSkillEnergy:
    ld a,[wWhichPokemon]
    ld hl,W_PARTYMON1_MOVE1PP
    ld bc,44
    call AddNTimes
    ld a,[hl]
    sub 10
    ret

CheckAndDecreaseSkillEnergy:
    call CheckSkillEnergy
    jr c,.noEnergy
    ld [hl],a ; New Energy Value
.noEnergy
    ret

; copies the tile patterns for letters and numbers into VRAM
LoadFontTilePatterns:
    ld de,FontGraphics
    ld hl,$8800
    ld bc,(BANK(FontGraphics) << 8 | $80)
    jp GoodCopyVideoData

PlayCryAndUpdatePokedex:
    ld [wMonIdCryAndDex],a
    call PlayCry
    ld a,[$d74b]
    bit 5,a ; does the player have the pokedex?
    ret z
    ld a,[wMonIdCryAndDex]
    call IsPokemonSeen
    ret nz ; rcf
.wait
    call GetJoypadStateLowSensitivity
    ld a,[$ffb5]
    and %00000011 ; ▼▲◄►StSeBA
    and a ; was a key pressed?
    jr z,.wait
    ld a,[wMonIdCryAndDex]
    call UpdatePokedex
    scf
    ret

; Input a = Pokemon ID
; Output z flag set = Pokemon NOT Seen
IsPokemonSeen:
    push bc ; Backup bc
    push af ; Backup a
    push hl ; Backup hl
    ld hl,$d11e
    ld b,[hl]
    push hl ; Backup $d11e
    push bc ; ...
    ld [$d11e],a
    call IndexToPokedexAndRestoreD11E
    ld c,a
    ld b,2 ; read
    ld hl,wPokedexSeen
    PREDEF HandleBitArray
    ld a,c
    and a ; rcf
    pop bc ; Restore $d11e
    pop hl ; ...
    ld [hl],b
    pop hl ; Restore hl
    pop bc ; Restore a
    ld a,b ; ...
    pop bc ; Restore bc
    ret

UpdatePokedex:
    push af
    call IsPokemonSeen
    ld hl,.LoadPokedexText
    call z,PrintText
    pop af
    jp DisplayPokedex
.LoadPokedexText
    TX_FAR _ItemUseBallText06
    db $13,$06
    db "@"

BackupHeader:
    ld hl,W_MONHEADER
    ld de,GenericBuffer+1
    jr HeaderCommon

RestoreHeader:
    ld hl,GenericBuffer+1
    ld de,W_MONHEADER
HeaderCommon:
    ld bc,28
    jp CopyData

GbPalComplete:
    ld a,[wRunningOnSGB]
    and a
    jp z,GBPalNormal
    ld a,%11100100
    jp GBPalCommon

; Change Battle Screen Palette to Player's Pkmn Color
GoPAL_SET_CF1C_NoHpPal:
    ld hl,wFlagNoHpPalBit2
    set 2,[hl]
    jp GoPAL_SET_CF1C

GoToTop:
    ld a,[H_NEWLYPRESSEDBUTTONS] ; ▼▲◄►StSeBA
    bit 7,a
    ret z
GoToTop2:
    xor a
    ld [hl],a
    ld [wCurrentMenuItem],a
    ret

GoToBottom:
    ld a,[H_NEWLYPRESSEDBUTTONS] ; ▼▲◄►StSeBA
    bit 6,a
    ret z
GoToBottom2:
    ld a,[$d12a]
    sub 3
    jr nc,.done
    add 2
    jr .end
.done
    ld [hl],a
    ld a,2
.end
    ld [wCurrentMenuItem],a
    ret

GetLeftTileOfHPBar:
    ld a,[wListMenuID] ; Is Party Menu?
    cp 2               ; ...
    ld a,$71 ; left of HP bar tile 1
    ret nz ; NotParty
    dec a ; $70 ; Energy Symbol in Party Menu
    ret

HandleMenuInputWithWrap:
    ld a,1
    ld [wMenuWrappingEnabled],a
    jp HandleMenuInput

GetSpecialListNameOrGetItemName:
    BANKSWITCH_JUMP GetSpecialListNameOrGetItemName_

SECTION "HandleMidJump",ROM0[$039e]

; this function calls a function that takes necessary actions
; at the beginning of each overworld loop iteration as the player jumps
; down a ledge
; it also ends the jump when it's completed
HandleMidJump: ; 039e (0:039e)
    BANKSWITCH_JUMP _HandleMidJump

; this is jumped to immediately after loading a save / starting a new game / loading a new map
EnterMap: ; 03a6 (0:03a6)
    ld a,$ff
    ld [wJoypadForbiddenButtonsMask],a
    call LoadMapData ; load map data
    BANKSWITCH Func_c335 ; initialize some variables
    ld hl,$d72c
    bit 0,[hl]
    jr z,.doNotCountSteps
    ld a,$03
    ld [$d13c],a ; some kind of step counter (counts up to 3 steps?)
.doNotCountSteps
    ld hl,$d72e
    bit 5,[hl] ; did a battle happen immediately before this?
    res 5,[hl] ; unset the "battle just happened" flag
    call z,ResetStrength
    call nz,MapEntryAfterBattle
    ld hl,$d732
    ld a,[hl]
    and a,$18
    jr z,.didNotFlyOrTeleportIn
    res 3,[hl]
    BANKSWITCH Func_70510 ; display fly/teleport in graphical effect
    call UpdateSprites ; move sprites
.didNotFlyOrTeleportIn
    BANKSWITCH CheckForceBikeOrSurf ; handle currents in SF islands and forced bike riding in cycling road
    ld hl,$d72d
    res 5,[hl]
    call UpdateSprites ; move sprites
    ld hl,$d126
    set 5,[hl]
    set 6,[hl]
    xor a
    ld [wJoypadForbiddenButtonsMask],a

SECTION "OverworldLoop",ROM0[$03ff]

OverworldLoop: ; 03ff (0:03ff)
    call Delay2
    call SynchronizeParty
    call LoadGBPal
    ld a,[$d736]
    bit 6,a ; jumping down a ledge?
    call nz,HandleMidJump
    ld a,[wWalkCounter]
    and a
    jp nz,.moveAhead ; if the player sprite has not yet completed the walking animation
    call GetJoypadStateOverworld ; get joypad state (which is possibly simulated)
    BANKSWITCH Func_1e988
    ld a,[$da46]
    and a
    jp nz,WarpFound2
    ld hl,$d72d
    bit 3,[hl]
    res 3,[hl]
    jp nz,WarpFound2
    call OverworldHackRoutine
    ld a,[$d732]
    and a,$18
    jp nz,HandleFlyOrTeleportAway
    ld a,[W_CUROPPONENT] ; $d059
    and a
    jp nz,.newBattle
    call IsSpriteInFrontOfPlayer4
    ld hl,wCollisionWithSpriteBit5
    res 5,[hl]
    jr z,.NoSpriteCollision
    set 5,[hl]
.NoSpriteCollision
    ld a,[$d730]
    bit 7,a ; are we simulating button presses?
    jr z,.notSimulating
    ld a,[H_CURRENTPRESSEDBUTTONS]
    jr .checkIfStartIsPressed
.notSimulating
    ld a,[H_NEWLYPRESSEDBUTTONS]
.checkIfStartIsPressed
    bit 3,a ; start button
    jr z,.startButtonNotPressed
; if START is pressed
    xor a
    ld [$ff8c],a ; the $2920 ID for the start menu is 0
    jr .displayDialogue
.startButtonNotPressed
    bit 2,a ; was the select button pressed?
    jr z,.selectButtonNotPressed
; if SELECT is pressed
    BANKSWITCH SelectInOverWorld
    jr OverworldLoop
.selectButtonNotPressed
    bit 0,a ; A button
    jp z,.checkIfDownButtonIsPressed
; if A is pressed
    ld a,[$d730]
    bit 2,a
    jp nz,.noDirectionButtonsPressed
    call IsPlayerCharacterBeingControlledByGame
    jr nz,.checkForOpponent
    call CheckForHiddenObjectOrBookshelfOrCardKeyDoor ; check for hidden items,PC's,etc.
    ld a,[$ffeb]
    and a
    jp z,OverworldLoop
    ld hl,wOverworldPressABit2
    set 2,[hl]
    call IsSpriteOrSignInFrontOfPlayer ; check for sign or sprite in front of the player
    ld hl,wOverworldPressABit2
    res 2,[hl]
    ld a,[$ff8c] ; $2920 ID for NPC/sign text,if any
    and a
    jp z,OverworldLoop
.displayDialogue
    PREDEF Func_c586 ; check what is in front of the player
    call UpdateSprites ; move sprites
    ld a,[wFlags_0xcd60]
    bit 2,a
    jr nz,.checkForOpponent
    bit 0,a
    jr nz,.checkForOpponent
    FuncCoord 8,9 ; $c45c
    ld a,[Coord]
    ld [$cf0e],a
    call DisplayTextID ; display either the start menu or the NPC/sign text
    ld a,[$cc47]
    and a
    jr z,.checkForOpponent
    dec a
    ld a,$00
    ld [$cc47],a
    jr z,.changeMap
    PREDEF LoadSAV
    ld a,[W_CURMAP]
    ld [$d71a],a
    call SpecialWarpIn
    ld a,[W_CURMAP]
    call SwitchToMapRomBank ; switch to the ROM bank of the current map
    ld hl,$d367
    set 7,[hl]
.changeMap
    jp EnterMap
.checkForOpponent
    ld a,[W_CUROPPONENT] ; $d059
    and a
    jp nz,.newBattle
    jp OverworldLoop
.noDirectionButtonsPressed
    ld hl,wFlags_0xcd60
    res 2,[hl]
    call UpdateSprites ; move sprites
    ld a,$01
    ld [$cc4b],a
    ld a,[$d528] ; the direction that was pressed last time
    and a
    jp z,OverworldLoop
; if a direction was pressed last time
    ld [$d529],a ; save the last direction
    xor a
    ld [$d528],a ; zero the direction
    jp OverworldLoop
.checkIfDownButtonIsPressed
    ld a,[H_CURRENTPRESSEDBUTTONS] ; current joypad state
    bit 7,a ; down button
    jr z,.checkIfUpButtonIsPressed
    ld a,$01
    ld [$c103],a
    ld a,$04
    jr .handleDirectionButtonPress
.checkIfUpButtonIsPressed
    bit 6,a ; up button
    jr z,.checkIfLeftButtonIsPressed
    ld a,$ff
    ld [$c103],a
    ld a,$08
    jr .handleDirectionButtonPress
.checkIfLeftButtonIsPressed
    bit 5,a ; left button
    jr z,.checkIfRightButtonIsPressed
    ld a,$ff
    ld [$c105],a
    ld a,$02
    jr .handleDirectionButtonPress
.checkIfRightButtonIsPressed
    bit 4,a ; right button
    jr z,.noDirectionButtonsPressed
    ld a,$01
    ld [$c105],a
.handleDirectionButtonPress
    ld [$d52a],a ; new direction
    ld a,[$d730]
    bit 7,a ; are we simulating button presses?
    jr nz,.noDirectionChange ; ignore direction changes if we are
    ld a,[$cc4b]
    and a
    jr z,.noDirectionChange
    push hl
    ld hl,wFlagFollowBoulderBit7
    bit 7,[hl]
    pop hl
    jr nz,.forceDirectionChange
    ld a,[$d52a] ; new direction
    ld b,a
    ld a,[$d529] ; old direction
    cp b
    jr z,.noDirectionChange
; the code below is strange
; it computes whether or not the player did a 180 degree turn,but then overwrites the result
; also,it does a seemingly pointless loop afterwards
;    swap a ; put old direction in upper half
;    or b ; put new direction in lower half
;    cp $48 ; change dir from down to up
;    jr nz,.notDownToUp
;    ld a,$02
;    ld [$d528],a
;    jr .oddLoop
;.notDownToUp
;    cp $84 ; change dir from up to down
;    jr nz,.notUpToDown
;    ld a,$01
;    ld [$d528],a
;    jr .oddLoop
;.notUpToDown
;    cp $12 ; change dir from right to left
;    jr nz,.notRightToLeft
;    ld a,$04
;    ld [$d528],a
;    jr .oddLoop
;.notRightToLeft
;    cp $21 ; change dir from left to right
;    jr nz,.oddLoop
;    ld a,$08
;    ld [$d528],a
.oddLoop
    ld hl,wFlags_0xcd60
    set 2,[hl]
    ld hl,$cc4b
    dec [hl]
    jr nz,.oddLoop
    ld a,[$d52a]
    ld [$d528],a
.forceDirectionChange
    call NewBattle
    jp c,.battleOccurred
    jp OverworldLoop
.noDirectionChange
    ld a,[$d52a] ; current direction
    ld [$d528],a ; save direction
    call UpdateSprites ; move sprites
    ld a,[$d700]
    cp $02 ; surfing
    jr z,.surfing
; not surfing
    call CollisionCheckOnLand
    jr nc,.noCollision
    push hl
    ld hl,$d736
    bit 2,[hl]
    pop hl
    jp z,OverworldLoop
    push hl
    call ExtraWarpCheck ; sets carry if there is a potential to warp
    pop hl
    jp c,CheckWarpsCollision
    jp OverworldLoop
.surfing
    call CollisionCheckOnWater
    jp c,OverworldLoop
.noCollision
    ld a,$08
    ld [wWalkCounter],a
    jr .moveAhead2
.moveAhead
    ld a,[$d736]
    bit 7,a
    jr z,.noSpinning
    BANKSWITCH Func_44fd7 ; spin while moving
.noSpinning
    call UpdateSprites ; move sprites
.moveAhead2
    ld hl,wFlags_0xcd60
    res 2,[hl]
    call TrySpeedUp
    call AdvancePlayerSprite ; Speed 1x
    ld a,[wWalkCounter] ; $cfc5
    and a
    jp nz,CheckMapConnections ; it seems like this check will never succeed (the other place where CheckMapConnections is run works)
; walking animation finished
    ld a,[$d730]
    bit 7,a
    jr nz,.doneStepCounting ; if button presses are being simulated,don't count steps
; step counting
    ld hl,$d13b ; step counter
    dec [hl]
    ld a,[$d72c]
    bit 0,a
    jr z,.doneStepCounting
    ld hl,$d13c
    dec [hl]
    jr nz,.doneStepCounting
    ld hl,$d72c
    res 0,[hl]
.doneStepCounting
    BANKSWITCH Func_1e997 ; Forced also in "not safari" because Count FossilSteps
    ld a,[$d790]
    bit 7,a ; in the safari zone?
    jr z,.notSafariZone
    ld a,[$da46]
    and a
    jp nz,WarpFound2
.notSafariZone
    ld a,[W_ISINBATTLE]
    and a
    jp nz,CheckWarpsNoCollision
    PREDEF Func_c69c ; decrement HP of poisoned pokemon
    ld a,[$d12d]
    and a
    jp nz,HandleBlackOut ; if all pokemon fainted
.newBattle
    call NewBattle
    ld hl,$d736
    res 2,[hl]
    jp nc,CheckWarpsNoCollision ; check for warps if there was no battle
.battleOccurred
    ld hl,$d72d
    res 6,[hl]
    ld hl,W_FLAGS_D733
    res 3,[hl]
    ld hl,$d126
    set 5,[hl]
    set 6,[hl]
    xor a
    ld [H_CURRENTPRESSEDBUTTONS],a ; clear joypad state
    call GetCurrentOldAdventureMap
    cp CINNABAR_GYM
    jr nz,.notCinnabarGym
    ld hl,$d79b
    set 7,[hl]
.notCinnabarGym
    ld hl,$d72e
    set 5,[hl]
    call GetCurrentOldAdventureMap
    cp OAKS_LAB
    jp z,.noFaintCheck
    BANKSWITCH AnyPokemonAliveCheck ; check if all the player's pokemon fainted
    call RestoreFaintenedWith1HP
    ld a,d
    and a
    jr z,.allPokemonFainted
.noFaintCheck
    ld c,$0a
    call DelayFrames
    jp EnterMap
.allPokemonFainted
    ld a,$ff
    ld [$d057],a
    call RunMapScript
    jp HandleBlackOut

; function to determine if there will be a battle and execute it (either a trainer battle or wild battle)
; sets carry if a battle occurred and unsets carry if not
NewBattle:
    ld a,[$d72d]
    bit 4,a
    jr nz,.noBattle
    call IsPlayerCharacterBeingControlledByGame
    jr nz,.noBattle
    ld a,[$d72e]
    bit 4,a
    jr nz,.noBattle
    ld a,[W_UNKNOWNDUNGEON3CURSCRIPT]
    cp $03 ; WaitGengarMoving
    jr z,.noBattle
    BANKSWITCH_JUMP InitBattle ; determines if a battle will occurr and runs the battle if so
.noBattle
    and a
    ret

;appears to be called twice inside function $C38B
;if $d700,$d11a == $1 then biking
;if $d700,$d11a == $2 then surfing
ForceBikeOrSurf:
    xor a
    ld [wSurfingMonID],a
    ld b,5 ;graphics bank 5
    ld hl,LoadPlayerSpriteGraphics ;load player sprite graphics
    call Bankswitch ;loads bank 5 and then calls LoadPlayerSpriteGraphics
    jp PlayDefaultMusicFadeOutCurrent ; jp PlayDefaultMusic ;update map/player state?

; check if the player has stepped onto a warp after having not collided
CheckWarpsNoCollision: ; 06b4 (0:06b4)
    ld a,[$d3ae] ; number of warps
    and a
    jp z,CheckMapConnections
    ld a,[$d3ae] ; number of warps
    ld b,$00
    ld c,a
    ld a,[W_YCOORD]
    ld d,a
    ld a,[W_XCOORD]
    ld e,a
    ld hl,$d3af ; start of warp entries
CheckWarpsNoCollisionLoop: ; 06cc (0:06cc)
    ld a,[hli] ; check if the warp's Y position matches
    cp d
    jr nz,CheckWarpsNoCollisionRetry1
    ld a,[hli] ; check if the warp's X position matches
    cp e
    jr nz,CheckWarpsNoCollisionRetry2
; if a match was found
    push hl
    push bc
    ld hl,$d736
    set 2,[hl]
    BANKSWITCH Func_c49d ; check if the player sprite is standing on a "door" tile
    pop bc
    pop hl
    jr c,WarpFound1 ; if it is,go to 0735
    push hl
    push bc
    call ExtraWarpCheck ; sets carry if the warp is confirmed
    pop bc
    pop hl
    jr nc,CheckWarpsNoCollisionRetry2
; if the extra check passed
    ld a,[W_FLAGS_D733]
    bit 2,a
    jr nz,WarpFound1
    push de
    push bc
    call GetJoypadState
    pop bc
    pop de
    ld a,[H_CURRENTPRESSEDBUTTONS] ; current joypad state
    and a,%11110000 ; bit mask for directional buttons
    jr z,CheckWarpsNoCollisionRetry2 ; if directional buttons aren't being pressed,do not pass through the warp
    jr WarpFound1

; check if the player has stepped onto a warp after having collided
CheckWarpsCollision: ; 0706 (0:0706)
    ld a,[$d3ae] ; number of warps
    ld c,a
    ld hl,$d3af ; start of warp entries
.loop
    ld a,[hli] ; Y coordinate of warp
    ld b,a
    ld a,[W_YCOORD]
    cp b
    jr nz,.retry1
    ld a,[hli] ; X coordinate of warp
    ld b,a
    ld a,[W_XCOORD]
    cp b
    jr nz,.retry2
    ld a,[hli]
    ld [$d42f],a ; save target warp ID
    ld a,[hl]
    ld [$ff8b],a ; save target map
    jr WarpFound2
.retry1
    inc hl
.retry2
    inc hl
    inc hl
    dec c
    jr nz,.loop
    jp OverworldLoop

CheckWarpsNoCollisionRetry1: ; 072f (0:072f)
    inc hl
CheckWarpsNoCollisionRetry2: ; 0730 (0:0730)
    inc hl
    inc hl
    jp ContinueCheckWarpsNoCollisionLoop

WarpFound1: ; 0735 (0:0735)
    ld a,[hli]
    ld [$d42f],a ; save target warp ID
    ld a,[hli]
    ld [$ff8b],a ; save target map

WarpFound2: ; 073c (0:073c)
    call BugFixWarpDuringJump ; ld a,[$d3ae] ; number of warps
    sub c
    ld [$d73b],a ; save ID of used warp
    ld a,[W_CURMAP]
    ld [$d73c],a
    call CheckIfInOutsideMap
    jr nz,.indoorMaps
; this is for handling "outside" maps that can't have the 0xFF destination map
    ld a,[W_CURMAP]
    ld [wLastMap],a ; save current map as previous map
    ld a,[W_CURMAPWIDTH]
    ld [$d366],a
    ld a,[$ff8b] ; destination map number
    call ChangeCurMap ; change current map to destination map
    call PlayMapChangeSound
    call CheckDarkMap
    jr .done
; for maps that can have the 0xFF destination map,which means to return to the outside map; not all these maps are necessarily indoors,though
.indoorMaps
    ld a,[$ff8b] ; destination map
    cp $ff
    jr z,.goBackOutside
; if not going back to the previous map
    call ChangeCurMap ; current map number
    BANKSWITCH Func_70787 ; check if the warp was a Silph Co. teleporter
    ld a,[$cd5b]
    dec a
    jr nz,.notTeleporter
; if it's a Silph Co. teleporter
    ld hl,$d732
    set 3,[hl]
    call DoFlyOrTeleportAwayGraphics
    jr .skipMapChangeSound
.notTeleporter
    call PlayMapChangeSound
    call CheckDarkMap
.skipMapChangeSound
    ld hl,$d736
    res 0,[hl]
    res 1,[hl]
    jr .done
.goBackOutside
    ld a,[wLastMap] ; previous map
    call ChangeCurMap
    call PlayMapChangeSound
    call CheckDarkMap
.done
    ld hl,$d736
    set 0,[hl]
    call Func_12da
    jp EnterMap

IsSurfingOnLapras:
    ld a,[wSurfingMonID]
    cp LAPRAS
    ret

Tset0E_Coll:
    INCBIN "gfx/tilesets/0e.tilecoll"

SECTION "ContinueCheckWarpsNoCollisionLoop",ROM0[$07b5]

ContinueCheckWarpsNoCollisionLoop: ; 07b5 (0:07b5)
    inc b ; increment warp number
    dec c ; decrement number of warps
    jp nz,CheckWarpsNoCollisionLoop

; if no matching warp was found
CheckMapConnections: ; 07ba (0:07ba)
.checkWestMap
    ld a,[W_XCOORD]
    cp $ff
    jr nz,.checkEastMap
    ld a,[$d387]
    call ChangeCurMap
    ld a,[$d38f] ; new X coordinate upon entering west map
    ld [W_XCOORD],a
    ld a,[W_YCOORD]
    ld c,a
    ld a,[$d38e] ; Y adjustment upon entering west map
    add c
    ld c,a
    ld [W_YCOORD],a
    ld a,[$d390] ; pointer to upper left corner of map without adjustment for Y position
    ld l,a
    ld a,[$d391]
    ld h,a
    srl c
    jr z,.savePointer1
.pointerAdjustmentLoop1
    ld a,[$d38d] ; width of connected map
    add a,$06
    ld e,a
    ld d,$00
    ld b,$00
    add hl,de
    dec c
    jr nz,.pointerAdjustmentLoop1
.savePointer1
    ld a,l
    ld [$d35f],a ; pointer to upper left corner of current tile block map section
    ld a,h
    ld [$d360],a
    jp .loadNewMap
.checkEastMap
    ld b,a
    ld a,[$d525] ; map width
    cp b
    jr nz,.checkNorthMap
    ld a,[$d392]
    call ChangeCurMap
    ld a,[$d39a] ; new X coordinate upon entering east map
    ld [W_XCOORD],a
    ld a,[W_YCOORD]
    ld c,a
    ld a,[$d399] ; Y adjustment upon entering east map
    add c
    ld c,a
    ld [W_YCOORD],a
    ld a,[$d39b] ; pointer to upper left corner of map without adjustment for Y position
    ld l,a
    ld a,[$d39c]
    ld h,a
    srl c
    jr z,.savePointer2
.pointerAdjustmentLoop2
    ld a,[$d398]
    add a,$06
    ld e,a
    ld d,$00
    ld b,$00
    add hl,de
    dec c
    jr nz,.pointerAdjustmentLoop2
.savePointer2
    ld a,l
    ld [$d35f],a ; pointer to upper left corner of current tile block map section
    ld a,h
    ld [$d360],a
    jp .loadNewMap
.checkNorthMap
    ld a,[W_YCOORD]
    cp $ff
    jr nz,.checkSouthMap
    ld a,[$d371]
    call ChangeCurMap
    ld a,[$d378] ; new Y coordinate upon entering north map
    ld [W_YCOORD],a
    ld a,[W_XCOORD]
    ld c,a
    ld a,[$d379] ; X adjustment upon entering north map
    add c
    ld c,a
    ld [W_XCOORD],a
    ld a,[$d37a] ; pointer to upper left corner of map without adjustment for X position
    ld l,a
    ld a,[$d37b]
    ld h,a
    ld b,$00
    srl c
    add hl,bc
    ld a,l
    ld [$d35f],a ; pointer to upper left corner of current tile block map section
    ld a,h
    ld [$d360],a
    jp .loadNewMap
.checkSouthMap
    ld b,a
    ld a,[$d524]
    cp b
    jr nz,.didNotEnterConnectedMap
    ld a,[$d37c]
    call ChangeCurMap
    ld a,[$d383] ; new Y coordinate upon entering south map
    ld [W_YCOORD],a
    ld a,[W_XCOORD]
    ld c,a
    ld a,[$d384] ; X adjustment upon entering south map
    add c
    ld c,a
    ld [W_XCOORD],a
    ld a,[$d385] ; pointer to upper left corner of map without adjustment for X position
    ld l,a
    ld a,[$d386]
    ld h,a
    ld b,$00
    srl c
    add hl,bc
    ld a,l
    ld [$d35f],a ; pointer to upper left corner of current tile block map section
    ld a,h
    ld [$d360],a
.loadNewMap ; load the connected map that was entered
    call LoadMapHeader
    call PlayDefaultMusicFadeOutCurrent ; music
    ld b,$09
    call GoPAL_SET
; Since the sprite set shouldn't change,this will just update VRAM slots at
; $C2XE without loading any tile patterns.
    BANKSWITCH InitMapSprites
    call LoadTileBlockMapAndRedrawMapView
    jp OverworldLoop+3
.didNotEnterConnectedMap
    jp OverworldLoop

; function to play a sound when changing maps
PlayMapChangeSound: ; 08c9 (0:08c9)
    FuncCoord 8,8 ; $c448
    ld a,[Coord] ; upper left tile of the 4x4 square the player's sprite is standing on
    cp $0b ; door tile in tileset 0
    jr nz,.didNotGoThroughDoor
    ld a,$ad
    jr .playSound
.didNotGoThroughDoor
    ld a,$b5
.playSound
    jp PlaySound

; sets opponent type and mon set/lvl based on the engaging trainer data
InitBattleEnemyParameters:
    PREDEF_JUMP _InitBattleEnemyParameters

SECTION "CheckIfInOutsideMap",ROM0[$08e1]

CheckIfInOutsideMap: ; 08e1 (0:08e1)
; If the player is in an outside map (a town or route),set the z flag
    ld a,[W_CURMAPTILESET]
    and a ; most towns/routes have tileset 0
    ret z
    cp $17 ; Route 23 / Indigo Plateau
    ret

; this function is an extra check that sometimes has to pass in order to warp,beyond just standing on a warp
; the "sometimes" qualification is necessary because of CheckWarpsNoCollision's behavior
; depending on the map,either "function 1" or "function 2" is used for the check
; "function 1" passes when the player is at the edge of the map and is facing towards the outside of the map
; "function 2" passes when the the tile in front of the player is among a certain set
; sets carry if the check passes,otherwise clears carry
ExtraWarpCheck:
    call GetCurrentOldAdventureMap
    cp SS_ANNE_3
    jr z,.useFunction1
    cp ROCKET_HIDEOUT_1
    jr z,.useFunction2
    cp ROCKET_HIDEOUT_2
    jr z,.useFunction2
    cp ROCKET_HIDEOUT_4
    jr z,.useFunction2
    cp ROCK_TUNNEL_1
    jr z,.useFunction2
    ld a,[W_CURMAPTILESET]
    and a ; outside tileset
    jr z,.useFunction2
    cp $0d ; S.S. Anne tileset
    jr z,.useFunction2
    cp $0e ; Vermilion Port tileset
    jr z,.useFunction2
    cp $17 ; Indigo Plateau tileset
    jr z,.useFunction2
.useFunction1
    ld hl,Func_c3ff
    jr .doBankswitch
.useFunction2
    ld hl,Func_c44e
.doBankswitch
    ld b,BANK(Func_c44e)
    jp Bankswitch

MapEntryAfterBattle:
    BANKSWITCH Func_c35f ; function that appears to disable warp testing after collisions if the player is standing on a warp
    ld a,[$d35d]
    and a
    jp z,GBFadeIn2
    jp LoadGBPal

; for when all the player's pokemon faint
; other code prints the "you blacked out" message before this is called
HandleBlackOut:
    call GBFadeIn1
    ld a,$08
    call StopMusic
    ld hl,$d72e
    res 5,[hl]
    ld a,$01
    call RoutineForRealGB
    call ResetStatusAndHalveMoneyOnBlackout
    call SpecialWarpIn
    call PlayDefaultMusicFadeOutCurrent
    jp SpecialEnterMap

StopMusic:
    ld [wMusicHeaderPointer],a
    ld a,$ff
    ld [$c0ee],a
    call PlaySound
.waitLoop
    ld a,[wMusicHeaderPointer]
    and a
    jr nz,.waitLoop
    jp StopAllSounds

HandleFlyOrTeleportAway:
    call UpdateSprites ; move sprites
    call Delay3
    xor a
    ld [wBattleResult],a
    ld [$d700],a
    ld [$d057],a
    ld [$d35d],a
    ld hl,$d732
    set 2,[hl]
    res 5,[hl]
    call DoFlyOrTeleportAwayGraphics
    ld a,$01
    call RoutineForRealGB
    call SpecialWarpIn
    jp SpecialEnterMap

; function that calls a function to do fly away or teleport away graphics
DoFlyOrTeleportAwayGraphics:
    BANKSWITCH_JUMP _DoFlyOrTeleportAwayGraphics

; load sprite graphics based on whether the player is standing,biking,or surfing
LoadPlayerSpriteGraphics:
    ld a,[$d700]
    dec a
    jr z,.ridingBike
    ld a,[$ffd7]
    and a
    jr nz,.determineGraphics
    jr .startWalking
.ridingBike
    call IsBikeRidingAllowed
    jr c,.determineGraphics ; don't start walking if bike riding is allowed
.startWalking
    xor a
    ld [$d700],a
    ld [$d11a],a
.determineGraphics
    ld a,[$d700]
    and a
    jp z,LoadWalkingPlayerSpriteGraphics
    dec a
    jp z,LoadBikePlayerSpriteGraphics
    call IsSurfingOnLapras
    jp z,LoadSurfingLaprasSpriteGraphics
    jp LoadSurfingPlayerSpriteGraphics

; function to check if bike riding is allowed on the current map
; sets carry if bike is allowed,clears carry otherwise
IsBikeRidingAllowed:
    call GetCurrentOldAdventureMap
    cp ROUTE_23
    jr z,.allowed
    cp INDIGO_PLATEAU
    jr z,.allowed
    ld a,[W_CURMAPTILESET]
    ld b,a
    ld hl,.BikeRidingTilesets
.loop
    ld a,[hli]
    cp b
    jr z,.allowed
    inc a
    jr nz,.loop
    and a
    ret
.allowed
    scf
    ret
.BikeRidingTilesets
    db $00,$03,$0B,$11,$FF

; load the tile pattern data of the current tileset into VRAM
LoadTilesetTilePatternData:
    ld a,[$d52e]
    ld l,a
    ld a,[$d52f]
    ld h,a
    ld de,$9000
    ld bc,$0600
    ld a,[$d52b]
    jp FarCopyData2

; this loads the current maps complete tile map (which references blocks,not individual tiles) to C6E8
; it can also load partial tile maps of connected maps into a border of length 3 around the current map
LoadTileBlockMap:
; fill C6E8-CBFB with the background tile
    ld hl,$c6e8
    ld a,[$d3ad] ; background tile number
    ld d,a
    ld bc,$0514
.backgroundTileLoop
    ld a,d
    ld [hli],a
    dec bc
    ld a,c
    or b
    jr nz,.backgroundTileLoop
; load tile map of current map (made of tile block IDs)
; a 3-byte border at the edges of the map is kept so that there is space for map connections
    ld hl,$c6e8
    ld a,[W_CURMAPWIDTH]
    ld [$ff8c],a
    add a,$06 ; border (east and west)
    ld [$ff8b],a ; map width + border
    ld b,$00
    ld c,a
; make space for north border (next 3 lines)
    add hl,bc
    add hl,bc
    add hl,bc
    ld c,$03
    add hl,bc ; this puts us past the (west) border
    ld a,[$d36a] ; tile map pointer
    ld e,a
    ld a,[$d36b]
    ld d,a ; de = tile map pointer
    ld a,[W_CURMAPHEIGHT]
    ld b,a
.rowLoop ; copy one row each iteration
    push hl
    ld a,[$ff8c] ; map width (without border)
    ld c,a
.rowInnerLoop
    ld a,[de]
    inc de
    ld [hli],a
    dec c
    jr nz,.rowInnerLoop
; add the map width plus the border to the base address of the current row to get the next row's address
    pop hl
    ld a,[$ff8b] ; map width + border
    add l
    ld l,a
    jr nc,.noCarry
    inc h
.noCarry
    dec b
    jr nz,.rowLoop
.northConnection
    ld a,[$d371]
    cp $ff
    jr z,.southConnection
    call SwitchToMapRomBank
    ld a,[$d372]
    ld l,a
    ld a,[$d373]
    ld h,a
    ld a,[$d374]
    ld e,a
    ld a,[$d375]
    ld d,a
    ld a,[$d376]
    ld [$ff8b],a
    ld a,[$d377]
    ld [$ff8c],a
    call LoadNorthSouthConnectionsTileMap
.southConnection
    ld a,[$d37c]
    cp $ff
    jr z,.westConnection
    call SwitchToMapRomBank
    ld a,[$d37d]
    ld l,a
    ld a,[$d37e]
    ld h,a
    ld a,[$d37f]
    ld e,a
    ld a,[$d380]
    ld d,a
    ld a,[$d381]
    ld [$ff8b],a
    ld a,[$d382]
    ld [$ff8c],a
    call LoadNorthSouthConnectionsTileMap
.westConnection
    ld a,[$d387]
    cp $ff
    jr z,.eastConnection
    call SwitchToMapRomBank
    ld a,[$d388]
    ld l,a
    ld a,[$d389]
    ld h,a
    ld a,[$d38a]
    ld e,a
    ld a,[$d38b]
    ld d,a
    ld a,[$d38c]
    ld b,a
    ld a,[$d38d]
    ld [$ff8b],a
    call LoadEastWestConnectionsTileMap
.eastConnection
    ld a,[$d392]
    cp $ff
    jr z,.done
    call SwitchToMapRomBank
    ld a,[$d393]
    ld l,a
    ld a,[$d394]
    ld h,a
    ld a,[$d395]
    ld e,a
    ld a,[$d396]
    ld d,a
    ld a,[$d397]
    ld b,a
    ld a,[$d398]
    ld [$ff8b],a
    call LoadEastWestConnectionsTileMap
.done
    jp RestoreChangedBlocks

LoadNorthSouthConnectionsTileMap:
    ld c,$03
.loop
    push de
    push hl
    ld a,[$ff8b] ; width of connection
    ld b,a
.innerLoop
    ld a,[hli]
    ld [de],a
    inc de
    dec b
    jr nz,.innerLoop
    pop hl
    pop de
    ld a,[$ff8c] ; width of connected map
    add l
    ld l,a
    jr nc,.noCarry1
    inc h
.noCarry1
    ld a,[W_CURMAPWIDTH]
    add a,$06
    add e
    ld e,a
    jr nc,.noCarry2
    inc d
.noCarry2
    dec c
    jr nz,.loop
    ret

LoadEastWestConnectionsTileMap:
    push hl
    push de
    ld c,$03
.innerLoop
    ld a,[hli]
    ld [de],a
    inc de
    dec c
    jr nz,.innerLoop
    pop de
    pop hl
    ld a,[$ff8b] ; width of connected map
    add l
    ld l,a
    jr nc,.noCarry1
    inc h
.noCarry1
    ld a,[W_CURMAPWIDTH]
    add a,$06
    add e
    ld e,a
    jr nc,.noCarry2
    inc d
.noCarry2
    dec b
    jr nz,LoadEastWestConnectionsTileMap
    ret

SECTION "IsSpriteOrSignInFrontOfPlayer",ROM0[$0b23]

; function to check if there is a sign or sprite in front of the player
; if so,it is stored in [$FF8C]
; if not,[$FF8C] is set to 0
IsSpriteOrSignInFrontOfPlayer: ; 0b23 (0:0b23)
    xor a
    ld [$ff8c],a
    ld a,[$d4b0] ; number of signs in the map
    and a
    jr z,.extendRangeOverCounter
; if there are signs
    PREDEF Func_c586 ; get the coordinates in front of the player in de
    ld hl,$d4b1 ; start of sign coordinates
    ld a,[$d4b0] ; number of signs in the map
    ld b,a
    ld c,$00
.signLoop
    inc c
    ld a,[hli] ; sign Y
    cp d
    jr z,.yCoordMatched
    inc hl
    jr .retry
.yCoordMatched
    ld a,[hli] ; sign X
    cp e
    jr nz,.retry
.xCoordMatched
; found sign
    push hl
    push bc
    ld hl,$d4d1 ; start of sign text ID's
    ld b,$00
    dec c
    add hl,bc
    ld a,[hl]
    ld [$ff8c],a ; store sign text ID
    pop bc
    pop hl
    ret
.retry
    dec b
    jr nz,.signLoop
; check if the player is front of a counter in a pokemon center,pokemart,etc. and if so,extend the range at which he can talk to the NPC
.extendRangeOverCounter
    PREDEF Func_c586 ; get the tile in front of the player in c
    ld hl,$d532 ; list of tiles that extend talking range (counter tiles)
    ld b,$03
    ld d,$20 ; talking range in pixels (long range)
.counterTilesLoop
    ld a,[hli]
    cp c
    jr z,IsSpriteInFrontOfPlayer2 ; jumps if the tile in front of the player is a counter tile
    dec b
    jr nz,.counterTilesLoop
    ; ft

; part of the above function,but sometimes its called on its own,when signs are irrelevant
; the caller must zero [$FF8C]
IsSpriteInFrontOfPlayer: ; 0b6b (0:0b6b)
    ld d,$10 ; talking range in pixels (normal range)
IsSpriteInFrontOfPlayer2: ; 0b6d (0:0b6d)
    ld bc,$3c40 ; Y and X position of player sprite
    ld a,[$c109] ; direction the player is facing
.checkIfPlayerFacingUp
    cp $04
    jr nz,.checkIfPlayerFacingDown
; facing up
    ld a,b
    sub d
    ld b,a
    ld a,$08
    jr .doneCheckingDirection
.checkIfPlayerFacingDown
    cp $00
    jr nz,.checkIfPlayerFacingRight
; facing down
    ld a,b
    add d
    ld b,a
    ld a,$04
    jr .doneCheckingDirection
.checkIfPlayerFacingRight
    cp $0c
    jr nz,.playerFacingLeft
; facing right
    ld a,c
    add d
    ld c,a
    ld a,$01
    jr .doneCheckingDirection
.playerFacingLeft
; facing left
    ld a,c
    sub d
    ld c,a
    ld a,$02
.doneCheckingDirection
    ld [$d52a],a
    ld a,[$d4e1] ; number of sprites
    and a
    ret z
; if there are sprites
    ld hl,$c110
    ld d,a
    ld e,$01
.spriteLoop
    push hl
    ld a,[hli] ; image (0 if no sprite)
    and a
    jr z,.nextSprite
    call .CheckOverworldPressA
    jr nz,.SkipCheckGhost ; Talk
    cp SPRITE_GHOST
    jr z,.nextSprite
.SkipCheckGhost
    inc l
    ld a,[hli] ; sprite visibility
    inc a
    jr z,.nextSprite
    inc l
    ld a,[hli] ; Y location
    cp b
    jr nz,.nextSprite
    inc l
    ld a,[hl] ; X location
    cp c
    jr z,.foundSpriteInFrontOfPlayer
.nextSprite
    pop hl
    ld a,l
    add a,$10
    ld l,a
    inc e
    dec d
    jr nz,.spriteLoop
    ret
.foundSpriteInFrontOfPlayer
    pop hl
    ld a,l
    and a,$f0
    inc a
    ld l,a
    call .CheckOverworldPressA
    jr z,.SkipChangeSpriteDirection
    set 7,[hl] ; Talk = Turn Sprite direction to Player
.SkipChangeSpriteDirection
    ld a,e
    ld [$ff8c],a ; store sprite ID
    ret
.CheckOverworldPressA
    push hl
    ld hl,wOverworldPressABit2
    bit 2,[hl]
    pop hl
    ret

; function to check if the player will jump down a ledge and check if the tile ahead is passable (when not surfing)
; sets the carry flag if there is a collision,and unsets it if there isn't a collision
CollisionCheckOnLand:
    ld a,[wFlagFollowBoulderBit7]
    bit 7,a
    jr nz,.TryJumping
    ld a,[$cd38]
    and a ; simulate?
    jr nz,NoCollision
    call IsSpriteInFrontOfPlayer3
    jr nz,Collision
; if no sprite collision
.TryJumping
    ld d,%00000001 ; TryJumping
    call CheckExceptionTilePassable
    jr nc,NoCollision

Collision::
    ld a,[$c02a]
    cp $b4 ; check if collision sound is already playing
    jr z,.setCarry
    ld a,$b4
    call PlaySound ; play collision sound (if it's not already playing)
.setCarry
    scf
    ret

NoCollision::
    and a
    ret

CheckExceptionTilePassable:
    BANKSWITCH_JUMP _CheckExceptionTilePassable ; check if the player is trying to jump a ledge

; ──────────────────────
; Handle Ghost Battle
; ──────────────────────

CheckGhostType:
    push bc
    push af
    ld b,4
.loop
    ld a,[hli]
    cp GHOST
    jr z,.end
    dec b
    jr nz,.loop
    inc b ; rzf
.end
    pop bc
    ld a,b
    pop bc
    ret

CheckWildGhost:
    push bc
    push hl
    push af
    ld a,[W_ISINBATTLE]
    dec a
    jr nz,.end
    ld hl,W_ENEMYBATTSTATUS3
    bit TRANSFORMED,[hl]
    jr nz,.end
    ld hl,W_ENEMYMONTYPES
    call CheckGhostType
.end
    pop bc
    ld a,b
    pop hl
    pop bc
    ret

IsGhostBattle:
    push bc
    push hl
    push af
    ld a,[W_ISINBATTLE]
    dec a
    jr nz,.end
    call CheckWildGhost
    jr nz,.end
    call IsSilphScopeInBagNotDark
    ; ft
.end
    pop bc
    ld a,b
    pop hl
    pop bc
    ret

IsSilphScopeInBagNotDark:
    call IsSilphScopeInBag
    ret z ; z = not in bag
    ld a,[wBackupDarkMap] ; [$d35d]
    and a
    jr nz,.Dark
    ld a,1 ; rzf
    and a  ; ...
    ret
.Dark
    xor a ; szf
    ret

IsSilphScopeInBag:
    ld b,SILPH_SCOPE
    jp IsItemInBag ; z = not in bag

IsGhostBattlePlus:
    call IsGhostBattle
    ret z
    ; If No Standard Ghost Check Marowak Event
    ; CheckBossGhost
    push bc
    push af
    ld a,[W_CUROPPONENT]
    cp MAROWAK
    jr z,.marowak
    cp HAUNTER
    jr nz,.end
.SafariGhost
    call GetCurrentOldAdventureMap
    cp SAFARI_ZONE_WEST
    jr .end
.marowak
    call GetCurrentOldAdventureMap
    cp POKEMONTOWER_6
    ; ft
.end
    pop bc
    ld a,b
    pop bc
    ret

