; Free

SECTION "LoadCurrentMapView",ROM0[$0ca2]

; this builds a tile map from the tile block map based on the current X/Y coordinates of the player's character
LoadCurrentMapView: ; 0ca2 (0:0ca2)
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,[$d52b] ; tile data ROM bank
    call RoutineForRealGB ; switch to ROM bank that contains tile data
    ld a,[$d35f] ; address of upper left corner of current map view
    ld e,a
    ld a,[$d360]
    ld d,a
    ld hl,wTileMapBackup
    ld b,$05
.rowLoop ; each loop iteration fills in one row of tile blocks
    push hl
    push de
    ld c,$06
.rowInnerLoop ; loop to draw each tile block of the current row
    push bc
    push de
    push hl
    ld a,[de]
    ld c,a ; tile block number
    call DrawTileBlock
    pop hl
    pop de
    pop bc
    inc hl
    inc hl
    inc hl
    inc hl
    inc de
    dec c
    jr nz,.rowInnerLoop
; update tile block map pointer to next row's address
    pop de
    ld a,[W_CURMAPWIDTH]
    add a,$06
    add e
    ld e,a
    jr nc,.noCarry
    inc d
.noCarry
; update tile map pointer to next row's address
    pop hl
    ld a,$60
    add l
    ld l,a
    jr nc,.noCarry2
    inc h
.noCarry2
    dec b
    jr nz,.rowLoop
    ld hl,wTileMapBackup
    ld bc,$0000
.adjustForYCoordWithinTileBlock
    ld a,[W_YBLOCKCOORD]
    and a
    jr z,.adjustForXCoordWithinTileBlock
    ld bc,$0030
    add hl,bc
.adjustForXCoordWithinTileBlock
    ld a,[W_XBLOCKCOORD]
    and a
    jr z,.copyToVisibleAreaBuffer
    ld bc,$0002
    add hl,bc
.copyToVisibleAreaBuffer
    ld de,wTileMap ; base address for the tiles that are directly transfered to VRAM during V-blank
    ld b,$12
.rowLoop2
    ld c,$14
.rowInnerLoop2
    ld a,[hli]
    ld [de],a
    inc de
    dec c
    jr nz,.rowInnerLoop2
    ld a,$04
    add l
    ld l,a
    jr nc,.noCarry3
    inc h
.noCarry3
    dec b
    jr nz,.rowLoop2
    pop af
    call RoutineForRealGB ; restore previous ROM bank

    ld de,wBackupNearPlayerTiles
    FuncCoord 8,9 ; tile the player is on
    ld hl,Coord
    jp BackupNearPlayerTiles

SECTION "AdvancePlayerSprite",ROM0[$0d27]

AdvancePlayerSprite: ; 0d27 (0:0d27)
    ld a,[$c103] ; delta Y
    ld b,a
    ld a,[$c105] ; delta X
    ld c,a
    ld hl,wWalkCounter ; walking animation counter
    dec [hl]
    jr nz,.afterUpdateMapCoords
; if it's the end of the animation,update the player's map coordinates
    ld a,[W_YCOORD]
    add b
    ld [W_YCOORD],a
    ld a,[W_XCOORD]
    add c
    ld [W_XCOORD],a
.afterUpdateMapCoords
    ld a,[wWalkCounter] ; walking animation counter
    cp $07
    jp nz,.scrollBackgroundAndSprites
; if this is the first iteration of the animation
    ld a,c
    cp $01
    jr nz,.checkIfMovingWest
; moving east
    ld a,[$d526]
    ld e,a
    and a,$e0
    ld d,a
    ld a,e
    add a,$02
    and a,$1f
    or d
    ld [$d526],a
    jr .adjustXCoordWithinBlock
.checkIfMovingWest
    cp $ff
    jr nz,.checkIfMovingSouth
; moving west
    ld a,[$d526]
    ld e,a
    and a,$e0
    ld d,a
    ld a,e
    sub a,$02
    and a,$1f
    or d
    ld [$d526],a
    jr .adjustXCoordWithinBlock
.checkIfMovingSouth
    ld a,b
    cp $01
    jr nz,.checkIfMovingNorth
; moving south
    ld a,[$d526]
    add a,$40
    ld [$d526],a
    jr nc,.adjustXCoordWithinBlock
    ld a,[$d527]
    inc a
    and a,$03
    or a,$98
    ld [$d527],a
    jr .adjustXCoordWithinBlock
.checkIfMovingNorth
    cp $ff
    jr nz,.adjustXCoordWithinBlock
; moving north
    ld a,[$d526]
    sub a,$40
    ld [$d526],a
    jr nc,.adjustXCoordWithinBlock
    ld a,[$d527]
    dec a
    and a,$03
    or a,$98
    ld [$d527],a
.adjustXCoordWithinBlock
    ld a,c
    and a
    jr z,.pointlessJump ; mistake?
.pointlessJump
    ld hl,W_XBLOCKCOORD
    ld a,[hl]
    add c
    ld [hl],a
    cp $02
    jr nz,.checkForMoveToWestBlock
; moved into the tile block to the east
    xor a
    ld [hl],a
    ld hl,$d4e3
    inc [hl]
    ld de,$d35f
    call MoveTileBlockMapPointerEast
    jr .updateMapView
.checkForMoveToWestBlock
    cp $ff
    jr nz,.adjustYCoordWithinBlock
; moved into the tile block to the west
    ld a,$01
    ld [hl],a
    ld hl,$d4e3
    dec [hl]
    ld de,$d35f
    call MoveTileBlockMapPointerWest
    jr .updateMapView
.adjustYCoordWithinBlock
    ld hl,W_YBLOCKCOORD
    ld a,[hl]
    add b
    ld [hl],a
    cp $02
    jr nz,.checkForMoveToNorthBlock
; moved into the tile block to the south
    xor a
    ld [hl],a
    ld hl,$d4e2
    inc [hl]
    ld de,$d35f
    ld a,[W_CURMAPWIDTH]
    call MoveTileBlockMapPointerSouth
    jr .updateMapView
.checkForMoveToNorthBlock
    cp $ff
    jr nz,.updateMapView
; moved into the tile block to the north
    ld a,$01
    ld [hl],a
    ld hl,$d4e2
    dec [hl]
    ld de,$d35f
    ld a,[W_CURMAPWIDTH]
    call MoveTileBlockMapPointerNorth
.updateMapView
    call LoadCurrentMapView
    ld a,[$c103] ; delta Y
    cp $01
    jr nz,.checkIfMovingNorth2
; if moving south
    call ScheduleSouthRowRedraw
    jr .scrollBackgroundAndSprites
.checkIfMovingNorth2
    cp $ff
    jr nz,.checkIfMovingEast2
; if moving north
    call ScheduleNorthRowRedraw
    jr .scrollBackgroundAndSprites
.checkIfMovingEast2
    ld a,[$c105] ; delta X
    cp $01
    jr nz,.checkIfMovingWest2
; if moving east
    call ScheduleEastColumnRedraw
    jr .scrollBackgroundAndSprites
.checkIfMovingWest2
    cp $ff
    jr nz,.scrollBackgroundAndSprites
; if moving west
    call ScheduleWestColumnRedraw
.scrollBackgroundAndSprites
    ld a,[$c103] ; delta Y
    ld b,a
    ld a,[$c105] ; delta X
    ld c,a
    sla b
    sla c
    ld a,[$ffaf]
    add b
    ld [$ffaf],a ; update background scroll Y
    ld a,[$ffae]
    add c
    ld [$ffae],a ; update background scroll X
; shift all the sprites in the direction opposite of the player's motion
; so that the player appears to move relative to them
    ld hl,$c114
    ld a,[$d4e1] ; number of sprites
    and a ; are there any sprites?
    jr z,.done
    ld e,a
.spriteShiftLoop
    ld a,[hl]
    sub b
    ld [hli],a
    inc l
    ld a,[hl]
    sub c
    ld [hl],a
    ld a,$0e
    add l
    ld l,a
    dec e
    jr nz,.spriteShiftLoop
.done
    ret

; the following four functions are used to move the pointer to the upper left
; corner of the tile block map in the direction of motion

MoveTileBlockMapPointerEast: ; 0e65 (0:0e65)
    ld a,[de]
    add a,$01
    ld [de],a
    ret nc
    inc de
    ld a,[de]
    inc a
    ld [de],a
    ret

MoveTileBlockMapPointerWest: ; 0e6f (0:0e6f)
    ld a,[de]
    sub a,$01
    ld [de],a
    ret nc
    inc de
    ld a,[de]
    dec a
    ld [de],a
    ret

MoveTileBlockMapPointerSouth: ; 0e79 (0:0e79)
    add a,$06
    ld b,a
    ld a,[de]
    add b
    ld [de],a
    ret nc
    inc de
    ld a,[de]
    inc a
    ld [de],a
    ret

MoveTileBlockMapPointerNorth: ; 0e85 (0:0e85)
    add a,$06
    ld b,a
    ld a,[de]
    sub b
    ld [de],a
    ret nc
    inc de
    ld a,[de]
    dec a
    ld [de],a
    ret

; the following 6 functions are used to tell the V-blank handler to redraw
; the portion of the map that was newly exposed due to the player's movement

ScheduleNorthRowRedraw: ; 0e91 (0:0e91)
    FuncCoord 0,0
    ld hl,Coord
    call ScheduleRowRedrawHelper
    ld a,[$d526]
    ld [H_SCREENEDGEREDRAWADDR],a
    ld a,[$d527]
    ld [H_SCREENEDGEREDRAWADDR + 1],a
    ld a,REDRAWROW
    ld [H_SCREENEDGEREDRAW],a
    ret

ScheduleRowRedrawHelper: ; 0ea6 (0:0ea6)
    ld de,wScreenEdgeTiles
    ld c,$28
.loop
    ld a,[hli]
    ld [de],a
    inc de
    dec c
    jr nz,.loop
    ret

ScheduleSouthRowRedraw: ; 0eb2 (0:0eb2)
    FuncCoord 0,16
    ld hl,Coord
    call ScheduleRowRedrawHelper
    ld a,[$d526]
    ld l,a
    ld a,[$d527]
    ld h,a
    ld bc,$0200
    add hl,bc
    ld a,h
    and a,$03
    or a,$98
    ld [H_SCREENEDGEREDRAWADDR + 1],a
    ld a,l
    ld [H_SCREENEDGEREDRAWADDR],a
    ld a,REDRAWROW
    ld [H_SCREENEDGEREDRAW],a
    ret

ScheduleEastColumnRedraw: ; 0ed3 (0:0ed3)
    FuncCoord 18,0
    ld hl,Coord
    call ScheduleColumnRedrawHelper
    ld a,[$d526]
    ld c,a
    and a,$e0
    ld b,a
    ld a,c
    add a,18
    and a,$1f
    or b
    ld [H_SCREENEDGEREDRAWADDR],a
    ld a,[$d527]
    ld [H_SCREENEDGEREDRAWADDR + 1],a
    ld a,REDRAWCOL
    ld [H_SCREENEDGEREDRAW],a
    ret

ScheduleColumnRedrawHelper: ; 0ef2 (0:0ef2)
    ld de,wScreenEdgeTiles
    ld c,$12
.loop
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[hl]
    ld [de],a
    inc de
    ld a,19
    add l
    ld l,a
    jr nc,.noCarry
    inc h
.noCarry
    dec c
    jr nz,.loop
    ret

ScheduleWestColumnRedraw: ; 0f08 (0:0f08)
    FuncCoord 0,0
    ld hl,Coord
    call ScheduleColumnRedrawHelper
    ld a,[$d526]
    ld [H_SCREENEDGEREDRAWADDR],a
    ld a,[$d527]
    ld [H_SCREENEDGEREDRAWADDR + 1],a
    ld a,REDRAWCOL
    ld [H_SCREENEDGEREDRAW],a
    ret

; function to write the tiles that make up a tile block to memory
; Input: c = tile block ID,hl = destination address
DrawTileBlock: ; 0f1d (0:0f1d)
    push hl
    ld a,[$d52c] ; pointer to tiles
    ld l,a
    ld a,[$d52d]
    ld h,a
    ld a,c
    swap a
    ld b,a
    and a,$f0
    ld c,a
    ld a,b
    and a,$0f
    ld b,a ; bc = tile block ID * 0x10
    add hl,bc
    ld d,h
    ld e,l ; de = address of the tile block's tiles
    pop hl
    ld c,$04 ; 4 loop iterations
.loop ; each loop iteration,write 4 tile numbers
    push bc
    ld a,[de]
    ld [hli],a
    inc de
    ld a,[de]
    ld [hli],a
    inc de
    ld a,[de]
    ld [hli],a
    inc de
    ld a,[de]
    ld [hl],a
    inc de
    ld bc,$0015
    add hl,bc
    pop bc
    dec c
    jr nz,.loop
    ret

; function to update joypad state and simulate button presses
GetJoypadStateOverworld: ; 0f4d (0:0f4d)
    xor a
    ld [$c103],a
    ld [$c105],a
    call RunMapScript
    call GetJoypadState
    ld a,[W_FLAGS_D733]
    bit 3,a ; check if a trainer wants a challenge
    jr nz,.notForcedDownwards
    call GetCurrentOldAdventureMap
    cp ROUTE_17 ; Cycling Road
    jr nz,.notForcedDownwards
    ld a,[H_CURRENTPRESSEDBUTTONS] ; current joypad state
    and a,%11110011 ; bit mask for all directions and A/B
    jr nz,.notForcedDownwards
    ld a,%10000000 ; down pressed
    ld [H_CURRENTPRESSEDBUTTONS],a ; on the cycling road,if there isn't a trainer and the player isn't pressing buttons,simulate a down press
.notForcedDownwards
    ld a,[$d730]
    bit 7,a
    ret z
; if simulating button presses
    ld a,[H_CURRENTPRESSEDBUTTONS] ; current joypad state
    ld b,a
    ld a,[$cd3b] ; bit mask for button presses that override simulated ones
    and b
    ret nz ; return if the simulated button presses are overridden
    ld hl,$cd38 ; index of current simulated button press
    dec [hl]
    ld a,[hl]
    cp $ff
    jr z,.doneSimulating ; if the end of the simulated button presses has been reached
    ld hl,$ccd3 ; base address of simulated button presses
; add offset to base address
    add l
    ld l,a
    jr nc,.noCarry
    inc h
.noCarry
    ld a,[hl]
    ld [H_CURRENTPRESSEDBUTTONS],a ; store simulated button press in joypad state
    and a
    ret nz
    ld [H_NEWLYPRESSEDBUTTONS],a
    ld [H_NEWLYRELEASEDBUTTONS],a
    ret
; if done simulating button presses
.doneSimulating
    xor a
    ld [$cd3a],a
    ld [$cd38],a
    ld [$ccd3],a
    call ResetJoypadForbiddenButtonsMask ; ld [wJoypadForbiddenButtonsMask],a
    ld [H_CURRENTPRESSEDBUTTONS],a
    ld hl,$d736
    ld a,[hl]
    and a,%11111100 ; add bit 2 to handle warp after simulation
    ld [hl],a
    ld hl,$d730
    res 7,[hl]
    ret

; function to check the tile ahead to determine if the character should get on land or keep surfing
; sets carry if there is a collision and clears carry otherwise
; It seems that this function has a bug in it,but due to luck,it doesn't
; show up. After detecting a sprite collision,it jumps to the code that
; checks if the next tile is passable instead of just directly jumping to the
; "collision detected" code. However,it doesn't store the next tile in c,
; so the old value of c is used. 2429 is always called before this function,
; and 2429 always sets c to 0xF0. There is no 0xF0 background tile,so it
; is considered impassable and it is detected as a collision.
CollisionCheckOnWater:
    ld a,[$d730]
    bit 7,a
    jr nz,.noCollision ; return and clear carry if button presses are being simulated
    call IsSpriteInFrontOfPlayer3
    jr nz,.collision
; if no sprite collision
    ld d,%00000010 ; TryStopSurfing
    call CheckExceptionTilePassable
    jr nc,.noCollision

.collision
    jp Collision
.noCollision
    jp NoCollision

DelayFramesCredits:
    call CheckHallOfFameWin
    jr z,.delay
    push bc
    push de
    call GetJoypadState
    pop de
    pop bc
    ld a,[H_CURRENTPRESSEDBUTTONS] ; ▼▲◄►StSeBA
    bit 1,a
    ret nz
.delay
    call DelayFrame
    dec c
    jr nz,DelayFramesCredits
    ret

HackForOtherText:
    ; close if $FF is the textID or sprite index
    cp $ff
    jp z,CloseTextDisplay
    cp $fe
    jr z,.FlashLightText
    cp $fd
    jr z,.StrengthText
    ld a,[$d4e1] ; number of sprites
    jp ReturnInDisplayTextIDHack
.FlashLightText
    ld hl,.flashLightsAreaText
.TextEnd
    call PrintText
    jp AfterDisplayingTextID
.flashLightsAreaText
    TX_FAR _FlashLightsAreaText
    db "@"
.StrengthText
    ld hl,.UnnamedText_cdbb
    jr .TextEnd
.UnnamedText_cdbb:
    TX_FAR _UnnamedText_cdbb
    db "@"

SECTION "RunMapScript",ROM0[$101b]

; function to run the current map's script
RunMapScript: ; 101b (0:101b)
    push hl
    push de
    push bc
    BANKSWITCH TryPushingBoulder ; check if the player is pushing a boulder
    ld a,[wFlags_0xcd60]
    bit 1,a ; is the player pushing a boulder?
    jr z,.afterBoulderEffect
    BANKSWITCH DoBoulderDustAnimation ; displays dust effect when pushing a boulder
.afterBoulderEffect
    pop bc
    pop de
    pop hl
    call Func_310e
    ld a,[W_CURMAP]
    call SwitchToMapRomBank ; change to the ROM bank the map's data is in
    ld hl,W_MAPSCRIPTPTR
    ld a,[hli]
    ld h,[hl]
    ld l,a
    jp hl ; jump to script

LoadWalkingPlayerSpriteGraphics:
    ld de,RedSprite
    ld bc,(BANK(RedSprite) << 8) + $0c
    jr LoadPlayerSpriteGraphicsCommon

LoadSurfingPlayerSpriteGraphics:
    ld de,FloatSprite
    ld bc,(BANK(FloatSprite) << 8) + $0c
    jr LoadPlayerSpriteGraphicsCommon

LoadBikePlayerSpriteGraphics:
    ld de,RedCyclingSprite
    ld bc,(BANK(RedCyclingSprite) << 8) + $0c
    ; ft

LoadPlayerSpriteGraphicsCommon:
    ld hl,$8000
    push de
    push bc
    call CopyVideoData
    pop bc
    pop de
    ld a,$c0
    add e
    ld e,a
    jr nc,.noCarry
    inc d
.noCarry
    ld hl,$8800
    jp CopyVideoData

SECTION "LoadMapHeader",ROM0[$107c]

; function to load data from the map header
LoadMapHeader: ; 107c (0:107c)
    BANKSWITCH SetVisitedAndLoadMissableObj
    ld a,[W_CURMAPTILESET]
    ld [$d119],a
    ld a,[W_CURMAP]
    call SwitchToMapRomBank
    ld a,[W_CURMAPTILESET]
    ld b,a
    res 7,a
    ld [W_CURMAPTILESET],a
    ld [$ff8b],a
    bit 7,b
    ret nz

    BANKSWITCH GetPointerToBaseOfMapHeader ; hl = base of map header

;    call GetMapHeaderPointers ; ld hl,MapHeaderPointers
;    ld a,[W_CURMAP]
;    sla a
;    jr nc,.noCarry1
;    inc h
;.noCarry1
;    add l
;    ld l,a
;    jr nc,.noCarry2
;    inc h
;.noCarry2
;    ld a,[hli]
;    ld h,[hl]
;    ld l,a ; hl = base of map header

; copy the first 10 bytes (the fixed area) of the map data to D367-D370
    ld de,$d367
    ld c,$0a
.copyFixedHeaderLoop
    ld a,[hli]
    ld [de],a
    inc de
    dec c
    jr nz,.copyFixedHeaderLoop
; initialize all the connected maps to disabled at first,before loading the actual values
    ld a,$ff
    ld [$d371],a
    ld [$d37c],a
    ld [$d387],a
    ld [$d392],a
; copy connection data (if any) to WRAM
    ld a,[W_MAPCONNECTIONS]
    ld b,a
.checkNorth
    bit 3,b
    jr z,.checkSouth
    ld de,W_MAPCONN1PTR
    call CopyMapConnectionHeader
.checkSouth
    bit 2,b
    jr z,.checkWest
    ld de,W_MAPCONN2PTR
    call CopyMapConnectionHeader
.checkWest
    bit 1,b
    jr z,.checkEast
    ld de,W_MAPCONN3PTR
    call CopyMapConnectionHeader
.checkEast
    bit 0,b
    jr z,.getObjectDataPointer
    ld de,W_MAPCONN4PTR
    call CopyMapConnectionHeader
.getObjectDataPointer
    ld a,[hli]
    ld [$d3a9],a
    ld a,[hli]
    ld [$d3aa],a
    push hl
    ld a,[$d3a9]
    ld l,a
    ld a,[$d3aa]
    ld h,a ; hl = base of object data
    ld de,$d3ad ; background tile ID
    ld a,[hli]
    ld [de],a ; save background tile ID
.loadWarpData
    ld a,[hli] ; number of warps
    ld [$d3ae],a ; save the number of warps
    and a ; are there any warps?
    jr z,.loadSignData ; if not,skip this
    ld c,a
    ld de,$d3af ; base address of warps
.warpLoop ; one warp per loop iteration
    ld b,$04
.warpInnerLoop
    ld a,[hli]
    ld [de],a
    inc de
    dec b
    jr nz,.warpInnerLoop
    dec c
    jr nz,.warpLoop
.loadSignData
    ld a,[hli] ; number of signs
    ld [$d4b0],a ; save the number of signs
    and a ; are there any signs?
    jr z,.loadSpriteData ; if not,skip this
    ld c,a
    ld de,$d4d1 ; base address of sign text IDs
    ld a,d
    ld [$ff95],a
    ld a,e
    ld [$ff96],a
    ld de,$d4b1 ; base address of sign coordinates
.signLoop
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[hli]
    ld [de],a
    inc de
    push de
    ld a,[$ff95]
    ld d,a
    ld a,[$ff96]
    ld e,a
    ld a,[hli]
    ld [de],a
    inc de
    ld a,d
    ld [$ff95],a
    ld a,e
    ld [$ff96],a
    pop de
    dec c
    jr nz,.signLoop
.loadSpriteData
    ld a,[$d72e]
    bit 5,a ; did a battle happen immediately before this?
    jp nz,.finishUp ; if so,skip this because battles don't destroy this data
    ld a,[hli]
    ld [$d4e1],a ; save the number of sprites
    push hl
; zero C110-C1FF and C210-C2FF
    ld hl,$c110
    ld de,$c210
    xor a
    ld b,$f0
.zeroSpriteDataLoop
    ld [hli],a
    ld [de],a
    inc e
    dec b
    jr nz,.zeroSpriteDataLoop
; initialize all C100-C1FF sprite entries to disabled (other than player's)
    ld hl,$c112
    ld de,$0010
    ld c,$0f
.disableSpriteEntriesLoop
    ld [hl],$ff
    add hl,de
    dec c
    jr nz,.disableSpriteEntriesLoop
    pop hl
    ld de,$c110
    ld a,[$d4e1] ; number of sprites
    and a ; are there any sprites?
    jp z,.finishUp ; if there are no sprites,skip the rest
    ld b,a
    ld c,$00
.loadSpriteLoop
    ld a,[hli]
    ld [de],a ; store picture ID at C1X0
    inc d
    ld a,$04
    add e
    ld e,a
    ld a,[hli]
    ld [de],a ; store Y position at C2X4
    inc e
    ld a,[hli]
    ld [de],a ; store X position at C2X5
    inc e
    ld a,[hli]
    ld [de],a ; store movement byte 1 at C2X6
    ld a,[hli]
    ld [$ff8d],a ; save movement byte 2
    ld a,[hli]
    ld [$ff8e],a ; save text ID and flags byte
    push bc
    push hl
    ld b,$00
    ld hl,W_MAPSPRITEDATA
    add hl,bc
    ld a,[$ff8d]
    ld [hli],a ; store movement byte 2 in byte 0 of sprite entry
    ld a,[$ff8e]
    ld [hl],a ; this appears pointless,since the value is overwritten immediately after
    ld a,[$ff8e]
    ld [$ff8d],a
    and a,$3f
    ld [hl],a ; store text ID in byte 1 of sprite entry
    pop hl
    ld a,[$ff8d]
    bit 6,a
    jr nz,.trainerSprite
    bit 7,a
    jr nz,.itemBallSprite
    jr .regularSprite
.trainerSprite
    ld a,[hli]
    ld [$ff8d],a ; save trainer class
    ld a,[hli]
    ld [$ff8e],a ; save trainer number (within class)
    push hl
    ld hl,W_MAPSPRITEEXTRADATA
    add hl,bc
    ld a,[$ff8d]
    ld [hli],a ; store trainer class in byte 0 of the entry
    ld a,[$ff8e]
    ld [hl],a ; store trainer number in byte 1 of the entry
    pop hl
    jr .nextSprite
.itemBallSprite
    ld a,[hli]
    ld [$ff8d],a ; save item number
    push hl
    ld hl,W_MAPSPRITEEXTRADATA
    add hl,bc
    ld a,[$ff8d]
    ld [hli],a ; store item number in byte 0 of the entry
    xor a
    ld [hl],a ; zero byte 1,since it is not used
    pop hl
    jr .nextSprite
.regularSprite
    push hl
    ld hl,W_MAPSPRITEEXTRADATA
    add hl,bc
; zero both bytes,since regular sprites don't use this extra space
    xor a
    ld [hli],a
    ld [hl],a
    pop hl
.nextSprite
    pop bc
    dec d
    ld a,$0a
    add e
    ld e,a
    inc c
    inc c
    dec b
    jp nz,.loadSpriteLoop
.finishUp
    PREDEF Func_c754 ; load tileset data
    BANKSWITCH LoadWildData ; load wild pokemon data
    pop hl ; restore hl from before going to the warp/sign/sprite data (this value was saved for seemingly no purpose)
    ld a,[W_CURMAPHEIGHT] ; map height in 4x4 tile blocks
    add a ; double it
    ld [$d524],a ; store map height in 2x2 tile blocks
    ld a,[W_CURMAPWIDTH] ; map width in 4x4 tile blocks
    add a ; double it
    ld [$d525],a ; map width in 2x2 tile blocks
    ld a,[W_CURMAP]
    ld c,a
    ld b,$00
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,BANK(MapSongBanks) ; same as MapSongBanksNew
    call RoutineForRealGB
    call GetMapSongBanks ; ld hl,MapSongBanks
    add hl,bc
    add hl,bc
    ld a,[hli]
    ld [$d35b],a ; music 1
    ld a,[hl]
    ld [$d35c],a ; music 2
    pop af
    jp RoutineForRealGB

CheckMoveRelearn:
    push hl
    ld hl,wFlagMoveRelearnEngagedBit7
    bit 7,[hl]
    pop hl
    ret

SECTION "CopyMapConnectionHeader",ROM0[$1238]

; function to copy map connection data from ROM to WRAM
; Input: hl = source,de = destination
CopyMapConnectionHeader: ; 1238 (0:1238)
    ld c,$0b
.loop
    ld a,[hli]
    ld [de],a
    inc de
    dec c
    jr nz,.loop
    ret

; function to load map data
LoadMapData:
    ld a,[H_LOADEDROMBANK]
    push af
    call DisableLCD
    ld a,$98
    ld [$d527],a
    xor a
    ld [$d526],a
    ld [$ffaf],a
    ld [$ffae],a
    ld [wWalkCounter],a
    ld [$d119],a
    ld [$d11a],a
    ld [$d3a8],a
    call LoadTextBoxTilePatterns
    call LoadMapHeader
    BANKSWITCH InitMapSprites ; load tile pattern data for sprites
    BANKSWITCH RunMapGraphicalScript
    call LoadTileBlockMap
    call LoadTilesetTilePatternData
    call LoadCurrentMapView
; copy current map view to VRAM
    ld hl,wTileMap
    ld de,$9800
    ld b,$12
.vramCopyLoop
    ld c,$14
.vramCopyInnerLoop
    ld a,[hli]
    ld [de],a
    inc e
    dec c
    jr nz,.vramCopyInnerLoop
    ld a,$0c
    add e
    ld e,a
    jr nc,.noCarry
    inc d
.noCarry
    dec b
    jr nz,.vramCopyLoop
    ld a,$01
    ld [$cfcb],a
    call EnableLCD
    ld b,$09
    call GoPAL_SET
    call LoadPlayerSpriteGraphics
    ld a,[$d732]
    and a,$18 ; did the player fly or teleport in?
    jr nz,.restoreRomBank
    ld a,[W_FLAGS_D733]
    bit 1,a
    jr nz,.restoreRomBank
    call Func_235f ; music related
    call PlayDefaultMusicFadeOutCurrent ; music related
.restoreRomBank
    pop af
    jp RoutineForRealGB

; function to switch to the ROM bank that a map is stored in
; Input: a = map number
SwitchToMapRomBank:
    push hl
    push bc
    ld c,a
    ld b,$00
    ld a,$03
    call BankswitchHome ; switch to ROM bank 3
    call GetMapHeaderBanks ; ld hl,MapHeaderBanks
    add hl,bc
    ld a,[hl]
    ld [$ffe8],a ; save map ROM bank
    call BankswitchBack
    ld a,[$ffe8]
    call RoutineForRealGB ; switch to map ROM bank
    pop bc
    pop hl
    ret

Func_12da:
