    ld [$d11e],a
    call IndexToPokedexAndRestoreD11E
    ld c,a
    ld b,0
    ld hl,CryData
    add hl,bc
    add hl,bc
    add hl,bc
    ld a,Bank(CryData)
    call BankswitchHome
    ld a,[hli]
    ld b,a
    ld a,[hli]
    ld [$c0f1],a
    ld a,[hl]
    ld [$c0f2],a
    call BankswitchBack
    ld a,b ; a = cryID
