SECTION "DisplayPartyMenu",ROM0[$13fc]

DisplayPartyMenu: ; 13fc (0:13fc)
    ld a,[$ffd7]
    push af
    xor a
    ld [$ffd7],a
    call GBPalWhiteOutWithDelay3
    call CleanLCD_OAM
    call PartyMenuInit
    call DrawPartyMenu
    jp HandlePartyMenuInput

GoBackToPartyMenu:
    ld a,[$ffd7]
    push af
    xor a
    ld [$ffd7],a
    call PartyMenuInit
    call RedrawPartyMenu
    jp HandlePartyMenuInput

PartyMenuInit:
    ld a,$01
    call BankswitchHome
    call LoadHpBarAndStatusTilePatterns
    ld hl,$d730
    set 6,[hl] ; turn off letter printing delay
    xor a
    ld [$cc49],a
    ld [$cc37],a
    ld hl,wTopMenuItemY
    inc a
    ld [hli],a ; top menu item Y
    xor a
    ld [hli],a ; top menu item X
    ld a,[wPartyAndBillsPCSavedMenuItem]
    push af
    ld [hli],a ; current menu item ID
    inc hl
    ld a,[W_NUMINPARTY]
    and a ; are there more than 0 pokemon in the party?
    jr z,.storeMaxMenuItemID
    dec a
; if party is not empty,the max menu item ID is ([W_NUMINPARTY] - 1)
; otherwise,it is 0
.storeMaxMenuItemID
    ld [hli],a ; max menu item ID
    ld a,[$d11f]
    and a
    ld a,%00000111 ; ▼▲◄►StSeBA
    jr z,.next
    xor a
    ld [$d11f],a
    inc a
.next
    ld [hli],a ; menu watched keys
    pop af
    ld [hl],a ; old menu item ID
    ret

HandlePartyMenuInput:
    ld hl,wForceSortPartyWSelectBit4
    bit 4,[hl]
    jr nz,.continue
    ld hl,wMenuWatchedKeys
    res 2,[hl]
.continue
    ld a,1
    ld [wMenuWrappingEnabled],a ; $cc4a
    ld a,$40
    ld [$d09b],a
    call HandleMenuInputPokemonSelection
    call PlaceUnfilledArrowMenuCursor
    ld b,a
    xor a
    ld [$d09b],a
    ld a,[wCurrentMenuItem]
    ld [wPartyAndBillsPCSavedMenuItem],a
    ld hl,$d730
    res 6,[hl] ; turn on letter printing delay
    ld a,[$cc35]
    and a
    jp nz,.swappingPokemon
    pop af
    ld [$ffd7],a
    bit 1,b
    jr nz,.noPokemonChosen
    ld a,[W_NUMINPARTY]
    and a
    jr z,.noPokemonChosen
    bit 2,b
    jr z,.NoSelect
    ld a,[W_NUMINPARTY]
    cp 2 ; is there more than one pokemon in the party?
    jr c,.NoSelect
    ld hl,wForceSortPartyWSelectBit4
    res 4,[hl]
.NoSelect
    ld a,[wCurrentMenuItem]
    ld [$cf92],a
    ld hl,W_PARTYMON1
    ld b,0
    ld c,a
    add hl,bc
    ld a,[hl]
    ld [$cf91],a
    ld [$cfd9],a
    call BankswitchBack
    and a
    ret
.noPokemonChosen
    call BankswitchBack
    scf
    ret
.swappingPokemon
    bit 1,b ; was the B button pressed?
    jr z,.handleSwap ; if not,handle swapping the pokemon
.cancelSwap ; if the B button was pressed
    BANKSWITCH ErasePartyMenuCursors
    xor a
    ld [$cc35],a
    ld [$d07d],a
    call RedrawPartyMenu
.hpmi_midjump
    jp HandlePartyMenuInput
.handleSwap
    ld a,[wCurrentMenuItem]
    ld [$cf92],a
    BANKSWITCH Func_13613
    jr .hpmi_midjump

DrawPartyMenu:
    ld hl,DrawPartyMenu_
    jr DrawPartyMenuCommon

RedrawPartyMenu:
    ld hl,RedrawPartyMenu_
    ; ft

DrawPartyMenuCommon:
    ld b,BANK(RedrawPartyMenu_)
    jp Bankswitch

; prints a pokemon's status condition
; INPUT:
; de = address of status condition
; hl = destination address
; bc = battle status 1 address (if 0 Not Battle HUD)
PrintStatusCondition: ; Don't Print "FNT"
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,BANK(PrintStatusAilment)
    call RoutineForRealGB
    call PrintStatusAilment ; print status condition
    pop bc
    ld a,b
    jp RoutineForRealGB

CheckSurfing:
    ld b,a
    jr nz,.notsurf
    call GetCurrentOldAdventureMap
    cp ROUTE_19
    jr c,.notsurf
    cp ROUTE_21+1
    jr nc,.notsurf
.surf
    ld a,(Music_Surfing - $4000) / 3
    scf
    jr .end
.notsurf
    xor a ; rcf
.end
    ret

; function to print pokemon level,leaving off the ":L" if the level is at least 100
; INPUT:
; hl = destination address
; [$cfb9] = level
PrintLevel:
    ld a,$6e ; ":L" tile ID
    ld [hli],a
    ld c,2 ; number of digits
    ld a,[$cfb9] ; level
    cp 100
    jr c,PrintLevelCommon
; if level at least 100,write over the ":L" tile
    dec hl
    inc c ; increment number of digits to 3
    jr PrintLevelCommon

; prints the level without leaving off ":L" regardless of level
; INPUT:
; hl = destination address
; [$cfb9] = level
PrintLevelFull:
    ld a,$6e ; ":L" tile ID
    ld [hli],a
    ld c,3 ; number of digits
    ld a,[$cfb9] ; level
    ; ft

PrintLevelCommon:
    ld [$d11e],a
    ld de,$d11e
    ld b,$41 ; no leading zeroes,left-aligned,one byte
    jp PrintNumber

; copies the base stat data of a pokemon to $D0B8 (W_MONHEADER)
; INPUT:
; [$D0B5] = pokemon ID
; [wAlternateFormIndex] = Alternate Form Index
GetMonHeader:
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,BANK(PokemonBaseStats)
    call RoutineForRealGB
    push bc
    push de
    push hl
    ld hl,wAlternateFormIndex
    ld a,[hl]
    push af
    push hl
    ld a,[$d11e]
    push af
    ld a,[$d0b5]
    ld [$d11e],a
    call IndexToPokedexAndRestoreD11E
    ld hl,PokemonBaseStats
    ld bc,28
    call AddNTimes
.retry
    ld bc,28
    ld de,W_MONHEADER
    call CopyData
    ld hl,wAlternateFormIndex
    ld a,[hl]
    and a
    jr z,.done
    dec a
    ld [hl],a
    ld hl,W_MONHNEXTALTFORM ; Actual Pointer to Alternate Forms
    ld a,[hli]
    ld h,[hl]
    ld l,a
    or h
    jr nz,.retry
    ; ft
.done
    pop af
    ld [$d11e],a
    pop hl
    pop af
    ld de,W_MONHALTFORM
    ld [de],a
    dec de
    xor a
    ld [hl],a
    ld [de],a ; W_MONH_UNUSED
    pop hl
    pop de
    pop bc
    pop af
    jp RoutineForRealGB

Tset11_Coll:
    INCBIN "gfx/tilesets/11.tilecoll"

SECTION "GetPartyMonName2",ROM0[$15b4]

; copy party pokemon's name to $CD6D
GetPartyMonName2: ; 15b4 (0:15b4)
    ld a,[$cf92] ; index within party
    ld hl,W_PARTYMON1NAME

; this is called more often
GetPartyMonName: ; 15ba (0:15ba)
    push hl
    push bc
    call SkipFixedLengthTextEntries ; add 11 to hl,a times
    ld de,$cd6d
    push de
    ld bc,11
    call CopyData
    pop de
    pop bc
    pop hl
    ret

; function to print a BCD (Binary-coded decimal) number
; de = address of BCD number
; hl = destination address
; c = flags and length
; bit 7: if set,do not print leading zeroes
;        if unset,print leading zeroes
; bit 6: if set,left-align the string (do not pad empty digits with spaces)
;        if unset,right-align the string
; bit 5: if set,print currency symbol at the beginning of the string
;        if unset,do not print the currency symbol
; bits 0-4: length of BCD number in bytes
; Note that bits 5 and 7 are modified during execution. The above reflects
; their meaning at the beginning of the functions's execution.
PrintBCDNumber: ; 15cd (0:15cd)
    ld b,c ; save flags in b
    res 7,c
    res 6,c
    res 5,c ; c now holds the length
    bit 5,b
    jr z,.loop
    bit 7,b
    jr nz,.loop
    ld [hl],"¥"
    inc hl
.loop
    ld a,[de]
    swap a
    call PrintBCDDigit ; print upper digit
    ld a,[de]
    call PrintBCDDigit ; print lower digit
    inc de
    dec c
    jr nz,.loop
    bit 7,b ; were any non-zero digits printed?
    jr z,.done ; if so,we are done
.numberEqualsZero ; if every digit of the BCD number is zero
    bit 6,b ; left or right alignment?
    jr nz,.skipRightAlignmentAdjustment
    dec hl ; if the string is right-aligned,it needs to be moved back one space
.skipRightAlignmentAdjustment
    bit 5,b
    jr z,.skipCurrencySymbol
    ld [hl],"¥"
    inc hl
.skipCurrencySymbol
    ld [hl],"0"
    call PrintLetterDelay
    inc hl
.done
    ret

PrintBCDDigit: ; 1604 (0:1604)
    and a,%00001111
    and a
    jr z,.zeroDigit
.nonzeroDigit
    bit 7,b ; have any non-space characters been printed?
    jr z,.outputDigit
; if bit 7 is set,then no numbers have been printed yet
    bit 5,b ; print the currency symbol?
    jr z,.skipCurrencySymbol
    ld [hl],"¥"
    inc hl
    res 5,b
.skipCurrencySymbol
    res 7,b ; unset 7 to indicate that a nonzero digit has been reached
.outputDigit
    add a,"0"
    ld [hli],a
    jp PrintLetterDelay
.zeroDigit
    bit 7,b ; either printing leading zeroes or already reached a nonzero digit?
    jr z,.outputDigit ; if so,print a zero digit
    bit 6,b ; left or right alignment?
    ret nz
    inc hl ; if right-aligned,"print" a space by advancing the pointer
    ret

; uncompresses the front or back sprite of the specified mon
; assumes the corresponding mon header is already loaded
; hl contains offset to sprite pointer ($b for front or $d for back)
UncompressMonSprite: ; 1627 (0:1627) ; Denim,completamente ristrutturato
    push hl
    ld e,l
    BANKSWITCH CheckSpecialHybridSprite
    pop hl
    jr c,.NormalId
    ld hl,W_SPRITEINPUTPTR
    ld [hl],d
    inc hl
    ld [hl],e
    jr .Done
.NormalId
    ld de,W_MONHEADER
    add hl,de
    ld a,[hli]
    ld [W_SPRITEINPUTPTR],a
    ld a,[hl]
    ld [W_SPRITEINPUTPTR+1],a
.Done
    ld a,[$d0d3] ; Ultimo Byte Base Stat = BANK immagine
.End
    jp UncompressSpriteData

CheckCyclingRoad:
    and a
    ret z
    ld a,[$d732]
    bit 5,a
    ld a,(Music_BikeRiding - $4000) / 3
    ret

BackupHlAndGetSpecialListNameOrGetItemName:  ; xxxx (0:xxxx) ; Denim ; spazio ricavato dalla routine precedente
    push hl
    call GetSpecialListNameOrGetItemName
    pop hl
    ld de,$CD6D
    ret

SECTION "LoadMonFrontSprite",ROM0[$1665] ; Denim

; de: destination location
LoadMonFrontSprite: ; 1665 (0:1665)
    push de
    ld hl,W_MONHFRONTSPRITE - W_MONHEADER
    call UncompressMonSprite
    ld hl,W_MONHSPRITEDIM
    ld a,[hli]
HackBackSprite: ; Denim,Pointer utilizzato per caricare i backsprite come i frontsprite
    ld c,a
    pop de
    ; ft

; postprocesses uncompressed sprite chunks to a 2bpp sprite and loads it into video ram
; calculates alignment parameters to place both sprite chunks in the center of the 7*7 tile sprite buffers
; de: destination location
; a,c:  sprite dimensions (in tiles of 8x8 each)
LoadUncompressedSpriteData: ; 1672 (0:1672)
    push de
    and $f
    ld [H_SPRITEWIDTH],a ; each byte contains 8 pixels (in 1bpp),so tiles=bytes for width
    ld b,a
    ld a,$7
    sub b      ; 7-w
    inc a      ; 8-w
    srl a      ; (8-w)/2     ; horizontal center (in tiles,rounded up)
    ld b,a
    add a
    add a
    add a
    sub b      ; 7*((8-w)/2) ; skip for horizontal center (in tiles)
    ld [H_SPRITEOFFSET],a
    ld a,c
    swap a
    and $f
    ld b,a
    add a
    add a
    add a     ; 8*tiles is height in bytes
    ld [H_SPRITEHEIGHT],a ; $FF00+$8c
    ld a,$7
    sub b      ; 7-h         ; skip for vertical center (in tiles,relative to current column)
    ld b,a
    ld a,[H_SPRITEOFFSET]
    add b     ; 7*((8-w)/2) + 7-h ; combined overall offset (in tiles)
    add a
    add a
    add a     ; 8*(7*((8-w)/2) + 7-h) ; combined overall offset (in bytes)
    ld [H_SPRITEOFFSET],a
    xor a
    ld [$4000],a
    ld hl,S_SPRITEBUFFER0
    call ZeroSpriteBuffer   ; zero buffer 0
    ld de,S_SPRITEBUFFER1
    ld hl,S_SPRITEBUFFER0
    call AlignSpriteDataCentered    ; copy and align buffer 1 to 0 (containing the MSB of the 2bpp sprite)
    ld hl,S_SPRITEBUFFER1
    call ZeroSpriteBuffer   ; zero buffer 1
    ld de,S_SPRITEBUFFER2
    ld hl,S_SPRITEBUFFER1
    call AlignSpriteDataCentered    ; copy and align buffer 2 to 1 (containing the LSB of the 2bpp sprite)
    pop de
    jp InterlaceMergeSpriteBuffers

; copies and aligns the sprite data properly inside the sprite buffer
; sprite buffers are 7*7 tiles in size,the loaded sprite is centered within this area
AlignSpriteDataCentered: ; 16c2 (0:16c2)
    ld a,[H_SPRITEOFFSET]
    ld b,$0
    ld c,a
    add hl,bc
    ld a,[H_SPRITEWIDTH] ; $FF00+$8b
.columnLoop
    push af
    push hl
    ld a,[H_SPRITEHEIGHT] ; $FF00+$8c
    ld c,a
.columnInnerLoop
    ld a,[de]
    inc de
    ld [hli],a
    dec c
    jr nz,.columnInnerLoop
    pop hl
    ld bc,7*8    ; 7 tiles
    add hl,bc    ; advance one full column
    pop af
    dec a
    jr nz,.columnLoop
    ret

; fills the sprite buffer (pointed to in hl) with zeros
ZeroSpriteBuffer: ; 16df (0:16df)
    ld bc,SPRITEBUFFERSIZE
.nextByteLoop
    xor a
    ld [hli],a
    dec bc
    ld a,b
    or c
    jr nz,.nextByteLoop
    ret

; combines the (7*7 tiles,1bpp) sprite chunks in buffer 0 and 1 into a 2bpp sprite located in buffer 1 through 2
; in the resulting sprite,the rows of the two source sprites are interlaced
; de: output address
InterlaceMergeSpriteBuffers: ; 16ea (0:16ea)
    xor a
    ld [$4000],a
    push de
    ld hl,S_SPRITEBUFFER2 + (SPRITEBUFFERSIZE - 1) ; destination: end of buffer 2
    ld de,S_SPRITEBUFFER1 + (SPRITEBUFFERSIZE - 1) ; source 2: end of buffer 1
    ld bc,S_SPRITEBUFFER0 + (SPRITEBUFFERSIZE - 1) ; source 1: end of buffer 0
    ld a,SPRITEBUFFERSIZE/2 ; $c4
    ld [H_SPRITEINTERLACECOUNTER],a ; $FF00+$8b
.interlaceLoop
    ld a,[de]
    dec de
    ld [hld],a   ; write byte of source 2
    ld a,[bc]
    dec bc
    ld [hld],a   ; write byte of source 1
    ld a,[de]
    dec de
    ld [hld],a   ; write byte of source 2
    ld a,[bc]
    dec bc
    ld [hld],a   ; write byte of source 1
    ld a,[H_SPRITEINTERLACECOUNTER] ; $FF00+$8b
    dec a
    ld [H_SPRITEINTERLACECOUNTER],a ; $FF00+$8b
    jr nz,.interlaceLoop
    ld a,[W_SPRITEFLIPPED]
    and a
    jr z,.notFlipped
    ld bc,2*SPRITEBUFFERSIZE
    ld hl,S_SPRITEBUFFER1
.swapLoop
    swap [hl]    ; if flipped swap nybbles in all bytes
    inc hl
    dec bc
    ld a,b
    or c
    jr nz,.swapLoop
.notFlipped
    pop hl
    ld de,S_SPRITEBUFFER1
    ld c,(2*SPRITEBUFFERSIZE)/16 ; $31,number of 16 byte chunks to be copied
    ld a,[H_LOADEDROMBANK]
    ld b,a
    jp CopyVideoData

Tset0B_Coll: ; 172f (0:172f)
    INCBIN "gfx/tilesets/0b.tilecoll"
