SECTION "FarCopyData2",ROM0[$17f7] ; Denim

; does the same thing as FarCopyData at 009D
; only difference is that it uses [$ff8b] instead of [$cee9] for a temp value
; copy bc bytes of data from a:hl to de
FarCopyData2: ; 17f7 (0:17f7)
    ld [$ff8b],a
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,[$ff8b]
    call RoutineForRealGB
    call CopyData
    pop af
    jp RoutineForRealGB

; does a far copy but the source is de and the destination is hl
; copy bc bytes of data from a:de to hl
FarCopyData3: ; 180d (0:180d)
    ld [$ff8b],a
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,[$ff8b]
    call RoutineForRealGB
    push hl
    push de
    push de
    ld d,h
    ld e,l
    pop hl
    call CopyData
    pop de
    pop hl
    pop af
    jp RoutineForRealGB

; copies each source byte to the destination twice (next to each other)
; copy bc source bytes from a:hl to de
FarCopyDataDouble: ; 182b (0:182b)
    ld [$ff8b],a
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,[$ff8b]
    call RoutineForRealGB
.loop
    ld a,[hli]
    ld [de],a
    inc de
    ld [de],a
    inc de
    dec bc
    ld a,c
    or b
    jr nz,.loop
    pop af
    jp RoutineForRealGB

; copy (c * 16) bytes from b:de to hl during V-blank
; transfers up to 128 bytes per V-blank
CopyVideoData: ; 1848 (0:1848)
    ld a,[H_AUTOBGTRANSFERENABLED] ; save auto-transfer enabled flag
    push af
    xor a
    ld [H_AUTOBGTRANSFERENABLED],a ; disable auto-transfer while copying
    ld a,[H_LOADEDROMBANK]
    ld [$ff8b],a
    ld a,b
    call RoutineForRealGB
    ld a,e
    ld [H_VBCOPYSRC],a
    ld a,d
    ld [H_VBCOPYSRC + 1],a
    ld a,l
    ld [H_VBCOPYDEST],a
    ld a,h
    ld [H_VBCOPYDEST + 1],a
.loop
    ld a,c
    cp 8 ; are there more than 128 bytes left to copy?
    jr nc,.copyMaxSize ; only copy up to 128 bytes at a time
.copyRemainder
    ld [H_VBCOPYSIZE],a
    call DelayFrame ; wait for V-blank handler to perform the copy
    ld a,[$ff8b]
    call RoutineForRealGB
    pop af
    ld [H_AUTOBGTRANSFERENABLED],a ; restore original auto-transfer enabled flag
    ret
.copyMaxSize
    ld a,8 ; 128 bytes
    ld [H_VBCOPYSIZE],a
    call DelayFrame ; wait for V-blank handler to perform the copy
    ld a,c
    sub a,8
    ld c,a
    jr .loop

; copy (c * 8) source bytes from b:de to hl during V-blank
; copies each source byte to the destination twice (next to each other)
; transfers up to 64 source bytes per V-blank
CopyVideoDataDouble: ; 1886 (0:1886)
    ld a,[H_AUTOBGTRANSFERENABLED] ; save auto-transfer enabled flag
    push af
    xor a
    ld [H_AUTOBGTRANSFERENABLED],a ; disable auto-transfer while copying
    ld a,[H_LOADEDROMBANK]
    ld [$ff8b],a
    ld a,b
    call RoutineForRealGB
    ld a,e
    ld [H_VBCOPYDOUBLESRC],a
    ld a,d
    ld [H_VBCOPYDOUBLESRC + 1],a
    ld a,l
    ld [H_VBCOPYDOUBLEDEST],a
    ld a,h
    ld [H_VBCOPYDOUBLEDEST + 1],a
.loop
    ld a,c
    cp 8 ; are there more than 64 source bytes left to copy?
    jr nc,.copyMaxSize ; only copy up to 64 source bytes at a time
.copyRemainder
    ld [H_VBCOPYDOUBLESIZE],a
    call DelayFrame ; wait for V-blank handler to perform the copy
    ld a,[$ff8b]
    call RoutineForRealGB
    pop af
    ld [H_AUTOBGTRANSFERENABLED],a ; restore original auto-transfer enabled flag
    ret
.copyMaxSize
    ld a,8 ; 64 source bytes
    ld [H_VBCOPYDOUBLESIZE],a
    call DelayFrame ; wait for V-blank handler to perform the copy
    ld a,c
    sub a,8
    ld c,a
    jr .loop

SECTION "ClearScreenArea",ROM0[$18c4]

; clears an area of the screen
; INPUT:
; hl = address of upper left corner of the area
; b = height
; c = width
ClearScreenArea: ; 18c4 (0:18c4)
    ld   a,$7F ; blank tile
    ld   de,20 ; screen width
.loop
    push hl
    push bc
.innerLoop
    ld [hli],a
    dec c
    jr nz,.innerLoop
    pop bc
    pop hl
    add hl,de
    dec b
    jr nz,.loop
    ret

; copies the screen tile buffer from WRAM to VRAM
; copying is done in 3 chunks of 6 rows each
; b: high byte of VRAM destination address ($98 or $9c for window tile map 0 or 1 resp.)
CopyScreenTileBufferToVRAM: ; 18d6 (0:18d6)
    ld c,$6
    ld hl,$0000
    ld de,wTileMap
    call InitScreenTileBufferTransferParameters
    call DelayFrame
    ld hl,$600
    ld de,wTileMap + 20 * 6 ; $c418
    call InitScreenTileBufferTransferParameters
    call DelayFrame
    ld hl,$c00
    ld de,wTileMap + 20 * 12 ; $c490
    call InitScreenTileBufferTransferParameters
    jp DelayFrame

InitScreenTileBufferTransferParameters: ; 18fc (0:18fc)
    ld a,d
    ld [H_VBCOPYBGSRC+1],a
    call GetRowColAddressBgMap
    ld a,l
    ld [H_VBCOPYBGDEST],a ; $FF00+$c3
    ld a,h
    ld [H_VBCOPYBGDEST+1],a
    ld a,c
    ld [H_VBCOPYBGNUMROWS],a ; $FF00+$c5
    ld a,e
    ld [H_VBCOPYBGSRC],a ; $FF00+$c1
    ret

ClearScreen: ; 190f (0:190f)
; clears all tiles in the tilemap,
; then wait three frames
    ld bc,$0168 ; tilemap size
    inc b
    ld hl,wTileMap ; TILEMAP_START
    ld a,$7F    ; $7F is blank tile
.loop
    ld [hli],a
    dec c
    jr nz,.loop
    dec b
    jr nz,.loop
    jp Delay3

TextBoxBorder: ; 1922 (0:1922)
; draw a text box
; upper-left corner at coordinates hl
; height b
; width c

    ; first row
    push hl
    ld a,"┌"
    ld [hli],a
    inc a    ; horizontal border ─
    call NPlaceChar
    inc a    ; upper-right border ┐
    ld [hl],a

    ; middle rows
    pop hl
    ld de,20
    add hl,de ; skip the top row

.PlaceRow
    push hl
    ld a,"│"
    ld [hli],a
    ld a," "
    call NPlaceChar
    ld [hl],"│"

    pop hl
    ld de,20
    add hl,de ; move to next row
    dec b
    jr nz,.PlaceRow

    ; bottom row
    ld a,"└"
    ld [hli],a
    ld a,"─"
    call NPlaceChar
    ld [hl],"┘"
    ret
;
NPlaceChar: ; 194f (0:194f)
; place a row of width c of identical characters
    ld d,c
.loop
    ld [hli],a
    dec d
    jr nz,.loop
    ret

SECTION "PlaceString",ROM0[$1955]

PlaceString: ; 1955 (0:1955)
    push hl
PlaceNextChar:
    ld a,[de]

    cp "@"
    jr nz,.PlaceText
    ld b,h
    ld c,l
    pop hl
    ret

.PlaceText
    cp $4E
    jr nz,.next
    ld bc,$0028
    ld a,[$FFF6]
    bit 2,a
    jr z,.next2
    ld bc,$14
.next2
    pop hl
    add hl,bc
    push hl
    jp Next19E8

.next
    cp $4F
    jr nz,.next3
    pop hl
    FuncCoord 1,16 ; $c4e1
    ld hl,Coord
    push hl
    jp Next19E8

.next3 ; Check against a dictionary
    and a
    jp z,Char00
    cp $4C
    jp z,Char4C
    cp $4B
    jp z,Char4B
    cp $51
    jp z,Char51
    cp $49
    jp z,Char49
    cp $52
    jp z,Char52
    cp $53
    jp z,Char53
    cp $54
    jp z,Char54
    cp $5B
    jp z,Char5B
    cp $5E
    jp z,Char5E
    cp $5C
    jp z,Char5C
    cp $5D
    jp z,Char5D
    cp $55
    jp z,Char55
    cp $56
    jp z,Char56
    cp $57
    jp z,Char57
    cp $58
    jp z,Char58
    cp $4A
    jp z,Char4A
    cp $5F
    jp z,Char5F
    cp $59
    jp z,Char59
    cp $5A
    jp z,Char5A
    ld [hli],a
    call PrintLetterDelay
Next19E8:
    inc de
    jp PlaceNextChar

Char00:
    ld b,h
    ld c,l
    pop hl
    ld de,Char00Text
    dec de
    ret

Char00Text: ; “%d ERROR.”
    TX_FAR _Char00Text
    db "@"

Char52: ; player’s name
    push de
    ld de,W_PLAYERNAME
    jr FinishDTE

Char53: ; rival’s name
    push de
    ld de,W_RIVALNAME
    jr FinishDTE

Char5D: ; TRAINER
    push de
    ld de,Char5DText
    jr FinishDTE

Char5C: ; TM
    push de
    ld de,Char5CText
    jr FinishDTE

Char5B: ; PC
    push de
    ld de,Char5BText
    jr FinishDTE

Char5E: ; ROCKET
    push de
    ld de,Char5EText
    jr FinishDTE

Char54: ; POKé
    push de
    ld de,Char54Text
    jr FinishDTE

Char56: ; ……
    push de
    ld de,Char56Text
    jr FinishDTE

Char4A: ; PKMN
    push de
    ld de,Char4AText
    jr FinishDTE

Char59:
; depending on whose turn it is,print
; enemy active monster’s name,prefixed with “Enemy ”
; or
; player active monster’s name
; (like Char5A but flipped)
    ld a,[H_WHOSETURN]
    xor 1
    jr MonsterNameCharsCommon

Char5A:
; depending on whose turn it is,print
; player active monster’s name
; or
; enemy active monster’s name,prefixed with “Enemy ”
    ld a,[H_WHOSETURN]
MonsterNameCharsCommon:
    push de
    and a
    jr nz,.Enemy
    ld de,W_PLAYERMONNAME ; player active monster name
    jr FinishDTE

.Enemy
    ; print “Enemy ”
    ld de,Char5AText
    call PlaceString

    ld h,b
    ld l,c
    ld de,W_ENEMYMONNAME ; enemy active monster name

FinishDTE:
    call PlaceString
    ld h,b
    ld l,c
    pop de
    inc de
    jp PlaceNextChar

Char5CText:
    db "TM@"
Char5DText:
    db "TRAINER@"
Char5BText:
    db "PC@"
Char5EText:
    db "ROCKET@"
Char54Text:
    db "POKé@"
Char56Text:
    db "……@"
Char5AText:
    db "Enemy @"
Char4AText:
    db $E1,$E2,"@" ; PKMN

Char55:
    push de
    ld b,h
    ld c,l
    ld hl,Char55Text
    call TextCommandProcessor
    ld h,b
    ld l,c
    pop de
    inc de
    jp PlaceNextChar

Char55Text:
; equivalent to Char4B
    TX_FAR _Char55Text
    db "@"

Char5F:
; ends a Pokédex entry
    ld [hl],"."
    pop hl
    ret

Char58:
    ld a,[$D12B]
    cp 4
    jp z,Next1AA2
    ld a,$EE
    FuncCoord 18,16 ; $c4f2
    ld [Coord],a
Next1AA2: ; 1aa2 (0:1aa2)
    call ProtectedDelay3
    call ManualTextScroll
    ld a,$7F
    FuncCoord 18,16 ; $c4f2
    ld [Coord],a
Char57: ; 1aad (0:1aad)
    pop hl
    ld de,Char58Text
    dec de
    ret

Char58Text:
    db "@"

Char51:
    push de
    ld a,$EE
    FuncCoord 18,16 ; $c4f2
    ld [Coord],a
    call ProtectedDelay3
    call ManualTextScroll
    FuncCoord 1,13 ; $c4a5
    ld hl,Coord
    ld bc,$0412
    call ClearScreenArea
    ld c,$14
    call DelayFrames
    pop de
    FuncCoord 1,14 ; $c4b9
    ld hl,Coord
    jp Next19E8

Char49:
    push de
    ld a,$EE
    FuncCoord 18,16 ; $c4f2
    ld [Coord],a
    call ProtectedDelay3
    call ManualTextScroll
    FuncCoord 1,10 ; $c469
    ld hl,Coord
    ld bc,$0712
    call ClearScreenArea
    ld c,$14
    call DelayFrames
    pop de
    pop hl
    FuncCoord 1,11 ; $c47d
    ld hl,Coord
    push hl
    jp Next19E8

Char4B:
    ld a,$EE
    FuncCoord 18,16 ; $c4f2
    ld [Coord],a
    call ProtectedDelay3
    push de
    call ManualTextScroll
    pop de
    ld a,$7F
    FuncCoord 18,16 ; $c4f2
    ld [Coord],a
    ;fall through

Char4C:
    push de
    call Next1B18
    call Next1B18
    FuncCoord 1,16 ; $c4e1
    ld hl,Coord
    pop de
    jp Next19E8

Next1B18:
    FuncCoord 0,14 ; $c4b8
    ld hl,Coord
    FuncCoord 0,13 ; $c4a4
    ld de,Coord
    ld b,$3C
.next
    ld a,[hli]
    ld [de],a
    inc de
    dec b
    jr nz,.next
    FuncCoord 1,16 ; $c4e1
    ld hl,Coord
    ld a,$7F
    ld b,$12
.next2
    ld [hli],a
    dec b
    jr nz,.next2

    ; wait five frames
    ld b,5
.WaitFrame
    call DelayFrame
    dec b
    jr nz,.WaitFrame

    ret

ProtectedDelay3:
    push bc
    call Delay3
    pop bc
    ret

TextCommandProcessor:
    ld a,[$d358]
    push af
    set 1,a
    ld e,a
    ld a,[$fff4]
    xor e
    ld [$d358],a
    ld a,c
    ld [$cc3a],a
    ld a,b
    ld [$cc3b],a

NextTextCommand:
    ld a,[hli]
    cp "@" ; terminator
    jr nz,.doTextCommand
    pop af
    ld [$d358],a
    ret
.doTextCommand
    push hl
    cp $17
    jp z,TextCommand17
    cp $0e
    jp nc,TextCommand0B ; if a != 0x17 and a >= 0xE,go to command 0xB
; if a < 0xE,use a jump table
    ld hl,TextCommandJumpTable
    push bc
    add a
    ld b,$00
    ld c,a
    add hl,bc
    pop bc
    ld a,[hli]
    ld h,[hl]
    ld l,a
    jp hl

; draw box
; 04AAAABBCC
; AAAA = address of upper left corner
; BB = height
; CC = width
TextCommand04:
    pop hl
    ld a,[hli]
    ld e,a
    ld a,[hli]
    ld d,a
    ld a,[hli]
    ld b,a
    ld a,[hli]
    ld c,a
    push hl
    ld h,d
    ld l,e
    call TextBoxBorder
    pop hl
    jr NextTextCommand

; place string inline
; 00{string}
TextCommand00:
    pop hl
    ld d,h
    ld e,l
    ld h,b
    ld l,c
    call PlaceString
    ld h,d
    ld l,e
    inc hl
    jr NextTextCommand

; place string from RAM
; 01AAAA
; AAAA = address of string
TextCommand01:
    pop hl
    ld a,[hli]
    ld e,a
    ld a,[hli]
    ld d,a
    push hl
    ld h,b
    ld l,c
    call PlaceString
    pop hl
    jr NextTextCommand

; print BCD number
; 02AAAABB
; AAAA = address of BCD number
; BB
; bits 0-4 = length in bytes
; bits 5-7 = unknown flags
TextCommand02:
    pop hl
    ld a,[hli]
    ld e,a
    ld a,[hli]
    ld d,a
    ld a,[hli]
    push hl
    ld h,b
    ld l,c
    ld c,a
    call PrintBCDNumber
    ld b,h
    ld c,l
    pop hl
    jr NextTextCommand

; repoint destination address
; 03AAAA
; AAAA = new destination address
TextCommand03:
    pop hl
    ld a,[hli]
    ld [$cc3a],a
    ld c,a
    ld a,[hli]
    ld [$cc3b],a
    ld b,a
    jp NextTextCommand

; repoint destination to second line of dialogue text box
; 05
; (no arguments)
TextCommand05:
    pop hl
    FuncCoord 1,16 ; $c4e1
    ld bc,Coord ; address of second line of dialogue text box
    jp NextTextCommand

; blink arrow and wait for A or B to be pressed
; 06
; (no arguments)
TextCommand06:
    ld a,[W_ISLINKBATTLE]
    cp $04
    jp z,TextCommand0D
    ld a,$ee ; down arrow
    FuncCoord 18,16 ; $c4f2
    ld [Coord],a ; place down arrow in lower right corner of dialogue text box
    push bc
    call ManualTextScroll ; blink arrow and wait for A or B to be pressed
    pop bc
    ld a," "
    FuncCoord 18,16 ; $c4f2
    ld [Coord],a ; overwrite down arrow with blank space
    pop hl
    jp NextTextCommand

; scroll text up one line
; 07
; (no arguments)
TextCommand07:
    ld a," "
    FuncCoord 18,16 ; $c4f2
    ld [Coord],a ; place blank space in lower right corner of dialogue text box
    call Next1B18 ; scroll up text
    call Next1B18
    pop hl
    FuncCoord 1,16 ; $c4e1
    ld bc,Coord ; address of second line of dialogue text box
    jp NextTextCommand

; execute asm inline
; 08{code}
TextCommand08:
    pop hl
    ld de,NextTextCommand
    push de ; return address
    jp hl

; print decimal number (converted from binary number)
; 09AAAABB
; AAAA = address of number
; BB
; bits 0-3 = how many digits to display
; bits 4-7 = how long the number is in bytes
TextCommand09:
    pop hl
    ld a,[hli]
    ld e,a
    ld a,[hli]
    ld d,a
    ld a,[hli]
    push hl
    ld h,b
    ld l,c
    ld b,a
    and a,$0f
    ld c,a
    ld a,b
    and a,$f0
    swap a
    set 6,a
    ld b,a
    call PrintNumber
    ld b,h
    ld c,l
    pop hl
    jp NextTextCommand

; wait half a second if the user doesn't hold A or B
; 0A
; (no arguments)
TextCommand0A:
    push bc
    call GetJoypadState
    ld a,[H_CURRENTPRESSEDBUTTONS]
    and a,%00000011 ; A and B buttons
    jr nz,.skipDelay
    ld c,30
    call DelayFrames
.skipDelay
    pop bc
    pop hl
    jp NextTextCommand

; plays sounds
; this actually handles various command ID's,not just 0B
; (no arguments)
TextCommand0B:
    pop hl
    push bc
    dec hl
    ld a,[hli]
    ld b,a ; b = command number that got us here
    push hl
    ld hl,.TextCommandSounds
.loop
    ld a,[hli]
    cp b
    jr z,.matchFound
    inc hl
    jr .loop
.matchFound
    cp $14
    jr z,.pokemonCry
    cp $15
    jr z,.pokemonCry
    cp $16
    jr z,.pokemonCry
    ld a,[hl]
    call PlaySoundWaitForCurrent ; call PlaySound ; Denim : modifica per riprodurre i suoni anche con velocità massima dei testi
    call WaitForSoundToFinish
    pop hl
    pop bc
    jp NextTextCommand
.pokemonCry
    push de
    ld a,[hl]
    call PlayCry
    pop de
    pop hl
    pop bc
    jp NextTextCommand

; format: text command ID,sound ID or cry ID
.TextCommandSounds
    db $0B,$86
    db $12,$9A
    db $0E,$91
    db $0F,$A5 ; error
    db $10,$89
    db $11,$94
    db $13,$98
    db $14,$A8
    db $15,$97
    db $16,$78

; draw ellipses
; 0CAA
; AA = number of ellipses to draw
TextCommand0C:
    pop hl
    ld a,[hli]
    ld d,a
    push hl
    ld h,b
    ld l,c
.loop
    ld a,$75 ; ellipsis
    ld [hli],a
    push de
    call GetJoypadState
    pop de
    ld a,[H_CURRENTPRESSEDBUTTONS] ; joypad state
    and a,%00000011 ; is A or B button pressed?
    jr nz,.skipDelay ; if so,skip the delay
    ld c,10
    call DelayFrames
.skipDelay
    dec d
    jr nz,.loop
    ld b,h
    ld c,l
    pop hl
    jp NextTextCommand

; wait for A or B to be pressed
; 0D
; (no arguments)
TextCommand0D:
    push bc
    call ManualTextScroll ; wait for A or B to be pressed
    pop bc
    pop hl
    jp NextTextCommand

; process text commands in another ROM bank
; 17AAAABB
; AAAA = address of text commands
; BB = bank
TextCommand17:
    pop hl
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,[hli]
    ld e,a
    ld a,[hli]
    ld d,a
    ld a,[hli]
    call RoutineForRealGB
    push hl
    ld l,e
    ld h,d
    call TextCommandProcessor
    pop hl
    pop af
    call RoutineForRealGB
    jp NextTextCommand

TextCommandJumpTable:
    dw TextCommand00
    dw TextCommand01
    dw TextCommand02
    dw TextCommand03
    dw TextCommand04
    dw TextCommand05
    dw TextCommand06
    dw TextCommand07
    dw TextCommand08
    dw TextCommand09
    dw TextCommand0A
    dw TextCommand0B
    dw TextCommand0C
    dw TextCommand0D

SECTION "GetRowColAddressBgMap",ROM0[$1cdd]

; this function seems to be used only once
; it store the address of a row and column of the VRAM background map in hl
; INPUT: h - row,l - column,b - high byte of background tile map address in VRAM
GetRowColAddressBgMap: ; 1cdd (0:1cdd)
    xor a
    srl h
    rr a
    srl h
    rr a
    srl h
    rr a
    or l
    ld l,a
    ld a,b
    or h
    ld h,a
    ret

; clears a VRAM background map with blank space tiles
; INPUT: h - high byte of background tile map address in VRAM
ClearBgMap: ; 1cf0 (0:1cf0)
    ld a," "
    jr .next
    ld a,l
.next
    ld de,$400 ; size of VRAM background map
    ld l,e
.loop
    ld [hli],a
    dec e
    jr nz,.loop
    dec d
    jr nz,.loop
    ret

; When the player takes a step,a row or column of 2x2 tile blocks at the edge
; of the screen toward which they moved is exposed and has to be redrawn.
; This function does the redrawing.
RedrawExposedScreenEdge: ; 1d01 (0:1d01)
    ld a,[H_SCREENEDGEREDRAW]
    and a
    ret z
    ld b,a
    xor a
    ld [H_SCREENEDGEREDRAW],a
    dec b
    jr nz,.redrawRow
.redrawColumn
    ld hl,wScreenEdgeTiles
    ld a,[H_SCREENEDGEREDRAWADDR]
    ld e,a
    ld a,[H_SCREENEDGEREDRAWADDR + 1]
    ld d,a
    ld c,18 ; screen height
.loop1
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[hli]
    ld [de],a
    ld a,31
    add e
    ld e,a
    jr nc,.noCarry
    inc d
.noCarry
; the following 4 lines wrap us from bottom to top if necessary
    ld a,d
    and a,$03
    or a,$98
    ld d,a
    dec c
    jr nz,.loop1
    xor a
    ld [H_SCREENEDGEREDRAW],a
    ret
.redrawRow
    ld hl,wScreenEdgeTiles
    ld a,[H_SCREENEDGEREDRAWADDR]
    ld e,a
    ld a,[H_SCREENEDGEREDRAWADDR + 1]
    ld d,a
    push de
    call .drawHalf ; draw upper half
    pop de
    ld a,32 ; width of VRAM background map
    add e
    ld e,a
                     ; draw lower half
.drawHalf
    ld c,10
.loop2
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[hli]
    ld [de],a
    ld a,e
    inc a
; the following 6 lines wrap us from the right edge to the left edge if necessary
    and a,$1f
    ld b,a
    ld a,e
    and a,$e0
    or b
    ld e,a
    dec c
    jr nz,.loop2
    ret

; This function automatically transfers tile number data from the tile map at
; wTileMap to VRAM during V-blank. Note that it only transfers one third of the
; background per V-blank. It cycles through which third it draws.
; This transfer is turned off when walking around the map,but is turned
; on when talking to sprites,battling,using menus,etc. This is because
; the above function,RedrawExposedScreenEdge,is used when walking to
; improve efficiency.
AutoBgMapTransfer: ; 1d57 (0:1d57)
    ld a,[H_AUTOBGTRANSFERENABLED]
    and a
    ret z
    ld hl,sp + 0
    ld a,h
    ld [H_SPTEMP],a
    ld a,l
    ld [H_SPTEMP + 1],a ; save stack pinter
    ld a,[H_AUTOBGTRANSFERPORTION]
    and a
    jr z,.transferTopThird
    dec a
    jr z,.transferMiddleThird
.transferBottomThird
    FuncCoord 0,12
    ld hl,Coord
    ld sp,hl
    ld a,[H_AUTOBGTRANSFERDEST + 1]
    ld h,a
    ld a,[H_AUTOBGTRANSFERDEST]
    ld l,a
    ld de,(12 * 32)
    add hl,de
    xor a ; TRANSFERTOP
    jr .doTransfer
.transferTopThird
    FuncCoord 0,0
    ld hl,Coord
    ld sp,hl
    ld a,[H_AUTOBGTRANSFERDEST + 1]
    ld h,a
    ld a,[H_AUTOBGTRANSFERDEST]
    ld l,a
    ld a,TRANSFERMIDDLE
    jr .doTransfer
.transferMiddleThird
    FuncCoord 0,6
    ld hl,Coord
    ld sp,hl
    ld a,[H_AUTOBGTRANSFERDEST + 1]
    ld h,a
    ld a,[H_AUTOBGTRANSFERDEST]
    ld l,a
    ld de,(6 * 32)
    add hl,de
    ld a,TRANSFERBOTTOM
.doTransfer
    ld [H_AUTOBGTRANSFERPORTION],a ; store next portion
    ld b,6

; unrolled loop and using pop for speed
TransferBgRows: ; 1d9e (0:1d9e)
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    ld a,13
    add l
    ld l,a
    jr nc,.noCarry
    inc h
.noCarry
    dec b
    jr nz,TransferBgRows
    ld a,[H_SPTEMP]
    ld h,a
    ld a,[H_SPTEMP + 1]
    ld l,a
    ld sp,hl ; restore stack pointer
    ret

; Copies [H_VBCOPYBGNUMROWS] rows from H_VBCOPYBGSRC to H_VBCOPYBGDEST.
; If H_VBCOPYBGSRC is XX00,the transfer is disabled.
VBlankCopyBgMap: ; 1de1 (0:1de1)
    ld a,[H_VBCOPYBGSRC] ; doubles as enabling byte
    and a
    ret z
    ld hl,sp + 0
    ld a,h
    ld [H_SPTEMP],a
    ld a,l
    ld [H_SPTEMP + 1],a ; save stack pointer
    ld a,[H_VBCOPYBGSRC]
    ld l,a
    ld a,[H_VBCOPYBGSRC + 1]
    ld h,a
    ld sp,hl
    ld a,[H_VBCOPYBGDEST]
    ld l,a
    ld a,[H_VBCOPYBGDEST + 1]
    ld h,a
    ld a,[H_VBCOPYBGNUMROWS]
    ld b,a
    xor a
    ld [H_VBCOPYBGSRC],a ; disable transfer so it doesn't continue next V-blank
    jr TransferBgRows

; This function copies ([H_VBCOPYDOUBLESIZE] * 8) source bytes
; from H_VBCOPYDOUBLESRC to H_VBCOPYDOUBLEDEST.
; It copies each source byte to the destination twice (next to each other).
; The function updates the source and destination addresses,so the transfer
; can be continued easily by repeatingly calling this function.
VBlankCopyDouble: ; 1e02 (0:1e02)
    ld a,[H_VBCOPYDOUBLESIZE]
    and a ; are there any bytes to copy?
    ret z
    ld hl,sp + 0
    ld a,h
    ld [H_SPTEMP],a
    ld a,l
    ld [H_SPTEMP + 1],a ; save stack pointer
    ld a,[H_VBCOPYDOUBLESRC]
    ld l,a
    ld a,[H_VBCOPYDOUBLESRC + 1]
    ld h,a
    ld sp,hl
    ld a,[H_VBCOPYDOUBLEDEST]
    ld l,a
    ld a,[H_VBCOPYDOUBLEDEST + 1]
    ld h,a
    ld a,[H_VBCOPYDOUBLESIZE]
    ld b,a
    xor a
    ld [H_VBCOPYDOUBLESIZE],a ; disable transfer so it doesn't continue next V-blank
.loop
    pop de
    ld [hl],e
    inc l
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    ld [hl],d
    inc hl
    dec b
    jr nz,.loop
    ld a,l
    ld [H_VBCOPYDOUBLEDEST],a
    ld a,h
    ld [H_VBCOPYDOUBLEDEST + 1],a ; update destination address
    ld hl,sp + 0
    ld a,l
    ld [H_VBCOPYDOUBLESRC],a
    ld a,h
    ld [H_VBCOPYDOUBLESRC + 1],a ; update source address
    ld a,[H_SPTEMP]
    ld h,a
    ld a,[H_SPTEMP + 1]
    ld l,a
    ld sp,hl ; restore stack pointer
    ret

; Copies ([H_VBCOPYSIZE] * 16) bytes from H_VBCOPYSRC to H_VBCOPYDEST.
; The function updates the source and destination addresses,so the transfer
; can be continued easily by repeatingly calling this function.
VBlankCopy: ; 1e5e (0:1e5e)
    ld a,[H_VBCOPYSIZE]
    and a ; are there any bytes to copy?
    ret z
    ld hl,sp + 0
    ld a,h
    ld [H_SPTEMP],a
    ld a,l
    ld [H_SPTEMP + 1],a ; save stack pointer
    ld a,[H_VBCOPYSRC]
    ld l,a
    ld a,[H_VBCOPYSRC + 1]
    ld h,a
    ld sp,hl
    ld a,[H_VBCOPYDEST]
    ld l,a
    ld a,[H_VBCOPYDEST + 1]
    ld h,a
    ld a,[H_VBCOPYSIZE]
    ld b,a
    xor a
    ld [H_VBCOPYSIZE],a ; disable transfer so it doesn't continue next V-blank
.loop
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc l
    pop de
    ld [hl],e
    inc l
    ld [hl],d
    inc hl
    dec b
    jr nz,.loop
    ld a,l
    ld [H_VBCOPYDEST],a
    ld a,h
    ld [H_VBCOPYDEST + 1],a
    ld hl,sp + 0
    ld a,l
    ld [H_VBCOPYSRC],a
    ld a,h
    ld [H_VBCOPYSRC + 1],a
    ld a,[H_SPTEMP]
    ld h,a
    ld a,[H_SPTEMP + 1]
    ld l,a
    ld sp,hl ; restore stack pointer
    ret

; This function updates the moving water and flower background tiles.
UpdateMovingBgTiles: ; 1ebe (0:1ebe)
    ld a,[$ffd7]
    and a
    ret z
    ld a,[$ffd8]
    inc a
    ld [$ffd8],a
    cp 20
    ret c
    cp 21
    jr z,.updateFlowerTile
    ld hl,$9140 ; water tile pattern VRAM location
    ld c,16 ; number of bytes in a tile pattern
    ld a,[$d085]
    inc a
    and a,$07
    ld [$d085],a
    and a,$04
    jr nz,.rotateWaterLeftLoop
.rotateWaterRightloop
    ld a,[hl]
    rrca
    ld [hli],a
    dec c
    jr nz,.rotateWaterRightloop
    jr .done
.rotateWaterLeftLoop
    ld a,[hl]
    rlca
    ld [hli],a
    dec c
    jr nz,.rotateWaterLeftLoop
.done
    ld a,[$ffd7]
    rrca
    ret nc
    xor a
    ld [$ffd8],a
    ret
.updateFlowerTile
    xor a
    ld [$ffd8],a
    ld a,[$d085]
    and a,$03
    cp 2
    ld hl,FlowerTilePattern1
    jr c,.writeTilePatternToVram
    ld hl,FlowerTilePattern2
    jr z,.writeTilePatternToVram
    ld hl,FlowerTilePattern3
.writeTilePatternToVram
    ld de,$9030 ; flower tile pattern VRAM location
    ld c,16 ; number of bytes in a tile pattern
.flowerTileLoop
    ld a,[hli]
    ld [de],a
    inc de
    dec c
    jr nz,.flowerTileLoop
    ret

FlowerTilePattern1: ; 1f19 (0:1f19)
    INCBIN "gfx/tilesets/flower/flower1.2bpp"

FlowerTilePattern2: ; 1f29 (0:1f29)
    INCBIN "gfx/tilesets/flower/flower2.2bpp"

FlowerTilePattern3: ; 1f39 (0:1f39)
    INCBIN "gfx/tilesets/flower/flower3.2bpp"

SECTION "SoftReset",ROM0[$1f49]

SoftReset: ; 1f49 (0:1f49)
    call StopAllSounds
    call GBPalWhiteOut
    ld c,$20
    call DelayFrames
    ;fall through

; initialization code
; explanation for %11100011 (value stored in rLCDC)
; * LCD enabled
; * Window tile map at $9C00
; * Window display enabled
; * BG and window tile data at $8800
; * BG tile map at $9800
; * 8x8 OBJ size
; * OBJ display enabled
; * BG display enabled
InitGame: ; 1f54 (0:1f54)
    di
; zero I/O registers
    xor a
    ld [$ff0f],a
    ld [$ffff],a
    ld [$ff43],a
    ld [$ff42],a
    ld [$ff01],a
    ld [$ff02],a
    ld [$ff4b],a
    ld [$ff4a],a
    ld [$ff06],a
    ld [$ff07],a
    ld [$ff47],a
    ld [$ff48],a
    ld [$ff49],a
    ld a,%10000000 ; enable LCD
    ld [rLCDC],a
    call DisableLCD ; why enable then disable?
    ld sp,$dfff ; initialize stack pointer
    ld hl,$c000 ; start of WRAM
    ld bc,$2000-1 ; size of WRAM
.zeroWramLoop
    ld [hl],0
    inc hl
    dec bc
    ld a,b
    or c
    jr nz,.zeroWramLoop
    call ZeroVram
    ld hl,$ff80
    ld bc,$007f
    call FillMemory ; zero HRAM
    call CleanLCD_OAM ; this is unnecessary since it was already cleared above
    ld a,BANK(WriteDMACodeToHRAMAndInitializeRNGState)
    call RoutineForRealGB
    call WriteDMACodeToHRAMAndInitializeRNGState ; copy DMA code to HRAM and Initialize RNG State
    xor a
    ld [$ffd7],a
    ld [$ff41],a
    ld [$ffae],a
    ld [$ffaf],a
    ld [$ff0f],a
    ld a,%00001101 ; enable V-blank,timer,and serial interrupts
    ld [rIE],a
    ld a,$90 ; put the window off the screen
    ld [$ffb0],a
    ld [rWY],a
    ld a,$07
    ld [rWX],a
    ld a,$ff
    ld [$ffaa],a
    ld h,$98
    call ClearBgMap ; fill $9800-$9BFF (BG tile map) with $7F tiles
    ld h,$9c
    call ClearBgMap ; fill $9C00-$9FFF (Window tile map) with $7F tiles
    ld a,%11100011
    ld [rLCDC],a ; enabled LCD
    ld a,$10
    ld [H_SOFTRESETCOUNTER],a
    call StopAllSounds
    ei
    PREDEF Func_7202b ; SGB border
    ld a,$1f
    ld [$c0ef],a
    ld [$c0f0],a
    ld a,$9c
    ld [$ffbd],a
    xor a
    ld [$ffbc],a
    dec a
    ld [$cfcb],a
    PREDEF PlayIntro ; display the copyrights,GameFreak logo,and battle animation
    call DisableLCD
    call ZeroVram
    call GBPalNormal
    call CleanLCD_OAM
    ld a,%11100011
    ld [rLCDC],a ; enable LCD
    jp Func_42b7

; zeroes all VRAM
ZeroVram:
    ld hl,$8000
    ld bc,$2000
    xor a
    jp FillMemory

; immediately stops all sounds
StopAllSounds:
    ld a,$2
    ld [$c0ef],a
    ld [$c0f0],a
    xor a
    ld [wMusicHeaderPointer],a
    ld [$c0ee],a
    ld [$cfca],a
    dec a
    jp PlaySound

VBlankHandler:
    push af
    push bc
    push de
    push hl
    ld a,[H_LOADEDROMBANK] ; current ROM bank
    ld [$d122],a
    ld a,[$ffae]
    ld [rSCX],a
    ld a,[$ffaf]
    ld [rSCY],a
    ld a,[$d0a0]
    and a
    jr nz,.doVramTransfers
    ld a,[$ffb0]
    ld [rWY],a
.doVramTransfers
    call AutoBgMapTransfer
    call VBlankCopyBgMap
    call RedrawExposedScreenEdge
    call VBlankCopy
    call VBlankCopyDouble
    call UpdateMovingBgTiles
    call $ff80 ; OAM DMA
    ld a,BANK(PrepareOAMData)
    call RoutineForRealGB
    call PrepareOAMData ; update OAM buffer with current sprite data
    call GenRandomAndAdvanceRNGState
    ld a,[H_VBLANKOCCURRED]
    and a
    jr z,.next
    xor a
    ld [H_VBLANKOCCURRED],a
.next
    ld a,[H_FRAMECOUNTER]
    and a
    jr z,.handleMusic
    dec a
    ld [H_FRAMECOUNTER],a
.handleMusic
    call Func_28cb
    ld a,[$c0ef] ; music ROM bank
    call RoutineForRealGB
    cp $02
    jr nz,.checkIfBank08
.bank02
    call Func_9103
    jr .afterMusic
.checkIfBank08
    cp $08
    jr nz,.bank1F
.bank08
    call Func_2136e
    call Func_21879
    jr .afterMusic
.bank1F
    call Func_7d177
.afterMusic
    BANKSWITCH Func_18dee ; keep track of time played
    ld a,[$fff9]
    and a
    call z,ReadJoypadRegister
    call PostVBlankHandler
    ld a,[$d122]
    call RoutineForRealGB
    pop hl
    pop de
    pop bc
    pop af
    reti

