; bankswitches and runs _UncompressSpriteData
; bank is given in a,sprite input stream is pointed to in W_SPRITEINPUTPTR
UncompressSpriteData:
    ld b,a
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,b
    call RoutineForRealGB
    ld a,$a
    ld [$0],a
    xor a
    ld [$4000],a
    call _UncompressSpriteData
    pop af
    jp RoutineForRealGB

SECTION "_UncompressSpriteData",ROM0[$251a]

; initializes necessary data to load a sprite and runs UncompressSpriteDataLoop
_UncompressSpriteData: ; 251a (0:251a)
    ld hl,S_SPRITEBUFFER1
    ld c,(2*SPRITEBUFFERSIZE) % $100
    ld b,(2*SPRITEBUFFERSIZE) / $100
    xor a
    call FillMemory           ; clear sprite buffer 1 and 2
    ld a,$1
    ld [W_SPRITEINPUTBITCOUNTER],a
    ld a,$3
    ld [W_SPRITEOUTPUTBITOFFSET],a
    xor a
    ld [W_SPRITECURPOSX],a
    ld [W_SPRITECURPOSY],a
    ld [W_SPRITELOADFLAGS],a ; $d0a8
    call ReadNextInputByte    ; first byte of input determines sprite width (high nybble) and height (low nybble) in tiles (8x8 pixels)
    ld b,a
    and $f
    add a
    add a
    add a
    ld [W_SPRITEHEIGHT],a
    ld a,b
    swap a
    and $f
    add a
    add a
    add a
    ld [W_SPRITEWITDH],a
    call ReadNextInputBit
    ld [W_SPRITELOADFLAGS],a ; initialite bit1 to 0 and bit0 to the first input bit
                              ; this will load two chunks of data to S_SPRITEBUFFER1 and S_SPRITEBUFFER2
                              ; bit 0 decides in which one the first chunk is placed
    ; ft

; uncompresses a chunk from the sprite input data stream (pointed to at $d0da) into S_SPRITEBUFFER1 or S_SPRITEBUFFER2
; each chunk is a 1bpp sprite. A 2bpp sprite consist of two chunks which are merged afterwards
; note that this is an endless loop which is terminated during a call to MoveToNextBufferPosition by manipulating the stack
UncompressSpriteDataLoop: ; 2556 (0:2556)
    ld hl,S_SPRITEBUFFER1
    ld a,[W_SPRITELOADFLAGS]  ; $d0a8
    bit 0,a
    jr z,.useSpriteBuffer1    ; check which buffer to use
    ld hl,S_SPRITEBUFFER2
.useSpriteBuffer1
    call StoreSpriteOutputPointer
    ld a,[W_SPRITELOADFLAGS]  ; $d0a8
    bit 1,a
    jr z,.startDecompression  ; check if last iteration
    call ReadNextInputBit      ; if last chunk,read 1-2 bit unpacking mode
    and a
    jr z,.unpackingMode0      ; 0   -> mode 0
    call ReadNextInputBit      ; 1 0 -> mode 1
    inc a                      ; 1 1 -> mode 2
.unpackingMode0
    ld [W_SPRITEUNPACKMODE],a
.startDecompression
    call ReadNextInputBit
    and a
    jr z,.readRLEncodedZeros ; if first bit is 0,the input starts with zeroes,otherwise with (non-zero) input
.readNextInput
    call ReadNextInputBit
    ld c,a
    call ReadNextInputBit
    sla c
    or c                       ; read next two bits into c
    and a
    jr z,.readRLEncodedZeros ; 00 -> RLEncoded zeroes following
    call WriteSpriteBitsToBuffer  ; otherwise write input to output and repeat
    call MoveToNextBufferPosition
    jr .readNextInput
.readRLEncodedZeros
    ld c,$0                   ; number of zeroes it length encoded,the number
.countConsecutiveOnesLoop      ; of consecutive ones determines the number of bits the number has
    call ReadNextInputBit
    and a
    jr z,.countConsecutiveOnesFinished
    inc c
    jr .countConsecutiveOnesLoop
.countConsecutiveOnesFinished
    ld a,c
    add a
    ld hl,LengthEncodingOffsetList
    add l
    ld l,a
    jr nc,.noCarry
    inc h
.noCarry
    ld a,[hli]                ; read offset that is added to the number later on
    ld e,a                    ; adding an offset of 2^length - 1 makes every integer uniquely
    ld d,[hl]                 ; representable in the length encoding and saves bits
    push de
    inc c
    ld e,$0
    ld d,e
.readNumberOfZerosLoop        ; reads the next c+1 bits of input
    call ReadNextInputBit
    or e
    ld e,a
    dec c
    jr z,.readNumberOfZerosDone
    sla e
    rl d
    jr .readNumberOfZerosLoop
.readNumberOfZerosDone
    pop hl                     ; add the offset
    add hl,de
    ld e,l
    ld d,h
.writeZerosLoop
    ld b,e
    xor a                      ; write 00 to buffer
    call WriteSpriteBitsToBuffer
    ld e,b
    call MoveToNextBufferPosition
    dec de
    ld a,d
    and a
    jr nz,.continueLoop
    ld a,e
    and a
.continueLoop
    jr nz,.writeZerosLoop
    jr .readNextInput

; moves output pointer to next position
; also cancels the calling function if the all output is done (by removing the return pointer from stack)
; and calls postprocessing functions according to the unpack mode
MoveToNextBufferPosition: ; 25d8 (0:25d8)
    ld a,[W_SPRITEHEIGHT]
    ld b,a
    ld a,[W_SPRITECURPOSY]
    inc a
    cp b
    jr z,.curColumnDone
    ld [W_SPRITECURPOSY],a
    ld a,[W_SPRITEOUTPUTPTR]
    inc a
    ld [W_SPRITEOUTPUTPTR],a
    ret nz
    ld a,[W_SPRITEOUTPUTPTR+1]
    inc a
    ld [W_SPRITEOUTPUTPTR+1],a
    ret
.curColumnDone
    xor a
    ld [W_SPRITECURPOSY],a
    ld a,[W_SPRITEOUTPUTBITOFFSET]
    and a
    jr z,.bitOffsetsDone
    dec a
    ld [W_SPRITEOUTPUTBITOFFSET],a
    ld hl,W_SPRITEOUTPUTPTRCACHED
    ld a,[hli]
    ld [W_SPRITEOUTPUTPTR],a
    ld a,[hl]
    ld [W_SPRITEOUTPUTPTR+1],a
    ret
.bitOffsetsDone
    ld a,$3
    ld [W_SPRITEOUTPUTBITOFFSET],a
    ld a,[W_SPRITECURPOSX]
    add $8
    ld [W_SPRITECURPOSX],a
    ld b,a
    ld a,[W_SPRITEWITDH]
    cp b
    jr z,.allColumnsDone
    ld a,[W_SPRITEOUTPUTPTR]
    ld l,a
    ld a,[W_SPRITEOUTPUTPTR+1]
    ld h,a
    inc hl
    jp StoreSpriteOutputPointer
.allColumnsDone
    pop hl
    xor a
    ld [W_SPRITECURPOSX],a
    ld a,[W_SPRITELOADFLAGS] ; $d0a8
    bit 1,a
    jr nz,.done            ; test if there is one more sprite to go
    xor $1
    set 1,a
    ld [W_SPRITELOADFLAGS],a ; $d0a8
    jp UncompressSpriteDataLoop
.done
    jp UnpackSprite

; writes 2 bits (from a) to the output buffer (pointed to from W_SPRITEOUTPUTPTR)
WriteSpriteBitsToBuffer: ; 2649 (0:2649)
    ld e,a
    ld a,[W_SPRITEOUTPUTBITOFFSET]
    and a
    jr z,.offset0
    cp $2
    jr c,.offset1
    jr z,.offset2
    rrc e ; offset 3
    rrc e
    jr .offset0
.offset1
    sla e
    sla e
    jr .offset0
.offset2
    swap e
.offset0
    ld a,[W_SPRITEOUTPUTPTR]
    ld l,a
    ld a,[W_SPRITEOUTPUTPTR+1]
    ld h,a
    ld a,[hl]
    or e
    ld [hl],a
    ret

; reads next bit from input stream and returns it in a
ReadNextInputBit: ; 2670 (0:2670)
    ld a,[W_SPRITEINPUTBITCOUNTER]
    dec a
    jr nz,.curByteHasMoreBitsToRead
    call ReadNextInputByte
    ld [W_SPRITEINPUTCURBYTE],a
    ld a,$8
.curByteHasMoreBitsToRead
    ld [W_SPRITEINPUTBITCOUNTER],a
    ld a,[W_SPRITEINPUTCURBYTE]
    rlca
    ld [W_SPRITEINPUTCURBYTE],a
    and $1
    ret

; reads next byte from input stream and returns it in a
ReadNextInputByte: ; 268b (0:268b)
    ld a,[W_SPRITEINPUTPTR]
    ld l,a
    ld a,[W_SPRITEINPUTPTR+1]
    ld h,a
    ld a,[hli]
    ld b,a
    ld a,l
    ld [W_SPRITEINPUTPTR],a
    ld a,h
    ld [W_SPRITEINPUTPTR+1],a
    ld a,b
    ret

; the nth item is 2^n - 1
LengthEncodingOffsetList: ; 269f (0:269f)
    dw %0000000000000001
    dw %0000000000000011
    dw %0000000000000111
    dw %0000000000001111
    dw %0000000000011111
    dw %0000000000111111
    dw %0000000001111111
    dw %0000000011111111
    dw %0000000111111111
    dw %0000001111111111
    dw %0000011111111111
    dw %0000111111111111
    dw %0001111111111111
    dw %0011111111111111
    dw %0111111111111111
    dw %1111111111111111

; unpacks the sprite data depending on the unpack mode
UnpackSprite: ; 26bf (0:26bf)
    ld a,[W_SPRITEUNPACKMODE]
    cp $2
    jp z,UnpackSpriteMode2
    and a
    jp nz,XorSpriteChunks
    ld hl,S_SPRITEBUFFER1
    call SpriteDifferentialDecode
    ld hl,S_SPRITEBUFFER2
    ; ft

; decodes differential encoded sprite data
; input bit value 0 preserves the current bit value and input bit value 1 toggles it (starting from initial value 0).
SpriteDifferentialDecode: ; 26d4 (0:26d4)
    xor a
    ld [W_SPRITECURPOSX],a
    ld [W_SPRITECURPOSY],a
    call StoreSpriteOutputPointer
    ld a,[W_SPRITEFLIPPED]
    and a
    jr z,.notFlipped
    ld hl,DecodeNybble0TableFlipped
    ld de,DecodeNybble1TableFlipped
    jr .storeDecodeTablesPointers
.notFlipped
    ld hl,DecodeNybble0Table
    ld de,DecodeNybble1Table
.storeDecodeTablesPointers
    ld a,l
    ld [W_SPRITEDECODETABLE0PTR],a
    ld a,h
    ld [W_SPRITEDECODETABLE0PTR+1],a
    ld a,e
    ld [W_SPRITEDECODETABLE1PTR],a
    ld a,d
    ld [W_SPRITEDECODETABLE1PTR+1],a
    ld e,$0                          ; last decoded nybble,initialized to 0
.decodeNextByteLoop
    ld a,[W_SPRITEOUTPUTPTR]
    ld l,a
    ld a,[W_SPRITEOUTPUTPTR+1]
    ld h,a
    ld a,[hl]
    ld b,a
    swap a
    and $f
    call DifferentialDecodeNybble     ; decode high nybble
    swap a
    ld d,a
    ld a,b
    and $f
    call DifferentialDecodeNybble     ; decode low nybble
    or d
    ld b,a
    ld a,[W_SPRITEOUTPUTPTR]
    ld l,a
    ld a,[W_SPRITEOUTPUTPTR+1]
    ld h,a
    ld a,b
    ld [hl],a                        ; write back decoded data
    ld a,[W_SPRITEHEIGHT]
    add l                             ; move on to next column
    jr nc,.noCarry
    inc h
.noCarry
    ld [W_SPRITEOUTPUTPTR],a
    ld a,h
    ld [W_SPRITEOUTPUTPTR+1],a
    ld a,[W_SPRITECURPOSX]
    add $8
    ld [W_SPRITECURPOSX],a
    ld b,a
    ld a,[W_SPRITEWITDH]
    cp b
    jr nz,.decodeNextByteLoop        ; test if current row is done
    xor a
    ld e,a
    ld [W_SPRITECURPOSX],a
    ld a,[W_SPRITECURPOSY]           ; move on to next row
    inc a
    ld [W_SPRITECURPOSY],a
    ld b,a
    ld a,[W_SPRITEHEIGHT]
    cp b
    jr z,.done                       ; test if all rows finished
    ld a,[W_SPRITEOUTPUTPTRCACHED]
    ld l,a
    ld a,[W_SPRITEOUTPUTPTRCACHED+1]
    ld h,a
    inc hl
    call StoreSpriteOutputPointer
    jr .decodeNextByteLoop
.done
    xor a
    ld [W_SPRITECURPOSY],a
    ret

; decodes the nybble stored in a. Last decoded data is assumed to be in e (needed to determine if initial value is 0 or 1)
DifferentialDecodeNybble: ; 276d (0:276d)
    srl a               ; c=a%2,a/=2
    ld c,$0
    jr nc,.evenNumber
    ld c,$1
.evenNumber
    ld l,a
    ld a,[W_SPRITEFLIPPED]
    and a
    jr z,.notFlipped     ; determine if initial value is 0 or one
    bit 3,e              ; if flipped,consider MSB of last data
    jr .selectLookupTable
.notFlipped
    bit 0,e              ; else consider LSB
.selectLookupTable
    ld e,l
    jr nz,.initialValue1 ; load the appropriate table
    ld a,[W_SPRITEDECODETABLE0PTR]
    ld l,a
    ld a,[W_SPRITEDECODETABLE0PTR+1]
    jr .tableLookup
.initialValue1
    ld a,[W_SPRITEDECODETABLE1PTR]
    ld l,a
    ld a,[W_SPRITEDECODETABLE1PTR+1]
.tableLookup
    ld h,a
    ld a,e
    add l
    ld l,a
    jr nc,.noCarry
    inc h
.noCarry
    ld a,[hl]
    bit 0,c
    jr nz,.selectLowNybble
    swap a  ; select high nybble
.selectLowNybble
    and $f
    ld e,a ; update last decoded data
    ret

DecodeNybble0Table: ; 27a7 (0:27a7)
    dn $0,$1
    dn $3,$2
    dn $7,$6
    dn $4,$5
    dn $f,$e
    dn $c,$d
    dn $8,$9
    dn $b,$a
DecodeNybble1Table: ; 27af (0:27af)
    dn $f,$e
    dn $c,$d
    dn $8,$9
    dn $b,$a
    dn $0,$1
    dn $3,$2
    dn $7,$6
    dn $4,$5
DecodeNybble0TableFlipped: ; 27b7 (0:27b7)
    dn $0,$8
    dn $c,$4
    dn $e,$6
    dn $2,$a
    dn $f,$7
    dn $3,$b
    dn $1,$9
    dn $d,$5
DecodeNybble1TableFlipped: ; 27bf (0:27bf)
    dn $f,$7
    dn $3,$b
    dn $1,$9
    dn $d,$5
    dn $0,$8
    dn $c,$4
    dn $e,$6
    dn $2,$a

; combines the two loaded chunks with xor (the chunk loaded second is the destination). The source chunk is differeintial decoded beforehand.
XorSpriteChunks: ; 27c7 (0:27c7)
    xor a
    ld [W_SPRITECURPOSX],a
    ld [W_SPRITECURPOSY],a
    call ResetSpriteBufferPointers
    ld a,[W_SPRITEOUTPUTPTR]          ; points to buffer 1 or 2,depending on flags
    ld l,a
    ld a,[W_SPRITEOUTPUTPTR+1]
    ld h,a
    call SpriteDifferentialDecode      ; decode buffer 1 or 2,depending on flags
    call ResetSpriteBufferPointers
    ld a,[W_SPRITEOUTPUTPTR]          ; source buffer,points to buffer 1 or 2,depending on flags
    ld l,a
    ld a,[W_SPRITEOUTPUTPTR+1]
    ld h,a
    ld a,[W_SPRITEOUTPUTPTRCACHED]    ; destination buffer,points to buffer 2 or 1,depending on flags
    ld e,a
    ld a,[W_SPRITEOUTPUTPTRCACHED+1]
    ld d,a
.xorChunksLoop
    ld a,[W_SPRITEFLIPPED]
    and a
    jr z,.notFlipped
    push de
    ld a,[de]
    ld b,a
    swap a
    and $f
    call ReverseNybble                 ; if flipped reverse the nybbles in the destination buffer
    swap a
    ld c,a
    ld a,b
    and $f
    call ReverseNybble
    or c
    pop de
    ld [de],a
.notFlipped
    ld a,[hli]
    ld b,a
    ld a,[de]
    xor b
    ld [de],a
    inc de
    ld a,[W_SPRITECURPOSY]
    inc a
    ld [W_SPRITECURPOSY],a             ; go to next row
    ld b,a
    ld a,[W_SPRITEHEIGHT]
    cp b
    jr nz,.xorChunksLoop               ; test if column finished
    xor a
    ld [W_SPRITECURPOSY],a
    ld a,[W_SPRITECURPOSX]
    add $8
    ld [W_SPRITECURPOSX],a             ; go to next column
    ld b,a
    ld a,[W_SPRITEWITDH]
    cp b
    jr nz,.xorChunksLoop               ; test if all columns finished
    xor a
    ld [W_SPRITECURPOSX],a
    ret

; reverses the bits in the nybble given in register a
ReverseNybble: ; 2837 (0:2837)
    ld de,NybbleReverseTable
    add e
    ld e,a
    jr nc,.asm_283f
    inc d
.asm_283f
    ld a,[de]
    ret

; resets sprite buffer pointers to buffer 1 and 2,depending on W_SPRITELOADFLAGS
ResetSpriteBufferPointers: ; 2841 (0:2841)
    ld a,[W_SPRITELOADFLAGS] ; $d0a8
    bit 0,a
    jr nz,.buffer2Selected
    ld de,S_SPRITEBUFFER1
    ld hl,S_SPRITEBUFFER2
    jr .storeBufferPointers
.buffer2Selected
    ld de,S_SPRITEBUFFER2
    ld hl,S_SPRITEBUFFER1
.storeBufferPointers
    ld a,l
    ld [W_SPRITEOUTPUTPTR],a
    ld a,h
    ld [W_SPRITEOUTPUTPTR+1],a
    ld a,e
    ld [W_SPRITEOUTPUTPTRCACHED],a
    ld a,d
    ld [W_SPRITEOUTPUTPTRCACHED+1],a
    ret

; maps each nybble to its reverse
NybbleReverseTable: ; 2867 (0:2867)
    db $0,$8,$4,$c,$2,$a,$6 ,$e,$1,$9,$5,$d,$3,$b,$7 ,$f

; combines the two loaded chunks with xor (the chunk loaded second is the destination). Both chunks are differeintial decoded beforehand.
UnpackSpriteMode2: ; 2877 (0:2877)
    call ResetSpriteBufferPointers
    ld a,[W_SPRITEFLIPPED]
    push af
    xor a
    ld [W_SPRITEFLIPPED],a            ; temporarily clear flipped flag for decoding the destination chunk
    ld a,[W_SPRITEOUTPUTPTRCACHED]
    ld l,a
    ld a,[W_SPRITEOUTPUTPTRCACHED+1]
    ld h,a
    call SpriteDifferentialDecode
    call ResetSpriteBufferPointers
    pop af
    ld [W_SPRITEFLIPPED],a
    jp XorSpriteChunks

; stores hl into the output pointers
StoreSpriteOutputPointer: ; 2897 (0:2897)
    ld a,l
    ld [W_SPRITEOUTPUTPTR],a
    ld [W_SPRITEOUTPUTPTRCACHED],a
    ld a,h
    ld [W_SPRITEOUTPUTPTR+1],a
    ld [W_SPRITEOUTPUTPTRCACHED+1],a
    ret

ResetPlayerSpriteData: ; 28a6 (0:28a6)
    ld hl,wSpriteStateData1
    call ResetPlayerSpriteData_ClearSpriteData
    ld hl,wSpriteStateData2
    call ResetPlayerSpriteData_ClearSpriteData
    ld a,$1
    ld [wSpriteStateData1],a
    ld [$c20e],a
    ld hl,$c104
    ld [hl],$3c     ; set Y screen pos
    inc hl
    inc hl
    ld [hl],$40     ; set X screen pos
    ret

; overwrites sprite data with zeroes
ResetPlayerSpriteData_ClearSpriteData: ; 28c4 (0:28c4)
    ld bc,$10
    xor a
    jp FillMemory

Func_28cb: ; 28cb (0:28cb)
    ld a,[wMusicHeaderPointer]
    and a
    jr nz,.asm_28dc
    ld a,[$d72c]
    bit 1,a
    ret nz
    ld a,$77
    ld [$FF00+$24],a
    ret
.asm_28dc
    ld a,[$cfc9]
    and a
    jr z,.asm_28e7
    dec a
    ld [$cfc9],a
    ret
.asm_28e7
    ld a,[$cfc8]
    ld [$cfc9],a
    ld a,[$FF00+$24]
    and a
    jr z,.asm_2903
    ld b,a
    and $f
    dec a
    ld c,a
    ld a,b
    and $f0
    swap a
    dec a
    swap a
    or c
    ld [$FF00+$24],a
    ret
.asm_2903
    ld a,[wMusicHeaderPointer]
    ld b,a
    xor a
    ld [wMusicHeaderPointer],a
    ld a,$ff
    ld [$c0ee],a
    call PlaySound
    ld a,[$c0f0]
    ld [$c0ef],a
    ld a,b
    ld [$c0ee],a
    jp PlaySound

; this function is used to display sign messages,sprite dialog,etc.
; INPUT: [$ff8c] = sprite ID or text ID
DisplayTextID: ; 2920 (0:2920)
    ld a,[H_LOADEDROMBANK]
    push af
    BANKSWITCH DisplayTextIDInit ; initialization
    ld hl,$cf11
    bit 0,[hl]
    res 0,[hl]
    jr nz,.skipSwitchToMapBank
    ld a,[W_CURMAP]
    call SwitchToMapRomBank
.skipSwitchToMapBank
    ld a,30 ; half a second
    ld [H_FRAMECOUNTER],a ; used as joypad poll timer
    ld hl,W_MAPTEXTPTR
    ld a,[hli]
    ld h,[hl]
    ld l,a ; hl = map text pointer
    ld d,$00
    ld a,[$ff8c] ; text ID
    ld [$cf13],a
    and a
    jp z,DisplayStartMenu
    cp $d3 ; safari game over
    jp z,DisplaySafariGameOverText
    cp $d0 ; fainted
    jp z,DisplayPokemonFaintedText
    cp $d1 ; blacked out
    jp z,DisplayPlayerBlackedOutText
    cp $d2 ; repel wore off
    jp z,DisplayRepelWoreOffText
    jp HackForOtherText ; ld a,[$d4e1] ; number of sprites
ReturnInDisplayTextIDHack:
    ld e,a
    ld a,[$ff8c] ; sprite ID
    cp e
    jr z,.spriteHandling
    jr nc,.skipSpriteHandling
.spriteHandling
; get the text ID of the sprite
    push hl
    push de
    push bc
    BANKSWITCH Func_13074 ; update the graphics of the sprite the player is talking to (to face the right direction)
    pop bc
    pop de
    ld hl,W_MAPSPRITEDATA ; NPC text entries
    ld a,[$ff8c]
    dec a
    add a
    add l
    ld l,a
    jr nc,.noCarry
    inc h
.noCarry
    inc hl
    ld a,[hl] ; a = text ID of the sprite
    pop hl
.skipSpriteHandling
; look up the address of the text in the map's text entries
    dec a
    ld e,a
    sla e
    add hl,de
    ld a,[hli]
    ld h,[hl]
    ld l,a ; hl = address of the text
    ld a,[hl] ; a = first byte of text
; check first byte of text for special cases
    cp $fe   ; Pokemart NPC
    jp z,DisplayPokemartDialogue
    cp $ff   ; Pokemon Center NPC
    jp z,DisplayPokemonCenterDialogue
    cp $fc   ; Item Storage PC
    jp z,FuncTX_ItemStoragePC
    cp $fd   ; Bill's PC
    jp z,FuncTX_BillsPC
    cp $f9   ; Pokemon Center PC
    jp z,FuncTX_PokemonCenterPC
    cp $f5   ; Vending Machine
    jr nz,.notVendingMachine
    BANKSWITCH VendingMachineMenu ; jump banks to vending machine routine
    jr AfterDisplayingTextID
.notVendingMachine
    cp $f7   ; slot machine
    jp z,FuncTX_SlotMachine
    cp $f6   ; cable connection NPC in Pokemon Center
    jr nz,.notSpecialCase
    BANKSWITCH DebugNPC ; BANKSWITCH CableClubNPC
    jr AfterDisplayingTextID
.notSpecialCase
    call Func_3c59 ; display the text
    ld a,[$cc3c]
    and a
    jr nz,HoldTextDisplayOpen

AfterDisplayingTextID: ; 29d6 (0:29d6)
    ld a,[$cc47]
    and a
    jr nz,HoldTextDisplayOpen
    call WaitForTextScrollButtonPress ; wait for a button press after displaying all the text

; loop to hold the dialogue box open as long as the player keeps holding down the A button
HoldTextDisplayOpen: ; 29df (0:29df)
    call GetJoypadState
    ld a,[H_CURRENTPRESSEDBUTTONS]
    bit 0,a ; is the A button being pressed?
    jr nz,HoldTextDisplayOpen

SECTION "CloseTextDisplay",ROM0[$29e8]

CloseTextDisplay: ; 29e8 (0:29e8)
    ld a,[W_CURMAP]
    call SwitchToMapRomBank
    ld a,$90
    ld [$ffb0],a ; move the window off the screen
    call DelayFrame
    call LoadGBPal
    xor a
    ld [H_AUTOBGTRANSFERENABLED],a ; disable continuous WRAM to VRAM transfer each V-blank
; loop to make sprites face the directions they originally faced before the dialogue
    ld hl,$c219
    ld c,$0f
    ld de,$0010
.restoreSpriteFacingDirectionLoop
    ld a,[hl]
    dec h
    ld [hl],a
    inc h
    add hl,de
    dec c
    jr nz,.restoreSpriteFacingDirectionLoop
    ld a,BANK(InitMapSprites)
    call RoutineForRealGB
    call InitMapSprites ; reload sprite tile pattern data (since it was partially overwritten by text tile patterns)
    ld hl,$cfc4
    res 0,[hl]
    ld a,[$d732]
    bit 3,a
    call z,LoadPlayerSpriteGraphics
    call LoadCurrentMapView
    pop af
    call RoutineForRealGB
    jp UpdateSprites ; move sprites

DisplayPokemartDialogue:
    push hl
    ld hl,.PokemartGreetingText
    call PrintText
    pop hl
    inc hl
    call LoadItemList
    ld a,$02
    ld [$cf94],a ; selects between subtypes of menus
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,BANK(DisplayPokemartDialogue_)
    call RoutineForRealGB
    call DisplayPokemartDialogue_
    pop af
    call RoutineForRealGB
    jp AfterDisplayingTextID

.PokemartGreetingText
    TX_FAR _PokemartGreetingText
    db "@"

LoadItemList:
    ld a,$01
    ld [$cfcb],a
    ld de,wBufferList + 1
    ld b,-1
.loop
    ld a,[hli]
    ld [de],a
    inc de
    inc b
    inc a
    jr nz,.loop
    ld a,b
    ld [wBufferList],a
    ret

DisplayPokemonCenterDialogue:
    xor a
    ld [$ff8b],a
    ld [$ff8c],a
    ld [$ff8d],a
    inc hl
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,BANK(DisplayPokemonCenterDialogue_)
    call RoutineForRealGB
    call DisplayPokemonCenterDialogue_
    pop af
    call RoutineForRealGB
    jp AfterDisplayingTextID

DisplaySafariGameOverText:
    BANKSWITCH Func_1e9ed
    jp AfterDisplayingTextID

DisplayPokemonFaintedText:
    ld hl,PokemonFaintedText
    call PrintText
    jp AfterDisplayingTextID

PokemonFaintedText:
    TX_FAR _PokemonFaintedText
    db "@"

DisplayPlayerBlackedOutText:
    ld hl,PlayerBlackedOutText
    call PrintText
    ld a,[$d732]
    res 5,a
    ld [$d732],a
    jp HoldTextDisplayOpen

PlayerBlackedOutText:
    TX_FAR _PlayerBlackedOutText
    db "@"

DisplayRepelWoreOffText:
    BANKSWITCH TryUseAnotherRepel
    jp CloseTextDisplay

DisplayStartMenu:
    ld a,BANK(StartMenu_Pokedex)
    call RoutineForRealGB ; ROM bank 4 
    ld hl,$cd38 ; DisableDebugWtW_Hack
    res 0,[hl]  ; ...
    ld a,[$d700] ; walking/biking/surfing
    ld [$d11a],a
    ld a,(SFX_02_3f - $4000) / 3 ; Start menu sound
    call PlaySound
    ; ft

RedisplayStartMenu:
    BANKSWITCH DrawStartMenu
    BANKSWITCH Func_c52f ; print Safari Zone info,if in Safari Zone
    call UpdateSprites ; move sprites
.loop
    call HandleMenuInput
    ld b,a
.checkIfUpPressed
    bit 6,a ; was Up pressed?
    jr z,.checkIfDownPressed
    ld a,[wCurrentMenuItem] ; menu selection
    and a
    jr nz,.loop
    ld a,[wLastMenuItem]
    and a
    jr nz,.loop
; if the player pressed tried to go past the top item,wrap around to the bottom
;    ld a,[$d74b]
;    bit 5,a ; does the player have the pokedex?
;    ld a,6-1 ; there are 7 menu items with the pokedex,so the max index is 6
;    jr nz,.wrapMenuItemId
;    dec a ; there are only 6 menu items without the pokedex
;.wrapMenuItemId
    ld a,4
    ld [wCurrentMenuItem],a
    call EraseMenuCursor
    jr .loop
.checkIfDownPressed
    bit 7,a
    jr z,.buttonPressed
; if the player pressed tried to go past the bottom item,wrap around to the top
;    ld a,[$d74b]
;    bit 5,a ; does the player have the pokedex?
;    ld a,[wCurrentMenuItem]
;    ld c,7-1 ; there are 7 menu items with the pokedex
;    jr nz,.checkIfPastBottom
;    dec c ; there are only 6 menu items without the pokedex
;.checkIfPastBottom
;    cp c
    ld a,[wCurrentMenuItem]
    cp 5
    jr nz,.loop
; the player went past the bottom,so wrap to the top
    xor a
    ld [wCurrentMenuItem],a
    call EraseMenuCursor
    jr .loop
.buttonPressed ; A,B,or Start button pressed
    call PlaceUnfilledArrowMenuCursor
    ld a,[wCurrentMenuItem]
    ld [wBattleAndStartSavedMenuItem],a ; save current menu item ID
    ld a,b
    and a,%00001010 ; was the Start button or B button pressed?
    jp nz,CloseStartMenu
    call SaveScreenTilesToBuffer2 ; copy background from wTileMap to wTileMapBackup2
;    ld a,[$d74b]
;    bit 5,a ; does the player have the pokedex?
;    ld a,[wCurrentMenuItem]
;    jr nz,.displayMenuItem
;    inc a ; adjust position to account for missing pokedex menu item
;.displayMenuItem
;    cp 0
;    jp z,StartMenu_Pokedex
;    cp 1
;    jp z,StartMenu_Pokemon
;    cp 2
;    jp z,StartMenu_Item
;    cp 3
;    jp z,StartMenu_TrainerInfo
;    cp 4
;    jp z,StartMenu_SaveReset
;    cp 5
;    jp z,StartMenu_Option
    ld a,[wCurrentMenuItem]
    and a
    jp z,StartMenu_Pokemon
    dec a
    jp z,StartMenu_Item
    dec a
    jp z,StartMenu_TrainerInfo
    dec a
    jp z,StartMenu_SaveReset
    jp StartMenu_Option

CloseStartMenu:
    call GetJoypadState
    ld a,[H_NEWLYPRESSEDBUTTONS]
    bit 0,a ; was A button newly pressed?
    jr nz,CloseStartMenu
    call LoadTextBoxTilePatterns
    jp CloseTextDisplay

; function to count how many bits are set in a string of bytes
; INPUT:
; hl = address of string of bytes
; b = length of string of bytes
; OUTPUT:
; [$D11E] = number of set bits
CountSetBits:
    ld c,0
.loop
    ld a,[hli]
    ld e,a
    ld d,8
.innerLoop ; count how many bits are set in the current byte
    srl e
    ld a,0
    adc c
    ld c,a
    dec d
    jr nz,.innerLoop
    dec b
    jr nz,.loop
    ld a,c
    ld [$d11e],a ; store number of set bits
    ret

; subtracts the amount the player paid from their money
; sets carry flag if there is enough money and unsets carry flag if not
SubtractAmountPaidFromMoney:
    BANKSWITCH_JUMP SubtractAmountPaidFromMoney_

; adds the amount the player sold to their money
AddAmountSoldToMoney:
    ld de,wPlayerMoney + 2
    ld hl,$ffa1 ; total price of items
    ld c,3 ; length of money in bytes
    PREDEF Func_f81d ; add total price to money
    ld a,$13
    ld [$d125],a
    call DisplayTextBoxID ; redraw money text box
    ld a,(SFX_02_5a - $4000) / 3
    call PlaySoundWaitForCurrent ; play sound
    jp WaitForSoundToFinish ; wait until sound is done playing

; function to remove an item (in varying quantities) from the player's bag or PC box
; INPUT:
; HL = address of inventory (either wNumBagItems or wNumBoxItems)
; [$CF92] = index (within the inventory) of the item to remove
; [$CF96] = quantity to remove
RemoveItemFromInventory:
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,BANK(RemoveItemFromInventory_)
    call RoutineForRealGB
    call RemoveItemFromInventory_
    pop af
    jp RoutineForRealGB

; function to add an item (in varying quantities) to the player's bag or PC box
; INPUT:
; HL = address of inventory (either wNumBagItems or wNumBoxItems)
; [$CF91] = item ID
; [$CF96] = item quantity
; sets carry flag if successful,unsets carry flag if unsuccessful
AddItemToInventory:
    push bc
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,BANK(AddItemToInventory_)
    call RoutineForRealGB
    call AddItemToInventory_
    pop bc
    ld a,b
    call RoutineForRealGB
    pop bc
    ret

; Output : a = [$ffb5]
;      z set = Can Continue
;    z reset = Must Wait
GetJoypadStateLowSensitivityWaitReleaseJoy:
    call GetJoypadStateLowSensitivity
    ld hl,wWaitReleaseJoyBit5
    bit 5,[hl]
    jr z,.end
    ld a,[H_CURRENTPRESSEDBUTTONS]
    and a
    jr nz,.end
    res 5,[hl]
.end
    ld a,[$ffb5]
    ret

; Free

SECTION "DisplayListMenuID",ROM0[$2be6] ; cannot be moved cause "HackItemInBattle"

; INPUT:
; [wListMenuID] = list menu ID
; [$cf8b] = address of the list (2 bytes)
DisplayListMenuID: ; 2be6 (0:2be6)
    xor a
    ld [H_AUTOBGTRANSFERENABLED],a ; disable auto-transfer
    inc a ; a = 1
    ld [$ffb7],a ; joypad state update flag
    ld a,[W_BATTLETYPE]
    and a ; is it the Old Man battle?
    jr nz,.specialBattleType
    ld a,$01
    jr .bankswitch
.specialBattleType ; Old Man battle
    ld a,$0f
.bankswitch
    call BankswitchHome
    ld hl,$d730
    set 6,[hl] ; turn off letter printing delay
    xor a
    ld [$cc35],a ; 0 means no item is currently being swapped
    ld a,[$cf8b]
    ld l,a
    ld a,[$cf8c]
    ld h,a ; hl = address of the list
    ld a,[hl]
    and a
    jp z,ExitListMenu
    ld [$d12a],a ; [$d12a] = number of list entries
    push af ; Backup number of list entries
    ld a,$0d ; list menu text box ID
    call HackItemInBattle ; ld [$d125],a ; $2c17
    call DisplayTextBoxID ; draw the menu text box
    call UpdateSprites ; move sprites
    FuncCoord 4,2 ; coordinates of upper left corner of menu text box
    call HackItemInBattle ; ld hl,Coord ; $2c20
    ld de,$090e ; height and width of menu text box
    ld a,[wListMenuID]
    and a ; is it a PC pokemon list?
    jr nz,.skipMovingSprites
    call UpdateSprites ; move sprites
.skipMovingSprites
    ld a,1 ; max menu item ID is 1 if the list has less than 2 entries
    ld [$cc37],a
    pop af ; Restore number of list entries
    dec a
    cp 2 ; does the list have less than 2 entries?
    jr c,.setMenuVariables
    ld a,2 ; max menu item ID is 2 if the list has at least 2 entries
.setMenuVariables
    ld [wMaxMenuItem],a
    ld a,4
    call HackItemInBattle ; ld [wTopMenuItemY],a ; $2c41
    ld a,5
    ld [wTopMenuItemX],a
    ld a,%11110111 ; ▼▲◄►StSeBA
    ld [wMenuWatchedKeys],a
    ld c,10
    call DelayFramesAndSetWaitReleaseJoyFlag ; call DelayFrames
    ; ft

DisplayListMenuIDLoop:
    xor a
    ld [H_AUTOBGTRANSFERENABLED],a ; disable transfer
    call PrintListMenuEntries
    ld a,1
    ld [H_AUTOBGTRANSFERENABLED],a ; enable transfer
    call Delay3
    ld a,[W_BATTLETYPE]
    and a ; is it the Old Man battle?
    jr z,.notOldManBattle
.oldManBattle
    ld a,"▶"
    FuncCoord 5,9
    ld [Coord],a ; place menu cursor in front of first menu entry
    ld c,80
    call DelayFrames
    xor a
    ld [wCurrentMenuItem],a
    ld hl,Coord
    ld a,l
    ld [wMenuCursorLocation],a
    ld a,h
    ld [wMenuCursorLocation + 1],a
    jr .buttonAPressed
.notOldManBattle
    ld hl,wTestWrapInMenuInputBit6
    set 6,[hl]
    call LoadGBPal
    call HandleMenuInput
    push af
    call PlaceMenuCursor
    pop af
    bit 0,a ; was the A button pressed?
    jp z,ListMenu_CheckOtherKeys

.buttonAPressed
    ld a,[wCurrentMenuItem]
    call PlaceUnfilledArrowMenuCursor
    ld a,$01
    ld [$d12e],a
    ld [$d12d],a
    xor a
    ld [$cc37],a
    ld a,[wCurrentMenuItem]
    ld c,a
    ld a,[wListScrollOffset]
    add c
    ld c,a
    ld a,[$d12a] ; number of list entries
    and a ; is the list empty?
    jp z,ExitListMenu ; if so,exit the menu
    dec a
    cp c ; did the player select Cancel?
    jp c,ExitListMenu ; if so,exit the menu
    ld a,c
    ld [$cf92],a
    ld a,[wListMenuID]
    cp ITEMLISTMENU
    jr nz,.skipMultiplying
; if it's an item menu
    sla c ; item entries are 2 bytes long,so multiply by 2
.skipMultiplying
    ld a,[$cf8b]
    ld l,a
    ld a,[$cf8c]
    ld h,a
    inc hl ; hl = beginning of list entries
    ld b,0
    add hl,bc
    ld a,[hl]
    ld [$cf91],a
    ld a,[wListMenuID]
    and a ; is it a PC pokemon list?
    jr z,.pokemonList
    push hl
    call GetItemPrice
    pop hl
    ld a,[wListMenuID]
    cp ITEMLISTMENU
    jr nz,.skipGettingQuantity
; if it's an item menu
    inc hl
    ld a,[hl] ; a = item quantity
    ld [$cf97],a
.skipGettingQuantity
    ld a,[$cf91]
    ld [$d0b5],a
    ld a,BANK(ItemNames) ; Denim,spostata tabella ItemNames in un altro BANK
    ld [$d0b7],a
    call GetName
    jr .storeChosenEntry
.pokemonList
    ld hl,W_NUMINPARTY
    ld a,[$cf8b]
    cp l ; is it a list of party pokemon or box pokemon?
    ld hl,W_PARTYMON1NAME
    jr z,.getPokemonName
    ld hl,$de06 ; box pokemon names
.getPokemonName
    ld a,[$cf92]
    call GetPartyMonName
.storeChosenEntry ; store the menu entry that the player chose and return
    ld de,$cd6d
    call CopyStringToCF4B ; copy name to $cf4b
    ld a,$01
    ld [$d12e],a
    ; ft

ResetListMenuEnv:
    ld hl,wTestWrapInMenuInputBit6
    res 6,[hl]
    ld a,[wCurrentMenuItem]
    ld [$d12d],a
    xor a
    ld [$ffb7],a ; joypad state update flag
    ld hl,$d730
    res 6,[hl] ; turn on letter printing delay
    jp BankswitchBack

ListMenu_CheckOtherKeys: ; check B,SELECT,Up,and Down keys
    bit 1,a ; was the B button pressed?
    jp nz,ExitListMenu ; if so,exit the menu
    bit 2,a ; was the select button pressed?
    jp nz,HandleItemListSwapping ; if so,allow the player to swap menu entries

    ; ▼▲◄►
    ld hl,wListScrollOffset
    ld de,DisplayListMenuIDLoop
    push de ; Return Pointer
    bit 5,a
    jr nz,.LeftPressed
    bit 4,a
    jr nz,.RightPressed
    call TestWrapInMenuInput ; Run Up/Down Code Only if MenuInput Try
    ret nz                    ; to Wrap (like in original Code)
    bit 6,a ; was Down pressed?
    jr nz,.UpPressed
.DownPressed
    ld a,[hl]
    add 3 + 1
    ld b,a
    ld a,[$d12a] ; number of list entries
    cp b ; will going down scroll past the Cancel button?
    jp c,GoToTop
    inc [hl] ; if not,go down
    ret
.UpPressed
    ld a,[hl]
    and a
    jp z,GoToBottom
    dec [hl]
    ret
.LeftPressed
    ld a,[hl]
    sub 3
    jp c,GoToTop2
    ld [hl],a
    ret
.RightPressed
    ld a,[hl]
    add 3 + 3
    ld b,a
    ld a,[$d12a] ; number of list entries
    cp b ; will going down scroll past the Cancel button?
    jp c,GoToBottom2
    inc [hl]
    inc [hl]
    inc [hl]
    ret

DisplayChooseQuantityMenu:
; text box dimensions/coordinates for just quantity

    ld a,1
    ld [$ffb7],a ; Set Quick Menu

    BANKSWITCH InitializeChooseQuantityMenu

    ld c,1
    jr .incrementQuantity

.waitForKeyPressLoop
    call GetJoypadStateLowSensitivityWaitReleaseJoy ; ▼▲◄►StSeBA
    jr nz,.waitForKeyPressLoop
    bit 0,a ; was the A button pressed?
    jp nz,QtyMenu_buttonAPressed
    bit 1,a ; was the B button pressed?
    jp nz,QtyMenu_buttonBPressed
    ld b,a
    ld a,[$ff8e]
    and a ; should the price be halved (for selling items)?
    jr nz,.CheckUpDownLeftRight
    ld a,[wListMenuID]
    cp PRICEDITEMLISTMENU
    jr nz,.CheckUpDownLeftRight
    ld a,[$cf91] ; selected item ID
    cp TM_01
    jr c,.CheckUpDownLeftRight
    jr .waitForKeyPressLoop

.CheckUpDownLeftRight
    ld a,b
    ld c,1
    bit 6,a ; was Up pressed?
    jr nz,.incrementQuantity
    bit 7,a ; was Down pressed?
    jr nz,.decrementQuantity
    ld c,10
    bit 4,a ; was Right pressed?
    jr nz,.incrementQuantity
    bit 5,a ; was Left pressed?
    jr nz,.decrementQuantity
    jr .waitForKeyPressLoop

.incrementQuantity
    ld a,[$cf97] ; max quantity
    inc a
    ld b,a
    ld hl,$cf96 ; current quantity
    ld a,[hl]
    add c
    jr c,.wrapToMax
    cp b
    jr c,.handleNewQuantity
    jr .wrapToMax

.decrementQuantity
    ld hl,$cf96 ; current quantity
    ld a,[hl]
    sub c
    jr c,.wrapTo1
    jr nz,.handleNewQuantity
    ; ft

.wrapTo1
    ld a,[hl] ; current quantity
    dec a
    jr nz,.wrapTo1Skip
    ld a,[H_NEWLYPRESSEDBUTTONS] ; No Infinite Loop
    and a                        ; ...
    jr nz,.wrapToMaxSkip         ; ...
.wrapTo1Skip
    ld a,1
    jr .handleNewQuantity

.wrapToMax
    ld a,[hl] ; current quantity
    dec b
    cp b
    jr nz,.wrapToMaxSkip
    ld a,[H_NEWLYPRESSEDBUTTONS] ; No Infinite Loop
    and a                        ; ...
    jr nz,.wrapTo1Skip           ; ...
.wrapToMaxSkip
    ld a,[$cf97] ; max quantity
    ; ft

.handleNewQuantity
    ld [hl],a
    FuncCoord 16,10
    ld hl,Coord
    ld a,[wListMenuID]
    cp PRICEDITEMLISTMENU
    jr nz,.printQuantity
    BANKSWITCH PrintPrice
    FuncCoord 08,10
    ld hl,Coord
.printQuantity
    ld de,$cf96 ; current quantity
    ld bc,((%10000000|01)<<8|03) ; print leading zeroes,1 byte,3 digits
    call PrintNumber
    jp .waitForKeyPressLoop

; Free

SECTION "PrintListMenuEntries",ROM0[$2e5a] ; cannot be moved cause "HackItemInBattle"

PrintListMenuEntries: ; 2e5a (0:2e5a)
    FuncCoord 5,3 ; $c3e1
    call HackItemInBattle ; ld hl,Coord ; $2e5a
    ld b,$09
    ld c,$0e
    call ClearScreenArea
    ld a,[$cf8b]
    ld e,a
    ld a,[$cf8c]
    ld d,a
    inc de ; de = beginning of list entries
    ld a,[wListScrollOffset]
    ld c,a
    ld a,[wListMenuID]
    cp ITEMLISTMENU
    ld a,c
    jr nz,.skipMultiplying
; if it's an item menu
; item entries are 2 bytes long,so multiply by 2
    sla a
    sla c
.skipMultiplying
    add e
    ld e,a
    jr nc,.noCarry
    inc d
.noCarry
    FuncCoord 6,4 ; coordinates of first list entry name
    call HackItemInBattle ; ld hl,Coord ; $2e82
    ld b,4 ; print 4 names
.loop
    ld a,b
    ld [$cf92],a
    ld a,[de]
    ld [$d11e],a
    cp $ff
    jp z,.end
    push bc
    push de
    push hl
    push hl
    push de
    ld a,[wListMenuID]
    and a
    jr z,.pokemonPCMenu
    cp $01
    jr z,.movesMenu
.itemMenu
    call BackupHlAndGetSpecialListNameOrGetItemName ; Denim ; call GetItemName
    jr .placeNameString
.pokemonPCMenu
    push hl
    ld hl,W_NUMINPARTY
    ld a,[$cf8b]
    cp l ; is it a list of party pokemon or box pokemon?
    ld hl,W_PARTYMON1NAME
    jr z,.getPokemonName
    ld hl,$de06 ; box pokemon names
.getPokemonName
    ld a,[$cf92]
    ld b,a
    ld a,4
    sub b
    ld b,a
    ld a,[wListScrollOffset]
    add b
    call GetPartyMonName
    pop hl
    jr .placeNameString
.movesMenu
    call GetMoveName
.placeNameString
    call PlaceString
    pop de
    pop hl
    ld a,[$cf93]
    and a ; should prices be printed?
    jr z,.skipPrintingItemPrice
.printItemPrice
    push hl
    ld a,[de]
    ld de,ItemPrices
    ld [$cf91],a
    call GetItemPrice ; get price
    pop hl
    ld bc,20 + 5 ; 1 row down and 5 columns right
    add hl,bc
    ld c,$a3 ; no leading zeroes,right-aligned,print currency symbol,3 bytes
    call PrintBCDNumber
.skipPrintingItemPrice
    ld a,[wListMenuID]
    and a
    jr nz,.skipPrintingPokemonLevel
.printPokemonLevel
    ld a,[$d11e]
    push af
    push hl
    ld hl,W_NUMINPARTY
    ld a,[$cf8b]
    cp l ; is it a list of party pokemon or box pokemon?
    ld a,$00
    jr z,.next
    ld a,$02
.next
    ld [$cc49],a
    ld hl,$cf92
    ld a,[hl]
    ld b,a
    ld a,$04
    sub b
    ld b,a
    ld a,[wListScrollOffset]
    add b
    ld [hl],a
    call LoadMonData ; load pokemon info
    ld a,[$cc49]
    and a ; is it a list of party pokemon or box pokemon?
    jr z,.skipCopyingLevel
.copyLevel
    ld a,[$cf9b]
    ld [$cfb9],a
.skipCopyingLevel
    pop hl
    ld bc,$001c
    add hl,bc
    call PrintLevel ; print level
    pop af
    ld [$d11e],a
.skipPrintingPokemonLevel
    pop hl
    pop de
    inc de
    ld a,[wListMenuID]
    cp ITEMLISTMENU
    jr nz,.nextListEntry
.printItemQuantity
    ld a,[$d11e]
    ld [$cf91],a
    call IsKeyItem ; check if item is unsellable
    ld a,[$d124]
    and a ; is the item unsellable?
    jr nz,.skipPrintingItemQuantity ; if so,don't print the quantity
    push hl
    ld bc,20 + 7 ; 1 row down and 7 columns right
    add hl,bc
    ld a,"×"
    ldi [hl],a
    ld a,[$d11e]
    push af
    ld a,[de]
    ld [$cf97],a
    push de
    ld de,$d11e
    ld [de],a
    ld bc,(01<<8|03)
    call PrintNumber
    pop de
    pop af
    ld [$d11e],a
    pop hl
.skipPrintingItemQuantity
    inc de
    pop bc
    inc c
    push bc
    inc c
    ld a,[$cc35] ; ID of item chosen for swapping (counts from 1)
    and a ; is an item being swapped?
    jr z,.nextListEntry
    sla a
    cp c ; is it this item?
    jr nz,.nextListEntry
    dec hl
    ld a,$ec ; unfilled right arrow menu cursor to indicate an item being swapped
    ld [hli],a
.nextListEntry
    ld bc,2 * 20 ; 2 rows
    add hl,bc
    pop bc
    inc c
    dec b
    jp nz,.loop
    ld bc,-8
    add hl,bc
    ld a,$ee ; down arrow
    ld [hl],a
.end
    BANKSWITCH PrintMenuQty
    ; ft

GetMonName:
    push hl
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,BANK(MonsterNames) ; 07
    call RoutineForRealGB
    call IndexToPokedexAndRestoreD11E
    ld hl,MonsterNames ; 421E
    ld c,10
    ld b,0
    call AddNTimes
    ld de,$cd6d
    push de
    ld bc,10
    call CopyData
    ld hl,$cd77
    ld [hl],"@"
    pop de
    pop af
    call RoutineForRealGB
    pop hl
    ret

GetItemName:
; given an item ID at [$D11E],store the name of the item into a string
; starting at $CD6D
    push hl
    push bc
    ld a,[$D11E]
    ld [$D0B5],a
    ld a,ITEM_NAME
    ld [W_LISTTYPE],a
    ld a,BANK(ItemNames)
    ld [$D0B7],a
    call GetName
    ld de,$CD6D ; pointer to where item name is stored in RAM
    pop bc
    pop hl
    ret

GetMoveName:
    push hl
    ld a,MOVE_NAME
    ld [W_LISTTYPE],a
    ld a,[$d11e]
    ld [$d0b5],a
    ld a,BANK(MoveNames)
    ld [$d0b7],a
    call GetName
    ld de,$cd6d ; pointer to where move name is stored in RAM
    pop hl
    ret

IsSpriteInFrontOfPlayer3:
    ld a,[$d52a] ; the direction that the player is trying to go in
    ld d,a
    ld a,[$c10c] ; the player sprite's collision data (bit field) (set in the sprite movement code)
    and d ; check if a sprite is in the direction the player is trying to go
    ret nz ; nz = collison
    ; ft

IsSpriteInFrontOfPlayer4:
    xor a
    ld [$ff8c],a
    call IsSpriteInFrontOfPlayer ; check for sprite collisions again? when does the above check fail to detect a sprite collision?
    ld a,[$ff8c]
    and a ; was there a sprite collision?
    ret ; nz = collison

IsSkill:
    push bc
    push af
    push de
    push hl
    ld hl,.SkillTable
    ld de,1
    call IsInArray
    jr c,.Found
.NotFound
    xor a ; rcf
    jr .IsSkill_End
.Found
    scf
.IsSkill_End
    pop hl
    pop de
    pop bc
    ld a,b
    pop bc
    ret
.SkillTable
    db Skill__FLY
    db Skill__DIG
    db Skill__CUT
    db Skill__FLOAT
    db Skill__STRENGTH
    db Skill__LIGHT
    db Skill__HEAL
    db $FF

SECTION "OverworldHackRoutine",ROM0[$3040]

OverworldHackRoutine:
    call HackFromBank0 ; $3040 ; _OverworldHackRoutine
    ret                ; $3043

RestoreFaintenedWith1HP:
    call HackFromBank0 ; $3044 ; _RestoreFaintenedWith1HP
    ret                ; $3047

BugFixWarpDuringJump:
    call HackFromBank0 ; $3048 ; _BugFixWarpDuringJump
    ret                ; $304b

; reloads text box tile patterns,current map view,and tileset tile patterns
ReloadMapData:
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,[W_CURMAP]
    call SwitchToMapRomBank
    call DisableLCD
    call LoadTextBoxTilePatterns
    call LoadCurrentMapView
    call LoadTilesetTilePatternData
    call EnableLCD
    pop af
    jp RoutineForRealGB

; reloads tileset tile patterns
ReloadTilesetTilePatterns:
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,[W_CURMAP]
    call SwitchToMapRomBank
    call DisableLCD
    call LoadTilesetTilePatternData
    call EnableLCD
    pop af
    jp RoutineForRealGB

; shows the town map and lets the player choose a destination to fly to
ChooseFlyDestination:
    ld hl,$d72e
    res 4,[hl]
    BANKSWITCH_JUMP _ChooseFlyDestination

; causes the text box to close waithout waiting for a button press after displaying text
DisableWaitingAfterTextDisplay:
    ld a,$01
    ld [$cc3c],a
    ret

; uses an item
; UseItem is used with dummy items to perform certain other functions as well
; INPUT:
; [$cf91] = item ID
; OUTPUT:
; [$cd6a] = success
; 00: unsucessful
; 01: successful
; 02: not able to be used right now,no extra menu displayed (only certain items use this)
UseItem:
    BANKSWITCH_JUMP UseItem_

; confirms the item toss and then tosses the item
; INPUT:
; hl = address of inventory (either wNumBagItems or wNumBoxItems)
; [$cf91] = item ID
; [$cf92] = index of item within inventory
; [$cf96] = quantity to toss
; OUTPUT:
; clears carry flag if the item is tossed,sets carry flag if not
TossItem:
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,BANK(TossItem_)
