SECTION "StoreTrainerHeaderPointer",ROM0[$3157]

; stores hl in [W_TRAINERHEADERPTR]
StoreTrainerHeaderPointer: ; 3157 (0:3157)
    ld a,h
    ld [W_TRAINERHEADERPTR],a
    ld a,l
    ld [W_TRAINERHEADERPTR+1],a
    ret

; executes the current map script from the function pointer array provided in hl.
; a: map script index to execute (unless overridden by [$d733] bit 4)
ExecuteCurMapScriptInTable: ; 3160 (0:3160)
    push af
    push de
    call StoreTrainerHeaderPointer
    pop hl
    pop af
    push hl
    ld hl,W_FLAGS_D733
    bit 4,[hl]
    res 4,[hl]
    jr z,.useProvidedIndex   ; test if map script index was overridden manually
    ld a,[W_CURMAPSCRIPT]
.useProvidedIndex
    pop hl
    ld [W_CURMAPSCRIPT],a
    call CallFunctionInTable
    ld a,[W_CURMAPSCRIPT]
    ret

LoadGymLeaderAndCityName: ; 317f (0:317f)
    push de
    ld de,wGymCityName
    ld bc,$11
    call CopyData   ; load city name
    pop hl
    ld de,wGymLeaderName
    ld bc,$b
    jp CopyData     ; load gym leader name

; reads specific information from trainer header (pointed to at W_TRAINERHEADERPTR)
; a: offset in header data
;    0 -> flag's bit (into wTrainerHeaderFlagBit)
;    2 -> flag's byte ptr (into hl)
;    4 -> before battle text (into hl)
;    6 -> after battle text (into hl)
;    8 -> end battle text (into hl)
ReadTrainerHeaderInfo: ; 3193 (0:3193)
    push de
    push af
    ld d,$0
    ld e,a
    ld hl,W_TRAINERHEADERPTR
    ld a,[hli]
    ld l,[hl]
    ld h,a
    add hl,de
    pop af
    and a
    jr nz,.nonZeroOffset
    ld a,[hl]
    ld [wTrainerHeaderFlagBit],a  ; store flag's bit
    jr .done
.nonZeroOffset
    cp $2
    jr z,.readPointer ; read flag's byte ptr
    cp $4
    jr z,.readPointer ; read before battle text
    cp $6
    jr z,.readPointer ; read after battle text
    cp $8
    jr z,.readPointer ; read end battle text
    cp $a
    jr nz,.done
    ld a,[hli]        ; read end battle text (2) but override the result afterwards (XXX why,bug?)
    ld d,[hl]
    ld e,a
    jr .done
.readPointer
    ld a,[hli]
    ld h,[hl]
    ld l,a
.done
    pop de
    ret

; calls HandleBitArray
HandleBitArray_Bank0: ; 31c7 (0:31c7)
    PREDEF_JUMP HandleBitArray

; direct talking to a trainer (rather than getting seen by one)
TalkToTrainer: ; 31cc (0:31cc)
    call StoreTrainerHeaderPointer
    xor a
    call ReadTrainerHeaderInfo     ; read flag's bit
    ld a,$2
    call ReadTrainerHeaderInfo     ; read flag's byte ptr
    ld a,[wTrainerHeaderFlagBit]
    ld c,a
    ld b,$2
    call HandleBitArray_Bank0      ; read trainer's flag
    ld a,c
    and a
    jr z,.trainerNotYetFought     ; test trainer's flag
    ld a,$6
    call ReadTrainerHeaderInfo     ; print after battle text
    jp PrintText
.trainerNotYetFought ; 0x31ed
    ld a,$4
    call ReadTrainerHeaderInfo     ; print before battle text
    call PrintText
    ld a,$a
    call ReadTrainerHeaderInfo     ; (?) does nothing apparently (maybe bug in ReadTrainerHeaderInfo)
    push de
    ld a,$8
    call ReadTrainerHeaderInfo     ; read end battle text
    pop de
    call PreBattleSaveRegisters
    ld hl,W_FLAGS_D733
    set 4,[hl]                    ; activate map script index override (index is set below)
    ld hl,wFlags_0xcd60
    bit 0,[hl]                    ; test if player is already being engaged by another trainer
    ret nz
    call EngageMapTrainer
    ld hl,W_CURMAPSCRIPT
    inc [hl]      ; progress map script index (assuming it was 0 before) to start pre-battle routines
    jp Func_325d

; checks if any trainers are seeing the player and wanting to fight
CheckFightingMapTrainers: ; 3219 (0:3219)
    call CheckForEngagingTrainers_NoDuringPushingBounder
    ld a,[$cf13]
    cp $ff
    jr nz,.trainerEngaging
    xor a
    ld [$cf13],a
    ld [wTrainerHeaderFlagBit],a
    ret
.trainerEngaging
    ld hl,W_FLAGS_D733
    set 3,[hl]
    ld [$cd4f],a
    xor a
    ld [$cd50],a
    PREDEF EmotionBubble
    ld a,BTN_RIGHT | BTN_LEFT | BTN_UP | BTN_DOWN
    ld [wJoypadForbiddenButtonsMask],a
    xor a
    ldh [$b4],a
    call TrainerWalkUpToPlayer_Bank0
    ld hl,W_CURMAPSCRIPT
    inc [hl]      ; progress to battle phase 1 (engaging)
    ret

DisplayEnemyTrainerTextAndStartBattle: ; 324c (0:324c)
    ld a,[$d730]
    and $1
    ret nz
    ld [wJoypadForbiddenButtonsMask],a
    ld a,[$cf13]
    ld [H_DOWNARROWBLINKCNT2],a ; $FF00+$8c
    call DisplayTextID

Func_325d: ; 325d (0:325d)
    xor a
    ld [wJoypadForbiddenButtonsMask],a
    call InitBattleEnemyParameters
    ld hl,$d72d
    set 6,[hl]
    set 7,[hl]
    ld hl,$d72e
    set 1,[hl]
    ld hl,W_CURMAPSCRIPT
    inc [hl]        ; progress to battle phase 2 (battling)
    ret

EndTrainerBattle: ; 3275 (0:3275)
    ld hl,$d126
    set 5,[hl]
    set 6,[hl]
    ld hl,$d72d
    res 7,[hl]
    ld hl,wFlags_0xcd60
    res 0,[hl]                  ; player is no longer engaged by any trainer
    ld a,[W_ISINBATTLE] ; $d057
    cp $ff
    jp z,ResetButtonPressedAndMapScript
    ld a,$2
    call ReadTrainerHeaderInfo
    ld a,[wTrainerHeaderFlagBit]
    ld c,a
    ld b,$1
    call HandleBitArray_Bank0   ; flag trainer as fought
    ld hl,W_TRAINERNO
    ld a,[hl]
    and a
    ld a,0
    ld [hl],a
    jr nz,.skipRemoveSprite    ; test if trainer was fought (in that case skip removing the corresponding sprite)
    ld hl,W_MISSABLEOBJECTLIST
    ld de,$2
    ld a,[$cf13]
    call IsInArray              ; search for sprite ID
    inc hl
    ld a,[hl]
    ld [$cc4d],a               ; load corresponding missable object index and remove it
    PREDEF RemoveMissableObject
.skipRemoveSprite
    ld hl,$d730
    bit 4,[hl]
    res 4,[hl]
    ret nz
    jp ResetButtonPressedAndMapScript

SpeedUp:
    ld a,[$d700] ; if 0 -> walk,if 1 -> byke
    and a
    jr z,TrySpeedUpWithB ; if walk
    dec a
    jp z,SpeedUpByke
;SpeedUpSurf
    call IsSurfingOnLapras
    ret nz
    call TrySpeedUpWithB
    ret z
    call TrySpeedUpWithA
    ; ft

TrySpeedUpWithA:
    ld a,[H_CURRENTPRESSEDBUTTONS] ; current joypad state
    and a,%00000001 ; bit mask for A
    jr TrySpeedUpCommon
TrySpeedUpWithB:
    ld a,[H_CURRENTPRESSEDBUTTONS] ; current joypad state
    and a,%00000010 ; bit mask for B
TrySpeedUpCommon:
    ret z
    push af
    call AdvancePlayerSprite ; Speed 2X
    pop af
    ret

