    ld [$d12c],a
    FuncCoord 14,7 ; $c43a
    ld hl,Coord
    ld bc,$80f
    ret

YesNoChoicePokeCenter:
    call SaveScreenTilesToBuffer1
    ld a,$6
    ld [$d12c],a
    FuncCoord 11,6 ; $c423
    ld hl,Coord
    ld bc,$80c
    ; ft

DisplayYesNoChoice:
    ld a,$14
