; calculates the difference |a-b|,setting carry flag if a<b
CalcDifference:
    sub b
    ret nc
    cpl
    add $1
    scf
    ret

MoveSprite:
; move the sprite [$FF8C] with the movement pointed to by de
; actually only copies the movement data to $CC5B for later
    call SetSpriteMovementBytesToFF
    ; ft

MoveSprite_:
    push hl
    push bc
    call GetSpriteMovementByte1Pointer
    xor a
    ld [hl],a
    ld hl,$CC5B
    ld c,0

.loop
    ld a,[de]
    ld [hli],a
    inc de
    inc c
    cp $FF ; have we reached the end of the movement data?
    jr nz,.loop

    ld a,c
    ld [$CF0F],a ; number of steps taken

    pop bc
    ld hl,$D730
    set 0,[hl]
    pop hl
    xor a
    ld [$CD3B],a
    ld [$CCD3],a
    dec a
    ld [wJoypadForbiddenButtonsMask],a
    ld [$CD3A],a
    ret

; divides [hDividend2] by [hDivisor2] and stores the quotient in [hQuotient2]
DivideBytes:
    push hl
    ld hl,$ffe7 ; hQuotient2
    xor a
    ld [hld],a
    ld a,[hld]
    and a
    jr z,.done
    ld a,[hli]
.loop
    sub [hl]
    jr c,.done
    inc hl
    inc [hl]
    dec hl
    jr .loop
.done
    pop hl
    ret

SpeedUpByke:
    call GetCurrentOldAdventureMap
    cp ROUTE_17 ; Cycling Road
    jr nz,.normalByke
    ld a,[H_CURRENTPRESSEDBUTTONS] ; current joypad state
    and a,%01110000 ; bit mask for up,left,right buttons
    jr nz,.TrySpeedUpWithB
.normalByke
    call AdvancePlayerSprite ; Speed 2X
    call TrySpeedUpWithB     ; Speed 3X
.TrySpeedUpWithB
    jp TrySpeedUpWithB       ; Speed 4X

TestWrapInMenuInput:
    push hl
    ld hl,wTestWrapInMenuInputBit6
    bit 6,[hl]
    pop hl
    ret

ChangeCurMap:
    ld [W_CURMAP],a
    ret

