    BANKSWITCH_JUMP LoadHpBarAndStatusTilePatterns_

; Output -> a
HackFromBank0:
    push bc
    push de
    push hl
    ld hl,sp+6
    ld a,[hli]
    ld d,a ; Input
    ld a,[hl]
    ld e,a ; Input
    BANKSWITCH _HackFromBank0
    ld a,d ; Output
    pop hl
    pop de
    pop bc
    ret

;Fills memory range with the specified byte.
;input registers a = fill_byte,bc = length,hl = address
FillMemory:
    push de
    ld d,a
.loop
    ld a,d
    ldi [hl],a
    dec bc
    ld a,b
    or c
    jr nz,.loop
    pop de
    ret

; loads sprite that de points to
UncompressSpriteFromDE:
    ld hl,W_SPRITEINPUTPTR
    ld [hl],e
    inc hl
    ld [hl],d
    jp UncompressSpriteData

