GetName: ; 376b (0:376b)
; arguments:
; [$D0B5] = which name
; [$D0B6] = which list (W_LISTTYPE)
; [$D0B7] = bank of list
;
; returns pointer to name in de
    ld a,[$d0b5]
    ld [$d11e],a
    ld a,[H_LOADEDROMBANK]
    push af
    push hl
    push bc
    push de
    ld a,[W_LISTTYPE]    ;List3759_entrySelector
    dec a
    jr nz,.otherEntries
    ;1 = MON_NAMES
    call GetMonName
    ld hl,11
    add hl,de
    ld e,l
    ld d,h
    jr .gotPtr
.otherEntries ; $378d
    ;2-7 = OTHER ENTRIES
    ld a,[$d0b7]
    call RoutineForRealGB
    ld a,[W_LISTTYPE]    ;VariousNames' entryID
    dec a
    add a
    ld d,0
    ld e,a
    jr nc,.skip
    inc d
.skip ; $37a0
    ld hl,NamePointers
    add hl,de
    ld a,[hli]
    ld [$ff96],a
    ld a,[hl]
    ld [$ff95],a
    ld a,[$ff95]
    ld h,a
    ld a,[$ff96]
    ld l,a
    ld a,[$d0b5]
    ld b,a
    ld c,0
.nextName
    ld d,h
    ld e,l
.nextChar
    ld a,[hli]
    cp "@"
    jr nz,.nextChar
    inc c           ;entry counter
    ld a,b          ;wanted entry
    cp c
    jr nz,.nextName
    ld h,d
    ld l,e
    ld de,$cd6d
    ld bc,$0014
    call CopyData
.gotPtr ; $37cd
    ld a,e
    ld [$cf8d],a
    ld a,d
    ld [$cf8e],a
    pop de
    pop bc
    pop hl
    pop af
    jp RoutineForRealGB

GetItemPrice:
