    jr nz,.asm_37ed
    ld a,$f
.asm_37ed
    call RoutineForRealGB
    ld hl,$cf8f
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ld a,[$cf91]
    cp TM_01
    jr nc,.asm_3812
    ld bc,$3
.asm_3802
