SECTION "PrintLetterDelay",ROM0[$38d3]

; This function is used to wait a short period after printing a letter to the
; screen unless the player presses the A/B button or the delay is turned off
; through the [$d730] or [$d358] flags.
PrintLetterDelay: ; 38d3 (0:38d3)
    ld a,[$d730]
    bit 6,a
    ret nz
    ld a,[$d358]
    bit 1,a
    ret z
    push hl
    push de
    push bc
    ld a,[$d358]
    bit 0,a
    jr z,.waitOneFrame
    ld a,[$d355]
    and a,$0f
    ld [H_FRAMECOUNTER],a
    jr .checkButtons
.waitOneFrame
    ld a,1
    ld [H_FRAMECOUNTER],a
.checkButtons
    call GetJoypadState
    ld a,[H_CURRENTPRESSEDBUTTONS]
.checkAButton
    bit 0,a ; is the A button pressed? ; Denim : Hack per non rallentare il testo premendo A o B
    jr nz,.done ; jr z,.checkBButton
    ;jr .endWait
.checkBButton
    bit 1,a ; is the B button pressed?
    jr nz,.done ; Add
    jr z,.buttonsNotPressed
.endWait
    call DelayFrame
    jr .done
.buttonsNotPressed ; if neither A nor B is pressed
    ld a,[H_FRAMECOUNTER]
    and a
    jr nz,.checkButtons
.done
    pop bc
    pop de
    pop hl
    ret

; Copies [hl,bc) to [de,bc - hl).
; In other words,the source data is from hl up to but not including bc,
; and the destination is de.
CopyDataUntil: ; 3913 (0:3913)
    ld a,[hli]
    ld [de],a
    inc de
    ld a,h
    cp b
    jr nz,CopyDataUntil
    ld a,l
    cp c
    jr nz,CopyDataUntil
    ret

