; calculates all 5 stats of current mon and writes them to [de]
CalcStats: ; 3936 (0:3936)
    ld c,$0
.statsLoop
    inc c
    call CalcStat
    ld a,[H_MULTIPLICAND+1]
    ld [de],a
    inc de
    ld a,[H_MULTIPLICAND+2]
    ld [de],a
    inc de
    ld a,c
    cp $5
