    jr nz,.loop
    ret

; Compare strings,c bytes in length,at de and hl.
; Often used to compare big endian numbers in battle calculations.
StringCmp:
    ld a,[de]
    cp [hl]
    ret nz
    inc de
    inc hl
    dec c
    jr nz,StringCmp
    ret

; INPUT:
; a = oam block index (each block is 4 oam entries)
; b = Y coordinate of upper left corner of sprite
; c = X coordinate of upper left corner of sprite
; de = base address of 4 tile number and attribute pairs
WriteOAMBlock:
    ld h,$c3
    swap a ; multiply by 16
    ld l,a
    call .writeOneEntry ; upper left
    push bc
    ld a,8
    add c
    ld c,a
    call .writeOneEntry ; upper right
    pop bc
    ld a,8
    add b
    ld b,a
    call .writeOneEntry ; lower left
    ld a,8
    add c
    ld c,a
                          ; lower right
.writeOneEntry
    ld [hl],b ; Y coordinate
    inc hl
    ld [hl],c ; X coordinate
    inc hl
    ld a,[de] ; tile number
    inc de
    ld [hli],a
    ld a,[de] ; attribute
    inc de
    ld [hli],a
    ret

HandleMenuInput:
    xor a
    ld [$d09b],a

HandleMenuInputPokemonSelection:
    ld a,[H_DOWNARROWBLINKCNT1]
    push af
    ld a,[H_DOWNARROWBLINKCNT2]
    push af ; save existing values on stack
    xor a
    ld [H_DOWNARROWBLINKCNT1],a ; blinking down arrow timing value 1
    ld a,$06
    ld [H_DOWNARROWBLINKCNT2],a ; blinking down arrow timing value 2
.loop1
    xor a
    ld [$d08b],a ; counter for pokemon shaking animation
    call PlaceMenuCursor
    call Delay3
.loop2
    ld a,[$d09b]
    and a ; is it a pokemon selection menu?
    jr z,.getJoypadState
    push hl
    BANKSWITCH ShakeMiniSprite ; shake mini sprite of selected pokemon
    pop hl
.getJoypadState
    call GetJoypadStateLowSensitivityWaitReleaseJoy
    jr nz,.loop2
    and a ; was a key pressed?
    jr nz,.keyPressed
    push hl
    FuncCoord 18,11 ; coordinates of blinking down arrow in some menus
    ld hl,Coord
    call HandleDownArrowBlinkTiming ; blink down arrow (if any)
    pop hl
    ld a,[wMenuJoypadPollCount]
    dec a
    jr z,.giveUpWaiting
    jr .loop2
.giveUpWaiting
; if a key wasn't pressed within the specified number of checks
    pop af
    ld [H_DOWNARROWBLINKCNT2],a
    pop af
    ld [H_DOWNARROWBLINKCNT1],a ; restore previous values
    xor a
    ld [wMenuWrappingEnabled],a ; disable menu wrapping
    ret
.keyPressed
    xor a
    ld [$cc4b],a
    ld a,[$ffb5]
    ld b,a
    bit 6,a ; pressed Up key?
    jr z,.checkIfDownPressed
.upPressed
    ld a,[wCurrentMenuItem] ; selected menu item
    and a ; already at the top of the menu?
    jr z,.alreadyAtTop
.notAtTop
    dec a
    ld [wCurrentMenuItem],a ; move selected menu item up one space
    jr .checkOtherKeys
.alreadyAtTop
    ld a,[wMenuWrappingEnabled]
    and a ; is wrapping around enabled?
    jr z,.noWrappingAround
    ld a,[wMaxMenuItem]
    ld [wCurrentMenuItem],a ; wrap to the bottom of the menu
    jr .checkOtherKeys
.checkIfDownPressed
    bit 7,a
    jr z,.checkOtherKeys
.downPressed
    ld a,[wCurrentMenuItem]
    inc a
    ld c,a
    ld a,[wMaxMenuItem]
    cp c
    jr nc,.notAtBottom
.alreadyAtBottom
    ld a,[wMenuWrappingEnabled]
    and a ; is wrapping around enabled?
    jr z,.noWrappingAround
    ld c,$00 ; wrap from bottom to top
.notAtBottom
    ld a,c
    ld [wCurrentMenuItem],a
.checkOtherKeys
    ld a,[wMenuWatchedKeys]
    and b ; does the menu care about any of the pressed keys?
    jp z,.loop1
.checkIfAButtonOrBButtonPressed
    ld a,[$ffb5]
    and a,%00000011 ; pressed A button or B button?
    jr z,.skipPlayingSound
.AButtonOrBButtonPressed
    push hl
    ld hl,wFlags_0xcd60
    bit 5,[hl]
    pop hl
    jr nz,.skipPlayingSound
    ld a,$90
    call PlaySound ; play sound
.skipPlayingSound
    pop af
    ld [H_DOWNARROWBLINKCNT2],a
    pop af
    ld [H_DOWNARROWBLINKCNT1],a ; restore previous values
    xor a
    ld [wMenuWrappingEnabled],a ; disable menu wrapping
    ld a,[$ffb5]
    ret
.noWrappingAround
    ld hl,wTestWrapInMenuInputBit6
    res 6,[hl]
    ld a,[$cc37]
    and a ; should we return if the user tried to go past the top or bottom?
    jr z,.checkOtherKeys
    jr .checkIfAButtonOrBButtonPressed

PlaceMenuCursor:
    ld a,[wTopMenuItemY]
    and a ; is the y coordinate 0?
    jr z,.adjustForXCoord
    ld hl,wTileMap
    ld bc,20 ; screen width
.topMenuItemLoop
    add hl,bc
    dec a
    jr nz,.topMenuItemLoop
.adjustForXCoord
    ld a,[wTopMenuItemX]
    ld b,$00
    ld c,a
    add hl,bc
    push hl
    ld a,[wLastMenuItem]
    and a ; was the previous menu id 0?
    jr z,.checkForArrow1
    push af
    ld a,[$fff6]
    bit 1,a ; is the menu double spaced?
    jr z,.doubleSpaced1
    ld bc,20
    jr .getOldMenuItemScreenPosition
.doubleSpaced1
    ld bc,40
.getOldMenuItemScreenPosition
    pop af
.oldMenuItemLoop
    add hl,bc
    dec a
    jr nz,.oldMenuItemLoop
.checkForArrow1
    ld a,[hl]
    cp "▶" ; was an arrow next to the previously selected menu item?
    jr nz,.skipClearingArrow
.clearArrow
    ld a,[wTileBehindCursor]
    ld [hl],a
.skipClearingArrow
    pop hl
    ld a,[wCurrentMenuItem]
    and a
    jr z,.checkForArrow2
    push af
    ld a,[$fff6]
    bit 1,a ; is the menu double spaced?
    jr z,.doubleSpaced2
    ld bc,20
    jr .getCurrentMenuItemScreenPosition
.doubleSpaced2
    ld bc,40
.getCurrentMenuItemScreenPosition
    pop af
.currentMenuItemLoop
    add hl,bc
    dec a
    jr nz,.currentMenuItemLoop
.checkForArrow2
    ld a,[hl]
    cp "▶" ; has the right arrow already been placed?
    jr z,.skipSavingTile ; if so,don't lose the saved tile
    ld [wTileBehindCursor],a ; save tile before overwriting with right arrow
.skipSavingTile
    ld a,"▶" ; place right arrow
    ld [hl],a
    ld a,l
    ld [wMenuCursorLocation],a
    ld a,h
    ld [wMenuCursorLocation + 1],a
    ld a,[wCurrentMenuItem]
    ld [wLastMenuItem],a
    ret

; This is used to mark a menu cursor other than the one currently being
; manipulated. In the case of submenus,this is used to show the location of
; the menu cursor in the parent menu. In the case of swapping items in list,
; this is used to mark the item that was first chosen to be swapped.
PlaceUnfilledArrowMenuCursor:
    ld b,a
    ld a,[wMenuCursorLocation]
    ld l,a
    ld a,[wMenuCursorLocation + 1]
    ld h,a
    ld [hl],$ec ; outline of right arrow
    ld a,b
    ret

; Replaces the menu cursor with a blank space.
EraseMenuCursor:
    ld a,[wMenuCursorLocation]
    ld l,a
    ld a,[wMenuCursorLocation + 1]
    ld h,a
    ld [hl]," "
    ret

; This toggles a blinking down arrow at hl on and off after a delay has passed.
; This is often called even when no blinking is occurring.
; The reason is that most functions that call this initialize H_DOWNARROWBLINKCNT1 to 0.
; The effect is that if the tile at hl is initialized with a down arrow,
; this function will toggle that down arrow on and off,but if the tile isn't
; initliazed with a down arrow,this function does nothing.
; That allows this to be called without worrying about if a down arrow should
; be blinking.
HandleDownArrowBlinkTiming:
    ld a,[hl]
    ld b,a
    ld a,$ee ; down arrow
    cp b
    jr nz,.downArrowOff
.downArrowOn
    ld a,[H_DOWNARROWBLINKCNT1]
    dec a
    ld [H_DOWNARROWBLINKCNT1],a
    ret nz
    ld a,[H_DOWNARROWBLINKCNT2]
    dec a
    ld [H_DOWNARROWBLINKCNT2],a
    ret nz
    ld a," "
    ld [hl],a
    ld a,$ff
    ld [H_DOWNARROWBLINKCNT1],a
    ld a,$06
    ld [H_DOWNARROWBLINKCNT2],a
    ret
.downArrowOff
    ld a,[H_DOWNARROWBLINKCNT1]
    and a
    ret z
    dec a
    ld [H_DOWNARROWBLINKCNT1],a
    ret nz
    dec a
    ld [H_DOWNARROWBLINKCNT1],a
    ld a,[H_DOWNARROWBLINKCNT2]
    dec a
    ld [H_DOWNARROWBLINKCNT2],a
    ret nz
    ld a,$06
    ld [H_DOWNARROWBLINKCNT2],a
    ld a,$ee ; down arrow
    ld [hl],a
    ret

SECTION "EnableAutoTextBoxDrawing",ROM0[$3c3c]

; The following code either enables or disables the automatic drawing of
; text boxes by DisplayTextID. Both functions cause DisplayTextID to wait
; for a button press after displaying text (unless [$cc47] is set).

EnableAutoTextBoxDrawing: ; 3c3c (0:3c3c)
    xor a
    jr AutoTextBoxDrawingCommon

DisableAutoTextBoxDrawing: ; 3c3f (0:3c3f)
    ld a,$01

AutoTextBoxDrawingCommon: ; 3c41 (0:3c41)
    ld [$cf0c],a ; control text box drawing
    xor a
    ld [$cc3c],a ; make DisplayTextID wait for button press
    ret

PrintText: ; 3c49 (0:3c49)
; given a pointer in hl,print the text there
    push hl
    ld a,1
    ld [$D125],a
    call DisplayTextBoxID
    call UpdateSprites
    call Delay3
    pop hl
Func_3c59: ; 3c59 (0:3c59)
    FuncCoord 1,14
    ld bc,Coord ;$C4B9
    jp TextCommandProcessor

; converts a big-endian binary number into decimal and prints it
; INPUT:
; b = flags and number of bytes
; bit 7: if set,print leading zeroes
;        if unset,do not print leading zeroes
; bit 6: if set,left-align the string (do not pad empty digits with spaces)
;        if unset,right-align the string
; bits 4-5: unused
; bits 0-3: number of bytes (only 1 - 3 bytes supported)
; c = number of decimal digits
; de = address of the number (big-endian)
PrintNumber: ; 3c5f (0:3c5f)
    push bc
    xor a
    ld [H_PASTLEADINGZEROES],a
    ld [H_NUMTOPRINT],a
    ld [H_NUMTOPRINT + 1],a
    ld a,b
    and a,%00001111
    cp 1
    jr z,.oneByte
    cp 2
    jr z,.twoBytes
.threeBytes
    ld a,[de]
    ld [H_NUMTOPRINT],a
    inc de
    ld a,[de]
    ld [H_NUMTOPRINT + 1],a
    inc de
    ld a,[de]
    ld [H_NUMTOPRINT + 2],a
    jr .checkNumDigits
.twoBytes
    ld a,[de]
    ld [H_NUMTOPRINT + 1],a
    inc de
    ld a,[de]
    ld [H_NUMTOPRINT + 2],a
    jr .checkNumDigits
.oneByte
    ld a,[de]
    ld [H_NUMTOPRINT + 2],a
.checkNumDigits
    push de
    ld d,b
    ld a,c
    ld b,a
    xor a
    ld c,a
    ld a,b ; a = number of decimal digits
    cp 2
    jr z,.tensPlace
    cp 3
    jr z,.hundredsPlace
    cp 4
    jr z,.thousandsPlace
    cp 5
    jr z,.tenThousandsPlace
    cp 6
    jr z,.hundredThousandsPlace
    cp 7
    jr z,.millionsPlace
.tenMillionsPlace
    ld a,10000000 >> 16
    ld [H_POWEROFTEN],a
    ld a,(10000000 >> 8) & $FF
    ld [H_POWEROFTEN + 1],a
    ld a,10000000 & $FF
    call .ProcessStep
.millionsPlace
    ld a,1000000 >> 16
    ld [H_POWEROFTEN],a
    ld a,(1000000 >> 8) & $FF
    ld [H_POWEROFTEN + 1],a
    ld a,1000000 & $FF
    call .ProcessStep
.hundredThousandsPlace
    ld a,100000 >> 16
    ld [H_POWEROFTEN],a
    ld a,(100000 >> 8) & $FF
    ld [H_POWEROFTEN + 1],a
    ld a,100000 & $FF
    call .ProcessStep
.tenThousandsPlace
    xor a
    ld [H_POWEROFTEN],a
    ld a,10000 >> 8
    ld [H_POWEROFTEN + 1],a
    ld a,10000 & $FF
    call .ProcessStep
.thousandsPlace
    xor a
    ld [H_POWEROFTEN],a
    ld a,1000 >> 8
    ld [H_POWEROFTEN + 1],a
    ld a,1000 & $FF
    call .ProcessStep
.hundredsPlace
    xor a
    ld [H_POWEROFTEN],a
    xor a
    ld [H_POWEROFTEN + 1],a
    ld a,100
    call .ProcessStep
.tensPlace
    ld c,00
    ld a,[H_NUMTOPRINT + 2]
.loop
    cp 10
    jr c,.underflow
    sub a,10
    inc c
    jr .loop
.underflow
    ld b,a
    ld a,[H_PASTLEADINGZEROES]
    or c
    ld [H_PASTLEADINGZEROES],a
    jr nz,.pastLeadingZeroes
    call PrintNumber_PrintLeadingZero
    jr .advancePointer
.pastLeadingZeroes
    ld a,"0"
    add c
    ld [hl],a
.advancePointer
    call PrintNumber_AdvancePointer
.onesPlace
    ld a,"0"
    add b
    ld [hli],a
    pop de
    dec de
    pop bc
    ret
.ProcessStep
    ld [H_POWEROFTEN + 2],a
    call PrintNumber_PrintDigit
    jp PrintNumber_AdvancePointer

SECTION "PrintNumber_PrintDigit",ROM0[$3d25]

; prints a decimal digit
; This works by repeatedely subtracting a power of ten until the number becomes negative.
; The number of subtractions it took in order to make the number negative is the digit for the current number place.
; The last value that the number had before becoming negative is kept as the new value of the number.
; A more succinct description is that the number is divided by a power of ten
; and the quotient becomes the digit while the remainder is stored as the new value of the number.
PrintNumber_PrintDigit: ; 3d25 (0:3d25)
    ld c,0 ; counts number of loop iterations to determine the decimal digit
.loop
    ld a,[H_POWEROFTEN]
    ld b,a
    ld a,[H_NUMTOPRINT]
    ld [H_SAVEDNUMTOPRINT],a
    cp b
    jr c,.underflow0
    sub b
    ld [H_NUMTOPRINT],a
    ld a,[H_POWEROFTEN + 1]
    ld b,a
    ld a,[H_NUMTOPRINT + 1]
    ld [H_SAVEDNUMTOPRINT + 1],a
    cp b
    jr nc,.noBorrowForByte1
.byte1BorrowFromByte0
    ld a,[H_NUMTOPRINT]
    or a,0
    jr z,.underflow1
    dec a
    ld [H_NUMTOPRINT],a
    ld a,[H_NUMTOPRINT + 1]
.noBorrowForByte1
    sub b
    ld [H_NUMTOPRINT + 1],a
    ld a,[H_POWEROFTEN + 2]
    ld b,a
    ld a,[H_NUMTOPRINT + 2]
    ld [H_SAVEDNUMTOPRINT + 2],a
    cp b
    jr nc,.noBorrowForByte2
.byte2BorrowFromByte1
    ld a,[H_NUMTOPRINT + 1]
    and a
    jr nz,.finishByte2BorrowFromByte1
.byte2BorrowFromByte0
    ld a,[H_NUMTOPRINT]
    and a
    jr z,.underflow2
    dec a
    ld [H_NUMTOPRINT],a
    xor a
.finishByte2BorrowFromByte1
    dec a
    ld [H_NUMTOPRINT + 1],a
    ld a,[H_NUMTOPRINT + 2]
.noBorrowForByte2
    sub b
    ld [H_NUMTOPRINT + 2],a
    inc c
    jr .loop
.underflow2
    ld a,[H_SAVEDNUMTOPRINT + 1]
    ld [H_NUMTOPRINT + 1],a
.underflow1
    ld a,[H_SAVEDNUMTOPRINT]
    ld [H_NUMTOPRINT],a
.underflow0
    ld a,[H_PASTLEADINGZEROES]
    or c
    jr z,PrintNumber_PrintLeadingZero
    ld a,"0"
    add c
    ld [hl],a
    ld [H_PASTLEADINGZEROES],a
    ret

; prints a leading zero unless they are turned off in the flags
PrintNumber_PrintLeadingZero: ; 3d83 (0:3d83)
    bit 7,d ; print leading zeroes?
    ret z
    ld [hl],"0"
    ret

; increments the pointer unless leading zeroes are not being printed,
; the number is left-aligned,and no nonzero digits have been printed yet
PrintNumber_AdvancePointer: ; 3d89 (0:3d89)
    bit 7,d ; print leading zeroes?
    jr nz,.incrementPointer
    bit 6,d ; left alignment or right alignment?
    jr z,.incrementPointer
    ld a,[H_PASTLEADINGZEROES]
    and a
    ret z
.incrementPointer
    inc hl
    ret

; calls a function from a table of function pointers
; INPUT:
; a = index within table
; hl = address of function pointer table
CallFunctionInTable: ; 3d97 (0:3d97)
    push hl
    push de
    push bc
    add a
    ld d,0
    ld e,a
    add hl,de
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ld de,.returnAddress
    push de
    jp hl
.returnAddress
    pop bc
    pop de
    pop hl
    ret

; searches an array at hl for the value in a.
; skips (de − 1) bytes between reads,so to check every byte,de should be 1.
; if found,returns count in b and sets carry.
IsInArray: ; 3dab (0:3dab)
    ld b,0
    ; ft

IsInArrayCummulativeCount: ; 3dad (0:3dad)
    ld c,a
.loop
    ld a,[hl]
    cp $FF
    jr z,.NotInArray
    cp c
    jr z,.InArray
    inc b
    add hl,de
    jr .loop
.NotInArray
    and a
    ret
.InArray
    scf
    ret

RestoreScreenTilesAndReloadTilePatterns: ; 3dbe (0:3dbe)
    call CleanLCD_OAM
    ld a,$1
    ld [$cfcb],a
    call ReloadMapSpriteTilePatterns
    call LoadScreenTilesFromBuffer2
    call LoadTextBoxTilePatterns
    call GoPAL_SET_CF1C
    jr Delay3

; calls GBPalWhiteOut and then Delay3
GBPalWhiteOutWithDelay3: ; 3dd4 (0:3dd4)
    call GBPalWhiteOut

Delay3: ; 3dd7 (0:3dd7)
; call Delay with a parameter of 3
    ld c,3
    jp DelayFrames

; resets BGP and OBP0 to their usual colors
GBPalNormal: ; 3ddc (0:3ddc)
    ld a,%11010000
GBPalCommon:
    ld [rOBP0],a
    ld a,%11100100
    ld [rBGP],a
    ret

; makes all palette colors white
GBPalWhiteOut: ; 3de5 (0:3de5)
    xor a
    ld [rBGP],a
    ld [rOBP0],a
    ld [rOBP1],a
    ret

GoPAL_SET_CF1C: ; 3ded (0:3ded)
    ld b,$ff
GoPAL_SET: ; 3def (0:3def)
    ld a,[wRunningOnSGB]
    and a
    jp z,Delay3
    jp DelayAndProcessSGBPacket

SECTION "GetHealthBarColor",ROM0[$3df9]

GetHealthBarColor: ; 3df9 (0:3df9)
    ld a,e
    cp $1b
    ld d,$0
    jr nc,.asm_3e06
    cp $a
    inc d
    jr nc,.asm_3e06
    inc d
.asm_3e06
    ld [hl],d
    ret

ReloadMapSpriteTilePatterns: ; 3e08 (0:3e08)
    ld hl,$cfc4
    ld a,[hl]
    push af
    res 0,[hl]
    push hl
    xor a
    ld [W_SPRITESETID],a ; $d3a8
    call DisableLCD
    BANKSWITCH InitMapSprites
    call EnableLCD
    pop hl
    pop af
    ld [hl],a
    call LoadPlayerSpriteGraphics
    call LoadFontTilePatterns
    jp UpdateSprites

GiveItem: ; 3e2e (0:3e2e)
; Give player quantity c of item b,and copy item name to $cf4b.
; Set carry on success. If no room in bag,reset carry.
    ld a,b
    ld [$d11e],a
    ld [$cf91],a
    ld a,c
    ld [$cf96],a
    ld hl,wNumBagItems
    call AddItemToInventory
    ret nc
HackForGetItemName:
    call GetItemName ; $2fcf
    call CopyStringToCF4B
    scf
    ret

GivePokemon: ; 3e48 (0:3e48)
    ld a,b
    ld [$cf91],a
    ld a,c
    ld [$d127],a
    xor a
    ld [$cc49],a
    BANKSWITCH_JUMP _GivePokemon

GenRandom: ; 3e5c (0:3e5c)
; store a random 8-bit value in a
    push hl
    push de
    push bc
    BANKSWITCH GenRandom_
    ld a,[H_RAND1]
    pop bc
    pop de
    pop hl
    ret

Predef: ; 3e6d (0:3e6d)
; runs a predefined ASM command,where the command ID is read from $D0B7
; $3E6D grabs the ath pointer from PredefPointers and executes it

    ld [$CC4E],a ; save the predef routine's ID for later

    ld a,[H_LOADEDROMBANK]
    ld [$CF12],a
    push af ; Backup Return Bank

    ld a,BANK(GetPredefPointer)
    call RoutineForRealGB
    call GetPredefPointer

    ; call the predef function
    call RoutineForRealGB
    ld de,.Return
    push de
    jp hl
    ; after the predefined function finishes it returns here
.Return

    push hl    ; ...
    push af    ; ...
    ld hl,sp+5 ; Restore Return Bank
    pop af     ; (No Flags affected)
    ld a,[hl]  ; ...
    pop hl     ; ...
    inc sp     ; "Fake Pop"
    inc sp     ; ...

    jp RoutineForRealGB

SECTION "Load16BitRegisters",ROM0[$3e94]

;loads hl from cc4f,de from cc51,and bc from cc53

Load16BitRegisters: ; 3e94 (0:3e94)
    ld a,[$cc4f]
    ld h,a
    ld a,[$cc50]
    ld l,a
    ld a,[$cc51]
    ld d,a
    ld a,[$cc52]
    ld e,a
    ld a,[$cc53]
    ld b,a
    ld a,[$cc54]
    ld c,a
    ret

Func_3ead:
    BANKSWITCH_JUMP CinnabarGymProcessAllGate

CheckForHiddenObjectOrBookshelfOrCardKeyDoor:
    ld a,[H_LOADEDROMBANK]
    push af
    ld a,[H_CURRENTPRESSEDBUTTONS]
    bit 0,a
    jr z,.nothingFound
    ld a,BANK(CheckForHiddenObject)
    call RoutineForRealGB
    call CheckForHiddenObject
    ld a,[$FF00+$ee]
    and a
    jr nz,.hiddenObjectNotFound
    ld a,[$cd3e]
    call RoutineForRealGB
    ld de,.return
    push de
    jp hl
.return
    xor a
    jr .done
.hiddenObjectNotFound
    BANKSWITCH PrintBookshelfText
    ld a,[$FF00+$db]
    and a
    jr z,.done
.nothingFound
    ld a,$ff
.done
    ld [$FF00+$eb],a
    pop af
    jp RoutineForRealGB

PrintPredefTextID:
    ld [H_DOWNARROWBLINKCNT2],a ; $FF00+$8c
    ld hl,TextPredefs
    call Func_3f0f
    ld hl,$cf11
    set 0,[hl]
    call DisplayTextID

Func_3f05:
    ld hl,W_MAPTEXTPTR ; $d36c
    ld a,[$FF00+$ec]
    ld [hli],a
    ld a,[$FF00+$ed]
    ld [hl],a
    ret

Func_3f0f:
    ld a,[W_MAPTEXTPTR] ; $d36c
    ld [$FF00+$ec],a
    ld a,[$d36d]
    ld [$FF00+$ed],a
    ld a,l
    ld [W_MAPTEXTPTR],a ; $d36c
    ld a,h
    ld [$d36d],a
    ret

TextPredefs:
    dw CardKeySuccessText                   ; id = 01
