; INPUT hl = giusto indirizzo degli IV del pokemon interessato
; W_ENEMYMONATKDEFIV ; .Front
; W_PLAYERMONIVS     ; .Back
; $cfb3              ; .OutOfBattle
IsShiny:
    push hl
    push af
    call CheckShiny
    jr nz,.End
    ld hl,wFlagShinyBit2
    set 2,[hl]
.End
    pop af
    pop hl
    ret

; INPUT hl = giusto indirizzo degli IV del pokemon interessato
; OUTPUT z = set if Shiny
CheckShiny:
    ld a,[hli] ; Controllo IV Atk/Def ; Controllo IV Atk,Shiny se IV Atk = 2,3,6,7,10,11,14 o 15
    and %00101111 ; Shiny se bit 5 di a settato,gli altri bit dell'atk non contano,applico maschera
    cp %00101010
    ld a,[hld] ; Controllo IV Spd/Spc
    ret nz
    cp %10101010
    ret

GoodCopyVideoData: ; Denim,ExpBar
    ld a,[rLCDC]
    bit 7,a ; is the LCD enabled?
    jp nz,CopyVideoData ; if LCD is on,transfer during V-blank
    ld a,b
    push hl
    push de
    ld h,0
    ld l,c
    add hl,hl
    add hl,hl
    add hl,hl
    add hl,hl
    ld b,h
    ld c,l
    pop hl
    pop de
    jp FarCopyData2 ; if LCD is off,transfer all at once

HackItemInBattle:
    pop hl  ; get Return Pointer to HL
    push hl ; restore Return Pointer in Stack
    push bc
    push de
    ld e,l
    BANKSWITCH _HackItemInBattle
    ld h,d
    ld l,e
    pop de
    pop bc
    ret

