; loads pokemon data from one of multiple sources to $cf98
; loads base stats to $d0b8 (W_MONHEADER)
; INPUT:
; [$cf92] = index of pokemon within party/box
; [$cc49] = source
; 00: player's party
; 01: enemy's party
; 02: current box
; 03: daycare
; OUTPUT:
; [$cf91] = pokemon ID
; $cf98 = base address of pokemon data
; $d0b8 = base address of base stats (W_MONHEADER)
LoadMonData_: ; 45b6 (1:45b6)
    ld a,[$da5f] ; daycare pokemon ID
    ld [$cf91],a
    ld a,[$cc49]
    cp $03
    jr z,.done
    ld a,[$cf92]
    ld e,a
    ld hl,W_PARTYMON1 ; $d164
    ld a,[$cc49]
    and a
    jr z,.getSpecies
    dec a
    jr z,.enemyParty
    ld hl,W_NUMINBOX+1 ; $da81
    jr .getSpecies
.enemyParty
    ld hl,wEnemyPartyMons ; $d89d
.getSpecies
    ld d,$0
    add hl,de
    ld a,[hl]
    ld [$cf91],a
.done
    ld a,[$cf91]
    ld [$d0b5],a ; input for GetMonHeader
    ld hl,W_PARTYMON1DATA
    ld bc,44
    ld a,[$cc49]
    cp $01
    jr c,.getMonEntry
    ld hl,wEnemyMons ; enemy pokemon 1 data
    jr z,.getMonEntry
    cp $02
    ld hl,W_BOXMON1DATA ; box pokemon 1 data
    ld bc,33
    jr z,.getMonEntry
    ld hl,$da5f ; daycare pokemon data
    jr .copyMonData
.getMonEntry ; add the product of the index and the size of each entry
    ld a,[$cf92]
    call AddNTimes
.copyMonData
    ld de,$cf98
    ld bc,44
    call CopyData
    ; Copy Exclusive
    ld a,[$cc49]
    and a
    ld hl,W_PARTYMON1OT+8
    jr z,.getExclusive
    dec a
    jr z,.resetExclusive ; Enemy Exclusive doesn't exists
    dec a
    ld hl,$dd2a+8 ; BOXMON1OT
    jr z,.getExclusive
    dec a
    ld hl,$da54+8 ; DayCare
    jr z,.CopyExclusive
.resetExclusive
    xor a
    ld hl,wTempExclusive
    ld [hli],a
    ld [hli],a
    ld [hl],a
    jr .end
.getExclusive
    ld a,[$cf92]
    ld bc,11
    call AddNTimes
.CopyExclusive
    ld de,wTempExclusive
    ld bc,3
    call CopyData ; copy bc bytes of data from hl to de
.end
    ; Save AlternateFormIndex
    ld a,[$cfb6] ; move2pp
    ld [wAlternateFormIndex],a
    jp GetMonHeader ; load base stats to $d0b8

