_UpdateSprites: ; 4c34 (1:4c34)
    ld h,$c1
    inc h
    ld a,$e    ; $c20e
.spriteLoop
    ld l,a
    sub $e
    ld c,a
    ld [H_CURRENTSPRITEOFFSET],a
    ld a,[hl]
    and a
    jr z,.skipSprite   ; tests $c2Xe
    push hl
