.loop
    call PlaceMenuCursor
    call SetOptionsFromCursorPositions
.getJoypadStateLoop
    call GetJoypadStateLowSensitivity
    ld a,[$ffb5]
    ld b,a
    and a,%11111010 ; ▼▲◄►StSeBA
    jr z,.getJoypadStateLoop
    bit 1,b ; B button pressed?
    jr nz,.exitMenu
    bit 3,b ; Start button pressed?
    jr nz,.exitMenu
;    bit 0,b ; A button pressed?
;    jr z,.checkDirectionKeys
    jr .checkDirectionKeys
;    ld a,[wTopMenuItemY]
;    cp 16 ; is the cursor on Cancel?
;    jr nz,.loop
.exitMenu
    ld a,$90
    call PlaySound ; play sound
    ret
.Version
    VERSION
    db "@"
.eraseOldMenuCursor
    ld [wTopMenuItemX],a
    call EraseMenuCursor
    jr .loop
.checkDirectionKeys
    ld a,[wTopMenuItemY]
    bit 7,b ; Down pressed?
    jr nz,.downPressed
    bit 6,b ; Up pressed?
    jr nz,.upPressed
    cp 7 ; cursor in Battle Animation section?
    jr z,.cursorInBattleAnimation
    cp 11 ; cursor in Battle Style section?
    jr z,.cursorInBattleStyle
    cp 16 ; cursor on Cancel?
    jr z,.loop
.cursorInTextSpeed
    bit 5,b ; Left pressed?
    jp nz,.pressedLeftInTextSpeed
    jp .pressedRightInTextSpeed
.downPressed
    cp 11
    ld b,-8
    ld hl,$cd3d
    jr z,.updateMenuVariables
    ld b,4
    cp 3
    inc hl
    jr z,.updateMenuVariables
    inc hl
    jr .updateMenuVariables
.upPressed
    cp 7
    ld b,-4
    ld hl,$cd3d
    jr z,.updateMenuVariables
    cp 11
    inc hl
    jr z,.updateMenuVariables
    ld b,+8
    inc hl
    ; ft
.updateMenuVariables
    add b
    ld [wTopMenuItemY],a
    ld a,[hl]
    ld [wTopMenuItemX],a
    call PlaceUnfilledArrowMenuCursor
    jp .loop
.cursorInBattleAnimation
    ld a,[$cd3e] ; battle animation cursor X coordinate
    xor a,$08 ; toggle between 2 and 10
    ld [$cd3e],a
    jp .eraseOldMenuCursor
.cursorInBattleStyle
    ld a,[$cd3f] ; battle style cursor X coordinate
    xor a,$08 ; toggle between 2 and 10
    ld [$cd3f],a
    jp .eraseOldMenuCursor
.pressedLeftInTextSpeed
    ld a,[$cd3d] ; text speed cursor X coordinate
    cp 2
    jr z,.updateTextSpeedXCoord
    cp 7
    jr nz,.fromSlowToMedium
    sub a,5
    jr .updateTextSpeedXCoord
.fromSlowToMedium
    sub a,7
    jr .updateTextSpeedXCoord
.pressedRightInTextSpeed
    ld a,[$cd3d] ; text speed cursor X coordinate
    cp 14
    jr z,.updateTextSpeedXCoord
    cp 7
    jr nz,.fromFastToMedium
    add a,7
    jr .updateTextSpeedXCoord
.fromFastToMedium
    add a,5
.updateTextSpeedXCoord
    ld [$cd3d],a ; text speed cursor X coordinate
    jp .eraseOldMenuCursor

