; sets the options variable according to the current placement of the menu cursors in the options menu
SetOptionsFromCursorPositions:
    ld hl,TextSpeedOptionData
    ld a,[$cd3d] ; text speed cursor X coordinate
    ld c,a
.loop
    ld a,[hli]
    cp c
    jr z,.textSpeedMatchFound
    inc hl
    jr .loop
.textSpeedMatchFound
    ld a,[hl]
    ld d,a
    call GetFirstBinaryOptionChoice ; ld a,[$cd3e] ; battle animation cursor X coordinate
    dec a
    jr z,.battleAnimationOn
.battleAnimationOff
    set 7,d
    jr .checkBattleStyle
.battleAnimationOn
    res 7,d
.checkBattleStyle
    call GetSecondBinaryOptionChoice ; ld a,[$cd3f] ; battle style cursor X coordinate
    dec a
    jr z,.battleStyleShift
.battleStyleSet
    set 5,d
    jr .storeOptions
.battleStyleShift
    res 5,d
.storeOptions
    set 6,d ; Real Battle Style
    ld a,d
    ld [W_OPTIONS],a
    ret

