SECTION "SetCursorPositionsFromOptions",ROMX[$604c],BANK[$1]

; reads the options variable and places menu cursors in the correct positions within the options menu
SetCursorPositionsFromOptions: ; 604c (1:604c)
    ld hl,TextSpeedOptionData + 1
    ld a,[W_OPTIONS]
    ld c,a
    and a,%00000011 ; Speed text from 0 to 2
    push bc
    ld de,2
    call IsInArray
    pop bc
    dec hl
    ld a,[hl]
    ld [$cd3d],a ; text speed cursor X coordinate
    FuncCoord 0,3
    ld hl,Coord
    call .placeUnfilledRightArrow
    sla c
    ld a,2 ; On
    jr nc,.storeBattleAnimationCursorX
    ld a,10 ; Off
.storeBattleAnimationCursorX
    ld [$cd3e],a ; battle animation cursor X coordinate
    FuncCoord 0,7
    ld hl,Coord
    call .placeUnfilledRightArrow
    call NewOption
    jr nc,.storeBattleStyleCursorX
    ld a,10
.storeBattleStyleCursorX
    ld [$cd3f],a ; battle style cursor X coordinate
    FuncCoord 0,11
    ld hl,Coord
;    call .placeUnfilledRightArrow
; cursor in front of Cancel
;    FuncCoord 0,16
;    ld hl,Coord
;    ld a,2
.placeUnfilledRightArrow
    ld e,a
    ld d,0
    add hl,de
    ld [hl],$ec ; unfilled right arrow menu cursor
    ret

SECTION "TextSpeedOptionData",ROMX[$6096],BANK[$1]

