    ; db  1,1 ; Fast
    ; db 7 ; default X coordinate (Medium)
    ; db $ff ; terminator
    db 14,2 ; Slow
    db  7,1 ; Medium
    db  2,0 ; Fast
    db 7 ; default X coordinate (Medium)
    db $ff ; terminator

