    ld [$cf93],a
    ld a,$13
    ld [$d125],a
    call DisplayTextBoxID ; draw money text box
    ld a,$15
    ld [$d125],a
    call DisplayTextBoxID ; do buy/sell/quit menu
    ld a,[$d12e]
    cp $02
    jp z,.done
    ld a,[$d12d] ; ID of the chosen menu item
    and a ; buying?
    jp z,.buyMenu
    dec a ; selling?
    jr z,.sellMenu
    dec a ; quitting?
    jp z,.done
.sellMenu
    xor a
    ld [$cf93],a
    ld a,$02
    ld [$d11b],a
    BANKSWITCH Func_39bd5
    ld a,[wNumBagItems]
    and a
    jp z,.bagEmpty
