.sellMenuLoop
    call LoadScreenTilesFromBuffer1 ; restore saved screen
    ld a,$13
    ld [$d125],a
    call DisplayTextBoxID ; draw money text box
    ld hl,wNumBagItems
    ld a,l
    ld [$cf8b],a
    ld a,h
    ld [$cf8c],a
    xor a
    ld [$cf93],a
    ld a,ITEMLISTMENU
    ld [wListMenuID],a
    call DisplayListMenuIDSaveCursor
    jp c,.returnToMainPokemartMenu ; if the player closed the menu
.confirmItemSale ; if the player is trying to sell a specific item
    call IsKeyItem ; check if item is unsellable
    ld a,[$d124]
    and a
    jr nz,.unsellableItem
    ld a,[$cf91]
    ld a,PRICEDITEMLISTMENU
    ld [wListMenuID],a
    BANKSWITCH HalvePrice
    call DisplayChooseQuantityMenu
    inc a
    jr z,.sellMenuLoop ; if the player closed the choose quantity menu with the B button
    ld hl,.PokemartTellSellPrice
    ld bc,$0e01
    call PrintText
    FuncCoord 14,7
    ld hl,Coord
    ld bc,$080f
    ld a,$14
    ld [$d125],a
    call DisplayTextBoxID ; yes/no menu
    ld a,[$d12e]
    cp $02
    jr z,.sellMenuLoop ; if the player pressed the B button
    ld a,[$d12d] ; ID of the chosen menu item
    dec a
    jr z,.sellMenuLoop ; if the player chose No
.sellItem
    ld a,[$cf0a] ; flag that is set if something is sold or bought
    and a
    jr nz,.skipSettingFlag1
    inc a
    ld [$cf0a],a
.skipSettingFlag1
    call AddAmountSoldToMoney
    ld hl,wNumBagItems
    call RemoveItemFromInventory
    ld a,[wNumBagItems]
    and a
    jr z,.returnToMainPokemartMenu2
    jp .sellMenuLoop
.unsellableItem
    ld hl,.PokemartUnsellableItemText
    call PrintText
    jp .sellMenuLoop
.bagEmpty
    ld hl,.PokemartItemBagEmptyText
    call PrintText
    call SaveScreenTilesToBuffer1 ; save screen
.returnToMainPokemartMenu2
    jp .returnToMainPokemartMenu
.buyMenu
    ld a,$01
    ld [$cf93],a
    ld a,$03
    ld [$d11b],a
    BANKSWITCH Func_39bd5
    ld hl,.PokemartBuyingGreetingText
    call PrintText
    call SaveScreenTilesToBuffer1 ; save screen
    call ResetSellBuyMenuCursor
.buyMenuLoop
    call LoadScreenTilesFromBuffer1 ; restore saved screen
    ld a,$13
    ld [$d125],a
    call DisplayTextBoxID ; draw money text box
    ld hl,wBufferList
    ld a,l
    ld [$cf8b],a
    ld a,h
    ld [$cf8c],a
    ld a,1
    ld [$cf93],a
    inc a ; a = 2 (PRICEDITEMLISTMENU)
    ld [wListMenuID],a
    call DisplayListMenuIDSaveCursor
    jr c,.returnToMainPokemartMenu ; if the player closed the menu
    ld a,254
    ld [$cf97],a
    xor a
    ld [$ff8e],a
    call DisplayChooseQuantityMenu
    inc a
    jr z,.buyMenuLoop ; if the player closed the choose quantity menu with the B button
    ld a,[$cf91] ; item ID
    ld [$d11e],a ; store item ID for GetItemName
    call GetItemName
    call CopyStringToCF4B ; copy name to $cf4b
    ld hl,.PokemartTellBuyPrice
    call PrintText
    FuncCoord 14,7
    ld hl,Coord
    ld bc,$080f
    ld a,$14
    ld [$d125],a
    call DisplayTextBoxID ; yes/no menu
    ld a,[$d12e]
    cp $02
    jr z,.buyMenuLoop ; if the player pressed the B button
    ld a,[$d12d] ; ID of the chosen menu item
    dec a
    jr z,.buyMenuLoop ; if the player chose No
.buyItem
    call .isThereEnoughMoney
    jr c,.notEnoughMoney
    ld hl,wNumBagItems
    call AddItemToInventory
    jr nc,.bagFull
    call SubtractAmountPaidFromMoney
    ld a,[$cf0a] ; flag that is set if something is sold or bought
    and a
    jr nz,.skipSettingFlag2
    ld a,$01
    ld [$cf0a],a
.skipSettingFlag2
    ld a,$b2
    call PlaySoundWaitForCurrent ; play sound
    call WaitForSoundToFinish ; wait until sound is done playing
    ld hl,.PokemartBoughtItemText
    call PrintText
    jp .buyMenuLoop
.returnToMainPokemartMenu
    call LoadScreenTilesFromBuffer1 ; restore save screen
    ld a,$13
    ld [$d125],a
    call DisplayTextBoxID ; draw money text box
    ld hl,.PokemartAnythingElseText
