LearnMove:
    call .IsSkill
    call LearnMove_CheckSkill
    jr nc,.continue
    ld b,$0 ; 0 = No Learn
    ret
.continue
    call CheckMoveRelearn
    call z,.SaveScreenTilesToBuffer1
    ld a,[wWhichPokemon] ; $cf92
    ld hl,W_PARTYMON1NAME ; $d2b5
    call GetPartyMonName
    ld hl,$cd6d
    ld de,$d036
    ld bc,$b
    call CopyData
    call CheckMoveRelearn
    jr nz,.skip
    ; XX learned YY! ♫♪
    call .IsSkill
    ld hl,LearnedSkillTextPlusSound
    jr c,.PrintLearned
    cp TELEPORT
    ld hl,.LearnedTextPlusSound
    jr nz,.PrintLearned
    ld hl,TELEPORT_FLAG_BYTE
    bit TELEPORT_FLAG_BIT,[hl]
    jr nz,.TeleportFullMessage
    ld hl,.LearnedTextPlusSound
    jr .PrintLearned
.TeleportFullMessage
    ld hl,LearnedSkillTextPlusSound
    call PrintText
    ld hl,.LearnedTextPlusSound
.PrintLearned
    call PrintText
    ; Get Mon OT Name to Try Add Exclusive Move
    ld hl,W_PARTYMON1OT+8
    ld a,[wWhichPokemon]
    ld bc,11
    call AddNTimes
    ld d,h
    ld e,l
    ld hl,GenericBuffer+1
    ld a,e
    ld [hli],a
    ld [hl],d
    ; Get Mon Start to Try Add Exclusive Move
    ld hl,W_PARTYMON1_NUM
    ld a,[wWhichPokemon]
    ld bc,$2c
    call AddNTimes
    ld d,h
    ld e,l
    BANKSWITCH TryToAddExclusiveMove
.skip
    call .IsSkill
    jp c,.SkillDontInsertInMonMoves
    ld hl,W_PARTYMON1_MOVE1 ; $d173
    ld bc,$2c
    ld a,[wWhichPokemon] ; $cf92
    call AddNTimes
    ld d,h
    ld e,l
    ld b,$4
    ld c,1 ; result
.FindEmptySlot
    ld a,[hl]
    and a
    jr z,.DoLearn
    inc hl
    dec b
    jr nz,.FindEmptySlot
    ; Return to First Move
    ld bc,$fffc ; -4
    add hl,bc
.TryToLearnMove
    push de
    call .LearnButJust4Moves
    pop de
    jr c,.AbandonLearningConfirm
    push hl
    push de
    call IsTryingToLearnPalFix_End
    pop de
    pop hl
    ld c,2 ; result
.DoLearn
    push bc
    ld a,[$d0e0]
    ld [hl],a
    ld a,[W_ISINBATTLE] ; $d057
    and a
    jr z,.LearnedMoveComplete
    ld a,[wWhichPokemon] ; $cf92
    ld b,a
    ld a,[wPlayerMonNumber] ; $cc2f
    cp b
    jp nz,.LearnedMoveComplete
    ; Check Transformed
    ld a,[W_PLAYERBATTSTATUS3]
    bit 3,a ; is the mon transformed?
    jp nz,.LearnedMoveComplete
    ; Update Active Mon Moves
    ld h,d
    ld l,e
    ld de,W_PLAYERMONMOVES
    ld bc,$4
    call CopyData
    jr .LearnedMoveComplete

