    ld hl,wTopMenuItemY ; $cc24
    ld a,13
    ld [hli],a
    ld a,01
    ld [hli],a
    xor a
    ld [hli],a
    inc hl
    ld a,[$cd6c]
    ld [hli],a
    call CheckMoveRelearn
    ld a,%11000011 ; ▼▲◄►StSeBA
    jr nz,.DoneMask
    ld a,%11001011 ; ▼▲◄►StSeBA
.DoneMask
    ld [hli],a
    ld [hl],$0
.RestartMenu
    FuncCoord 00,12
    ld hl,Coord
    ld bc,$0412
    call TextBoxBorder
    FuncCoord 02,13
    ld hl,Coord
    ld de,$d0e1
    ld a,[$FF00+$f6]
    set 2,a
    ld [$FF00+$f6],a
    call PlaceString
    ld a,[$FF00+$f6]
    res 2,a
    ld [$FF00+$f6],a
    ld hl,$fff6
    set 1,[hl]
    pop hl
    push hl
    call HandleMenuInput_PrintMoveBox ; call HandleMenuInput
    bit 3,a
    jr nz,.RestartMenu
    ld hl,$fff6
    res 1,[hl]
    push af
    call CheckMoveRelearn
    call z,LoadScreenTilesFromBuffer1
    pop af
    pop hl
    bit 1,a
    jr nz,.asm_6fab_B_Pressed

    ld a,[wCurrentMenuItem] ; $cc26
    ld c,a
    ld b,$0

    add hl,bc
    and a ; rcf
    ret
