; function that performs initialization for DisplayTextID
DisplayTextIDInit: ; 7096 (1:7096)
    xor a
    ld [$cf94],a
    ld a,[$cf0c]
    bit 0,a
    jr nz,.skipDrawingTextBoxBorder
    ld a,[$ff8c] ; text ID (or sprite ID)
    and a
    jr nz,.notStartMenu
; if text ID is 0 (i.e. the start menu)
; Note that the start menu text border is also drawn in the function directly
; below this,so this seems unnecessary.
;    ld a,[$d74b]
;    bit 5,a ; does the player have the pokedex?
; start menu with pokedex
;    FuncCoord 10,0 ; $c3aa
;    ld hl,Coord
;    ld b,$0e-2
;    ld c,$08
;    jr nz,.drawTextBoxBorder
; start menu without pokedex
    FuncCoord 10,0 ; $c3aa
    ld hl,Coord
    ld b,$0c-2
    ld c,$08
    jr .drawTextBoxBorder
; if text ID is not 0 (i.e. not the start menu) then do a standard dialogue text box
.notStartMenu
    FuncCoord 0,12 ; $c490
    ld hl,Coord
    ld b,$04
    ld c,$12
.drawTextBoxBorder
    call TextBoxBorder
.skipDrawingTextBoxBorder
    ld hl,$cfc4
    set 0,[hl]
    ld hl,wFlags_0xcd60
    bit 4,[hl]
    res 4,[hl]
    jr nz,.skipMovingSprites
    call UpdateSprites ; move sprites
.skipMovingSprites
; loop to copy C1X9 (direction the sprite is facing) to C2X9 for each sprite
; this is done because when you talk to an NPC,they turn to look your way
; the original direction they were facing must be restored after the dialogue is over
    ld hl,$c119
    ld c,$0f
    ld de,$0010
.spriteFacingDirectionCopyLoop
    ld a,[hl]
    inc h
    ld [hl],a
    dec h
    add hl,de
    dec c
    jr nz,.spriteFacingDirectionCopyLoop
; loop to force all the sprites in the middle of animation to stand still
; (so that they don't like they're frozen mid-step during the dialogue)
    ld hl,$c102
    ld de,$0010
    ld c,e
.spriteStandStillLoop
    ld a,[hl]
    cp $ff ; is the sprite visible?
    jr z,.nextSprite
; if it is visible
    and a,$fc
    ld [hl],a
.nextSprite
    add hl,de
    dec c
    jr nz,.spriteStandStillLoop
    ld b,$9c ; window background address
    call CopyScreenTileBufferToVRAM ; transfer background in WRAM to VRAM
    xor a
    ld [$ffb0],a ; put the window on the screen
    call LoadFontTilePatterns
    ld a,$01
    ld [H_AUTOBGTRANSFERENABLED],a ; enable continuous WRAM to VRAM transfer each V-blank
    ret

; function that displays the start menu
DrawStartMenu:
;    ld a,[$d74b]
;    bit 5,a ; does the player have the pokedex?
; menu with pokedex
;    FuncCoord 10,0 ; $c3aa
;    ld hl,Coord
;    ld b,$0e-2
;    ld c,$08
;    jr nz,.drawTextBoxBorder
; shorter menu if the player doesn't have the pokedex
    FuncCoord 10,0 ; $c3aa
    ld hl,Coord
    ld b,$0c-2
    ld c,$08
.drawTextBoxBorder
    call TextBoxBorder
    ld a,%11001011 ; bit mask for down,up,start,B,and A buttons
    ld [$cc29],a
    ld a,$02
    ld [$cc24],a ; Y position of first menu choice
    ld a,$0b
    ld [$cc25],a ; X position of first menu choice
    ld a,[wBattleAndStartSavedMenuItem] ; remembered menu selection from last time
    ld [$cc26],a
    ld [$cc2a],a
    xor a
    ld [$cc37],a
    ld hl,$d730
    set 6,[hl] ; no pauses between printing each letter
    FuncCoord 12,2 ; $c3d4
    ld hl,Coord
;    ld a,[$d74b]
;    bit 5,a ; does the player have the pokedex?
; case for not having pokdex
;    ld a,$06-1
;    jr z,.storeMenuItemCount
; case for having pokedex
;    ld de,.StartMenuPokedexText
;    call .PrintStartMenuItem
;    ld a,$07-1
;.storeMenuItemCount
    ld a,5
    ld [$cc28],a ; number of menu items
    ld de,.StartMenuPokemonText
    call .PrintStartMenuItem
    ld de,.StartMenuItemText
    call .PrintStartMenuItem
    ld de,$d158 ; player's name
    call .PrintStartMenuItem
    ld a,[$d72e]
    bit 6,a ; is the player using the link feature?
; case for not using link feature
    ld de,.StartMenuSaveText
    jr z,.printSaveOrResetText
; case for using link feature
    ld de,.StartMenuResetText
.printSaveOrResetText
    call .PrintStartMenuItem
    ld de,.StartMenuOptionText
    call .PrintStartMenuItem
    ld hl,$d730
    res 6,[hl] ; turn pauses between printing letters back on
    ret

;.StartMenuPokedexText
;    db "POKéDEX@"

.StartMenuPokemonText
    db "POKéMON@"

.StartMenuItemText
    db "ITEM@"

.StartMenuSaveText
    db "SAVE@"

.StartMenuResetText
    db "RESET@"

.StartMenuOptionText
    db "OPTION@"

.PrintStartMenuItem
    push hl
    call PlaceString
    pop hl
    ld de,$28
    add hl,de
    ret

