DrainHPEffect_:
    ld de,W_DAMAGE+1
    ld hl,wBattleValueToPrint+1
    ld a,[de]
    ld [hld],a
    dec de
    ld a,[de]
    ld [hl],a
    srl a
    ld [hli],a
    ld a,[hl]
    rr a
    ld [hld],a
    or [hl]
    jr nz,.getAttackerHP
; if damage is 0, increase to 1 so that the attacker gains at least 1 HP
    inc hl
    inc [hl]
.getAttackerHP
    ld hl,W_PLAYERMONCURHP ; $d015
    ld de,W_PLAYERMONMAXHP ; $d023
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.addDamageToAttackerHP
    ld hl,W_ENEMYMONCURHP ; $cfe6
    ld de,W_ENEMYMONMAXHP ; $cff4
.addDamageToAttackerHP
    ld bc,wHPBarOldHP+1
; copy current HP to wHPBarOldHP
    ld a,[hli]
    ld [bc],a
    ld a,[hl]
    dec bc
    ld [bc],a
; copy max HP to wHPBarMaxHP
    ld a,[de]
    dec bc
    ld [bc],a
    inc de
    ld a,[de]
    dec bc
    ld [bc],a
; add damage to attacker's HP and copy new HP to wHPBarNewHP
    ld a,[wBattleValueToPrint+1]
    ld b,[hl]
    add b
    ld [hld],a
    ld [wHPBarNewHP],a
    ld a,[wBattleValueToPrint]
    ld b,[hl]
    adc b
    ld [hli],a
    ld [wHPBarNewHP+1],a
    jr c,.capToMaxHP ; if HP > 65,535, cap to max HP
; compare HP with max HP
    ld a,[hld]
    ld b,a
    ld a,[de]
    dec de
    sub b
    ld a,[hli]
    ld b,a
    ld a,[de]
    inc de
    sbc b
    jr nc,.next
.capToMaxHP
    ld a,[de]
    ld [hld],a
    ld [wHPBarNewHP],a
    dec de
    ld a,[de]
    ld [hli],a
    ld [wHPBarNewHP+1],a
    inc de
.next
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    FuncCoord 10,09 ; Player Bar in Battle
    ld hl,Coord
    ld a,$1
    jr z,.next2
    FuncCoord 02,02 ; Enemy Bar in Battle
    ld hl,Coord
    xor a
.next2
    ld [wListMenuID],a ; $cf94
    ld d,h
    ld e,l
    call SetCureDuringAbsorb
    PREDEF DrawPlayerHUDAndHPBar
    PREDEF DrawEnemyHUDAndHPBar
    BANKSWITCH ReadPlayerMonCurHPAndStatus
    ld hl,.SuckedHealthText
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    ld a,[W_PLAYERMOVEEFFECT] ; $cfd3
    jr z,.next3
    ld a,[W_ENEMYMOVEEFFECT] ; $cfcd
.next3
    cp DREAM_EATER_EFFECT
    jr nz,.printText
    ld hl,.DreamWasEatenText
.printText
    jp PrintText
.SuckedHealthText
    TX_FAR _SuckedHealthText
    db "@"
.DreamWasEatenText
