HandleIVAndLevelAndLoadRenameScreenDuringPartyRenameScreen:
    push de
    ld a,[wWhichPokemon] ; Pokemon Party Order
    ld hl,W_PARTYMON1_IV
    ld bc,44 ; Pokemon Data Lenght
    call AddNTimes
    call SetTempIV
    ld bc,W_PARTYMON1_LEVEL-W_PARTYMON1_IV
    add hl,bc
    ld a,[hl]
    ld [wTmpLevel],a
    pop hl
    call LoadRenameScreen
    jp ResetTempIV

PrintGenderAndLevelInRenameScreen:
    add hl,bc
    push bc
    ld a,[wTmpLevel]
    ld [$cfb9],a
    call PrintLevel
    xor a
    ld [wTmpLevel],a
    push hl ; Backup Coord
    ld a,[$cf91] ; Pokemon ID
    ld [$d11e],a
    BANKSWITCH GetGender
    ld a,$7F ; Blank
    jr c,.End ; Genderless
    ld a,$EF ; Male
    jr nz,.End ; Male
    ld a,$F5 ; Female
.End
    pop hl ; Restore Coord
    ld [hl],a
    pop bc
    ret

; During Battle clear Pokemon Stat and Change Palette to avoid Yes/No bad Palette Border
HidePlayerBattleHudAndStandarizePaletteBeforeRenameInBattle:
