.Done
    ld hl,DoYouWantToNicknameText ; $6557
    ret

; Format:
; 00: text box ID
; 01: column of upper left corner
; 02: row of upper left corner
; 03: column of lower right corner
; 04: row of lower right corner
TextBoxCoordTable:
    db $01,0,12,19,17
    db $03,0,0,19,14
    db $07,0,0,11,6
    db $0d,4,2,19,12 ; Item Menù
    db $10,7,0,19,17
    db $11,6,4,14,13
    db $77,4,2+5,19,12+5 ; Item Menù during Battle

    db $ff ; terminator

PrintDenimVersionAndSaveScreenTilesToBuffer2:
    ld a,[wFlagGameBoyColor]
    cp $11
    jr nz,.done
    ld de,.GBC
    FuncCoord 0,0
    ld hl,Coord
    ld b,1
    call .Loop
.done
    FuncCoord 12,0
    ld hl,Coord
    ld de,.Version
    ld b,8
    call .Loop
    jp SaveScreenTilesToBuffer2
.Loop
    ld a,[de]
    ld [hli],a
    inc de
    dec b
    jr nz,.Loop
    ret
.Version
    VERSION
.GBC
    db $41

GetQtyAndGiveItem:
