    ld de,Coord
    FuncCoord 19,02
    ld a,[Coord]
    cp $7B ; Upper Right Corner
    jr nz,.skip2
    FuncCoord 09,01
    ld de,Coord
    jr .skip2
.skip1
    ld a,[H_CURRENTPRESSEDBUTTONS]
    bit 3,a ; ▼▲◄►StSeBA
    jr nz,.skip3
.skip2
    PREDEF PrintMoveDetailsBox
.skip3

