    jr nz,.asm_9508
    ld a,d
    call Func_9876
.asm_9508
    pop bc
    pop de

Music2_notelength: ; 0x950a
    ld a,d
    push af
    and $f
    inc a
    ld b,$0
    ld e,a  ; store note length (in 16ths)
    ld d,b
    ld hl,$c0c6
