    ld a,d
    ld hl,$c0b6
    add hl,bc
    ld [hl],a
    ld hl,$c036
    add hl,bc
    bit 0,[hl]
    jr nz,Music2_notepitch
    ld hl,$c02e
    add hl,bc
    bit 2,[hl]
    jr z,Music2_notepitch
    pop hl
    ret

Music2_notepitch: ; 0x9568
    pop af
    and $f0
    cp $c0 ; compare to rest
    jr nz,.notRest
    ld a,c
    cp CH4
    jr nc,.sfxChannel
