CheckForceBikeOrSurf: ; c38b (3:438b)
    ld hl,$D732
    bit 5,[hl]
    ret nz
    ld hl,ForcedBikeOrSurfMaps
    ld a,[W_YCOORD]
    ld b,a
    ld a,[W_XCOORD]
    ld c,a
    call GetCurrentOldAdventureMap
    ld d,a
.loop
    ld a,[hli]
    cp $ff
    ret z ;if we reach FF then it's not part of the list
    cp d ;compare to current map
    jr nz,.incorrectMap
    ld a,[hli]
    cp b ;compare y-coord
    jr nz,.incorrectY
    ld a,[hli]
    cp c ;compare x-coord
    jr nz,.loop ; incorrect x-coord,check next item
    call GetCurrentOldAdventureMap
    cp SEAFOAM_ISLANDS_4
    ld a,$2
    ld [W_SEAFOAMISLANDS4CURSCRIPT],a
    jr z,.forceSurfing
    call GetCurrentOldAdventureMap
    cp SEAFOAM_ISLANDS_5
    ld a,$2
    ld [W_SEAFOAMISLANDS5CURSCRIPT],a
    jr z,.forceSurfing
    ;force bike riding
    ld hl,$d732
    set 5,[hl]
    ld a,$1
    ld [$d700],a
    ld [$d11a],a
    jp ForceBikeOrSurf
.incorrectMap
    inc hl
.incorrectY
    inc hl
    jr .loop
.forceSurfing
    ld a,$2
    ld [$d700],a
    ld [$d11a],a
    jp ForceBikeOrSurf

