    dec a
.compareXCoords
    cp b
    jr z,.failure
.nextSprite2
    dec c
    jr z,.success
    add hl,de
    jr .pushingHorizontallyLoop
.failure
    ld a,$ff
    ret
.success
    xor a
    ret
.IsSpriteVisible
    push hl
    push de
    ld de,-$0102 ; Go from $c214 to $c112
    add hl,de
    ld a,[hl]
    inc a ; Is $FF = Not Visible?
    pop de
    pop hl
    ret

