SentNewMonToBox_ResetMovePPs:
    call ResetMovePPs_
    xor a     ; Reset Move 2/3 PP
    ld [de],a ; ...
    dec de    ; ...
    ld [de],a ; ...
    inc de    ; ...
    ret

CopyDataSkipEnergyAltForm:
    ld bc,5
    call CopyData
    inc hl
    inc hl
    xor a     ; Reset EX Type 1
    ld [de],a ; ...
    inc de
    ld [de],a ; ...
    inc de
    ld bc,5
    jp CopyData

CheckItemOnActive:
    ld a,[W_ISINBATTLE]
    and a
    ret z ; z if not in battle
    ld a,[wPlayerMonNumber]
    ld b,a
    ld a,[$cf92]
    cp b
    ret ; z if active mon is choice in battle

SurfingCryAndGetSurfingGotOnText:
    ld a,[$d152]
    and a ; using surfboard?
    jr z,.skip
    ld a,[wSkillMonID]
    ld [wSurfingMonID],a
    call PlayCryAndDecreaseSkillEnergy
    call IsSurfingOnLapras
    ld hl,.SurfingOnLaprasText
    ret z
.skip
    ld hl,.SurfingGotOnText
    ret
.SurfingOnLaprasText:
    TX_FAR _SurfingOnLaprasText
    db "@"
.SurfingGotOnText
    TX_FAR _SurfingGotOnText
    db "@"

GetEndSurfText:
    call IsSurfingOnLapras
    ld hl,.EndSurfOnLaprasText
    ret z
    ld hl,.EndSurfText
    ret
.EndSurfOnLaprasText:
    TX_FAR _EndSurfOnLaprasText
    db "@"
.EndSurfText
    TX_FAR _EndSurfText
    db "@"

SurfingAttemptFailed:
    ld hl,ItemUseFailed
    push hl ; return pointer
    ld a,[wSkillMonID]
    cp LAPRAS
    ld hl,NoSurfingHereText
    ret nz
    ld hl,.NoSurfingOnLaprasHereText
    ret
.NoSurfingOnLaprasHereText
    TX_FAR _NoSurfingOnLaprasHereText
    db "@"

ItemUseBengal:
    ld a,[W_ISINBATTLE]
    and a
    jp nz,ItemUseNotTime
    ; Check Surfing
    ld a,[$d700]
    cp 2 ; Surfing?
    jr nz,.SurfingCheckOK
    call IsSurfingOnLapras
    jr z,.SurfingCheckOK
    ld hl,.PrintNoLightInWater
    call RunOnlyIfNotSelectInOverworld
    xor a
    ld [$cd6a],a ; item use failed
    ret
.SurfingCheckOK
    ld a,[$d152]
    and a ; is using mon's light
    jr nz,.skip
    call ItemUseReloadOverworldData
    ld hl,wOverworlLightSoundBit4
    set 4,[hl]
    jr .end
.skip
    ld hl,PlayCryAndDecreaseSkillEnergy
    call RunOnlyIfNotSelectInOverworld
.end
    ld hl,wOverworlLightAnimBit0
    set 0,[hl]
    ld hl,wOverworldGoToDarkBit4
    res 4,[hl]
    ld a,1
    ld [$cd6a],a ; item use success
    ret
.PrintNoLightInWater
    ld hl,.NoLightInWaterText
    jp PrintText
.NoLightInWaterText
    TX_FAR _NoLightInWaterText
    db "@"

ItemUsePokedex:
    ld a,[W_ISINBATTLE]
    and a
    jr nz,.battle
    PREDEF DisplayPokedexMenu_
    ret
.battle
    PREDEF ShowBattlePokedex
    xor a        ; Force item use failed
    ld [$cd6a],a ; to do not consume turn during battle
    ld hl,wBattlePokedexUsedBit5
    set 5,[hl] ; Don't consume turn
    ret

NUM_OF_STORED_BLOCKS EQU 15

BackupChangedBlocks:
    push hl
    ld d,h
    ld e,l
    ld hl,wChangedBlocksNum
    ld a,[hli]
    and a
    jr z,.insert
    ld b,a
    ld c,0
.loop
    ld a,[hli] ; H
    cp d
    jr nz,.next1
    ld a,[hli] ; L
    cp e
    jr nz,.next2
.found
    ld a,[hl]
    ld b,a
    ld a,[$d09f]
    cp b
    ld [hl],a ; ID
    jr .done
.next1
    inc hl
.next2
    inc hl
    inc c
    dec b
    jr nz,.loop
    ld a,c
    cp NUM_OF_STORED_BLOCKS
    call nc,.overflow
.insert
    ld a,d
    ld [hli],a ; H
    ld a,e
    ld [hli],a ; L
    ld a,[$d09f] ; NewTileBlockID
    ld [hl],a ; ID
    ld hl,wChangedBlocksNum
    inc [hl]
    ld a,1 ; reset all flag
    or a   ; ...
.done
    pop hl
    ret

.overflow
    push de
    ld hl,wChangedBlocksNum
    dec [hl]
    inc hl
    ld d,h
    ld e,l
    inc de
    inc de
    inc de
    ld b,NUM_OF_STORED_BLOCKS - 1
.LoopOverflow
    ld a,[de]
    ld [hli],a
    inc de
    ld a,[de]
    ld [hli],a
    inc de
    ld a,[de]
    ld [hli],a
    inc de
    dec b
    jr nz,.LoopOverflow
    pop de
    ret

CheckCutTile: ;joenote - consolidate this into its own function
    ld a,[W_CURMAPTILESET]
    and a
    jr z,.overworld
    cp 7
    jr z,.gym
    cp 23 ;added plateau
    jr z,.plateau
    ret ;nz if not one of the listed tilesets
.gym
    ld a,[$cfc6]
    cp $50 ; gym cut tree
    jr z,.loadCutTile
    ret ;nz if not a cuttable tile
.plateau
    ld a,[$cfc6]
    cp $45 ; grass
    jr z,.loadCutTile
    ret ;nz if not a cuttable tile
.overworld
    ld a,[$cfc6]
    cp $3d ; cut tree
    jr z,.loadCutTile
    cp $52 ; grass
    jr z,.loadCutTile
    ret ;nz if not a cuttable tile
.loadCutTile
    ld [$cd4d],a ; CutTile
    ret ;z already set at this return

