    cp $ff          ; end of list
    ret z
    push hl
    inc hl
    ld a,[hl]
    cp Hide
    jr nz,.asm_f19d
    ld hl,W_MISSABLEOBJECTFLAGS_NEW
    ld a,[$d048]
    ld c,a
    ld b,$1
    call HandleBitArray2 ; set flag if Item is hidden
.asm_f19d
    ld hl,$d048
    inc [hl]
    pop hl
    inc hl
    inc hl
    jr .missableObjectsLoop

