SECTION "ItemUseBall",ROMX[$5687],BANK[$3]

ItemUseBall: ; d687 (3:5687)
    ld a,[W_ISINBATTLE]
    and a
    jp z,ItemUseNotTime ; not in battle
    dec a
    jp nz,ThrowBallAtTrainerMon
    ld a,[W_BATTLETYPE]
    dec a
    jr z,.UseBall
    ld a,[W_NUMINPARTY]    ;is Party full?
    cp 6
    jr nz,.UseBall
    ld a,[W_NUMINBOX]    ;is Box full?
    cp 20
    jp z,BoxFullCannotThrowBall
.UseBall    ;$56a7
;ok,you can use a ball
    xor a
    ld [$d11c],a
    ld a,[W_BATTLETYPE]
    cp 2        ;SafariBattle
    jr nz,.skipSafariZoneCode
.safariZone
    push af
    ; remove a Safari Ball from inventory
    ld hl,W_NUMSAFARIBALLS
    dec [hl]
    pop af
.skipSafariZoneCode    ;$56b6
    jr z,.skipNotSafariZoneCode
    ld hl,$cf91 ; Backup BALL ID
    ld a,[hl]   ; ...
    push af     ; ...
    push hl     ; ...
    call ReDrawBattleHudAfterItemUse
    pop hl      ; Restore BALL ID
    pop af      ; ...
    ld [hl],a   ; ...
.skipNotSafariZoneCode
    ld a,$43
    ld [$d11e],a
    ld hl,ItemUseText00
    call PrintText
    call IsGhostBattle
    ld b,$10
    jp z,.next12
    ld a,[W_BATTLETYPE]
    dec a
    jr nz,.notOldManBattle
.oldManBattle
    ld hl,W_GRASSRATE
    ld de,W_PLAYERNAME
    ld bc,11
    call CopyData ; save the player's name in the Wild Monster data (part of the Cinnabar Island Missingno glitch)
    jp .BallSuccess    ;$578b
.notOldManBattle    ;$56e9
    call GetCurrentOldAdventureMap
    cp POKEMONTOWER_6
    jr nz,.loop
    ld a,[W_ENEMYMONID]
    cp MAROWAK
    ld b,$10
    jp z,.next12
; if not fighting ghost Marowak,loop until a random number in the current
; pokeball's allowed range is found
.loop    ;$56fa
    call GenRandom
    ld b,a
    ld hl,$cf91
    ld a,[hl]
    cp MASTER_BALL
    jp z,.BallSuccess    ;$578b
    cp POKE_BALL
    jr z,.checkForAilments
    ld a,200
    cp b
    jr c,.loop    ;get only numbers <= 200 for Great Ball
    ld a,[hl]
    cp GREAT_BALL
    jr z,.checkForAilments
    ld a,150    ;get only numbers <= 150 for Ultra Ball
    cp b
    jr c,.loop
.checkForAilments    ;$571a
; pokemon can be caught more easily with any (primary) status ailment
; Frozen/Asleep pokemon are relatively even easier to catch
; for Frozen/Asleep pokemon,any random number from 0-24 ensures a catch.
; for the others,a random number from 0-11 ensures a catch.
    push bc
    call GetStatusFactor ; Get d
    pop af
    sub d
    jp c,.BallSuccess
    ld b,a
    push bc        ;save RANDOM number
    xor a
    ld [H_MULTIPLICAND],a
    ld hl,W_ENEMYMONMAXHP
    ld a,[hli]
    ld [H_MULTIPLICAND + 1],a
    ld a,[hl]
    ld [H_MULTIPLICAND + 2],a
    ld a,255
    ld [H_MULTIPLIER],a
    call Multiply    ; MaxHP * 255
    ld a,[$cf91]
    cp GREAT_BALL
    ld a,12        ;any other BallFactor
    jr nz,.next7
    ld a,8
.next7    ;$574d
    ld [H_DIVISOR],a
    ld b,4        ; number of bytes in dividend
    call Divide
    ld hl,W_ENEMYMONCURHP
    ld a,[hli]
    ld b,a
    ld a,[hl]

; explanation: we have a 16-bit value equal to [b << 8 | a].
; This number is divided by 4. The result is 8 bit (reg. a).
; Always bigger than zero.
    srl b
    rr a
    srl b
    rr a ; a = current HP / 4
    and a
    jr nz,.next8
    inc a
.next8    ;$5766
    ld [H_DIVISOR],a
    ld b,4
    call Divide    ; ((MaxHP * 255) / BallFactor) / (CurHP / 4)
    ld a,[H_QUOTIENT + 2]
    and a
    jr z,.next9
    ld a,255
    ld [H_QUOTIENT + 3],a
.next9    ;$5776
    pop bc
    ld a,[$d007]    ;enemy: Catch Rate
    cp b
    jr c,.next10
    ld a,[H_QUOTIENT + 2]
    and a
    jr nz,.BallSuccess ; if ((MaxHP * 255) / BallFactor) / (CurHP / 4) > 0x255,automatic success
    call GenRandom
    ld b,a
    ld a,[H_QUOTIENT + 3]
    cp b
    jr c,.next10
.BallSuccess    ;$578b
    jr .BallSuccess2
.next10    ;$578d
    ld a,[H_QUOTIENT + 3]
    ld [$d11e],a
    xor a
    ld [H_MULTIPLICAND],a
    ld [H_MULTIPLICAND + 1],a
    ld a,[$d007]    ;enemy: Catch Rate
    ld [H_MULTIPLICAND + 2],a
    ld a,100
    ld [H_MULTIPLIER],a
    call Multiply    ; CatchRate * 100
    ld a,[$cf91]
    ld b,255
    cp POKE_BALL
    jr z,.next11
    ld b,200
    cp GREAT_BALL
    jr z,.next11
    ld b,150
    cp ULTRA_BALL
    jr z,.next11
.next11    ;$57b8
    ld a,b
    ld [H_DIVISOR],a
    ld b,4
    call Divide
    ld a,[H_QUOTIENT + 2]
    and a
    ld b,$63
    jr nz,.next12
    ld a,[$d11e]
    ld [H_MULTIPLIER],a
    call Multiply
    ld a,255
    ld [H_DIVISOR],a
    ld b,4
    call Divide
    call GetStatusFactor ; Get e
    ld a,[H_QUOTIENT + 3]
    add e
    ld [H_QUOTIENT + 3],a
    cp 10
    ld b,$20
    jr c,.next12
    cp 30
    ld b,$61
    jr c,.next12
    cp 70
    ld b,$62
    jr c,.next12
    ld b,$63
.next12    ;$5801
    ld a,b
    ld [$d11e],a
.BallSuccess2    ;$5805
    ld c,20
    call DelayFrames
    ld a,TOSS_ANIM
    ld [W_ANIMATIONID],a
    xor a
    ld [$fff3],a
    ld [$cc5b],a
    ld [$d05b],a
    ld a,[$cf92]
    push af
    ld a,[$cf91]
    push af
    PREDEF MoveAnimation ; probably animations
    pop af
    ld [$cf91],a
    pop af
    ld [$cf92],a
    ld a,[$d11e]
    cp $10
    ld hl,ItemUseBallText00
    jp z,.printText0
    cp $20
    ld hl,ItemUseBallText01
    jp z,.printText0
    cp $61
    ld hl,ItemUseBallText02
    jp z,.printText0
    cp $62
    ld hl,ItemUseBallText03
    jp z,.printText0
    cp $63
    ld hl,ItemUseBallText04
    jp z,.printText0
    ld hl,$cfe6    ;current HP
    ld a,[hli]
    push af
    ld a,[hli]
    push af        ;backup currentHP...
    inc hl
    ld a,[hl]
    push af        ;...and status ailments
    push hl
    call HandleBackupAfterBallCatch
    ld a,[$cf91]
    push af
    ld a,[W_ENEMYMONID]
    ld [$cf91],a
    ld a,[$cff3]
    ld [$d127],a
    BANKSWITCH LoadEnemyMonData
    pop af
    ld [$cf91],a
    pop hl
    pop af
    ld [hld],a
    dec hl
    pop af
    ld [hld],a
    pop af
    ld [hl],a
    ld a,[$cfe5]    ;enemy
    ld [$cf91],a
    ld [$d11e],a
    call FlagExitBattle ; Denim,ld [$d11c],a
    ld a,[W_BATTLETYPE]
    dec a
    jr z,.printText1
    PREDEF IndexToPokedex ; convert order: Internal->Dex
;    ld a,[$d11e]
;    ld c,a
;    ld b,2
    ld hl,wPokedexOwned    ;Dex_own_flags (pokemon)
;    PREDEF HandleBitArray    ;check Dex flag (own already or not)
;    ld a,c
;    push af
    ld a,[$d11e]
    ld c,a
    ld b,1
    PREDEF HandleBitArray ; set Dex_own_flag?
    BANKSWITCH DrawEnemyHUDAndHPBar
    call StopAlarmAndLoadCaughtText ; ld hl,ItemUseBallText05
    call PrintText
;    pop af
;    and a
;    jr nz,.checkParty
;    ld hl,ItemUseBallText06
;    call PrintText
;    call CleanLCD_OAM
;    ld a,[$cfe5]    ;caught mon_ID
;    ld [$d11e],a
;    PREDEF ShowPokedexData
;.checkParty    ;$58f4
    ld a,[W_NUMINPARTY]
    cp 6        ;is party full?
    jr z,.sendToBox
    xor a
    ld [$cc49],a
    call CleanLCD_OAM
    call AddPokemonToParty    ;add mon to Party
    ld hl,wNoExpToLastPartyMonBit1
    set 1,[hl]
    jr .End
.sendToBox    ;$5907
    call CleanLCD_OAM
    call SendNewMonToBox
    ld hl,ItemUseBallText07
    ld a,[$d7f1]
    bit 0,a        ;already met Bill?
    jr nz,.sendToBox2
    ld hl,ItemUseBallText08
.sendToBox2    ;$591a
    call PrintText
    jr .End
.printText1    ;$591f
    call StopAlarmAndLoadCaughtText ; ld hl,ItemUseBallText05
.printText0    ;$5922
    call PrintText
    call CleanLCD_OAM
.End    ;$5928
    ld a,[W_BATTLETYPE]
    and a
    ret nz
    ld hl,wNumBagItems
    inc a
    ld [$cf96],a
    jp RemoveItemFromInventory    ;remove ITEM (XXX)

;joenote - undo brn/par stat changes for Full Restore after restoring HP in battle
UndoBurnParStats_FullRestore:
    push hl
    push de
    ld a,[H_WHOSETURN]
    push af
    xor a    ;forcibly set it to the player's turn
    ld [H_WHOSETURN],a
    ;undo brn/par stat changes
    ld d,%0000101 ; bit 0 = attack | bit 2 = speed
    PREDEF UndoBurnParStats
    pop af
    ld [H_WHOSETURN],a
    pop de
    pop hl
    ret

HandleBackupAfterBallCatch:
    ld hl,W_ENEMYBATTSTATUS3
    bit 3,[hl]
    jr nz,.justTransformed
    set 3,[hl]
    call BackupMoves
    call BackupPP
    ld hl,$cceb
    ld a,[W_ENEMYMONATKDEFIV]
    ld [hli],a
    ld a,[W_ENEMYMONSPDSPCIV]
    ld [hl],a
.justTransformed
    ld a,[W_ENEMYMONENERGY]   ; Backup Current Energy
    ld [wBackupEnemyEnergy],a ; ...
    ret

; Free

SECTION "ItemUseBallText00",ROMX[$5937],BANK[$3]

ItemUseBallText00: ; d937 (3:5937)
;"It dodged the thrown ball!"
;"This pokemon can't be caught"
