ItemUseTownMap: ; d968 (3:5968)
    ld a,[W_ISINBATTLE]
    and a
    jp nz,ItemUseNotTime
    BANKSWITCH_JUMP DisplayTownMap ; display Town Map

ItemUseBicycle: ; d977 (3:5977)
    ld a,[W_ISINBATTLE]
    and a
    jp nz,ItemUseNotTime
    ld a,[$d700]
    ld [$d11a],a
    cp 2 ; is the player surfing?
    jp z,ItemUseNotTime
    dec a ; is player already bicycling?
    jr nz,.tryToGetOnBike
.getOffBike
    call ItemUseReloadOverworldData
    xor a
    ld [$d700],a ; change player state to walking
    ds 3 ; call PlayDefaultMusic ; play walking music
    ld hl,GotOffBicycleText
    jr .printText
.tryToGetOnBike
    call IsBikeRidingAllowed
    jp nc,NoCyclingAllowedHere
    call ItemUseReloadOverworldData
    xor a ; no keys pressed
    ld [H_CURRENTPRESSEDBUTTONS],a ; current joypad state
    inc a
    ld [$d700],a ; change player state to bicycling
    ld hl,GotOnBicycleText
    ds 3 ; call PlayDefaultMusic ; play bike riding music
.printText
    jp PrintText

; used for Surf out-of-battle effect
ItemUseSurfboard: ; d9b4 (3:59b4)
    ld a,[W_ISINBATTLE]
    and a
    jp nz,ItemUseNotTime
    ld hl,.HandleSurfboardCheck
    call RunOnlyIfNotSelectInOverworld
    jr z,.tryToStopSurfing
    jp c,SurfingAttemptFailed
.surf
    call .makePlayerMoveForward
    ld hl,$d730
    set 7,[hl]
    ld a,2
    ld [$d700],a ; change player state to surfing
    ld hl,$d728 ; Disable Strength
    res 0,[hl]  ; ...
    call CheckDisableLightDuringFloat
    call PlayDefaultMusicFadeOutCurrent ; call PlayDefaultMusic ; play surfing music
    ld hl,.HandleSurfboardTextMessage
    jp RunOnlyIfNotSelectInOverworld
.tryToStopSurfing
    xor a
    ld [$ff8c],a
    ld d,16 ; talking range in pixels (normal range)
    call IsSpriteInFrontOfPlayer2
    res 7,[hl]
    ld a,[$ff8c]
    and a ; is there a sprite in the way?
    jr nz,.cannotStopSurfing
    ld d,%00000100 ; CanSurfing
    call CheckExceptionTilePassable
    jr c,.cannotStopSurfing
    ld hl,W_TILESETCOLLISIONPTR ; pointer to list of passable tiles
    ld a,[hli]
    ld h,[hl]
    ld l,a ; hl now points to passable tiles
    ld a,[$cfc6] ; tile in front of the player
    ld b,a
.passableTileLoop
    ld a,[hli]
    cp b
    jr z,.stopSurfing
    cp $ff
    jr nz,.passableTileLoop
.cannotStopSurfing
    ld hl,SurfingNoPlaceToGetOffText
    jr .PrintText
.stopSurfing
    call .makePlayerMoveForward
    ld hl,$d730
    set 7,[hl]
    xor a
    ld [$d700],a ; change player state to walking
;    dec a
;    ld [wJoypadForbiddenButtonsMask],a
    call PlayDefaultMusicFadeOutCurrent ; call PlayDefaultMusic ; play walking music
    call GetEndSurfText
    jr .PrintText
; uses a simulated button press to make the player move forward
.makePlayerMoveForward
    ld a,[$d52a] ; direction the player is going
    bit 3,a
    ld b,%01000000 ; Up key
    jr nz,.storeSimulatedButtonPress
    bit 2,a
    ld b,%10000000 ; Down key
    jr nz,.storeSimulatedButtonPress
    bit 1,a
    ld b,%00100000 ; Left key
    jr nz,.storeSimulatedButtonPress
    ld b,%00010000 ; Right key
.storeSimulatedButtonPress
    ld a,b
    ld [$ccd3],a ; base address of simulated button presses
    xor a
    ld [$cd39],a
    inc a
    ld [$cd38],a ; index of current simulated button press
    ret
.HandleSurfboardCheck
    ld a,[$d700]
    ld [$d11a],a
    cp 2 ; is the player already surfing?
    ret z; jr z,.tryToStopSurfing
.tryToSurf
    call IsNextTileShoreOrWater
    ret c ; jp c,SurfingAttemptFailed
    ld d,%00000100 ; CanSurfing
    call CheckExceptionTilePassable
    ret c ; jp c,SurfingAttemptFailed
    ld hl,wCollisionWithSpriteBit5
    bit 5,[hl]
    jr nz,.NoFloat
    ld a,1
    or a ; reset all flag
    ret
.NoFloat
    ld a,1
    or a ; reset all flag
    scf
    ret
.HandleSurfboardTextMessage
    call SurfingCryAndGetSurfingGotOnText
.PrintText
    jp PrintText

ItemUseEvoStone:
    ld a,[W_ISINBATTLE]
    and a
    jp nz,ItemUseNotTime
    BANKSWITCH_JUMP ItemUseEvoStone_

ItemUseVitamin:
    ld a,[W_ISINBATTLE]
    and a
    jp nz,ItemUseNotTime
    ; ft

ItemUseMedicine:
    ld a,[W_NUMINPARTY]
    and a
    jr z,.emptyParty
    ld a,[$cf92]
    push af
    ld a,[$cf91]
    push af
    ld a,$01
    ld [$d07d],a ; item use party menu
    ld a,$ff
    ld [$cfcb],a
    ld a,[$d152]
    and a ; using Softboiled?
    jr z,.notUsingSoftboiled
; if using softboiled
    call GoBackToPartyMenu
    jr .getPartyMonDataAddress
.emptyParty
    ld hl,.EmptyPartyText
    xor a
    ld [$cd6a],a ; item use failed
    jp PrintText
.EmptyPartyText
    TX_FAR _EmptyPartyText
    db "@"
.MustChoiceActiveText
    TX_FAR _MustChoiceActiveText
    db "@"
.notUsingSoftboiled
    call DisplayPartyMenu
.getPartyMonDataAddress
    jp c,.canceledItemUse
    call CheckItemOnActive
    jr z,.continue ; continue if not in battle or if active mon is choice in battle
    pop af
    ld [$cf91],a
    pop af
    ld [$cf92],a
    ld hl,.MustChoiceActiveText
    call PrintText
.forceAnotherChoice
    jr ItemUseMedicine ; force another choice
.continue
    ld hl,W_PARTYMON1DATA
    ld bc,44
    ld a,[$cf92]
    call AddNTimes
    ld a,[$cf92]
    ld [$cf06],a
    ld d,a
    ld a,[$cf91]
    ld e,a
    ld [$d0b5],a
    pop af
    ld [$cf91],a
    pop af
    ld [$cf92],a
    ld a,[$d152]
    and a ; using Softboiled?
    jr z,.checkItemType
; if using softboiled
    ld a,[$cf92]
    cp d ; is the pokemon trying to use softboiled on itself?
    jr z,.forceAnotherChoice ; if so,force another choice
.checkItemType
    ld a,[$cf91]
    cp REVIVE
    jp nc,.healHP ; if it's a Revive or Max Revive
    cp FULL_HEAL
    jr z,.cureStatusAilment ; if it's a Full Heal
    cp HP_UP
    jp nc,.useVitamin ; if it's a vitamin or Rare Candy
    cp FULL_RESTORE
    jp nc,.healHP ; if it's a Full Restore or one of the potions
; ft if it's one of the status-specifc healing items
.cureStatusAilment
    ld bc,4
    add hl,bc ; hl now points to status
    call CheckFaintenedFromStatusPointer
    ld a,[$cf91]
    jp z,.healingItemNoEffect
    ld bc,$f008
    cp ANTIDOTE
    jr z,.checkMonStatus
    ld bc,$f110
    cp BURN_HEAL
    jr z,.checkMonStatus
    ld bc,$f220
    cp ICE_HEAL
    jr z,.checkMonStatus
    ld bc,$f307
    cp AWAKENING
    jr z,.checkMonStatus
    ld bc,$f440
    cp PARLYZ_HEAL
    jr z,.checkMonStatus
    ld bc,$f6ff ; Full Heal
.checkMonStatus
    ld a,[hl] ; pokemon's status
    and c ; does the pokemon have a status ailment the item can cure?
    jp z,.healingItemNoEffect
; if the pokemon has a status the item can heal
    ld a,c
    cpl ; Complement A register. (Flip all bits.)
    ld c,a
    ld a,[hl] ; pokemon's status
    and c ; reset only status ailment the item can cure?
    ld [hl],a ; remove the status ailment in the party data
    ld a,b
    ld [$d07d],a ; the message to display for the item used
    ld a,[W_ISINBATTLE]
    and a
    jp z,.doneHealing
    ld a,[wPlayerMonNumber]
    cp d ; is pokemon the item was used on active in battle?
    jp nz,.doneHealing
; if it is active in battle
    push hl ; Backup status ailment in the party data
    ld a,[H_WHOSETURN] ; Backup Turn
    push af            ; ...
    xor a              ; Force player turn
    ld [H_WHOSETURN],a ; ...
    push de
    ld d,%00000000 ; initialize all Flags Zero
    bit BRN_Bit,c
    jr nz,.SkipBrnFlag
    set 0,d ; bit 0 = attack
.SkipBrnFlag
    bit PAR_Bit,c
    jr nz,.SkipParFlag
    set 2,d ; bit 2 = speed
.SkipParFlag
    PREDEF UndoBurnParStats
    pop de
    pop af             ; Restore Turn
    ld [H_WHOSETURN],a ; ...
    pop hl ; Restore status ailment in the party data
    ld a,[hl]
    ld [W_PLAYERMONSTATUS],a ; remove the status ailment in the in-battle pokemon data
    bit PSN_Bit,a
    jr nz,.SkipRemoveToxic
    xor a
    ld [W_PLAYERTOXICCOUNTER],a ; clear toxic counter
    ld hl,W_PLAYERBATTSTATUS3
    res BADLY_POISONED,[hl] ; heal Toxic status
.SkipRemoveToxic
    jp .doneHealing
.healHP
    inc hl ; hl = address of current HP
    ld a,[hli]
    ld b,a
    ld [wHPBarOldHP+1],a
    ld a,[hl]
    ld c,a
    ld [wHPBarOldHP],a ; current HP stored at $ceeb (2 bytes,big-endian)
    or b
    jr nz,.notFainted
.fainted
    ld a,[$cf91]
    cp REVIVE
    jr z,.updateInBattleFaintedData
    cp MAX_REVIVE
    jr z,.updateInBattleFaintedData
    jp .healingItemNoEffect
.updateInBattleFaintedData
    ld a,[W_ISINBATTLE]
    and a
    jr z,.compareCurrentHPToMaxHP
    jp .healingItemNoEffect
.notFainted
    ld a,[$cf91]
    cp REVIVE
    jp z,.healingItemNoEffect
    cp MAX_REVIVE
    jp z,.healingItemNoEffect
.compareCurrentHPToMaxHP
    push hl
    push bc
    ld bc,32
    add hl,bc ; hl now points to max HP
    pop bc
    ld a,[hli]
    cp b
    jr nz,.skipComparingLSB ; no need to compare the LSB's if the MSB's don't match
    ld a,[hl]
    cp c
.skipComparingLSB
    pop hl
    jr nz,.notFullHP
.fullHP ; if the pokemon's current HP equals its max HP
    ld a,[$cf91]
    cp FULL_RESTORE
    jp nz,.healingItemNoEffect
    inc hl
    inc hl
    ld a,[hld] ; status ailment
    and a ; does the pokemon have a status ailment?
    jp z,.healingItemNoEffect
    ld a,FULL_HEAL
    ld [$cf91],a
    dec hl
    dec hl
    dec hl
    jp .cureStatusAilment
.notFullHP ; if the pokemon's current HP doesn't equal its max HP
    xor a
    ld [$d083],a
    ld [$c02a],a
    push hl
    push de
    ld bc,32
    add hl,bc ; hl now points to max HP
    ld a,[hli]
    ld [wHPBarMaxHP+1],a
    ld a,[hl]
    ld [wHPBarMaxHP],a ; max HP stored at $cee9 (2 bytes,big-endian)
    ld a,[$d152]
    and a ; using Softboiled?
    jp z,.notUsingSoftboiled2
; if using softboiled
    call PlayCryAndDecreaseSkillEnergy
    ld hl,wHPBarMaxHP
    ld a,[hli]
    push af
    ld a,[hli]
    push af
    ld a,[hli]
    push af
    ld a,[hl]
    push af
    ld hl,W_PARTYMON1_MAXHP
    ld a,[$cf92]
    ld bc,44
    call AddNTimes
    ld a,[hli]
    ld [$ceea],a
    ld [H_DIVIDEND],a
    ld a,[hl]
    ld [wHPBarMaxHP],a
    ld [H_DIVIDEND + 1],a
    ld a,5
    ld [H_DIVISOR],a
    ld b,2 ; number of bytes
    call Divide ; get 1/5 of max HP of pokemon that used Softboiled
    ld bc,-33
    add hl,bc ; hl now points to LSB of current HP of pokemon that used Softboiled
; subtract 1/5 of max HP from current HP of pokemon that used Softboiled
    ld a,[H_QUOTIENT + 3]
    push af
    ld b,a
    ld a,[hl]
    ld [wHPBarOldHP],a
    sub b
    ld [hld],a
    ld [wHPBarNewHP],a
    ld a,[H_QUOTIENT + 2]
    ld b,a
    ld a,[hl]
    ld [wHPBarOldHP+1],a
    sbc b
    ld [hl],a
    ld [wHPBarNewHP+1],a
    FuncCoord 4+7,1 ; Spostata HP Bar Durante Softboiled
    ld hl,Coord
    ld a,[$cf92]
    ld bc,2 * 20
    call AddNTimes ; calculate coordinates of HP bar of pokemon that used Softboiled
    ld a,$8d
    call PlaySoundWaitForCurrent ; play sound
    ld a,[$fff6]
    set 0,a
    ld [$fff6],a
    ld a,$02
    ld [$cf94],a
    PREDEF UpdateHPBar ; animate HP bar decrease of pokemon that used Softboiled
    ld a,[$fff6]
    res 0,a
    ld [$fff6],a
    pop af
    ld b,a ; store heal amount (1/5 of max HP)
    ld hl,$ceec
    pop af
    ld [hld],a
    pop af
    ld [hld],a
    pop af
    ld [hld],a
    pop af
    ld [hl],a
    jr .addHealAmount
.notUsingSoftboiled2
    ld a,[$cf91]
    cp SODA_POP
    ld b,60 ; Soda Pop heal amount
    jr z,.addHealAmount
    ld b,80 ; Lemonade heal amount
    jr nc,.addHealAmount
    cp FRESH_WATER
    ld b,50 ; Fresh Water heal amount
    jr z,.addHealAmount
    cp SUPER_POTION
    ld b,200 ; Hyper Potion heal amount
    jr c,.addHealAmount
    ld b,50 ; Super Potion heal amount
    jr z,.addHealAmount
    ld b,20 ; Potion heal amount
.addHealAmount
    pop de
    pop hl
    ld a,[hl]
    add b
    ld [hld],a
    ld [wHPBarNewHP],a
    ld a,[hl]
    ld [wHPBarNewHP+1],a
    jr nc,.noCarry
    inc [hl]
    ld a,[hl]
    ld [$ceee],a
.noCarry
    push de
    inc hl
    ld d,h
    ld e,l ; de now points to current HP
    ld hl,33
    add hl,de ; hl now points to max HP
    ld a,[$cf91]
    cp REVIVE
    jr z,.setCurrentHPToHalfMaxHP
    ld a,[hld]
    ld b,a
    ld a,[de]
    sub b
    dec de
    ld b,[hl]
    ld a,[de]
    sbc b
    jr nc,.setCurrentHPToMaxHp ; if current HP exceeds max HP after healing
    ld a,[$cf91]
    cp HYPER_POTION
    jr c,.setCurrentHPToMaxHp ; if using a Full Restore or Max Potion
    cp MAX_REVIVE
    jr z,.setCurrentHPToMaxHp ; if using a Max Revive
    jr .updateInBattleData
.setCurrentHPToHalfMaxHP
    dec hl
    dec de
    ld a,[hli]
    ld a,0 ; 1 HP ; srl a
    ld [de],a
    ld [wHPBarNewHP+1],a
    ld a,[hl]
    ld a,1 ; 1 HP ;  rr a
    inc de
    ld [de],a
    ld [wHPBarNewHP],a
    dec de
    jr .doneHealingPartyHP
.setCurrentHPToMaxHp
    ld a,[hli]
    ld [de],a
    ld [wHPBarNewHP+1],a
    inc de
    ld a,[hl]
    ld [de],a
    ld [wHPBarNewHP],a
    dec de
.doneHealingPartyHP ; done updating the pokemon's current HP in the party data structure
    ld a,[$cf91]
    cp FULL_RESTORE
    jr nz,.updateInBattleData
    ld bc,-31
    add hl,bc
    ld a,[W_ISINBATTLE]
    and a
    call nz,UndoBurnParStats_FullRestore
    xor a
    ld [hl],a ; remove the status ailment in the party data
.updateInBattleData
    ld h,d
    ld l,e
    pop de
    ld a,[wPlayerMonNumber]
    cp d ; is pokemon the item was used on active in battle?
    jr nz,.calculateHPBarCoords
; copy party HP to in-battle HP
    ld a,[hli]
    ld [W_PLAYERMONCURHP],a
    ld a,[hld]
    ld [W_PLAYERMONCURHP + 1],a
    ld a,[$cf91]
    cp FULL_RESTORE
    jr nz,.calculateHPBarCoords
    xor a
    ld [W_PLAYERMONSTATUS],a ; remove the status ailment in the in-battle pokemon data
.calculateHPBarCoords
    ld hl,$c390+7 ; Spostate Coordinate Barra HP Durante Cura
    ld bc,2 * 20
    inc d
.calculateHPBarCoordsLoop
    add hl,bc
    dec d
    jr nz,.calculateHPBarCoordsLoop
    jr .doneHealing
.healingItemNoEffect
    call ItemUseNoEffect
    jp .done
.doneHealing
    ld a,[$d152]
    and a ; using Softboiled?
    jr nz,.skipRemovingItem ; no item to remove if using Softboiled
    push hl
    call RemoveUsedItem
    pop hl
.skipRemovingItem
    ld a,[$cf91]
    cp FULL_RESTORE
    jr c,.playStatusAilmentCuringSound
    cp FULL_HEAL
    jr z,.playStatusAilmentCuringSound
    ld a,$8d ; HP healing sound
    call PlaySoundWaitForCurrent ; play sound
    ld a,[$fff6]
    set 0,a
    ld [$fff6],a
    ld a,$02
    ld [$cf94],a
    PREDEF UpdateHPBar ; animate the HP bar lengthening
    ld a,[$fff6]
    res 0,a
    ld [$fff6],a
    ld a,$f7 ; revived message
    ld [$d07d],a
    ld a,[$cf91]
    cp REVIVE
    jr z,.showHealingItemMessage
    cp MAX_REVIVE
    jr z,.showHealingItemMessage
    ld a,$f5 ; standard HP healed message
    ld [$d07d],a
    jr .showHealingItemMessage
.playStatusAilmentCuringSound
    ld a,$8e ; status ailment curing sound
    call PlaySoundWaitForCurrent ; play sound
.showHealingItemMessage
    xor a
    ld [H_AUTOBGTRANSFERENABLED],a
    call ClearScreen
    dec a
    ld [$cfcb],a
    call RedrawPartyMenu ; redraws the party menu and displays the message
    ld a,1
    ld [H_AUTOBGTRANSFERENABLED],a
    ld c,50
    call DelayFrames
    call WaitForTextScrollButtonPress ; wait for a button press
    jr .done
.canceledItemUse
    xor a
    ld [$cd6a],a ; item use failed
    pop af
    pop af
.done
    ld a,[$d152]
    and a ; using Softboiled?
    ret nz ; if so,return
    call GBPalWhiteOut
    call z,GoPAL_SET_CF1C
    ld a,[W_ISINBATTLE]
    and a
    ret nz
    jp ReloadMapData ; restore saved screen
.useVitamin
    push hl
    ld a,[hl]
    ld [$d0b5],a
    ld [$d11e],a
    ld bc,33
    add hl,bc ; hl now points to level
    ld a,[hld] ; a = level
    ld [$d127],a ; store level
    dec hl
    dec hl ; hl now points to move2pp
    ld a,[hl]
    ld [wAlternateFormIndex],a
    call GetMonHeader
    push de
    ld a,d
    ld hl,W_PARTYMON1NAME
    call GetPartyMonName
    pop de
    pop hl
    ld a,[$cf91]
    cp RARE_CANDY
    jp z,.useRareCandy
    push hl
    sub a,HP_UP
    add a
    ld bc,17
    add hl,bc
    add l
    ld l,a
    jr nc,.noCarry2
    inc h
.noCarry2
    ld a,30
    ld b,a
    ld a,[hl] ; a = MSB of stat experience of the appropriate stat
    cp 247 ; is there already at least 63232 (256 * 253) stat experience?
    jr nc,.vitaminNoEffect ; if so,vitamins can't add any more
    add b ; add 7680 (256 * 30) stat experience
    jr nc,.noCarry3 ; a carry should be impossible here,so this will always jump
    ld a,255
.noCarry3
    ld [hl],a
    pop hl
    call .recalculateStats
    ld hl,.VitaminText
    ld a,[$cf91]
    sub a,HP_UP - 1
    ld c,a
.statNameLoop ; loop to get the address of the name of the stat the vitamin increases
    dec c
    jr z,.gotStatName
.statNameInnerLoop
    ld a,[hli]
    ld b,a
    ld a,$50
    cp b
    jr nz,.statNameInnerLoop
    jr .statNameLoop
.gotStatName
    ld de,$cf4b
    ld bc,10
    call CopyData ; copy the stat's name to $cf4b
    ld a,$8e
    call PlaySound ; play sound
    ld hl,.VitaminStatRoseText
    call PrintText
    jp RemoveUsedItem
.vitaminNoEffect
    pop hl
    ld hl,.VitaminNoEffectText
    call PrintText
    jp GBPalWhiteOut
.recalculateStats
    ld bc,34
    add hl,bc
    ld d,h
    ld e,l ; de now points to stats
    ld bc,-18
    add hl,bc ; hl now points to byte 3 of experience
    ld b,1
    jp CalcStats ; recalculate stats
.useRareCandy
    push hl
    ld bc,33
    add hl,bc ; hl now points to level
    ld a,[hl] ; a = level
    cp 100
    jr z,.vitaminNoEffect ; can't raise level above 100
    ld [$cd46],a ; ($cd46 = wTempCoins1) - fixing skip move-learn glitch: need to store the current level in wram
                 ; wTempCoins1 was chosen because it's used only for slot machine and gets defaulted to 1 during the mini-game
    inc a
    ld [hl],a ; store incremented level
    ld [$d127],a
    push hl
    push de
    ld d,a
    BANKSWITCH CalcExperience ; calculate experience for next level and store it at $ff96
    pop de
    pop hl
    ld bc,-19
    add hl,bc ; hl now points to experience
; update experience to minimum for new level
    ld a,[$ff96]
    ld [hli],a
    ld a,[$ff97]
    ld [hli],a
    ld a,[$ff98]
    ld [hl],a
    pop hl
    ld a,[$cf92]
    push af
    ld a,[$cf91]
    push af
    push de
    push hl
    ld bc,34
    add hl,bc ; hl now points to MSB of max HP
    ld a,[hli]
    ld b,a
    ld c,[hl]
    pop hl
    push bc
    push hl
    call .recalculateStats
    pop hl
    ld bc,35 ; hl now points to LSB of max HP
    add hl,bc
    pop bc
    ld a,[hld]
    sub c
    ld c,a
    ld a,[hl]
    sbc b
    ld b,a ; bc = the amount of max HP gained from leveling up
; add the amount gained to the current HP
    ld de,-32
    add hl,de ; hl now points to MSB of current HP
    ld a,[hl]
    add c
    ld [hld],a
    ld a,[hl]
    adc b
    ld [hl],a
    ld a,$f8 ; level up message
    ld [$d07d],a
    call RedrawPartyMenu
    pop de
    ld a,d
    ld [$cf92],a
    ld a,e
    ld [$d11e],a
    xor a
    ld [$cc49],a ; load from player's party
    call PartyMenuHPAndStandarizePalette ; call LoadMonData
    ld d,$01
    BANKSWITCH PrintStatsBox ; display new stats text box
    call WaitForTextScrollButtonPress ; wait for button press
    xor a
    ld [$cc49],a
    PREDEF LearnMoveFromLevelUp
    xor a
    ld [$ccd4],a
    BANKSWITCH TryEvolvingMon ; evolve pokemon,if appropriate
    ld a,$01
    ld [$cfcb],a
    pop af
    ld [$cf91],a
    pop af
    ld [$cf92],a
    jp RemoveUsedItem
.VitaminStatRoseText
    TX_FAR _VitaminStatRoseText
    db "@"
.VitaminNoEffectText
    TX_FAR _VitaminNoEffectText
    db "@"
.VitaminText
    db "HEALTH@"
    db "ATTACK@"
    db "DEFENSE@"
    db "SPEED@"
    db "SPECIAL@"

ItemUseBait:
    ld hl,ThrewBaitText
    call PrintText
    ld hl,$d007 ; catch rate
    srl [hl] ; halve catch rate
    ld a,BAIT_ANIM
    ld hl,$cce9 ; bait factor
    ld de,$cce8 ; escape factor
    jr BaitRockCommon

ItemUseRock:
    ld hl,ThrewRockText
    call PrintText
    ld hl,$d007 ; catch rate
    ld a,[hl]
    add a ; double catch rate
    jr nc,.noCarry
    ld a,$ff
.noCarry
    ld [hl],a
    ld a,ROCK_ANIM
    ld hl,$cce8 ; escape factor
    ld de,$cce9 ; bait factor

BaitRockCommon:
    ld [W_ANIMATIONID],a
    xor a
    ld [$cc5b],a
    ld [H_WHOSETURN],a
    ld [de],a ; zero escape factor (for bait),zero bait factor (for rock)
.randomLoop ; loop until a random number less than 5 is generated
    call GenRandom
    and a,7
    cp 5
    jr nc,.randomLoop
    inc a ; increment the random number,giving a range from 1 to 5 inclusive
;joenote - There is a bug here.
; - The 1-to-5 number is always decremented when PrintSafariZoneBattleText runs.
; - So getting a number of 1 will decrement immediately to zero and do nothing to the eating/angry state.
; - To get an effective 1-to-5 turns, increment once more to bump the range to 2-to-6
    inc a
    ld b,a
    ld a,[hl]
    add b ; increase bait factor (for bait),increase escape factor (for rock)
    jr nc,.noCarry
    ld a,$ff
.noCarry
    ld [hl],a
    PREDEF MoveAnimation
    jp RockDamageOrBaitHealth

ThrewBaitText:
    TX_FAR _ThrewBaitText
    db "@"

ThrewRockText:
    TX_FAR _ThrewRockText
    db "@"

; also used for Dig out-of-battle effect
ItemUseAuger:
    call CanDig
    jp nc,ItemUseFailed
    call CheckDiglettsCaveHole
    ret c
    ld hl,$d732
    set 3,[hl]
    set 6,[hl]
    ld hl,$d72e
    res 4,[hl]
    ld hl,$d790
    res 7,[hl] ; unset Safari Zone bit
    xor a
    ld [$da47],a
    ld [W_SAFARIZONEENTRANCECURSCRIPT],a
    inc a
    ld [$d078],a
    ld [$cd6a],a ; item used
    call UsingDigCry ; ld a,[$d152]
    and a ; using Dig?
    ret nz ; if so,return
    call ItemUseReloadOverworldData
    ld c,30
    jp DelayFrames

CanDig:
    ld a,[W_ISINBATTLE]
    and a
    ld hl,ItemUseNotTimeText
    jr nz,.Cant
    ; Check Surfing
    ld a,[$d700]
    cp 2 ; Surfing?
    ld hl,.CantDigDuringFloatText
    jr z,.Cant
    ld a,[W_CURMAPTILESET]
    cp $11 ; Cave
    jr z,.Can
    call GetCurrentOldAdventureMap
    cp VIRIDIAN_FOREST
    ld hl,.cannotDigHereText
    jr nz,.Cant
    ; ft
.Can
    scf
    ret
.Cant
    and a ; rcf
    ret

.CantDigDuringFloatText
    TX_FAR _CantDigDuringFloatText
    db "@"
.cannotDigHereText
    TX_FAR _CannotDigHereText
    db "@"

SECTION "ItemUseRepel",ROMX[$6003],BANK[$3]

ItemUseRepel: ; e003 (3:6003)
    ld b,100

ItemUseRepelCommon: ; e005 (3:6005)
    ld a,[W_ISINBATTLE]
    and a
    jp nz,ItemUseNotTime
    ld a,b
