    jp PrintItemUseTextAndRemoveItem

; handles X Accuracy item
ItemUseXAccuracy: ; e013 (3:6013)
    ld a,[W_ISINBATTLE]
    and a
    jp z,ItemUseNotTime
    ld hl,W_PLAYERBATTSTATUS2
    set 0,[hl] ; X Accuracy bit
    ; ft

SimpleBattleItemEnd:
    call ReDrawBattleHudAfterItemUse
