LoadFluteSprite:
    ld a,$8e
    call PlaySound ; play sound
    ld c,90
    call DelayFrames
    ld hl,$d736
    set 6,[hl]
    ld de,RedSprite ; $4180
    ld hl,$8000
    ld bc,(BANK(RedSprite) << 8) + $0c
    call CopyVideoData
    ld a,4
    ld hl,.UnknownFluteAnim
    ld bc,0
.loop
    push af
    push bc
    push hl
    add hl,bc
    ld a,[hli]
    ld e,a
    ld a,[hli]
    ld d,a
    ld a,[hli]
    ld c,a
    ld a,[hli]
    ld b,a
    ld a,[hli]
    ld h,[hl]
    ld l,a
    call CopyVideoData
    pop hl
    pop bc
    ld a,6
    add c
    ld c,a
    pop af
    dec a
    jr nz,.loop
    ld hl,$d736
    res 6,[hl]
    ret
.UnknownFluteAnim
INCBIN "baserom.gbc",$70866,$7087e - $70866

ItemUseGuardSpec:
    ld a,[W_ISINBATTLE]
    and a
    jp z,ItemUseNotTime
    ld hl,W_PLAYERBATTSTATUS2
    set 1,[hl] ; Mist bit
    jp SimpleBattleItemEnd

ItemUseSuperRepel:
