    jp ItemUseRepelCommon

ItemUseDireHit:
    ld a,[W_ISINBATTLE]
    and a
    jp z,ItemUseNotTime
    ld hl,W_PLAYERBATTSTATUS2
    set 2,[hl] ; Focus Energy bit
