ItemUseXStat:
    ld a,[W_ISINBATTLE]
    and a
    jp z,ItemUseNotTime
    ld hl,W_PLAYERMOVENUM
    ld a,[hli]
    push af ; save [W_PLAYERMOVENUM]
    ld a,[hl]
    push af ; save [W_PLAYERMOVEEFFECT]
    push hl
    ld a,[$cf91]
    sub a,X_ATTACK - ATTACK_UP1_EFFECT
    ld [hl],a ; store player move effect
    call SimpleBattleItemEnd
    ld a,XSTATITEM_ANIM ; X stat item animation ID
    ld [W_PLAYERMOVENUM],a
    xor a
    ld [H_WHOSETURN],a ; set turn to player's turn
    BANKSWITCH StatModifierUpEffect ; do stat increase move
    pop hl
    pop af
    ld [hld],a ; restore [W_PLAYERMOVEEFFECT]
    pop af
    ld [hl],a ; restore [W_PLAYERMOVENUM]
    ret

; Free

SECTION "ItemUsePokeflute",ROMX[$6140],BANK[$3]

ItemUsePokeflute: ; e140 (3:6140)
    ld a,[W_ISINBATTLE]
    cp 2
.ItemUseNotTime
    jp z,ItemUseNotTime ; Trainer Battle

    ; Init Context
    and a
    jr nz,.BattleContext

    ; Check Surfing
    ld a,[$d700]
    cp 2 ; Surfing?
    jr z,.ItemUseNotTime

    call ItemUseReloadOverworldData
    jr .ContextDone
.BattleContext
    call ReDrawBattleHudAfterItemUse
.ContextDone

    ; Play Flute
    ld hl,.PlayedFluteHadEffectText
    call PrintText

    ; Wake Up Entire Party
    xor a
    ld [$cd3d],a ; initialize variable that indicates if any pokemon were woken up to zero
    ld b,~SLP & $FF
    ld hl,W_PARTYMON1_STATUS
    call WakeUpEntireParty

    ld a,[W_ISINBATTLE]
    and a
    jr z,.NotInBattle

.inBattle
    ld hl,W_PLAYERMONSTATUS
    ld a,[hl]
    and b ; remove Sleep status
    ld [hl],a
    ld hl,W_ENEMYMONSTATUS
    ld a,[hl]
    push af
    and a,SLP ; is pokemon asleep?
    jr z,.notAsleep
    ld a,1
    ld [$cd3d],a ; indicate that a pokemon had to be woken up
.notAsleep
    pop af
    and b ; remove Sleep status
    ld [hl],a
    jr .PrintFluteResult

.NotInBattle
    call .PrintFluteResult
    call ItemUseReloadOverworldData
    call GetCurrentOldAdventureMap
    cp ROUTE_12
    jr nz,.notRoute12
    ld a,[$d7d8]
    bit 7,a ; has the player beaten Route 12 Snorlax yet?
    ret nz
; if the player hasn't beaten Route 12 Snorlax
    ld hl,Route12SnorlaxFluteCoords
    call ArePlayerCoordsInArray
    ret nc
    ld hl,$d7d8
    set 6,[hl] ; trigger Snorlax fight (handled by map script)
    ret
.notRoute12
    cp ROUTE_16
    jr nz,.notRoute16
    ld a,[$d7e0]
    bit 1,a ; has the player beaten Route 16 Snorlax yet?
    ret nz
; if the player hasn't beaten Route 16 Snorlax
    ld hl,Route16SnorlaxFluteCoords
    call ArePlayerCoordsInArray
    ret nc
    ld hl,$d7e0
    set 0,[hl] ; trigger Snorlax fight (handled by map script)
    ret
.notRoute16
    cp DIGLETTS_CAVE
    ret nz
    ld a,[wEventBeatAerodactylBit5]
    bit 5,a ; has the player beaten Diglett's Cave Aerodactyl yet?
    ret nz
; if the player hasn't beaten Diglett's Cave Aerodactyl
    ld a,[$d35d]
    and a ; if it's not dark
    ret nz
    call ArePlayerNearAerodactyl
    ret nc
    ld a,4 ; DiglettsCaveBeforeAerodactyl
    ld [W_GENERICMAPCURSCRIPT],a ; trigger Aerodactyl fight
    ret

.PrintFluteResult
    ld a,[$cd3d]
    and a ; were any pokemon asleep before playing the flute?
    ret z
    ld hl,.FluteWokeUpText
    jp DrawHudAndPrintTextPokeFlute

.FluteWokeUpText
    TX_FAR _FluteWokeUpText
    db "@"

.PlayedFluteHadEffectText
    TX_FAR _PlayedFluteHadEffectText
    db $08
    ld a,[W_ISINBATTLE]
    and a
    jr nz,.MusicInBattle
; play out-of-battle pokeflute music
    call LoadFluteSprite
    ld a,$ff
    call PlaySound ; turn off music
    ld a,(SFX_02_5e - $4000) / 3
    ld c,BANK(SFX_02_5e)
    call PlayMusic ; play music
.musicWaitLoop1 ; wait for music to finish playing
    ld a,[$c028]
    cp $b8
    jr z,.musicWaitLoop1
    call PlayDefaultMusic ; start playing normal music again
    jr .done
.MusicInBattle
    ld a,[$d083]
    and a,$80
    jr nz,.BattleAlarm
    call WaitForSoundToFinish ; wait for sound to end
    BANKSWITCH Music_PokeFluteInBattle ; play in-battle pokeflute music
.musicWaitLoop2 ; wait for music to finish playing
    ld a,[$c02c]
    and a ; music off?
    jr nz,.musicWaitLoop2
.done
    jp TextScriptEnd ; end text
.BattleAlarm
    ld c,50
    call DelayFrames
    jr .done

SECTION "ItemUseOldRod",ROMX[$623a],BANK[$3]

ItemUseOldRod:
    call FishingInit
    jp c,ItemUseNotTime
    call GetOldRodData ; ld hl,OldRodData
    ld a,[W_CURMAP]
    ld de,1 ; each fishing group is one byte wide
    call IsInArray
    jr c,.Magikarp
    ld a,$2 ; $2 if no fishing groups found
    jr RodResponse
.Magikarp
    ld bc,(1 << 8) | MAGIKARP ; Entry Point
    ld a,$1 ; set bite
    jr RodResponse

ItemUseGoodRod:
    call FishingInit
    jp c,ItemUseNotTime
    call GetGoodRodData_DE ; ld de,GoodRodData
    jr ItemUseRodCommon

ItemUseSuperRod:
    call FishingInit
    jp c,ItemUseNotTime
    call GetSuperRodData_DE ; ld de,SuperRodData

ItemUseRodCommon:
    call ReadRodData ; 0xe8ea
    ld a,e

RodResponse: ; e28d (3:628d)
    ld [wWhichTrade],a
    dec a ; is there a bite?
    jr nz,.next
    ; if yes,store level and species data
    ld a,1
    ld [$D05F],a
    ld a,b ; level
    call GetBiteLevel ; ld [W_CURENEMYLVL],a
    ld a,c ; species
    ld [W_CUROPPONENT],a ; $d059
    ld [W_ENEMYMONID],a
    BANKSWITCH GetWildEnemyLevel
.next
    ld hl,$D700
    ld a,[hl] ; store the value in a
    push af
    push hl
    ld [hl],0
    BANKSWITCH Func_707b6
    pop hl
    pop af
    ld [hl],a
    ret

; checks if fishing is possible and if so,runs initialization code common to all rods
; unsets carry if fishing is possible,sets carry if not
FishingInit:
    ld a,[W_ISINBATTLE]
    and a
    jr z,.notInBattle
    scf ; can't fish during battle
    ret
.notInBattle
    call IsNextTileShoreOrWater
    ret c
    ld d,%00000100 ; CanSurfing
    call CheckExceptionTilePassable
    ret c
    ld a,[$d700]
    cp 2 ; Surfing?
    jr z,.surfing
    call ItemUseReloadOverworldData
    ld hl,.PrintText
    call RunOnlyIfNotSelectInOverworld
    ld a,$8e
    call PlaySound ; play sound
    ld c,80
    call DelayFrames
    and a
    ret
.surfing
    scf ; can't fish when surfing
    ret
.PrintText
    ld hl,ItemUseText00
    jp PrintText

ItemUseOaksParcel:
    jp ItemUseNotYoursToUse

ItemUseItemfinder:
    ld a,[W_ISINBATTLE]
    and a
    jp nz,ItemUseNotTime
    call ItemUseReloadOverworldData
    BANKSWITCH Func_7481f ; check for hidden items
    jr c,.found
    ld a,$a5 ; Error
    call PlaySoundWaitForCurrent ; play sound
    ld hl,.PrintItemfinderFoundNothing
    jr .printText ; if no hidden items
.found
    ld c,4
.loop
    ld a,$9e
    call PlaySoundWaitForCurrent ; play sound
    ld a,$b2
