ItemUsePPRestore:
    ld a,[W_NUMINPARTY]
    and a
    jr z,.emptyParty
    ld a,[$cf92]
    push af
    ld a,[$cf91]
    push af
    ld [$cd3d],a
.chooseMon
    xor a
    ld [$cfcb],a
    ld a,$01 ; item use party menu
    ld [$d07d],a
    call DisplayPartyMenu
    jr nc,.useEther
    jp .itemNotUsed
.emptyParty
    ld hl,.EmptyPartyText
    xor a
    ld [$cd6a],a ; item use failed
    jp PrintText
.EmptyPartyText
    TX_FAR _EmptyPartyText
    db "@"
.MustChoiceActiveText
    TX_FAR _MustChoiceActiveText
    db "@"
.afterRestoringPP ; after using a (Max) Ether/Elixir
    ld a,$8e
    call PlaySound
    ld a,[hl]
    ld b,a
    ld hl,$d11e
    ld a,[hl]
    push af
    push hl
    ld [hl],b
    FuncCoord 08,01 ; Party Ether Update Energy
    ld hl,Coord
    ld a,[$cf92]
    ld bc,40
    call AddNTimes
    ld de,$d11e
    ld bc,$0103
    call PrintNumber
    pop hl
    pop af
    ld [hl],a
    ld hl,.PPRestoredText
    call PrintText
    pop af
    ld [$cf91],a
    pop af
    ld [$cf92],a
    call GBPalWhiteOut
    call GoPAL_SET_CF1C
    jp RemoveUsedItem
.useEther
    call CheckItemOnActive
    jr z,.continue ; continue if not in battle or if active mon is choice in battle
    pop af
    ld [$cf91],a
    pop af
    ld [$cf92],a
    ld hl,.MustChoiceActiveText
    call PrintText
    jp ItemUsePPRestore ; force another choice
.continue
    call .restorePP
    jr nz,.afterRestoringPP
    jp .noEffect
.restorePP
    ld a,[$cd3d]
    ld b,a
    ld hl,.Table
.next
    ld a,[hli]
    cp $FF
    jr z,.NoEffect
    cp b
    jr z,.found
    inc hl
    jr .next
.found
    ld a,[hl]
    ld d,a ; Amount
    ld [$d11e],a
    ld a,255
    sub d
    inc a
    ld e,a ; Check
    ld hl,W_PARTYMON1_MOVE1PP
    ld bc,44
    ld a,[$cf92]
    call AddNTimes ; hl now points to move's PP
    ld a,[hl] ; Read Energy
    cp 255
    jr z,.NoEffect
    cp e ; Check
    jr c,.LessThenE
    push hl
    ld d,a
    ld a,255
    sub d
    ld hl,$d11e
    ld [hl],a
    pop hl
    ld a,255
    jr .storeNewAmount
.LessThenE
    add d ; Amount
    push hl
    ld hl,$d11e
    ld [hl],d
    pop hl
.storeNewAmount
    ld [hl],a
    push af
    ld a,[W_ISINBATTLE]
    and a
    jr z,.NotInBattleOrNotActiveThanSkip
    ld a,[wPlayerMonNumber]
    ld b,a
    ld a,[$cf92]
    cp b
    jr nz,.NotInBattleOrNotActiveThanSkip
    pop af
    ld [W_PLAYERMONENERGY],a
    jr .end
.NotInBattleOrNotActiveThanSkip
    pop af
.end
    and a
    ret
.Table
    db ETHER,100
    db ELIXER,255
    db $FF
.NoEffect
    xor a
    ret
.noEffect
    call ItemUseNoEffect
.itemNotUsed
    call GBPalWhiteOut
    call GoPAL_SET_CF1C
    pop af
    pop af
    xor a
    ld [$cd6a],a ; item use failed
    ret
.PPRestoredText
    TX_FAR _PPRestoredText
    db "@"

