; Output ► d = Status Factor 1
;        ► e = Status Factor 2
GetStatusFactor:
    ld de,0 ; Initialize Outputs to 0
    ld a,[W_ENEMYMONSTATUS] ;status ailments
    and a
    jr z,.noAilments
    bit FRZ_Bit,a
    jr z,.NotFrz
    ld b,+40
    ld c,+16
    call .IncreaseFactor
    jr .FrzThenSkipSlpBrn
.NotFrz
    ld b,a
    and a,SLP
    ld a,b
    jr z,.NotSlp
    ld b,+25
    ld c,+10
    call .IncreaseFactor
.NotSlp
    bit BRN_Bit,a
    jr z,.NotBrn
    ld b,+12
    ld c,+05
    call .IncreaseFactor
.NotBrn
.FrzThenSkipSlpBrn
    bit PAR_Bit,a
    jr z,.NotPar
    ld b,+12
    ld c,+05
    call .IncreaseFactor
.NotPar
    bit PSN_Bit,a
    jr z,.NotPsn
    ld b,+12
    ld c,+05
    call .IncreaseFactor
.NotPsn
.noAilments
    ret
.IncreaseFactor
    push af
    xor a
    add d
    add b
    ld d,a
    xor a
    add e
    add c
    ld e,a
    pop af
    ret

