; checks if an item is a key item
; INPUT:
; [$cf91] = item ID
; OUTPUT:
; [$d124] = result
; 00: item is not key item
; 01: item is key item
IsKeyItem_: ; e764 (3:6764)
    ld a,$01
    ld [$d124],a
    ld a,[$cf91]
; if the item is not a TM
    push af
    ld hl,.KeyItemBitfield
    ld de,$cee9
    ld bc,15 ; only 11 bytes are actually used
    call CopyData
    pop af
    dec a
    ld c,a
    ld hl,$cee9
    ld b,$02 ; test bit
    PREDEF HandleBitArray ; bitfield operation function
    ld a,c
    and a
    ret nz
    xor a
    ld [$d124],a
    ret
.KeyItemBitfield
    db %11110000
    db %00000001
    db %00110000
    db %01010001
    db %00000000
    db %10010111
    db %00000010
    db %11000000
    db %11110000
    db %00111111
    db %11111000

