    jp nz,ItemUseNotTime
    ld a,[$d152]
    push af
    ld a,[$cf91]
    ld [$d152],a
    push af
    call LoadHpBarAndStatusTilePatterns
    ld a,1
    ld [$ffb7],a
    ld a,[wLastTechMachIdUsed] ; restore last choice
    ld [$cf91],a
    ld hl,wWaitReleaseJoyBit5
    set 5,[hl]
    call GetTMChoiceItemID ; put item_ID in $cf91
    ld a,[$cf91]
    ld [wLastTechMachIdUsed],a ; overwrite last choice
    call c,ItemUseTMHM
    xor a
    ld [$ffb7],a
    pop af
    ld [$cf91],a
    pop af
    ld [$d152],a
    ret

GetTMChoiceItemID:
    cp TM_01 ; less then TM01?
    jr c,.Init
    cp TM_64+1 ; greater then TM_64?
    jr nc,.Init
    call GetTMQty
    jr z,.Init
    push af
    call .PrintBasicLayoutTMChoice
    pop af
    ld hl,$cf91
    jr .start

.Init
    ld hl,wTM
    ld b,((TM_64-TM_01+1) >> 2)+1
.LoopSearchAtLeastOne
    ld a,[hli]
    and a
    jr nz,.AtLeastOne
    dec b
    jr nz,.LoopSearchAtLeastOne
    call PrintTMEmpty
    ; ft

.BPressed
    ld a,2
    ld [$cd6a],a ; item not used
    xor a ; rcf
    ret

.APressed
    scf ; APressed
    ret

.AtLeastOne
    call .PrintBasicLayoutTMChoice
    ld a,TM_01-1
    ld hl,$cf91
    ; ft

.TryNext
    inc a
    cp [hl]
    jr z,.NoChange
    cp TM_64+1
    jr c,.continue1
    ld a,[H_NEWLYPRESSEDBUTTONS] ; No Infinite Loop
    and a                        ; ...
    jr z,.NoChange               ; ...
    ld a,TM_01
.continue1
    call GetTMQty ; input a = TM ID | output c = Qty | z if Qty=0
    jr z,.TryNext
    jr .start

.TryPrev
    dec a
    cp [hl]
    jr z,.NoChange
    cp TM_01
    jr nc,.continue2
    ld a,[H_NEWLYPRESSEDBUTTONS] ; No Infinite Loop
    and a                        ; ...
    jr z,.NoChange               ; ...
    ld a,TM_64
.continue2
    call GetTMQty ; input a = TM ID | output c = Qty | z if Qty=0
    jr z,.TryPrev
    ; ft

.start
    ld [hl],a
    call .ClearScreenArea
    call .GetAndPlaceTMStats
    ; ft

.NoChange
    call .DrawArrows
    ; ft

.getJoypadStateLoop
    call GetJoypadStateLowSensitivityWaitReleaseJoy
    jr nz,.getJoypadStateLoop
    and %11110011 ; ▼▲◄►StSeBA
    jr z,.getJoypadStateLoop
    bit 0,a ; pressed A?
    jr nz,.APressed
    bit 1,a ; pressed B?
    jr nz,.BPressed
    bit 4,a ; pressed Right?
    jr nz,.RightPressed
    bit 5,a ; pressed Left?
    jr nz,.LeftPressed
    bit 6,a ; pressed Up?
    jr nz,.UpPressed
    bit 7,a ; pressed Down?
    jr nz,.DownPressed
    jr .getJoypadStateLoop

.RightPressed
    call .BlinkRightArrow
    ld hl,$cf91
    ld a,[hl]
    jr .TryNext

.LeftPressed
    call .BlinkLeftArrow
    ld hl,$cf91
    ld a,[hl]
    jr .TryPrev

.UpPressed
    call .BlinkRightArrow
    ld hl,$cf91
    ld a,[hl]
    add 6
    cp TM_01
    jr nc,.TryPrev
    ld a,TM_64+1
    jr .TryPrev

.DownPressed
    call .BlinkLeftArrow
    ld hl,$cf91
    ld a,[hl]
    sub 6
    jp .TryNext

.BlinkLeftArrow
    FuncCoord 05,11
    ld hl,Coord
    jp .BlinkArrow

.BlinkRightArrow
    FuncCoord 18,11
    ld hl,Coord
    ; ft

.BlinkArrow
    ld [hl]," "
    jp Delay3

.PrintBasicLayoutTMChoice
    ld hl,.ChoiceTMText
    call PrintText
    FuncCoord 04,10
    ld hl,Coord
    ld bc,$020e ; 02,14
    jp TextBoxBorder

.ClearScreenArea
    FuncCoord 06,11
    ld hl,Coord
    ld bc,$020c ; 02,12
    jp ClearScreenArea

.DrawArrows
    FuncCoord 05,11
    ld hl,Coord
    ld [hl],$D6 ; Arrow Left
    FuncCoord 18,11
    ld hl,Coord
    ld [hl],$ED ; Arrow Right
    ret

.GetAndPlaceTMStats
    FuncCoord 14,12
    ld hl,Coord
    ld de,.X
    call PlaceString
    ld a,[$cf91]
    push af
    ld b,a
    call GetTMQty
    ld a,c
    ld de,$d11e
    ld [de],a
    FuncCoord 15,12
    ld hl,Coord
    ld bc,$0102 ; b=1 | c=2
    call PrintNumber
    pop af
    sub TM_01
    inc a
    ld [$d11e],a
    ld de,$d11e
    FuncCoord 06,12
    ld hl,Coord
    ld bc,$8102 ; b=%10000001 Leading Zeroes | c=2
    call PrintNumber
    PREDEF TMToMove ; get move ID from TM/HM ID
    ld a,[$d11e]
    ld [$d0e0],a
    ld [wPlayerSelectedMove],a
    call GetMoveName
    call CopyStringToCF4B ; copy name to $cf4b
    ld de,$cf4b
    FuncCoord 06,11
    ld hl,Coord
    call PlaceString
    ; Print Move Details Box
    FuncCoord 10,5
    ld de,Coord
    ld hl,wHyperBeamUnknownTypeBit4
    set 4,[hl]
    PREDEF_JUMP PrintMoveDetailsBox

.ChoiceTMText:
    TX_FAR _ChoiceTMText
    db "@"
.X
    db "×@"

DrawBadges:
    BANKSWITCH_JUMP _DrawBadges

GymLeaderFaceAndBadgeTileGraphics:
