ReplaceTileBlockNoRedraw:
    ld hl,wDisableAutoRedrawMapBit5
    set 5,[hl]
    ; ft

; replaces a tile block with the one specified in [$d09f] ; NewTileBlockID
; and redraws the map view if necessary
; b = Y
; c = X
ReplaceTileBlock:
    call Load16BitRegisters
    ld hl,$c6e8 ; OverworldMap
    ld a,[W_CURMAPWIDTH] ; $d369
    add $6
    ld e,a
    ld d,$0
    add hl,de
    add hl,de
    add hl,de
    ld e,$3
    add hl,de
    ld e,a
    ld a,b
    and a
    jr z,.addX
; add width * Y
.addWidthYTimesLoop
    add hl,de
    dec b
    jr nz,.addWidthYTimesLoop
.addX
    add hl,bc
    call BackupChangedBlocks
    ret z ; kickout if same block ID
    ld a,[$d09f] ; NewTileBlockID
    ld [hl],a
    ld a,[$d35f] ; CurrentTileBlockMapViewPointer
    ld c,a
    ld a,[$d360] ; CurrentTileBlockMapViewPointer + 1
    ld b,a
    call CompareHLWithBC
    ret c ; return if the replaced tile block is below the map view in memory
    push hl
    ld l,e
    ld h,$0
    ld e,$6
    ld d,h
    add hl,hl
    add hl,hl
    add hl,de
    add hl,bc
    pop bc
    call CompareHLWithBC
    ret c ; return if the replaced tile block is above the map view in memory
    ld hl,wDisableAutoRedrawMapBit5 ; wMustRedrawMapBlockBit6
    bit 5,[hl]
    res 5,[hl]
    jr z,RedrawMapView
    set 6,[hl]
    ret

TryToRedrawMapView:
    ld hl,wMustRedrawMapBlockBit6
    bit 6,[hl]
    res 6,[hl]
    ret z
    ; ft

RedrawMapView:
    ld a,[W_ISINBATTLE] ; $d057
    inc a
    ret z
    ld a,[H_AUTOBGTRANSFERENABLED] ; $FF00+$ba
    push af
    ld a,[$FF00+$d7] ; TileAnimations
    push af
    xor a
    ld [H_AUTOBGTRANSFERENABLED],a ; $FF00+$ba
    ld [$FF00+$d7],a ; TileAnimations
    call LoadCurrentMapView
    ld hl,$d526 ; MapViewVRAMPointer
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ld de,$ffc0 ; -2 * BG_MAP_WIDTH
    add hl,de
    ld a,h
    and $3
    or $98
    ld a,l
    ld [$cee9],a ; wBuffer
    ld a,h
    ld [$ceea],a ; wBuffer + 1
    ld a,$2
    ld [$FF00+$be],a ; RowOffset
    ld c,$9 ; SCREEN_HEIGHT / 2 ; number of rows of 2x2 tiles (this covers the whole screen)
.redrawRowLoop
    push bc
    push hl
    push hl
    ld hl,$c378 ; wTileMap - 2 * SCREEN_WIDTH
    ld de,$14 ; SCREEN_WIDTH
    ld a,[$FF00+$be] ; RowOffset
.calcWRAMAddrLoop
    add hl,de
    dec a
    jr nz,.calcWRAMAddrLoop
    call ScheduleRowRedrawHelper
    pop hl
    ld de,$20 ; BG_MAP_WIDTH
    ld a,[$FF00+$be] ; RowOffset
    ld c,a
.calcVRAMAddrLoop
    add hl,de
    ld a,h
    and $3
    or $98
    dec c
    jr nz,.calcVRAMAddrLoop
    ld [$FF00+$d2],a ; RedrawRowOrColumnDest + 1
    ld a,l
    ld [H_SCREENEDGEREDRAWADDR],a ; RedrawRowOrColumnDest
    ld a,$2 ; REDRAW_ROW
    ld [H_SCREENEDGEREDRAW],a ; RedrawRowOrColumnMode
    call DelayFrame
    ld hl,$ffbe ; RowOffset
    inc [hl]
    inc [hl]
    pop hl
    pop bc
    dec c
    jr nz,.redrawRowLoop
    pop af
    ld [$FF00+$d7],a ; TileAnimations
    pop af
    ld [H_AUTOBGTRANSFERENABLED],a ; $FF00+$ba
    ret

CompareHLWithBC:
    ld a,h
    sub b
    ret nz
    ld a,l
    sub c
    ret

UsedCut:
    xor a
    ld [$cd6a],a
    call CheckCutTile
    jr nz,.nothingToCut
    ld a,$1
    ld [$cd6a],a
    jr CanCut
.nothingToCut
