    jp PrintText

CanCut:
    ld hl,.HandlePartyMenuToCut
    call RunOnlyIfNotSelectInOverworld
    ld a,[W_CURMAPTILESET]
    cp 23 ; plateau
    jr z,.plateau
    ld a,$ff
    ld [$cfcb],a
    call InitCutAnimOAM
    ld de,CutTreeBlockSwaps ; $7100
