    call RedrawMapView
    BANKSWITCH Func_79e96
    ld a,$1
    ld [$cfcb],a
    ld a,$ac
    call PlaySound
    ld a,$90
    ld [$FF00+$b0],a
    jp UpdateSprites
.plateau
