    ld hl,W_PARTYMON1NAME ; $d2b5
    call GetPartyMonName
    ld hl,$d730
    set 6,[hl]
    call GBPalWhiteOutWithDelay3
    call CleanLCD_OAM
    call RestoreScreenTilesAndReloadTilePatterns
    ld a,$90
    ld [$FF00+$b0],a
    call Delay3
    call LoadGBPal
    call LoadCurrentMapView
    call SaveScreenTilesToBuffer2
    call Delay3
    xor a
    ld [$FF00+$b0],a
    ld hl,UsedCutText ; $6ff2
    call PrintText
    call LoadScreenTilesFromBuffer2
    ld hl,$d730
    res 6,[hl]
    ret

InitCutAnimOAM:
    xor a
    ld [$cd50],a
    ld a,$e4
    ld [rOBP1],a ; $FF00+$49
    ld a,[$cd4d]
    cp $52
    jr z,.asm_f020
    ld de,TreeOAM ; $42d0 ; cuttable tree sprite
    ld hl,$8fc0
    ld bc,(BANK(TreeOAM) << 8) | 04
    call CopyVideoData
    jr asm_f055
.asm_f020
    ld hl,$8fc0
    call .Func_f04c
    ld hl,$8fd0
    call .Func_f04c
    ld hl,$8fe0
    call .Func_f04c
    ld hl,$8ff0
    call .Func_f04c
    call asm_f055
    ld hl,$c393
    ld de,$4
    ld a,$30
    ld c,e
.asm_f044
    ld [hl],a
    add hl,de
    xor $60
    dec c
    jr nz,.asm_f044
    ret
.Func_f04c
    ld de,AnimationTileset2 + $60 ; $474e ; tile depicting a leaf
    ld bc,(BANK(AnimationTileset2) << 8) + $01
    jp CopyVideoData

asm_f055:
    call Func_f068
    ld a,$9
    ld de,UnknownOAM_f060 ; $7060
    jp WriteOAMBlock

DungeonTilesetIDs:
    db $03,$0A,$0D,$10,$11,$12,$13,$0C,$14,$16,$0F,$07
    db $FF

