SECTION "Func_f068",ROMX[$7068],BANK[$3]

Func_f068: ; f068 (3:7068)
    ld hl,$c104
    ld a,[hli]
    ld b,a
    inc hl
    ld a,[hli]
    ld c,a ; bc holds ypos/xpos of player's sprite
    inc hl
    inc hl
    ld a,[hl] ; a holds direction of player (00: down,04: up,08: left,0C: right)
    srl a
    ld e,a
    ld d,$0 ; de holds direction (00: down,02: up,04: left,06: right)
    ld a,[$cd50]
    and a
    ld hl,CutTreeAnimationOffsets ; $708f
    jr z,.asm_f084
    ld hl,BoulderDustAnimationOffsets ; $7097
.asm_f084
    add hl,de
    ld e,[hl]
    inc hl
    ld d,[hl]
    ld a,b
    add d
    ld b,a
    ld a,c
    add e
    ld c,a
    ret

CutTreeAnimationOffsets: ; f08f (3:708f)
; Each pair represents the x and y pixels offsets from the player of where the cut tree animation should be drawn
    db  8,36 ; player is facing down
    db  8,4 ; player is facing up
    db -8,20 ; player is facing left
    db 24,20 ; player is facing right

BoulderDustAnimationOffsets: ; f097 (3:7097)
; Each pair represents the x and y pixels offsets from the player of where the Dust animation should be drawn
; These offsets represent 1 blocks away from the player
    db  8,36 ; player is facing down
    db  8,4 ; player is facing up
    db -8,20 ; player is facing left
    db 24,20 ; player is facing right

ReplaceTreeTileBlock: ; f09f (3:709f)
; Determine the address of the tile block that contains the tile in front of the
; player (i.e. where the tree is) and replace it with the corresponding tile
; block that doesn't have the tree.
    push de
    ld a,[W_CURMAPWIDTH] ; $d369
    add $6
    ld c,a
    ld b,$0
    ld d,$0
    ld hl,$d35f ; CurrentTileBlockMapViewPointer
    ld a,[hli]
    ld h,[hl]
    ld l,a
    add hl,bc
    ld a,[$c109] ; SpritePlayerStateData1FacingDirection
    and a
    jr z,.down
    cp $4 ; SPRITE_FACING_UP
    jr z,.up
    cp $8 ; SPRITE_FACING_LEFT
    jr z,.left
; right
    ld a,[W_XBLOCKCOORD] ; $d364
    and a
    jr z,.centerTileBlock
    jr .rightOfCenter
.down
    ld a,[W_YBLOCKCOORD] ; $d363
    and a
    jr z,.centerTileBlock
    jr .belowCenter
.up
    ld a,[W_YBLOCKCOORD] ; $d363
    and a
    jr z,.aboveCenter
    jr .centerTileBlock
.left
    ld a,[W_XBLOCKCOORD] ; $d364
    and a
    jr z,.leftOfCenter
    jr .centerTileBlock
.belowCenter
    add hl,bc
.centerTileBlock
    add hl,bc
.aboveCenter
    ld e,$2
    add hl,de
    jr .next
.leftOfCenter
    ld e,$1
    add hl,bc
    add hl,de
    jr .next
.rightOfCenter
    ld e,$3
    add hl,bc
    add hl,de
.next
    pop de
    ld a,[hl]
    ld c,a
.loop ; find the matching tile block in the array
    ld a,[de]
    inc de
    inc de
    cp $ff
    ret z
    cp c
    jr nz,.loop
    dec de
;    ld a,[de] ; replacement tile block from matching array entry
;    ld [hl],a
;    ret
    jp BackupChangedBlocks_Cut

CutTreeBlockSwaps: ; f100 (3:7100)
; first byte = tileset block containing the cut tree
; second byte = corresponding tileset block after the cut animation happens
    db $32,$6D
    db $33,$6C
    db $34,$6F
    db $35,$4C
    db $60,$6E
    db $0B,$0A
    db $3C,$35
    db $3F,$35
    db $3D,$36
    db $FF ; list terminator

SetVisitedAndLoadMissableObj:
    call IsCurrentMapTown
    jr nc,.notInTown
    ld c,a
    ld b,$1
    call GetTownVisitedFlag ; ld hl,W_TOWNVISITEDFLAG ; mark town as visited (for flying)
    PREDEF HandleBitArray
.notInTown
    call GetMapHS ; ld de,MapHS
    ld a,[W_CURMAP]
    ld b,a
    ld c,0
    ld de,W_MISSABLEOBJECTLIST
.loop
    ld a,[hli]
    cp $ff
    jr z,.done
    cp b
    jr nz,.next
    ld a,[hli]
    inc hl
    ld [de],a
    inc de
    ld a,c
    inc c
    ld [de],a
    inc de
    jr .loop
.next
    inc c
    inc hl
    inc hl
    jr .loop
.done
    ld a,$ff
    ld [de],a
    ret

; Free

SECTION "InitializeMissableObjectsFlags",ROMX[$7175],BANK[$3]

InitializeMissableObjectsFlags: ; f175 (3:7175)
    ld hl,W_MISSABLEOBJECTFLAGS
    ld bc,$20
    xor a
    call FillMemory ; clear missable objects flags
    ld hl,MapHS
    xor a
    ld [$d048],a
.missableObjectsLoop
    ld a,[hli]
    cp $ff          ; end of list
    ret z
    push hl
    inc hl
    ld a,[hl]
    cp Hide
    jr nz,.asm_f19d
    ld hl,W_MISSABLEOBJECTFLAGS
    ld a,[$d048]
    ld c,a
    ld b,$1
    call HandleBitArray2 ; set flag iff Item is hidden
.asm_f19d
    ld hl,$d048
    inc [hl]
    pop hl
    inc hl
    inc hl
    jr .missableObjectsLoop

; tests if current sprite is a missable object that is hidden/has been removed
IsMissableObjectHidden: ; f1a6 (3:71a6)
    ld a,[H_CURRENTSPRITEOFFSET]
    swap a
    ld b,a
    ld hl,W_MISSABLEOBJECTLIST
.loop
    ld a,[hli]
    cp $ff
    jr z,.notHidden ; not missable -> not hidden
    cp b
    ld a,[hli]
    jr nz,.loop
    ld c,a
    ld b,$2
    call GetMissableObjectFlag ; ld hl,W_MISSABLEOBJECTFLAGS
    call HandleBitArray2
    ld a,c
    and a
    jr nz,.hidden
.notHidden
    xor a
.hidden
    ld [$FF00+$e5],a
    ret

; adds missable object (items,leg. pokemon,etc.) to the map
; [$cc4d]: index of the missable object to be added (global index)
AddMissableObject: ; f1c8 (3:71c8)
    call GetMissableObjectFlag ; ld hl,W_MISSABLEOBJECTFLAGS
    ld a,[$cc4d]
    ld c,a
    ld b,$0
    call HandleBitArray2   ; reset "removed" flag
    jp UpdateSprites

; removes missable object (items,leg. pokemon,etc.) from the map
; [$cc4d]: index of the missable object to be removed (global index)
RemoveMissableObject: ; f1d7 (3:71d7)
    call GetMissableObjectFlag ; ld hl,W_MISSABLEOBJECTFLAGS
    ld a,[$cc4d]
    ld c,a
    ld b,$1
    call HandleBitArray2   ; set "removed" flag
    jp UpdateSprites

; functionally identical to _HandleBitArray,but with less optimized instructions
; executes operations on a field of bits
; b = 0 -> reset bit
; b = 1 -> set bit
; b = 2 -> read bit (into c and z-flag)
; hl: base address
; c: bit index
HandleBitArray2: ; f1e6 (3:71e6)
    push hl
    push de
    push bc
    ld a,c
    ld d,a
    and $7
    ld e,a        ; store bit offset in e
    ld a,d
    srl a
    srl a
    srl a          ; calc byte offset
    add l
    ld l,a
    jr nc,.noCarry
    inc h
.noCarry
    inc e
    ld d,$1
.shiftLeftLoop     ; d = 1 << e,bitmask for the used bit
    dec e
    jr z,.operationSelect
    sla d
    jr .shiftLeftLoop
.operationSelect
    ld a,b
    and a
    jr z,.resetBit
    cp $2
    jr z,.readBit
    ld a,[hl] ; set bit
    ld b,a
    ld a,d
    or b
    ld [hl],a
    jr .done
.resetBit
    ld a,[hl]
    ld b,a
    ld a,d
    xor $ff
    and b
    ld [hl],a
    jr .done
.readBit
    ld a,[hl]
    ld b,a
    ld a,d
    and b
.done
    pop bc
    pop de
    pop hl
    ld c,a
    ret

; Free

SECTION "_AddPokemonToParty",ROMX[$72e5],BANK[$3]

_AddPokemonToParty: ; f2e5 (3:72e5)
; Adds a new mon to the player's or enemy's party.
; [$cc49] is used in an unusual way in this function.
; If the lower nybble is 0, the mon is added to the player's party, else the enemy's.
; If the entire value is 0, then the player is allowed to name the mon.
    ld de,W_NUMINPARTY ; $d163
    ld a,[$cc49]
    and $f
    jr z,.next
    ld de,wEnemyPartyCount ; $d89c
.next
    ld a,[de]
    inc a
    cp $7 ; PARTY_LENGTH+1
    ret nc ; return if the party is already full
    ld [de],a
    ld a,[de]
    ld [$FF00+$e4],a ; NewPartyLength
    add e
    ld e,a
    jr nc,.noCarry
    inc d
.noCarry
    ld a,[$cf91]
    ld [de],a ; write species of new mon in party list
    inc de
    ld a,$ff ; terminator
    ld [de],a
    ld hl,W_PARTYMON1OT ; $d273
    ld a,[$cc49]
    and $f
    jr z,.next2
    ld hl,W_ENEMYMON1OT
.next2
    ld a,[$FF00+$e4] ; NewPartyLength
    dec a
    call SkipFixedLengthTextEntries
    ld d,h
    ld e,l
    ld hl,W_PLAYERNAME ; $d158
    ld bc,$b
    call CopyData
    call InsertIVDuringAddMonToParty
    ld a,[$cc49]
    and a
    jr nz,.skipNaming
    ld hl,W_PARTYMON1NAME ; $d2b5
    ld a,[$FF00+$e4] ; NewPartyLength
    dec a
    call SkipFixedLengthTextEntries
    ld a,$2 ; NAME_MON_SCREEN
    ld [$d07d],a ; NamingScreenType
    PREDEF AskForMonNickname
.skipNaming
    ld hl,W_PARTYMON1_NUM ; $d16b (aliases: W_PARTYMON1DATA)
    ld a,[$cc49]
    and $f
    jr z,.next3
    ld hl,wEnemyMons ; $d8a4
.next3
    ld a,[$FF00+$e4] ; NewPartyLength
    dec a
    ld bc,$2c
    call AddNTimes
    ld e,l
    ld d,h
    push hl
    ld a,[$cf91]
    ld [$d0b5],a
    call GetAlternateForm
    call GetMonHeader
    ld hl,W_MONHEADER
    ld a,[hli]
    ld [de],a
    inc de
    pop hl
    push hl
    ld a,[$cc49]
    and $f
    call GenerateRandomEnemyTrainerIV ; ld a,$98     ; set enemy trainer mon IVs to fixed average values
    ;ds 1                             ; ld b,$88
    jr nz,.writeFreshMonData
    ; If the mon is being added to the player's party, update the pokedex.
    ld a,[$cf91]
    ld [$d11e],a
    push de
    PREDEF IndexToPokedex
    pop de
    ld a,[$d11e]
    ld c,a
    ld b,$2
    ld hl,wPokedexOwned ; $d2f7
    call _HandleBitArray
    ld a,[$d11e]
    ld c,a
    ld b,$1
    push bc
    call _HandleBitArray
    pop bc
    ld hl,wPokedexSeen
    call _HandleBitArray
    pop hl
    push hl
    ld a,[W_ISINBATTLE] ; $d057
    and a ; is this a wild mon caught in battle?
    jr nz,.copyEnemyMonData
    ; Not wild.
    ld a,[wDVForShinySpdSpc] ; call GenRandom
    ld b,a
    ld a,[wDVForShinyAtkDef] ; call GenRandom
.writeFreshMonData ; f3b3
    push bc
    ld bc,$1b ; go to IV
    add hl,bc
    pop bc
    ld [hli],a
    ld [hl],b         ; write IVs
    ld bc,$fff4 ; go to exp
    add hl,bc
    ld a,$1
    ld c,a
    xor a
    ld b,a
    call CalcStat      ; calc HP stat (set cur Hp to max HP)
    ld a,[H_MULTIPLICAND+1]
    ld [de],a
    inc de
    ld a,[H_MULTIPLICAND+2]
    ld [de],a
    inc de
    xor a
    ld [de],a         ; level (?)
    inc de
    ld [de],a         ; status ailments
    inc de
    jr .copyMonTypesAndMoves
.copyEnemyMonData
    ld bc,$1b ; go to IV
    add hl,bc
    ld a,[W_ENEMYMONATKDEFIV] ; copy IVs from cur enemy mon
    ld [hli],a
    ld a,[W_ENEMYMONSPDSPCIV]
    ld [hl],a
    ld a,[W_ENEMYMONCURHP]    ; copy HP from cur enemy mon
    ld [de],a
    inc de
    ld a,[W_ENEMYMONCURHP+1]
    ld [de],a
    inc de
    xor a
    ld [de],a                 ; level (?)
    inc de
    ld a,[W_ENEMYMONSTATUS]   ; copy status ailments from cur enemy mon
    ld [de],a
    inc de
.copyMonTypesAndMoves
    ld h,d
    ld l,e
    xor a
    ld [hli],a ; energy
    ld [hli],a ; alt form
    ld [hli],a ; catch rate (held item in gen 2)
    ld [hli],a ; move 1
    ld [hli],a ; move 2
    ld [hli],a ; move 3
    ld [hli],a ; move 4
    push hl
    dec hl
    dec hl
    dec hl
    dec hl ; go to move 1
    xor a
    ld [wLearningMovesFromDayCare],a
    ld d,h
    ld e,l
    call WriteMonMoves2
    pop hl
    ld a,[wPlayerID]  ; set trainer ID to player ID
    ld [hli],a
    ld a,[wPlayerID + 1]
    ld [hli],a
    push hl
    ld a,[W_CURENEMYLVL]
    ld d,a
    BANKSWITCH CalcExperience
    pop hl
    ld a,[H_MULTIPLICAND] ; write experience
    ld [hli],a
    ld a,[H_MULTIPLICAND+1]
    ld [hli],a
    ld a,[H_MULTIPLICAND+2]
    ld [hl],a
    ld d,h
    ld e,l
    call AddPokemonToParty_SetStatExp
    inc de
    inc de
    call WriteMovePP
    inc de
    ld a,[W_CURENEMYLVL] ; $d127
    ld [de],a
    inc de
    call ResetIVAndCheckIsInBattle ; ld a,[W_ISINBATTLE] ; $d057
    dec a
    jr nz,.calcFreshStats
    ld hl,W_ENEMYMONMAXHP ; $cff4
    ld bc,$a
    call CopyData          ; copy stats of cur enemy mon
    pop hl
    jr .done
.calcFreshStats
    pop hl
    ld bc,$10
    add hl,bc
    ld b,$1 ; Consider also stat exp
    call CalcStatsAndSetCurrentHpToMax ; call CalcStats         ; calculate fresh set of stats
.done
    call AddPokemonToParty_TryToAddExclusiveMove
    scf
    ret

ResetMovePPs:
    call Load16BitRegisters
    ; ft
ResetMovePPs_:
    inc de
    ld a,255
    ld [de],a
    inc de
    ld a,[wTempAlternateFormIndex]
    ld [de],a
    inc de
    xor a
    ;ld [de],a
    inc de
    ;ld [de],a
    ld [wTempAlternateFormIndex],a
    ret

ResetEnemyHPStatusTypeAndPP:
    xor a
    ld hl,W_ENEMYMONSTATUS
    ld [hl],a ; Status
    ld hl,W_ENEMYMONTYPES
    ld [hli],a ; Type 1
    ld [hli],a ; Type 2
    ld [hli],a ; Type 3
    ld [hl],a  ; Type 4
    ld hl,W_ENEMYMONMAXHP
    ld a,[hli]
    ld [W_ENEMYMONCURHP],a
    ld a,[hl]
    ld [W_ENEMYMONCURHP+1],a
    ld a,255
    ld [W_ENEMYMONENERGY],a
    ld hl,W_ENEMYMON_START
    ret

; adds enemy mon [$cf91] (at position [$cf92] in enemy list) to own party
; no known uses in the game
_AddEnemyMonToPlayerParty:
    ld hl,W_NUMINPARTY
    ld a,[hl]
    cp $6
    scf
    ret z            ; party full,return failure
    inc a
    ld [hl],a       ; add 1 to party members
    ld c,a
    ld b,$0
    add hl,bc
    ld a,[$cf91]
    ld [hli],a      ; add mon as last list entry
    ld [hl],$ff     ; write new sentinel
    ld hl,W_PARTYMON1DATA
    ld a,[W_NUMINPARTY]
    dec a
    ld bc,W_PARTYMON2DATA - W_PARTYMON1DATA
    call AddNTimes
    ld e,l
    ld d,h
    ld hl,$cf98
    call CopyData    ; write new mon's data (from $cf98)
    ld hl,W_PARTYMON1OT
    ld a,[W_NUMINPARTY]
    dec a
    call SkipFixedLengthTextEntries
    ld d,h
    ld e,l
    ld hl,W_ENEMYMON1OT
    ld a,[$cf92]
    call SkipFixedLengthTextEntries
    ld bc,$000b
    call CopyData    ; write new mon's OT name (from an enemy mon)
    ld hl,W_PARTYMON1NAME
    ld a,[W_NUMINPARTY]
    dec a
    call SkipFixedLengthTextEntries
    ld d,h
    ld e,l
    ld hl,W_ENEMYMON1NAME
    ld a,[$cf92]
    call SkipFixedLengthTextEntries
    ld bc,$000b
    call CopyData    ; write new mon's nickname (from an enemy mon)
    ld a,[$cf91]
    ld [$d11e],a
    PREDEF IndexToPokedex
    ld a,[$d11e]
    ld c,a
    ld b,$1
    ld hl,wPokedexOwned
    push bc
    call _HandleBitArray ; add to owned pokemon
    pop bc
    ld hl,wPokedexSeen
    call _HandleBitArray ; add to seen pokemon
    and a
    ret                  ; return success

