; predef $10
; executes operations on a field of bits
; b = 0 -> reset bit
; b = 1 -> set bit
; b = 2 -> read bit (into c and z-flag)
; hl: base address
; c: bit index
HandleBitArray: ; f666 (3:7666)
    call Load16BitRegisters

_HandleBitArray: ; f669 (3:7669)
    push hl
    push de
    push bc
    ld a,c
    ld d,a
    and $7
    ld e,a        ; store bit offset in e
    ld a,d
    srl a
    srl a
    srl a          ; calc byte offset
    add l
    ld l,a
    jr nc,.noCarry
    inc h
.noCarry
    inc e
    ld d,$1
.shiftLeftLoop     ; d = 1 << e,bitmask for the used bit
    dec e
    jr z,.operationSelect
    sla d
    jr .shiftLeftLoop
.operationSelect
    ld a,b
    and a
    jr z,.resetBit
    cp $2
    jr z,.readBit
    ld b,[hl] ; set bit
    ld a,d
    or b
    ld [hl],a
    jr .done
.resetBit
    ld b,[hl]
    ld a,d
    xor $ff
    and b
    ld [hl],a
    jr .done
.readBit
    ld b,[hl]
    ld a,d
    and b
.done
    pop bc
    pop de
    pop hl
    ld c,a
    ret

HealParty: ; f6a5 (3:76a5)
    ld hl,W_PARTYMON1
    ld de,W_PARTYMON1_HP
.HealPokemon: ; f6ab (3:76ab)
    ld a,[hli]
    cp $ff
    jr z,.DoneHealing ; End if there's no Pokémon
    push hl
    push de
    ld hl,$0003 ; Status offset
    add hl,de
    xor a
    ld [hl],a ; Clean status conditions
    push de
;    ld b,$4 ; A Pokémon has 4 moves
;.RestorePP
    ld hl,$0007 ; Move offset
    add hl,de
;    ld a,[hl]
;    and a
;    jr z,.HealNext ; Skip if there's no move here
;    dec a
    ld hl,$001c ; PP offset
    add hl,de
;    push hl
;    push de
;    push bc
;    ld hl,Moves
;    ld bc,$0006
;    call AddNTimes
;    ld de,$cd6d
;    ld a,BANK(Moves)
;    call FarCopyData ; copy move header to memory
;    ld a,[$cd72] ; get default PP
;    pop bc
;    pop de
;    pop hl
;    inc de
;    push bc
;    ld b,a
;    ld a,[hl]
;    and $c0
;    add b
    ld a,255  ; Energy 255
    ld [hl],a ; Disable PP Restore (Energy 255)
;    pop bc
;.HealNext
;    dec b
;    jr nz,.RestorePP ; Continue if there's still moves
    pop de
    ld hl,$0021 ; Max HP offset
    add hl,de
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[hl]
    ld [de],a ; Restore full HP
    pop de
    pop hl
    push hl
    ld bc,$002c
    ld h,d
    ld l,e
    add hl,bc
    ld d,h
    ld e,l
    pop hl
    jr .HealPokemon ; Next Pokémon
.DoneHealing
    xor a
    ld [$cf92],a
    ld [$d11e],a
    call .ResetPikachuEeveeEncounter
    ld a,[W_NUMINPARTY]
    ld b,a
.restoreBonusPPLoop ; loop to restore bonus PP from PP Ups
;    push bc
    ; call RestoreBonusPP ; Disable PP Restore
;    pop bc
    ld hl,$cf92
    inc [hl]
    dec b
    jr nz,.restoreBonusPPLoop
    ret
.ResetPikachuEeveeEncounter
    ld hl,wDisableEncounterBit1 ; wDisableEncounterBit3
    res 1,[hl]
    res 3,[hl]
    ret

