; calculates bc * 48 / de,the number of pixels the HP bar has
; the result is always at least 1
UpdateHPBar_CalcNumberOfHPBarPixels: ; f9df (3:79df)
    push hl
    xor a
    ld hl,H_MULTIPLICAND
    ld [hli],a
    ld a,b
    ld [hli],a
    ld a,c
    ld [hli],a
    ld [hl],$30
    call Multiply      ; 48 * bc (hp bar is 48 pixels long)
    ld a,d
    and a
    jr z,.maxHPSmaller256
    srl d              ; make HP in de fit into 1 byte by dividing by 4
    rr e
    srl d
    rr e
    ld a,[H_MULTIPLICAND+1]
    ld b,a
    ld a,[H_MULTIPLICAND+2]
    srl b              ; divide multiplication result as well
    rr a
    srl b
    rr a
    ld [H_MULTIPLICAND+2],a
    ld a,b
    ld [H_MULTIPLICAND+1],a
.maxHPSmaller256
    ld a,e
    ld [H_DIVISOR],a
    ld b,$4
    call Divide
    ld a,[H_MULTIPLICAND+2]
    ld e,a            ; e = bc * 48 / de (num of pixels of HP bar)
    pop hl
    and a
    ret nz
    ld e,$1           ; make result at least 1
    ret

; predef $48
UpdateHPBar: ; fa1d (3:7a1d)
    push hl
    call PrintBattleValueNearMon ; ld hl,wHPBarOldHP
    ld a,[hli]
    ld c,a      ; old HP into bc
    ld a,[hli]
    ld b,a
    ld a,[hli]
    ld e,a      ; new HP into de
    ld d,[hl]
    pop hl
    push de
    push bc
    call UpdateHPBar_CalcHPDifference
    ld a,e
    ld [wHPBarHPDifference+1],a
    ld a,d
    ld [wHPBarHPDifference],a
    pop bc
    pop de
    call UpdateHPBar_CompareNewHPToOldHP
    jr z,.end
    ld a,$ff
    jr c,.HPdecrease
    ld a,$1
.HPdecrease
    ld [wHPBarDelta],a
    call Load16BitRegisters
    ld a,[wHPBarNewHP]
    ld e,a
    ld a,[wHPBarNewHP+1]
    ld d,a
.animateHPBarLoop
    push de
    ld a,[wHPBarOldHP]
    ld c,a
    ld a,[wHPBarOldHP+1]
    ld b,a
    call UpdateHPBar_CompareNewHPToOldHP
    jr z,.animateHPBarDone
    jr nc,.HPIncrease
    dec bc        ; subtract 1 HP
    ld a,c
    ld [wHPBarNewHP],a
    ld a,b
    ld [wHPBarNewHP+1],a
    call UpdateHPBar_CalcOldNewHPBarPixels
    ld a,e
    sub d         ; calc pixel difference
    jr .asm_fa7e
.HPIncrease
    inc bc        ; add 1 HP
    ld a,c
    ld [wHPBarNewHP],a
    ld a,b
    ld [wHPBarNewHP+1],a
    call UpdateHPBar_CalcOldNewHPBarPixels
    ld a,d
    sub e         ; calc pixel difference
.asm_fa7e
    call DecreaseValCounterAndPrintHPNumber ; call UpdateHPBar_PrintHPNumber
    and a
    jr z,.noPixelDifference
    call UpdateHPBar_AnimateHPBar
.noPixelDifference
    ld a,[wHPBarNewHP]
    ld [wHPBarOldHP],a
    ld a,[wHPBarNewHP+1]
    ld [wHPBarOldHP+1],a
    pop de
    jr .animateHPBarLoop
.animateHPBarDone
    pop de
    ld a,e
    ld [wHPBarOldHP],a
    ld a,d
    ld [wHPBarOldHP+1],a
    or e
    jr z,.monFainted
    call UpdateHPBar_CalcOldNewHPBarPixels
    ld d,e
.monFainted
    call UpdateHPBar_PrintHPNumber
    ld a,$1
    call UpdateHPBar_AnimateHPBar
.end
    jp RemoveBattleValue ; jp Delay3

