SECTION "UpdateHPBar_CompareNewHPToOldHP",ROMX[$7ad1],BANK[$3]

; compares old HP and new HP and sets c and z flags accordingly
UpdateHPBar_CompareNewHPToOldHP: ; fad1 (3:7ad1)
    ld a,d
    sub b
    ret nz
    ld a,e
    sub c
    ret

; calcs HP difference between bc and de (into de)
UpdateHPBar_CalcHPDifference: ; fad7 (3:7ad7)
    ld a,d
    sub b
    jr c,.oldHPGreater
    jr z,.testLowerByte
.newHPGreater
    ld a,e
    sub c
    ld e,a
    ld a,d
    sbc b
    ld d,a
    ret
.oldHPGreater
    ld a,c
    sub e
    ld e,a
    ld a,b
    sbc d
    ld d,a
    ret
.testLowerByte
    ld a,e
    sub c
    jr c,.oldHPGreater
    jr nz,.newHPGreater
    ld de,$0
    ret

UpdateHPBar_PrintHPNumber: ; faf5 (3:7af5)
    push af
    push de
    ld a,[wListMenuID] ; $cf94
    and a
    jr z,.asm_fb2d
    ld a,[wHPBarOldHP]
    ld [$cef1],a
    ld a,[wHPBarOldHP+1]
    ld [$cef0],a
    push hl
    ld a,[$FF00+$f6]
    bit 0,a
    jr z,.asm_fb15
    ld de,-18 ; Offset HP Number Party
    jr .asm_fb18
.asm_fb15
    ld de,+20 ; Offset HP Number Battle
.asm_fb18
    add hl,de
    push hl
    ld a,$7f
    ld [hli],a
    ld [hli],a
    ld [hli],a
    pop hl
    ld de,$cef0
    ld bc,$203
    call PrintNumber
    call DelayFrame
    pop hl
.asm_fb2d
    pop de
    pop af
    ret

; calcs number of HP bar pixels for old and new HP value
; d: new pixels
; e: old pixels
UpdateHPBar_CalcOldNewHPBarPixels: ; fb30 (3:7b30)
    push hl
    ld hl,wHPBarMaxHP
    ld a,[hli]  ; max HP into de
    ld e,a
    ld a,[hli]
    ld d,a
    ld a,[hli]  ; old HP into bc
    ld c,a
    ld a,[hli]
    ld b,a
    ld a,[hli]  ; new HP into hl
    ld h,[hl]
    ld l,a
    push hl
    push de
    call UpdateHPBar_CalcNumberOfHPBarPixels ; calc num pixels for old HP
    ld a,e
    pop de
    pop bc
    push af
    call UpdateHPBar_CalcNumberOfHPBarPixels ; calc num pixels for new HP
    pop af
    ld d,e
    ld e,a
    pop hl
    ret

