GetTMQty:
    ; a = TM ID
    push hl
    push af
    call FindRightByteAndNibbleID ; hl=pointerToRightByte | e=nibbleID
    ld a,[hl]
    ld b,a
.LoopForRightNibble
    ld a,e
    and a
    jr z,.RightNibbleDone
    srl b ; shift right byte read
    srl b ; ...
    dec e
    jr .LoopForRightNibble
.RightNibbleDone
    ld a,b
    and %00000011 ; Mask
.end
    pop bc
    ld c,a
    ld a,b
    pop hl
    ; a = TM ID
    ; c = Qty
    ret

ResetTMQty:
    ; a = TM ID
    call FindRightByteAndNibbleID ; hl=pointerToRightByte | e=nibbleID
    ld b,%00000011 ; Mask
.LoopForMask
    ld a,e
    and a
    jr z,.RightMask
    sla b ; shift left mask
    sla b ; ...
    dec e
    jr .LoopForMask
.RightMask
    ld a,[hl] ; Read Original
    or b ; Apply Mask (Qty = 3)
    ld [hl],a ; Overwrite
    scf
    ret

RemoveTMQty:
    ; a = TM ID
    call FindRightByteAndNibbleID ; hl=pointerToRightByte | e=nibbleID
    ld a,[hl]
    ld b,a
    ld d,e ; Backup Nibble
    ld c,%00000011 ; Mask
.LoopForMaskAndRightNibble
    ld a,e
    and a
    jr z,.RightMaskAndNibble
    srl b ; shift right byte read
    srl b ; ...
    sla c ; shift left mask
    sla c ; ...
    dec e
    jr .LoopForMaskAndRightNibble
.RightMaskAndNibble
    ld a,b
    and %00000011 ; Mask to Only Actual TM Qty
    ld b,a
    dec b ; Remove 1 Unit to TM Qty
.LoopToRevertSlide
    ld a,d
    and a
    jr z,.RevertSlideDone
    sla b ; shift left byte read
    sla b ; ...
    dec d
    jr .LoopToRevertSlide
.RevertSlideDone
    ld a,%11111111  ; Reverse Mask
    sub c           ; ...
    ld c,a          ; ...
    ld a,[hl] ; Read Original
    and c ; Apply Mask
    add b ; Insert New TM Qty
    ld [hl],a ; Overwrite
    ret

AddTMQty:
    ; a = TM ID
    call FindRightByteAndNibbleID ; hl=pointerToRightByte | e=nibbleID
    ld a,[hl]
    ld b,a
    ld d,e ; Backup Nibble
    ld c,%00000011 ; Mask
.LoopForMaskAndRightNibble
    ld a,e
    and a
    jr z,.RightMaskAndNibble
    srl b ; shift right byte read
    srl b ; ...
    sla c ; shift left mask
    sla c ; ...
    dec e
    jr .LoopForMaskAndRightNibble
.RightMaskAndNibble
    ld a,b
    and %00000011 ; Mask to Only Actual TM Qty
    cp 3
    ret z ; rcf ; 3 = Max Quantity than EXIT
    ld b,a
    inc b ; Add 1 Unit to TM Qty
.LoopToRevertSlide
    ld a,d
    and a
    jr z,.RevertSlideDone
    sla b ; shift left byte read
    sla b ; ...
    dec d
    jr .LoopToRevertSlide
.RevertSlideDone
    ld a,%11111111  ; Reverse Mask
    sub c           ; ...
    ld c,a          ; ...
    ld a,[hl] ; Read Original
    and c ; Apply Mask
    add b ; Insert New TM Qty
    ld [hl],a ; Overwrite
    scf
    ret

FindRightByteAndNibbleID:
    sub TM_01 ; TM01 ID = 0
    ld c,a
    ld e,0
    srl c
    jr nc,.skipBit0
    set 0,e
.skipBit0
    srl c
    jr nc,.skipBit1
    set 1,e
.skipBit1
    ld hl,wTM ; c=byte|e=nibbleID
    ld b,0
    add hl,bc
    ret

