StartMenu_Option_Init:
    xor a
    ld [H_AUTOBGTRANSFERENABLED],a
    call ClearScreen
    call UpdateSprites
    BANKSWITCH_JUMP DisplayOptionMenu

GetWildEnemyLevel:
    push de
.Retry
    ld b,0
    call GenRandom
    ld c,a
    and %00000111
    jr z,.Add1 ; 1/8 = 12.50%
    ld a,c
    and %11111000
    jr z,.Add2 ; (1-1/8)/32 = 2.73%
    call GenRandom
    and %01111111
    jr z,.Add3 ; (1-((1-1/8)/32))/128 = 0.76%
    call GenRandom
    and %00111111
    jr z,.BabyLevel2 ; (1-(1/8)-((1-1/8)/32)-((1-((1-1/8)/32))/128))/64 = 1.31%
.Add0 ; 1-(1/8)-((1-1/8)/32)-((1-((1-1/8)/32))/128)-(1-(1/8)-((1-1/8)/32)-((1-((1-1/8)/32))/128))/64 = 82.70%
.End
    ld a,[W_CURENEMYLVL] ; $d127
    add b
    ld [W_CURENEMYLVL],a ; $d127
    pop de
    ret
.Add3
    inc b
.Add2
    inc b
.Add1
    inc b
    jr .End
.BabyLevel2
    push bc
    ld a,[W_ENEMYMONID] ; mon id
    ld hl,BabyMon
    ld de,$0001
    call IsInArray
    pop bc
    jr nc,.Add0
    ld a,2
    ld [W_CURENEMYLVL],a ; $d127
    jr .Retry

