SECTION "DrawPartyMenu_",ROMX[$6cd2],BANK[$4]

; [$D07D] = menu type / message ID
; if less than $F0,it is a menu type
; menu types:
; 00: normal pokemon menu (e.g. Start menu)
; 01: use healing item on pokemon menu
; 02: in-battle switch pokemon menu
; 03: learn TM/HM menu
; 04: swap pokemon positions menu
; 05: use evolution stone on pokemon menu
; otherwise,it is a message ID
; f0: poison healed
; f1: burn healed
; f2: freeze healed
; f3: sleep healed
; f4: paralysis healed
; f5: HP healed
; f6: health returned
; f7: revitalized
; f8: leveled up
DrawPartyMenu_: ; 12cd2 (4:6cd2)
    xor a
    ld [H_AUTOBGTRANSFERENABLED],a
    call ClearScreen
    call UpdateSprites ; move sprites
    BANKSWITCH Func_71791 ; load pokemon icon graphics

RedrawPartyMenu_: ; 12ce3 (4:6ce3)
    ld a,[$D07D]
    cp $04
    jp z,.printMessage
    call ErasePartyMenuCursors
    BANKSWITCH Func_71fb6 ; loads some data to $cf2e
    FuncCoord 3,0
    ld hl,Coord
    ld de,W_PARTYMON1
    xor a
    ld c,a
    ld [$FF8C],a ; loop counter
    ld [$CF2D],a
.loop
    ld a,[de]
    cp $FF ; reached the terminator?
    jp z,.afterDrawingMonEntries
    push bc
    push de
    push hl
    ld a,c
    push hl
    ld hl,W_PARTYMON1NAME
    call GetPartyMonName
    pop hl
    call PlaceString ; print the pokemon's name
    BANKSWITCH PlaceAppropriatePokemonIcon ; place the appropriate pokemon icon
    ld a,[$FF8C] ; loop counter
    ld [$CF92],a
    inc a
    ld [$FF8C],a
    call LoadMonData
    pop hl
    push hl
    ld a,[$CC35]
    and a ; is the player swapping pokemon positions?
    jr z,.skipUnfilledRightArrow
; if the player is swapping pokemon positions
    dec a
    ld b,a
    ld a,[$CF92]
    cp b ; is the player swapping the current pokemon in the list?
    jr nz,.skipUnfilledRightArrow
; the player is swapping the current pokemon in the list
    dec hl
    dec hl
    dec hl
    ld a,$EC ; unfilled right arrow menu cursor
    ld [hli],a ; place the cursor
    inc hl
    inc hl
.skipUnfilledRightArrow
    ld a,[$D07D] ; menu type
    cp $03
    jr z,.teachMoveMenu
    cp $05
    jr z,.evolutionStoneMenu
    push hl
    ld bc,20 ; Party Menu Status
    add hl,bc
    ld de,$CF9C
    ld bc,0 ; not volatile status
    call PrintStatusCondition
    pop hl
    push hl
    ld bc,28 ; Party Menu Hp Bar
    ld a,[$FFF6]
    set 0,a
    ld [$FFF6],a
    add hl,bc
    PREDEF DrawPlayerHPBarParty ; draw HP bar and prints current / max HP
    ld a,[$FFF6]
    res 0,a
    ld [$FFF6],a
    call Func_12ec7 ; color the HP bar (on SGB)
    pop hl
    jr .printLevel
.teachMoveMenu
    push hl
    PREDEF TestMonMoveCompatibility ; check if the pokemon can learn the move
    pop hl
    ld de,.ableToLearnMoveText
    ld a,c
    and a
    jr nz,.placeMoveLearnabilityString
    ld de,.notAbleToLearnMoveText
.placeMoveLearnabilityString
    ld bc,20 + 9 ; down 1 row and right 9 columns
    push hl
    add hl,bc
    call FixTMPalette ; call PlaceString
    pop hl
.printLevel
    ld bc,14 ; Party Mon Level
    add hl,bc
    call PrintLevelAndGender ; call PrintLevel
    pop hl
    pop de
    inc de
    ld bc,2 * 20
    add hl,bc
    pop bc
    inc c
    jp .loop
.ableToLearnMoveText
    db "ABLE@"
.notAbleToLearnMoveText
    db "NOT ABLE@"
.evolutionStoneMenu
    push hl
    ld de,$CD6D
    PREDEF _GetEvos
    ld de,.notAbleToEvolveText
; loop through the pokemon's evolution entries
.checkEvolutionsLoop
    ld a,[hli]
    and a ; reached terminator?
    jr z,.placeEvolutionStoneString ; if so,place the "NOT ABLE" string
    inc hl
    inc hl
    cp EV_ITEM
    jr nz,.checkEvolutionsLoop
; if it's a stone evolution entry
    dec hl
    dec hl
    ld b,[hl]
    ld a,[$D156] ; evolution stone item ID
    inc hl
    inc hl
    inc hl
    cp b ; does the player's stone match this evolution entry's stone?
    jr nz,.checkEvolutionsLoop
; if it does match
    ld de,.ableToEvolveText
.placeEvolutionStoneString
    ld bc,20 + 9 ; down 1 row and right 9 columns
    pop hl
    push hl
    add hl,bc
    call PlaceString
    pop hl
    jr .printLevel
.ableToEvolveText
    db "ABLE@"
.notAbleToEvolveText
    db "NOT ABLE@"
.afterDrawingMonEntries
    ld b,$0A
    call GoPAL_SET
.printMessage
    ld hl,$D730
    ld a,[hl]
    push af
    push hl
    set 6,[hl] ; turn off letter printing delay
    ld a,[$D07D] ; message ID
    cp $F0
    jr nc,.printItemUseMessage
    add a
    call CheckIfInBattleItem ; ld hl,PartyMenuMessagePointers
    ld b,0
    ld c,a
    add hl,bc
    ld a,[hli]
    ld h,[hl]
    ld l,a
    call PrintText
.done
    pop hl
    pop af
    ld [hl],a
    ld a,1
    ld [H_AUTOBGTRANSFERENABLED],a
    call Delay3
    jp GbPalComplete ; Denim ; Party Sprite con tutti e 4 i colori palette ; jp GBPalNormal
.printItemUseMessage
    and a,$0F
    ld hl,PartyMenuItemUseMessagePointers
    add a
    ld c,a
    ld b,0
    add hl,bc
    ld a,[hli]
    ld h,[hl]
    ld l,a
    push hl
    ld a,[$CF06]
    ld hl,W_PARTYMON1NAME
    call GetPartyMonName
    pop hl
    call PrintText
    jr .done

; items which close the item menu when used
