Func_13074: ; 13074 (4:7074)
    ld h,$c2
    ld a,[H_CURRENTSPRITEOFFSET]
    add $8
    ld l,a
    ld a,$7f
    ld [hl],a
    dec h
    ld a,[H_CURRENTSPRITEOFFSET]
