StartMenu_Pokedex: ; 13095 (4:7095)
    PREDEF DisplayPokedexMenu_
    call LoadScreenTilesFromBuffer2 ; restore saved screen
    call Delay3
    call LoadGBPal
    call UpdateSprites
    jp RedisplayStartMenu

StartMenu_Pokemon:
    ld a,[W_NUMINPARTY]
    and a
    jp z,RedisplayStartMenu
    xor a
    ld [$cc35],a
    ld [$d07d],a
    ld [$cfcb],a
    ld hl,wForceSortPartyWSelectBit4
    set 4,[hl]
    call DisplayPartyMenu
    jr .checkIfPokemonChosen
.loop
    xor a
    ld [$cc35],a
    ld [$d07d],a
.checkIfPokemonChosen2
    ld hl,wForceSortPartyWSelectBit4
    set 4,[hl]
    call GoBackToPartyMenu
.checkIfPokemonChosen
    ld a,0
    ld [wSkillMonID],a
    jr nc,.chosePokemon
.exitMenu
    ld hl,wForceSortPartyWSelectBit4
    res 4,[hl]
    call GBPalWhiteOutWithDelay3
    call RestoreScreenTilesAndReloadTilePatterns
    call LoadGBPal
    jp RedisplayStartMenu
.chosePokemon
    call SaveScreenTilesToBuffer1 ; save screen
    ld hl,wForceSortPartyWSelectBit4
    bit 4,[hl]
    jr z,.choseSwitch
.RedrawMenu
    ld a,3 ; ChoiceMonSimpleMenu
    ld [$d125],a
    call DisplayTextBoxID ; display pokemon menu options
    ld bc,$0408 ; ld bc,$020c ; max menu item ID,top menu item Y
    ld d,12 ; top menu item X
    call HandlePkmnSubMenu
    bit 1,a ; was the B button pressed?
    jr nz,.ReloadScreenAndLoop
    ld a,[wCurrentMenuItem]
    and a
    jr z,.choseSkill
    push af
    call LoadScreenTilesFromBuffer1 ; restore saved screen
    pop af
    dec a
    jr z,.choseStats
    dec a
    jr z,.choseMoves
    dec a
    jr z,.choseRename
    ; ft

.choseSwitch
    ld a,[W_NUMINPARTY]
    cp 2 ; is there more than one pokemon in the party?
    jr c,StartMenu_Pokemon ; if not,no switching
    call Func_13653
    ld a,$04 ; swap pokemon positions menu
    ld [$d07d],a
    jr .checkIfPokemonChosen2

.ReloadScreenAndLoop
    call LoadScreenTilesFromBuffer1 ; restore saved screen
.MiddleJumpToLoop
    jr .loop

.choseStats
    call CleanLCD_OAM
    xor a
    ld [$cc49],a
    PREDEF StatusScreen
.ReturnToPartyMenu
    call ReloadMapData
    jp StartMenu_Pokemon

.choseMoves
    PREDEF MovesMenu
    jr .ReturnToPartyMenu

.choseRename
    call DisplayPartyRenameScreen
    jr .ReturnToPartyMenu

.NoSkill
    ld a,$a5 ; Error
    call PlaySoundWaitForCurrent ; play sound
    jr .RedrawMenu

.choseSkill
    BANKSWITCH GetMonSkill
    ld a,[wNumSkill]
    and a
    jr z,.NoSkill
    call CheckSkillEnergy
    jr c,.NoSkill
    ld a,4 ; SkillMenu
    ld [$d125],a
    call DisplayTextBoxID ; display pokemon skill
    ld bc,$ff12 ; max menu item ID,top menu item Y
    ld d,04 ; top menu item X
    call HandlePkmnSubMenuSkill
    push af
    call LoadScreenTilesFromBuffer1 ; restore saved screen
    pop af
    bit 1,a ; was the B button pressed?
    jr nz,.MiddleJumpToLoop
    ld hl,wSkill
    ld b,0
    ld a,[wCurrentMenuItem]
    ld c,a
    add hl,bc
    call GetPartyMonIDAndName
    ld a,[hl]
    dec a
    add a
    ld b,0
    ld c,a
    ld hl,.outOfBattleMovePointers
    add hl,bc
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ld a,[W_OBTAINEDBADGES] ; badges obtained
    jp hl
.outOfBattleMovePointers
    dw .fly
    dw .teleport
    dw .dig
    dw .cut
    dw .surf
    dw .strength
    dw .flash
    dw .softboiled

.fly
    call CanFly
    jr c,.canFly
    push hl
    call GetPartyMonName2
    pop hl
    call PrintText
    jp .loop
.canFly
    call ChooseFlyDestination
    ld a,[$d732]
    bit 3,a ; did the player decide to fly?
    jr z,.undoFly
    call .ResetSafari
    call PlayCryAndDecreaseSkillEnergy
    jp .goBackToMap
.undoFly
    call LoadFontTilePatterns
    ld hl,$d72e
    set 1,[hl]
    jp StartMenu_Pokemon

.cut
    BANKSWITCH CheckCutTile
    call z,PlayCryAndDecreaseSkillEnergy
    PREDEF UsedCut
    ld a,[$cd6a]
    and a
    jp z,.loop
    ld hl,wForceSortPartyWSelectBit4
    res 4,[hl]
    jp CloseTextDisplay

.surf
    BANKSWITCH IsSurfingAllowed
    ld hl,$d728
    bit 1,[hl]
    res 1,[hl]
    jp z,.loop
    ld a,SURFBOARD
    ld [$cf91],a
    ld [$d152],a
    call UseItem
    ld a,[$cd6a]
    and a
    jp z,.loop
.WhiteScreenAndGotoMap
    call GBPalWhiteOutWithDelay3
    jp .goBackToMap

.strength
    PREDEF UseStrength
    jp nc,.loop
    jr .WhiteScreenAndGotoMap

.flash
    ld a,BENGAL
    jr .common

.dig
    ld a,AUGER
    ; ft

.common
    ld [$cf91],a
    ld [$d152],a
    call UseItem
    ld a,[$cd6a]
    and a
    jp z,.loop
    jr .WhiteScreenAndGotoMap

.teleport
    call CanTeleport
    jr c,.canTeleport
    push hl
    call GetPartyMonName2
    pop hl
    call PrintText
    jp .loop
.canTeleport
    call PlayCryAndDecreaseSkillEnergy
    ld hl,.warpToLastPokemonCenterText
    call PrintText
    ld hl,$d732
    set 3,[hl]
    set 6,[hl]
    ld hl,$d72e
    set 1,[hl]
    res 4,[hl]
    call .ResetSafari
    ld c,60
    call DelayFrames
    call GBPalWhiteOutWithDelay3 ; zero all three palettes and wait 3 V-blanks
    jp .goBackToMap
.warpToLastPokemonCenterText
    TX_FAR _WarpToLastPokemonCenterText
    db "@"

.ResetSafari
    ld hl,$d790
    res 7,[hl] ; unset Safari Zone bit
    xor a
    ld [$da47],a
    ld [W_SAFARIZONEENTRANCECURSCRIPT],a
    ret

.softboiled
    ld hl,W_PARTYMON1_MAXHP
    ld a,[$cf92]
    ld bc,44
    call AddNTimes
    ld a,[hli]
    ld [H_DIVIDEND],a
    ld a,[hl]
    ld [H_DIVIDEND + 1],a
    ld a,5
    ld [H_DIVISOR],a
    ld b,2 ; number of bytes
    call Divide
    ld bc,-33
    add hl,bc
    ld a,[hld]
    ld b,a
    ld a,[H_QUOTIENT + 3]
    sub b
    ld b,[hl]
    ld a,[H_QUOTIENT + 2]
    sbc b
    jp nc,.notHealthyEnough
    ld a,[wPartyAndBillsPCSavedMenuItem]
    push af
    ld a,POTION
    ld [$cf91],a
    ld [$d152],a
    call UseItem
    pop af
    ld [wPartyAndBillsPCSavedMenuItem],a
    jp .loop
.notHealthyEnough ; if current HP is less than 1/5 of max HP
    ld hl,.notHealthyEnoughText
    call PrintText
    jp .loop
.notHealthyEnoughText
    TX_FAR _NotHealthyEnoughText
    db "@"

.goBackToMap
    ld hl,wForceSortPartyWSelectBit4
    res 4,[hl]
    call RestoreScreenTilesAndReloadTilePatterns
    jp CloseTextDisplay

; Free

SECTION "ItemMenuLoop",ROMX[$72fc],BANK[$4]

ItemMenuLoop: ; 132fc (4:72fc)
    call LoadScreenTilesFromBuffer2DisableBGTransfer ; restore saved screen
    call GoPAL_SET_CF1C

StartMenu_Item: ; 13302 (4:7302)
    ld a,[W_ISLINKBATTLE]
    dec a
    jr nz,.notInLinkBattle
    ld hl,.CannotUseItemsHereText
    call PrintText
    jr .exitMenu
.notInLinkBattle
    ld a,[wNumBagItems]
    and a
    jr z,.exitMenu
    ld bc,wNumBagItems
    ld hl,$cf8b
    ld a,c
    ld [hli],a
    ld [hl],b ; store item bag pointer at $cf8b (for DisplayListMenuID)
    xor a
    ld [$cf93],a
    ld a,ITEMLISTMENU
    ld [wListMenuID],a
    ld a,[wBagSavedMenuItem]
    ld [wCurrentMenuItem],a
    call DisplayListMenuID
    ld a,[wCurrentMenuItem]
    ld [wBagSavedMenuItem],a
    jr nc,.choseItem
.exitMenu
    call LoadScreenTilesFromBuffer2 ; restore saved screen
    call LoadTextBoxTilePatterns
    call UpdateSprites ; move sprites
    jp RedisplayStartMenu
.choseItem
; erase menu cursor (blank each tile in front of an item name)
    ld a," "
    FuncCoord 5,4
    ld [Coord],a
    FuncCoord 5,6
    ld [Coord],a
    FuncCoord 5,8
    ld [Coord],a
    FuncCoord 5,10
    ld [Coord],a
    call PlaceUnfilledArrowMenuCursor
    xor a
    ld [$cc35],a
    ld a,[$cf91]
    cp BICYCLE
    jp z,.useOrTossItem
    cp TECH_MACHINE
    jp z,.useOrTossItem
    cp POKEDEX
    jp z,.useOrTossItem
.notBicycle1
    ld a,$06 ; use/toss menu
    ld [$d125],a
    call DisplayTextBoxID
    ld hl,wTopMenuItemY
    ld a,11
    ld [hli],a ; top menu item Y
    ld a,14
    ld [hli],a ; top menu item X
    xor a
    ld [hli],a ; current menu item ID
    inc hl
    inc a ; a = 1
    ld [hli],a ; max menu item ID
    ld a,%00000011 ; A button,B button
    ld [hli],a ; menu watched keys
    xor a
    ld [hl],a ; old menu item id
    call HandleMenuInput
    call PlaceUnfilledArrowMenuCursor
    bit 1,a ; was the B button pressed?
    jr z,.useOrTossItem
    jp ItemMenuLoop
.useOrTossItem ; if the player made the choice to use or toss the item
    ld a,[$cf91]
    ld [$d11e],a
    call GetItemName
    call CopyStringToCF4B ; copy name to $cf4b
    ld a,[$cf91]
    cp BICYCLE
    jr nz,.notBicycle2
    ld a,[$d732]
    bit 5,a
    jr z,.useItem_closeMenu
    ld hl,.CannotGetOffHereText
    call PrintText
    jp ItemMenuLoop
.notBicycle2
    ld a,[$cf91]
    cp TECH_MACHINE
    jr z,.useItem_partyMenu
    cp POKEDEX
    jr z,.useItem_Standard
    ld a,[wCurrentMenuItem]
    and a
    jr nz,.tossItem
.useItem
    ld [$d152],a
    ld a,[$cf91]
    cp $FF
    jr z,.useItem_Standard
    cp TM_01
    jr nc,.useItem_partyMenu
    ld hl,UsableItems_CloseMenu
    ld de,1
    call IsInArray
    jr c,.useItem_closeMenu
    ld a,[$cf91]
    ld hl,UsableItems_PartyMenu
    ld de,1
    call IsInArray
    jr c,.useItem_partyMenu
.useItem_Standard
    call UseItem
    jp ItemMenuLoop
.useItem_closeMenu
    xor a
    ld [$d152],a
    call UseItem
    ld a,[$cd6a]
    and a
    jp z,ItemMenuLoop
    jp CloseStartMenu
.useItem_partyMenu
    ld a,[$cfcb]
    push af
    call UseItem
    ld a,[$cd6a]
    cp $02
    jp z,.partyMenuNotDisplayed
    call GBPalWhiteOutWithDelay3
    call RestoreScreenTilesAndReloadTilePatterns
    pop af
    ld [$cfcb],a
    jp StartMenu_Item
.partyMenuNotDisplayed
    pop af
    ld [$cfcb],a
    jp ItemMenuLoop
.tossItem
    call IsKeyItem
    ld a,[$d124]
