; Input
; e = Encounter Slot
; [W_ENEMYMONID] = Actual Wild Mon ID
; [W_CURENEMYLVL] = Actual Wild Mon Level
GetEnemy:
    ld a,[W_ENEMYMONID]
    cp $FF
    jr nz,.WillEncounter
.Exception
    push hl
    push de
    ld a,[W_CURENEMYLVL] ; Exception ID
    cp W_STANDARD
    jr nc,.NotEncounter
    ld d,a ; Exception ID
    ld hl,.WildExceptionPointer
    add a
    ld c,a
    ld b,0
    add hl,bc
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ld b,BANK(WildSubGroup)
    call Bankswitch
    pop de
    pop hl
    ret nc ; NotEncounter
    jr GetEnemy
.WildExceptionPointer
    dw WildSubGroup
    dw WildUnknownDungeon
    dw WildUnknownDungeon
    dw WildDockMew
    dw WildPikachu
    dw WildEevee
    dw WildArticuno
    dw WildZapdos
    dw WildMoltres
.WillEncounter
    call .DittoDebugInRoute15
    ld a,[W_ENEMYMONID]
    ld [$cf91],a
    scf ; WillEncounter
    ret
.NotEncounter
    and a ; Reset Carry Flag ; NotEncounter
    ret
.DittoDebugInRoute15
    call GetCurrentOldAdventureMap
    cp ROUTE_15
    ret nz
    ld a,[H_CURRENTPRESSEDBUTTONS]
    bit 2,a ; was the select button pressed?
    ret z
    ld a,DITTO
    ld [W_ENEMYMONID],a
    ret

