CheckIfInBattleItem:
    ld hl,PartyMenuMessagePointers
    cp 2 ; If Original $D07D = 1 because doubled
    ret nz
    call .IsInBattle
    jr nz,.ItemInBattle
    call .IsUsingSoftboiled
    jr nz,.Softboiled
    ret
.ItemInBattle
    xor a
.Softboiled ; a = 2
    ld hl,PartyMenuMessagePointersNew
    ret
.IsInBattle
    push bc
    ld b,a ; Backup
    ld a,[W_ISINBATTLE]
    and a
    ld a,b ; Restore
    pop bc
    ret
.IsUsingSoftboiled
    push bc
    ld b,a ; Backup
    ld a,[$d152]
    and a ; using Softboiled?
    ld a,b ; Restore
    pop bc
    ret

