    ld hl,W_ENEMYMONTYPES
    ld de,W_PLAYERMONTYPES
    ld a,[H_WHOSETURN]
    and a
    ld a,[W_ENEMYBATTSTATUS1]
    jr z,.done
    push hl
    ld h,d
    ld l,e
    pop de
    ld a,[W_PLAYERBATTSTATUS1]
.done
    bit 6,a ; invulnerable
    jr nz,.attackMissed
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[hli]
    ld [de],a
    inc de
