    ld hl,W_PARTYMON1_LEVEL
    ld de,W_PARTYMON2DATA-W_PARTYMON1DATA
    ld bc,0
.loop
    push af
    ld a,[hl]
    add c
    ld c,a
    jr nc,.NoCarry
    inc b
.NoCarry
    add hl,de
    pop af
