TryUseAnotherRepel:
    ld hl,wNumBagItems
    ld a,[hli]
    and a
    jr z,.NoOtherRepelInBag
    ld b,a
    ld c,0
.loop
    ld a,[hli]
    cp $FF
    jr z,.NoOtherRepelInBag
    cp REPEL
    jr z,.RepelFound
    cp SUPER_REPEL
    jr z,.RepelFound
    cp MAX_REPEL
    jr z,.RepelFound
    inc hl
    inc c
    dec b
    jr nz,.loop
.NoOtherRepelInBag
    ld hl,.RepelWoreOffText
    jp PrintText
.RepelFound
    ld [$cf91],a ; Item ID
    ld [$d11e],a ; load item so its name can be grabbed
    ld a,c
    ld [$cf92],a ; Item Index
    ld a,[hl]
    ld [wTmpRepelQty],a
    push af
    call GetItemName ; get the item name into de register
    call CopyStringToCF4B ; copy name from de to wcf4b so it shows up in text
    pop af
    ld hl,.TryUseAnotherRepelText
    call PrintText
    call YesNoChoice ; yes/no textbox
    ld a,[$CC26] ; yes/no answer (Y=0,N=1)
    and a
    jr nz,.end
    xor a
    ld [$d152],a
    call UseItem
.end
    ret
.RepelWoreOffText
    TX_FAR _RepelWoreOffText
    db "@"
.TryUseAnotherRepelText
    TX_FAR _TryUseAnotherRepelText
    db "@"

