EmotionBubble:
    ld a,[$cd50] ; WhichEmotionBubble
    ld c,a
    ld b,$0
    ld hl,EmotionBubblesPointerTable ; $7caf
    add hl,bc
    add hl,bc
    ld e,[hl]
    inc hl
    ld d,[hl]
    ld hl,$8f80
    ld bc,(BANK(EmotionBubbles) << 8) + $04
    call CopyVideoData
    ld a,[$cfcb]
    push af
    ld a,$ff
    ld [$cfcb],a
    ld a,[$d736]
    bit 6,a
    ld hl,$c38f
    ld de,$c39f
    jr z,.asm_17c7a
    ld hl,$c37f
    ld de,$c38f
.asm_17c7a
    ld bc,$90
.asm_17c7d
    ld a,[hl]
    ld [de],a
    dec hl
    dec de
    dec bc
    ld a,c
    or b
    jr nz,.asm_17c7d
    ld hl,$c104
    ld a,[$cd4f]
    swap a
    ld c,a
    ld b,$0
    add hl,bc
    ld a,[hli]
    ld b,a
    inc hl
    ld a,[hl]
    add $8
    ld c,a
    ld de,EmotionBubblesOAM ; $7cb5
    xor a
    call WriteOAMBlock
    ld c,$3c
    call DelayFrames
    pop af
    ld [$cfcb],a
    call DelayFrame
    jp UpdateSprites

SECTION "ActivatePC",ROMX[$7e2c],BANK[$5]

ActivatePC: ; 17e2c (5:7e2c)
    call SaveScreenTilesToBuffer2  ;XXX: copy background from wTileMap to wTileMapBackup2
    ld a,$99
    call PlaySound  ;XXX: play sound or stop music
    ld hl,UnnamedText_17f23  ;player turned on PC
    call PrintText
    call WaitForSoundToFinish  ;XXX: wait for sound to be done
    ld hl,wFlags_0xcd60
    set 3,[hl]
    call LoadScreenTilesFromBuffer2  ;XXX: restore saved screen
    call Delay3
PCMainMenu: ; 17e48 (5:7e48)
    BANKSWITCH Func_213c8
    ld hl,wFlags_0xcd60
    set 5,[hl]
    call HandleMenuInputWithWrap
    bit 1,a              ;if player pressed B
    jp nz,LogOff
    ld a,[wMaxMenuItem]
    cp 2-1
    jr nz,.next ;if not 2 menu items (not counting log off) (2 occurs before you get the pokedex)
    ld a,[wCurrentMenuItem]
    and a
    jp z,BillsPC    ;if current menu item id is 0,it's bills pc
    cp 1
    jr z,.playersPC ;if current menu item id is 1,it's players pc
    jp LogOff        ;otherwise,it's 2,and you're logging off
.next
    cp 3-1
    jr nz,.next2 ;if not 3 menu items (not counting log off) (3 occurs after you get the pokedex,before you beat the pokemon league)
    ld a,[wCurrentMenuItem]
    and a
    jp z,BillsPC    ;if current menu item id is 0,it's bills pc
    cp 1
    jr z,.playersPC ;if current menu item id is 1,it's players pc
    cp 2
    jp z,OaksPC     ;if current menu item id is 2,it's oaks pc
    jp LogOff        ;otherwise,it's 3,and you're logging off
.next2
    ld a,[wCurrentMenuItem]
    and a
    jp z,BillsPC    ;if current menu item id is 0,it's bills pc
    cp 1
    jr z,.playersPC ;if current menu item id is 1,it's players pc
    cp 2
    jp z,OaksPC     ;if current menu item id is 2,it's oaks pc
    cp 3
    jp z,PKMNLeague ;if current menu item id is 3,it's pkmnleague
    jp LogOff        ;otherwise,it's 4,and you're logging off
.playersPC
    ld hl,wFlags_0xcd60
    res 5,[hl]
    set 3,[hl]
    ld a,$9B
    call PlaySound  ;XXX: play sound or stop music
    call WaitForSoundToFinish  ;XXX: wait for sound to be done
    ld hl,UnnamedText_17f32  ;accessed players pc
    call PrintText
    BANKSWITCH PlayerPC
    jr ReloadMainMenu
OaksPC: ; 17ec0 (5:7ec0)
    ld a,$9B
    call PlaySound  ;XXX: play sound or stop music
    call WaitForSoundToFinish  ;XXX: wait for sound to be done
    BANKSWITCH OpenOaksPC
    jr ReloadMainMenu
PKMNLeague: ; 17ed2 (5:7ed2)
    ld a,$9B
    call PlaySound  ;XXX: play sound or stop music
    call WaitForSoundToFinish  ;XXX: wait for sound to be done
    BANKSWITCH PKMNLeaguePC
    jr ReloadMainMenu
BillsPC: ; 17ee4 (5:7ee4)
    ld a,$9B
    call PlaySound    ;XXX: play sound or stop music
    call WaitForSoundToFinish    ;XXX: wait for sound to be done
    ld a,[$D7F1] ;has to do with having met Bill
    bit 0,a
    jr nz,.billsPC ;if you've met bill,use that bill's instead of someone's
    ld hl,UnnamedText_17f2d ;accessed someone's pc
    jr .printText
.billsPC
    ld hl,UnnamedText_17f28 ;accessed bill's pc
.printText
    call PrintText
    BANKSWITCH BillsPC_
ReloadMainMenu: ; 17f06 (5:7f06)
    xor a
    ld [$CC3C],a
    call ReloadMapData
    call UpdateSprites  ;XXX: moves sprites
    jp PCMainMenu
LogOff: ; 17f13 (5:7f13)
    ld a,$9A
    call PlaySound  ;XXX: play sound or stop music
    call WaitForSoundToFinish  ;XXX: wait for sound to be done
    ld hl,wFlags_0xcd60
    res 3,[hl]
    res 5,[hl]
    ret

UnnamedText_17f23: ; 17f23 (5:7f23)
    TX_FAR _UnnamedText_17f23
    db "@"

UnnamedText_17f28: ; 17f28 (5:7f28)
    TX_FAR _UnnamedText_17f28
    db "@"

UnnamedText_17f2d: ; 17f2d (5:7f2d)
    TX_FAR _UnnamedText_17f2d
    db "@"

UnnamedText_17f32: ; 17f32 (5:7f32)
    TX_FAR _UnnamedText_17f32
    db "@"

; removes one of the specified item ID [$FFdb] from bag (if existent)
RemoveItemByID:
    ld hl,wNumBagItems
    ld a,[hli]
    and a
    ret z
    ld e,a
    ld a,[$FF00+$db]
    ld b,a
    xor a
    ld [$FF00+$dc],a
.loop
    ld a,[hli]
    cp $ff
    ret z
    cp b
    jr z,.found
    inc hl
    ld a,[$FF00+$dc]
    inc a
    ld [$FF00+$dc],a
    dec e
    ret z
    jr .loop
.found
    ld a,1
    ld [$cf96],a
    ld a,[$FF00+$dc]
    ld [$cf92],a
    ld hl,wNumBagItems
    jp RemoveItemFromInventory

EmotionBubblesPointerTable:
    dw EmotionBubbles
    dw EmotionBubbles + $40
    dw EmotionBubbles + $80
    dw EmotionBubbles + $C0

EmotionBubblesOAM:
    db $F8,$00,$F9,$00
    db $FA,$00,$FB,$00

Func_17d7d:
    ld a,[wPlayerMonAccuracyMod] ; $cd1e
    cp $86
    jr z,.asm_17d8d
    cp $92
    ret nz
    ld a,[wPlayerMonEvasionMod] ; $cd1f
    cp $8f
    ret nz
.asm_17d8d
    ld a,[W_NUMINPARTY] ; $d163
    dec a
    ld [wWhichPokemon],a ; $cf92
    ld a,$1
    ld [$ccd4],a
    ld a,$32
    ld [W_ISLINKBATTLE],a ; $d12b
    BANKSWITCH TryEvolvingMon
    xor a
    ld [W_ISLINKBATTLE],a ; $d12b
    jp PlayDefaultMusic

