_CheckExceptionTilePassable: ; 1a672 (6:6672)

    ; Input
    ld a,d
    ld [wCollisionFlag],a

    ; Debug
    ld a,$FF
    ld [wCollisionRule],a

; get the tile in front of the player (or boulder/walking sprite)
    call GetDirectionOffset
    call GetTileOffset
    ld [$cfc6],a

    ; Check just Jumping
    ld a,[wCollisionFlag]
    bit 4,a ; Try Walking Sprite
    jr nz,.SkipCheckJump
    ld a,[$d736]
    bit 6,a
    jp nz,.end
.SkipCheckJump

    ; Collision Rule
    ld hl,CollissionRule
    push hl ; Backup Collision Rule Start Pointer

    ld bc,$00FF ; -1
.loop
    inc c
    ld a,8
    pop hl  ; Collision Rule Start Pointer
    push hl ; ...
    call AddNTimes

    ; Direction
    ld a,[$c109]
    ld d,a
    ld a,[hli]
    cp $FF
    jr nz,.continue
    pop af ; delete useless stack
    jp .end
.continue
    cp d
    jr nz,.loop

    ; Jump Tile
    ld a,[hli]
    call GetTileOffset
    ld a,[hli]
    call GetTilesetTile
    cp d
    jr nz,.loop

.endloop
    pop af ; delete useless stack

    ; Debug
    ld a,c
    ld [wCollisionRule],a

    ; Next Tile Simulation
    ld a,[hli]
    and a
    jr z,.skipSimulation
    call GetTilesetTile
    ld [$cfc6],a
.skipSimulation

    ; Check Try Pushing Boulder
    ld a,[wCollisionFlag]
    bit 3,a ; Try Pushing Boulder
    jr z,.noBoulder
    inc hl
    ld a,[hld]
    bit 4,a ; EX_BOULDER
    jr z,.noBoulder
    ld a,$FF
    ld [$cfc6],a ; Next Tile Simulation
    jr .end
.noBoulder

    ; Check Try Walking Sprite
    ld a,[wCollisionFlag]
    bit 4,a ; Try Walking Sprite
    jr z,.noWalkingSprite
    inc hl
    ld a,[hld]
    bit 5,a ; EX_WALING_SPRITE
    jr z,.noWalkingSprite
    ld a,$FF
    ld [$cfc6],a ; Next Tile Simulation
    jr .end
.noWalkingSprite

    ; Check Float
    ld a,[$d700]
    cp $2
    jr z,.end

    ; Check Try Jumping
    ld a,[wCollisionFlag]
    bit 0,a ; Try Jumping
    jr z,.end

    ; Collision Tile After Jump to Check
    ld a,[hli]
    and a
    jr z,.skipCheckCollision
    call GetTileOffset
    call CheckTilePassable
    jr c,.end
.skipCheckCollision

    ; Exception Flag
    call CheckJumpExceptionFlag
    inc hl
    jr nc,.end

.jumpfound

    ; Simulation Jump Distance
    ld a,[hli]
    ld [$cd38],a

    ; Direction Output
    ld a,[hl]
    ld [$ccd3],a

    ld a,$ff
    ld [wJoypadForbiddenButtonsMask],a
    ld hl,$d736
    set 6,[hl]
    call StartSimulatingJoypadStates

    call Func_1a6f0
    ld a,$a2
    jp PlaySound

    and a ; rcf -> WTW
    ret
.end
    ld a,[$cfc6] ; $FF = Not Passable
    ld d,a

    ; Check Try Stop Surfing
    ld a,[wCollisionFlag]
    bit 1,a ; Try Stop Surfing
    jr nz,CheckWaterTilePassable
    ; Check Can Surfing
    bit 2,a ; Can Surfing
    jr nz,CheckWaterTilePassable

    ; Check Float
    ld a,[$d700]
    cp $2
    jr z,CheckWaterTilePassable
    ; ft

CheckTilePassable:
    push hl
    ld hl,W_TILESETCOLLISIONPTR ; pointer to list of passable tiles
    ld a,[hli]
    ld h,[hl]
    ld l,a ; hl now points to passable tiles
.loop
    ld a,[hli]
    cp $ff
    jr z,.tileNotPassable
    cp d
    jr z,.tilePassable
    jr .loop
.tileNotPassable
    call ResetFlags
    scf
.end
    pop hl
    ret
.tilePassable
    call ResetFlags
    jr .end

CheckWaterTilePassable:
    ld a,d
    cp $14 ; water tile
    jr z,.noCollision ; keep surfing if it's a water tile
    cp $32 ; either the left tile of the S.S. Anne boarding platform or the tile on eastern coastlines (depending on the current tileset)
    jr z,.checkIfVermilionDockTileset
    cp $48 ; tile on right on coast lines in Safari Zone
    jr z,.noCollision ; keep surfing
; check if the [land] tile in front of the player is passable
    call CheckTilePassable
    jr nc,.stopSurfing
    jr .collision
.checkIfVermilionDockTileset
    ld a,[W_CURMAPTILESET] ; tileset
    cp $0e ; Vermilion Dock tileset
    jr nz,.noCollision ; keep surfing if it's not the boarding platform tile
    ; if it is the boarding platform tile,stop surfing
    ; ft
.stopSurfing
    ; Check Try Stop Surfing
    ld a,[wCollisionFlag]
    bit 1,a ; Try Stop Surfing
    jr z,.noCollision
    xor a
    ld [$d700],a
    call LoadPlayerSpriteGraphics
    call PlayDefaultMusicFadeOutCurrent ; call PlayDefaultMusic
    ; ft
.noCollision
    jr ResetFlags
.collision
    call ResetFlags
    scf
    ret

ResetFlags:
    ld a,1
    or a ; reset all flag
    ret

GetTilesetTile:
    push hl
    push bc
    ld c,a
    ld a,[W_CURMAPTILESET]
    ld b,a
    ld hl,.TilesetTileConvertionTable
.loop
    ld a,[hli]
    cp $FF
    jr z,.end
    cp b
    jr nz,.next1
    ld a,[hli]
    cp c
    jr nz,.next2
    ld a,[hl]
.end
    pop bc
    pop hl
    ret
.next1
    inc hl
.next2
    inc hl
    jr .loop
.TilesetTileConvertionTable
    ; Tileset
    ; Tile Type ID
    ; Tile ID
    db $00,TILE_J_DOWN   , TILE_00_J_DOWN
    db $00,TILE_J_UP     , TILE_00_J_UP
    db $00,TILE_J_LEFT   , TILE_00_J_LEFT
    db $00,TILE_J_RIGHT  , TILE_00_J_RIGHT
    db $00,TILE_UPP_CTR  , TILE_00_UPP_CTR
    db $00,TILE_UPP_RGT  , TILE_00_UPP_RGT
    db $00,TILE_BTM_LFT  , TILE_00_BTM_LFT
    db $00,TILE_BTM_RGT  , TILE_00_BTM_RGT
    db $00,TILE_WALKING  , TILE_00_WALKING
    db $11,TILE_J_DOWN   , TILE_11_J_DOWN
    db $11,TILE_J_UP     , TILE_11_J_UP
    db $11,TILE_J_LEFT   , TILE_11_J_LEFT
    db $11,TILE_J_RIGHT  , TILE_11_J_RIGHT
    db $11,TILE_UPP_CTR  , TILE_11_UPP_CTR
    db $11,TILE_UPP_RGT  , TILE_11_UPP_RGT
    db $11,TILE_BTM_LFT  , TILE_11_BTM_LFT
    db $11,TILE_BTM_RGT  , TILE_11_BTM_RGT
    db $11,TILE_WALKING  , TILE_11_WALKING
    db $11,TILE_CAV_HOLE , TILE_11_CAV_HOLE
    db $11,TILE_STRS_STD , TILE_11_STRS_STD
    db $11,TILE_STRS_HRZ , TILE_11_STRS_HRZ
    db $11,TILE_STRS_VRT , TILE_11_STRS_VRT
    db $11,TILE_STRS_UP  , TILE_11_STRS_UP
    db $11,TILE_STRS_DW  , TILE_11_STRS_DW
    db $03,TILE_J_DOWN   , TILE_03_J_DOWN
    db $03,TILE_J_UP     , TILE_03_J_UP
    db $03,TILE_J_LEFT   , TILE_03_J_LEFT
    db $03,TILE_J_RIGHT  , TILE_03_J_RIGHT
    db $03,TILE_UPP_CTR  , TILE_03_UPP_CTR
    db $03,TILE_UPP_RGT  , TILE_03_UPP_RGT
    db $03,TILE_BTM_LFT  , TILE_03_BTM_LFT
    db $03,TILE_BTM_RGT  , TILE_03_BTM_RGT
    db $03,TILE_WALKING  , TILE_03_WALKING
