CheckJumpExceptionFlag:

    ; Check Force Fail Flag
    bit 7,[hl] ; EX_FAIL
    jr nz,.fail

    ; Check No Bike Flag
    bit 3,[hl] ; EX_NOBIKE
    jr z,.skipBikeCheck
    ld a,[$d700] ; 1 = bike
    dec a
    jr z,.fail
.skipBikeCheck

    ; Check B pressed Flag
    bit 1,[hl] ; EX_B
    jr z,.skipBCheck
    call CheckHallOfFameWin
    jr z,.fail
    ld a,[H_CURRENTPRESSEDBUTTONS]
    bit 1,a
    jr z,.fail
.skipBCheck

    scf
    ret
.fail
    and a ; rcf
    ret

