_FuchsiaCityScript:
    ld hl,$d126
    bit 5,[hl]
    res 5,[hl]
    jr z,.next
    ld a,[wEventErikMeetSaraBit3]
    bit 3,a
    jr nz,.next
    ld a,$FA ; SafariZoneRestHouse1ErikOAM
    ld [$cc4d],a
    PREDEF RemoveMissableObject
.next
    ld hl,$d126
    bit 6,[hl]
    res 6,[hl]
    jr z,.end
    ld a,[$d7f6]
    bit 6,a
    ld de,MonOverworldDataNew2_emimonserrate+($80*((DEX_OMANYTE)%(128)))
    jr nz,.done
    bit 7,a
    ld de,MonOverworldDataNew2_emimonserrate+($80*((DEX_KABUTO)%(128)))
    jr z,.end
.done
    ld hl,$87c0
    ld bc,(BANK(MonOverworldDataNew2_emimonserrate) << 8) + $04
    call GoodCopyVideoData
.end
    call EnableAutoTextBoxDrawing
    ld hl,FuchsiaCityScriptPointers
    ld a,[W_FUCHSIACITYCURSCRIPT]
    jp CallFunctionInTable

FuchsiaCityScriptPointers:
    dw Nope
    dw FuchsiaCityScript1
    dw FuchsiaCityScript2

FuchsiaCityScript1:
    ld a,[W_XCOORD]
    ld b,a
    ld a,[W_YCOORD]
    ld c,a
    ld hl,.ErikMovement
.retry
    ld a,[hli]
    cp b
    jr nz,.next
    ld a,[hli]
    cp c
    jr nz,.next
    ld d,h
    ld e,l
    ld a,3
    ld [$ff00+$8c],a
    call MoveSprite
    ld a,2 ; FuchsiaCityScript2
    ld [W_CURMAPSCRIPT],a
    ld [W_FUCHSIACITYCURSCRIPT],a
    ret
.next
    ld a,[hli]
    cp $FF
    jr z,.retry
    jr .next
.ErikMovement
    db 30,15
    db RT,RT,RT,RT,RT,UP,UP,UP,$FF
    db 29,14
    db RT,RT,RT,RT,$FF
    db 31,14
    db DN,RT,RT,RT,RT,RT,UP,UP,UP,UP,UP,$FF

FuchsiaCityScript2:
    ld a,[$d730]
    bit 0,a
    ret nz
    ld a,$FA ; SafariZoneRestHouse1ErikOAM
    ld [$cc4d],a
    PREDEF AddMissableObject
    ld a,$F9 ; FuchsiaCityErikOAM
    ld [$cc4d],a
    PREDEF RemoveMissableObject
    ld hl,wEventErikMeetSaraBit3
    set 3,[hl]
    xor a ; FuchsiaCityScript0
    ld [W_CURMAPSCRIPT],a
    ld [W_FUCHSIACITYCURSCRIPT],a
    ld [wJoypadForbiddenButtonsMask],a
    ret

