CinnabarGymProcessAllGate:
    push bc
    xor a        ; Reset Redraw Flag
    ld [$d12f],a ; ...
    ld a,6
    ld de,wChangedBlocksNum
    ld [de],a
    ld [$FF00+$db],a
.loop
    inc de ; go to wChangedBlocksH
    ld a,[$FF00+$db]
    dec a
    add a
    push de
    ld d,$0
    ld e,a
    ld hl,.CinnabarGymGateCoords
    add hl,de
    pop de
    ld a,$C7
    ld [de],a
    inc de
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[de]
    ld b,a
    ld a,[hl]
    call .GetProspectTile
    cp b
    jr z,.skip
    push af
    ld a,1       ; Set Redraw Flag
    ld [$d12f],a ; ...
    pop af
.skip
    ld [de],a
    ld hl,$FF00+$db
    dec [hl]
    jr nz,.loop
    ld a,[$d12f] ; Check Redraw Flag
    and a        ; ...
    call nz,.RedrawMapView
    pop bc
    ret

.GetProspectTile
    push de
    push bc
    push af
    ld a,[$FF00+$db]
    ld [$FF00+$e0],a
    ld c,a
    ld b,2
    call CheckCinnabarCymGateFlag
    ld a,c
    and a
    jr nz,.open
    pop af
    jr .done
.open
    pop af
    ld a,$0E ; open
.done
    pop bc
    pop de
    ret

.RedrawMapView
    call RestoreChangedBlocks
    PREDEF_JUMP RedrawMapView

.CinnabarGymGateCoords
    ; format: LSB Changed Block Address,direction
    ; direction: $54 = horizontal gate,$5f = vertical gate
    ; Note : MSB is ever C7
    db $54,$54
    db $51,$54
    db $81,$54
    db $9E,$5f
    db $7D,$54
    db $4D,$54

OakLabHealParty:
