DisplayStarterPokedexAndResetSeenOwn:
    ld hl,wJoypadForbiddenButtonsMask
    ld a,[hl]
    push af
    push hl
    xor %00110000 ; ▼▲◄►StSeBA
    ld [hl],a
    call .GetStarter
    ld hl,wPokedexSeen
    call .FillMemory
    ld hl,wPokedexOwned
    call .FillMemory
    call .SetStarter
    ld a,[W_PLAYERSTARTER]
    call UpdatePokedex
    pop hl
    pop af
    ld [hl],a
    ret
.GetStarter
    ld a,[W_PLAYERSTARTER]
    ld [$d11e],a
    call IndexToPokedexAndRestoreD11E
    ld [$d11e],a
    ret
.FillMemory
    push hl
    xor a
    ld bc,wPokedexOwnedEnd-wPokedexOwned ; same as Seen
    call FillMemory
    pop hl
    ret
.SetStarter
    ld a,[$d11e]
    ld b,1
    ld c,a
    PREDEF_JUMP HandleBitArray

