DecreaseFossilStep:
    ld hl,$d7a3
    bit 1,[hl]
    jr z,.Skip
    ld a,[wFossilSteps]
    ld b,a
    ld a,[wFossilSteps+1]
    ld c,a
    or b
    jr nz,.FossilStepNotZero
    res 1,[hl] ; Fossil Live
    ld a,$86
    call PlaySound
    jr .Skip
.FossilStepNotZero
    dec bc
    ld a,b
    ld [wFossilSteps],a ; $d70d
    ld a,c
    ld [wFossilSteps+1],a ; $d70e
.Skip
    call .HandleEnergySteps
    ld a,[$d790]
    bit 7,a ; in the safari zone?
    ret z ; notSafariZone
    ld a,[wSafariSteps] ; $d70d
    jp ContinueSafariSteps

.HandleEnergySteps
    ld a,[wEnergySteps]
    ld b,a
    dec a
    and %00001111
    push af
    ld c,a
    ld a,b
    and %11110000
    or c
    ld [wEnergySteps],a
    pop af
    ret nz
    ; RestorePartyEnergy
    ld a,[W_NUMINPARTY]
    and a
    ret z
    ld d,a
    ld e,0
.loop
    ld hl,W_PARTYMON1_MOVE1PP
    ld bc,44
    ld a,e
    call AddNTimes ; hl now points to move's PP
    ld a,[hl] ; Read Energy
    inc a
    jr z,.JustMax
    ld [hl],a
.JustMax
    inc e
    dec d
    jr nz,.loop
    ret

