PowerPlantExplosion:
    ld hl,wFlagFollowBoulderBit7
    bit 7,[hl]
    ret nz
    call GenRandom
    cp $CC ; (204+1)/256 = 80% Explode
    jr nc,.FailExplosionOrResetScript
    ld c,10
    call DelayFrames
    ld a,[$ff00+$8c]
    dec a
    ld hl,PowerPlantVoltorbElectrode+6
    ld bc,08
    call AddNTimes
    ld a,[hl]
    call GetCryData
    call PlaySound
    call .Animation
.FailExplosionOrResetScript
    xor a ; PowerPlantScript0
    ld [W_POWERPLANTCURSCRIPT],a
    ld [W_CURMAPSCRIPT],a
    ret
.Animation
    ld a,[rBGP]
    ld [wTempInitialPalette],a
    ld b,10
.loop
    push bc
    call .SlideLeft
    call .InvertColor
    call .SlideRight
    call .WhiteColor
    call .SlideRight
    call .InvertColor
    call .SlideLeft
    call .RestoreColor
    pop bc
    ld a,b
    cp 5
    call z,.RemoveSprite
    dec b
    jr nz,.loop
    xor a
    ld [$c105],a ; delta X
    ld [wWalkCounter],a
    ret
.SlideLeft
    ld a,-01
    jr .SlideScreen
.SlideRight
    ld a,+01
    ; ft
.SlideScreen
    ld [$c105],a ; delta X
    ld a,8
    ld [wWalkCounter],a
    call AdvancePlayerSprite
    call AdvancePlayerSprite
    call AdvancePlayerSprite
    jp AdvancePlayerSprite
.RemoveSprite
    ld a,[$ff00+$8c]
    dec a
    add $4D ; First Voltorb Missable ID
    ld [$cc4d],a
    PREDEF_JUMP RemoveMissableObject
.InvertColor
    ld a,%00011011 ; 0,1,2,3 (inverted colors)
    ld [rBGP],a
    ld c,2
    jp DelayFrames
.WhiteColor
    ld a,%00000001 ; 0,0,0,1 (light colors)
    ld [rBGP],a
    ld c,2
    jp DelayFrames
.RestoreColor
    ld a,[wTempInitialPalette] ; restore initial palette
    ld [rBGP],a
    ld c,2
    jp DelayFrames

