    ld a,[$FF00+$f6]
    set 2,a
    ld [$FF00+$f6],a
    call PlaceString
    ld a,[$FF00+$f6]
    res 2,a
    ld [$FF00+$f6],a
    ld hl,wTopMenuItemY ; $cc24
    ld a,$9
    ld [hli],a
    ld a,$5
    ld [hli],a
    xor a
    ld [hli],a
    inc hl
    ld a,[$cd6c]
    ld [hli],a
    ld a,$3
    ld [hli],a
    ld [hl],$0
    ld hl,$fff6
    set 1,[hl]
    call HandleMenuInput
    ld hl,$fff6
    res 1,[hl]
    bit 1,a ; was the B button pressed?
    ret

GetMoveNameNotZero:
    ld a,[$D11E]
