; ────────────────────────────────────────────────────────────
; Get Mon Potential Move List
; ────────────────────────────────────────────────────────────

; Input : b = Level
;       : wWriteInGenericBufferBit4
;         Use "GenericBuffer+1" instead of "wMoveRelearnerMoveList+1"
;       : wNoSkillInListBit6
;         ByPass Skill in "Get Moves"
;       : wNoExclusiveInListBit7
;         ByPass "Handle Exclusive Learn Move"
;
; Output : hl/de     = First Output Move
;        : hl-1/de-1 = Move Counter (Only in "wMoveRelearnerMoveList")

GetMonPotentialMoveList:

    ; Reset Output
    call .GetPointer
    jr nz,.DontOverwriteFirstByte
    xor a
    dec de
    ld [de],a
    inc de
.DontOverwriteFirstByte
    xor a
    ld [de],a
    dec a ; a = $FF
    ld [wMaxNotExclMoveSlotId],a

    ; Check Not MEW
    ld a,[W_MONHEADER]
    cp MEW
    ret z
    
    ; Get Moves
    PREDEF GetMoves

    ; Handle Exclusive Learn Move
    ld hl,wNoExclusiveInListBit7
    bit 7,[hl]
    jr nz,.SkipExclusive
    BANKSWITCH HandleExclusiveLearnMove
.SkipExclusive

    ; Insert End List
    xor a
    ld [de],a

    ; Check End (Write in GenericBuffer)
    call .GetPointer
    ret nz

    ; Insert Counter
    ld b,-1
    ld hl,wMoveRelearnerMoveList+1
.CountLoop
    inc b
    ld a,[hli]
    and a
    jr nz,.CountLoop
    ld a,b
    ld hl,wMoveRelearnerMoveList
    ld [hli],a ; Insert Counter
    ; hl = wMoveRelearnerMoveList+1
    ld d,h
    ld e,l
    ret

.GetPointer
    ld hl,wWriteInGenericBufferBit4
    bit 4,[hl]
    ld de,wMoveRelearnerMoveList+1
    jr z,.GetPointer_End
    ld de,GenericBuffer+1
.GetPointer_End
    ld h,d
    ld l,e
    ret

; ────────────────────────────────────────────────────────────
; Move Relearner
; ────────────────────────────────────────────────────────────

RELEARN_MOVE_SCREEN_LENGHT EQU 9

MovesMenu:

    ; Start
    call SaveScreenTilesToBuffer1
    ld hl,wFlagMoveRelearnEngagedBit7
    set 7,[hl]
    ld hl,wNoSkillInListBit6
    set 6,[hl]
    ; Backup Screen "Offset"
    ld a,[wListScrollOffset]
    push af
    ; Disable Update Sprites Flag
    ld hl,$cfcb
    ld a,[hl]
    push af ; Backup Update Sprites Flag
    ld a,$ff
    ld [hl],a
    ; prevent audio fade out
    ld hl,$d72c
    set 1,[hl]
    ld a,$33
    ld [$ff00+$24],a ; Reduce the volume
    ; water/flower tile animation
    ld a,[$ff00+$d7]
    push af
    xor a
    ld [$ff00+$d7],a
    ; Quick Joypad
    ld a,1
    ld [$ffb7],a

    ; Clear Screen and Sprite and No HP Bar Palette
    call GBPalWhiteOutWithDelay3
    call ClearScreen
    call CleanLCD_OAM ; Remove Mini Sprite
    ld b,15 ; GetMovesMenuPalatteID
    call GoPAL_SET
    ; Disable Transfer
    xor a
    ld [H_AUTOBGTRANSFERENABLED],a
    call GbPalComplete

    ; Print Border
    FuncCoord 00,02
    ld hl,Coord
    ld bc,$0e12
    call TextBoxBorder

    ; Print Title
    call MovesMenuPrintTitle

    ; Get Actual Moves and Mon Potential Move List in wMoveRelearnerMoveList
    call LoadMonDataAndPrintActualMoves
    call WriteEnergyAllMovesDuringMoveRelearn
    ld a,[$cfb9] ; Level
    ld b,a       ; ...
    call GetMonPotentialMoveList

    ; Check at least one move or MEW Exception
    ld a,[W_MONHEADER]
    cp MEW
    jr z,.continue
    dec hl
    ld a,[hli]
    and a
    jp z,.return ; No Move to Learn
.continue

    ; Mini Sprite
    ld a,[$cf98]
    ld [$cd5d],a
    BANKSWITCH WriteMonPartySpriteOAMBySpecies

    ; Initialize Menù Config
    ld hl,wTopMenuItemY ; $cc24
    ld a,03
    ld [hli],a ; wTopMenuItemY
    ld a,01
    ld [hli],a ; wTopMenuItemX
    xor a
    ld [hli],a ; wCurrentMenuItem
    inc hl
    inc hl
    inc hl
    ld [hl],a ; wLastMenuItem
    ld [wListScrollOffset],a

    ; Choice Move
.Retry
    call .RemoveActualMovesArrow
    call ChoiceRelearnMove
    jr nz,.return ; B Pressed

    ; Check Move Just Known
    ld a,[$d11e]
    call .CheckMoveJustKnown
    jr z,.MoveJustKnown

    ; Backup Menu
    ld hl,wTopMenuItemY
    ld c,7
.LoopBackupMenu
    ld a,[hli]
    push af
    dec c
    jr nz,.LoopBackupMenu

    ; Learn Move
    PREDEF LearnMove

    ; Restore Menu
    ld hl,wLastMenuItem
    ld c,7
.LoopRestoreMenu
    pop af
    ld [hld],a
    dec c
    jr nz,.LoopRestoreMenu

    ; Check Result
    ld a,b
    and a
    jr z,.Retry
    call LoadMonDataAndPrintActualMoves
    call WriteEnergyAllMovesDuringMoveRelearn
    jr .Retry

.MoveJustKnown
    call Delay3 ; Show "UnfilledArrow"
    ld a,$a5 ; Error
    call PlaySoundWaitForCurrent ; play sound
    jr .Retry

.return
    ; Enable Transfer
    ld a,1
    ld [H_AUTOBGTRANSFERENABLED],a
    ; Quick Joypad
    xor a
    ld [$ffb7],a
    ; water/flower tile animation
    pop af
    ld [$ff00+$d7],a
    ; prevent audio fade out
    ld hl,$d72c
    res 1,[hl]
    ld a,$77
    ld [$ff00+$24],a
    ; Restore Palette
    call GBPalWhiteOut
    ; Restore Update Sprites Flag
    pop af
    ld [$cfcb],a

    pop af
    ld [wListScrollOffset],a ; Restore Screen "Offset"
    ld hl,wNoSkillInListBit6
    res 6,[hl]
    ld hl,wFlagMoveRelearnEngagedBit7
    res 7,[hl]
    jp LoadScreenTilesFromBuffer1

.CheckMoveJustKnown
    push hl
    push de
    ld e,a
    ld hl,$cfa0 ; Loaded Move Mon Data
    ld d,4
.Loop
    ld a,[hli]
    and a
    jr z,.MoveNotKnow
    cp e
    jr z,.MoveKnow ; z = Move Just Know
    dec d
    jr nz,.Loop
.MoveNotKnow
    ld a,e
    and a ; nz = Move doesn't Know
    jr .CheckMoveJustKnown_end
.MoveKnow
    ld a,e
.CheckMoveJustKnown_end
    pop de
    pop hl
    ret

.RemoveActualMovesArrow
    FuncCoord 01,13
    ld hl,Coord
    ld bc,$0401
    jp ClearScreenArea

MovesMenuPrintTitle:
    call GetPartyMonName2
    FuncCoord 03,00
    ld hl,Coord
    call PlaceString
    ld h,b
    ld l,c
    ld de,.MovesText
    jp PlaceString
.MovesText
    db "'s Moves@"

LoadMonDataAndPrintActualMoves:
    xor a ; player party
    ld [$cc49],a
    call LoadMonData
    ld hl,$cfa0 ; Moves
    ld de,$d0dc
    ld bc,$4
    call CopyData
    BANKSWITCH FormatMovesString
    FuncCoord 00,12
    ld hl,Coord
    ld bc,$0412
    call TextBoxBorder
    FuncCoord 02,13
    ld hl,Coord
    ld de,$d0e1
    ld a,[$FF00+$f6]
    set 2,a
    ld [$FF00+$f6],a
    call PlaceString
    ld a,[$FF00+$f6]
    res 2,a
    ld [$FF00+$f6],a
    ret

WriteEnergyAllMovesDuringMoveRelearn:
    ld d,4
.Loop4Moves
    push de
    ld c,d
    dec c
    ld hl,$cfa0 ; Moves
    ld b,0
    add hl,bc
    ld a,[hl]
    and a
    jr z,.SkipCurrentMove
    push bc
    ; Get Current Move
    dec a
    ld hl,Moves+5 ; Move Energy
    ld bc,6
    call AddNTimes
    ld a,BANK(Moves)
    ld de,W_PLAYERMOVEMAXPP ; Energy
    ld bc,1
    call FarCopyData
    ; Print Current Energy
    pop bc
    ld a,c
    FuncCoord 15,13
    ld hl,Coord
    ld bc,20
    call AddNTimes
    ld de,W_PLAYERMOVEMAXPP ; Energy
    ld bc,$0103
    call PrintNumber
    ld de,.EnergyIcon
    call PlaceString
.SkipCurrentMove
    pop de
    dec d
    jr nz,.Loop4Moves
    ret
.EnergyIcon
    db $DA,"@"

; Choice Relearn Move Selected Pokemon (a = party index)
; output a = Flag Result,[wCurrentMenuItem] = Index of Choice
ChoiceRelearnMove:

    ld hl,wWaitReleaseJoyBit5
    set 5,[hl]
    call .ResetScreen

.MenuLoop
    BANKSWITCH ShakeMiniSprite ; shake mini sprite of selected pokemon
    call GetJoypadStateLowSensitivityWaitReleaseJoy ; ▼▲◄►StSeBA
    jr nz,.MenuLoop
    bit 1,a ; was the B button pressed?
    ret nz
    bit 0,a ; was the A button pressed? 
    jr nz,.APressed
    bit 6,a ; was up button pressed?
    jr nz,.UpPressed
    bit 7,a ; was down button pressed?
    jr nz,.DownPressed
    bit 5,a ; was left button pressed?
    jr nz,.LeftPressed
    bit 4,a ; was right button pressed?
    jr nz,.RightPressed
    bit 2,a ; was select button pressed?
    jp nz,.SelectPressed
    bit 3,a ; was start button pressed?
    jr nz,.StartPressed
    jr .MenuLoop

.StartPressed
    ld a,[H_NEWLYPRESSEDBUTTONS] ; No Infinite Loop
    and a                        ; ...
    call nz,.ResetScreen         ; ...
    jr .MenuLoop

.UpPressed
    ld a,[wCurrentMenuItem]
    dec a
    jr .UpDownCommon
.DownPressed
    ld a,[wCurrentMenuItem]
    inc a
.UpDownCommon
    ld hl,wMaxMenuItem
    ld b,[hl]
    inc b ; Max Menu Id + 1 = Number of Slot
    cp b
    jr c,.UpDownEnd
    ld b,a
    ld a,[H_NEWLYPRESSEDBUTTONS] ; No Infinite Loop
    and a                        ; ...
    jr z,.MenuLoop               ; ...
    inc b
    ld a,0 ; Start
    jr nz,.UpDownEnd
    ld a,[wMaxMenuItem] ; End
.UpDownEnd
    ld [wCurrentMenuItem],a
    jr .UpOrDownPressed

.APressed
    ld hl,H_CURRENTPRESSEDBUTTONS ; ▼▲◄►StSeBA
    res 3,[hl] ; Disable Start Pressed
    call .ResetScreen
    call PlaceUnfilledArrowMenuCursor
    xor a ; szf
    ret

.LeftPressed
    FuncCoord 04,01
    ld hl,Coord
    ld a,[wListScrollOffset]
    dec a
    jr .LeftRightCommon
.RightPressed
    FuncCoord 06,01
    ld hl,Coord
    ld a,[wListScrollOffset]
    inc a
.LeftRightCommon
    call .GetNumberOfScreenMenu
    cp b
    jr c,.MenuContinue
    jr z,.RightToStart
.LeftToEnd
    ld a,b
    dec a
    jr .CheckNoInfiniteLoop
.RightToStart
    xor a
.CheckNoInfiniteLoop
    ld b,a
    ld a,[H_NEWLYPRESSEDBUTTONS] ; No Infinite Loop
    and a                        ; ...
    jp z,.MenuLoop               ; ...
    ld a,b
.MenuContinue
    ld [hl]," "
    ld [wListScrollOffset],a
    call Delay3 ; Disappear Left/Right Arrow 
    ld a,[wCurrentMenuItem]
    ld b,a
    call .GetMaxCurrentScreenMenuLenght
    cp b
    jr nc,.DontResetItemId
    ld [wCurrentMenuItem],a
.DontResetItemId
    call .ResetScreen
    jp .MenuLoop

.ResetScreen
    call .ClearScreenArea
    call .PrintMovesAndArrows
    call .PlaceMenuCursor
    call .GetCurrentMove
    call .GetMaxCurrentScreenMenuLenght
    ld [wMaxMenuItem],a
    jp Delay3 ; Wait Screen Reset

.UpOrDownPressed
    call .ClearScreenArea
    call .PrintMoves
    call .PlaceMenuCursor
    call .GetCurrentMove
    call Delay3 ; Wait Screen Update
    jp .MenuLoop

.PlaceMenuCursor
    ld hl,$fff6
    set 1,[hl]
    call PlaceMenuCursor
    ld hl,$fff6
    res 1,[hl]
    ret

.GetCurrentMove
    call .ListLenghtAndPointerToFirst
    ld a,[wCurrentMenuItem]
    ld d,a
    ld a,[wListScrollOffset]
    and a
    jr z,.skipLoopOffset
    ld e,a
    ld bc,RELEARN_MOVE_SCREEN_LENGHT
.LoopOffset
    add hl,bc ; add [wListScrollOffset] * RELEARN_MOVE_SCREEN_LENGHT
    dec e
    jr nz,.LoopOffset
.skipLoopOffset
    ld b,0
    ld c,d
    add hl,bc ; add [wCurrentMenuItem]
    ld a,[$cf98]
    cp MEW
    ld a,l
    jr z,.SkipReadMoveHL
    ld a,[hl] ; get New Move ; a = Move ID
.SkipReadMoveHL

    ; Set Move Relearned
    ld [$d0e0],a

    ; Set Move for Name
    ld [$d11e],a

    ; Fix Border and Print Title
    call .FixBorderAndPrintTitle

    ; Print Move Details Box
    ld [wPlayerSelectedMove],a
    ld a,[H_CURRENTPRESSEDBUTTONS] ; ▼▲◄►StSeBA
    and %00001100                  ; skip if start/select pressed
    jr nz,.SkipMoveDetails         ; ...
    FuncCoord 10,06
    ld hl,Coord
    ld a,[wCurrentMenuItem]
    cp 3
    jr c,.MoveDetailsBox
    ld de,-120 ; 6 Rows
    add hl,de
.MoveDetailsBox
    ld d,h
    ld e,l
    PREDEF PrintMoveDetailsBox
.SkipMoveDetails

    ; Enable Transfer
    ld a,1
    ld [H_AUTOBGTRANSFERENABLED],a

    ; Get Move Name
    call GetMoveName
    ld de,$cd6d
    jp CopyStringToCF4B

.FixBorderAndPrintTitle
    push af
    ld a,$7B ; Upper Right Corner
    FuncCoord 19,02
    ld [Coord],a
    ld a,$7A ; Horizonal Border
    FuncCoord 09,02
    ld hl,Coord
    ld d,10
.LoopFixHrzBrd
    ld [hli],a
    dec d
    jr nz,.LoopFixHrzBrd
    ld a,$7C ; Vertical Border
    FuncCoord 19,03
    ld hl,Coord
    ld d,9
    ld bc,20
.LoopFixVrtBrd
    ld [hl],a
    add hl,bc
    dec d
    jr nz,.LoopFixVrtBrd
    call MovesMenuPrintTitle
    pop af
    ret

.PrintMovesAndArrows

    ; Check more than one screen
    call .GetNumberOfScreenMenu ; b = max num of screen (1,2,...)
    dec b
    jr z,.PrintMoves ; skipArrows

    ; Print Screen Page Number
    ld a,[wListScrollOffset]
    ld c,a
    ld a,[$cf98]
    cp MEW
    ld a,"A"
    jr z,.mew
    ld a,"1"
.mew
    add c
    FuncCoord 05,01
    ld [Coord],a

    ; Print Left Arrow
    ld a,c
    and a
    ld a,$d6 ; left arrow
    jr nz,.NotScreen0
    ld a,$7f;$d5 ; left arrow transparent
.NotScreen0
    FuncCoord 04,01
    ld [Coord],a

    ; Print Right Arrow
    ld a,c ; screen num (0,1,...)
    cp b ; max num of screen - 1 (0,1,...)
    ld a,$ed ; right arrow
    jr nz,.NotLastScreen
    ld a,$7f;$ec ; right arrow transparent
.NotLastScreen
    FuncCoord 06,01
    ld [Coord],a

.PrintMoves
    call .ListLenghtAndPointerToFirst
    and a
    jr z,.end ; EmptyList
    ; Add Offset to HL
    ld a,[wListScrollOffset]
    and a
    jr z,.SkipLoopScreenLenght
    ld d,a
    ld bc,RELEARN_MOVE_SCREEN_LENGHT
.LoopScreenLenght
    add hl,bc
    dec d
    jr nz,.LoopScreenLenght
.SkipLoopScreenLenght
    ; Read Moves
    ld d,h
    ld e,l
    FuncCoord 02,03
    ld hl,Coord
    ld b,RELEARN_MOVE_SCREEN_LENGHT
.LoopMove
    ld a,[W_MONHEADER]
    cp MEW
    ld a,e
    jr z,.SkipReadMoveDE
    ld a,[de] ; Read Move Id
.SkipReadMoveDE
    and a
    jr z,.end ; EndOfList
    cp STRUGGLE
    jr z,.end ; EndOfList
    push bc
    call .PrintMove
    ld bc,20 ; New Line
    add hl,bc
    pop bc
    inc de
    dec b
    jr nz,.LoopMove
.end
    ret

.PrintMove
    push hl
    push de
    ld [$d11e],a
    call .HandleExclusiveSymbol
    call GetMoveName
    ld de,$cd6d
    call PlaceString
    pop de
    pop hl
    ret

.HandleExclusiveSymbol
    push de
    push hl
    call .ListLenghtAndPointerToFirst
    ; de = Pointer to Move to Write
    ; hl = Pointer to First Move
    ld a,e ; c = e - l
    sub l  ; ...
    ld c,a ; ...
    ld a,d          ; b = d - h - carry
    jr nc,.NotCarry ; ...
    dec a           ; ...
.NotCarry           ; ...
    sub h           ; ...
    ld b,a          ; ...
    ld a,b
    and a
    jr nz,.HandleExclusiveSymbol_End
    ; c = {0,1,...}
    ld a,[wMaxNotExclMoveSlotId]
    cp c
    jr nc,.HandleExclusiveSymbol_End
    pop hl
    ld [hl],$D2 ; Plus Symbol
    inc hl
    jr .HandleExclusiveSymbol_End2
.HandleExclusiveSymbol_End
    pop hl
.HandleExclusiveSymbol_End2
    pop de
    ret

.ListLenghtAndPointerToFirst
    ld a,[W_MONHEADER]
    cp MEW
    ld a,STRUGGLE-1
    ld hl,1
    ret z
    ld hl,wMoveRelearnerMoveList
    ld a,[hli] ; List Lenght
    ret

.GetNumberOfScreenMenu
    push af
    push hl
    call .ListLenghtAndPointerToFirst
    pop hl
    dec a
    ld b,0
.LoopUntilUnderFlow
    inc b
    sub RELEARN_MOVE_SCREEN_LENGHT
    jr nc,.LoopUntilUnderFlow
    pop af
    ret

.GetMaxCurrentScreenMenuLenght
    push bc
    push hl
    call .ListLenghtAndPointerToFirst
    pop hl
    ld b,a
    ld a,[wListScrollOffset]
    and a
    ld c,a
    ld a,b
    jr z,.skipLoopModuleLenghtByOffset
.LoopModuleLenghtByOffset
    sub RELEARN_MOVE_SCREEN_LENGHT
    dec c
    jr nz,.LoopModuleLenghtByOffset
.skipLoopModuleLenghtByOffset
    cp RELEARN_MOVE_SCREEN_LENGHT+1
    jr c,.LessOrEqualToMax
    ld a,RELEARN_MOVE_SCREEN_LENGHT
.LessOrEqualToMax
    dec a
    pop bc
    ret

.ClearScreenArea
    ; Disable Transfer
    xor a
    ld [H_AUTOBGTRANSFERENABLED],a
    FuncCoord 01,03
    ld hl,Coord
    ld bc,$0912
    call ClearScreenArea
    FuncCoord 09,00
    ld hl,Coord
    ld bc,$020b
    jp ClearScreenArea

.SelectPressed
    call .ResetScreen
    FuncCoord 01,03
    ld hl,Coord
    ld bc,09 << 8 | 18
    call ClearScreenArea
    ; Backup Menu
    ld hl,wTopMenuItemY
    ld c,7
.LoopBackupMenu
    ld a,[hli]
    push af
    dec c
    jr nz,.LoopBackupMenu
    ; SortMoves
    call SortMoves
    ; Restore Menu
    ld hl,wLastMenuItem
    ld c,7
.LoopRestoreMenu
    pop af
    ld [hld],a
    dec c
    jr nz,.LoopRestoreMenu
    jp ChoiceRelearnMove

SortMoves:
    ; Initialize Menù Config
    ld hl,wTopMenuItemY ; $cc24
    ld a,13
    ld [hli],a ; wTopMenuItemY
    ld a,01
    ld [hli],a ; wTopMenuItemX
    xor a
    ld [hli],a ; wCurrentMenuItem
    ld a,$EC ; Blank Right Arrow
    ld [hli],a ; wTileBehindCursor
    inc hl
    ld a,%11000111 ; ▼▲◄►StSeBA
    ld [hli],a ; wMenuWatchedKeys
    xor a
    ld [hl],a ; wLastMenuItem
    ld hl,W_PARTYMON1_MOVE1
    ld a,[wWhichPokemon]
    ld bc,$2c
    call AddNTimes
    ld b,4
.LoopMoves
    ld a,[hli]
    and a
    jr z,.StoreMaxItem
    dec b
    jr nz,.LoopMoves
.StoreMaxItem
    ld a,4        ; b = 4,3,2,1,0
    sub b         ; a = 0,1,2,3,4
    dec a         ; a = 255,0,1,2,3
    cp 4
    jr c,.done
    xor a         ; a = 0,0,1,2,3
.done
    ld [wMaxMenuItem],a ; wMaxMenuItem
    jr .UpdateMovesOrUpOrDownPressed
.LoopSortMenu
    call .HandleMenuInput
    bit 1,a ; was the B button pressed?
    ld hl,wFlagSortMoveBit1
    jr nz,.UndoSwap
    and %11000000 ; up or down pressed?
    jr nz,.UpdateMovesOrUpOrDownPressed
    ; select or A pressed
    bit 1,[hl]
    set 1,[hl]
    jr nz,.DoSwap
    ld a,[wCurrentMenuItem]
    ld [$cc35],a
    call PlaceUnfilledArrowMenuCursor
    jr .LoopSortMenu
.UpdateMovesOrUpOrDownPressed
    call .GetCurrentMove
    jr .LoopSortMenu
.UndoSwap
    bit 1,[hl]
    res 1,[hl]
.ResetAndLoop
    push af
    xor a
    ld [$cc35],a
    call .ClearSortMovesArrow
    pop af
    jr nz,.UpdateMovesOrUpOrDownPressed
    ret
.DoSwap
    res 1,[hl]
    ld hl,W_PARTYMON1_MOVE1
    ld a,[wWhichPokemon]
    ld bc,$2c
    call AddNTimes
    push hl
    ld a,[$cc35]
    ld c,a
    ld b,0
    add hl,bc
    ld d,h
    ld e,l
    pop hl
    ld a,[wCurrentMenuItem]
    ld c,a
    ld b,0
    add hl,bc
    ld a,[de]
    ld b,[hl]
    ld [hl],a
    ld a,b
    ld [de],a
    call LoadMonDataAndPrintActualMoves
    call WriteEnergyAllMovesDuringMoveRelearn
    ld a,1
    and a
    jr .ResetAndLoop
.HandleMenuInput
    ld a,1
    ld [wMenuWrappingEnabled],a ; wMenuWrappingEnabled
    ld hl,$fff6
    set 1,[hl]
    call HandleMenuInput
    ld hl,$fff6
    res 1,[hl]
    ret
.ClearSortMovesArrow
    FuncCoord 01,13
    ld hl,Coord
    ld bc,$0401
    jp ClearScreenArea
.GetCurrentMove
    ld hl,W_PARTYMON1_MOVE1
    ld a,[wWhichPokemon]
    ld bc,$2c
    call AddNTimes
    ld a,[wCurrentMenuItem]
    ld c,a
    ld b,0
    add hl,bc
    ld a,[hl] ; Current Move
    ld [$d11e],a
    ; Print Move Details Box
    ld [wPlayerSelectedMove],a
    FuncCoord 01,06
    ld de,Coord
.skip
    PREDEF_JUMP PrintMoveDetailsBox

HandleExclusiveLearnMove:
    ; de = Pointer to next Potential Move

    ; Backup
    ld a,[wBufferPointerByte1]
    push af
    ld a,[wBufferPointerByte2]
    push af

    call .GetBufferPointerToCorrectExclusiveLearnMoveList

    ; Process Potential Store Byte
    ld hl,$cf9d ; Ex Type1
    ld c,0      ; Byte 0
    call .SearchSetBit
    ld hl,$cf9e ; Ex Type2
    ld c,1      ; Byte 1
    call .SearchSetBit
    ld hl,wTempExclusiveByte01
    ld c,2      ; Byte 2
    call .SearchSetBit
    ld hl,wTempExclusiveByte02
    ld c,3      ; Byte 3
    call .SearchSetBit
    ld hl,wTempExclusiveByte03
    ld c,4      ; Byte 4
    call .SearchSetBit
    ld hl,$cfb7 ; Ex Move 3 PP
    ld c,5      ; Byte 5
    call .SearchSetBit

    ; Restore
    pop af
    ld [wBufferPointerByte2],a
    pop af
    ld [wBufferPointerByte1],a
    ret

.SearchSetBit
    ld a,[hl]
    ld b,8
.LoopBit
    srl a
    jr nc,.NextBit
    call .BitFound
.NextBit
    dec b
    jr nz,.LoopBit
    ret

.GetBufferPointerToCorrectExclusiveLearnMoveList
    push de
    ld hl,ExclusiveMoveLearnTable
    ld a,[$cf98] ; Pokemon ID
    ld [$d11e],a
    call IndexToPokedexAndRestoreD11E
    ld b,0
    add a
    rl b
    ld c,a
    add hl,bc
    ld de,wBufferPointerByte1
    ld bc,2
    call CopyData
    pop de
    ret

.BitFound
    ; c = Byte (0,1,...)
    ; b = Bit  (8,7,...,1)
    push af
    push bc
    push hl
    ld a,8
    sub b
    ld b,a ; b = Bit (0,1,...,7)
    call .GetPointerToCorrectExclusiveLearnMoveList
    push de ; Backup Pointer to Move List Current Elements
    ld a,c
    and a
    jr z,.SkipLoopCByte
    ld d,c
.LoopCByte
    ld e,8
.Loop8Bit
    ld a,[hli]
    and a
    jr z,.OutOfRange
    dec e
    jr nz,.Loop8Bit
    dec d
    jr nz,.LoopCByte
.SkipLoopCByte
    ld a,b
    and a
    jr z,.SkipLoopBBit
    ld e,b
.LoopBBit
    ld a,[hli]
    and a
    jr z,.OutOfRange
    dec e
    jr nz,.LoopBBit
.SkipLoopBBit
    ld a,[hl] ; Exclusive Move
    and a
    jr z,.OutOfRange
    call CheckSkillInList
    call nz,IsSkill
    jr c,.OutOfRange
    pop de ; Restore Pointer to Move List Current Elements
    ld b,a
    inc a
    jr z,.end ; $FF = Empty Move
    call .CheckMoveJustPotentialKnow
    jr c,.end
    ld a,b
    ld [de],a
    inc de
.end
    pop hl
    pop bc
    pop af
    ret
.OutOfRange
    pop de ; Restore Pointer to Move List Current Elements
    jr .end

.GetPointerToCorrectExclusiveLearnMoveList
    ld hl,wBufferPointerByte1
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ret

.CheckMoveJustPotentialKnow
    push hl
    ld a,[$cf98]
    cp MEW
    ld hl,1
    jr z,.Loop
    call .GetPointer
.Loop
    ld a,h
    cp d ; Actual Position MSB
    jr nz,.ReadMove
    ld a,l
    cp e ; Actual Position LSB
    jr z,.ConfirmExclusive
.ReadMove
    ld a,[hli]
    cp b
    jr nz,.Loop
.MoveJustPotentialKnow
    scf
    pop hl
    ret
.ConfirmExclusive
    and a ; rcf
    pop hl
    ret

.GetPointer
    ld hl,wWriteInGenericBufferBit4
    bit 4,[hl]
    ld hl,wMoveRelearnerMoveList+1
    ret z
    ld hl,GenericBuffer+1
    ret

AddPokemonToParty_TryToAddExclusiveMove_:
    ; Backup
    ld a,[wWhichPokemon]
    push af
    ld a,[$cc49]
    push af

    ; Get Move List
    ld a,[$FF00+$e4] ; Mon Id +1
    dec a
    ld [wWhichPokemon],a
    xor a ; player party
    ld [$cc49],a
    call LoadMonData
    ld a,[W_MONHEADER]
    cp MEW
    jr z,.end
    ld a,[$cfb9] ; Level
    ld b,a       ; ...
    call GetMonPotentialMoveList

    ; Save Exclusive Move in Mon Internal Bytes from MonPotentialMoveList
    ld hl,wMoveRelearnerMoveList
    ld a,[hli]
    ld b,a
    call .Loop

    ; Save Exclusive Move in Mon Internal Bytes from 4 Moves
    ld hl,W_PARTYMON1_MOVE1
    ld a,[wWhichPokemon]
    ld bc,$2c
    call AddNTimes
    ld b,4
    call .Loop

    ; Restore
.end
    pop af
    ld [$cc49],a
    pop af
    ld [wWhichPokemon],a
    ret
.Loop
    ld a,[hli]
    and a
    ret z
    ld [$d0e0],a
    push bc
    push hl
    ; Get Mon OT Name to Try Add Exclusive Move
    ld hl,W_PARTYMON1OT+8
    ld a,[wWhichPokemon]
    ld bc,11
    call AddNTimes
    ld d,h
    ld e,l
    ld hl,GenericBuffer+1
    ld a,e
    ld [hli],a
    ld [hl],d
    ; Get Mon Start to Try Add Exclusive Move
    ld hl,W_PARTYMON1_NUM
    ld a,[wWhichPokemon]
    ld bc,$2c
    call AddNTimes
    ld d,h
    ld e,l
    call TryToAddExclusiveMove
    pop hl
    pop bc
    dec b
    jr nz,.Loop
    ret

SentNewMonToBox_TryToAddExclusiveMove:
    ; Backup
    ld a,[wWhichPokemon]
    push af
    ld a,[$cc49]
    push af

    ; Get Move List
    xor a ; id = 0
    ld [wWhichPokemon],a
    ld a,2 ; current box
    ld [$cc49],a
    call LoadMonData
    ld a,[W_MONHEADER]
    cp MEW
    jr z,.end
    ld a,[$cf9b] ; Level
    ld b,a       ; ...
    call GetMonPotentialMoveList

    ; Save Exclusive Move in Mon Internal Bytes from MonPotentialMoveList
    ld hl,wMoveRelearnerMoveList
    ld a,[hli]
    ld b,a
    call .Loop

    ; Save Exclusive Move in Mon Internal Bytes from 4 Moves
    ld hl,W_BOXMON1DATA+(W_PARTYMON1_MOVE1-W_PARTYMON1DATA)
    ld b,4
    call .Loop

    ; Restore
.end
    pop af
    ld [$cc49],a
    pop af
    ld [wWhichPokemon],a
    ret
.Loop
    ld a,[hli]
    and a
    ret z
    ld [$d0e0],a
    push bc
    push hl
    ; Get Mon OT Name to Try Add Exclusive Move
    ld de,$dd2a+8 ; BOXMON1OT
    ld hl,GenericBuffer+1
    ld a,e
    ld [hli],a
    ld [hl],d
    ; Get Mon Start to Try Add Exclusive Move
    ld de,W_BOXMON1DATA
    call TryToAddExclusiveMove
    pop hl
    pop bc
    dec b
    jr nz,.Loop
    ret

; Input
; [$d0e0] = Learned Move
; [de] = Mon Start
; [GenericBuffer+1]=Pointer to Mon OT last 3 Byte
TryToAddExclusiveMove:
    ld a,[de] ; mon ID
    ld hl,ExclusiveMoveLearnTable
    ld [$d11e],a
    call IndexToPokedexAndRestoreD11E
    ld b,0
    add a
    rl b
    ld c,a
    add hl,bc
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ld a,[$d0e0] ; Learned Move
    ld b,a
    ld c,0
.Loop
    ld a,[hli]
    and a
    ret z
    cp b
    jr z,.MoveFound
    inc c
    jr .Loop
.MoveFound ; c = id move in Table
    ; Get correct start point in de
    ld a,c
    cp 8*2 ; check if the move is in the first 2 bytes
    jr c,.notInOTName
    cp 8*5 ; check if the move is in the first 4 bytes
    jr nc,.notInOTName
    ld hl,GenericBuffer+1
    ld a,[hli]
    ld d,[hl]
    ld e,a
.notInOTName
    push de
    ld hl,.LocationByteOffset
    ld d,0
    ld e,c
    srl e ; Divided by 8
    srl e ; ...
    srl e ; ...
    add hl,de
    pop de
    ld l,[hl]
    ld h,0
    add hl,de
    ; hl = pointer to mon correct Byte to flag
    ld a,c
    and %00000111 ; Mask to obtain bit id (0,1,...,7)
    ld b,a
    inc b ; (1,2,...,8)
    ld c,%00000000 ; Start Final Bit Mask with all bit reset
    scf
.LoopBit
    rl c ; rotate Final Bit Mask
    and a ; rcf
    dec b
    jr nz,.LoopBit
    ld a,[hl]
    or c ; set correct bit
    ld [hl],a
    ret
.LocationByteOffset
    db W_PARTYMON1_TYPE1-W_PARTYMON1_NUM
    db W_PARTYMON1_TYPE2-W_PARTYMON1_NUM
    db 0
    db 1
    db 2
    db W_PARTYMON1_MOVE3PP-W_PARTYMON1_NUM

