; Input
; $d0e0 = Move ID
; wWhichPokemon = Mon Party ID
CheckMonAlreadyKnowMove:
    xor a ; player party
    ld [$cc49],a
    call LoadMonData
    ld a,[$cfb9] ; Level
    ld b,a       ; ...
    call GetMonPotentialMoveList
    ; ft

CheckMonAlreadyKnowMoveQuick:
    ld a,[W_MONHEADER]
    cp MEW
    jr z,.Find
    ld a,[$d0e0]
    ld b,a
    ld hl,wMoveRelearnerMoveList
    ld a,[hli]
    ld c,a
.Loop
    ld a,[hli]
    and a
    jr z,.NotFind
    cp b
    jr z,.Find
    dec c
    jr nz,.Loop
.NotFind
    and a
    ret
.Find
    scf
    ret

; ────────────────────────────────────────────────────────────

CheckEnableLastPkmn:
    ld hl,wEventEnableOakLastPkmnBit4
    bit 4,[hl]
    jr nz,.Ignore
    push hl
    ld hl,W_OBTAINEDBADGES
    ld b,$1
    call CountSetBits
    ld a,[$d11e] ; Num of Badges
    cp 7
    pop hl
    jr c,.Ignore
    set 4,[hl]
    pop hl ; Delete Return Pointer
    ld hl,EnableLastPkmnText
    call PrintText
    jp TextScriptEnd
.Ignore
    ld hl,UnnamedText_1d31d
    ret

EnableLastPkmnText:
    TX_FAR _EnableLastPkmnText
    db "@"

GetOakLastPkmn:
    ld hl,wEventEnableOakLastPkmnBit4
    bit 4,[hl]
    jr z,.Ignore
    ld a,[W_PLAYERSTARTER]
    cp CHARMANDER
    jr z,.Charmander
    cp SQUIRTLE
    jr z,.Squirtle
.Bulbasaur
    ld a,SQUIRTLE
    ld d,$2c
    jr .Done
.Charmander
    ld a,BULBASAUR
    ld d,$2d
    jr .Done
.Squirtle
    ld a,CHARMANDER
    ld d,$2b
.Done
    push de
    push af
    call UpdatePokedex
    pop af
    ld b,a
    ld c,5
    ld a,1
    ld [wTempAlternateFormIndex],a
    call GivePokemon
    pop de
    ret nc ; PartyFull
    ld a,d
    ld [$cc4d],a
    PREDEF_JUMP RemoveMissableObject ; Hide Last Pokeball
.Ignore
    ld hl,OaksLabLastMonText ; $5243
    jp PrintText

GiveVoltorb:
    push bc
    ld hl,VoltorbText
    call PrintText
    pop bc
    ld a,b
    push bc
    call UpdatePokedex
    pop bc
    jp GivePokemon

VoltorbText:
    TX_FAR _VoltorbText
    db "@"

DiglettsCaveRoute2Text1:
    db $08 ; asm
    ld hl,.end
    push hl
    ld b,AUGER
    PREDEF _IsItemInBagOrBox
    ld hl,.DiglettsCaveRoute2Text1
    ret nz
    ld hl,.AugerReceiveText1
    call PrintText
    ld bc,(AUGER << 8) | 1
    call GiveItem
    ld hl,.AugerNoRoomText
    ret nc
    ld hl,.AugerReceiveText2
    ret
.end
    call PrintText
    jp TextScriptEnd
.AugerReceiveText1
    TX_FAR _AugerReceiveText1
    db "@"
.AugerReceiveText2
    TX_FAR _ReceivedText
    db $11,"@"
.AugerNoRoomText
    TX_FAR _AugerNoRoomText
    db $0F,"@"
.DiglettsCaveRoute2Text1
    TX_FAR _DiglettsCaveRoute2Text1
    db "@"

