Func_21879: ; 21879 (8:5879)
    ld c,CH0
.loop
    ld b,$0
    ld hl,$c026
    add hl,bc
    ld a,[hl]
    and a
    jr z,.nextChannel
    ld a,c
    cp CH4
    jr nc,.applyAffects ; if sfx channel
    ld a,[$c002]
    and a
    jr z,.applyAffects
    bit 7,a
    jr nz,.nextChannel
    set 7,a
    ld [$c002],a
    xor a
    ld [$FF00+$25],a
    ld [$FF00+$1a],a
    ld a,$80
    ld [$FF00+$1a],a
    jr .nextChannel
.applyAffects
    call Music8_ApplyMusicAffects
.nextChannel
    ld a,c
    inc c
    cp CH7
    jr nz,.loop
    ret

; this routine checks flags for music effects currently applied
; to the channel and calls certain functions based on flags.
; known flags for $c02e:
;    1: call has been used
;    3: a toggle used only by this routine for vibrato
;    4: pitchbend flag
;    6: dutycycle flag
Music8_ApplyMusicAffects: ; 218ae (8:58ae)
    ld b,$0
    ld hl,$c0b6 ; delay unitl next note
    add hl,bc
    ld a,[hl]
    cp $1 ; if the delay is 1,play next note
    jp z,Music8_PlayNextNote
    dec a ; otherwise,decrease the delay timer
    ld [hl],a
    ld a,c
    cp CH4
    jr nc,.startChecks ; if a sfx channel
    ld hl,$c02a
    add hl,bc
    ld a,[hl]
    and a
    jr z,.startChecks
    ret
.startChecks
    ld hl,$c02e
    add hl,bc
    bit 6,[hl] ; dutycycle
    jr z,.checkForExecuteMusic
    call Music8_ApplyDutyCycle
.checkForExecuteMusic
    ld b,$0
    ld hl,$c036
    add hl,bc
    bit 0,[hl]
    jr nz,.checkForPitchBend
    ld hl,$c02e
    add hl,bc
    bit 2,[hl]
    jr nz,.disablePitchBendVibrato
.checkForPitchBend
    ld hl,$c02e
    add hl,bc
    bit 4,[hl] ; pitchbend
    jr z,.checkVibratoDelay
    jp Music8_ApplyPitchBend
.checkVibratoDelay
    ld hl,$c04e ; vibrato delay
    add hl,bc
    ld a,[hl]
    and a ; check if delay is over
    jr z,.checkForVibrato
    dec [hl] ; otherwise,dec delay
.disablePitchBendVibrato
    ret
.checkForVibrato
    ld hl,$c056 ; vibrato rate
    add hl,bc
    ld a,[hl]
    and a
    jr nz,.vibrato
    ret ; no vibrato
.vibrato
    ld d,a
    ld hl,$c05e
    add hl,bc
    ld a,[hl]
    and $f
    and a
    jr z,.vibratoAlreadyDone
    dec [hl] ; apply vibrato pitch change
    ret
.vibratoAlreadyDone
    ld a,[hl]
    swap [hl]
    or [hl]
    ld [hl],a ; reset the vibrato value and start again
    ld hl,$c066
    add hl,bc
    ld e,[hl] ; get note pitch
    ld hl,$c02e
    add hl,bc
    bit 3,[hl] ; this is the only code that sets/resets bit three so
    jr z,.unset ; it continuously alternates which path it takes
    res 3,[hl]
    ld a,d
    and $f
    ld d,a
    ld a,e
    sub d
    jr nc,.noCarry
    ld a,$0
.noCarry
    jr .done
.unset
    set 3,[hl]
    ld a,d
    and $f0
    swap a
    add e
    jr nc,.done
    ld a,$ff
.done
    ld d,a
    ld b,$3
    call Func_21ff7
    ld [hl],d
    ret

; this routine executes all music commands that take up no time,
; like tempo changes,duty changes etc. and doesn't return
; until the first note is reached
Music8_PlayNextNote: ; 21946 (8:5946)
    ld hl,$c06e
    add hl,bc
    ld a,[hl]
    ld hl,$c04e
    add hl,bc
    ld [hl],a
    ld hl,$c02e
    add hl,bc
    res 4,[hl]
    res 5,[hl]
    ld a,c
    cp CH4
    jr nz,.beginChecks
    ld a,[$d083]
    bit 7,a
    ret nz
.beginChecks
    call Music8_endchannel
    ret

Music8_endchannel: ; 21967 (8:5967)
    call Music8_GetNextMusicByte
    ld d,a
    cp $ff ; is this command an endchannel?
    jp nz,Music8_callchannel ; no
    ld b,$0 ; yes
    ld hl,$c02e
    add hl,bc
    bit 1,[hl]
    jr nz,.returnFromCall
    ld a,c
    cp CH3
    jr nc,.noiseOrSfxChannel
    jr .asm_219c0
.noiseOrSfxChannel
    res 2,[hl]
    ld hl,$c036
    add hl,bc
    res 0,[hl]
    cp CH6
    jr nz,.notSfxChannel3
    ld a,$0
    ld [$FF00+$1a],a
    ld a,$80
    ld [$FF00+$1a],a
.notSfxChannel3
    jr nz,.asm_219a3
    ld a,[$c003]
    and a
    jr z,.asm_219a3
    xor a
    ld [$c003],a
    jr .asm_219c0
.asm_219a3
    jr .asm_219c9
.returnFromCall
    res 1,[hl]
    ld d,$0
    ld a,c
    add a
    ld e,a
    ld hl,$c006
    add hl,de
    push hl ; store current channel address
    ld hl,$c016
    add hl,de
    ld e,l
    ld d,h
    pop hl
    ld a,[de]
    ld [hli],a
    inc de
    ld a,[de]
    ld [hl],a ; loads channel address to return to
    jp Music8_endchannel
.asm_219c0
    ld hl,Unknown_222de
    add hl,bc
    ld a,[$FF00+$25]
    and [hl]
    ld [$FF00+$25],a
.asm_219c9
    ld a,[$c02a]
    cp $14
    jr nc,.asm_219d2
    jr .asm_219ef
.asm_219d2
    ld a,[$c02a]
    cp $86
    jr z,.asm_219ef
    jr c,.asm_219dd
    jr .asm_219ef
.asm_219dd
    ld a,c
    cp CH4
    jr z,.asm_219e6
    call Func_21e6d
    ret c
.asm_219e6
    ld a,[$c005]
    ld [$FF00+$24],a
    xor a
    ld [$c005],a
.asm_219ef
    ld hl,$c026
    add hl,bc
    ld [hl],b
    ret

Music8_callchannel: ; 219f5 (8:59f5)
    cp $fd ; is this command a callchannel?
    jp nz,Music8_loopchannel ; no
    call Music8_GetNextMusicByte ; yes
    push af
    call Music8_GetNextMusicByte
    ld d,a
    pop af
    ld e,a
    push de ; store pointer
    ld d,$0
    ld a,c
    add a
    ld e,a
    ld hl,$c006
    add hl,de
    push hl
    ld hl,$c016
    add hl,de
    ld e,l
    ld d,h
    pop hl
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[hld]
    ld [de],a ; copy current channel address
    pop de
    ld [hl],e
    inc hl
    ld [hl],d ; overwrite current address with pointer
    ld b,$0
    ld hl,$c02e
    add hl,bc
    set 1,[hl] ; set the call flag
    jp Music8_endchannel

Music8_loopchannel: ; 21a2a (8:5a2a)
    cp $fe ; is this command a loopchannel?
    jp nz,Music8_notetype ; no
    call Music8_GetNextMusicByte ; yes
    ld e,a
    and a
    jr z,.infiniteLoop
    ld b,$0
    ld hl,$c0be
    add hl,bc
    ld a,[hl]
    cp e
    jr nz,.loopAgain
    ld a,$1 ; if no more loops to make,
    ld [hl],a
    call Music8_GetNextMusicByte ; skip pointer
    call Music8_GetNextMusicByte
    jp Music8_endchannel
.loopAgain ; inc loop count
    inc a
    ld [hl],a
    ; ft
.infiniteLoop ; overwrite current address with pointer
    call Music8_GetNextMusicByte
    push af
    call Music8_GetNextMusicByte
    ld b,a
    ld d,$0
    ld a,c
    add a
    ld e,a
    ld hl,$c006
    add hl,de
    pop af
    ld [hli],a
    ld [hl],b
    jp Music8_endchannel

Music8_notetype: ; 21a65 (8:5a65)
    and $f0
    cp $d0 ; is this command a notetype?
    jp nz,Music8_togglecall ; no
    ld a,d ; yes
    and $f
    ld b,$0
    ld hl,$c0c6
    add hl,bc
    ld [hl],a ; store low nibble as speed
    ld a,c
    cp CH3
    jr z,.noiseChannel ; noise channel has 0 params
    call Music8_GetNextMusicByte
    ld d,a
    ld a,c
    cp CH2
    jr z,.musicChannel3
    cp CH6
    jr nz,.notChannel3
    ld hl,$c0e7
    jr .sfxChannel3
.musicChannel3
    ld hl,$c0e6
.sfxChannel3
    ld a,d
    and $f
    ld [hl],a ; store low nibble of param as duty
    ld a,d
    and $30
    sla a
    ld d,a
    ; ft

    ; if channel 3,store high nibble as volume
    ; else,store volume (high nibble) and fade (low nibble)
.notChannel3
    ld b,$0
    ld hl,$c0de
    add hl,bc
    ld [hl],d
.noiseChannel
    jp Music8_endchannel

Music8_togglecall: ; 21aa4 (8:5aa4)
    ld a,d
    cp $e8 ; is this command an togglecall?
    jr nz,Music8_vibrato ; no
