PrintTypesFull:
    call Load16BitRegisters
    ld a,[W_MONHTYPE1]
    call .PrintSingleType
    ld a,[W_MONHTYPE2]
    call .PrintSingleType
    ld a,[W_MONHTYPE3]
    call .PrintSingleType
    ld a,[W_MONHTYPE4]
    ; ft
.PrintSingleType
    push hl
    call PrintMoveType_
    pop hl
    ld bc,20
    add hl,bc
    ret

PrintTypes:
    call Load16BitRegisters
    ld a,[W_MONHTYPE3]
    and a
    jr nz,.MoreThan2Types
    ld a,[W_MONHTYPE1]
    call .PrintSingleType
    ld a,[W_MONHTYPE2]
    ; ft
.PrintSingleType
    push hl
    call PrintMoveType_
    pop hl
    ld bc,20
    add hl,bc
    ret

.MoreThan2Types
    ld a,[W_MONHTYPE1]
    call .PrintSingleTypeShort1
    ld a,[W_MONHTYPE2]
    call .PrintSingleTypeShort2
    ld a,[W_MONHTYPE3]
    call .PrintSingleTypeShort1
    ld a,[W_MONHTYPE4]
    ; ft
.PrintSingleTypeShort2
    push hl
    call PrintMoveTypeShort_
    pop hl
    ld bc,-15
    add hl,bc
    ret
.PrintSingleTypeShort1
    push hl
    call PrintMoveTypeShort_
    pop hl
    ld bc,20
    add hl,bc
    ret

PrintMoveType:
    call Load16BitRegisters
    ld a,[W_PLAYERMOVETYPE]
PrintMoveType_:
    push hl
    add a
    ld hl,TypeNamePointers
    ld e,a
    ld d,$0
    add hl,de
    ld a,[hli]
    ld e,a
    ld d,[hl]
    pop hl
    jp PlaceString

PrintMoveTypeShort:
    call Load16BitRegisters
    ld a,[W_PLAYERMOVETYPE]
PrintMoveTypeShort_:
    push hl
    add a
    ld hl,TypeNamePointersShort
    ld e,a
    ld d,$0
    add hl,de
    ld a,[hli]
    ld e,a
    ld d,[hl]
    pop hl
    ld b,3
.loop
    ld a,[de]
    cp "@"
    ret z
    ld [hli],a
    inc de
    dec b
    jr nz,.loop
    ret

