LeechSeedEffect_:
    ld hl,W_ENEMYBATTSTATUS2 ; $d068
    ld de,W_ENEMYMONTYPES
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.done
    ld hl,W_PLAYERBATTSTATUS2 ; $d063
    ld de,W_PLAYERMONTYPES
.done
    push hl
    push de
    BANKSWITCH MoveHitTestPlus
    pop de
    pop hl
    jr nz,.moveMissed
    ld a,[de]
    cp GRASS
    jr z,.doesntAffect
    inc de
    ld a,[de]
    cp GRASS
    jr z,.doesntAffect
    inc de
    ld a,[de]
    cp GRASS
    jr z,.doesntAffect
    inc de
    ld a,[de]
    cp GRASS
    jr z,.doesntAffect
    bit 7,[hl] ; SEEDED
    jr nz,.justSeeded
    set 7,[hl] ; SEEDED
    BANKSWITCH PlayCurrentMoveAnimation2
    ld hl,.WasSeededText ; $7ef2
    jp .DrawHudAndPrintText
.moveMissed
    call .PlayCurrentMoveAnimation
    BANKSWITCH_JUMP PrintMoveFailureText
.doesntAffect
    call .PlayCurrentMoveAnimation
    BANKSWITCH_JUMP PrintDoesntAffectMonText
.justSeeded
    call .PlayCurrentMoveAnimation
    ld c,50
    call DelayFrames
    ld hl,.WasJustSeededText
    jp PrintText
.PlayCurrentMoveAnimation
    BANKSWITCH_JUMP PlayCurrentMoveAnimation
.DrawHudAndPrintText
    push hl
    PREDEF DrawHUDsAndHPBars
    pop hl
    jp PrintText
.WasSeededText
    TX_FAR _WasSeededText
    db "@"
.WasJustSeededText
    TX_FAR _WasJustSeededText
    db "@"

