DisplayEffectiveness:
    ld a,[H_WHOSETURN]
    and a
    ld hl,W_PLAYERMOVEEFFECT
    ld de,$d06a ; PlayerNumAttacksLeft
    jr z,.ok
    ld hl,W_ENEMYMOVEEFFECT
    ld de,$d06f ; EnemyNumAttacksLeft
.ok
    ld a,[hld] ; hl ► W_PLAYERMOVENUM/W_ENEMYMOVENUM
    cp ATTACK_TWICE_EFFECT
    jr z,.CheckMultiTurn
    cp TWO_TO_FIVE_ATTACKS_EFFECT
    jr z,.CheckMultiTurn
    ld a,[hl]
    cp TWINEEDLE
    jr nz,.continue
.CheckMultiTurn
    ld a,[de]
    and a
    ret nz ; kickout if MultiAttack
.continue
    xor a
    ld hl,H_MULTIPLICAND
    ld [hli],a
    ld [hli],a
    ld a,[$D05B]
    and a,%01111111
    push af
    ld [hli],a
    ld [hl],10
    call Multiply
    ld a,[H_PRODUCT+2]
    ld [wTmpDmgMultiplier],a
    ld a,[H_PRODUCT+3]
    ld [wTmpDmgMultiplier+1],a
    pop af
    cp 10
    ret z
    cp 35
    ld hl,.ExtremelyEffectiveText
    jr nc,.done
    cp 25
    ld hl,.UltraEffectiveText
    jr nc,.done
    cp 20
    ld hl,.SuperEffectiveText
    jr nc,.done
    cp 15
    ld hl,.VeryEffectiveText
    jr nc,.done
    cp 10
    ld hl,.QuiteEffectiveText
    jr nc,.done
    cp 08
    ld hl,.AlmostEffectiveText
    jr nc,.done
    cp 05
    ld hl,.NotVeryEffectiveText
    jr nc,.done
    and a ; cp 00
    ld hl,.AlmostIneffectiveText
    jr nz,.done
    ld hl,.IneffectiveText
.done
    jp PrintText
.ExtremelyEffectiveText
    TX_FAR _ExtremelyEffectiveText
    db "@"
.UltraEffectiveText
    TX_FAR _UltraEffectiveText
    db "@"
.SuperEffectiveText
    TX_FAR _SuperEffectiveText
    db "@"
.VeryEffectiveText
    TX_FAR _VeryEffectiveText
    db "@"
.QuiteEffectiveText
    TX_FAR _QuiteEffectiveText
    db "@"
.AlmostEffectiveText
    TX_FAR _AlmostEffectiveText
    db "@"
.NotVeryEffectiveText
    TX_FAR _NotVeryEffectiveText
    db "@"
.AlmostIneffectiveText
    TX_FAR _AlmostIneffectiveText
    db "@"
.IneffectiveText
    TX_FAR _IneffectiveText
    db "@"

