CompareSpeedAndGetRandomEffort:
    call CompareSpeed
    jr z,.speedEqual
    jr nc,.playerMovesFirst
.enemyMovesFirst
    ld b,$60 ; 37.5%
    jr .end
.speedEqual
    ld b,$A0 ; 62.5%
    jr .end
.playerMovesFirst
    ld b,$F0 ; 93.75%
.end
    call GenRandom
    cp b
    ret

CompareSpeed:
    ld de,W_PLAYERMONSPEED ; player speed value
