AIRecoverHP: ; 3a6da (e:66da)
; heal b HP and print "trainer used $(a) on pokemon!"
    ld [$CF05],a
    ld hl,$CFE7
    ld a,[hl]
    ld [wHPBarOldHP],a
    add b
    ld [hld],a
    ld [wHPBarNewHP],a
