    jr z,.done_fainted
.alive
    inc hl
    inc hl
    ld a,[hl] ; status
    and a
    ld b,$32 ; black ball (status)
    jr nz,.done
    dec b ; regular ball
    jr .done
.done_fainted
    inc hl
    inc hl
.done
    ld a,b
    ld [de],a
    ld bc,$0028 ; rest of mon struct
