AfterEvolution_TryToAddExclusiveMove:
    ; Backup
    ld a,[$d11e]
    ld [$cf91],a
    push af
    ld a,[wWhichPokemon]
    push af
    ld a,[$cc49]
    push af

    ; Get Pre Evolution Form Move List
    call GetUpdatedActualMoveList

    ; Save Exclusive Move in Mon Internal Bytes from MonPotentialMoveList
    ld hl,wMoveRelearnerMoveList
    ld a,[hli]
    ld b,a
    call .Loop

    ; Save Exclusive Move in Mon Internal Bytes from 4 Moves
    ld hl,W_PARTYMON1_MOVE1
    ld a,[wWhichPokemon]
    ld bc,$2c
    call AddNTimes
    ld b,4
    call .Loop

    ; Restore
    pop af
    ld [$cc49],a
    pop af
    ld [wWhichPokemon],a
    pop af
    ld [$d11e],a
    ld [$cf91],a
    ld [wNewMonIdDuringLearnMove],a
    jr LearnMoveCommon
.Loop
    ld a,[hli]
    and a
    ret z
    and a
    jr z,.next
    ld [$d0e0],a
    push bc
    push hl
    ; Get Mon OT Name to Try Add Exclusive Move
    ld hl,W_PARTYMON1OT+8
    ld a,[wWhichPokemon]
    ld bc,11
    call AddNTimes
    ld d,h
    ld e,l
    ld hl,GenericBuffer+1
    ld a,e
    ld [hli],a
    ld [hl],d
    ; Get Mon Start to Try Add Exclusive Move
    ld hl,W_PARTYMON1_NUM
    ld a,[wWhichPokemon]
    ld bc,$2c
    call AddNTimes
    ld d,h
    ld e,l
    BANKSWITCH TryToAddExclusiveMove
    pop hl
    pop bc
.next
    dec b
    jr nz,.Loop
    ret

GetUpdatedActualMoveList:
    xor a ; player party
    ld [$cc49],a
    call LoadMonData
    ld a,[$cfb9] ; Level
    ld b,a       ; ...
    PREDEF_JUMP GetMonPotentialMoveList

LearnMoveFromLevelUp:
    ld a,[$d11e]
    ld [$cf91],a
    cp MEW
    ret z ; Mew just know every Move!
    ld [wNewMonIdDuringLearnMove],a
    ld hl,W_PARTYMON1_LEVEL
    ld a,[wWhichPokemon] ; $cf92
    ld bc,$2c
    call AddNTimes
    ld a,[hl]
    push hl ; Backup Level
    push af ; ...
    ld a,[$cd46] ; load the current level into a ($cd46 = wTempCoins1)
    ld [hl],a ; Old Level because "CheckMonAlreadyKnowMove" fail 100% if not
    xor a
    ld [$cd46],a
    call GetUpdatedActualMoveList
    call LearnMoveCommon
    pop af    ; Restore Level
    pop hl    ; ...
    ld [hl],a ; ...
    ret

LearnMoveCommon:
    call .GetPotentialNewMoves
.learnSetLoop
    ld a,[hli]
    and a
    jr z,.done
.learnmove
    ld [$d0e0],a
    push hl ; Backup Pointer to Current Learn Move's Level
    BANKSWITCH CheckMonAlreadyKnowMoveQuick
    jr c,.LearnEndOrJustKnow
    ld a,[$d0e0]
    ld [$d11e],a
    call GetMoveName
    call CopyStringToCF4B
    PREDEF LearnMove
    call .GetPotentialNewMoves
.LearnEndOrJustKnow
    pop hl ; Restore Pointer to Current Learn Move's Level
    jr .learnSetLoop
.done
    ld a,[wNewMonIdDuringLearnMove]
    ld [$cf91],a
    ld [$d11e],a
    ret

.GetPotentialNewMoves
    ld a,[wNewMonIdDuringLearnMove]
    ld [$d0b5],a
    ld [$cf91],a
    ld hl,W_PARTYMON1_MOVE2PP ; move2pp
    ld a,[wWhichPokemon] ; $cf92
    ld bc,$2c
    call AddNTimes
    ld a,[hl]
    ld [wAlternateFormIndex],a
    call GetMonHeader
    ld hl,wWriteInGenericBufferBit4
    set 4,[hl] ; wWriteInGenericBufferBit4
    set 7,[hl] ; wNoExclusiveInListBit7
    ld a,[W_CURENEMYLVL] ; Level
    ld b,a               ; ...
    PREDEF GetMonPotentialMoveList
    push hl
    ld hl,wWriteInGenericBufferBit4
    res 4,[hl] ; wWriteInGenericBufferBit4
    res 7,[hl] ; wNoExclusiveInListBit7
    pop hl
    ret

