    BANKSWITCH PlayCurrentMoveAnimation
    ld hl,W_PLAYERBATTSTATUS3 ; $d064
    ld de,W_PLAYERMOVEEFFECT ; $cfd3
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.done
    ld hl,W_ENEMYBATTSTATUS3 ; $d069
    ld de,W_ENEMYMOVEEFFECT ; $cfcd
.done
    ld a,[de]
    cp LIGHT_SCREEN_EFFECT
    jr nz,.reflect
    bit 1,[hl] ; HAS_LIGHT_SCREEN_UP ; is mon already protected by light screen?
    jr nz,.moveFailed
    set 1,[hl] ; mon is now protected by light screen
    ld hl,LightScreenProtectedText ; $7bd7
    jr .PrintText
.reflect
    bit 2,[hl] ; HAS_REFLECT_UP ; is mon already protected by reflect?
    jr nz,.moveFailed
    set 2,[hl] ; mon is now protected by reflect
    ld hl,ReflectGainedArmorText ; $7bdc
.PrintText
    jp PrintText
.moveFailed
    ld c,50
    call DelayFrames
    ld hl,.AlreadyProtectedText
    jr .PrintText
.AlreadyProtectedText
    TX_FAR _AlreadyProtectedText
    db "@"

TryEvolvingMon:
    ld hl,$ccd3 ; wCanEvolveFlags
    xor a
    ld [hl],a
    ld a,[wWhichPokemon] ; $cf92
    ld c,a
    ld b,$1
    call HandleBitArray_BankE

EvolutionAfterBattle:
    ld a,[$FF00+$d7]
    push af
    xor a
    ld [$d121],a
    dec a
    ld [wWhichPokemon],a ; $cf92
    push hl
    push bc
    push de
    ld hl,W_NUMINPARTY ; $d163
    push hl

Evolution_PartyMonLoop:
    ld hl,wWhichPokemon ; $cf92
    inc [hl]
    pop hl
    inc hl
    ld a,[hl]
    cp $ff
    jp z,Func_3aede
    ld [$cee9],a
    push hl
    ld a,[wWhichPokemon] ; $cf92
    ld c,a
    ld hl,$ccd3 ; wCanEvolveFlags
    ld b,$2
    call HandleBitArray_BankE
    ld a,c
    and a
    jp z,Evolution_PartyMonLoop
    ld a,[$cee9]
    ld [$d0b5],a
    ld hl,W_PARTYMON1_MOVE2PP ; move2pp
    ld a,[wWhichPokemon] ; $cf92
    ld bc,$2c
    call AddNTimes
    ld a,[hl]
    ld [wAlternateFormIndex],a
    call GetMonHeader
    ld de,GenericBuffer+1
    PREDEF _GetEvos
    push hl
    ld a,[$cf91]
    push af
    xor a
    ld [$cc49],a
    call LoadMonData
    pop af
    ld [$cf91],a
    pop hl

TryEvolution: ; loop over evolution entries
    ld a,[hli]
    and a
    jr z,Evolution_PartyMonLoop
    ld b,a
    cp EV_TRADE
    jr z,.checkTradeEvo
    ld a,[W_ISLINKBATTLE] ; $d12b
    cp $32
    jr z,Evolution_PartyMonLoop
    ld a,b
    cp EV_ITEM
    jr z,.checkItemEvo
    ld a,[$ccd4]
    and a
    jr nz,Evolution_PartyMonLoop
    ld a,b
    cp EV_LEVEL
    jr z,.checkLevel
.checkTradeEvo
    ld a,[W_ISLINKBATTLE] ; $d12b
    cp $32
    jp nz,nextEvoEntry1
    ld a,[hli]
    ld b,a
    ld a,[$cfb9]
    cp b
    jp c,Evolution_PartyMonLoop
    jr .doEvolution
.checkItemEvo
    ld a,[hli]
    ld b,a
    call BugfixEvolutionStoneInBattle ; ds 3 ; ld a,[$cf91]
    nop ; ds 1 ; cp b
    jp nz,nextEvoEntry1 ; if in battle next
.checkLevel
    ld a,[hli]
    ld b,a
    ld a,[$cfb9]
    cp b
    jp c,nextEvoEntry2
.doEvolution
    ld [W_CURENEMYLVL],a ; $d127
    ld a,$1
    ld [$d121],a
    push hl
    ld a,[hl]
    ld [$ceea],a
    ld a,[wWhichPokemon] ; $cf92
    ld hl,W_PARTYMON1NAME ; $d2b5
    call GetPartyMonName
    call CopyStringToCF4B
    ld hl,UnnamedText_3af4d ; $6f4d
    call PrintText
    ld c,$32
    call DelayFrames
    xor a
    ld [H_AUTOBGTRANSFERENABLED],a ; $FF00+$ba
    ld hl,wTileMap
    ld bc,$c14
    call ClearScreenArea
    ld a,$1
    ld [H_AUTOBGTRANSFERENABLED],a ; $FF00+$ba
    ld a,$ff
    ld [$cfcb],a
    call CleanLCD_OAM
    ld a,[wWhichPokemon]
    ld c,a
    ld hl,$ccd3 ; wCanEvolveFlags
    ld b,$0
    call HandleBitArray_BankE
    ld hl,wTestEvoDuringBattleBit3
    res 3,[hl]
    ld hl,wFlagDisableSynchronizeBit0
    set 0,[hl]
    BANKSWITCH EvolveMon
    jp c,Func_3af2e
    ld hl,UnnamedText_3af3e ; $6f3e
    call PrintText
    pop hl
    ld a,[hl]
    ld [$d0b5],a
    ld [$cf98],a
    ld [$ceea],a
    ld a,MONSTER_NAME
    ld [W_LISTTYPE],a
    ld a,$e
    ld [$d0b7],a
    call GetName
    push hl
    ld hl,UnnamedText_3af43 ; $6f43
    call Func_3c59
    ld a,$89
    call PlaySoundWaitForCurrent
    call WaitForSoundToFinish
    call RenameEvolvedMon
    call DoEvolution_HandleAlternative ; call GetMonHeader
    ld hl,$cfa8
    ld de,$cfba
    ld b,$1
    call CalcStats
    ld a,[wWhichPokemon] ; $cf92
    ld hl,W_PARTYMON1_NUM ; $d16b (aliases: W_PARTYMON1DATA)
    ld bc,$2c
    call AddNTimes
    ld e,l
    ld d,h
    push hl
    push bc
    ld bc,$22
    add hl,bc
    ld a,[hli]
    ld b,a
    ld c,[hl]
    ld hl,$cfbb
    ld a,[hld]
    sub c
    ld c,a
    ld a,[hl]
    sbc b
    ld b,a
    ld hl,$cf9a
    ld a,[hl]
    add c
    ld [hld],a
    ld a,[hl]
    adc b
    ld [hl],a
    dec hl
    pop bc
    call CopyData
    ld a,[$d0b5]
    ld [$d11e],a
    xor a
    ld [$cc49],a
    call .PrintStatsBox
    call .AfterEvolution_TryToAddExclusiveMove
    ld hl,wFlagDisableSynchronizeBit0
    res 0,[hl]
    ld c,60
    call DelayFrames
    call .ShowPokedex
    call ClearScreen
    pop hl
    ld a,[W_ISINBATTLE] ; $d057
    and a
    call z,Func_3af52
    PREDEF IndexToPokedex
    ld a,[$d11e]
    ld c,a
    ld b,$1
    ld hl,wPokedexOwned ; $d2f7
    push bc
    call HandleBitArray_BankE
    pop bc
    ld hl,wPokedexSeen
    call HandleBitArray_BankE
    pop de
    pop hl
    ld a,[$cf98]
    ld [hl],a
    push hl
    ld l,e
    ld h,d
    jp Evolution_PartyMonLoop ; jr nextEvoEntry2

.AfterEvolution_TryToAddExclusiveMove
    ld a,[$d0b5]
    push af
    call AfterEvolution_TryToAddExclusiveMove
    pop af
    ld [$d0b5],a
    ret

.PrintStatsBox
    call SaveScreenTilesToBuffer1
    ld hl,W_ISINBATTLE
    ld a,[hl]
    push af
    push hl
    xor a
    ld [hl],a
    ld d,$01
    BANKSWITCH PrintStatsBox ; display new stats text box
    pop hl
    pop af
    ld [hl],a
    call WaitForTextScrollButtonPress
    jp LoadScreenTilesFromBuffer1

.ShowPokedex
