    ld a,[$d0b5]
    ld [$d11e],a
    push af
    PREDEF ShowPokedexData
    pop af
    ld [$d0b5],a
    ld [$d11e],a
    ret
.LoadPokedexText
    TX_FAR _ItemUseBallText06
    db $13,$06
    db "@"

nextEvoEntry1:
