; ────────────────────────────────────────────────────────────

SearchMoveToReplace:
    push de
    push hl
    push hl

    ; Shuffle Move
    push af
    call .ShuffleMoves
    pop af

    ; Check New Move
    push de
    call .GetMoveDamageAndType
    ld a,d
    ld [wNewMoveDamage],a
    ld a,e
    ld [wNewMoveType],a
    pop de
    ld b,%00111111 ; 1/64 = 1.5625% not learn
    ld hl,.LearnDamageNewMove
    jr nz,.done
    ld b,%00001111 ; 1/16 = 6.25% not learn
    ld hl,.LearnZeroDamageNewMove
.done
    call .DefinePriorityMoveToReplace
    jr nc,.fail

    ; Read Calculated Move Priority to Identify Worst
.resetloop
    ld hl,wMoveForgotPriority
    ld c,-1
.loop1
    inc c
    ld a,c
    cp 4
    jr z,.resetloop
    dec [hl]
    jr z,.endloop
    inc hl
    jr .loop1
.endloop

    ; Place Worst Move to first position
    pop hl
    ld d,h
    ld e,l
    ld b,0
    add hl,bc
    call .SwapMoves

.end1
    pop hl
    pop de
    call ShiftMoveData ; shift all moves one up (deleting move 1)
    scf
    ret
.fail
    pop hl
    pop hl
    pop de
    xor a ; rcf
    ret

.DefinePriorityMoveToReplace
    call GenRandom
    and b
    ret z ; rcf
    ld bc,$00FF ; b = 0 | c = -1
.loop2
    inc c
    push hl
    push bc
    ld a,c
    cp 4
    jr z,.end2
    ld a,[de]
    ld b,20 ; Start Value
    push de
    ld de,.return
    push de
    call .GetMoveDamageAndType
    call .LearnDamageAndZeroDamageMoveCommon
    jp hl
.return
    pop de
    ld a,b
    ld hl,wMoveForgotPriority
    pop bc
    add hl,bc
    ld [hl],a
    pop hl
    inc de
    jr .loop2
.end2
    pop bc
    pop hl
    scf
    ret

.LearnZeroDamageNewMove
    jr z,.Zero1
    jr c,.One1
    call .HandleOldStabMove
    inc b ; ▼ old not zero damage
.Zero1
    dec b ; ▲ old zero damage
    dec b ; ...
.One1
    dec b ; ▲ old special (1 damage)
    ret

.LearnDamageNewMove
    jr z,.Zero2
    jr c,.One2
    call .HandleOldStabMove
    ld a,[wNewMoveType]
    cp e
    jr nz,.DifferentType
    dec b ; ▲ same type
    ld a,[wNewMoveDamage]
    cp d
    jr c,.DifferentType ; c = damage old > damage new
    call .EncourageForgot3 ; ▲ same type and new damage >= old damage
.DifferentType
    ld a,[wNewMoveDamage]
    cp d
    jr nc,.NewMoreDamageThanOld ; c = damage old > damage new
    ; old > new
    ld e,a ; a = delta
    ld a,d ; ...
    sub e  ; ...
.LoopDeltaDamage1
    inc b ; ▼ damage old > damage new
    sub 20
    jr nc,.LoopDeltaDamage1
    ret
.NewMoreDamageThanOld
    ; new >= old
    sub d ; a = delta
.LoopDeltaDamage2
    dec b ; ▲ damage new >= old
    sub 20
    jr nc,.LoopDeltaDamage2
    ret
.Zero2
    inc b ; ▼ old zero damage
    ret
.One2
    dec b ; ▲ old special (1 damage)
    ret

.LearnDamageAndZeroDamageMoveCommon
    push af
    push de
    push hl
    ld hl,W_ISINBATTLE
    ld d,[hl]
    dec d
    jr nz,.notWildBattle
    ld hl,.EscapeMoves
    call .CheckList
    jr nc,.notWildBattle
    call .DiscourageForgot6 ; ▼ Escape
.notWildBattle
    ld hl,.DreamEaterMoves
    call .CheckList
    jr nc,.notDreamEater
    call .DiscourageForgot6 ; ▼ DreamEater
.notDreamEater
    ld hl,.NotForgottableMoves
    call .CheckList
    jr nc,.notForgottable
    call .DiscourageForgot3 ; ▼ Unforgottable
.notForgottable
    pop hl
    pop de
    pop af
    ret

.HandleOldStabMove
    push hl
    ld hl,W_MONHTYPES
    ld a,[hli]
    cp e
    jr z,.StabFound
    ld a,[hli]
    cp e
    jr z,.StabFound
    ld a,[hli]
    cp e
    jr z,.StabFound
    ld a,[hl]
    cp e
    jr nz,.StabDone
.StabFound
    inc b ; ▼ stab
.StabDone
    pop hl
    ret

.ShuffleMoves
    push de
    push hl
    call .Shuffle
    pop hl
    pop de
    ret
.Shuffle
    ld h,d
    ld l,e
    ld b,0
    push hl
.loop3
    inc b
    ld a,b
    cp 30 ; swap slot n times
    pop hl
    ret z
    call GenRandom
    and %00000011 ; from 0 to 3
    ld e,a
    ld d,0
    push hl
    add hl,de
    ld a,[hl]
    and a
    jr z,.loop3
    pop de
    push de
    call .SwapMoves
    jr .loop3

.SwapMoves
    push bc
    ld a,[hl]
    ld c,a
    ld a,[de]
    ld [hl],a
    ld a,c
    ld [de],a
    pop bc
    ret

; INPUT
; a = Move ID
; OUTPUT
; d = damage
; e = type
; set z reset c if damage = 0
; set c reset z if damage = 1
; reset z reset c if damage > 1
.GetMoveDamageAndType
    push hl
    push bc
    push af
    dec a
    ld hl,Moves+2 ; damage
    ld bc,6
    call AddNTimes
    ld a,[hli] ; damage
    ld d,a
    and a ; rcf
    jr z,.GetType ; szf
    dec a
    jr nz,.GetType
    inc a ; rzf
    scf ; scf
.GetType
    ld a,[hl] ; type
    ld e,a
    pop bc
    ld a,b
    pop bc
    pop hl
    ret

.DiscourageForgot6
    call .DiscourageForgot3
.DiscourageForgot3
    inc b
    inc b
    inc b
    ret

.EncourageForgot6
    call .EncourageForgot3
.EncourageForgot3
    dec b
    dec b
    dec b
    ret

.CheckList
    push bc
    push af
    push de
    ld de,1
    call IsInArray
    pop de
    pop bc
    ld a,b
    pop bc
    ret

.EscapeMoves
    db ROAR
    db TELEPORT
    db WHIRLWIND
    db $FF

.DreamEaterMoves
    db SING
    db SLEEP_POWDER
    db HYPNOSIS
    db LOVELY_KISS
    db SPORE
    db DREAM_EATER
    db $FF

.NotForgottableMoves
    db SWORDS_DANCE
    db BODY_SLAM
    db TWINEEDLE
    db FLAMETHROWER
    db TSUNAMI
    db ICE_BEAM
    db DRILL_PECK
    db SUBMISSION
    db LOW_KICK
    db RAZOR_LEAF
    db THUNDERBOLT
    db THUNDER_WAVE
    db EARTHQUAKE
    db PSYCHIC_M
    db NIGHT_SHADE
    db RECOVER
    db SLUDGE
    db BONE_CLUB
    db AMNESIA
    db SOFTBOILED
    db FLARE
    db TRANSFORM
    db HAMMER
    db EXPLOSION
    db BONEMERANG
    db REST
    db ROCK_SLIDE
    db HYPER_FANG
    db SUPER_FANG
    db SLASH
    db SUBSTITUTE
    db $FF

; ────────────────────────────────────────────────────────────

; writes the moves a mon has at level [W_CURENEMYLVL] to [de]
; move slots are being filled up sequentially and shifted if all slots are full
; [wLearningMovesFromDayCare]: Day Care
WriteMonMoves:
    call Load16BitRegisters
    push hl
    push de
    push bc
    push de
    ld hl,wWriteInGenericBufferBit4
    set 4,[hl] ; wWriteInGenericBufferBit4
    set 6,[hl] ; wNoSkillInListBit6
    set 7,[hl] ; wNoExclusiveInListBit7
    ld a,[wLearningMovesFromDayCare]
    and a
    jr z,.skip
    res 7,[hl] ; wNoExclusiveInListBit7
.skip
    ld a,[W_CURENEMYLVL] ; Level
    ld b,a               ; ...
    PREDEF GetMonPotentialMoveList
    push hl
    ld hl,wWriteInGenericBufferBit4
    res 4,[hl] ; wWriteInGenericBufferBit4
    res 6,[hl] ; wNoSkillInListBit6
    res 7,[hl] ; wNoExclusiveInListBit7
    pop hl
    dec hl ; because "inc" in next instructions
.nextMove
    pop de
.nextMove2
    inc hl
    ld a,[hl]        ; read next move in learnset
    and a
    jp z,.done       ; end of list
    push de
    ld c,4
.moveAlreadyLearnedCheckLoop
    ld a,[de]
    inc de
    cp [hl]
    jr z,.nextMove
    dec c
    jr nz,.moveAlreadyLearnedCheckLoop
    pop de
    push de
    ld c,4
.findEmptySlotLoop
    ld a,[de]
    and a
    jr z,.writeMoveToSlot
    inc de
    dec c
    jr nz,.findEmptySlotLoop
    pop de                        ; no empty move slots found
    push de
    push hl
    ld a,[hl] ; read new move
    ld h,d
    ld l,e
    call SearchMoveToReplace
    pop hl
    jr nc,.nextMove
.writeMoveToSlot
    ld a,[hl]
    ld [de],a
    jr .nextMove
.done
    pop bc
    pop de
    pop hl
    ret

HealEffect_:
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    ld de,W_PLAYERMONCURHP+1 ; $d015
    ld hl,W_PLAYERMONMAXHP+1 ; $d023
    ld a,[W_PLAYERMOVENUM] ; $cfd2
    jr z,.done
    ld de,W_ENEMYMONCURHP+1 ; $cfe6
    ld hl,W_ENEMYMONMAXHP+1 ; $cff4
    ld a,[W_ENEMYMOVENUM] ; $cfcc
.done
    cp REST
    jr nz,.healHP

.healStatusAndSleep
    push hl
    push de
    push af
    ld c,50
    call DelayFrames
    ld hl,W_PLAYERMONSTATUS ; $d018
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.restEffect
    ld hl,W_ENEMYMONSTATUS ; $cfe9
.restEffect
    push hl
;undo the stat-changing effects of burn and paralyze and clear toxic info
    ld d,%0000101 ; bit 0 = attack | bit 2 = speed
    PREDEF UndoBurnParStats
    ld hl,W_PLAYERBATTSTATUS3     ; load in for toxic bit
    ld de,W_PLAYERTOXICCOUNTER    ; load in for toxic counter
    ld a,[H_WHOSETURN]
    and a
    jr z,.undoToxic
    ld hl,W_ENEMYBATTSTATUS3      ; load in for toxic bit
    ld de,W_ENEMYTOXICCOUNTER     ; load in for toxic counter
.undoToxic
    res BADLY_POISONED,[hl]       ; heal Toxic status
    dec hl
    dec hl                        ; hl now point to "Status1"
    res CONFUSED,[hl]             ; heal Confused status
    xor a                         ; clear a
    ld [de],a                     ; write a to toxic counter
    pop hl
    ld a,[hl]
    and a
    ld [hl],3 ; clear status and set number of turns asleep to 3
    ld hl,StartedSleepingEffect
    jr z,.printRestText
    ld hl,FellAsleepBecameHealthyText ; if mon had an status
.printRestText
    call DrawHudAndPrintTextBankE
    pop af
    pop de
    pop hl
    ; ft

.healHP
    ld a,[hld]
    ld [wHPBarMaxHP],a
    ld c,a
    ld a,[hl]
    ld [wHPBarMaxHP+1],a
    ld b,a
    jr z,.gotHPAmountToHeal
; Recover and Softboiled only heal for half the mon's max HP
    srl b
    rr c
.gotHPAmountToHeal
; update HP
    ; ────────────
    push hl
    push de
    push bc
    ld d,b
    ld e,c
    BANKSWITCH SetCureDirect
    pop bc
    pop de
    pop hl
    ; ────────────
    ld a,[de]
    ld [wHPBarOldHP],a
    add c
    ld [de],a
    ld [wHPBarNewHP],a
    dec de
    ld a,[de]
    ld [wHPBarOldHP+1],a
    adc b
    ld [de],a
    ld [wHPBarNewHP+1],a
    inc hl
    inc de
    ld a,[de]
    dec de
    sub [hl]
    dec hl
    ld a,[de]
    sbc [hl]
    jr c,.playAnim
    ld a,[hli]
    ld [de],a
    ld [wHPBarNewHP+1],a
    inc de
    ld a,[hl]
    ld [de],a
    ld [wHPBarNewHP],a
.playAnim
    BANKSWITCH PlayCurrentMoveAnimation
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    FuncCoord 10,09 ; Player Bar in Battle
    ld hl,Coord
    ld a,$1
    jr z,.updateHPBar
    FuncCoord 02,02 ; Enemy Bar in Battle
    ld hl,Coord
    xor a
.updateHPBar
    ld [wListMenuID],a ; $cf94
    PREDEF UpdateHPBar ; UpdateHPBar
    ld hl,RegainedHealthText ; $7aac
    jp DrawHudAndPrintTextBankE

TransformEffect_:
    call .HideSubstitute
    ld hl,W_PLAYERMONID
    ld de,W_ENEMYMON_START
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    ld a,[W_PLAYERBATTSTATUS1]
    jr nz,.done
    push hl
    ld h,d
    ld l,e
    pop de
    ld a,[W_ENEMYBATTSTATUS1]
.done
    bit 6,a ; invulnerable
    jp nz,.attackMissed
    push hl
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr nz,.skipResetLastMove
    ld a,0                        ; If Success during player
    ld [wPlayerMoveListIndex],a   ; turn reset move last choice
.skipResetLastMove
    jr z,.SkipBackupMoves
    ld a,[W_ENEMYBATTSTATUS3]
    bit 3,a ; Pokemon is Just Transformed
    jr nz,.SkipBackupMoves
    ; Backup Moves & PP
    push hl
    push de
    ld hl,W_ENEMYMONMOVES
    ld de,wBackupEnemyMoves
    ld bc,4
    call CopyData
    ld hl,W_ENEMYMONENERGY ; W_ENEMYMONALTFORM
    ld de,wBackupEnemyEnergy ; wBackupEnemyAltForm
    ld bc,2
    call CopyData
    pop de
    pop hl
.SkipBackupMoves
    ld a,[hl]
    ld [de],a
    ld bc,$6
    add hl,bc
    inc de
    inc de
    inc de
    inc de
    inc de
    inc de
    ; Handle Alternate Form Index
    ld a,[hli]
    ld [de],a
    inc de
    dec bc
    call CopyData
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    push af
    ld bc,W_PLAYERBATTSTATUS3
    jr z,.SkipBackupDV
    ld bc,W_ENEMYBATTSTATUS3
    ld a,[bc]
    bit 3,a ; Pokemon is Just Transformed
    jr nz,.SkipBackupDV
    push de
    ; Backup IV
    ld a,[de]
    ld [$cceb],a
    inc de
    ld a,[de]
    ld [$ccec],a
    pop de
.SkipBackupDV
    ld a,[bc]
    set 3,a ; Set Transformed
    ld [bc],a
; ───────────────────────── Conflict with Disable Start
    pop af ;get the saved turn result
    jr nz, .undo_enemy_disable
.undo_player_disable
    xor a
    ld [W_PLAYERDISABLEDMOVE], a
    ld [$ccee], a
    jr .undo_disable_end
.undo_enemy_disable
    xor a
    ld [W_ENEMYDISABLEDMOVE], a
    ld [$ccef], a
.undo_disable_end
; ───────────────────────── Conflict with Disable End
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[hli]
    ld [de],a
    inc de
    inc hl
    inc hl
    inc hl
    inc de
    inc de
    inc de

    ; Copy Original 4 Stats
    ld bc,8
    add hl,bc
    push hl
    ld a,[H_WHOSETURN]
    and a
    ld hl,$cd26 ; EnemyMonUnmodifiedAttack
    jr z,.ContinueCopy4Stats
    ld hl,$cd12 ; PlayerMonUnmodifiedAttack
.ContinueCopy4Stats
    call CopyData
    pop hl

    ; Copy Types
    ld bc,4
    call CopyData

    pop hl
    ld a,[hl]
    ld [$d11e],a
    call GetMonName
    ld hl,$cd26 ; EnemyMonUnmodifiedAttack
    ld de,$cd12 ; PlayerMonUnmodifiedAttack
    call Func_3bb7d
    ld hl,wEnemyMonStatMods ; $cd2e
    ld de,wPlayerMonStatMods ; $cd1a
    call Func_3bb7d

    ; Calculate New Stats & Apply Boost/Penaties
    ld a,[$d11e]
    push af
    ld a,[H_WHOSETURN]
    ld [$d11e],a
    BANKSWITCH CalculateModifiedStats
    pop af
    ld [$d11e],a
    ld a,[H_WHOSETURN]
    and a
    BANKSWITCH_Z ApplyBadgeStatBoostsFull
    ld a,[H_WHOSETURN]
    push af
    and a
    ld hl,ApplyBurnAndParalysisPenaltiesToPlayer
    jr z,.ApplyBurnAndParalysisPenalties
    ld hl,ApplyBurnAndParalysisPenaltiesToEnemy
.ApplyBurnAndParalysisPenalties
    ld b,BANK(ApplyBurnAndParalysisPenaltiesToPlayer) ; ApplyBurnAndParalysisPenaltiesToEnemy
    call Bankswitch
    pop af
    ld [H_WHOSETURN],a

    call .TransformAnimation
    call Delay3
    call .RestoreSubstitute
    ld hl,UnnamedText_3bb92 ; $7b92
    jp DrawHudAndPrintTextBankE
.attackMissed
    ld a,1
    ld [W_MOVEMISSED],a
    call .TransformAnimation
    call .RestoreSubstitute
    BANKSWITCH_JUMP PrintMoveFailureText
.HideSubstitute
    push hl
    push de
    call .GetSubstituteFlag
    BANKSWITCH_NZ HideSubstituteShowMonAnim
    pop de
    pop hl
    ret
.RestoreSubstitute
    push hl
    push de
    call .GetSubstituteFlag
    BANKSWITCH_NZ ReshowSubstituteAnim
    pop de
    pop hl
    ret
.GetSubstituteFlag
    ld hl,W_PLAYERBATTSTATUS2 ; $d063
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.getsubstflg
    ld hl,W_ENEMYBATTSTATUS2 ; $d068
.getsubstflg
    bit 4,[hl]
    ret
.TransformAnimation
    ; (1) Battle Animation ON - Success
    ; (2) Battle Animation ON - Fail
    ; (3) Battle Animation OFF - Success
    ; (4) Battle Animation OFF - Fail
    push hl
    push de
    ld a,[W_OPTIONS] ; $d355
    add a
    ld hl,PlayCurrentMoveAnimation ; (1)
    ld b,BANK(PlayCurrentMoveAnimation)
    jr nc,.done2
    ld hl,AnimationTransformMon ; (3)
    ld b,BANK(AnimationTransformMon)
.done2
    ld a,[W_MOVEMISSED]
    and a
    push af
    call z,Bankswitch
    pop af
    call nz,.MissedAnimation
    pop de
    pop hl
    ret
.MissedAnimation
    ld a,[W_OPTIONS] ; $d355
    add a
    ret c ; (4)
    xor a
    ld [$cc5b],a
    ld d,$CC ; TransformFailAnim
    BANKSWITCH_JUMP PlayBattleAnimationFromAnotherBank ; (2)

