    ld a,[hli]
    or [hl]
    jr nz,.asm_3c13c
    add hl,bc
    jr .asm_3c134
.asm_3c13c
    ld a,d
    ld [$cc3e],a
    ld a,[W_ISINBATTLE] ; $d057
