MainInBattleLoop: ; 3c233 (f:4233)
    call ResetLeechSeedFlagAndReadPlayerMonCurHPAndStatus ; call ReadPlayerMonCurHPAndStatus
    ld hl,W_PLAYERMONCURHP
    ld a,[hli]
    or [hl]
    jp z,HandlePlayerMonFainted  ; test if current player mon is fainted
    ld hl,$cfe6
    ld a,[hli]
    or [hl]
    jp z,HandleEnemyMonFainted
    call SaveScreenTilesToBuffer1
    xor a
    ld [$d11d],a
    call SelectEnemyMove
    BANKSWITCH HandlePlayerRageAndThrashing
    ld a,[W_PLAYERBATTSTATUS2]
    and %01100000 ; check if the player is using Rage or needs to recharge
    jr nz,.selectEnemyMove
    ld hl,W_ENEMYBATTSTATUS1
    res 3,[hl] ; reset flinch bit
    ld hl,W_PLAYERBATTSTATUS1
    res 3,[hl] ; reset flinch bit
    ld a,[hl]
    and %00010010 ; check if the player is thrashing about or charging for an attack
    jr nz,.selectEnemyMove

.InitBattleMenu
    call InitBattleMenu ; show battle menu
    ret c ; return if player ran from battle
    ld a,[$d078]
    and a
    ret nz ; return if pokedoll was used to escape from battle

;joenote - This whole thing is problematic. Just comment it all out.
;        -allow the player to select a move even if frozen in order to prevent PP underflow and link desyncs
;        -also allow the player to select a move if you don't want sleep to waste a turn on wakeup
;    ld a,[W_PLAYERMONSTATUS]        ; joedebug - sleep won't waste turn
;    and $27                         ; ...
;    jr nz,.selectEnemyMove
    ld a,[W_PLAYERBATTSTATUS1]
    and %00100001 ; bide OR using multi-turn move (e.g. wrap) ; check player is using Bide or using a multi-turn attack like wrap
    jr nz,.selectEnemyMove
    ld a,[W_ENEMYBATTSTATUS1]
    bit 5,a ; using multi-turn move (e.g. wrap)
    jr z,.selectPlayerMove
    ld a,$ff
    ld [wPlayerSelectedMove],a
    jr .selectEnemyMove

.selectPlayerMove
    ld a,[$cd6a] ; ActionResultOrTookBattleTurn
    and a ; has the player already used the turn (e.g. by using an item, trying to run or switching pokemon)
    jr nz,.selectEnemyMove
    ld [wMoveMenuType],a
    inc a
    ld [W_ANIMATIONID],a
    xor a
    ld [$cc35],a
    call MoveSelectionMenu
    push af
    call LoadScreenTilesFromBuffer1
;    call DrawHUDsAndHPBars ; Useless and Slow in Super Game Boy Mode
    pop af
    jr nz,.InitBattleMenu

.selectEnemyMove
    ld a,[W_ISLINKBATTLE]
    cp $4
    jr nz,.noLinkBattle
; link battle
    ld a,[$cc3e] ; SerialExchangeNybbleReceiveData
    cp $f ; LINKBATTLE_RUN
    jp z,EnemyRan
    cp $e ; LINKBATTLE_STRUGGLE
    jr z,.noLinkBattle
    cp $d ; LINKBATTLE_NO_ACTION
    jr z,.noLinkBattle
    sub $4
    jr c,.noLinkBattle
; the link battle enemy has switched mons
    ld a,[W_PLAYERBATTSTATUS1]
    bit 5,a ; check if using multi-turn move like Wrap
    jr z,.specialMoveNotUsed
    ld a,[$cc2e]
    ld hl,W_PLAYERMONMOVES
    ld c,a
    ld b,$0
    add hl,bc
    ld a,[hl]
    cp $76
    jr nz,.specialMoveNotUsed
    ld [wPlayerSelectedMove],a
.specialMoveNotUsed
    BANKSWITCH SwitchEnemyMon

.noLinkBattle
    ld a,[wPlayerSelectedMove]
    cp QUICK_ATTACK
    jr nz,.playerDidNotUseQuickAttack
    ld a,[wEnemySelectedMove]
    cp QUICK_ATTACK
    jr z,.compareSpeed  ; both used Quick Attack
    jp .playerMovesFirst ; player used Quick Attack
.playerDidNotUseQuickAttack
    ld a,[wEnemySelectedMove]
    cp QUICK_ATTACK
    jr z,.enemyMovesFirst
    ld a,[wPlayerSelectedMove]
    cp COUNTER
    jr nz,.playerDidNotUseCounter
    ld a,[wEnemySelectedMove]
    cp COUNTER
    jr z,.compareSpeed ; both used Counter
    jr .enemyMovesFirst ; player used Counter
.playerDidNotUseCounter
    ld a,[wEnemySelectedMove]
    cp COUNTER
    jr z,.playerMovesFirst
.compareSpeed
    ld de,W_PLAYERMONSPEED ; player speed value
    ld hl,W_ENEMYMONSPEED ; enemy speed value
    ld c,$2
    call StringCmp ; compare speed values
    jr z,.speedEqual
    jr nc,.playerMovesFirst
    jr .enemyMovesFirst
.speedEqual
    ld a,[$ff00+$aa]
    cp $2
    jr z,.invertOutcome
    call GenRandomInBattle
    cp $80
    jr c,.playerMovesFirst
    jr .enemyMovesFirst
.invertOutcome
    call GenRandomInBattle
    cp $80
    jr c,.enemyMovesFirst
    jr .playerMovesFirst

.enemyMovesFirst
    ld a,$1
    ld [H_WHOSETURN],a
    BANKSWITCH TrainerAI
    jr c,.AIActionUsedEnemyFirst
    call ExecuteEnemyMove ; execute enemy move
    ld a,[$d078]
    and a ; was Teleport, Road, or Whirlwind used to escape from battle?
    ret nz
    ld a,b
    and a
    jr z,.HandlePlayerMonFainted
.AIActionUsedEnemyFirst
    call HandlePoisonBurnLeechSeed
    jr z,.HandleEnemyMonFainted
    call ExecutePlayerMove ; execute player move
    ld a,[$d078] ; was Teleport, Road, or Whirlwind used to escape from battle?
    and a
    ret nz
    ld a,b
    and a
    jr z,.HandleEnemyMonFainted
    call HandlePoisonBurnLeechSeed
    jr z,.HandlePlayerMonFainted
    jr .end

.playerMovesFirst
;#1 - handle enemy switching or using an item
    call HandleEnemySwitchingOrUsingAnItemAndThenExecutePlayerMove ; call ExecutePlayerMove ; execute player move ;note: this function writes zero to H_WHOSETURN
;#2 - handle player using a move
    ld a,[$d078]
    and a ; was Teleport, Road, or Whirlwind used to escape from battle?
    ret nz
    ld a,b
    and a
    push af
    call z,CheckandResetEnemyActedBit ;reset enemy acted bit if enemy pkmn fainted
    pop af
    jr z,.HandleEnemyMonFainted
    call HandlePoisonBurnLeechSeed
    jr z,.HandlePlayerMonFainted
;#3 - handle enemy using move
    ld a,$1
    ld [H_WHOSETURN],a
    ;BANKSWITCH TrainerAI
    call CheckandResetEnemyActedBit ;check to see if ai trainer already acted this turn
    jr nz,.AIActionUsedPlayerFirst
    ;else execute the enemy move
    call ExecuteEnemyMove ; execute enemy move
    ld a,[$d078]
    and a ; was Teleport, Road, or Whirlwind used to escape from battle?
    ret nz
    ld a,b
    and a
    jr z,.HandlePlayerMonFainted
.AIActionUsedPlayerFirst
    call HandlePoisonBurnLeechSeed
    jr z,.HandleEnemyMonFainted

.end
    call DrawHUDsAndHPBars
    call CheckNumAttacksLeft
    jp MainInBattleLoop

.HandleEnemyMonFainted
    jp HandleEnemyMonFainted
.HandlePlayerMonFainted
    jp HandlePlayerMonFainted

HandlePoisonBurnLeechSeed:
    call DrawHUDsAndHPBars
HandlePoisonBurnLeechSeed2:
    BANKSWITCH_JUMP HandlePoisonBurnLeechSeed_

MoveEffectToPercentage:
    cp 7    ; 10% status effects are 04,05,06 so 07 will set carry for those
    ld b,$1a  ; [1A-1]/100 or [26-1]/256 = 9.8%~ chance
    ret c     ; branch ahead if this is a 10% chance effect..
    ld b,$4d  ; ..or use [4D-1]/100 or [76-1]/256 = 29.7%~ chance
    sub a,$1e ; subtract $1E to map to equivalent 10% chance effects
    ret

CheckDefrost:
    bit FRZ_Bit,a                  ;are they frozen?
    ret z                          ;return if so
;not frozen
    ld a,[H_WHOSETURN]             ;whose turn?
    and a
    jr nz,.opponent
;player [attacker]
    ld a,[W_PLAYERMOVETYPE]
    cp FIRE
    ret nz                         ;return if it isn't fire
    ld hl,W_ENEMYMONSTATUS
    res FRZ_Bit,[hl]               ;"defrost" a frozen monster
    ld hl,$d8a8                    ;status of first opponent monster in their roster
    ld a,[W_ENEMYMONNUMBER]
    ld bc,$002c                    ;$2C bytes per roster entry
    call AddNTimes
    res FRZ_Bit,[hl]               ;"defrost" in roster
    jr .common
.opponent
    ld a,[W_ENEMYMOVETYPE]         ;same as above with addresses swapped
    cp FIRE
    ret nz
    ld hl,W_PLAYERMONSTATUS
    res FRZ_Bit,[hl]
    ld hl,W_PARTYMON1_STATUS
    ld a,[wPlayerMonNumber]
    ld bc,$002c
    call AddNTimes
    res FRZ_Bit,[hl]
.common
    ld hl,.UnnamedText_3f423
    jp DrawHudAndPrintText
.UnnamedText_3f423
    TX_FAR _UnnamedText_3f423
    db "@"

