GetPlayerOrEnemyTurnWithSubstitute:
    ld de,wEnemySubstituteHP
    ld bc,W_ENEMYBATTSTATUS2
    ld a,[wFlagValueToPlayerBit1]
    bit 1,a
    jr z,.DamageToEnemy
    ld de,wPlayerSubstituteHP
    ld bc,W_PLAYERBATTSTATUS2
;DamageToPlayer
    call .CheckTurn
    ret nz
    jr FlipTurn
.DamageToEnemy
    call .CheckTurn
    ret z
    jr FlipTurn
.CheckTurn
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
