UpdateCurMonHPBar:
    FuncCoord 10,09 ; Player Bar in Battle
    ld hl,Coord    ; tile pointer to player HP bar
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    ld a,$1
    jr z,.playersTurn
    FuncCoord 02,02 ; Enemy Bar in Battle
    ld hl,Coord    ; tile pointer to enemy HP bar
    xor a
.playersTurn
    push bc
    ld [wListMenuID],a ; $cf94
    PREDEF UpdateHPBar ; UpdateHPBar
    pop bc
    ret

CheckNumAttacksLeft:
    ld a,[$d06a]
    and a
    jr nz,.asm_3c51a
    ld hl,W_PLAYERBATTSTATUS1 ; $d062
    res 5,[hl]
.asm_3c51a
    ld a,[$d06f]
    and a
    ret nz
    ld hl,W_ENEMYBATTSTATUS1 ; $d067
    res 5,[hl]
    ret

HandlePlayerAliveAndApplyPoisonBurn:
.AnyPokemonAliveCheck
    call AnyPokemonAliveCheck ; test if any more mons are alive
    ld a,d
    and a
    jr z,.HandlePlayerBlackOut
    ld hl,W_PLAYERMONCURHP
    ld a,[hli]
    or [hl]
    jr z,.SkipPlayer
    call DrawPlayerHUDAndHPBar
    call HandlePoisonBurnAfterEnemyMonFainted
    jr nz,.SkipPlayer
    call RemoveFaintedPlayerMon2
    jr .AnyPokemonAliveCheck
.SkipPlayer
    call ReadPlayerMonCurHPAndStatus
    ld a,1 ; rzf
    and a  ; ...
    ret
.HandlePlayerBlackOut
    call HandlePlayerBlackOut
    xor a ; szf
    ret

HandleEnemyMonFainted:
    xor a
    ld [$ccf0],a
    call FaintEnemyPokemon
    call HandlePlayerAliveAndApplyPoisonBurn
    ret z
    ld a,[W_ISINBATTLE]
    dec a
    ret z ; if wild encounter, battle is over
    call AnyEnemyPokemonAliveCheck
    jp z,TrainerBattleVictory
    call PrintEmptyString
    call SaveScreenTilesToBuffer1
    ld hl,W_PLAYERMONCURHP
    ld a,[hli]
    or [hl]
    jr nz,.skipReplacingBattleMon
    call ChooseNextMon
.skipReplacingBattleMon
    jp ReplaceFaintedEnemyMon_

FaintEnemyPokemon:
    call ReadPlayerMonCurHPAndStatus
    ld a,[W_ISINBATTLE] ; $d057
    dec a
    jr z,.wild
    ld a,[W_ENEMYMONNUMBER] ; $cfe8
    ld hl,W_ENEMYMON1HP
    ld bc,$2c ; mon struct len
    call AddNTimes
    xor a
    ld [hli],a
    ld [hl],a
.wild
    ld hl,W_PLAYERBATTSTATUS1 ; $d062
    res 2,[hl]
; Bug. This only zeroes the high byte of the player's accumulated damage,
; setting the accumulated damage to itself mod 256 instead of 0 as was probably
; intended. That alone is problematic, but this mistake has another more severe
; effect. This function's counterpart for when the player mon faints,
; RemoveFaintedPlayerMon, zeroes both the high byte and the low byte. In a link
; battle, the other player's Game Boy will call that function in response to
; the enemy mon (the player mon from the other side's perspective) fainting,
; and the states of the two Game Boys will go out of sync unless the damage
; was congruent to 0 modulo 256.
    xor a
    call ResetPlayerBideAccumulatedDamage ; ld [W_NUMHITS],a ; $d074
    ld hl,$d065 ; enemy statuses
    ld [hli],a
    ld [hli],a
    ld [hli],a
    ld [hli],a
    ld [hl],a
    ld [W_ENEMYDISABLEDMOVE],a ; $d072
    ld [$ccef],a
    ld [$ccf3],a
    ld hl,$ccf1
    ld [hli],a
    ld [hl],a
    FuncCoord 12,5 ; $c410
    ld hl,Coord
    FuncCoord 12,6 ; $c424
    ld de,Coord
    call Func_3c893
    ld hl,wTileMap
    ld bc,$40b
    call ClearScreenArea
    call AnyPokemonAliveCheck ; move the check for alive party members up here
    ld a,d
    and a
    push af ; save the results and flags of the check on the stack
    ld a,[W_ISINBATTLE] ; $d057
    dec a
    jr z,.wild_win
    xor a
    ld [$c0f1],a
    ld [$c0f2],a
    ld a,$9e ; SFX_FALL?
    call PlaySoundWaitForCurrent
.sfxwait
    ld a,[$c02a]
    cp $9e
    jr z,.sfxwait
    ld a,$95 ; SFX_DROP
    call PlaySound
    call WaitForSoundToFinish
    jr .sfxplayed
.wild_win
    call Func_3c643
    pop af  ; get the saved party check off of the stack
    push af ; save the results and flags of the check on the stack
    ld a,(Music_DefeatedWildMon - $4000) / 3
    call nz,Func_3c6ee ; only play the victory music if at least 1 pokemon remains alive
.sfxplayed
    ld hl,EnemyMonFainted ; $463e
    call PrintText
    ld hl,W_PLAYERMONCURHP ; $d015
    ld a,[hli]
    or [hl]
    jr nz,.playermonnotfaint
    ld a,[$ccf0]
    and a
    jr nz,.playermonnotfaint
    call RemoveFaintedPlayerMon2
.playermonnotfaint
    ;call AnyPokemonAliveCheck ; moving this upwards
    ;ld a,d
    ;and a
    pop af ; get the saved party check off of the stack
    ret z
    call PrintEmptyString
    call SaveScreenTilesToBuffer1
    xor a
    ld [wBattleResult],a

