ReplaceFaintedEnemyMon: ; 3c664 (f:4664)
    ld hl,$cf1e
    ld e,$30
    call GetBattleHealthBarColor
    BANKSWITCH DrawEnemyPokeballs
    ld a,[W_ISLINKBATTLE] ; $d12b
    cp $4
    jr nz,.asm_3c687
    call Func_3d605
    ld a,[$cc3e]
    cp $f
    ret z
    call LoadScreenTilesFromBuffer1
.asm_3c687
    call EnemySendOutAfterDelay
    xor a
    ld [W_ENEMYMOVENUM],a ; $cfcc
    ld [$cd6a],a
