    ld a,[$d083]
    bit 7,a      ; skip sound flag (red bar (?))
    jr z,.skipWaitForSound
    ld a,$ff
    ld [$d083],a
    call WaitForSoundToFinish
.skipWaitForSound
    ld hl,$cd05
    ld [hli],a
    ld [hl],a
    call SetExplodeFlagBecauseStatusAfterFainted ; ld [W_PLAYERMONSTATUS],a ; $d018
    call ReadPlayerMonCurHPAndStatus
    FuncCoord 9,7 ; $c435
    ld hl,Coord
