    call ClearScreenArea
    FuncCoord 1,10 ; $c469
    ld hl,Coord
    FuncCoord 1,11 ; $c47d
    ld de,Coord
    call Func_3c893
    ld a,$1
    ld [wBattleResult],a
    ld a,[$ccf0]
    and a
    ret z
    ld a,[W_PLAYERMONID]
    call PlayCry
    ld hl,.PlayerMonFaintedText
    jp PrintText
.PlayerMonFaintedText
    TX_FAR _PlayerMonFaintedText
    db "@"

PlayMoveAnimation_WithException:
    cp WHIRLWIND
    jr nz,.notWhirlWind
    ld a,$CE ; WhirlwindAnimTrainerBattle
    jr .done
.notWhirlWind
    cp SEISMIC_TOSS
    jr nz,.done
    push bc
    ld b,a
    ld a,[W_MOVEMISSED]
    and a
    ld a,b
    pop bc
    jr z,.done
    ld a,TACKLE
.done
    jp PlayMoveAnimation

