    srl b
    rr a
    and a
    jr z,.canEscape
    ld [H_REMAINDER],a ; $FF00+$99 (aliases: H_DIVISOR,H_MULTIPLIER,H_POWEROFTEN)
    ld b,$2
    call Divide
    ld a,[$FF00+$97]
    and a
    jr nz,.canEscape
    ld a,[$d120]
    ld c,a
.asm_3cb2b
    dec c
    jr z,.asm_3cb39
    ld b,$1e
