; ──────────────────────────────────────────
; ExecutePlayerMove
; ──────────────────────────────────────────

ExecutePlayerMove: ; 3d65e (f:565e)
    xor a
    ld [H_WHOSETURN],a ; set player's turn
    ld a,[wPlayerSelectedMove] ; $ccdc
    inc a
    jp z,ExecutePlayerMoveDone ; for selected move = FF, skip most of player's turn
    xor a
    ld [W_MOVEMISSED],a ; $d05f
    ld [$cced],a ; MonIsDisobedient
    ld [$ccf4],a ; MoveDidntMiss
    ld a,10
    ld [$d05b],a ; DamageMultipliers
    ld a,[$cd6a] ; ActionResultOrTookBattleTurn
    and a ; has the player already used the turn (e.g. by using an item, trying to run or switching pokemon)
    jp nz,ExecutePlayerMoveDone
    call PrintGhostText
    jp z,ExecutePlayerMoveDone
    call CheckPlayerStatusConditions
    jr nz,.playerHasNoSpecialCondition
    jp hl
.playerHasNoSpecialCondition
    xor a        ; Reset
    ld [$d06a],a ; PlayerNumAttacksLeft
    call GetCurrentMove
    ld hl,W_PLAYERBATTSTATUS1 ; $d062
    bit CHARGING_UP,[hl] ; charging up for attack
    jr nz,PlayerCanExecuteChargingMove
    call CheckForDisobedience
    jp z,ExecutePlayerMoveDone

CheckIfPlayerNeedsToChargeUp:
    ld a,[W_PLAYERMOVEEFFECT] ; $cfd3
    cp CHARGE_EFFECT
    jp z,JumpMoveEffect
    cp FLY_EFFECT
    jp z,JumpMoveEffect
    jr PlayerCanExecuteMove

; in-battle stuff
PlayerCanExecuteChargingMove:
    ld hl,W_PLAYERBATTSTATUS1 ; reset charging up and invulnerability statuses if mon was charging up for an attack
                              ; being fully paralyzed or hurting oneself in confusion removes charging up status
                              ; resulting in the Pokemon being invulnerable for the whole battle
    res CHARGING_UP,[hl]
    res INVULNERABLE,[hl]
    inc hl
    res USING_FLY,[hl]
    dec hl

PlayerCanExecuteMove:
    call PrintMonName1Text
    ld de,wPlayerSelectedMove ; pointer to the move just used
    BANKSWITCH DecrementPP
    ld a,[W_PLAYERMOVEEFFECT] ; effect of the move just used
    ld hl,EffectsArray1
    call RunMoveEffectInList
    ret c ; ResidualEffects1 moves skip damage calculation and accuracy tests
                        ; unless executed as part of their exclusive effect functions
    ld a,[W_PLAYERMOVEEFFECT]
    ld hl,EffectsArray5B
    call RunMoveEffectInList ; execute the effects of SpecialEffectsCont moves (e.g. Wrap, Thrash) but don't skip anything
    ld a,[$d078] ; EscapedFromBattle
    and a
    ret nz ; return if whirlwind success
    xor a
    ld [W_MOVEMISSED],a

PlayerCalcMoveDamage:
    ld a,[W_PLAYERMOVEEFFECT]
    ld hl,EffectsArray2
    ld de,1
    call IsInArray
    jp c,.moveHitTest ; SetDamageEffects moves (e.g. Seismic Toss and Super Fang) skip damage calculation
    call CriticalHitTest
    call HandleCounterMove
    jr z,handleIfPlayerMoveMissed
    call CalculateDamage
    call MoreCalculateDamage
    jp z,playerCheckIfFlyOrChargeEffect ; for moves with 0 BP, skip any further damage calculation and, for now, skip MoveHitTest
                                        ; for these moves, accuracy tests will only occur if they are called as part of the effect itself
    call AdjustDamageForMoveType
    call RandomizeDamage
.moveHitTest
    call MoveHitTest

handleIfPlayerMoveMissed:
    ld a,[W_MOVEMISSED]
    and a
    jr z,.moveDidNotMiss
    xor a
    jr playPlayerMoveAnimation
.moveDidNotMiss
    ; ft

getPlayerAnimationType:
    ld a,[W_PLAYERMOVEEFFECT]
    and a
    ld a,4 ; move has no effect other than dealing damage
    jr z,playPlayerMoveAnimation
    ld a,5 ; move has effect

playPlayerMoveAnimation:
    push af
    ld a,[W_PLAYERBATTSTATUS2]
    bit 4,a ; HAS_SUBSTITUTE_UP
    BANKSWITCH_NZ HideSubstituteShowMonAnim
    pop af
    ld [$CC5B],a ; AnimationType
    ld a,[W_PLAYERMOVENUM]
    call PlayMoveAnimation_WithException
    call HandleExplodingAnimation
    call DrawPlayerHUDAndHPBar
    ld a,[W_PLAYERBATTSTATUS2]
    bit 4,a ; HAS_SUBSTITUTE_UP
    BANKSWITCH_NZ ReshowSubstituteAnim
    jr MirrorMoveCheck

playerCheckIfFlyOrChargeEffect:
    ld c,$1E
    call DelayFrames
    ld a,[W_PLAYERMOVEEFFECT]
    cp FLY_EFFECT
    jr z,.playAnim
    cp CHARGE_EFFECT
    jr z,.playAnim
    jr MirrorMoveCheck
.playAnim
    xor a
    ld [$CC5B],a
    ld a,$A7 ; STATUS_AFFECTED_ANIM
    call PlayMoveAnimation

MirrorMoveCheck:
    ld a,[W_PLAYERMOVEEFFECT]
    cp MIRROR_MOVE_EFFECT
    jr nz,.metronomeCheck
    call MirrorMoveCopyMove
    jp z,ExecutePlayerMoveDone
    xor a
    ld [$CCED],a
    jp CheckIfPlayerNeedsToChargeUp
.metronomeCheck
    cp METRONOME_EFFECT
    jr nz,.next
    call MetronomePickMove
    jp CheckIfPlayerNeedsToChargeUp ; if Mirror Move was successful go back to damage calculation for copied move
.next
    ld a,[W_PLAYERMOVEEFFECT]
    ld hl,EffectsArray3
    call RunMoveEffectInList
    ret c ; done here after executing effects of EffectsArray3
    ld a,[W_MOVEMISSED]
    and a
    jr z,.moveDidNotMiss
    call PrintMoveFailureText
    ld a,[W_PLAYERMOVEEFFECT]
    ld hl,EffectsArray6
    ld de,1
    call IsInArray
    jr c,.notDone
    jr ExecutePlayerMoveDone ; otherwise, we're done if the move missed
.moveDidNotMiss
    call ApplyAttackToEnemyPokemon
    call PrintCriticalOHKOText
    BANKSWITCH DisplayEffectiveness
    call PlayerMoveDidntMissAndEnemyBideAccum
.notDone
    ld a,[W_PLAYERMOVEEFFECT]
    ld hl,EffectsArray4
    call RunMoveEffectInList ; not done after executing effects of EffectsArray4
    ld hl,W_ENEMYMONCURHP
    ld a,[hli]
    ld b,[hl]
    or b
    ret z ; don't do anything else if the enemy fainted
    call HandleBuildingRage

    ld hl,W_PLAYERBATTSTATUS1
    bit 2,[hl] ; ATTACKING_MULTIPLE_TIMES
    jr z,.executeOtherEffects
    ld a,[$D06A] ; PlayerNumAttacksLeft
    dec a
    ld [$D06A],a ; PlayerNumAttacksLeft
    jp nz,getPlayerAnimationType ; for multi-hit moves, apply attack until PlayerNumAttacksLeft hits 0 or the enemy faints.
                                 ; damage calculation and accuracy tests only happen for the first hit

    res 2,[hl] ; ATTACKING_MULTIPLE_TIMES
    ld hl,MultiHitText
    call PrintText
    xor a
    ld [W_NUMHITS],a ; reset
.executeOtherEffects
    ld a,[W_PLAYERMOVEEFFECT]
    and a
    jr z,ExecutePlayerMoveDone
    ld hl,EffectsArray5
    call RunMoveEffectNotInList
    ; ft

ExecutePlayerMoveDone:
    xor a
    ld [$CD6A],a
    ld b,1
    ret

