SECTION "PrintGhostText",ROMX[$5811],BANK[$f]

PrintGhostText: ; 3d811 (f:5811)
; print the ghost battle messages
    call IsGhostBattle
    ret nz
    ld a,[H_WHOSETURN]
    and a
    jr nz,.Ghost
    ld a,[W_PLAYERMONSTATUS] ; player’s turn
    and a,SLP | FRZ
    ret nz
    ld hl,ScaredText
    call PrintText
    xor a
    ret
.Ghost ; ghost’s turn
    ld hl,GetOutText
    call PrintText
    xor a
    ret

