; ──────────────────────────────────────────────────────────────────────
; CheckPlayerStatusConditions
; ──────────────────────────────────────────────────────────────────────

CheckPlayerStatusConditions:
    ld hl,W_PLAYERMONSTATUS

.FrozenCheck
    bit FRZ_Bit,[hl]
    jr z,.SleepCheck
    ld hl,FrozenText
    jr .SleepFrozenDone

.SleepCheck
    ld a,[hl]
    and SLP
    ld a,[hl]
    jr z,.HeldInPlaceCheck

    dec a ; decrement sleep count
    ld [hl],a
    and SLP
    jr z,.WakeUp

    xor a
    ld [$CC5B],a
    ld a,SLP_ANIM - 1
    call PlayMoveAnimation
    ld hl,FastAsleepText

.SleepFrozenDone
    call PrintText
    xor a
    ld [$CCF1],a
    jr .ExecutePlayerMoveDone

.WakeUp
    ld hl,WokeUpText
    call .DrawHudAndPrintText ; call PrintText
    call IsGhostBattle
    jr z,.ExecutePlayerMoveDone
    ; ft

.HeldInPlaceCheck
    ld a,[W_ENEMYBATTSTATUS1]
    bit 5,a
    jr z,.FlinchedCheck
    ld hl,CantMoveText
    call PrintText
    ; ft

.ExecutePlayerMoveDone
    ld hl,ExecutePlayerMoveDone
    jp .Func_3da37

.FlinchedCheck
    ld hl,W_PLAYERBATTSTATUS1
    bit 3,[hl]
    jr z,.HyperBeamCheck
    res 3,[hl]
    ld hl,FlinchedText
    call PrintText
    jr .ExecutePlayerMoveDone

.HyperBeamCheck
    ld hl,W_PLAYERBATTSTATUS2
    bit 5,[hl]
    jr z,.next ; 58D7
    res 5,[hl]
    ld hl,MustRechargeText
    call PrintText
    jr .ExecutePlayerMoveDone
.next
    ld hl,$D06D
    ld a,[hl]
    and a
    jr z,.next2 ; 58EE
    dec a
    ld [hl],a
    and a,$F
    jr nz,.next2
    ld [hl],a
    ld [$CCEE],a
    ld hl,DisabledNoMoreText
    call PrintText
.next2
    ld a,[W_PLAYERBATTSTATUS1]
    add a
    jr nc,.next3 ; 5929
    ld hl,$D06B
    dec [hl]
    jr nz,.next4 ; 5907
    ld hl,W_PLAYERBATTSTATUS1
    res 7,[hl]
    ld hl,ConfusedNoMoreText
    call .DrawHudAndPrintText ; call PrintText
    jr .next3
.next4
    ld hl,IsConfusedText
    call PrintText
    xor a
    ld [$CC5B],a
    ld a,CONF_ANIM - 1
    call PlayMoveAnimation
    call GenRandomInBattle
    cp $80
    jr c,.next3
    ld hl,W_PLAYERBATTSTATUS1
    ld a,[hl]
    and a,$80
    ld [hl],a
    call PlayerHurtItself
    jr .MonHurtItselfOrFullyParalysed ; 5952
.next3
    ld a,[$CCEE]
    and a
    jr z,.ParalysisCheck ; 593E
    ld hl,$CCDC
    cp [hl]
    jr nz,.ParalysisCheck
    call Func_3da88
    jp .ExecutePlayerMoveDone
.ParalysisCheck
    ld hl,W_PLAYERMONSTATUS
    bit 6,[hl]
    jr z,.next7 ; 5975
    call GenRandomInBattle ; random number
    cp $3F
    jr nc,.next7
    ld hl,FullyParalyzedText
    call PrintText
.MonHurtItselfOrFullyParalysed
    ld hl,W_PLAYERBATTSTATUS1
    ld a,[hl]
    and %10001100 ; Reset also invulnerablility
    ld [hl],a
    inc hl
    res USING_FLY,[hl]
    dec hl
    ld a,[W_PLAYERMOVEEFFECT]
    cp FLY_EFFECT
    jr z,.next8 ; 5966
    cp CHARGE_EFFECT
    jp nz,.ExecutePlayerMoveDone
.next8
    xor a
    ld [$CC5B],a
    ld a,$A7
    call PlayMoveAnimation
    jp .ExecutePlayerMoveDone
.next7
    ld hl,W_PLAYERBATTSTATUS1
    bit 0,[hl]
    jr z,.next10 ; 59D0
;joenote - done elsewhere using PlayerBideAccum
;    xor a
;    ld [W_PLAYERMOVENUM],a
;    ld hl,$D0D7
;    ld a,[hli]
;    ld b,a
;    ld c,[hl]
;    ld hl,$D075
;    ld a,[hl]
