CalculateDamage: ; 3ddcf (f:5dcf)
    xor a
    ld hl,W_DAMAGE ;damage to eventually inflict,intitialise to zero
    ldi [hl],a
    ld [hl],a
    ld hl,W_PLAYERMOVEPOWER
    ld a,[hli]     ;*read attack base power
    and a
    ld d,a         ;*D = attack base,used later
    ret z           ;return if attack is zero
    ;ld a,[hl]      ;*test attacking type
    ;cp $14       ;types >= $14 are all special
    call TestPhysicalSpecialBattle
    jr nz,.specialAttack
.physicalAttack
    ld hl,W_ENEMYMONDEFENSE    ;opponent defense
    ld a,[hli]                 ;*BC = opponent defense used later
    ld b,a
    ld c,[hl]
    ld a,[W_ENEMYBATTSTATUS3]  ;test for reflect
    bit 2,a ; reflect
    jr z,.next
.doubleDefense
    sla c  ;x2 defense if bit2 of D069 is set
    rl b
; reflect and light screen boosts do not cap the stat at 999, so weird things will happen during stats scaling if
; a Pokemon with 512 or more Defense has used Reflect, or if a Pokemon with 512 or more Special has used Light Screen
    PREDEF BC999cap
.next
    ld hl,W_PLAYERMONATK  ;attack pointer
    ld a,[wCriticalHitOrOHKO]
    and a
    jr z,.next3
    ld c,3
    call GetEnemyMonStat
    ld a,[$ff00+$97]
    ld b,a
    ld a,[$ff00+$98]
    ld c,a
    push bc
    ld hl,$d18f
    ld a,[wPlayerMonNumber]
    ld bc,$002c
    call AddNTimes
    pop bc
    PREDEF CritHitStatsPlayerPhysical
    jr .next3
.specialAttack
    ld hl,W_ENEMYMONSPECIAL    ;opponent special
    ld a,[hli]                 ;*BC = opponent special defense used later
    ld b,a
    ld c,[hl]
    ld a,[W_ENEMYBATTSTATUS3]  ;test for lightscreen
    bit 1,a ; light screen
    jr z,.next2
.doubleSpecialDefense
    sla c           ;x2 special defense if bit1 of D069 set
    rl b
; reflect and light screen boosts do not cap the stat at 999, so weird things will happen during stats scaling if
; a Pokemon with 512 or more Defense has used Reflect, or if a Pokemon with 512 or more Special has used Light Screen
    PREDEF BC999cap
.next2
    ld hl,W_PLAYERMONSPECIAL
    ld a,[wCriticalHitOrOHKO]   ;XXX
    and a
    jr z,.next3  ;skip portion of code that pulls up inactive pokemon
    ld c,5
    call GetEnemyMonStat
    ld a,[$ff00+$97]
    ld b,a
    ld a,[$ff00+$98]
    ld c,a
    push bc
    ld hl,$d195
    ld a,[wPlayerMonNumber]
    ld bc,$002c
    call AddNTimes
    pop bc
    PREDEF CritHitStatsPlayerSpecial
.next3
    call GetDamageVarsScaleStats
.next4
    ld b,l        ;*B = attack [possibly scaled] [C contains defense]
    ld a,[$d022]  ;*E = level
    ld e,a
;    ld a,[wCriticalHitOrOHKO] ; do this in damage calculation
;    and a                     ; ...
;    jr z,.next5               ; ...
;    sla e                     ; ...
;.next5                        ; ...
    ld a,1  ;return Z = 0
    and a
    ret

CalculateDamageAfterEnemyAttack:
    ld hl,W_DAMAGE ; $d0d7
    xor a
