    rl b
; reflect and light screen boosts do not cap the stat at 999, so weird things will happen during stats scaling if
; a Pokemon with 512 or more Defense has used Reflect, or if a Pokemon with 512 or more Special has used Light Screen
    PREDEF BC999cap
.next2
    ld hl,W_ENEMYMONSPECIAL ; $cffc
    ld a,[wCriticalHitOrOHKO]
    and a
    jr z,.next3
    ld hl,W_PARTYMON1_SPECIAL ; $d195
    ld a,[wPlayerMonNumber] ; $cc2f
    ld bc,$2c
    call AddNTimes
    ld a,[hli]
    ld b,a
    ld c,[hl]
    push bc
    ld c,$5
    call GetEnemyMonStat
    ld hl,$ff97
    pop bc
    PREDEF CritHitStatsEnemySpecial
.next3
    call GetDamageVarsScaleStats
.next4
    ld b,l
    ld a,[W_ENEMYMONLEVEL] ; $cff3
    ld e,a
;    ld a,[wCriticalHitOrOHKO] ; do this in damage calculation
;    and a                     ; ...
;    jr z,.next5               ; ...
;    sla e                     ; ...
;.next5                        ; ...
    ld a,1
    and a
    and a
    ret

; get stat c of enemy mon
; c: stat to get (HP=1,Attack=2,Defense=3,Speed=4,Special=5)
GetEnemyMonStat:
    push de
    push bc
    ld a,[W_ISLINKBATTLE] ; $d12b
    cp $4
    jr nz,.asm_3df40
    ld hl,$d8c6
    dec c
    sla c
    ld b,$0
    add hl,bc
    ld a,[W_ENEMYMONNUMBER] ; $cfe8
    ld bc,$2c
    call AddNTimes
    ld a,[hli]
    ld [$FF00+$97],a
    ld a,[hl]
    ld [$FF00+$98],a
    pop bc
    pop de
    ret
.asm_3df40
    ld a,[W_ENEMYMONLEVEL] ; $cff3
    ld [W_CURENEMYLVL],a ; $d127
    ld a,[W_ENEMYMON_START]
    ld [$d0b5],a
    call GetEnemyMonStat_HandleAlternative ; call GetMonHeader
    ld hl,$cff1
    ld de,$cfaf
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[hl]
    ld [de],a
    pop bc
    ld b,$0
    ld hl,$cfa4
    call CalcStat
    pop de
    ret

MoreCalculateDamage:
; input:
;    b: attack
;    c: opponent defense
;    d: base power
;    e: level

    ld a,[$fff3] ; whose turn?
    and a
    ld a,[W_PLAYERMOVEEFFECT]
    jr z,.effect
    ld a,[W_ENEMYMOVEEFFECT]
.effect

; EXPLODE_EFFECT halves defense.
    cp EXPLODE_EFFECT
    jr nz,.ok
    srl c
    jr nz,.ok
    inc c ; ...with a minimum value of 1 (used as a divisor later on)
.ok

; Multi-hit attacks may or may not have 0 bp.
    cp TWO_TO_FIVE_ATTACKS_EFFECT
    jr z,.skipbp
    cp $1e
    jr z,.skipbp

; Calculate OHKO damage based on remaining HP.
    cp OHKO_EFFECT
    jp z,.Func_3e016

; Don't calculate damage for moves that don't do any.
    ld a,d ; base power
    and a
    ret z
.skipbp

    xor a
    ld hl,H_DIVIDEND
    ldi [hl],a
    ldi [hl],a
    ld [hl],a

; Multiply level by 2
; made this more efficient by using shifts and rotates
    ld a,e ; level
;    add a
;    jr nc,.nc
;    push af
;    ld a,1
;    ld [hl],a
;    pop af
;.nc
;    inc hl
;    ldi [hl],a
    sla a
    rl [hl]

; double the effective level here if critical hit instead of GetDamageVars functions
    push bc
    ld b,a
    ld a,[wCriticalHitOrOHKO]
    cp 1
    ld a,b
    pop bc
    jr c,.nocrit
    sla a
    rl [hl]
.nocrit
    inc hl
    ldi [hl],a

; Divide by 5
    ld a,5
    ldd [hl],a
    push bc
    ld b,4
    call Divide
    pop bc

; Add 2
    inc [hl]
    inc [hl]

    inc hl ; multiplier

; Multiply by attack base power
    ld [hl],d
    call Multiply

; Multiply by attack stat
    ld [hl],b
    call Multiply

; Divide by defender's defense stat
    ld [hl],c
    ld b,4
    call Divide

; Divide by 50
    ld [hl],50
    ld b,4
    call Divide

    ld hl,W_DAMAGE
    ld b,[hl]
    ld a,[H_QUOTIENT + 3]
    add b
    ld [H_QUOTIENT + 3],a
    jr nc,.asm_3dfd0

    ld a,[H_QUOTIENT + 2]
    inc a
    ld [H_QUOTIENT + 2],a
    and a
    jr z,.asm_3e004

.asm_3dfd0
    ld a,[H_QUOTIENT]
    ld b,a
    ld a,[H_QUOTIENT + 1]
    or a
    jr nz,.asm_3e004

    ld a,[H_QUOTIENT + 2]
    cp 65279 / $100 ; cp 998 / $100 ; Denim,aumentato danno massimo a $FEFF
    jr c,.asm_3dfe8
    cp 65279 / $100 + 1
    jr nc,.asm_3e004
    ld a,[H_QUOTIENT + 3]
    cp 65279 % $100
    jr nc,.asm_3e004

.asm_3dfe8
    inc hl
    ld a,[H_QUOTIENT + 3]
    ld b,[hl]
    add b
    ld [hld],a

    ld a,[H_QUOTIENT + 2]
    ld b,[hl]
    adc b
    ld [hl],a
    jr c,.asm_3e004

    ld a,[hl]
    cp 65279 / $100
    jr c,.asm_3e00a
    cp 65279 / $100 + 1
    jr nc,.asm_3e004
    inc hl
    ld a,[hld]
    cp 65279 % $100
    jr c,.asm_3e00a

.asm_3e004
    ld a,65278 / $100
    ld [hli],a
    ld a,65278 % $100
    ld [hld],a

.asm_3e00a
    inc hl
    ld a,[hl]
    add 2
    ld [hld],a
    jr nc,.done
    inc [hl]
.done

    ld a,1
    and a
    ret

.Func_3e016
    call JumpMoveEffect
    ld a,[W_MOVEMISSED] ; $d05f
    dec a
    ret

INCBIN "baserom.gbc",$3e01e,$3e023 - $3e01e

; determines if attack is a critical hit
CriticalHitTest:
    BANKSWITCH_JUMP _CriticalHitTest_NoBug

ResetLeechSeedFlagAndReadPlayerMonCurHPAndStatus:
    ;joenote - zero the damage from last round if not using a trapping move
    call CheckTrappingToResetDamage
    ;joenote - clear custom battle flags
    ld a,[wUnusedC000]
    res 7,a ;reset the bit that causes counter to miss
    res 6,a ;reset the bit that specifies a leech seed effect
    ld [wUnusedC000],a
    jp ReadPlayerMonCurHPAndStatus

CheckNotEscapeWildPokemon:
    push hl
    BANKSWITCH _CheckNotEscapeWildPokemon
    pop hl
    ret

DrawCurrentMonGenderInBattle:
    push de
    push bc
    BANKSWITCH _DrawCurrentMonGenderInBattle
    pop bc
    pop de
    ret

ResetBattleFlagAndLoadCurrentOpponent:
    xor a
    ld [wUnusedC000],a;joenote - clear custom ai bits and battle flags at battle start
    ld [wUnusedD366],a;joenote - clear ai switch tracker bits
    ld a,[W_CUROPPONENT] ; $d059
    ret

; function to determine if Counter hits and if so,how much damage it does
HandleCounterMove:
    ld a,[H_WHOSETURN] ; whose turn
    and a
; player's turn
    ld hl,wEnemySelectedMove
    ld bc,W_ENEMYMON_START
    ld de,W_ENEMYMOVEPOWER
    ld a,[wPlayerSelectedMove]
    jr z,.next
; enemy's turn
    ld hl,wPlayerSelectedMove
    ld bc,W_PLAYERMONID
    ld de,W_PLAYERMOVEPOWER
    ld a,[wEnemySelectedMove]
.next
    cp COUNTER
    ret nz ; return if not using Counter
    ld a,$01
    ld [W_MOVEMISSED],a ; initialize the move missed variable to true (it is set to false below if the move hits)
    ld a,[hl]
    cp COUNTER
    ret z ; if the target also used Counter,miss
    ld a,[de]
    and a
    ret z ; if the move the target used has 0 power,miss
    push bc ; Backup Target ID
    ld hl,(W_PLAYERMONATK)-W_PLAYERMONID
    add hl,bc
    ld d,h
    ld e,l ; de point to mon attack
    call TestPhysicalSpecial
    pop de ; Restore Target ID
    jr nz,.specialAttackFail
    call CheckCounterFail
    ret z
; double the damage that the target did to the Counter user
    ld a,[hl]
    add a
    ldd [hl],a
    ld a,[hl]
    adc a
    ld [hl],a
    jr nc,.noCarry
; damage is capped at 0xFFFF
    ld a,$ff
    ld [hli],a
    ld [hl],a
.noCarry
    xor a
    ld [W_MOVEMISSED],a
    call MoveHitTest ; do the normal move hit test in addition to Counter's special rules
.specialAttackFail
    xor a
    ret

HalvePlayerSpeedAfterRun:
    ld a,[hli]
    srl a ; Player Speed divided by 2
    ld [$FF00+$97],a
    ld a,[hl]
    rr a  ; Player Speed divided by 2
    ld [$FF00+$98],a
    ld a,[de]
    ld [$FF00+$8d],a
    inc de
    ld a,[de]
    ld [$FF00+$8e],a
    ret

ReflectLightScreenEffect:
    BANKSWITCH_JUMP ReflectLightScreenEffect_

EnemyMonFainted:
    TX_FAR _EnemyMonFainted
    db "@"

Func_3c643:
    xor a
    ld [$d083],a
    ld [$c02a],a
    inc a
    ld [$ccf6],a
    ret

; Free

SECTION "ApplyAttackToEnemyPokemon",ROMX[$60df],BANK[$f]

ApplyAttackToEnemyPokemon: ; 3e0df (f:60df)
    ld a,[W_PLAYERMOVEEFFECT]
    cp OHKO_EFFECT
    jr z,ApplyDamageToEnemyPokemon
    cp SUPER_FANG_EFFECT
    jr z,.superFangEffect
    cp SPECIAL_DAMAGE_EFFECT
    jr z,.specialDamage
    call CheckTrappingToResetPlayerHyperBeam ; ld a,[W_PLAYERMOVEPOWER]
    and a
    jp z,ApplyAttackToEnemyPokemonDone
    jr ApplyDamageToEnemyPokemon
.superFangEffect
; set the damage to half the target's HP
    ld hl,W_ENEMYMONCURHP
    ld de,W_DAMAGE
    ld a,[hli]
    srl a
    ld [de],a
    inc de
    ld b,a
    ld a,[hl]
    rr a
    ld [de],a
    or b
    jr nz,ApplyDamageToEnemyPokemon
; make sure Super Fang's damage is always at least 1
    ld a,$01
    ld [de],a
    jr ApplyDamageToEnemyPokemon
.specialDamage
    ld hl,W_PLAYERMONLEVEL
    ld a,[hl]
    ld b,a
    ld a,[W_PLAYERMOVENUM]
    cp SEISMIC_TOSS
    jr z,.storeDamage
    cp NIGHT_SHADE
    jr z,.storeDamage
    ld b,SONICBOOM_DAMAGE
    cp SONICBOOM
    jr z,.storeDamage
    ld b,DRAGON_RAGE_DAMAGE
    cp DRAGON_RAGE
    jr z,.storeDamage
; Psywave
    ld a,[hl]
    ld b,a
    srl a
    add b
    ld b,a ; b = level * 1.5
; loop until a random number in the range [1,b) is found
.loop
    call GenRandomInBattle ; random number
    and a
    jr z,.loop
    cp b
    jr nc,.loop
    ld b,a
.storeDamage
    ld hl,W_DAMAGE
    xor a
    ld [hli],a
    ld a,b
    ld [hl],a

ApplyDamageToEnemyPokemon: ; 3e142 (f:6142)
    call SetDamageDirectToEnemy ; Denim ; ld hl,W_DAMAGE
    ld a,[hli]
    ld b,a
    ld a,[hl]
    or b
    ;jr z,ApplyAttackToEnemyPokemonDone ; we're done if damage is 0
    ld a,[W_ENEMYBATTSTATUS2]
    bit 4,a ; does the enemy have a substitute?
    jp nz,AttackSubstitute
; subtract the damage from the pokemon's current HP
; also,save the current HP at wHPBarOldHP
    ld a,[hld]
    ld b,a
    ld a,[W_ENEMYMONCURHP + 1]
    ld [wHPBarOldHP],a
    sub b
    ld [W_ENEMYMONCURHP + 1],a
    ld a,[hl]
    ld b,a
    ld a,[W_ENEMYMONCURHP]
    ld [wHPBarOldHP+1],a
    sbc b
    ld [W_ENEMYMONCURHP],a
    jr nc,.animateHpBar
; if more damage was done than the current HP,zero the HP and set the damage
; equal to how much HP the pokemon had before the attack
    ld a,[wHPBarOldHP+1]
    ld [hli],a
    ld a,[wHPBarOldHP]
    ld [hl],a
    xor a
    ld hl,W_ENEMYMONCURHP
    ld [hli],a
    ld [hl],a
.animateHpBar
    ld hl,W_ENEMYMONMAXHP
    ld a,[hli]
    ld [wHPBarMaxHP+1],a
    ld a,[hl]
    ld [wHPBarMaxHP],a
    ld hl,W_ENEMYMONCURHP
    ld a,[hli]
    ld [wHPBarNewHP+1],a
    ld a,[hl]
    ld [wHPBarNewHP],a
    FuncCoord 02,02 ; Enemy Bar in Battle
    ld hl,Coord
    xor a
    ld [$cf94],a
    PREDEF UpdateHPBar ; animate the HP bar shortening
ApplyAttackToEnemyPokemonDone: ; 3e19d (f:619d)
    jp DrawHUDsAndHPBars ; redraw pokemon names and HP bars

SECTION "ApplyAttackToPlayerPokemon",ROMX[$61a0],BANK[$f]

ApplyAttackToPlayerPokemon: ; 3e1a0 (f:61a0)
    ld a,[W_ENEMYMOVEEFFECT]
    cp OHKO_EFFECT
    jr z,ApplyDamageToPlayerPokemon
    cp SUPER_FANG_EFFECT
    jr z,.superFangEffect
    cp SPECIAL_DAMAGE_EFFECT
    jr z,.specialDamage
    call CheckTrappingToResetEnemyHyperBeam ; ld a,[W_ENEMYMOVEPOWER]
    and a
    jp z,ApplyAttackToPlayerPokemonDone
    jr ApplyDamageToPlayerPokemon
.superFangEffect
; set the damage to half the target's HP
    ld hl,W_PLAYERMONCURHP
    ld de,W_DAMAGE
    ld a,[hli]
    srl a
    ld [de],a
    inc de
    ld b,a
    ld a,[hl]
    rr a
    ld [de],a
    or b
    jr nz,ApplyDamageToPlayerPokemon
; make sure Super Fang's damage is always at least 1
    ld a,$01
    ld [de],a
    jr ApplyDamageToPlayerPokemon
.specialDamage
    ld hl,W_ENEMYMONLEVEL
    ld a,[hl]
    ld b,a
    ld a,[W_ENEMYMOVENUM]
    cp SEISMIC_TOSS
    jr z,.storeDamage
    cp NIGHT_SHADE
    jr z,.storeDamage
    ld b,SONICBOOM_DAMAGE
    cp SONICBOOM
    jr z,.storeDamage
    ld b,DRAGON_RAGE_DAMAGE
    cp DRAGON_RAGE
    jr z,.storeDamage
; Psywave
    ld a,[hl]
    ld b,a
    srl a
    add b
    ld b,a ; b = attacker's level * 1.5
; loop until a random number in the range [0,b) is found
; this differs from the range when the player attacks,which is [1,b)
; it's possible for the enemy to do 0 damage with Psywave,but the player always does at least 1 damage
.loop
    call GenRandomInBattle ; random number
    cp b
    jr nc,.loop
    ld b,a
.storeDamage
    ld hl,W_DAMAGE
    xor a
    ld [hli],a
    ld a,b
    ld [hl],a

ApplyDamageToPlayerPokemon: ; 3e200 (f:6200)
    call SetDamageDirectToPlayer ; Denim ; ld hl,W_DAMAGE
    ld a,[hli]
    ld b,a
    ld a,[hl]
    or b
    ;jr z,ApplyAttackToPlayerPokemonDone ; we're done if damage is 0
    ld a,[W_PLAYERBATTSTATUS2]
    bit 4,a ; does the player have a substitute?
    jp nz,AttackSubstitute
; subtract the damage from the pokemon's current HP
; also,save the current HP at wHPBarOldHP and the new HP at wHPBarNewHP
    ld a,[hld]
    ld b,a
    ld a,[W_PLAYERMONCURHP + 1]
    ld [wHPBarOldHP],a
    sub b
    ld [W_PLAYERMONCURHP + 1],a
    ld [wHPBarNewHP],a
    ld b,[hl]
    ld a,[W_PLAYERMONCURHP]
    ld [wHPBarOldHP+1],a
    sbc b
    ld [W_PLAYERMONCURHP],a
    ld [wHPBarNewHP+1],a
    jr nc,.animateHpBar
; if more damage was done than the current HP,zero the HP and set the damage
; equal to how much HP the pokemon had before the attack
    ld a,[wHPBarOldHP+1]
    ld [hli],a
    ld a,[wHPBarOldHP]
    ld [hl],a
    xor a
    ld hl,W_PLAYERMONCURHP
    ld [hli],a
    ld [hl],a
    ld hl,wHPBarNewHP
    ld [hli],a
    ld [hl],a
.animateHpBar
    ld hl,W_PLAYERMONMAXHP
    ld a,[hli]
    ld [wHPBarMaxHP+1],a
    ld a,[hl]
    ld [wHPBarMaxHP],a
    FuncCoord 10,09 ; Player Bar in Battle
    ld hl,Coord
    ld a,$01
    ld [$cf94],a
    PREDEF UpdateHPBar ; animate the HP bar shortening
ApplyAttackToPlayerPokemonDone
    jp DrawHUDsAndHPBars ; redraw pokemon names and HP bars

AttackSubstitute: ; 3e25e (f:625e)
    call GetPlayerOrEnemyTurnWithSubstitute
    push de
    push bc
    BANKSWITCH PrintBattleValueNearMon_
    call RemoveBattleValueBankF
    ld hl,.SubstituteTookDamageText
    call PrintText
    pop bc
    pop de
    ld hl,W_DAMAGE
    ld a,[hli]
    and a
    jr nz,.substituteBroke ; damage > 0xFF always breaks substitutes
; subtract damage from HP of substitute
    ld a,[de]
    sub [hl]
    ld [de],a
    ret nc
.substituteBroke
    ld h,b
    ld l,c
    res 4,[hl] ; unset the substitute bit
    ld hl,.SubstituteBrokeText
    call PrintText
; flip whose turn it is for the next function call
    call FlipTurn
    BANKSWITCH HideSubstituteShowMonAnim ; animate the substitute breaking
; flip the turn back to the way it was
    call FlipTurn
    ld hl,W_PLAYERMOVEEFFECT ; value for player's turn
    and a
    jr z,.nullifyEffect
    ld hl,W_ENEMYMOVEEFFECT ; value for enemy's turn
.nullifyEffect
    call CheckNotNullifyEffectWithSubstitute
    jr z,.skipNullify
    xor a
    ld [hl],a ; zero the effect of the attacker's move
.skipNullify
    jp DrawHUDsAndHPBars ; redraw pokemon names and HP bars
.SubstituteBrokeText
    TX_FAR _SubstituteBrokeText
    db "@"
.SubstituteTookDamageText
    TX_FAR _SubstituteTookDamageText
    db "@"

SECTION "HandleBuildingRage",ROMX[$62b6],BANK[$f]

; this function raises the attack modifier of a pokemon using Rage when that pokemon is attacked
HandleBuildingRage: ; 3e2b6 (f:62b6)
; values for the player turn
    ld hl,W_ENEMYBATTSTATUS2
    ld de,wEnemyMonStatMods
    ld bc,W_ENEMYMOVENUM
    ld a,[H_WHOSETURN]
    and a
    jr z,.next
; values for the enemy turn
    ld hl,W_PLAYERBATTSTATUS2
    ld de,wPlayerMonStatMods
    ld bc,W_PLAYERMOVENUM
.next
    bit 6,[hl] ; is the pokemon being attacked under the effect of Rage?
    ret z ; return if not
    ld a,[de]
    cp $0d ; maximum stat modifier value
    ret z ; return if attack modifier is already maxed
    ld a,[H_WHOSETURN]
    xor a,$01 ; flip turn for the stat modifier raising function
    ld [H_WHOSETURN],a
; change the target pokemon's move to $00 and the effect to the one
; that causes the attack modifier to go up one stage
    ld h,b
    ld l,c
    ld [hl],$00 ; null move number
    inc hl
    ld [hl],ATTACK_UP1_EFFECT
    push hl
    ld hl,BuildingRageText
    call PrintText
    call StatModifierUpEffect ; stat modifier raising function
    pop hl
    xor a
    ldd [hl],a ; null move effect
    ld a,RAGE
    ld [hl],a ; restore the target pokemon's move number to Rage
    ld a,[H_WHOSETURN]
    xor a,$01 ; flip turn back to the way it was
    ld [H_WHOSETURN],a
    ret

BuildingRageText: ; 3e2f8 (f:62f8)
    TX_FAR _BuildingRageText
    db "@"

; copy last move for Mirror Move
; sets zero flag on failure and unsets zero flag on success
MirrorMoveCopyMove: ; 3e2fd (f:62fd)
    ld a,[H_WHOSETURN]
    and a
; values for player turn
    ld a,[$ccf2]
    ld hl,wPlayerSelectedMove
    ld de,W_PLAYERMOVENUM
    jr z,.next
; values for enemy turn
    ld a,[$ccf1]
    ld de,W_ENEMYMOVENUM
    ld hl,wEnemySelectedMove
.next
    ld [hl],a
    cp MIRROR_MOVE ; did the target pokemon also use Mirror Move?
    jr z,.mirrorMoveFailed
    and a ; null move?
    jr nz,ReloadMoveData
.mirrorMoveFailed
; Mirror Move fails on itself and null moves
    ld hl,MirrorMoveFailedText
    call PrintText
    xor a
    ret

MirrorMoveFailedText: ; 3e324 (f:6324)
    TX_FAR _MirrorMoveFailedText
    db "@"

; function used to reload move data for moves like Mirror Move and Metronome
ReloadMoveData: ; 3e329 (f:6329)
    ld [$d11e],a
    dec a
    ld hl,Moves
    ld bc,$0006
    call AddNTimes
    ld a,BANK(Moves)
    call FarCopyData ; copy the move's stats
    call ZeroMoveEnergy
; the follow two function calls are used to reload the move name
    call GetMoveName
    call CopyStringToCF4B
    ld a,$01
    and a
    ret

; function that picks a random move for metronome
MetronomePickMove: ; 3e348 (f:6348)
    xor a
    ld [$cc5b],a
    ld a,METRONOME
    call PlayMoveAnimation ; play Metronome's animation
; values for player turn
    ld de,W_PLAYERMOVENUM
    ld hl,wPlayerSelectedMove
    ld a,[H_WHOSETURN]
    and a
    jr z,.pickMoveLoop
; values for enemy turn
    ld de,W_ENEMYMOVENUM
    ld hl,wEnemySelectedMove
; loop to pick a random number in the range [1,$a5) to be the move used by Metronome
.pickMoveLoop
    call GenRandomInBattle ; random number
    and a
    jr z,.pickMoveLoop
    cp $a5 ; max normal move number + 1 (this is Struggle's move number)
    jr nc,.pickMoveLoop
    cp METRONOME
    jr z,.pickMoveLoop
    ld [hl],a
    jr ReloadMoveData

; this function set to zero the current move's Energy
; it's used to prevent moves that run another move within the same turn
; (like Mirror Move and Metronome) from losing energy 2 times
ZeroMoveEnergy: ; 3e373 (f:6373)
; PP ► ENERGY - DONE
    ld a,[H_WHOSETURN]
    and a
; values for player turn
    ld hl,W_PLAYERMOVEMAXPP
    jr z,.next
; values for enemy turn
    ld hl,W_ENEMYMOVEMAXPP
.next
    ld [hl],0
    ret

; Input de = pointer to first move
; Output c = numer of moves
;        z flag = set if 0 moves
HowManyMovesWithEnoughEnergy:
    ld a,[wCurrentMenuItem] ; Backup Current Menu Item
    push af                 ; ...
    ld bc,0
.Loop
    ld a,b
    cp 4
    jr z,.End
    ld [wCurrentMenuItem],a
    push bc
    BANKSWITCH CheckEnoughEnergy
    pop bc
    jr c,.Next
    inc c
.Next
    inc b
    jr .Loop
.End
    pop af                  ; Restore Current Menu Item
    ld [wCurrentMenuItem],a ; ...
    ret

; function to adjust the base damage of an attack to account for type effectiveness
AdjustDamageForMoveType:
    PREDEF AdjustDamageForMoveType_GetInput
    jr z,.skipSameTypeAttackBonus ; TYPE_NA?
    ld a,[$d11e] ; move type
    ld hl,wTmpAttackerTypes
    ld b,4
.LoopAttackerTypes
    cp [hl] ; does the move type match type of the attacker?
    jr z,.sameTypeAttackBonus
    inc hl
    dec b
    jr nz,.LoopAttackerTypes
    jr .skipSameTypeAttackBonus
.sameTypeAttackBonus
; if the move type matches one of the attacker's types
    ld hl,W_DAMAGE + 1
    ld a,[hld]
    ld h,[hl]
    ld l,a    ; hl = damage
    ld b,h
    ld c,l    ; bc = damage
    srl b
    rr c      ; bc = floor(0.5 * damage)
    add hl,bc ; hl = floor(1.5 * damage)
; store damage
    ld a,h
    ld [W_DAMAGE],a
    ld a,l
    ld [W_DAMAGE + 1],a
    ld hl,$d05b
    set 7,[hl]
.skipSameTypeAttackBonus
    ld a,[$d11e]
    ld b,a ; b = move type
    call GetTypeEffects
.loop
    ld a,[hli] ; a = "attacking type" of the current type pair
    cp $ff
    jr z,.done
    cp b ; does move type match "attacking type"?
    jr nz,.nextTypePair
    ld a,[hl] ; a = "defending type" of the current type pair
    push hl
    ld hl,wTmpDefenderTypes
    ld d,4
.LoopDefenderTypes
    cp [hl] ; does type of defender match "defending type"?
    jr z,.matchingPairFound
    inc hl
    dec d
    jr nz,.LoopDefenderTypes
    pop hl
    jr .nextTypePair
.matchingPairFound
    pop hl
; if the move type matches the "attacking type" and one of the defender's types matches the "defending type"
    push hl
    push bc
    inc hl
    ld a,[$d05b]
    ; and a,$80
    ld b,a
    ld a,[hl] ; a = damage multiplier
    ld [H_MULTIPLIER],a
    ; add b
    ; ld [$d05b],a
    call MultiplyD05B ; Denim,corretto bug superefficace!
    xor a
    ld [H_MULTIPLICAND],a
    ld hl,W_DAMAGE
    ld a,[hli]
    ld [H_MULTIPLICAND + 1],a
    ld a,[hld]
    ld [H_MULTIPLICAND + 2],a
    call Multiply
    ld a,10
    ld [H_DIVISOR],a
    ld b,$04
    call Divide
    ld a,[H_QUOTIENT + 2]
    ld [hli],a
    ld b,a
    ld a,[H_QUOTIENT + 3]
    ld [hl],a
    or b ; is damage 0?
    jr nz,.skipTypeImmunity
    ld [wCriticalHitOrOHKO],a ; if damage is 0,delete crit hit flag
.skipTypeImmunity
    pop bc
    pop hl
.nextTypePair
    inc hl
    inc hl
    jp .loop
.done
    ret

HandleEnemySwitchingOrUsingAnItemAndThenExecutePlayerMove:
    ld a,$1
    ld [H_WHOSETURN],a
    BANKSWITCH TrainerAI
    call c,SetEnemyActedBit ;if carry was set from TrainerAI, set the bit indicating the ai trainer switched or used an item
    jp ExecutePlayerMove ; execute player move ;note: this function writes zero to H_WHOSETURN

HandleMenuInputLockedDuringDebugEnemyMove:
    ld hl,wDebugEnemyMoveBit7
    bit 7,[hl]
    res 7,[hl]
    jp z,HandleMenuInput ; No Lock
    call WaitButtonPressed
    ld a,%0000010 ; Emulate B press to Close Debug Enemy Move Menù
    ret

GetTypeEffects:
    push bc
    push de
    BANKSWITCH GetTypeEffects_
    pop de
    pop bc
    ld hl,wBufferTypeEffects
    ret

CheckPoisonableMon:
    ld b,4
.loop
    ld a,[hli]
    cp POISON ; can't poison a poison-type target
    ret z
    cp METAL ; can't poison a metal-type target
    ret z
    dec b
    jr nz,.loop
    ld a,1 ; reset all flag
    or a   ; ...
    ret

BackupMovesBeforeEnemyMimic:
    push af
    push de
    jr z,.end
    ld a,[W_ISINBATTLE]
    dec a ; wild?
    jr nz,.end
    ld hl,W_ENEMYBATTSTATUS3
    bit 3,[hl] ; Pokemon is Just Transformed
    jr nz,.end
    ; Backup Moves
    set 3,[hl] ; Set Transformed
    ld hl,W_ENEMYMONMOVES
    ld de,wBackupEnemyMoves
    ld bc,4
    call CopyData
.end
    pop de
    pop af
    ld hl,W_PLAYERMONMOVES
    ret

HazeEffect:
    BANKSWITCH_JUMP HazeEffect_

JumpMoveEffect:
    call JumpMoveEffect_
    ld b,$1
    ret

;joenote - zero the damage from last round if not using a trapping move
CheckTrappingToResetDamage:
    ld a,[W_ENEMYBATTSTATUS1]
    bit USING_TRAPPING_MOVE,a
    ret nz
    ld a,[W_PLAYERBATTSTATUS1]
    bit USING_TRAPPING_MOVE,a
    ret nz
    ; ft ; joenote - prevent counter shenanigans of all sorts

;joenote - this sets the last damage dealt to zero
;meant for fixing counter glitches
ZeroLastDamage:
    push af
    push hl
    ld a,0
    ld hl,W_DAMAGE
    ld [hli],a
    ld [hl],a
    pop hl
    pop af
    ret

TrappingEffect:
    ld hl,wUnusedC000
    set 3,[hl]
    ld hl,W_PLAYERBATTSTATUS1 ; $d062
    ld de,$d06a
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.done
    ld hl,wUnusedC000
    res 3,[hl]
    ld hl,W_ENEMYBATTSTATUS1 ; $d067
    ld de,$d06f
.done
    bit 5,[hl]
    ret nz
    push hl
    push bc
    push de
    call AIGetTypeEffectiveness
    pop de
    pop bc
    pop hl
    ld a,[$d11e]
    and a
    ret z
    ;call ClearHyperBeam ; since this effect is called before testing whether the move will hit,
                         ; the target won't need to recharge even if the trapping move missed
                         ; joenote - will do this later under ApplyAttackToEnemy/Player functions
    set 5,[hl]
    call GenRandomInBattle
    and $3
    cp $2
    jr c,.setTrappingCounter
    call GenRandomInBattle
    and $3
.setTrappingCounter
    inc a
    ld [de],a
    ret

LoadEnemyMonData_GetAlternateMonHeader:
    BANKSWITCH LoadEnemyMonData_GetAlternateMonHeader_
    jp GetMonHeader

; some tests that need to pass for a move to hit
MoveHitTest:
    ld hl,W_ENEMYBATTSTATUS1
    ld de,W_PLAYERMOVEEFFECT
    ld bc,W_ENEMYMONSTATUS
    ld a,[H_WHOSETURN]
    and a
    jr z,.done
; enemy's turn
    ld hl,W_PLAYERBATTSTATUS1
    ld de,W_ENEMYMOVEEFFECT
    ld bc,W_PLAYERMONSTATUS
.done
    dec de ; W_PLAYERMOVENUM / W_ENEMYMOVENUM
    ld a,[de]
    inc de
    cp SEISMIC_TOSS
    jr nz,.NotSeismicToss
    push hl
    push bc
    ld hl,W_PLAYERMONTYPES-W_PLAYERMONSTATUS
    add hl,bc
    ld b,4
.LoopTypesToFindGhost
    ld a,[hli]
    cp GHOST
    jr z,.GhostFound
    dec b
    jr nz,.LoopTypesToFindGhost
    inc b ; rzf
.GhostFound
    pop bc
    pop hl
    jr z,.moveMissed2
.NotSeismicToss
    ld a,[de]
    cp JUMP_KICK_EFFECT
    jr nz,.dreamEaterCheck
    push hl
    ld hl,W_DAMAGE
    ld a,[hli]
    or [hl]
    pop hl
    jr z,.moveMissed2
.dreamEaterCheck
    ld a,[de]
    cp DREAM_EATER_EFFECT
    jr nz,.swiftCheck
    ld a,[bc]
    and a,$07 ; is the target pokemon sleeping?
    jr z,.moveMissed2
.swiftCheck
    ld a,[de]
    cp SWIFT_EFFECT
    ret z ; Swift never misses (interestingly,Azure Heights lists this is a myth,but it appears to be true)
    call CheckTargetSubstitute ; substitute check (note that this overwrites a)
    jr z,.checkForDigOrFlyStatus
    ld a,[de]
    cp DRAIN_HP_EFFECT
    jr z,.moveMissed2
    cp DREAM_EATER_EFFECT
    jr z,.moveMissed2
    cp LEECH_SEED_EFFECT
    jr z,.moveMissed2
.checkForDigOrFlyStatus
    bit INVULNERABLE,[hl]
    jr z,.NotDigOrFly
    inc hl
    bit USING_FLY,[hl]
    dec hl
    jr z,.Dig
.Fly
    push hl
    ld hl,DontMissFlyMoves
    call CheckFlyDigDontMissMove
    pop hl
    jr c,.NotDigOrFly
    jr .moveMissed2
.Dig
    push hl
    ld hl,DontMissDigMoves
    call CheckFlyDigDontMissMove
    pop hl
    jr c,.NotDigOrFly
    jr .moveMissed2
.NotDigOrFly
    ld a,[H_WHOSETURN]
    and a
    jr nz,.enemyTurn
.playerTurn
; this checks if the move effect is disallowed by mist
    ld a,[W_PLAYERMOVEEFFECT]
    cp ATTACK_DOWN1_EFFECT
    jr c,.skipEnemyMistCheck
    cp HAZE_EFFECT+1
    jr c,.enemyMistCheck
    cp ATTACK_DOWN2_EFFECT
    jr c,.skipEnemyMistCheck
    cp REFLECT_EFFECT+1
    jr nc,.skipEnemyMistCheck
.enemyMistCheck
; if move effect is from $12 to $19 inclusive or $3a to $41 inclusive
; i.e. the following moves
; GROWL,TAIL WHIP,LEER,STRING SHOT,SAND-ATTACK,SMOKESCREEN,KINESIS,
; FLASH,CONVERSION,HAZE*,SCREECH,LIGHT SCREEN*,REFLECT*
; the moves that are marked with an asterisk are not affected since this
; function is not called when those moves are used
; XXX are there are any others like those three?
    ld a,[W_ENEMYBATTSTATUS2]
    bit 1,a ; PROTECTED_BY_MIST
    jr nz,.moveMissed
.skipEnemyMistCheck
    ld a,[W_PLAYERBATTSTATUS2]
    bit 0,a ; USING_X_ACCURACY ; is the player using X Accuracy?
    jr z,.calcHitChance
    ; if so, always hit regardless of accuracy/evasion
.player_ohko_xacc    ;joenote - player ohko moves now ignore x accuracy
    ; this section is entered if the player is using x accuracy
    ld a,[W_PLAYERMOVEEFFECT] ; load the move effect
    cp OHKO_EFFECT            ; check if it's an ohko move
    ret nz                    ; if not, the x accuracy skips hit chance
    jr .calcHitChance         ; else do normal accuracy checks
.moveMissed2
    jr .moveMissed
.enemyTurn
    ld a,[W_ENEMYMOVEEFFECT]
    cp ATTACK_DOWN1_EFFECT
    jr c,.skipPlayerMistCheck
    cp HAZE_EFFECT+1
    jr c,.playerMistCheck
    cp ATTACK_DOWN2_EFFECT
    jr c,.skipPlayerMistCheck
    cp REFLECT_EFFECT+1
    jr c,.playerMistCheck
    jr .skipPlayerMistCheck
.playerMistCheck
; similar to enemy mist check
    ld a,[W_PLAYERBATTSTATUS2]
    bit 1,a ; PROTECTED_BY_MIST
    jr nz,.moveMissed
.skipPlayerMistCheck
    ld a,[W_ENEMYBATTSTATUS2]
    bit 0,a ; USING_X_ACCURACY ; is the enemy using X Accuracy?
    jr z,.calcHitChance
    ; if so, always hit regardless of accuracy/evasion
.enemy_ohko_xacc    ;joenote - enemy ohko moves now ignore x accuracy
    ; this section is entered if the enemy is using x accuracy
    ld a,[W_ENEMYMOVEEFFECT] ; load the move effect
    cp OHKO_EFFECT           ; check if it's an ohko move
    ret nz                   ; if not, the x accuracy skips hit chance
    ;jr .calcHitChance       ; else do normal accuracy checks
.calcHitChance
    call CalcHitChance ; scale the move accuracy according to attacker's accuracy and target's evasion
    ld a,[W_PLAYERMOVEACCURACY]
    ld b,a
    ld a,[H_WHOSETURN]
    and a
    jr z,.doAccuracyCheck
    ld a,[W_ENEMYMOVEACCURACY]
    ld b,a
.doAccuracyCheck
; if the random number generated is greater than or equal to the scaled accuracy,the move misses
; note that this means that even the highest accuracy is still just a 255/256 chance,not 100%
    call GenRandomInBattle ; random number
    cp b
    ret c
.moveMissed
    ld hl,W_DAMAGE
    push de
    ld de,wBackupDamage
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[hld]
    ld [de],a
    pop de
    xor a ; zero the damage
    ld [hli],a
    ld [hl],a
    inc a
    ld [W_MOVEMISSED],a
    ld a,[H_WHOSETURN]
    and a
    jr z,.playerTurn2
.enemyTurn2
    ld hl,W_ENEMYBATTSTATUS1
    jr .end
.playerTurn2
    ld hl,W_PLAYERBATTSTATUS1
.end
    res 5,[hl] ; end multi-turn attack e.g. wrap
    ret

; values for player turn
CalcHitChance:
    ld hl,W_PLAYERMOVEACCURACY
    ld a,[H_WHOSETURN]
    and a
    ld a,[wPlayerMonAccuracyMod]
    ld b,a
    ld a,[wEnemyMonEvasionMod]
    ld c,a
    jr z,.next
; values for enemy turn
    ld hl,W_ENEMYMOVEACCURACY
    ld a,[wEnemyMonAccuracyMod]
    ld b,a
    ld a,[wPlayerMonEvasionMod]
    ld c,a
.next
    ld a,$0e
    sub c
    ld c,a ; c = 14 - EVASIONMOD (this "reflects" the value over 7,so that an increase in the target's evasion decreases the hit chance instead of increasing the hit chance)
; zero the high bytes of the multiplicand
    xor a
    ld [H_MULTIPLICAND],a
    ld [H_MULTIPLICAND + 1],a
    ld a,[hl]
    ld [H_MULTIPLICAND + 2],a ; set multiplicand to move accuracy
    push hl
    ld d,$02 ; loop has two iterations
; loop to do the calculations,the first iteration multiplies by the accuracy ratio and the second iteration multiplies by the evasion ratio
.loop
    push bc
    ld hl,StatModifierRatiosAccuracyEvasion  ; stat modifier ratios (ACR/EVA)
    dec b
    sla b
    ld c,b
    ld b,$00
    add hl,bc ; hl = address of stat modifier ratio
    pop bc
    ld a,[hli]
    ld [H_MULTIPLIER],a ; set multiplier to the numerator of the ratio
    call Multiply
    ld a,[hl]
    ld [H_DIVISOR],a ; set divisor to the the denominator of the ratio (the dividend is the product of the previous multiplication)
    ld b,$04 ; number of bytes in the dividend
    call Divide
    ld a,[H_QUOTIENT + 3]
    ld b,a
    ld a,[H_QUOTIENT + 2]
    or b
    jp nz,.nextCalculation
; make sure the result is always at least one
    ld [H_QUOTIENT + 2],a
    ld a,$01
    ld [H_QUOTIENT + 3],a
.nextCalculation
    ld b,c
    dec d
    jr nz,.loop
    ld a,[H_QUOTIENT + 2]
    and a ; is the calculated hit chance over 0xFF?
    ld a,[H_QUOTIENT + 3]
    jr z,.storeAccuracy
; if calculated hit chance over 0xFF
    ld a,$ff ; set the hit chance to 0xFF
.storeAccuracy
    pop hl
    ld [hl],a ; store the hit chance in the move accuracy variable
    ret

RandomizeDamage:
    ld hl,W_DAMAGE ; $d0d7
    ld a,[hli]
    and a
    jr nz,.asm_3e692
    ld a,[hl]
    cp $2
    ret c
.asm_3e692
    xor a
    ld [H_NUMTOPRINT],a ; $FF00+$96 (aliases: H_MULTIPLICAND)
    dec hl
    ld a,[hli]
    ld [$FF00+$97],a
    ld a,[hl]
    ld [$FF00+$98],a
.asm_3e69c
    call GenRandomInBattle
    rrca
    cp $d9
    jr c,.asm_3e69c
    ld [H_REMAINDER],a ; $FF00+$99 (aliases: H_DIVISOR,H_MULTIPLIER,H_POWEROFTEN)
    call Multiply
    ld a,$ff
    ld [H_REMAINDER],a ; $FF00+$99 (aliases: H_DIVISOR,H_MULTIPLIER,H_POWEROFTEN)
    ld b,$4
    call Divide
    ld a,[$FF00+$97]
    ld hl,W_DAMAGE ; $d0d7
    ld [hli],a
    ld a,[$FF00+$98]
    ld [hl],a
    ret

; ──────────────────────────────────────────
; ExecuteEnemyMove
; ──────────────────────────────────────────

ExecuteEnemyMove:
    ld a,[wEnemySelectedMove] ; $ccdd
    inc a
    jp z,ExecuteEnemyMoveDone
    call PrintGhostText
    jp z,ExecuteEnemyMoveDone
    ld a,[W_ISLINKBATTLE] ; $d12b
    cp $4
    jr nz,.executeEnemyMove
    ld b,$1
    ld a,[$cc3e] ; SerialExchangeNybbleReceiveData
    cp $e ; LINKBATTLE_STRUGGLE
    jr z,.executeEnemyMove
    cp $4
    ret nc
.executeEnemyMove
    ld hl,$ccd5 ; AILayer2Encouragement
    inc [hl]
    xor a
    ld [W_MOVEMISSED],a ; $d05f
    ld [$ccf4],a ; MoveDidntMiss
    ld a,10
    ld [$d05b],a ; DamageMultipliers
    call CheckEnemyStatusConditions
    jr nz,.enemyHasNoSpecialConditions
    jp hl
.enemyHasNoSpecialConditions
    xor a        ; Reset
    ld [$d06f],a ; EnemyNumAttacksLeft
    ld hl,W_ENEMYBATTSTATUS1 ; $d067
    bit 4,[hl] ; is the enemy charging up for attack?
    jr nz,EnemyCanExecuteChargingMove
    call GetCurrentMove

CheckIfEnemyNeedsToChargeUp:
    ld a,[W_ENEMYMOVEEFFECT] ; $cfcd
    cp CHARGE_EFFECT
    jp z,JumpMoveEffect
    cp FLY_EFFECT
    jp z,JumpMoveEffect
    jr EnemyCanExecuteMove

EnemyCanExecuteChargingMove:
    ld hl,W_ENEMYBATTSTATUS1 ; $d067
    res CHARGING_UP,[hl] ; no longer charging up for attack
    res INVULNERABLE,[hl] ; no longer invulnerable to typical attacks
    inc hl
    res USING_FLY,[hl]
    dec hl
    ld a,[W_ENEMYMOVENUM] ; $cfcc
    ld [$d0b5],a
    ld a,BANK(MoveNames)
    ld [$d0b7],a
    ld a,MOVE_NAME
    ld [W_LISTTYPE],a
    call GetName
    ld de,$cd6d
    call CopyStringToCF4B

EnemyCanExecuteMove:
    xor a
    ld [$cced],a
    call DecrementEnemyPP ; call PrintMonName1Text
    ld a,[W_ENEMYMOVEEFFECT] ; $cfcd
    ld hl,EffectsArray1
    call RunMoveEffectInList
    ret c
    ld a,[W_ENEMYMOVEEFFECT] ; $cfcd
    ld hl,EffectsArray5B
    call RunMoveEffectInList
    ld a,[$d078] ; EscapedFromBattle
    and a
    ret nz ; return if whirlwind success
    xor a
    ld [W_MOVEMISSED],a

EnemyCalcMoveDamage:
    call SwapPlayerAndEnemyLevels
    ld a,[W_ENEMYMOVEEFFECT] ; $cfcd
    ld hl,EffectsArray2 ; $4011
    ld de,$1
    call IsInArray
    jr c,.EnemyMoveHitTest
    call CriticalHitTest
    call HandleCounterMove
    jr z,handleIfEnemyMoveMissed
    call SwapPlayerAndEnemyLevels
    call CalculateDamageAfterEnemyAttack
    call SwapPlayerAndEnemyLevels
    call MoreCalculateDamage
    jp z,EnemyCheckIfFlyOrChargeEffect
    call AdjustDamageForMoveType
    call RandomizeDamage

.EnemyMoveHitTest:
    call MoveHitTest

handleIfEnemyMoveMissed:
    ld a,[W_MOVEMISSED] ; $d05f
    and a
    jr z,.moveDidNotMiss
    jr handleExplosionMiss
.moveDidNotMiss
    call SwapPlayerAndEnemyLevels
    ; ft

GetEnemyAnimationType:
    ld a,[W_ENEMYMOVEEFFECT] ; $cfcd
    and a
    ld a,1
    jr z,playEnemyMoveAnimation
    ld a,2
    jr playEnemyMoveAnimation

handleExplosionMiss:
    call SwapPlayerAndEnemyLevels
    xor a

playEnemyMoveAnimation:
    push af
    ld a,[W_ENEMYBATTSTATUS2] ; $d068
    bit 4,a ; does mon have a substitute?
    BANKSWITCH_NZ HideSubstituteShowMonAnim
    pop af
    ld [$CC5B],a ; AnimationType
    ld a,[W_ENEMYMOVENUM] ; $cfcc
    call PlayMoveAnimation_WithException
    call HandleExplodingAnimation
    call DrawEnemyHUDAndHPBar
    ld a,[W_ENEMYBATTSTATUS2] ; $d068
    bit 4,a ; does mon have a substitute?
    BANKSWITCH_NZ ReshowSubstituteAnim
    jr EnemyCheckIfMirrorMoveEffect

EnemyCheckIfFlyOrChargeEffect:
    call SwapPlayerAndEnemyLevels
    ld c,$1e
    call DelayFrames
    ld a,[W_ENEMYMOVEEFFECT] ; $cfcd
    cp FLY_EFFECT
    jr z,.playAnim
    cp CHARGE_EFFECT
    jr z,.playAnim
    jr EnemyCheckIfMirrorMoveEffect
.playAnim
    xor a
    ld [$CC5B],a ; AnimationType
    ld a,$a7 ; STATUS_AFFECTED_ANIM
    call PlayMoveAnimation

EnemyCheckIfMirrorMoveEffect:
    ld a,[W_ENEMYMOVEEFFECT] ; $cfcd
    cp MIRROR_MOVE_EFFECT
    jr nz,.notMirrorMoveEffect
    call MirrorMoveCopyMove
    jp z,ExecuteEnemyMoveDone
    jp CheckIfEnemyNeedsToChargeUp
.notMirrorMoveEffect
    cp METRONOME_EFFECT
    jr nz,.notMetronomeEffect
    call MetronomePickMove
    jp CheckIfEnemyNeedsToChargeUp
.notMetronomeEffect
    ld a,[W_ENEMYMOVEEFFECT] ; $cfcd
    ld hl,EffectsArray3
    call RunMoveEffectInList
    ret c
    ld a,[W_MOVEMISSED] ; $d05f
    and a
    jr z,.moveDidNotMiss
    call PrintMoveFailureText
    ld a,[W_ENEMYMOVEEFFECT] ; $cfcd
    ld hl,EffectsArray6
    ld de,1
    call IsInArray
    jr c,.notDone
    jr ExecuteEnemyMoveDone
.moveDidNotMiss
    call ApplyAttackToPlayerPokemon
    call PrintCriticalOHKOText
    BANKSWITCH DisplayEffectiveness
    call EnemyMoveDidntMissAndPlayerBideAccum
.notDone
    ld a,[W_ENEMYMOVEEFFECT] ; $cfcd
    ld hl,EffectsArray4
    call RunMoveEffectInList
    ld hl,W_PLAYERMONCURHP ; $d015
    ld a,[hli]
    ld b,[hl]
    or b
    ret z
    call HandleBuildingRage
    ld hl,W_ENEMYBATTSTATUS1 ; $d067
    bit 2,[hl] ; ATTACKING_MULTIPLE_TIMES ; is mon hitting multiple times? (example: double kick)
    jr z,.notMultiHitMove
    push hl
    ld hl,$d06f ; EnemyNumAttacksLeft
    dec [hl]
    pop hl
    jp nz,GetEnemyAnimationType
    res 2,[hl] ; ATTACKING_MULTIPLE_TIMES
    ld hl,HitXTimesText
    call PrintText
    xor a
    ld [$cd05],a
.notMultiHitMove
    ld a,[W_ENEMYMOVEEFFECT] ; $cfcd
    and a
    jr z,ExecuteEnemyMoveDone
    ld hl,EffectsArray5
    call RunMoveEffectNotInList
    ; ft

ExecuteEnemyMoveDone:
    ld b,$1
    ret

HitXTimesText:
    TX_FAR _HitXTimesText
    db "@"

; ──────────────────────────────────────────

QuarterSpeedDueToParalysisOrHalveAttackDueToBurn_Down:
    ld hl,QuarterSpeedDueToParalysisOrHalveAttackDueToBurn_Down_
QuarterSpeedDueToParalysisOrHalveAttackDueToBurn_Up:
    ld b,BANK(QuarterSpeedDueToParalysisOrHalveAttackDueToBurn_Down_)
    jp Bankswitch

; ──────────────────────────────────────────────────────────────────────
; CheckEnemyStatusConditions
; ──────────────────────────────────────────────────────────────────────

CheckEnemyStatusConditions:
    ld hl,W_ENEMYMONSTATUS

.FrozenCheck
    bit FRZ_Bit,[hl]
    jr z,.SleepCheck
    ld hl,FrozenText
    jr .SleepFrozenDone

.SleepCheck
    ld a,[hl]
    and SLP
    ld a,[hl]
    jr z,.HeldInPlaceCheck

    dec a ; decrement sleep count
    ld [hl],a
    and SLP
    jr z,.WakeUp

    xor a
    ld [$CC5B],a
    ld a,SLP_ANIM
    call PlayMoveAnimation
    ld hl,FastAsleepText

.SleepFrozenDone
