    call .DrawHudAndPrintText ; call PrintText
    ; ft

.HeldInPlaceCheck
    ld a,[W_PLAYERBATTSTATUS1] ; $d062
    bit 5,a
    jp z,.FlinchedCheck
    ld hl,CantMoveText ; $5a83
    call PrintText
    ; ft

.ExecuteEnemyMoveDone
    ld hl,ExecuteEnemyMoveDone
    jp .Func_3eab8

.FlinchedCheck
    ld hl,W_ENEMYBATTSTATUS1 ; $d067
    bit 3,[hl]
    jr z,.HyperBeamCheck
    res 3,[hl]
    ld hl,FlinchedText ; $5a51
    call PrintText
    jr .ExecuteEnemyMoveDone

.HyperBeamCheck
    ld hl,W_ENEMYBATTSTATUS2 ; $d068
    bit 5,[hl]
    jr z,.next
    res 5,[hl]
    ld hl,MustRechargeText ; $5a56
    call PrintText
    jr .ExecuteEnemyMoveDone
.next
    ld hl,W_ENEMYDISABLEDMOVE ; $d072
    ld a,[hl]
    and a
    jr z,.next2
    dec a
    ld [hl],a
    and $f
    jr nz,.next2
    ld [hl],a
    ld [$ccef],a
    ld hl,DisabledNoMoreText ; $5a5b
    call PrintText
.next2
    ld a,[W_ENEMYBATTSTATUS1] ; $d067
    add a
    jp nc,.next3
    ld hl,$d070
    dec [hl]
    jr nz,.next4
    ld hl,W_ENEMYBATTSTATUS1 ; $d067
    res 7,[hl]
    ld hl,ConfusedNoMoreText
    call .DrawHudAndPrintText ; call PrintText
    jp .next3
.next4
    ld hl,IsConfusedText ; $5a60
    call PrintText
    xor a
    ld [$cc5b],a
    ld a,$bf
    call PlayMoveAnimation
    call GenRandomInBattle
    cp $80
    jr c,.next3
    ld hl,W_ENEMYBATTSTATUS1 ; $d067
    ld a,[hl]
    and $80
    ld [hl],a
    call EnemyHurtItself
    jr .MonHurtItselfOrFullyParalysed
.next3
    ld a,[$ccef]
    and a
    jr z,.ParalysisCheck
    ld hl,wEnemySelectedMove ; $ccdd
    cp [hl]
    jr nz,.ParalysisCheck
    call Func_3da88
    jp .ExecuteEnemyMoveDone
.ParalysisCheck
    ld hl,W_ENEMYMONSTATUS ; $cfe9
    bit 6,[hl]
    jr z,.next7
    call GenRandomInBattle
    cp $3f
    jr nc,.next7
    ld hl,FullyParalyzedText ; $5a4c
    call PrintText
.MonHurtItselfOrFullyParalysed
    ld hl,W_ENEMYBATTSTATUS1 ; $d067
    ld a,[hl]
    and %10001100 ; Reset also invulnerablility
    ld [hl],a
    inc hl
    res USING_FLY,[hl]
    dec hl
    ld a,[W_ENEMYMOVEEFFECT] ; $cfcd
    cp FLY_EFFECT
    jr z,.next8
