    ld hl,$d06f
    dec [hl]
    jp nz,.ExecuteEnemyMoveDone
    ld hl,W_ENEMYBATTSTATUS1 ; $d067
    res 0,[hl]
    ld hl,UnleashedEnergyText ; $5a74
    call PrintText
    ld a,$1
    ld [W_ENEMYMOVEPOWER],a ; $cfce
    ld hl,$cd06
    ld a,[hld]
