SleepEffect:
    ld de,W_ENEMYMONSTATUS ; $cfe9
    ld bc,W_ENEMYBATTSTATUS2 ; $d068
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.done
    ld de,W_PLAYERMONSTATUS ; $d018
    ld bc,W_PLAYERBATTSTATUS2 ; $d063
.done
    call MoveHitTestPlus
    jr nz,.attackMissed
    ld a,[de]
    and SLP
    jr nz,.alreadyAsleep
    ld a,[bc] ; target no longer needs to recharge (hyper beam)
    res NEEDS_TO_RECHARGE,a   ; ...
    ld [bc],a ; ...
    ld a,[de]
    ld b,a ; Current Status
.setSleepCounter
    call GenRandomInBattle
    and SLP
    jr z,.setSleepCounter
    or b ; Apply Sleep Mask to Current Status
    ld [de],a
    ld hl,.FellAsleepText ; $7245
    call PlayCurrentMoveAnimation2
    jp DrawHudAndPrintText
.attackMissed
    call PlayCurrentMoveAnimation
    jp PrintMoveFailureText
.alreadyAsleep
    call PlayCurrentMoveAnimation
    jp PrintAlreadyAsleepText
.FellAsleepText
    TX_FAR _FellAsleepText
    db "@"

PoisonEffect:
    ld hl,W_ENEMYMONSTATUS ; $cfe9
    ld de,W_PLAYERMOVEEFFECT ; $cfd3
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.done
    ld hl,W_PLAYERMONSTATUS ; $d018
    ld de,W_ENEMYMOVEEFFECT ; $cfcd
.done
    ld a,[de]
    cp POISON_EFFECT
    jr nz,.skipMoveHitTest
    call MoveHitTestPlus
    jr nz,.attackMissed
.skipMoveHitTest
    call CheckTargetSubstitute
    jr nz,.didntAffect ; can't poison a substitute target
    ld a,[hl]
    ld b,a
    bit PSN_Bit,a
    jr nz,.alreadyPoisoned ; miss if target is already statused
.retry
    push hl
    ld bc,W_PLAYERMONTYPES-W_PLAYERMONSTATUS
    add hl,bc
    call CheckPoisonableMon
    pop hl
    jr z,.doesntAffect
    ld a,[de]
    cp POISON_SIDE_EFFECT1
    ld b,$34 ; 20% chance of poisoning
    jr z,.sideEffectTest
    cp POISON_SIDE_EFFECT2
    ld b,$67 ; 40% chance of poisoning
    jr nz,.inflictPoison
.sideEffectTest
    call CheckZeroDamageOrSideEffectRandom ; call GenRandomInBattle
    cp b
    ret nc
.inflictPoison
    set PSN_Bit,[hl] ; mon is now poisoned
    push de
    dec de
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    ld b,$c7 ; ANIM_C7
    ld hl,W_PLAYERBATTSTATUS3 ; $d064
    ld a,[de]
    ld de,W_PLAYERTOXICCOUNTER ; $d06c
    jr nz,.ok
    ld b,$a9 ; ANIM_A9
    ld hl,W_ENEMYBATTSTATUS3 ; $d069
    ld de,W_ENEMYTOXICCOUNTER ; $d071
.ok
    cp TOXIC
    jr nz,.normalPoison ; done if move is not Toxic
    set BADLY_POISONED,[hl] ; else set Toxic battstatus
    xor a
    ld [de],a
    ld hl,.BadlyPoisonedText ; $72e4
    jr .continue
.normalPoison
    ld hl,.PoisonedText ; $72df
.continue
    pop de
    ld a,[de]
    cp POISON_EFFECT
    jr z,.regularPoisonEffect
    ld a,b
    call PlayBattleAnimation2
    jp DrawHudAndPrintText
.regularPoisonEffect
    call PlayCurrentMoveAnimation2
    jp DrawHudAndPrintText
.attackMissed
    ld hl,PrintMoveFailureText
    jr .checkEnd
.doesntAffect
    ld hl,PrintDoesntAffectMonText
    jr .checkEnd
.didntAffect
    ld hl,PrintDidntAffectText
    jr .checkEnd
.alreadyPoisoned
    dec de
    ld a,[de]
    inc de
    cp TOXIC
    jr nz,.alreadyPoisoned2
    push hl
    ld a,[H_WHOSETURN]
    and a
    ld hl,W_PLAYERBATTSTATUS3
    jr nz,.ok2
    ld hl,W_ENEMYBATTSTATUS3
.ok2
    bit BADLY_POISONED,[hl]
    pop hl
    jp z,.retry
.alreadyPoisoned2
    ld hl,PrintAlreadyPoisonedText
    ; ft
.checkEnd
    ld a,[de]
    cp POISON_EFFECT
    ret nz
    call PlayCurrentMoveAnimation
    jp hl
.PoisonedText
    TX_FAR _PoisonedText
    db "@"
.BadlyPoisonedText
    TX_FAR _BadlyPoisonedText
    db "@"

DrainHPEffect:
    BANKSWITCH_JUMP DrainHPEffect_

FreezeBurnParalyzeEffect:
    xor a
    ld [$cc5b],a
    call CheckTargetSubstitute         ;test bit 4 of d063/d068 flags [target has substitute flag]
    ret nz             ;return if they have a substitute,can't effect them
    ld a,[H_WHOSETURN]
    and a
    jp nz,.OpponentAttacker

.PlayerAttacker
    ld a,[W_ENEMYMONSTATUS]
    call CheckDefrost
    call GetSideEffectType_Player ; ld a,[W_PLAYERMOVETYPE]
    ld hl,W_ENEMYMONTYPES
    call .AttackerTypeMatchOneOfDefenderTypesPlusException
    ret z
    ld a,[W_PLAYERMOVEEFFECT]
    call MoveEffectToPercentage
    push af     ;push effect...
    call CheckZeroDamageOrSideEffectRandom ; call GenRandomInBattle  ;get random 8bit value for probability test
    cp b        ;success?
    pop bc      ;...pop effect into B
    ret nc      ;do nothing if random value is >= 1A or 4D [no status applied]
    ld hl,W_ENEMYMONSTATUS
    ld a,b     ;what type of effect is this?
    cp BURN_SIDE_EFFECT1
    jr z,.burn1
    cp FREEZE_SIDE_EFFECT
    jr z,.freeze1
.par1
    bit PAR_Bit,[hl]
    set PAR_Bit,[hl]
    ret nz
    call QuarterSpeedDueToParalysis  ;quarter speed of affected monster
    call PlayA9BattleAnimation
    jp PrintMayNotAttackText    ;print paralysis text
.burn1
    bit BRN_Bit,[hl]
    set BRN_Bit,[hl]
    ret nz
    call HalveAttackDueToBurn
    call PlayA9BattleAnimation
    ld hl,.UnnamedText_3f3d8
    jr .DrawHudAndPrintText
.freeze1
    bit FRZ_Bit,[hl]
    set FRZ_Bit,[hl]
    ret nz
    call ClearHyperBeam  ;resets bit 5 of the D063/D068 flags
    ld a,[hl]
    and ~SLP & ~BRN ; Remove Sleep & Burn
    ld [hl],a
    call PlayA9BattleAnimation
    ld hl,.UnnamedText_3f3dd
    jr .DrawHudAndPrintText

.OpponentAttacker
    ld a,[W_PLAYERMONSTATUS]
    call CheckDefrost
    call GetSideEffectType_Enemy ; ld a,[W_ENEMYMOVETYPE]
    ld hl,W_PLAYERMONTYPES
    call .AttackerTypeMatchOneOfDefenderTypesPlusException
    ret z
    ld a,[W_ENEMYMOVEEFFECT]
    call MoveEffectToPercentage
    push af
    call CheckZeroDamageOrSideEffectRandom ; call GenRandomInBattle
    cp b
    pop bc
    ret nc
    ld hl,W_PLAYERMONSTATUS
    ld a,b
    cp BURN_SIDE_EFFECT1
    jr z,.burn2
    cp FREEZE_SIDE_EFFECT
    jr z,.freeze2
.par2
    bit PAR_Bit,[hl]
    set PAR_Bit,[hl]
    ret nz
    call QuarterSpeedDueToParalysis
    call PlayC7BattleAnimation
    jp PrintMayNotAttackText
.burn2
    bit BRN_Bit,[hl]
    set BRN_Bit,[hl]
    ret nz
    call HalveAttackDueToBurn
    call PlayC7BattleAnimation
    ld hl,.UnnamedText_3f3d8
    jr .DrawHudAndPrintText
.freeze2
    bit FRZ_Bit,[hl]
    set FRZ_Bit,[hl]
    ret nz
    call ClearHyperBeam  ;resets bit 5 of the D063/D068 flags
    ld a,[hl]
    and ~SLP & ~BRN ; Remove Sleep & Burn
    ld [hl],a
    call PlayC7BattleAnimation
    ld hl,.UnnamedText_3f3dd
    jr .DrawHudAndPrintText

.UnnamedText_3f3d8
    TX_FAR _UnnamedText_3f3d8
    db "@"
.UnnamedText_3f3dd
    TX_FAR _UnnamedText_3f3dd
    db "@"

.DrawHudAndPrintText
    jp DrawHudAndPrintText

.AttackerTypeMatchOneOfDefenderTypesPlusException
    push hl
    call .Loop4MovesInHLAndCompareWithA
    pop hl
    ret z
    cp THUNDER
    ret nz
    ld a,ROCK
    ; ft
.Loop4MovesInHLAndCompareWithA
    ld b,4
.loop
    cp [hl]
    ret z ; return if they match
          ; can't freeze an ice type
          ; can't paralyze a rock type
          ; etc....
    inc hl
    dec b
    jr nz,.loop
    inc b ; rzf
    ret

; ──────────────────────────────────────────────────────────────────────
; StatModifierUpEffect
; ──────────────────────────────────────────────────────────────────────

StatModifierUpEffect:
    ld hl,wPlayerMonStatMods ; $cd1a
    ld de,W_PLAYERMOVEEFFECT ; $cfd3
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.done
    ld hl,wEnemyMonStatMods ; $cd2e
    ld de,W_ENEMYMOVEEFFECT ; $cfcd
.done
    ld a,[de]
    sub ATTACK_UP1_EFFECT    ;normalize the effects from 0 to 5 to get an offset
    cp 6 ; regular "UP Effect" base from 0 to 5
    jr c,.statupcheck
    sub ATTACK_UP2_EFFECT - ATTACK_UP1_EFFECT ; map +2 effects to corresponding +1 effect
    cp 6 ; regular "UP Effect" base from 0 to 5
    jr c,.statupcheck
    sub ATTACK_UP3_EFFECT - ATTACK_UP2_EFFECT ; map +3 effects to corresponding +1 effect
.statupcheck
    ld c,a
    ld b,$0
    inc a              ; joenote - backup the address offset for the stat mod
    ld [wBackupStatRaisedLoweredType],a ; ...
    add hl,bc
    ld b,[hl]
    inc b
    ld a,$d
    cp b
    jp c,.NothingHappened
    ; Check up2
    ld a,[de]
    cp EVASION_UP1_EFFECT + 1 ; is it a +2 effect?
    jr c,.ok3
    inc b
    ld a,$d
    cp b
    jr nc,.ok2
    ld b,a
    jr .ok3
.ok2
    ; Check up3
    ld a,[de]
    cp EVASION_UP2_EFFECT + 1 ; is it a +3 effect?
    jr c,.ok3
    inc b
    ld a,$d
    cp b
    jr nc,.ok3
    ld b,a
.ok3
    ld [hl],b
    ld a,c
    cp $4
    jr nc,.UpdateStatDone ; jump if mod affected is evasion/accuracy
    push hl
    ld hl,W_PLAYERMONATK+1
    ld de,$cd12 ; PlayerMonUnmodifiedAttack
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.pointToStats
    ld hl,W_ENEMYMONATTACK+1
    ld de,$cd26 ; EnemyMonUnmodifiedAttack
.pointToStats
    push bc
    sla c
    ld b,$0
    add hl,bc ; hl = modified stat
    ld a,c
    add e
    ld e,a
    jr nc,.checkIf999
    inc d ; de = unmodified (original) stat
.checkIf999
    pop bc
    ; check if stat is already 999
    ld a,[hld]
    sub $e7
    jr nz,.recalculateStat
    ld a,[hl]
    sbc $3
    jp z,RestoreOriginalStatModifier
.recalculateStat ; recalculate affected stat
                 ; paralysis and burn penalties, as well as badge boosts are ignored
    push hl
    push bc
    ld hl,StatModifierRatios ; $76cb
    dec b
    sla b
    ld c,b
    ld b,$0
    add hl,bc
    pop bc
    xor a
    ld [H_NUMTOPRINT],a ; $FF00+$96 (aliases: H_MULTIPLICAND)
    ld a,[de]
    ld [$FF00+$97],a
    inc de
    ld a,[de]
    ld [$FF00+$98],a
    ld a,[hli]
    ld [H_REMAINDER],a ; $FF00+$99 (aliases: H_DIVISOR,H_MULTIPLIER,H_POWEROFTEN)
    call Multiply
    ld a,[hl]
    ld [H_REMAINDER],a ; $FF00+$99 (aliases: H_DIVISOR,H_MULTIPLIER,H_POWEROFTEN)
    ld b,$4
    call Divide
    pop hl
    ld a,[$FF00+$98]
    sub $e7
    ld a,[$FF00+$97]
    sbc $3
    jr c,.UpdateStat
    ld a,$3
    ld [$FF00+$97],a
    ld a,$e7
    ld [$FF00+$98],a
.UpdateStat
    ld a,[$FF00+$97]
    ld [hli],a
    ld a,[$FF00+$98]
    ld [hl],a
    pop hl
.UpdateStatDone
    ld b,c
    inc b
    call PrintStatText
    ld hl,W_PLAYERBATTSTATUS2 ; $d063
    ld de,W_PLAYERMOVENUM ; $cfd2
    ld bc,$ccf7
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.playerTurn
    ld hl,W_ENEMYBATTSTATUS2 ; $d068
    ld de,W_ENEMYMOVENUM ; $cfcc
    ld bc,$ccf3
.playerTurn
    ld a,[de]
    cp MINIMIZE
    jr nz,.notMinimize
    bit 4,[hl] ; HAS_SUBSTITUTE_UP
    push af
    push bc
    push de
    BANKSWITCH_NZ HideSubstituteShowMonAnim
    pop de
.notMinimize
    call PlayCurrentMoveAnimation_WithException
    ld a,[de]
    cp MINIMIZE
    jr nz,.applyBadgeBoostsAndStatusPenalties
    pop bc
    ld a,$1
    ld [bc],a
    pop af
    BANKSWITCH_NZ ReshowSubstituteAnim
.applyBadgeBoostsAndStatusPenalties
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    call z,ApplyBadgeStatBoosts
    ld hl,.MonsStatsRoseText
    call PrintText
    ld hl,QuarterSpeedDueToParalysisOrHalveAttackDueToBurn_Up_
    jp QuarterSpeedDueToParalysisOrHalveAttackDueToBurn_Up
.NothingHappened
    call PlayCurrentMoveAnimation_WithException
    jp PrintNothingHappenedText
.MonsStatsRoseText
    TX_FAR _MonsStatsRoseText
    db $08 ; asm
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    ld a,[W_PLAYERMOVEEFFECT] ; $cfd3
    jr z,.done1
    ld a,[W_ENEMYMOVEEFFECT] ; $cfcd
.done1
    cp EVASION_UP1_EFFECT + 1
    ld hl,.RoseText
    ret c
    cp EVASION_UP2_EFFECT + 1
    ld hl,.GreatlyText
    ret c
    ld hl,.EnormouslyText
    ret
.GreatlyText
    db $0a
    TX_FAR _GreatlyText
.RoseText
    TX_FAR _RoseText
    db "@"
.EnormouslyText
    db $0a
    TX_FAR _EnormouslyText
    TX_FAR _RoseText
    db "@"

; ──────────────────────────────────────────────────────────────────────

RestoreOriginalStatModifier:
    pop hl
    dec [hl]
    call PlayCurrentMoveAnimation_WithException
    ; ft

PrintNothingHappenedText:
    ld hl,NothingHappenedText ; $7b3e
    jp Delay50AndPrintText

; ──────────────────────────────────────────────────────────────────────
; StatModifierDownEffect
; ──────────────────────────────────────────────────────────────────────

StatModifierDownEffect:
    ld hl,wEnemyMonStatMods ; $cd2e
    ld de,W_PLAYERMOVEEFFECT ; $cfd3
    ld bc,W_ENEMYBATTSTATUS1 ; $d067
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.done
    ld hl,wPlayerMonStatMods ; $cd1a
    ld de,W_ENEMYMOVEEFFECT ; $cfcd
    ld bc,W_PLAYERBATTSTATUS1 ; $d062
.done
    ld a,[de]
    cp ATTACK_DOWN_SIDE1_EFFECT
    jr nc,.skipMoveHitTest
    call MoveHitTestPlus
    jr nz,.attackMissed
.skipMoveHitTest
    call CheckTargetSubstitute
    jr nz,.didntAffect
    ld a,[de]
    cp ATTACK_DOWN_SIDE1_EFFECT
    jr c,.nonSideEffect
    call CheckCustomSideEffect ; GenRandomInBattle
    call CompareCustomValue ; cp $55 ; 33%
    ret nc ; don't apply side effect
    ld a,[de]
    sub ATTACK_DOWN_SIDE1_EFFECT ; map each stat to 0-3
    cp EVASION_DOWN_SIDE1_EFFECT + $3 - ATTACK_DOWN_SIDE1_EFFECT ; covers all -1 effects
    jr c,.decrementStatMod
    sub ATTACK_DOWN_SIDE2_EFFECT - ATTACK_DOWN_SIDE1_EFFECT ; map -2 effects to corresponding -1 effect
    jr .decrementStatMod
.CantLowerAnymore_Pop
    pop de
    pop hl
    inc [hl]
.CantLowerAnymore
    ld hl,PrintNothingHappenedText
    jr .checkEnd
.attackMissed
    ld hl,PrintMoveFailureText
    jr .checkEnd
.didntAffect
    ld hl,PrintDidntAffectText
    ; ft
.checkEnd
    ld a,[de]
    cp ATTACK_DOWN_SIDE1_EFFECT
    ret nc
    call PlayCurrentMoveAnimation_WithException
    jp hl
.nonSideEffect
    ld a,[de]
    sub ATTACK_DOWN1_EFFECT
    cp EVASION_DOWN1_EFFECT + $3 - ATTACK_DOWN1_EFFECT ; covers all -1 effects
    jr c,.decrementStatMod
    sub ATTACK_DOWN2_EFFECT - ATTACK_DOWN1_EFFECT ; map -2 effects to corresponding -1 effect
.decrementStatMod
    ld c,a
    ld b,$0
    inc a              ; joenote - backup the address offset for the stat mod
    ld [wBackupStatRaisedLoweredType],a ; ...
    add hl,bc
    ld b,[hl]
    dec b ; dec corresponding stat mod
    jr z,.CantLowerAnymore
    ld a,[de]
    cp ATTACK_DOWN2_EFFECT - $16 ; $24
    jr c,.ok
    cp EVASION_DOWN2_EFFECT + $5 ; $44
    jr nc,.ok
    dec b ; stat down 2 effects only (dec mod again)
    jr nz,.ok
    inc b ; increment mod to 1 (-6) if it would become 0 (-7)
.ok
    ld [hl],b
    ld a,c
    cp $4
    jr nc,.UpdateLoweredStatDone ; jump for evasion/accuracy
    push hl
    push de
    ld hl,W_ENEMYMONATTACK+1
    ld de,$cd26 ; EnemyMonUnmodifiedAttack
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.pointToStat
    ld hl,W_PLAYERMONATK+1
    ld de,$cd12 ; PlayerMonUnmodifiedAttack
.pointToStat
    push bc
    sla c
    ld b,$0
    add hl,bc ; hl = modified stat
    ld a,c
    add e
    ld e,a
    jr nc,.noCarry
    inc d ; de = unmodified stat
.noCarry
    pop bc
    ld a,[hld]
    sub 1 ; can't lower stat below 1 (-6)
    jr nz,.recalculateStat
    ld a,[hl]
    and a
    jr z,.CantLowerAnymore_Pop
.recalculateStat
    push hl
    push bc
    ld hl,StatModifierRatios ; $76cb
    dec b
    sla b
    ld c,b
    ld b,$0
    add hl,bc
    pop bc
    xor a
    ld [H_NUMTOPRINT],a ; $FF00+$96 (aliases: H_MULTIPLICAND)
    ld a,[de]
    ld [$FF00+$97],a
    inc de
    ld a,[de]
    ld [$FF00+$98],a
    ld a,[hli]
    ld [H_REMAINDER],a ; $FF00+$99 (aliases: H_DIVISOR,H_MULTIPLIER,H_POWEROFTEN)
    call Multiply
    ld a,[hl]
    ld [H_REMAINDER],a ; $FF00+$99 (aliases: H_DIVISOR,H_MULTIPLIER,H_POWEROFTEN)
    ld b,$4
    call Divide
    pop hl
    ld a,[$FF00+$98]
    ld b,a
    ld a,[$FF00+$97]
    or b
    jr nz,.UpdateLoweredStat
    ld [$FF00+$97],a
    ld a,$1
    ld [$FF00+$98],a
.UpdateLoweredStat
    ld a,[$FF00+$97]
    ld [hli],a
    ld a,[$FF00+$98]
    ld [hl],a
    pop de
    pop hl
.UpdateLoweredStatDone
    ld b,c
    inc b
    push de
    call PrintStatText
    pop de
    ld a,[de]
    cp ATTACK_DOWN_SIDE1_EFFECT
    jr nc,.ApplyBadgeBoostsAndStatusPenalties
    call PlayCurrentMoveAnimation2_WithException
.ApplyBadgeBoostsAndStatusPenalties
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    call nz,ApplyBadgeStatBoosts
    ld hl,.MonsStatsFellText
    call PrintText
    jp QuarterSpeedDueToParalysisOrHalveAttackDueToBurn_Down
.MonsStatsFellText
    TX_FAR _MonsStatsFellText
    db $08 ; asm
    ld hl,.FellText
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    ld a,[W_PLAYERMOVEEFFECT] ; $cfd3
    jr z,.done2
    ld a,[W_ENEMYMOVEEFFECT] ; $cfcd
.done2
    cp BIDE_EFFECT
    ret c
    cp ATTACK_DOWN_SIDE1_EFFECT
    ret nc
    ld hl,.GreatlyFellText
    ret
.GreatlyFellText
    db $0a
    TX_FAR _GreatlyFellText
.FellText
    TX_FAR _FellText
    db "@"

