; Free

SECTION "PrintStatText",ROMX[$7688],BANK[$f]

PrintStatText: ; 3f688 (f:7688)
    ld hl,StatsTextStrings ; $769f
    ld c,"@"
.findStatName_outer
    dec b
    jr z,.foundStatName
.findStatName_inner
    ld a,[hli]
    cp c
    jr z,.findStatName_outer
    jr .findStatName_inner
.foundStatName
    ld de,$cf4b ; StringBuffer
    ld bc,$a
    jp CopyData

StatsTextStrings: ; 3f69f (f:769f)
    db "ATTACK@"
    db "DEFENSE@"
    db "SPEED@"
    db "SPECIAL@"
    db "ACCURACY@"
    db "EVADE@"

StatModifierRatios: ; 3f6cb (f:76cb)
; first byte is numerator,second byte is denominator
    db 025,100  ; 0.25
    db 028,100  ; 0.28
    db 033,100  ; 0.33
    db 040,100  ; 0.40
    db 050,100  ; 0.50
    db 066,100  ; 0.66
    db 001,001  ; 1.00
    db 015,010  ; 1.50
    db 002,001  ; 2.00
    db 025,010  ; 2.50
    db 003,001  ; 3.00
    db 035,010  ; 3.50
    db 004,001  ; 4.00

BideEffect: ; 3f6e5 (f:76e5)
    ld hl,W_PLAYERBATTSTATUS1
    ld de,W_NUMHITS
    ld bc,$d06a
    ld a,[H_WHOSETURN]
    and a
    jr z,.asm_3f6fc
    ld hl,W_ENEMYBATTSTATUS1
    ld de,$cd05
    ld bc,$d06f
.asm_3f6fc
    set 0,[hl]
    xor a
    ld [de],a
    inc de
    ld [de],a
    ld [W_PLAYERMOVEEFFECT],a
    ld [W_ENEMYMOVEEFFECT],a
    call GenRandomInBattle
    and $1
    inc a
    inc a
    ld [bc],a
    ld a,[H_WHOSETURN]
    add $ae
    jp PlayBattleAnimation2

ThrashPetalDanceEffect: ; 3f717 (f:7717)
    ld hl,W_PLAYERBATTSTATUS1 ; $d062
    ld de,$d06a
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.asm_3f728
    ld hl,W_ENEMYBATTSTATUS1 ; $d067
    ld de,$d06f
.asm_3f728
    set 1,[hl]
    call GenRandomInBattle
    and $1
    inc a
    inc a
    ld [de],a
    ld a,[H_WHOSETURN] ; $FF00+$f3
    add $b0
    jp PlayBattleAnimation2

SwitchAndTeleportEffect: ; 3f739 (f:7739)
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr nz,.handleEnemy

.handlePlayer
    ld a,[W_ISINBATTLE] ; $d057
    dec a
    jr nz,.notWildBattle1
    ld a,[W_PLAYERMOVENUM]
    cp WHIRLWIND
    jr nz,.NotWhirlWind1
    call MoveHitTestPlus
    jr nz,.notWildBattle1
.NotWhirlWind1
    ld a,[W_CURENEMYLVL] ; $d127
    ld b,a
    ld a,[W_PLAYERMONLEVEL] ; $d022
    cp b ; is the player's level greater than the enemy's level?
    jr nc,.playerMoveWasSuccessful ; if so, teleport will always succeed
    add b
    ld c,a
    inc c ; c = playerLevel + enemyLevel + 1
.rejectionSampleLoop1
    call GenRandomInBattle
    cp c ; get a random number between 0 and c
    jr nc,.rejectionSampleLoop1
    srl b
    srl b ; b = enemyLevel / 4
    cp b ; is rand[0, playerLevel + enemyLevel] >= (enemyLevel / 4)?
    jr nc,.playerMoveWasSuccessful ; if so, allow teleporting
.notWildBattle1
    ld a,[W_PLAYERMOVENUM] ; $cfd2
    ld hl,W_PLAYERMOVEEFFECT
    jr .handleFailed
.playerMoveWasSuccessful
    call ReadPlayerMonCurHPAndStatus
    xor a
    ld [$cc5b],a ; AnimationType
    inc a
    ld [$d078],a ; EscapedFromBattle
    ld a,[W_PLAYERMOVENUM] ; $cfd2
    jr .playAnimAndPrintText

.handleEnemy
    ld a,[W_ISINBATTLE] ; $d057
    dec a
    jr nz,.notWildBattle2
    ld a,[W_ENEMYMOVENUM]
    cp WHIRLWIND
    jr nz,.NotWhirlWind2
    call MoveHitTestPlus
    jr nz,.notWildBattle2
.NotWhirlWind2
    ld a,[W_PLAYERMONLEVEL] ; $d022
    ld b,a
    ld a,[W_CURENEMYLVL] ; $d127
    cp b
    jr nc,.enemyMoveWasSuccessful
    add b
    ld c,a
    inc c
.rejectionSampleLoop2
    call GenRandomInBattle
    cp c
    jr nc,.rejectionSampleLoop2
    srl b
    srl b
    cp b
    jr nc,.enemyMoveWasSuccessful
.notWildBattle2
    ld a,[W_ENEMYMOVENUM] ; $cfcc
    ld hl,W_ENEMYMOVEEFFECT
    jr .handleFailed
.enemyMoveWasSuccessful
    call ReadPlayerMonCurHPAndStatus
    xor a
    ld [$cc5b],a
    inc a
    ld [$d078],a
    ld a,[W_ENEMYMOVENUM] ; $cfcc
    jr .playAnimAndPrintText

.handleFailed
    cp WHIRLWIND
    ret z
    cp TELEPORT
    jr nz,.roar
    ld [hl],SPEED_UP1_EFFECT
    ret
.roar
    ld [hl],ATTACK_DOWN2_EFFECT
    ret

.playAnimAndPrintText
    push af
    call PlayBattleAnimation
    ld c,20
    call DelayFrames
    pop af
    ld hl,.RanFromBattleText
    cp TELEPORT
    jr z,.printText
    ld hl,.RanAwayScaredText
    cp ROAR
    jr z,.printText
    ld hl,.WasBlownAwayText
.printText
    jp PrintText

.RanFromBattleText
    TX_FAR _RanFromBattleText
    db "@"
.RanAwayScaredText
    TX_FAR _RanAwayScaredText
    db "@"
.WasBlownAwayText
    TX_FAR _WasBlownAwayText
    db "@"

; Free

SECTION "TwoToFiveAttacksEffect",ROMX[$7811],BANK[$f]

TwoToFiveAttacksEffect: ; 3f811 (f:7811)
    ld hl,W_PLAYERBATTSTATUS1 ; $d062
    ld de,$d06a
    ld bc,W_NUMHITS ; $d074
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.asm_3f828
    ld hl,W_ENEMYBATTSTATUS1 ; $d067
    ld de,$d06f
    ld bc,$cd05
.asm_3f828
    bit 2,[hl]
    ret nz
    set 2,[hl]
    ld hl,W_PLAYERMOVEEFFECT ; $cfd3
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.asm_3f838
    ld hl,W_ENEMYMOVEEFFECT ; $cfcd
.asm_3f838
    ld a,[hl]
    cp TWINEEDLE_EFFECT
    jr z,.asm_3f856
    cp ATTACK_TWICE_EFFECT
    ld a,2
    jr z,.asm_3f853
    call GenRandomInBattle
    and $3
    cp $2
    jr c,.asm_3f851
    call GenRandomInBattle
    and $3
.asm_3f851
    inc a
    inc a
.asm_3f853
    ld [de],a
    ld [bc],a
    ret
.asm_3f856
    ld a,POISON_SIDE_EFFECT1
    ld [hl],a
    jr .asm_3f853

FlinchSideEffect: ; 3f85b (f:785b)
    call CheckTargetSubstitute
    ret nz
    ld hl,W_ENEMYBATTSTATUS1 ; $d067
    ld de,W_PLAYERMOVEEFFECT ; $cfd3
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.asm_3f870
    ld hl,W_PLAYERBATTSTATUS1 ; $d062
    ld de,W_ENEMYMOVEEFFECT ; $cfcd
.asm_3f870
    ld a,[de]
    cp FLINCH_SIDE_EFFECT1
    ld b,$1a
    jr z,.asm_3f879
    ld b,$4d
.asm_3f879
    call CheckZeroDamageOrSideEffectRandom ; call GenRandomInBattle
    cp b
