MimicEffect: ; 3f9ed (f:79ed)
    ld c,50
    call DelayFrames
    call MoveHitTestPlus
    jr nz,.mimicMissed
    ld a,[H_WHOSETURN]
    and a
    ld hl,W_PLAYERMONMOVES
    ld a,[W_PLAYERBATTSTATUS1]
    jr nz,.enemyTurn
    ld a,[W_ISLINKBATTLE]
    cp $4
    jr nz,.letPlayerChooseMove
    ld hl,W_ENEMYMONMOVES
    ld a,[W_ENEMYBATTSTATUS1]
.enemyTurn
.getRandomMove
    push hl
    call GenRandomInBattle
    and $3
    ld c,a
    ld b,$0
    add hl,bc
    ld a,[hl]
    pop hl
    and a
    jr z,.getRandomMove
    ld d,a
    ld a,[H_WHOSETURN]
    and a
    call BackupMovesBeforeEnemyMimic ; ld hl,W_PLAYERMONMOVES
    ld a,[wPlayerMoveListIndex]
    jr z,.playerTurn
    ld hl,W_ENEMYMONMOVES
    ld a,[wEnemyMoveListIndex]
    jr .playerTurn
.letPlayerChooseMove
