    push af
    ld a,$1
    ld [wMoveMenuType],a
    call MoveSelectionMenu
    call LoadScreenTilesFromBuffer1AndGoPalSet ; After MIMIC
    ld hl,W_ENEMYMONMOVES
    ld a,[wCurrentMenuItem]
    ld c,a
    ld b,$0
    add hl,bc
    ld d,[hl]
    pop af
    ld hl,W_PLAYERMONMOVES
.playerTurn
