    ld hl,W_ENEMYMONMOVES
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.disableEffect
    ld de,W_PLAYERDISABLEDMOVE ; $d06d
    ld hl,W_PLAYERMONMOVES
.disableEffect
    ld a,[de]
    and a
    jr nz,.alreadyDisabled
; PP ► ENERGY - DONE
    push hl
    ld d,h
    ld e,l
    call HowManyMovesWithEnoughEnergy
    pop hl
    ld a,c
    and a
    jr z,.noEnergy ; if 0 moves with enough energy
    ld a,[wCurrentMenuItem] ; Backup Current Menu Item
    push af                 ; ...
.pickMoveToDisable
    push hl
    call GenRandomInBattle
    and $3
    ld c,a
    ld b,$0
    add hl,bc
    ld a,[hl]
    pop hl
    and a
    jr z,.pickMoveToDisable
    ld [$d11e],a
    ld a,c
    ld [wCurrentMenuItem],a
    push bc
    BANKSWITCH CheckEnoughEnergy
    pop bc
    jr c,.pickMoveToDisable
    pop af                  ; Restore Current Menu Item
    ld [wCurrentMenuItem],a ; ...
    ld de,W_ENEMYDISABLEDMOVE ; $d072
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.next
    ld de,W_PLAYERDISABLEDMOVE ; $d06d
.next
    call GenRandomInBattle
    and $7
    inc a
    inc c
    swap c
    add c
    ld [de],a
    call PlayCurrentMoveAnimation2
    ld hl,$ccee
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr nz,.printDisableText
    inc hl
.printDisableText
