; function to tell how effective the type of an enemy attack is on the player's current pokemon
; this doesn't take into account the effects that dual types can have
; (e.g. 4x weakness / resistance,weaknesses and resistances canceling)
; the result is stored in [$D11E]
; ($05 is not very effective,$0A is neutral,$14 is super effective)
; ($00 is immune, $02 is 4x uneffective, $28 is 4x super effective)
; as far is can tell,this is only used once in some AI code to help decide which move to use
AIGetTypeEffectiveness:
;joenote - if type-effectiveness bit is set, then do W_PLAYERMOVETYPE and W_ENEMYMONTYPES
;        -also changed neutral value from $10 to $0A since it makes more sense
;        -and modifying this to take into account both types
    ld a,[wUnusedC000]
    bit 3,a
    jr z,.EnemyMove
    ld a,[W_PLAYERMOVETYPE]
    ld de,W_ENEMYMONTYPES        ; [de] = types of enemy's pokemon
    jr .common
.EnemyMove
    ld a,[W_ENEMYMOVETYPE]
    ld de,W_PLAYERMONTYPES       ; [de] = types of player's pokemon
.common
    ld b,a                       ; b = type of attacker move
    ld [$d11e],a
    call GetTypeEffects
    ld a,$0A
    ld [$d11e],a                 ; initialize [$D11E] to neutral effectiveness
; ──────────────────────────────────────────────────
.loop
    ld a,[hli]                   ; Read Attacker Type from "TypeEffects"
    cp $ff
    ret z
    cp b                         ; match the type of the attacker move
    jr nz,.nextTypePair1
    ld a,[hli]                   ; Read Defender Type from "TypeEffects"
    push hl
    ld h,d
    ld l,e
    ld c,4
.LoopMonTypes
    cp [hl]                      ; match with types of defender pokemon
    jr z,.AImatchingPairFound
    inc hl
    dec c
    jr nz,.LoopMonTypes
    pop hl
    jr .nextTypePair2
.nextTypePair1
    inc hl
.nextTypePair2
    inc hl
    jr .loop
; ──────────────────────────────────────────────────
.AImatchingPairFound
    pop hl
    push hl
    push bc
    ld a,[hl]                    ; a = damage multiplier from "TypeEffects"
    ld [H_MULTIPLIER],a
    xor a
    ld [H_MULTIPLICAND],a
    ld [H_MULTIPLICAND + 1],a
    ld a,[$d11e]
    ld [H_MULTIPLICAND + 2],a
    call Multiply
    ld a,10
    ld [H_DIVISOR],a
    ld b,4
    call Divide
    ld a,[H_QUOTIENT + 3]
    ld [$d11e],a
    pop bc
    pop hl
    jr .nextTypePair2
; ──────────────────────────────────────────────────

PlayBattleMusicAndDoBattleTransitionAndInitBatVar:
   BANKSWITCH PlayBattleMusic
   jp DoBattleTransitionAndInitBatVar

;calls out to trainer ai routines with no-attack bit set
;move-choosing ai routines now check for the no-attack bit and kick out if found
;used so only ai switching checks can run
NoAttackAICall:
    push af ;preserve flags on stack
    ld a,[W_ISINBATTLE]
    dec a
    jr z,.NoAttackAICall_exit ; exit if this is a wild encounter
    ;set the no-attack bit
    ld a,[wUnusedC000]
    set 2,a
    ld [wUnusedC000],a
    ;call ai routines
    BANKSWITCH AIEnemyTrainerChooseMoves
    ;joenote - reset the no-attack bit
    ld a,[wUnusedC000]
    res 2,a
    ld [wUnusedC000],a
.NoAttackAICall_exit
    pop af ;get flags from stack
    ret

