SECTION "bank10",ROMX,BANK[$10]

DisplayPokedexMenu_: ; 40000 (10:4000)
    call GBPalWhiteOut
    call ClearScreen
    call UpdateSprites ; move sprites
    ld a,[wListScrollOffset]
    push af
    xor a
    ld [wCurrentMenuItem],a
    ld [wListScrollOffset],a
    ld [wLastMenuItem],a
    inc a
    ld [$d11e],a
.setUpGraphics
    ld b,$08
    call GoPAL_SET
    BANKSWITCH LoadPokedexTilePatterns
.doPokemonListMenu
    ld hl,wTopMenuItemY
    ld a,2
    ld [hli],a ; top menu item Y
    xor a
    ld [hli],a ; top menu item X
    inc a
    ld [$cc37],a
    ld [$ffb7],a ; Enable Quick Menu
    inc hl
    inc hl
    ld a,7
    ld [hli],a ; max menu item ID
    ld [hl],%00110011 ; menu watched keys (Left,Right,B button,A  button)
    call HandlePokedexListMenu
    jr c,.goToSideMenu ; if the player chose a pokemon from the list
.exitPokedex
    xor a
    ld [$cc37],a
    ld [wCurrentMenuItem],a
    ld [wLastMenuItem],a
    ld [$ffb7],a ; Disable Quick Menu
    ld [$cd3a],a
    ld [$cd3b],a
    pop af
    ld [wListScrollOffset],a
    call GBPalWhiteOutWithDelay3
    call GoPAL_SET_CF1C
    jp ReloadMapData
.goToSideMenu
    call HandlePokedexSideMenu
    dec b
    jr z,.doPokemonListMenu ; if pokemon not seen or player pressed B button
    jp .setUpGraphics ; if pokemon data or area was shown

; handles the menu on the lower right in the pokedex screen
; OUTPUT:
; b = reason for exiting menu
; 00: showed pokemon data or area
; 01: the pokemon has not been seen yet or the player pressed the B button
HandlePokedexSideMenu: ; 4006d (10:406d)
    call PlaceUnfilledArrowMenuCursor
    ld a,[wCurrentMenuItem]
    push af
    ld b,a
    ld a,[wLastMenuItem]
    push af
    ld a,[wListScrollOffset]
    push af
    add b
    ld [$d11e],a
    ; ds 3 ; ld a,[$d11e]
    push af
    ld a,[$cd3d]
    push af
    ld hl,wPokedexSeen
    call IsPokemonBitSet
    ld b,1
    jr z,.exitSideMenu
    call PokedexToIndex
    ld hl,wTopMenuItemY
    ld a,10
    ld [hli],a ; top menu item Y
    ld a,15
    ld [hli],a ; top menu item X
    xor a
    ld [hli],a ; current menu item ID
    ld [$ffb7],a ; Disable Quick Menu
    inc hl
    ld a,2
    ld [hli],a ; max menu item ID
    inc a ; %00000011 ; ▼▲◄►StSeBA
    ld [hli],a ; menu watched keys (A button and B button)
    xor a
    ld [hli],a ; old menu item ID
    ld [$cc37],a
    call EnableWrapping
.handleMenuInput
    call HandleMenuInput
    bit 1,a ; was the B button pressed?
    ld b,1
    jr nz,.buttonBPressed
    ld a,[wCurrentMenuItem]
    and a
    jr z,.choseData
    dec a
    jr z,.choseCry
    ; ft
.choseArea
    PREDEF Func_70f60 ; display pokemon areas
    ld b,0
    jr .exitSideMenu
.choseData
    call ShowPokedexDataInternal
    ld b,0
    ; ft
.exitSideMenu
    pop af
    ld [$cd3d],a
    pop af
    ld [$d11e],a
    pop af
    ld [wListScrollOffset],a
    pop af
    ld [wLastMenuItem],a
    pop af
    ld [wCurrentMenuItem],a
    push bc
    FuncCoord 0,1
    ld hl,Coord
    ld de,20
    ld bc,$7f10 ; 16 blank tiles
    call DrawTileLine ; cover up the menu cursor in the pokemon list
    pop bc
    ret
.buttonBPressed
    push bc
    FuncCoord 15,10
    ld hl,Coord
    ld de,20
    ld bc,$7f07 ; 7 blank tiles
    call DrawTileLine ; cover up the menu cursor in the side menu
    pop bc
    jr .exitSideMenu
; play pokemon cry
.choseCry
    ld a,[$d11e]
    call GetCryData ; get cry data
    call PlaySound ; play sound
    jr .handleMenuInput

SECTION "HandlePokedexListMenu",ROMX[$4111],BANK[$10]

; handles the list of pokemon on the left of the pokedex screen
; sets carry flag if player presses A,unsets carry flag if player presses B
HandlePokedexListMenu: ; 40111 (10:4111)
    xor a
    ld [H_AUTOBGTRANSFERENABLED],a
; draw the horizontal line separating the seen and owned amounts from the menu
    FuncCoord 15,8
    ld hl,Coord
    ld a,$7a ; horizontal line tile
    ld [hli],a
    ld [hli],a
    ld [hli],a
    ld [hli],a
    ld [hli],a
    FuncCoord 14,00
    ld hl,Coord
    call DrawPokedexVerticalLine
    FuncCoord 14,08
    ld hl,Coord
    ld [hl],$68 ; cross tile
    ld hl,wPokedexSeen
    ld b,wPokedexSeenEnd - wPokedexSeen
    call CountSetBits
    ld de,$d11e
    FuncCoord 16,3
    ld hl,Coord
    ld bc,$0103
    call PrintNumber ; print number of seen pokemon
    ld hl,wPokedexOwned
    ld b,wPokedexOwnedEnd - wPokedexOwned
    call CountSetBits
    ld de,$d11e
    FuncCoord 16,6
    ld hl,Coord
    ld bc,$0103
    call PrintNumber ; print number of owned pokemon
    FuncCoord 16,2
    ld hl,Coord
    ld de,PokedexSeenText
    call PlaceString
    FuncCoord 16,5
    ld hl,Coord
    ld de,PokedexOwnText
    call PlaceString
    FuncCoord 16,10
    ld hl,Coord
    ld de,PokedexMenuItemsText
    call PlaceString
; find the highest pokedex number among the pokemon the player has seen
    ld hl,wPokedexSeenEnd - 1
    ld b,DEX_NUM_MON + 1
.maxSeenPokemonLoop
    ld a,[hld]
    ld c,8
.maxSeenPokemonInnerLoop
    dec b
    sla a
    jr c,.storeMaxSeenPokemon
    dec c
    jr nz,.maxSeenPokemonInnerLoop
    jr .maxSeenPokemonLoop
.storeMaxSeenPokemon
    ld a,b
    ld [$cd3d],a ; max seen pokemon
    ld hl,wWaitReleaseJoyBit5
    set 5,[hl]
.loop2
    xor a
    ld [H_AUTOBGTRANSFERENABLED],a
    FuncCoord 4,2
    ld hl,Coord
    ld bc,$0f0a
    call ClearScreenArea
    FuncCoord 1,2
    ld hl,Coord
    ld a,[wListScrollOffset]
    dec a
    ld [$d11e],a
    ld d,8
    ld a,[$cd3d]
    cp 8
    jr nc,.printPokemonLoop
    ld d,a
    dec a
    ld [wMaxMenuItem],a
; loop to print pokemon pokedex numbers and names
; if the player has owned the pokemon,it puts a pokeball beside the name
.printPokemonLoop
    ld a,[$d11e]
    inc a
    ld [$d11e],a
    push af
    push de
    push hl
    ld de,-20
    add hl,de
    ld de,$d11e
    ld bc,$8103
    call PrintNumber ; print the pokedex number
    ld de,18
    add hl,de
    push hl
    ld hl,wPokedexOwned
    call IsPokemonBitSet
    pop hl
    ld a," "
    ld [hli],a ; Write Empty "MonNestIcon"
    jr z,.writeTile
    ld a,$72 ; pokeball tile
.writeTile
    ld [hl],a ; put a pokeball next to pokemon that the player has owned
    push hl
    ld hl,wPokedexSeen
    call IsPokemonBitSet
    pop hl
    push hl
    PREDEF_NZ IsMonInCurrentMap
    jr nz,.getPokemonName ; if the player has seen the pokemon
    ld de,.dashedLine ; print a dashed line in place of the name if the player hasn't seen the pokemon
    jr .skipGettingName
.dashedLine ; for unseen pokemon in the list
    db "----------@"
.getPokemonName
    call PokedexToIndex
    call GetMonName
.skipGettingName
    pop hl
    inc hl
    call PlaceString
    pop hl
    ld bc,2 * 20
    add hl,bc
    pop de
    pop af
    ld [$d11e],a
    dec d
    jr nz,.printPokemonLoop
    ld a,01
    ld [H_AUTOBGTRANSFERENABLED],a
    call Delay3
    call GBPalNormal
    call HandleMenuInput
    bit 1,a ; was the B button pressed?
    jp nz,.buttonBPressed
.checkIfUpPressed
    bit 6,a ; was Up pressed?
    jr z,.checkIfDownPressed
.upPressed ; scroll up one row
    ld a,[wListScrollOffset]
    and a
    jr z,.loop
    dec a
    ld [wListScrollOffset],a
    jr .loop
.checkIfDownPressed
    bit 7,a ; was Down pressed?
    jr z,.checkIfRightPressed
.downPressed ; scroll down one row
    ld a,[$cd3d]
    cp 8
    jr c,.loop
    sub a,8
    ld b,a
    ld a,[wListScrollOffset]
    cp b
    jr z,.loop
    inc a
    ld [wListScrollOffset],a
    jr .loop
.checkIfRightPressed
    bit 4,a ; was Right pressed?
    jr z,.checkIfLeftPressed
.rightPressed ; scroll down 8 rows
    ld a,[$cd3d]
    cp 8
    jr c,.loop
    sub a,7
    ld b,a
    ld a,[wListScrollOffset]
    add a,8
    ld [wListScrollOffset],a
    cp b
    jr c,.loop
    dec b
    ld a,b
    ld [wListScrollOffset],a
    jr .loop
.checkIfLeftPressed ; scroll up 8 rows
    bit 5,a ; was Left pressed?
    jr z,.buttonAPressed
.leftPressed
    ld a,[wListScrollOffset]
    sub a,8
    ld [wListScrollOffset],a
    jr nc,.loop
    xor a
    ld [wListScrollOffset],a
.loop
    jp .loop2
.buttonAPressed
    scf
    ret
.buttonBPressed
    and a
    ret

DrawPokedexVerticalLine:
    ld c,18 ; height of line
    ld de,20 ; width of screen
    ld a,$66 ; vertical line tile
.loop
    ld [hl],a
    add hl,de
;    xor a,1 ; toggle between vertical line tile and box tile
    dec c
    jr nz,.loop
    ret

