SECTION "ShowPokedexData",ROMX[$42d1],BANK[$10]

; function to display pokedex data from outside the pokedex
ShowPokedexData: ; 402d1 (10:42d1)
    call GBPalWhiteOutWithDelay3
    call ClearScreen
    call UpdateSprites
    BANKSWITCH LoadPokedexTilePatterns ; load pokedex tiles
    ; ft

; function to display pokedex data from inside the pokedex
ShowPokedexDataInternal: ; 402e2 (10:42e2)
    ; Text without "\n"
    ld hl,$fff6
    set 2,[hl]
    ; 3/7 Volume
    ld a,$33
    ld [$ff24],a
    ; prevent audio fade out
    ld hl,$d72c
    set 1,[hl]
    ; water/flower tile animation
    ld a,[$ffd7]
    push af
    xor a
    ld [$ffd7],a
    ; reset mon picture "just load" flag 
    ld hl,wPokedexScreenJustLoadBit6
    res 6,[hl]

    call GBPalWhiteOut ; zero all palettes
    call ClearScreen
    call .DrawPokedexBorder
    call .CommonInitilization
    jr .SkipFirstTime

.FirstPage
    call .ClearCommonScreenArea
.SkipFirstTime
    call .ShowPokedexFirstPage
    ld b,%00010011 ; ▼▲◄►StSeBA
    ; ft

.waitForButtonPress
    call GetJoypadStateLowSensitivity
    ld a,[$ffb5]
    and %00010011 ; ▼▲◄►StSeBA
    jr z,.waitForButtonPress
    bit 1,a
    jr nz,.end
    ; ft

.SecondPage
    call .ClearCommonScreenArea
    call .ShowPokedexSecondPage

.waitForButtonPress2
    call GetJoypadStateLowSensitivity
    ld a,[$ffb5]
    and %00100011 ; ▼▲◄►StSeBA
    jr z,.waitForButtonPress2
    bit 5,a
    jr nz,.FirstPage
    ; ft

.end
    ; Restore Screen
    call GBPalWhiteOut
    call ClearScreen
    call GoPAL_SET_CF1C
    ld hl,wForceShowPokedexBit5
    bit 5,[hl]
    call z,LoadTextBoxTilePatterns
    call GBPalNormal
    ; reset mon picture "just load" flag 
    ld hl,wPokedexScreenJustLoadBit6
    res 6,[hl]
    ; water/flower tile animation
    pop af
    ld [$ffd7],a
    ; prevent audio fade out
    ld hl,$d72c
    res 1,[hl]
    ; Max Volume
    ld a,$77
    ld [$ff24],a
    ; UNDO Text without "\n"
    ld hl,$fff6
    res 2,[hl]
    ret

