.DrawPokedexBorder
    FuncCoord 00,00
    ld hl,Coord
    ld de,1
    ld bc,$6414
    call DrawTileLine ; draw top border
    FuncCoord 00,17
    ld hl,Coord
    ld b,$6f
    call DrawTileLine ; draw bottom border
    FuncCoord 00,01
    ld hl,Coord
    ld de,20
    ld bc,$6610
    call DrawTileLine ; draw left border
    FuncCoord 19,01
    ld hl,Coord
    ld b,$67
    call DrawTileLine ; draw right border
    FuncCoord 00,00
    ld a,$63 ; upper left corner tile
    ld [Coord],a
    FuncCoord 19,00
    ld a,$65 ; upper right corner tile
    ld [Coord],a
    FuncCoord 00,17
    ld a,$6c ; lower left corner tile
    ld [Coord],a
    FuncCoord 19,17
    ld a,$6e ; lower right corner tile
    ld [Coord],a
    ret
.ClearCommonScreenArea
    FuncCoord 08,03
    ld hl,Coord
    ld bc,((05 << 8) + 11)
    call ClearScreenArea
    FuncCoord 01,08
    ld hl,Coord
    ld bc,((09 << 8) + 18)
    jp ClearScreenArea
.DisableAutoBG
    xor a
    ld [$ff00+$ba],a ; AutoBGTransferEnabled
    ret
.EnableAutoBG
    ld a,$1
    ld [$ff00+$ba],a ; AutoBGTransferEnabled
    ret

