.CommonInitilization
    ld a,[$d11e] ; pokemon ID
    ld [$cf91],a
    push af
    call HandleColorlessGameBoyOrGoPAL_SET ; call GoPAL_SET
    pop af
    ld [$d11e],a
    ret

; ───────────────────────────────────────

.ShowPokedexFirstPage
    call .DisableAutoBG
    FuncCoord 00,10
    ld hl,Coord
    ld de,.PokedexDataDividerLine
    call PlaceString ; draw horizontal divider line
    FuncCoord 09,08
    ld hl,Coord
    ld de,.HeightWeightText
    call PlaceString ; Draw Height/Weight Label
    call GetMonName
    FuncCoord 09,02
    ld hl,Coord
    call PlaceString
    ld hl,PokedexEntryPointers
    call IndexToPokedexAndRestoreD11E
    ; dec a ; 00MOD
    ld e,a
    ld d,0
    add hl,de
    add hl,de
    ld a,[hli]
    ld e,a
    ld d,[hl] ; de = address of pokedex entry
    FuncCoord 09,07
    ld hl,Coord
    call PlaceString ; print species name
    ld h,b
    ld l,c
    push de
    ld a,[$d11e]
    push af
    call IndexToPokedex
    FuncCoord 02,09
    ld hl,Coord
    ld a,"№"
    ld [hli],a
    ld a,$f2
    ld [hli],a
    ld de,$d11e
    ld bc,$8103
    call PrintNumber ; print pokedex number
    pop af
    ld [$d11e],a
    ld a,[$cf91]
    ld [$d0b5],a
    pop de
    inc de ; de = address of feet (height)
    ld a,[de] ; reads feet,but a is overwritten without being used
    FuncCoord 12,08
    ld hl,Coord
    ld bc,$0102
    call PrintNumber ; print feet (height)
    ld a,$70 ; feet symbol tile (one tick)
    ld [hl],a
    inc de
    inc de ; de = address of inches (height)
    FuncCoord 15,08
    ld hl,Coord
    ld bc,$8102
    call PrintNumber ; print inches (height)
    ld a,$71 ; inches symbol tile (two ticks)
    ld [hl],a
; now print the weight (note that weight is stored in tenths of pounds internally)
    inc de
    inc de
    inc de ; de = address of upper byte of weight
    push de
; put weight in big-endian order at $ff8b
    ld hl,$ff8b
    ld a,[hl] ; save existing value of [$ff8b]
    push af
    ld a,[de] ; a = upper byte of weight
    ld [hli],a ; store upper byte of weight in [$ff8b]
    ld a,[hl] ; save existing value of [$ff8c]
    push af
    dec de
    ld a,[de] ; a = lower byte of weight
    ld [hl],a ; store lower byte of weight in [$ff8c]
    FuncCoord 11,09
    ld de,$ff8b
    ld hl,Coord
    ld bc,$0205 ; no leading zeroes,right-aligned,2 bytes,5 digits
    call PrintNumber ; print weight
    FuncCoord 14,09
    ld hl,Coord
    ld a,[$ff8c]
    sub a,10
    ld a,[$ff8b]
    sbc a,0
    jr nc,.next
    ld [hl],"0" ; if the weight is less than 10,put a 0 before the decimal point
.next
    inc hl
    ld a,[hli]
    ld [hld],a ; make space for the decimal point by moving the last digit forward one tile
    ld [hl],$f2 ; decimal point tile
    pop af
    ld [$ff8c],a ; restore original value of [$ff8c]
    pop af
    ld [$ff8b],a ; restore original value of [$ff8b]
    pop hl
    inc hl ; hl = address of pokedex description text
    FuncCoord 01,11
    ld bc,Coord
    ld a,2
    ld [$fff4],a
    call TextCommandProcessor ; print pokedex description text
    xor a
    ld [$fff4],a
    FuncCoord 09,04
    ld hl,Coord
    PREDEF PrintTypes
    call .EnableAutoBG
    call Delay3
    call GBPalNormal
    ; header just loaded in "GetPokedexPaletteID" ; call GetMonHeader ; load pokemon picture location
    ld hl,wPokedexScreenJustLoadBit6
    bit 6,[hl]
    set 6,[hl]
    jr nz,.PictureJustLoad
    FuncCoord 01,01
    ld hl,Coord
    call LoadMonSpritePokedexWithDebug ; call LoadFlippedFrontSpriteByMonIndex ; draw pokemon picture
    ld a,[$cf91]
    call GetCryData ; get cry data
    call PlaySound ; play sound
.PictureJustLoad
    ret

.HeightWeightText
    db "HT   ",$60,"  ",$61,$4E,"WT      lb@"

; horizontal line that divides the pokedex text description from the rest of the data
.PokedexDataDividerLine
    db $68,$69,$6B,$69,$6B
    db $69,$6B,$69,$6B,$6B
    db $6B,$6B,$69,$6B,$69
    db $6B,$69,$6B,$69,$6A
    db $50

; ───────────────────────────────────────

.ShowPokedexSecondPage
    ; Backup STACK
    ld a,[$d11e]
    push af

    ; Backup
    ld hl,wBackupBattleDataDuringDex2ndPage
    ld a,[H_WHOSETURN]
    ld [hli],a
    ld a,[W_PLAYERMONID]
    ld [hli],a
    ld a,[W_PLAYERMOVENUM]
    ld [hli],a
    ld a,[W_ENEMYMON_START]
    ld [hli],a
    ld d,h
    ld e,l
    ld hl,W_PLAYERMONTYPES
    ld bc,4
    call CopyData ; copy bc bytes of data from hl to de
    ld hl,W_ENEMYMONTYPES
    ld bc,4
    call CopyData ; copy bc bytes of data from hl to de

    call .DisableAutoBG
    FuncCoord 00,10
    ld hl,Coord
    ld [hl],$66 ; Border Left
    FuncCoord 19,10
    ld hl,Coord
    ld [hl],$67 ; Border Right

    FuncCoord 09,04
    ld hl,Coord
    PREDEF PrintTypesFull

    FuncCoord 02,09
    ld hl,Coord
    ld de,.TypesAttack1
    call .LoopTypesAttack
    FuncCoord 11,09
    ld hl,Coord
    ld de,.TypesAttack2
    call .LoopTypesAttack

    call .EnableAutoBG
    call Delay3
    call GBPalNormal

    ; Restore
    ld hl,wBackupBattleDataDuringDex2ndPage
    ld a,[hli]
    ld [H_WHOSETURN],a
    ld a,[hli]
    ld [W_PLAYERMONID],a
    ld a,[hli]
    ld [W_PLAYERMOVENUM],a
    ld a,[hli]
    ld [W_ENEMYMON_START],a
    ld de,W_PLAYERMONTYPES
    ld bc,4
    call CopyData ; copy bc bytes of data from hl to de
    ld de,W_ENEMYMONTYPES
    ld bc,4
    call CopyData ; copy bc bytes of data from hl to de

    ; Restore STACK
    pop af
    ld [$d11e],a
    ret

.LoopTypesAttack
    ld a,[de]
    cp $FF
    ret z
    push de
    push hl
    ld [W_PLAYERMOVETYPE],a
    PREDEF PrintMoveTypeShort
    xor a
    ld [H_WHOSETURN],a
    ld [W_PLAYERMONID],a
    ld [W_PLAYERMOVENUM],a
    ld [W_ENEMYMON_START],a
    ld hl,W_PLAYERMONTYPES
    ld bc,4
    call FillMemory
    ld hl,W_ENEMYMONTYPES
    ld de,W_MONHTYPES
    ld b,4
.Loop4Types
    ld a,[de]
    inc de
    ld [hli],a
    dec b
    jr nz,.Loop4Types
    ld a,10
    ld [$d05b],a ; DamageMultipliers
    BANKSWITCH AdjustDamageForMoveType
    call .ReadDamageMultiplier
    pop hl
    push hl
    call .PrintDamageMultiplier
    pop hl
    ld bc,20
    add hl,bc
    pop de
    inc de
    jr .LoopTypesAttack

.ReadDamageMultiplier
    xor a
    ld hl,H_MULTIPLICAND
    ld [hli],a
    ld [hli],a
    ld a,[$D05B]
    and a,%01111111 ; ignore STAB
    cp 10
    push af
    ld [hli],a
    ld [hl],10
    call Multiply
    ld a,[H_PRODUCT+2]
    ld [wTmpDmgMultiplier],a
    ld a,[H_PRODUCT+3]
    ld [wTmpDmgMultiplier+1],a
    pop af
    ret

.PrintDamageMultiplier
    jr z,.skip
    jr c,.skip
    inc hl
    inc hl
    inc hl
    ld [hl],$D4 ; Up Arrow Symbol
    dec hl
    dec hl
    dec hl
.skip
    ld bc,4
    add hl,bc
    ld de,wTmpDmgMultiplier
    ld bc,(%00000010 << 8) + 3 ; three digits
    call PrintNumber
    ld [hl],$D9 ; %
    ret

.TypesAttack1
    db FIGHT
    db WIND
    db POISON
    db EARTH
    db ROCK
    db BUG
    db METAL
    db NORMAL
    db $FF

.TypesAttack2
    db IVORY
    db RUBBER
    db FIRE
    db WATER
    db GRASS
    db THUNDER
    db PSYCHIC
    db ICE
    db $FF

; ───────────────────────────────────────

