DisplayDexRating: ; 44169 (11:4169)
    ld hl,wPokedexSeen
    ld b,wPokedexSeenEnd - wPokedexSeen
    call CountSetBits
    ld a,[$D11E] ; result of CountSetBits (seen count)
    ld [$FFDB],a
    ld hl,wPokedexOwned
    ld b,wPokedexOwnedEnd - wPokedexOwned
    call CountSetBits
    ld a,[$D11E] ; result of CountSetBits (own count)
    ld [$FFDC],a
    ld a,[$D747]
    bit 3,a
    res 3,a
    ld [$D747],a
    ret nz ; from hall of fame
    ld hl,.DexRatingsTable
.findRating
    ld a,[hli]
    ld b,a
    ld a,[$FFDC] ; number of pokemon owned
    cp b
    jr c,.foundRating
    inc hl
    inc hl
    jr .findRating
.foundRating
    ld a,[hli]
    ld h,[hl]
    ld l,a ; load text pointer into hl
    push hl
    ld hl,.UnnamedText_441cc
    call PrintText
    pop hl
    call PrintText
    BANKSWITCH Func_7d13b
    jp WaitForTextScrollButtonPress ; wait for button press

