; ──────────────────────
; Lapras General
; ──────────────────────

SafariZoneScript:
    call EnableAutoTextBoxDrawing
    ld hl,SafariZoneScriptPointers
    ld a,[W_SAFARIZONECURSCRIPT]
    jp CallFunctionInTable

SafariZoneScriptPointers:
    dw Nope
    dw SafariZonePostLapras
    dw Nope
    dw Nope

SafariZoneLapras:
    db $8
    ld hl,SafariZoneLaprasText
    call PrintText
    ld a,LAPRAS
    call PlayCry
    call WaitForSoundToFinish
    ld hl,.OAMIdList
    call GetCurrentMapLaprasInfo
    ld [$FF00+$8c],a ; OAM
    xor a
    ld [W_GYMLEADERNO],a
    ld a,30
    ld [W_CURENEMYLVL],a
    ld a,LAPRAS ; Entry Point
    ld [W_CUROPPONENT],a ; $d059
    ld [wEngagedTrainerClass],a
    call PlayTrainerMusic
    ld a,1 ; SafariZonePostLapras
    ld [W_SAFARIZONECURSCRIPT],a
    ld [W_CURMAPSCRIPT],a
    jp TextScriptEnd
.OAMIdList
    db SAFARI_ZONE_EAST,5
    db SAFARI_ZONE_NORTH,3
    db SAFARI_ZONE_CENTER,2

SafariZoneLaprasText:
    TX_FAR _SafariZoneLaprasText
    db "@"

SafariZonePostLapras:
    ld a,[W_ISINBATTLE] ; $d057
    cp $ff
    jr z,.reset
    ld hl,.MissableIdList
    call GetCurrentMapLaprasInfo
    ld [$cc4d],a
    PREDEF RemoveMissableObject
    call UpdateSprites
    call Delay3
    ld a,[wBattleResult]
    cp $2
    jr z,.reset
    ld hl,.RunAwayTextIdList
    call GetCurrentMapLaprasInfo
    ld [H_DOWNARROWBLINKCNT2],a ; $FF00+$8c
    call DisplayTextID
    ; Show Another Lapras
    call GenRandom
    srl a
    ld hl,.ShowLapras1IdList
    jr c,.done
    ld hl,.ShowLapras2IdList
.done
    call GetCurrentMapLaprasInfo
    ld [$cc4d],a
    PREDEF AddMissableObject
.reset
    jr SafariZoneResetScript
.MissableIdList
    db SAFARI_ZONE_EAST,$E8
    db SAFARI_ZONE_NORTH,$EB
    db SAFARI_ZONE_CENTER,$F1
.RunAwayTextIdList
    db SAFARI_ZONE_EAST,9
    db SAFARI_ZONE_NORTH,9
    db SAFARI_ZONE_CENTER,5
.ShowLapras1IdList
    db SAFARI_ZONE_EAST,$EB
    db SAFARI_ZONE_NORTH,$E8
    db SAFARI_ZONE_CENTER,$E8
.ShowLapras2IdList
    db SAFARI_ZONE_EAST,$F1
    db SAFARI_ZONE_NORTH,$F1
    db SAFARI_ZONE_CENTER,$EB

GetCurrentMapLaprasInfo:
    call GetCurrentOldAdventureMap
    ld b,a
.Loop
    ld a,[hli]
    cp b
