    dw UnknownDungeon4MewtwoText ; 0x5f26 TextAfterBattle
    dw UnknownDungeon4MewtwoText ; 0x5f26 TextEndBattle
    dw UnknownDungeon4MewtwoText ; 0x5f26 TextEndBattle

