    dw UnknownDungeon4AlakazamText ; TextBeforeBattle
    dw UnknownDungeon4AlakazamText ; TextAfterBattle
    dw UnknownDungeon4AlakazamText ; TextEndBattle
    dw UnknownDungeon4AlakazamText ; TextEndBattle

