UnknownDungeon4Script0:
    ld a,[$c152] ; Gengar Visibility
    inc a
    jr z,.end
    ld a,[$c15a] ; Gengar Y Delta
    cp $40
    jr nz,.end
    ld a,[$c15b] ; Gengar X Delta
    cp $40
    jr nz,.end
    ; Over Gengar
    ld a,[$c109] ; direction the player is facing
    cp $04 ; up
    ld de,.MovementDown
    jr z,.continue
    and a ; down
    ld de,.MovementUp
    jr z,.continue
    cp $0C ; right
    ld de,.MovementLeft
    jr z,.continue
    ; left
    ld de,.MovementRight
.continue
    ld a,$5
    ld [$ff00+$8c],a
    call MoveSprite
    ld a,[H_CURRENTPRESSEDBUTTONS]
    and %11110010 ; ▼▲◄►StSeBA
    ld [H_CURRENTPRESSEDBUTTONS],a
    ld a,%00001101 ; ▼▲◄►StSeBA
    ld [wJoypadForbiddenButtonsMask],a
    ld a,$3 ; WaitGengarMoving
    ld [W_UNKNOWNDUNGEON3CURSCRIPT],a
    ld [W_CURMAPSCRIPT],a
    ret
.end
    jp CheckFightingMapTrainers
.MovementDown
    db DN,$FF
.MovementUp
    db UP,$FF
.MovementLeft
    db LT,$FF
.MovementRight
    db RT,$FF

WaitGengarMoving:
    ld a,[$d730]
    bit 0,a
    ret nz
    xor a ; UnknownDungeon4Script0
    ld [wJoypadForbiddenButtonsMask],a
    ld [W_UNKNOWNDUNGEON3CURSCRIPT],a
    ld [W_CURMAPSCRIPT],a
    ret

