    ld a,[$d880]
    and $3
    cp $3
    ret z
    ld hl,.CoordsData
    call ArePlayerCoordsInArray
    ret nc
    ld a,[$cd3d]
    cp $1
    ld de,.RLEMovement0815
    jr z,.done
    ld de,.RLEMovement1023
.done
    ld hl,$ccd3
    call DecodeRLEList
    dec a
    ld [$cd38],a
    call StartSimulatingJoypadStates
    ld hl,W_FLAGS_D733
    set 2,[hl]
    ld a,$1
    ld [W_SEAFOAMISLANDS4CURSCRIPT],a
    ret
.CoordsData
    db 08,15
    db 10,23
    db $FF
.RLEMovement0815
    db $80,6
    db $10,5
    db $80,3
    db $ff
.RLEMovement1023
    db $80,6
    db $20,2
    db $80,1
    db $ff

