SafariZoneRestHouse1Text1:
    db $08 ; asm
    ld a,[wEventErikMeetSaraBit3]
    bit 3,a
    jr nz,.AfterMeetErik
    ld hl,.SafariZoneRestHouse1Text1
    call PrintText
    ld hl,wEventEncounterSaraBit2
    set 2,[hl]
.end
    jp TextScriptEnd
