Func_480eb: ; 480eb (12:40eb)
    call Load16BitRegisters
    ld a,[rBGP] ; $FF00+$47
    or b
    ld [rBGP],a ; $FF00+$47
    ld c,$4
    call DelayFrames
    ld a,[rBGP] ; $FF00+$47
    and $fc
    ld [rBGP],a ; $FF00+$47
    ret

Func_480ff: ; 480ff (12:40ff)
    call Load16BitRegisters
    ld a,$1
    ld [$d0a0],a
    xor a
.asm_48108
    ld [H_NUMTOPRINT],a ; $FF00+$96 (aliases: H_MULTIPLICAND)
    call Func_48119
    call Func_48119
    dec b
    ld a,b
    jr nz,.asm_48108
    xor a
    ld [$d0a0],a
    ret

Func_48119: ; 48119 (12:4119)
    ld a,[H_NUMTOPRINT] ; $FF00+$96 (aliases: H_MULTIPLICAND)
    xor b
    ld [H_NUMTOPRINT],a ; $FF00+$96 (aliases: H_MULTIPLICAND)
    ld [rWY],a ; $FF00+$4a
    ld c,$3
    jp DelayFrames

ShakeScreenHorizontally: ; 48125 (12:4125)
    call Load16BitRegisters
    xor a
.asm_48129
    ld [$FF00+$97],a
    call Func_4813f
    ld c,$1
    call DelayFrames
    call Func_4813f
    dec b
    ld a,b
    jr nz,.asm_48129
    ld a,$7
    ld [rWX],a ; $FF00+$4b
    ret

Func_4813f: ; 4813f (12:413f)
    ld a,[$FF00+$97]
    xor b
    ld [$FF00+$97],a
    bit 7,a
    jr z,.asm_48149
    xor a
.asm_48149
    add $7
    ld [rWX],a ; $FF00+$4b
    ld c,$4
    jp DelayFrames

