_GivePokemon: ; 4fda5 (13:7da5)
    call EnableAutoTextBoxDrawing
    xor a
    ld [$ccd3],a
    ld a,[W_NUMINPARTY] ; $d163
    cp $6
    jr c,.asm_4fe01
    ld a,[W_NUMINBOX] ; $da80
    cp $14
    jr nc,.asm_4fdf9
    xor a
    ld [W_ENEMYBATTSTATUS3],a ; $d069
    ld a,[$cf91]
    ld [W_ENEMYMONID],a
    call GivePokemon_LoadEnemyMonData
    call .SetPokedexOwnedFlag
    BANKSWITCH SendNewMonToBox
    ld hl,$cf4b
    ld a,[$d5a0]
    and $7f
    cp $9
    jr c,.asm_4fdec
    sub $9
    ld [hl],$f7
    inc hl
    add $f6
    jr .asm_4fdee
.asm_4fdec
    add $f7
.asm_4fdee
    ld [hli],a
    ld [hl],$50
    ld hl,.UnnamedText_4fe3f
    call PrintText
    scf
    ret
.asm_4fdf9
    ld hl,.UnnamedText_4fe44
    call PrintText
    and a
    ret
.asm_4fe01
    call .SetPokedexOwnedFlag
    call AddPokemonToParty
    ld a,$1
    ld [$cc3c],a
    ld [$ccd3],a
    scf
    ret

.SetPokedexOwnedFlag
    ld a,[$cf91]
    push af
    ld [$d11e],a
    PREDEF IndexToPokedex
    ld a,[$d11e]
    ld c,a
    ld hl,wPokedexOwned ; $d2f7
    ld b,$1
    PREDEF HandleBitArray
    pop af
    ld [$d11e],a
    call GetMonName
    ld hl,.UnnamedText_4fe39
    jp PrintText

.UnnamedText_4fe39
    TX_FAR _UnnamedText_4fe39
    db $0b
    db "@"

.UnnamedText_4fe3f
    TX_FAR _UnnamedText_4fe3f
    db "@"

.UnnamedText_4fe44
    TX_FAR _UnnamedText_4fe44
    db "@"

GivePokemon_LoadEnemyMonData:
    ld hl,wTempAlternateFormIndex
    ld a,[hl]
    push af
    push hl
    BANKSWITCH LoadEnemyMonData
    pop hl
    pop af
    ld [hl],a
    ret

