ResetSeaFormEventsIfNotCompleted:
    ld hl,$d880
    call .CheckBit01
    jr z,.NextFlagsByte
    call .ResetBit01
    ld a,$d7
    call .AddMissableObject
    ld a,$d8
    call .AddMissableObject
    ld hl,.MissableObjectIDs ; $4ce8
.loop
    ld a,[hli]
    cp $ff
    jr z,.NextFlagsByte
    push hl
    call .RemoveMissableObject
    pop hl
    jr .loop

.MissableObjectIDs:
    db $D9,$DA,$DB,$DC,$DF,$E0,$FF

.NextFlagsByte
    ld hl,$d881
    call .CheckBit01
    ret z
    call .ResetBit01
    ld a,$dd
    call .AddMissableObject
    ld a,$de
    call .AddMissableObject
    ld a,$e1
    call .RemoveMissableObject
    ld a,$e2
    jr .RemoveMissableObject

.CheckBit01
    ld a,[hl]
    and %00000011
    cp %00000011
    ret

.ResetBit01
    ld a,[hl]
    and %11111100
    ld [hl],a
    ret

.AddMissableObject
    ld [$cc4d],a
    PREDEF_JUMP AddMissableObject

.RemoveMissableObject
    ld [$cc4d],a
    PREDEF_JUMP RemoveMissableObject

