    bit 5,[hl]
    res 5,[hl]
    call nz,VictoryRoad2Script_517c9
    call EnableAutoTextBoxDrawing
    ld hl,VictoryRoad2TrainerHeaders
    ld de,VictoryRoad2ScriptPointers
    ld a,[W_VICTORYROAD2CURSCRIPT]
