ParalyzeEffect_:
    ld hl,W_ENEMYMONSTATUS ; $cfe9
    ld de,W_PLAYERMOVETYPE ; $cfd5
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.next
    ld hl,W_PLAYERMONSTATUS ; $d018
    ld de,W_ENEMYMOVETYPE ; $cfcf
.next
    bit PAR_Bit,[hl]
    jr nz,.alreadyParalyzed ; miss if target is already paralyzed
    ld a,[de]
    cp THUNDER
    jr nz,.hitTest
    call CheckGoundOrRock
    jr z,.doesntAffect
.hitTest
    push hl
    BANKSWITCH MoveHitTestPlus
    pop hl
    jr nz,.didntAffect
    set PAR_Bit,[hl]
    BANKSWITCH QuarterSpeedDueToParalysis
    ld c,30
    call DelayFrames
    BANKSWITCH PlayCurrentMoveAnimation2
    BANKSWITCH_JUMP PrintMayNotAttackText
.alreadyParalyzed
    ld hl,PrintAlreadyParalyzedText
    jr .PlayAnimationAndTextFail
.didntAffect
    ld hl,PrintDidntAffectText
    jr .PlayAnimationAndTextFail
.doesntAffect
    ld hl,PrintDoesntAffectMonText
    ; ft
.PlayAnimationAndTextFail
    push hl
    call .PlayCurrentMoveAnimation
    pop hl
    jr .BankswitchToF
.PlayCurrentMoveAnimation
    ld hl,PlayCurrentMoveAnimation
    ; ft
.BankswitchToF
    ld b,BANK(PlayCurrentMoveAnimation) ; same PrintAlreadyParalyzedText,PrintDidntAffectText
    jp Bankswitch

