SECTION "GetPrizeMenuId",ROMX[$678e],BANK[$14]

GetPrizeMenuId: ; 5278e (14:678e)
; determine which one among the three
; prize-texts has been selected
; using the text ID (stored in [$FF8C])
; load the four prizes at $D13D-$D140
; load the four prices at $D142-$D149
; display the four prizes' names
; (distinguishing between Pokemon names
; and Items (specifically TMs) names)
    ld a,[$FF8C]
    sub a,$03       ; prize-texts' id are 3,4 and 5
    ld [$D12F],a    ; prize-texts' id (relative,i.e. 0,1 or 2)
    add a
    add a
    ld d,$00
    ld e,a
    ld hl,.PrizeDifferentMenuPtrs
    add hl,de
    ld a,[hli]
    ld d,[hl]
    ld e,a
    inc hl
    push hl
    ld hl,W_PRIZE1
    call CopyString      ; XXX what does this do
    pop hl
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ld de,W_PRICE1
    ld bc,$0008
    call CopyData
    ld a,[$D12F]
    cp $02        ;is TM_menu?
    jr nz,.putMonName
    ld a,[W_PRIZE1]
    ld [$D11E],a
    call GetItemName
    FuncCoord 2,4
    ld hl,Coord
    call PlaceString
    ld a,[W_PRIZE2]
    ld [$D11E],a
    call GetItemName
    FuncCoord 2,6
    ld hl,Coord
    call PlaceString
    ld a,[W_PRIZE3]
    ld [$D11E],a
    call GetItemName
    FuncCoord 2,8
    ld hl,Coord
    call PlaceString
    ld a,[W_PRIZE4]
    ld [$D11E],a
    call GetItemName
    FuncCoord 2,10
    ld hl,Coord
    call PlaceString
    jr .putNoThanksText
.putMonName ; 14:67EC
    ld a,[W_PRIZE1]
    ld [$D11E],a
    call GetMonName
    FuncCoord 2,4
    ld hl,Coord
    call PlaceString
    ld a,[W_PRIZE2]
    ld [$D11E],a
    call GetMonName
    FuncCoord 2,6
    ld hl,Coord
    call PlaceString
    ld a,[W_PRIZE3]
    ld [$D11E],a
    call GetMonName
    FuncCoord 2,8
    ld hl,Coord
    call PlaceString
    ld a,[W_PRIZE4]
    ld [$D11E],a
    call GetMonName
    FuncCoord 2,10
    ld hl,Coord
    call PlaceString
.putNoThanksText ; 14:6819
;    FuncCoord 2,10
;    ld hl,Coord
;    ld de,NoThanksText
;    call PlaceString
; put prices on the right side of the textbox
    ld de,W_PRICE1
    FuncCoord 13,5
    ld hl,Coord
; reg. c:
; [low nybble] number of bytes
; [bit 765 = %100] space-padding (not zero-padding)
    ld c,(1 << 7 | 2)
; Function $15CD displays BCD value (same routine
; used by text-command $02)
    call PrintBCDNumber ; Print_BCD
    ld de,W_PRICE2
    FuncCoord 13,7
    ld hl,Coord
    ld c,(%1 << 7 | 2)
    call PrintBCDNumber
    ld de,W_PRICE3
    FuncCoord 13,9
    ld hl,Coord
    ld c,(1 << 7 | 2)
    call PrintBCDNumber
    ld de,W_PRICE4
    FuncCoord 13,11
    ld hl,Coord
    ld c,(1 << 7 | 2)
    jp PrintBCDNumber
.PrizeDifferentMenuPtrs
    dw .PrizeMenuMon1Entries
    dw .PrizeMenuMon1Cost
    dw .PrizeMenuMon2Entries
    dw .PrizeMenuMon2Cost
    dw .PrizeMenuTMsEntries
    dw .PrizeMenuTMsCost

.PrizeMenuMon1Entries
    db MAGIKARP
    db BUTTERFREE
    db DODUO
    db RHYHORN
    db "@"
.PrizeMenuMon1Cost
    db $02,$00 ; MAGIKARP   =  4000 Yen
    db $09,$00 ; BUTTERFREE = 18000 Yen
    db $10,$00 ; DODUO      = 20000 Yen
    db $25,$00 ; RHYHORN    = 50000 Yen
    db "@"

.PrizeMenuMon2Entries
    db STARMIE
    db ARCANINE
    db CLOYSTER
    db EXEGGUTOR
    db "@"
.PrizeMenuMon2Cost
    db $35,$00 ; STARMIE   = 70000 Yen
    db $30,$00 ; ARCANINE  = 60000 Yen
    db $35,$00 ; CLOYSTER  = 70000 Yen
    db $45,$00 ; EXEGGUTOR = 90000 Yen
    db "@"

.PrizeMenuTMsEntries
    db RARE_CANDY
    db TM_16 ; PAY_DAY
    db TM_15 ; HYPER_BEAM
    db TM_50 ; SUBSTITUTE
    db "@"
.PrizeMenuTMsCost
    db $15,$00 ; RARE_CANDY        =  30000 Yen
    db $25,$00 ; TM16 (PAY_DAY)    =  50000 Yen
    db $55,$00 ; TM15 (HYPER_BEAM) = 110000 Yen
    db $77,$00 ; TM50 (SUBSTITUTE) = 154000 Yen
    db "@"

