HandlePrizeChoice: ; 528c6 (14:68c6)
    ld a,[$CC26] ; selected menu_entry
    ld [$D139],a
    ld d,$00
    ld e,a
    ld hl,W_PRIZE1
    add hl,de
    ld a,[hl]
    ld [$D11E],a
    ld a,[$D12F]
    cp $02 ; is prize a TM?
    jr nz,.GetMonName
    call GetItemName
    jr .GivePrize
.GetMonName ; 14:68E3
    call UpdatePokedexAndGetMonName ;  call GetMonName
.GivePrize ; 14:68E6
    ld hl,SoYouWantPrizeTextPtr
    call PrintText
    call YesNoChoice ; yes/no textbox
    ld a,[$CC26] ; yes/no answer (Y=0,N=1)
    and a
    jr nz,.PrintOhFineThen
    call LoadCoinsToSubtract
    call HasEnoughCoins
    jr c,.NotEnoughCoins
    ld a,[$D12F]
    cp $02
    jr nz,.GiveMon
    ld a,[$D11E]
    ld b,a
    ld a,1
    ld c,a
    call PrizeGiveItem ; GiveItem
    jr nc,.BagFull
    jr .SubtractCoins
.GiveMon ; 14:6912
    ld a,[$D11E]
    ld [$CF91],a
    push af
    call GetPrizeMonLevel ; 14:6977
    ld c,a
    pop af
    ld b,a
    call GivePokemon
    push af
    ld a,[$CCD3] ; XXX is there room?
    and a
    call z,WaitForTextScrollButtonPress
    pop af
    ret nc
.SubtractCoins ; 14:692C
    call LoadCoinsToSubtract
    ld hl,$FFA1
    ld de,wPlayerCoins + 1
    ld c,$02 ; how many bytes
    PREDEF Func_f836 ; subtract coins (BCD daa operations)
    jp PrintPrizePrice
.BagFull
    ld hl,PrizeRoomBagIsFullTextPtr
    jp PrintText
.NotEnoughCoins ; 14:6945
    ld hl,SorryNeedMoreCoinsTextPtr
    jp PrintText
.PrintOhFineThen ; 14:694B
    ld hl,OhFineThenTextPtr
    jp PrintText

