GetPrizeMonLevel:
    ld a,[$CF91]
    ld [W_ENEMYMONID],a ; $cfd8
    ld b,a
    ld hl,.PrizeMonLevelDictionary
.loop
    ld a,[hli]
    cp $FF
    jr z,.ErrorNotFound
    cp b
    jr z,.matchFound
    inc hl
    jr .loop
.matchFound
    ld a,[hl]
    ld [W_CURENEMYLVL],a ; $d127
    BANKSWITCH GetWildEnemyLevel
    ld a,[W_CURENEMYLVL] ; $d127
.end
    ld [W_CURENEMYLVL],a ; $d127
    ret
.ErrorNotFound
    ld a,2
    jr .end
.PrizeMonLevelDictionary
    db MAGIKARP,15
    db BUTTERFREE,18
    db DODUO,17 ; Entry Point
    db RHYHORN,19 ; Entry Point
    db STARMIE,31 ; Entry Point
    db ARCANINE,31 ; Entry Point
    db CLOYSTER,31 ; Entry Point
    db EXEGGUTOR,31 ; Entry Point
