GainExperience:
    ld a,[W_ISLINKBATTLE]
    cp $4
    ret z
    call DivideExpDataByNumMonsGainingExp
    ld hl,W_PARTYMON1_NUM
    xor a
    ld [wWhichPokemon],a
.partyMonLoop ; loop over each mon and add gained exp
    inc hl
    ld a,[hli]
    or [hl] ; is mon's HP 0?
    jp z,.nextMon ; if so, go to next mon
    push hl
    ld hl,W_PLAYERMONSALIVEFLAGS
    ld a,[wWhichPokemon]
    ld c,a
    ld b,$2
    PREDEF HandleBitArray
    ld a,c
    and a ; is mon's gain exp flag set?
    pop hl
    jp z,.nextMon ; if mon's gain exp flag not set, go to next mon
    ld de,(W_PARTYMON1_EVHP+1)-(W_PARTYMON1_HP+1)
    add hl,de
    ld d,h
    ld e,l
    ld hl,wEnemyMonBaseStats
    ld c,5
.gainStatExpLoop
    ld a,[hli]
    ld b,a ; enemy mon base stat
    ld a,[de] ; stat exp
    add b ; add enemy mon base state to stat exp
    ld [de],a
    jr nc,.nextBaseStat
; if there was a carry, increment the upper byte
    dec de
    ld a,[de]
    inc a
    jr z,.maxStatExp ; jump if the value overflowed
    ld [de],a
    inc de
    jr .nextBaseStat
.maxStatExp
    ld a,$ff
    ld [de],a
    inc de
    ld [de],a
.nextBaseStat
    dec c
    jr z,.statExpDone
    inc de
    inc de
    jr .gainStatExpLoop
.statExpDone
    call CheckReachLevelLimit
    jp nc,.nextMon
    ld [H_MULTIPLICAND+2],a
    ld a,[W_ENEMYMONLEVEL]
    ld [H_MULTIPLIER],a
    call Multiply
    ld a,7
    ld [H_DIVISOR],a
    ld b,4
    call Divide
    ld a,$0
    ld [$cf4d],a
    ld a,[W_ISINBATTLE]
    dec a ; is it a trainer battle?
    call nz,BoostExp ; if so, boost exp
    call IsCurrentMonBattleMon ; Boost if Current Active Mon
    call z,BoostExpCurrentMon
; add the gained exp to the party mon's exp
    ld hl,(W_PARTYMON1_EXP+2)-(W_PARTYMON1_EVSECIAL+1)
    add hl,de
    ld b,[hl]
    ld a,[H_QUOTIENT+3]
    ld [$cf4c],a ; ExpAmountGained+1
    add b
    ld [hld],a
    ld b,[hl]
    ld a,[H_QUOTIENT+2]
    ld [$cf4b],a ; ExpAmountGained
    adc b
    ld [hl],a
    jr nc,.noCarry
    dec hl
    inc [hl]
    inc hl
.noCarry
; calculate exp for the mon at max level, and cap the exp at that value
    inc hl
    push hl
    ld a,[wWhichPokemon]
    ld c,a
    ld b,$0
    ld hl,W_PARTYMON1
    add hl,bc
    ld a,[hl]
    ld [$d0b5],a
    call GetMonHeaderAndMaxLevel
    BANKSWITCH CalcExperience
; compare max exp with current exp
    ld a,[H_MULTIPLICAND]
    ld b,a
    ld a,[H_MULTIPLICAND+1]
    ld c,a
    ld a,[H_MULTIPLICAND+2]
    ld d,a
    pop hl
    ld a,[hld]
    sub d
    ld a,[hld]
    sbc c
    ld a,[hl]
    sbc b
    jr c,.next2
; the mon's exp is greater than the max exp, so overwrite it with the max exp
    ld a,b
    ld [hli],a
    ld a,c
    ld [hli],a
    ld a,d
    ld [hld],a
    dec hl
.next2
    push hl
    ld a,[wWhichPokemon]
    ld hl,W_PARTYMON1NAME
    call GetPartyMonName
    call GetExperienceTextPointerAndPrintText
    xor a
    ld [$cc49],a
    call LoadMonData
    call AnimateEXPBar
    pop hl
    ld bc,W_PARTYMON1_LEVEL-W_PARTYMON1_EXP
    add hl,bc
    push hl
    BANKSWITCH CalcLevelFromExperience
    pop hl
    ld a,[hl] ; current level
    ld [$cd46],a ; ($cd46 = wTempCoins1) - fixing skip move-learn glitch: need to store the current level in wram
    ;wTempCoins1 was chosen because it's used only for slot machine and gets defaulted to 1 during the mini-game
    cp d
    jp z,.nextMon ; if level didn't change, go to next mon
    call KeepEXPBarFull
    ld a,[W_CURENEMYLVL]
    push af
    push hl
    ld a,d
    ld [W_CURENEMYLVL],a
    ld [hl],a
    ld bc,W_PARTYMON1_NUM-W_PARTYMON1_LEVEL
    add hl,bc
    ld a,[hl]
    ld [$d0b5],a
    ld [$d11e],a
    push hl
    ld bc,W_PARTYMON1_MOVE2PP-W_PARTYMON1_NUM ; go to move2pp
    add hl,bc
    ld a,[hl]
    ld [wAlternateFormIndex],a
    pop hl
    call GetMonHeader
    ld bc,(W_PARTYMON1_MAXHP+1)-W_PARTYMON1_NUM
    add hl,bc
    push hl
    ld a,[hld]
    ld c,a
    ld b,[hl]
    push bc ; push max HP (from before levelling up)
    ld d,h
    ld e,l
    ld bc,(W_PARTYMON1_EVHP-1)-W_PARTYMON1_MAXHP
    add hl,bc
    ld b,1 ; consider stat exp when calculating stats
    call CalcStats
    pop bc ; pop max HP (from before levelling up)
    pop hl
    ld a,[hld]
    sub c
    ld c,a
    ld a,[hl]
    sbc b
    ld b,a ; bc = difference between old max HP and new max HP after levelling
    ld de,(W_PARTYMON1_HP+1)-W_PARTYMON1_MAXHP
    add hl,de
; add to the current HP the amount of max HP gained when levelling
    ld a,[hl] ; W_PARTYMON1_HP + 1
    add c
    ld [hld],a ; W_PARTYMON1_HP + 1
    ld a,[hl] ; W_PARTYMON1_HP
    adc b
    ld [hl],a ; W_PARTYMON1_HP
    call IsCurrentMonBattleMon
    call z,CopyInfoFromMonPartyToBattle
    ld hl,GrewLevelText
    call PrintText
    xor a ; PLAYER_PARTY_DATA
    ld [$cc49],a
    call LoadMonData
    call AnimateEXPBarAgain
    ld d,$1
    BANKSWITCH PrintStatsBox
    call WaitForTextScrollButtonPress
    call LoadScreenTilesFromBuffer1
    xor a ; PLAYER_PARTY_DATA
    ld [$cc49],a
    ld a,[$d0b5]
    ld [$d11e],a
    PREDEF LearnMoveFromLevelUp
    ld hl,$ccd3 ; wCanEvolveFlags
    ld a,[wWhichPokemon]
    ld c,a
    ld b,$1
    PREDEF HandleBitArray
    pop hl
    pop af
    ld [W_CURENEMYLVL],a

.nextMon
    ld a,[W_NUMINPARTY]
    ld b,a
    ld a,[wWhichPokemon]
    inc a
    cp b
    jr z,.done
    ld [wWhichPokemon],a
    ld bc,W_PARTYMON2DATA-W_PARTYMON1DATA
    ld hl,W_PARTYMON1_NUM
    call AddNTimes
    jp .partyMonLoop
.done
    ld hl,wFirstExpAllMessageBit6
    res 6,[hl]
    ld hl,W_PLAYERMONSALIVEFLAGS
    xor a
    ld [hl],a
    ld a,[wPlayerMonNumber]
    ld c,a
    ld b,$1
    push bc
    PREDEF HandleBitArray ; set the gain exp flag for the mon that is currently out
    ld hl,$ccf5 ; PartyFoughtCurrentEnemyFlags
    xor a
    ld [hl],a
    pop bc
    PREDEF_JUMP HandleBitArray ; set the fought current enemy flag for the mon that is currently out

HandleEvolutionDuringBattle:
    ld a,[W_ISINBATTLE]
    cp 2 ; Trainer Battle
    ret nz
    ld hl,wTestEvoDuringBattleBit3
    set 3,[hl]
    BANKSWITCH EvolutionAfterBattlePlus
    ld hl,wTestEvoDuringBattleBit3
    bit 3,[hl]
    res 3,[hl]
    ret nz
.ResetCurrentMonGraphics
    call ClearScreen
    call DisableAutoBgTransfer
    ld a,[wPlayerMonNumber]
    ld [wWhichPokemon],a
    BANKSWITCH LoadBattleMonFromParty
    ld a,[W_PLAYERMONID]
    ld [$d0b5],a
    ld a,[W_PLAYERMONALTFORM]
    ld [wAlternateFormIndex],a
    call GetMonHeader
    ld a,[$cfd9]
    push af
    ld a,[W_MONHEADER]
    ld [$cfd9],a
    PREDEF LoadMonBackSprite
    pop af
    ld [$cfd9],a
    call LoadFontTilePatterns
    BANKSWITCH LoadHudAndHpBarAndStatusTilePatterns
    ld hl,.EmptyText
    call PrintText
    FuncCoord 01,05
    ld hl,Coord
    ld a,$31         ; BackSprite Uncompressed
    ld [$FF00+$e1],a ; offset
    PREDEF CopyUncompressedPicToTilemap
    PREDEF DrawPlayerHUDAndHPBar
    call SaveScreenTilesToBuffer1
    ld c,60
    jp DelayFrames
.EmptyText
    db "@"

CopyInfoFromMonPartyToBattle:
    ld de,W_PLAYERMONCURHP
; copy party mon HP to battle mon HP
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[hl]
    ld [de],a
; copy other stats from party mon to battle mon
    ld bc,W_PARTYMON1_LEVEL-(W_PARTYMON1_HP+1)
    add hl,bc
    push hl
    ld de,W_PLAYERMONLEVEL
    ld bc,1+(5*2) ; size of stats
    call CopyData
    pop hl
    ld a,[W_PLAYERBATTSTATUS3]
    bit 3,a ; is the mon transformed?
    jr nz,.recalcStatChanges
; the mon is not transformed, so update the unmodified stats
    ld de,$cd0f ; PlayerMonUnmodifiedLevel
    ld bc,1+(5*2) ; size of stats
    call CopyData
.recalcStatChanges
    xor a
    ld [$d11e],a
    BANKSWITCH CalculateModifiedStats
    BANKSWITCH ApplyBadgeStatBoostsFull
    BANKSWITCH ApplyBurnAndParalysisPenaltiesToPlayer
    BANKSWITCH DrawPlayerHUDAndHPBar
    BANKSWITCH PrintEmptyString
    jp SaveScreenTilesToBuffer1

BoostExpCurrentMon:
    call TryToBoostUnderLevelled
    jp BoostExpALittle

TryToBoostUnderLevelled:
    ld a,[W_PLAYERMONLEVEL]
    ld b,a
    ld a,[W_ENEMYMONLEVEL]
    cp b
    ret z ; return if enemy lvl = player level
    ret c ; return if enemy lvl < player level
    jp BoostExp

; add 1/16 exp to exp
BoostExpALittle:
    ld a,[$FF00+$97]
    ld b,a
    ld a,[$FF00+$98]
    ld c,a
    srl b
    rr c
    srl b
    rr c
    srl b
    rr c
    srl b
    rr c
    jr BoostCommon

; multiplies exp by 1.5
BoostExp: ; 5549f (15:549f)
    ld a,[$FF00+$97]
    ld b,a
    ld a,[$FF00+$98]
    ld c,a
    srl b
    rr c
BoostCommon:
    add c
    ld [$FF00+$98],a
    ld a,[$FF00+$97]
    adc b
    ld [$FF00+$97],a
    ret nc ; no overflow
    ld a,$FF
    ld [$FF00+$97],a
    ld [$FF00+$98],a
    ret

