TrainerWalkUpToPlayer: ; 56881 (15:6881)
    ld a,[$cf13]
    swap a
    ld [wTrainerSpriteOffset],a ; $cd3d
    call ReadTrainerScreenPosition
    ld a,[wTrainerFacingDirection]
    and a
    jr z,.facingDown
    cp $4
    jr z,.facingUp
    cp $8
    jr z,.facingLeft
    jr .facingRight
.facingDown
    ld a,[wTrainerScreenY]
    ld b,a
    ld a,$3c           ; (fixed) player screen Y pos
    call CalcDifference
    cp $10              ; trainer is right above player
    ret z
    swap a
    dec a
    ld c,a             ; bc = steps yet to go to reach player
    xor a
    ld b,a           ; a = direction to go to
    jr .writeWalkScript
.facingUp
    ld a,[wTrainerScreenY]
    ld b,a
    ld a,$3c           ; (fixed) player screen Y pos
    call CalcDifference
    cp $10              ; trainer is right below player
    ret z
    swap a
    dec a
    ld c,a             ; bc = steps yet to go to reach player
    ld b,$0
    ld a,$40           ; a = direction to go to
    jr .writeWalkScript
.facingRight
    ld a,[wTrainerScreenX]
    ld b,a
    ld a,$40           ; (fixed) player screen X pos
    call CalcDifference
    cp $10              ; trainer is directly left of player
    ret z
    swap a
    dec a
    ld c,a             ; bc = steps yet to go to reach player
    ld b,$0
    ld a,$c0           ; a = direction to go to
    jr .writeWalkScript
.facingLeft
    ld a,[$cd41]
    ld b,a
    ld a,$40           ; (fixed) player screen X pos
    call CalcDifference
    cp $10              ; trainer is directly right of player
    ret z
    swap a
    dec a
    ld c,a             ; bc = steps yet to go to reach player
    ld b,$0
    ld a,$80           ; a = direction to go to
.writeWalkScript
    ld hl,$cc97
    ld de,$cc97
    call FillMemory     ; write the necessary steps to reach player
    ld [hl],$ff        ; write end of list sentinel
    ld a,[$cf13]
    ld [H_DOWNARROWBLINKCNT2],a ; $FF00+$8c
    jp MoveSprite_

Func_56903: ; 56903 (15:6903)
    push de
    add hl,de
    ld a,[H_DOWNARROWBLINKCNT2] ; $FF00+$8c
    swap a
    ld d,$0
    ld e,a
    add hl,de
    pop de
    ret

; tests if this trainer is in the right position to engage the player and do so if she is.
CheckEngagePlayer: ; 5690f (15:690f)
    push hl
    push de
    ld a,[wTrainerSpriteOffset] ; $cd3d
    add $2
    ld d,$0
    ld e,a
    ld hl,wSpriteStateData1
    add hl,de
    ld a,[hl]             ; c1x2: sprite image index
    sub $ff
    jr nz,.spriteOnScreen ; test if sprite is on screen
    jp .noEngage
.spriteOnScreen
    ld a,[wTrainerSpriteOffset] ; $cd3d
    add $9
    ld d,$0
    ld e,a
    ld hl,wSpriteStateData1
    add hl,de
    ld a,[hl]             ; c1x9: facing direction
    ld [$cd3f],a
    call ReadTrainerScreenPosition
    ld a,[$cd40]          ; sprite screen Y pos
    ld b,a
    ld a,$3c
    cp b
    jr z,.linedUpY
    ld a,[$cd41]          ; sprite screen X pos
    ld b,a
    ld a,$40
    cp b
    jr z,.linedUpX
    xor a
    jp .noEngage
.linedUpY
    ld a,[$cd41]        ; sprite screen X pos
    ld b,a
    ld a,$40            ; (fixed) player X position
    call CalcDifference  ; calc distance
    jr z,.noEngage      ; exact same position as player
    call CheckSpriteCanSeePlayer
    jr c,.engage
    xor a
    jr .noEngage
.linedUpX
    ld a,[$cd40]        ; sprite screen Y pos
    ld b,a
    ld a,$3c            ; (fixed) player Y position
    call CalcDifference  ; calc distance
    jr z,.noEngage      ; exact same position as player
    call CheckSpriteCanSeePlayer
    jr c,.engage
    xor a
    jp .noEngage
.engage
    call CheckPlayerIsInFrontOfSprite
    ld a,[wTrainerSpriteOffset] ; $cd3d
    and a
    jr z,.noEngage
    ld hl,wFlags_0xcd60
    set 0,[hl]
    call EngageMapTrainer
    ld a,$ff
.noEngage: ; 56988 (15:6988)
    ld [wTrainerSpriteOffset],a ; $cd3d
    pop de
    pop hl
    ret

; reads trainer's Y position to $cd40 and X position to $cd41
ReadTrainerScreenPosition: ; 5698e (15:698e)
    ld a,[wTrainerSpriteOffset] ; $cd3d
    add $4
    ld d,$0
    ld e,a
    ld hl,wSpriteStateData1
    add hl,de
    ld a,[hl]
    ld [$cd40],a
    ld a,[wTrainerSpriteOffset] ; $cd3d
    add $6
    ld d,$0
    ld e,a
    ld hl,wSpriteStateData1
    add hl,de
    ld a,[hl]
    ld [$cd41],a
    ret

; checks if the sprite is properly lined up with the player with respect to the direction it's looking. Also checks the distance between player and sprite
; note that this does not necessarily mean the sprite is seeing the player,he could be behind it's back
; a: distance player to sprite
CheckSpriteCanSeePlayer: ; 569af (15:69af)
    ld b,a
    ld a,[wTrainerEngageDistance]  ; sprite line of sight (engage distance)
    cp b
    jr nc,.checkIfLinedUp
    jr .notInLine         ; player too far away
.checkIfLinedUp
    ld a,[$cd3f]         ; sprite facing direction
    cp $0                 ; down
    jr z,.checkXCoord
    cp $4                 ; up
    jr z,.checkXCoord
    cp $8                 ; left
    jr z,.checkYCoord
    cp $c                 ; right
    jr z,.checkYCoord
    jr .notInLine
.checkXCoord
    ld a,[$cd41]         ; sprite screen X position
    ld b,a
    cp $40
    jr z,.inLine
    jr .notInLine
.checkYCoord
    ld a,[$cd40]         ; sprite screen Y position
    ld b,a
    cp $3c
    jr nz,.notInLine
.inLine
    scf
    ret
.notInLine
    and a
    ret

; tests if the player is in front of the sprite (rather than behind it)
CheckPlayerIsInFrontOfSprite: ; 569e3 (15:69e3)
    call GetCurrentOldAdventureMap
    cp POWER_PLANT
    jp z,.engage       ; XXX not sure why bypass this for power plant (maybe to get voltorb fake items to work?)
    ld a,[wTrainerSpriteOffset] ; $cd3d
    add $4
    ld d,$0
    ld e,a
    ld hl,wSpriteStateData1
    add hl,de
    ld a,[hl]          ; c1x4 (sprite screen Y pos)
    cp $fc
    jr nz,.notOnTopmostTile ; special case if sprite is on topmost tile (Y = $fc (-4)),make it come down a block
    ld a,$c
.notOnTopmostTile
    ld [$cd40],a
    ld a,[wTrainerSpriteOffset] ; $cd3d
    add $6
    ld d,$0
    ld e,a
    ld hl,wSpriteStateData1
    add hl,de
    ld a,[hl]          ; c1x6 (sprite screen X pos)
    ld [$cd41],a
    ld a,[$cd3f]       ; facing direction
    cp $0
    jr nz,.notFacingDown
    ld a,[$cd40]       ; sprite screen Y pos
    cp $3c
    jr c,.engage       ; sprite above player
    jr .noEngage        ; sprite below player
.notFacingDown
    cp $4
    jr nz,.notFacingUp
    ld a,[$cd40]       ; sprite screen Y pos
    cp $3c
    jr nc,.engage      ; sprite below player
    jr .noEngage        ; sprite above player
.notFacingUp
    cp $8
    jr nz,.notFacingLeft
    ld a,[$cd41]       ; sprite screen X pos
    cp $40
    jr nc,.engage      ; sprite right of player
    jr .noEngage        ; sprite left of player
.notFacingLeft
    ld a,[$cd41]       ; sprite screen X pos
    cp $40
    jr nc,.noEngage    ; sprite right of player
.engage
    ld a,$ff
    jr .done
.noEngage
    xor a
.done
    ld [wTrainerSpriteOffset],a ; $cd3d
    ret

AnimateEXPBarAgain:
    call IsCurrentMonBattleMon
    ret nz
    xor a
    ld [wEXPBarPixelLength],a
    FuncCoord 17,11
    ld hl,Coord
    ld a,$c0
    ld c,$08
.loop
    ld [hld],a
    dec c
    jr nz,.loop
AnimateEXPBar:
    call IsCurrentMonBattleMon
    ret nz
    ld a,(SFX_08_3d - $4000) / 3
    call PlaySoundWaitForCurrent
    BANKSWITCH CalcEXPBarPixelLength
    ld a,[wEXPBarPixelLength]
    ld b,a
    ld a,[H_QUOTIENT + 3]
    sub b
    jr z,.done
    ld b,a
    ld c,$08
    FuncCoord 17,11
    ld hl,Coord
.loop1
    ld a,[hl]
    cp $c8
    jr nz,.loop2
    dec hl
    dec c
    jr z,.done
    jr .loop1
.loop2
    inc a
    ld [hl],a
    call DelayFrame
    dec b
    jr z,.done
    jr .loop1
.done
    ld bc,$08
    FuncCoord 10,11
    ld hl,Coord
    ld de,$c5ee
    call CopyData
    ld c,$20
    jp DelayFrames

KeepEXPBarFull:
    call IsCurrentMonBattleMon
    ret nz
    ld a,[wEXPBarKeepFullFlag]
    set 0,a
    ld [wEXPBarKeepFullFlag],a
    ret

IsCurrentMonBattleMon:
    ld a,[wPlayerMonNumber]
    ld b,a
    ld a,[wWhichPokemon]
    cp b
    ret

SetFirstExpAllMessage:
    ld a,[$cc5b]
    and a
    ret z
    ld a,[H_CURRENTPRESSEDBUTTONS]
    bit 2,a ; was the select button pressed?
    jr z,.NotSelect
    xor a
    ld [$cc5b],a ; If Select FORCE All Details
    ret
.NotSelect
    ld a,[wFirstExpAllMessageBit6]
    set 6,a
    ld [wFirstExpAllMessageBit6],a
    ret

DivideExpDataByNumMonsGainingExp:
    call SetFirstExpAllMessage
    ld a,[W_PLAYERMONSALIVEFLAGS]
    ld [wBackupFlagGainingExp],a ; make a backup of flagged mons gaining exp
    ld b,a
    xor a
    ld c,$8
    ld d,$0
.asm_55475
    xor a
    srl b
    adc d
    ld d,a
    dec c
    jr nz,.asm_55475
    cp $2
    ret c
    ld [$d11e],a
    ld hl,$d002
    ld c,$7
.asm_55488
    xor a
    ld [H_DIVIDEND],a ; $FF00+$95 (aliases: H_PRODUCT,H_PASTLEADINGZEROES,H_QUOTIENT)
    ld a,[hl]
    ld [H_NUMTOPRINT],a ; $FF00+$96 (aliases: H_MULTIPLICAND)
    ld a,[$d11e]
    ld [H_REMAINDER],a ; $FF00+$99 (aliases: H_DIVISOR,H_MULTIPLIER,H_POWEROFTEN)
    ld b,$2
    call Divide
    ld a,[$FF00+$98]
    inc a ; Add 1 Point to Limit Approx Error
    ld [hli],a
    dec c
    jr nz,.asm_55488
    ret

GetExperienceTextPointerAndPrintText:
    ld a,[$cc5b]
    and a
    ld hl,UnnamedText_554b2 ; $54b2
    jr z,.noexpall
.exp_all
    ld a,[wFirstExpAllMessageBit6]
    bit 6,a
    ret z ; NO exp.all text
    res 6,a
    ld [wFirstExpAllMessageBit6],a
    ld hl,WithExpAllText
.noexpall
    jp PrintText

WithExpAllText:
    TX_FAR _WithExpAllText
    db "@"

GetMonHeaderAndMaxLevel:
    ld hl,W_PARTYMON1_MOVE2PP
    ld a,[wWhichPokemon]
    ld bc,$2c
    call AddNTimes
    ld a,[hl]
    ld [wAlternateFormIndex],a
    call GetMonHeader
    BANKSWITCH_JUMP GetMaxLevel

CheckReachLevelLimit:
    push de
    ld hl,-10
    add hl,de
; calculate exp for the mon at max level
    push hl
    ld a,[wWhichPokemon]
    ld c,a
    ld b,0
    ld hl,W_PARTYMON1
    add hl,bc
    ld a,[hl]
    ld [$d0b5],a
    call GetMonHeaderAndMaxLevel
    BANKSWITCH CalcExperience
; compare max exp with current exp
    ld a,[H_MULTIPLICAND]
    ld b,a
    ld a,[H_MULTIPLICAND+1]
    ld c,a
    ld a,[H_MULTIPLICAND+2]
    ld d,a
    pop hl
    ld a,[hld]
    sub d
    ld a,[hld]
    sbc c
    ld a,[hl]
    sbc b ; If Carry Flag = 0 -> the mon's exp is greater than the max exp
    pop de
    ret nc
; Original Code
    xor a ; Reset Carry Flag
    ld [H_MULTIPLICAND],a
    ld [H_MULTIPLICAND+1],a
    ld a,[wEnemyMonBaseExp]
    scf ; Set Carry Flag
    ret

