; calculates the amount of experience needed for level d
CalcExperience: ; 58f6a (16:4f6a)
    ld a,[W_MONHGROWTHRATE]
    add a
    add a
    ld c,a
    ld b,$0
    ld hl,GrowthRateTable
    add hl,bc
    call CalcDSquared
    ld a,d
    ld [H_MULTIPLIER],a ; $FF00+$99
    call Multiply
    ld a,[hl]
    and $f0
    swap a
    ld [H_MULTIPLIER],a ; $FF00+$99
    call Multiply
    ld a,[hli]
    and $f
    ld [H_DIVISOR],a ; $FF00+$99
    ld b,$4
    call Divide
    ld a,[H_MULTIPLICAND] ; $FF00+$96 (aliases: H_NUMTOPRINT)
    push af
    ld a,[H_MULTIPLICAND+1]
    push af
    ld a,[H_MULTIPLICAND+2]
    push af
    call CalcDSquared
    ld a,[hl]
    and $7f
    ld [H_MULTIPLIER],a ; $FF00+$99
    call Multiply
    ld a,[H_MULTIPLICAND] ; $FF00+$96 (aliases: H_NUMTOPRINT)
    push af
    ld a,[H_MULTIPLICAND+1]
    push af
    ld a,[H_MULTIPLICAND+2]
    push af
    ld a,[hli]
    push af
    xor a
    ld [H_MULTIPLICAND],a ; $FF00+$96
    ld [H_MULTIPLICAND+1],a
    ld a,d
    ld [H_MULTIPLICAND+2],a
    ld a,[hli]
    ld [H_MULTIPLIER],a
    call Multiply
    ld b,[hl]
    ld a,[H_MULTIPLICAND+2]
    sub b
    ld [H_MULTIPLICAND+2],a
    ld b,$0
    ld a,[H_MULTIPLICAND+1]
    sbc b
    ld [H_MULTIPLICAND+1],a
    ld a,[H_MULTIPLICAND] ; $FF00+$96
    sbc b
    ld [H_MULTIPLICAND],a ; $FF00+$96
    pop af
    and $80
    jr nz,.subtractSquaredTerm ; check sign
    pop bc
    ld a,[H_MULTIPLICAND+2]
    add b
    ld [H_MULTIPLICAND+2],a
    pop bc
    ld a,[H_MULTIPLICAND+1]
    adc b
    ld [H_MULTIPLICAND+1],a
    pop bc
    ld a,[H_MULTIPLICAND]
    adc b
    ld [H_MULTIPLICAND],a
    jr .addCubedTerm
.subtractSquaredTerm
    pop bc
    ld a,[H_MULTIPLICAND+2]
    sub b
    ld [H_MULTIPLICAND+2],a
    pop bc
    ld a,[H_MULTIPLICAND+1]
    sbc b
    ld [H_MULTIPLICAND+1],a
    pop bc
    ld a,[H_MULTIPLICAND]
    sbc b
    ld [H_MULTIPLICAND],a
.addCubedTerm
    pop bc
    ld a,[H_MULTIPLICAND+2]
    add b
    ld [H_MULTIPLICAND+2],a
    pop bc
    ld a,[H_MULTIPLICAND+1]
    adc b
    ld [H_MULTIPLICAND+1],a
    pop bc
    ld a,[H_MULTIPLICAND]
    adc b
    ld [H_MULTIPLICAND],a
    ret

; calculates d*d
CalcDSquared: ; 59010 (16:5010)
    xor a
    ld [H_MULTIPLICAND],a ; $FF00+$96 (aliases: H_NUMTOPRINT)
    ld [H_MULTIPLICAND+1],a
    ld a,d
    ld [H_MULTIPLICAND+2],a
    ld [H_MULTIPLIER],a ; $FF00+$99 (aliases: H_DIVISOR,H_REMAINDER,H_POWEROFTEN)
    jp Multiply

SECTION "GrowthRateTable",ROMX[$501d],BANK[$16]

; each entry has the following scheme:
; %AAAABBBB %SCCCCCCC %DDDDDDDD %EEEEEEEE
; resulting in
;  (a*n^3)/b + sign*c*n^2 + d*n - e
; where sign = -1 <=> S=1
GrowthRateTable: ; 5901d (16:501d) ; Don't Move this Subroutine (MissingNo Growth Rate)
    db $11,$00,$00,$00 ; medium fast      n^3
    db $34,$0A,$00,$1E ; (unused?)    3/4 n^3 + 10 n^2         - 30
    db $34,$14,$00,$46 ; (unused?)    3/4 n^3 + 20 n^2         - 70
    db $65,$8F,$64,$8C ; medium slow: 6/5 n^3 - 15 n^2 + 100 n - 140
    db $45,$00,$00,$00 ; fast:        4/5 n^3
    db $54,$00,$00,$00 ; slow:        5/4 n^3
   ;db $08,$21,$9B,$50 ; missingno:   0/8 n^3 + 33 n^2 + 155 n - 80

SECTION "OakAideNDexToGiftItem",ROMX[$5035],BANK[$16]

OakAideNDexToGiftItem: ; 0x59035 ; Don't Move this Subroutine (MissingNo Growth Rate)
    ld hl,UnnamedText_59091 ; $5091
    call PrintText
    call YesNoChoice
    ld a,[$cc26]
    and a
    jr nz,.asm_59086 ; 0x59042 $42
    ld hl,wPokedexOwned ; $d2f7
    ld b,wPokedexOwnedEnd - wPokedexOwned
    call CountSetBits
    ld a,[$d11e]
    ld [$ff00+$dd],a
    ld b,a
    ld a,[$ff00+$db]
    cp b
    jr z,.asm_59059 ; 0x59055 $2
    jr nc,.asm_5907c ; 0x59057 $23
.asm_59059
    ld hl,UnnamedText_590a0 ; $50a0
    call PrintText
    ld a,[$ff00+$dc]
    ld b,a
    ld c,1
    call GiveItem
    jr nc,.BagFull
    ld hl,UnnamedText_590a5 ; $50a5
    call PrintText
    ld a,$1
    jr .asm_5908e ; 0x59071 $1b
.BagFull
    ld hl,UnnamedText_590ab ; $50ab
    call PrintText
    xor a
    jr .asm_5908e ; 0x5907a $12
.asm_5907c
    ld hl,UnnamedText_59096 ; $5096
    call PrintText
    ld a,$80
    jr .asm_5908e ; 0x59084 $8        ; Dex#00 Growth Rate
.asm_59086
    ld hl,UnnamedText_5909b ; $509b   ; ... = $08,$21,$9B,$50
    call PrintText
    ld a,$ff
.asm_5908e
    ld [$ff00+$db],a
    ret

