Route12Script0: ; 59619 (16:5619)
    ld hl,$d7d8
    bit 7,[hl]
    jp nz,CheckFightingMapTrainers
    bit 6,[hl]
    res 6,[hl]
    jp z,CheckFightingMapTrainers
    ld a,SNORLAX
    call PlayCry
    call WaitForSoundToFinish
    ld a,$d
    ld [H_DOWNARROWBLINKCNT2],a ; $FF00+$8c
    call DisplayTextID
    ret

Route12Script3: ; 5964c (16:564c)
    ld a,[W_ISINBATTLE] ; $d057
    cp $ff
    jr z,Route12Script_59606
    ld a,[wBattleResult]
    cp $2
    jr z,.asm_59664
    ld a,$e
    ld [H_DOWNARROWBLINKCNT2],a ; $FF00+$8c
    call DisplayTextID
.asm_59664
    ld a,$1d
    ld [$cc4d],a
    PREDEF RemoveMissableObject
    call UpdateSprites
    ld hl,$d7d8
    set 7,[hl]
    call Delay3
    ld a,$0
    ld [W_ROUTE12CURSCRIPT],a
    ld [W_CURMAPSCRIPT],a
    ret

