    res 1,[hl]
    inc hl
    set 0,[hl]
    call .Wait
    call WaitForTextScrollButtonPress
    ld hl,$d5a2
    ld a,[hl]
    inc a
    jr z,.skip
    inc [hl]
.skip
    PREDEF HoF_SetVariables
    ld hl,wFlagsGymLeaderAfterHoFWin
