    call CountSetBits
    cp 7
    jr c,.skip2
    ld hl,wFlagsGymLeaderAfterHoFWin
    set 7,[hl]
.skip2
    ld a,%01111111
    call StoreGymLeaderRematch
    call GBFadeOut2
    ld a,8
    call StopMusic
    ld c,50
    call DelayFrames
    BANKSWITCH_JUMP SpecialRestartAfterHallOfFame
.Wait
    ld b,$5
.loop
    ld c,$78
    call DelayFramesCredits
    dec b
    jr nz,.loop
    ret

