FightingDojoText6: ; 5cf06 (17:4f06)
; Hitmonlee Poké Ball
    db $08 ; asm
    ld a,[$d7b1]
    and %11000000
    jr z,.GetMon
    push de
    call GetLastFighter ; ld hl,OtherHitmonText
    pop de
    ds 1 ; call PrintText
    jr .done
.GetMon
    ld a,HITMONLEE ; Entry Point
    call UpdatePokedex
    ld hl,WantHitmonleeText
    call PrintText
    call YesNoChoice
    ld a,[$cc26]
    and a
    jr nz,.done
    ld a,[$cf91]
    ld b,a
    ld c,30
    call GivePokemon
    jr nc,.done

    ; once Poké Ball is taken,hide sprite
    ld a,$4a
    ld [$cc4d],a
    PREDEF RemoveMissableObject
    ld hl,$d7b1
    set 6,[hl]
    set 0,[hl]
.done
    jp TextScriptEnd

