    ld a,[$d730]
    bit 0,a
    ret nz
    call Func_61416
    xor a
    ld [wJoypadForbiddenButtonsMask],a
    ld a,$2
    ld [$ff00+$8c],a
    call DisplayTextID
    call Delay3
    ld a,SONY2
    ld [W_CUROPPONENT],a ; $d059

    ; select which team to use during the encounter
    ld a,[W_RIVALSTARTER]
    cp SQUIRTLE
    jr nz,.NotSquirtle ; 0x61451 $4
    ld a,$1
    jr .done
.NotSquirtle
    cp BULBASAUR
    jr nz,.Charmander ; 0x61459 $4
    ld a,$2
    jr .done
.Charmander
    ld a,$3
.done
    ld [W_TRAINERNO],a

    call Func_61416
    ld a,$2
    ld [W_SSANNE2CURSCRIPT],a
    ret

