    xor a
    ld [wWhichTrade],a ; $cd3d
    pop af
.RestartCurrentMap
    call .SetTownMapBeforeJoypad
    jr .enterLoop
.townMapLoop
    call .TestAndResetTownMapBeforeJoypad
    jr z,.skip
    xor a
    ld [wWhichTrade],a ; $cd3d
.skip
    call .ClearTitle
    call ChoiceTownMapOrder ; ld hl,TownMapOrder ; $4f11
    ld a,[wWhichTrade] ; $cd3d
    ld c,a
    ld b,$0
    add hl,bc
    ld a,[hl]
.enterLoop:
    ld de,$cee9
    call LoadTownMapEntry
    ld a,[de]
    push hl
    call TownMapCoordsToOAMCoords
    ld a,$4
    ld [$cd5b],a
    ld hl,$c310
    call Func_71279
    pop hl
    ld de,$cd6d
.asm_70eac
    ld a,[hli]
    ld [de],a
    inc de
    cp $50
    jr nz,.asm_70eac
    FuncCoord 1,0 ; $c3a1
    ld hl,Coord
    ld de,$cd6d
    call PlaceString
    ld hl,$c310
    ld de,$c518
    ld bc,$10
    call CopyData
.inputLoop
    call Func_716c6
    call GetJoypadStateLowSensitivity
    ld a,[$FF00+$b5]
    ld b,a
    and %11000111 ; ▼▲◄►StSeBA
    jr z,.inputLoop
    ld a,$8c
    call PlaySound
    bit 2,b
    jr nz,.selectPressed
    bit 6,b
    jr nz,.pressedUp
    bit 7,b
    jr nz,.pressedDown
    call .TestAndResetTownMapBeforeJoypad
    xor a
    ld [$d09b],a
    ld [$FF00+$b7],a
    ld [W_SUBANIMTRANSFORM],a ; $d08b
    call Func_711ab
    pop hl
    pop af
    ld [hl],a
    ret
.pressedUp
    ld a,[wWhichTrade] ; $cd3d
    inc a
    call CompareWithMaxNumberOfTownInCurrentWorld ; cp TownMapOrderEnd-TownMapOrder ; number of list items + 1
    jr nz,.noOverflow
    xor a
.noOverflow
    ld [wWhichTrade],a ; $cd3d
    jp .townMapLoop
.pressedDown
    ld a,[wWhichTrade] ; $cd3d
    dec a
    cp -1
    jr nz,.noUnderflow
    call LoadMaxNumberOfTownInCurrentWorld ; ld a,TownMapOrderEnd-TownMapOrder-1 ; number of list items
.noUnderflow
    ld [wWhichTrade],a ; $cd3d
    jp .townMapLoop
.selectPressed
    call .ClearTitle
    ld a,[W_CURMAP]
    jp .RestartCurrentMap

.SetTownMapBeforeJoypad
    ld hl,wTownMapBeforeJoypadBit0
    set 0,[hl]
    ret

.TestAndResetTownMapBeforeJoypad
    ld hl,wTownMapBeforeJoypadBit0
    bit 0,[hl]
    res 0,[hl]
    ret

