LoadTrainerCardBadgePalettes:
    ld de,$030C ; Coordinate 03,12
    ld hl,$cc5d
    ld a,[W_OBTAINEDBADGES]
    ld c,8
    ld b,0
.loop
    srl a
    push af
    jr nc,.nextBadge
.haveBadge
    call .CheckRainbowException
    jr z,.RainbowException
    call .HandleRule
    call .HandleColor
    call .Handle1stCoord
    call .Handle2ndCoord
    jr .BadgeInsertDone
.RainbowException
    call .HandleRainbowBadge
.BadgeInsertDone
    inc b
    call .NextBadgeCoord
.nextBadge
    pop af
    dec c
    jr nz,.loop
    call .CheckAtLeastOneRule
    call .GetCommandLenght
    ld [$cc5b],a
    ld a,b
    ld [$cc5c],a
    ld hl,PalPacket_72498
    ld de,$cc5b
    ret

.CheckAtLeastOneRule
    ld a,b
    and a
    ret nz
    push bc
    ld d,h
    ld e,l
    ld hl,.FakeRule
    ld bc,6
    call CopyData
    pop bc
    inc b
    ret
.FakeRule
    db %00000100,%00000000
    db $00,$00,$00,$00

.NextBadgeCoord
    ld a,[W_OBTAINEDBADGES]
    bit 3,a ; Check Rainbow
    ld a,b
    jr z,.noRainbow
    sub 2
.noRainbow
    cp 4
    jr nz,.skip
    push hl
    ld hl,-$0C00+$0003
    add hl,de
    ld d,h
    ld e,l
    pop hl
    ret
.skip
    inc d
    inc d
    inc d
    inc d
    ret

.GetBadgeColor
    push hl
    push bc
    ld hl,.BadgeColor
    ld a,8
    sub c
    ld b,0
    ld c,a
    add hl,bc
    ld a,[hl]
    pop bc
    pop hl
    ret
.BadgeColor
    db %00000000 ; Boulder Badge
    db %00000101 ; Cascade Badge
    db %00001111 ; Thunder Badge
    db %00000000 ; Rainbow Badge (Not Used)
    db %00001010 ; Soul Badge
    db %00001111 ; Marsh Badge
    db %00001010 ; Volcano Badge
    db %00000101 ; Earth Badge

.HandleRainbowBadge
    push bc
    ld bc,.RainbowBadgeColorCoord
    ld a,3
.RainbowLoop
    push af
    ; Rule
    ld a,%00000010
    ld [hli],a
    ; Color
    ld a,[bc]
    ld [hli],a
    inc bc
    ; Coord
    ld a,[bc]
    add d
    ld [hli],a
    inc hl
    ld [hld],a
    inc bc
    ld a,[bc]
    add e
    ld [hli],a
    inc hl
    ld [hli],a
    inc bc
    pop af
    dec a
    jr nz,.RainbowLoop
    pop bc
    inc b
    inc b
    ret
.RainbowBadgeColorCoord
    db %00001010,01,00 ; Upper Right
    db %00000101,00,01 ; Bottom Left
    db %00001111,01,01 ; Bottom Right

.GetCommandLenght ; ($4 << 3) + ((\1 * 6) / 16 + 1)
    push bc
    ld a,b
    add b
    add b
    add b
    add b
    add b
    srl a
    srl a
    srl a
    srl a
    inc a
    ld b,$20
    add b
    pop bc
    ret

.HandleRule
    ld a,%00000010 ; Rule
    ld [hli],a
    ret

.HandleColor
    call .GetBadgeColor
    ld [hli],a
    ret

.Handle1stCoord
    ld a,d
    ld [hli],a
    ld a,e
    ld [hli],a
    ret

.Handle2ndCoord
    ld a,d
    inc a
    ld [hli],a
    ld a,e
    inc a
    ld [hli],a
    ret

.CheckRainbowException
    ld a,c
    cp 5
    ret

