GetBattleScreenPaletteID: ; 71e06 (1c:5e06)
    ld hl,PalPacket_72428
    ld de,$cf2d
    ld bc,$10
    call CopyData

    call BackupHeader

    ; Get Front Palette
    ld hl,W_ENEMYMONID
    ld a,[hl]
    call CheckShinyFrontAndGetPAL ; DONE:Palette
    push hl ; Backup frontsprite palette

    ; Get Back Palette
    ld hl,W_PLAYERMONID
    ld a,[hl]
    call CheckShinyBackAndGetPAL ; DONE:Palette
    push hl ; Backup backsprite palette

    call RestoreHeader

    ld hl,$cf2e

    ; backsprite palette
    pop bc ; Restore backsprite palette
    ld a,c
    ld [hli],a
    ld a,b
    ld [hli],a

    ; frontsprite palette
    pop de ; Restore frontsprite palette
    ld a,e
    ld [hli],a
    ld a,d
    ld [hli],a

    call FirstHPBarPalette ; palette hp bar : player?

    ; palette hp bar : opponent?
    ld a,[$cf1e]
    add PAL_GREENBAR
    ld [hl],a

    ld hl,$cf2d
    ld de,Unknown_721b5
    ld a,$1
    ld [$cf1c],a
    ret

