CheckFlyingMonSprite:
    push hl
    ld hl,wFlagFlyingMonSpriteBit0
    bit 0,[hl]
    res 0,[hl]
    jr z,.CheckBit1
    ld bc,$0040
    jr .end
.CheckBit1
    bit 1,[hl] ; wFlagFlyingMonSpriteBit1
    res 1,[hl]
    jr z,.CheckBit2
    ld bc,$0080
    jr .end
.CheckBit2
    bit 2,[hl] ; wFlagFlyingMonSpriteBit2
    res 2,[hl]
    jr z,.skip
    ld bc,$0880
.end
    pop hl
    add hl,bc
    ret
.skip
    pop hl
    ret

