; checks if the tile in front of the player is a shore or water tile
; used for surfing and fishing
; unsets carry if it is,sets carry if not
_IsNextTileShoreOrWater:
    ld a,[W_CURMAPTILESET]
    ld hl,WaterTilesets
    ld de,1
    call IsInArray
    jr nc,.notShoreOrWater
    ld hl,WaterTile
    ld a,[W_CURMAPTILESET]
    cp $0e ; Vermilion Dock tileset
    jr z,.skipShoreTiles
    cp $07 ; Gym tileset
    jr z,.skipShoreTiles
    cp $05 ; Dojo/Lance/OakLab tileset
    jr z,.skipShoreTiles
    ld hl,ShoreTiles
.skipShoreTiles
    ld a,[$cfc6] ; tile in front of player
    ld de,$1
    call IsInArray
    jr c,.shoreOrWater
.notShoreOrWater
    scf
    ret
.shoreOrWater
    and a
    ret

; shore tiles
ShoreTiles:
    db $48,$32
WaterTile:
    db $14
    db $ff ; terminator

; tilesets with water
WaterTilesets:
    db $00,$03,$05,$07,$0d,$0e,$11,$16,$17
    db $ff ; terminator

