SECTION "LoadSAV",ROMX[$75e8],BANK[$1C]

LoadSAV: ; 735e8 (1c:75e8)
;(if carry -> write
;"the file data is destroyed")
    call ClearScreen
    call LoadFontTilePatterns
    call LoadTextBoxTilePatterns
    call LoadSAVCheckSum
    jr c,.badsum
    call LoadSAVCheckSum1
    jr c,.badsum
    call LoadSAVCheckSum2
    jr c,.badsum
    ld a,$2 ; good checksum
    jr .goodsum
.badsum
    ld hl,$d730
    push hl
    set 6,[hl]
    ld hl,FileDataDestroyedText ; $761e
    call PrintText
    ld c,$64
    call DelayFrames
    pop hl
    res 6,[hl]
    ld a,$1 ; bad checksum
.goodsum
    ld [$d088],a ; checksum flag
    ret

FileDataDestroyedText: ; 7361e (1c:761e)
    TX_FAR _FileDataDestroyedText
    db "@"

LoadSAVCheckSum: ; 73623 (1c:7623)
    ld a,$a
    ld [$0],a
    ld a,$1
    ds 3
    ld [$4000],a
    ld hl,$a598 ; hero name located in SRAM
    ld bc,$f8b ; but here checks the full SAV
    call SAVCheckSum
    ld c,a
    ld a,[$b523] ; SAV's checksum
    cp c
    jp z,.Func_73652
    ld hl,$a598
    ld bc,$f8b
    call SAVCheckSum
    ld c,a
    ld a,[$b523] ; SAV's checksum
    cp c
    jp nz,SAVBadCheckSum

.Func_73652 ; 73652 (1c:7652)
    ld hl,$a598
    ld de,W_PLAYERNAME ; $d158
    ld bc,$b
    call CopyData
    ld hl,$a5a3
    ld de,wPokedexOwned ; $d2f7
    ld bc,$789
    call CopyData
    ld hl,W_CURMAPTILESET ; $d367
    set 7,[hl]
    ld hl,$ad2c
    ld de,wSpriteStateData1
    ld bc,$200
    call CopyData
    ld a,[$b522]
    ld [$FF00+$d7],a
    ld hl,$b0c0
    ld de,W_NUMINBOX ; $da80
    ld bc,$462
    call CopyData
    and a
    jp SAVGoodChecksum

LoadSAVCheckSum1: ; 73690 (1c:7690)
    ld a,$a
    ld [$0],a
    ld a,$1
    ds 3
    ld [$4000],a
    ld hl,$a598 ; hero name located in SRAM
    ld bc,$f8b  ; but here checks the full SAV
    call SAVCheckSum
    ld c,a
    ld a,[$b523] ; SAV's checksum
    cp c
    jr nz,SAVBadCheckSum
    ld hl,$b0c0
    ld de,W_NUMINBOX ; $da80
    ld bc,$462
    call CopyData
    and a
    jp SAVGoodChecksum

LoadSAVCheckSum2: ; 736bd (1c:76bd)
    ld a,$a
    ld [$0],a
    ld a,$1
    ds 3
    ld [$4000],a
    ld hl,$a598 ; hero name located in SRAM
    ld bc,$f8b  ; but here checks the full SAV
    call SAVCheckSum
    ld c,a
    ld a,[$b523] ; SAV's checksum
    cp c
    jp nz,SAVBadCheckSum
    ld hl,$af2c
    ld de,W_NUMINPARTY ; $d163
    ld bc,$194
    call CopyData
    ld hl,$a5a3
    ld de,wPokedexOwned ; $d2f7
    ld bc,$26
    call CopyData
    and a
    jp SAVGoodChecksum

SAVBadCheckSum: ; 736f7 (1c:76f7)
    scf

SAVGoodChecksum: ; 736f8 (1c:76f8)
    ld a,$0
    ds 3
    ld [$0],a
    ret

Func_73701: ; 0x73701
    call LoadSAVCheckSum
    call LoadSAVCheckSum1
    jp LoadSAVCheckSum2

SaveSAV: ;$770a
    BANKSWITCH Func_5def ; LoadGameMenuInGame
    ld hl,WouldYouLikeToSaveText
    call SaveSAVConfirm
    and a   ;|0 = Yes|1 = No|
    ret nz
    ld a,[$d088]
    dec a
    jr z,.save
    call SAVCheckRandomID
    jr z,.save
    ld hl,OlderFileWillBeErasedText
    call SaveSAVConfirm
    and a
    ret nz
.save        ;$772d
    call SaveSAVtoSRAM      ;$7848
    FuncCoord 1,13
    ld hl,Coord
    ld bc,$0412
    call ClearScreenArea      ;clear area 4x12 starting at 13,1
    FuncCoord 1,14
    ld hl,Coord
    ld de,NowSavingString
    call PlaceString
    ld c,$1e;$78
    call DelayFrames
    ld hl,GameSavedText
    call PrintText
    ld a,$b6        ;sound for saved game
    call PlaySoundWaitForCurrent
    call WaitForSoundToFinish
    ld c,$10;$1e
    jp DelayFrames

NowSavingString:
    db "Now saving...@"

SaveSAVConfirm: ; 73768 (1c:7768)
    call PrintText
    FuncCoord 0,7
    ld hl,Coord
    ld bc,$0801     ;arrow's coordinates |b = Y|c = X|
    ld a,$14        ;one line shifting ($28 = 2 lines)
    ld [$d125],a
    call DisplayTextBoxID      ;handle Yes/No KeyPress
    ld a,[$cc26]
    ret

