SAVCheckSum: ; 73856 (1c:7856)
;Check Sum (result[1 byte] is complemented)
    ld d,$0
.loop
    ld a,[hli]
    add d
    ld d,a
    dec bc
    ld a,b
    or c
    jr nz,.loop
    ld a,d
    cpl
    ret

