    ld hl,$b188
    call Func_73a7f
    ld hl,$b5ea
    call Func_73a7f
    ld hl,$a000
    ld bc,$1a4c
    call SAVCheckSum
    ld [$ba4c],a
    call Func_73863
    ret

Func_73a7f: ; 73a7f (1c:7a7f)
