    ld [hli],a
    dec a
    ld [hl],a
    ret

Func_73a84: ; 73a84 (1c:7a84)
    ld hl,wWhichTrade ; $cd3d
    push hl
    ld a,$a
    ld [$0],a
    ld a,$1
    ds 3
    ld a,$2
    ld [$4000],a
    call Func_73ab8
    ld a,$3
    ld [$4000],a
    call Func_73ab8
    xor a
    ds 3
    ld [$0],a
    pop hl
    ld a,[$d5a0]
    and $7f
    ld c,a
    ld b,$0
    add hl,bc
    ld a,[W_NUMINBOX] ; $da80
    ld [hl],a
    ret

Func_73ab8: ; 73ab8 (1c:7ab8)
    ld a,[$a000]
    ld [hli],a
    ld a,[$a462]
    ld [hli],a
    ld a,[$a8c4]
    ld [hli],a
    ld a,[$ad26]
    ld [hli],a
    ld a,[$b188]
    ld [hli],a
    ld a,[$b5ea]
    ld [hli],a
    ret

SAVCheckRandomID: ;$7ad1
;checks if Sav file is the same by checking player's name 1st letter ($a598)
; and the two random numbers generated at game beginning
;(which are stored at $d359-d35a)
    ld a,$0a
    ld [$0000],a
    ld a,$01
    ds 3
    ld [$4000],a
    ld a,[$a598]
    and a
    jr z,.next
    ld hl,$a598
    ld bc,$0f8b
    call SAVCheckSum
    ld c,a
    ld a,[$b523]
    cp c
    jr nz,.next
    ld hl,$a605
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ld a,[$d359]
    cp l
    jr nz,.next
    ld a,[$d35a]
    cp h
.next
    ld a,$00
    ds 3
    ld [$0000],a
    ret

SaveHallOfFameTeams: ; 73b0d (1c:7b0d)
    ld a,[$d5a2]
    nop ; dec a ; Counter Updated at the End
    cp $32
    jr nc,.shiftHOFTeams
    ld hl,$a598
    ld bc,$60
    call AddNTimes
    ld e,l
    ld d,h
    ld hl,$cc5b
    ld bc,$60
    jr HallOfFame_Copy

.shiftHOFTeams
; if the space designated for HOF teams is full, then shift all HOF teams to the next slot, making space for the new HOF team
; this deletes the last HOF team though
    ld hl,$a5f8
    ld de,$a598
    ld bc,$1260
    call HallOfFame_Copy
    ld hl,$cc5b
    ld de,$b7f8
    ld bc,$60
    jr HallOfFame_Copy

LoadHallOfFameTeams: ; 73b3f (1c:7b3f)
    ld hl,$a598
    ld bc,$60
    ld a,[wWhichTrade] ; $cd3d
    call AddNTimes
    ld de,$cc5b
    ld bc,$60
    ; ft

HallOfFame_Copy: ; 73b51 (1c:7b51)
    ld a,$a
    ld [$0],a
    ld a,$1
    ds 3
    xor a
    ld [$4000],a
    call CopyData
    xor a
    ds 3
    ld [$0],a
    ret

Func_73b6a: ; 73b6a (1c:7b6a)
    ld a,$a
    ld [$0],a
    ld a,$1
    ds 3
    xor a
    call PadSRAM_FF
    ld a,$1
    call PadSRAM_FF
    ld a,$2
    call PadSRAM_FF
    ld a,$3
    call PadSRAM_FF
    xor a
    ds 3
    ld [$0],a
    ret

PadSRAM_FF: ; 73b8f (1c:7b8f)
    ld [$4000],a
    ld hl,$a000
    ld bc,$2000
    ld a,$ff
    jp FillMemory

TryToSendSGBPackets_Plus: ; Denim ; gameboycolor
    ld a,[wFlagGameBoyColor]
    cp $11
    jr z,.GameBoyColor
    jp Func_7209b
.GameBoyColor
    scf ; setCarryFlag
    ret

; Denim : gameboycolor
; se GameBoyColor e PAL_SET,copio i 4 colori del pacchetto in WRAM2
; se GameBoyColor e ATTR_BLK,copio su VRAM2 gli ID delle Palette da utilizzare per ogni tiles
CheckIfGameBoyColorModeAndSetPalette:
    di
    ld a,[wFlagGameBoyColor]
    cp $11
    ld a,[hl]
    push af ; Backup First Byte Packet
    jr nz,.Done
    and a,%11111000 ; Apply Mask to SGB Packet Type
    cp %01010000 ; PAL_SET : $A
    jr z,.SetGBCPalette
    cp %00100000 ; ATTR_BLK ; $4
    jr z,.SetGBCAttrBlk
    jr .Done

.SetGBCPalette


    push hl ; Backup
    push de
    push bc

    ld a,2
    ld [H_LOADEDWRAMBANK],a ; WRAM Bank 2

    inc hl
    ld b,4 ; Counter 4 Palette (2 Byte each)
    xor a
    ld [wLastrBGPUsed],a  ; Force to Update FF47 Interpretation
    ld [wLastrOBP0Used],a
    ld [wPointerToCurrentPaletteByteLSB],a ; Pointer to Current SGB Color in WRAM 2 (4LSB)
.Loop4Palette
    ld a,[hli] ; 1st Byte Current Color
    ld e,a
    ld a,[hli] ; 2nd Byte Current Color
    ld d,a ; de = PALETTE ID

    push hl ; Backup pointer to current Palette ID
    ld h,d
    ld l,e ; hl = PALETTE ID
    ld de,SuperPalettes
    add hl,hl ; hl = PALETTE ID * 2
    add hl,hl ; hl = PALETTE ID * 4
    add hl,hl ; hl = PALETTE ID * 8
    add hl,de ; hl = pointer to current Palette Color

    push bc ; Backup Offset

    ld a,[$ff8b] ; Backup FF8B
    push af
    ld a,[wPointerToCurrentPaletteByteLSB]
    ld d,$d0
    ld e,a
    ld bc,8
    ld a,BANK(SuperPalettes)
    call FarCopyData2 ; copy bc bytes of data from a:hl to de
    ld a,e
    ld [wPointerToCurrentPaletteByteLSB],a
    pop af
    ld [$ff8b],a ; Restore FF8B

    pop bc ; Restore Offset
    pop hl ; Restore pointer to current Palette ID

    dec b ; Update Counter
    jr nz,.Loop4Palette

    ld a,$90
    ld [$d08f],a

    BANKSWITCH DebugStoreColour

    ld a,1
    ld [H_LOADEDWRAMBANK],a ; WRAM Bank 1

.Restore
    pop bc ; Restore
    pop de
    pop hl
    pop af ; Restore First Byte Packet
    xor a ; set Number of packet to zero
    jr .NoSentPacket

.Done
    pop af ; Restore First Byte Packet
    and a,%00000111
.NoSentPacket
    ei
    ret

.SetGBCAttrBlk

    push hl ; Backup
    push de
    push bc

    ld d,h
    ld e,l
    inc de
    ld a,[de] ; number of data sets
    push af ; Backup Counter
    scf ; set carry flag
.Loop
    ld hl,wBlkCurrentPaletteColor
    inc de
    inc de
    ld a,[de] ; Color Palette Designation
    call c,ResetPreVRAM2
    and a,%00000011 ; Mask for Palette Number for inside of surrounded area
    ld [hli],a
    inc de
    ld a,[de] ; Coordinate X1 (left)
    ld [hli],a
    inc de
    ld a,[de] ; Coordinate Y1 (upper)
    ld [hli],a
    inc de
    ld a,[de] ; Coordinate X2 (right)
    ld [hli],a
    inc de
    ld a,[de] ; Coordinate Y2 (lower)
    ld [hl],a

    push de ; Backup Pointer to Packet

    ld hl,wBlkCoordinateX1Left
    ld a,[hli]
    ld d,a
    ld a,[hli]
    ld e,a

    ld hl,wPreLoadOfVRAM2
    ld l,d
    ld bc,$20
    call AddNTimes ; hl : puntatore su VRAM2
    push hl ; Backup puntatore su VRAM2

    ld hl,wBlkCoordinateX2Right
    ld a,[hli]
    ld b,a
    ld a,[hli]
    ld d,a
    ld a,[wBlkCurrentPaletteColor]
    ld c,a
    pop hl ; Restore puntatore su VRAM2

    ; hl : puntatore su VRAM2
    ; b  : colonna finale
    ; d  : riga finale
    ; c  : Palette
    ; e  : riga iniziale
    ld a,2
    ld [H_LOADEDWRAMBANK],a ; WRAM Bank 2
    inc d
.PreLoop
    push hl ; Backup puntatore su VRAM2
    push de ; Backup Row Counter
    jr .NextColumn
.NextRow
    pop hl ; Restore puntatore su VRAM2
    push bc ; Backup Counter
    ld bc,$20
    add hl,bc
    pop bc ; Restore Counter
    jr .PreLoop
.NextColumn
    ld a,c
    ld [hl],a
    ld a,l
    and a,%00011111 ; Mask per ottenere un massimo di $1F equivalente all'ultima colonna
    cp b
    inc hl
    jr nz,.NextColumn
    pop de ; Restore Row Counter
    inc e
    ld a,e
    cp d
    jr nz,.NextRow
    pop hl ; Restore puntatore su VRAM2 (useless)
    ld a,1
    ld [wForceVRAM2Writing],a
    ld [H_LOADEDWRAMBANK],a ; WRAM Bank 1

    pop de ; Restore Pointer to Packet
    pop af ; Restore Counter
    dec a
    push af ; Backup Counter
    jr nz,.Loop
    pop af ; Restore Counter (useless)

    jr .Restore

; Azzeramento intero Pre caricamento VRAM2 con Palette derivante dalla prima sequenza del pacchetto attr_blk
ResetPreVRAM2:
    push af
    push hl
    and a,%00110000
    swap a
    ld b,a
;    di
    ld a,2
    ld [H_LOADEDWRAMBANK],a ; WRAM Bank 2
    ld a,b
    ld bc,1024
    ld hl,wPreLoadOfVRAM2
    call FillMemory
    ld a,1
    ld [H_LOADEDWRAMBANK],a ; WRAM Bank 1
;    ei
    pop hl
    pop af
    ret

CheckShinyFrontAndGetPAL:
    push hl
    ld hl,wFlagForceGhostPalBit4
    bit 4,[hl]
    jr z,.NoGhost
.Ghost
    ld hl,W_MONH_PALETTE_ID
    ld a,PAL_GASTLY ; Ghost Color is Gastly Color
    ld [hli],a
    xor a
    ld [hl],a
    ld a,GASTLY ; Ghost Color is Gastly Color
    jp SkipShinyAndGetPAL
.NoGhost
    ld hl,wFlagBackFrontSpriteBit56
    set 6,[hl]
    ld hl,W_ENEMYBATTSTATUS3
    bit 3,[hl] ; bit 3 of battle status 3,set if current Pokemon is transformed
    jr z,.NoTransform
    ld a,[$cfe5]
.NoTransform
    push af
    ld [$d0b5],a
    BANKSWITCH GetBattleFrontMonHeader
    ld hl,W_ENEMYMONATKDEFIV
    jr GetPalCommon

CheckShinyBackAndGetPAL:
    push hl
    push af
    ld [$d0b5],a
    BANKSWITCH GetBattleBackMonHeader
    ld hl,wFlagBackFrontSpriteBit56
    set 5,[hl]
    ld hl,W_PLAYERMONIVS
    jr GetPalCommon

CheckShinyAndGetPAL:
