    push af
    ld [$d0b5],a
    BANKSWITCH GetLoadedMonHeader
    ld hl,$cfb3
    ; ft

GetPalCommon:
    pop af
    call IsShiny
SkipShinyAndGetPAL:
    pop hl
    ; ft

DeterminePaletteID: ; DONE:Palette
    push bc
    push de
    and a
    jr z,.idZero
    cp CHARIZARD_M
    ld l,PAL_REDMON
    jr z,.PaletteSingleByteDone
    jr .Standard
.idZero
    ld hl,wFlagBackFrontSpriteBit56
    bit 5,[hl]
    jr nz,.Back
    bit 6,[hl]
    jr nz,.Front
    jr .Standard ; MissingNo00 front Sprite out of battle
.Front
    ld a,[W_TRAINERNO]
    and a
    jr z,.Standard ; MissingNo00 front Sprite during wild battle
    ; Trainer can't use MissingNo00
    ld a,[W_TRAINERCLASS]
    ld e,a
    ld hl,TrainerPalettes ; Just for Trainer
    ld d,0
    add hl,de
    ld l,[hl]
    jr .PaletteSingleByteDone
.Back
    ld hl,wFlagBackSpritePlayerBit4 ; Pointer to Flag BackSpritePlayer (Bit4)
    bit 4,[hl]
    jr z,.Standard   ; if 0 -> MissingNo00 Back sprite during battle
    ld l,PAL_VARIOUS ; if 1 -> Player BackSprite
.PaletteSingleByteDone
    ld h,0
    jr .End
.Standard
     ld hl,W_MONH_PALETTE_ID
     ld a,[hli]
     ld h,[hl]
     ld l,a
     call .CheckShiny
     jr z,.End
     ld bc,1
     add hl,bc
.End
    call .ResetFlags
    pop de
    pop bc
    ret
.CheckShiny
    push hl
    ld hl,wFlagShinyBit2
    bit 2,[hl]
    pop hl
    ret
.ResetFlags
    push hl
    ld hl,wFlagBackFrontSpriteBit56
    res 5,[hl]
    res 6,[hl]
    ld hl,wFlagShinyBit2
    res 2,[hl]
    pop hl
    ret

CreateMonOvWorldSprInstruction:
    ld hl,wSpriteOAMBySpeciesBit7
    bit 7,[hl]
    res 7,[hl]
    jr z,.NoRename
    inc hl ; hl point to wSpriteOAMBySpeciesId
    ld a,1
    jr .StartCreation
.NoRename
    ld hl,W_NUMINPARTY
    ld a,[hli] ; numero di Pokemon nel party
    and a
    jr z,.EmptyParty

.StartCreation
    push af ; Backup numero di Pokemon nel party
    ld d,a ; contatore in discesa
    xor a
    ld e,a ; contatore in salita
.NextPartyPokemon
    xor a
    ld b,a
    ld c,e
    ld a,[hli] ; leggo id Pokemon n-esimo
    push hl ; Backup location id Pokemon n-esimo
    push af ; Backup Id Pokemon
    ld hl,wArrayMiniSpriteLoaded
    add hl,bc
    ld [hl],a ; Memorizzo l'elenco dei pokemon Id cosi come verranno caricati in VRAM

    ld a,e
    ld hl,wLocationMonOvSprInstruction
    ld bc,$06
    call AddNTimes ; 3a87 (0:3a87) ; add bc to hl a times
    pop af ; Restore Id Pokemon
    push hl ; Backup wLocationMonOvSprInstruction corretta

    call IndexToMiniSpriteOrder
    ld b,128 ; TAUROS in original pokedex
    cp b
    push af ; Backup flag C
    jr c,.Before128 ; < TAUROS in original pokedex
    sub b
.Before128
    ld hl,$4000 ; Entrambe le liste di immagini mini sprite iniziano a inizio BANK
    ld bc,$80
    call AddNTimes ; 3a87 (0:3a87) ; add bc to hl a times
    call CheckFlyingMonSprite2
    ld b,h
    ld c,l

    pop af ; Restore flag C
    pop hl ; Restore wLocationMonOvSprInstruction corretta
    ld a,c
    ld [hli],a
    ld a,b
    ld [hli],a
    call GetMonSpriteNumOfTiles ; ld a,$08
    ld [hli],a
    ld a,BANK(MonOverworldDataNew_emimonserrate)
    jr c,.Before128_2
    inc a
.Before128_2
    ld [hli],a
    push hl ; Backup wLocationMonOvSprInstruction
    ld a,e
    ld bc,$80
    ld hl,$8000
    call AddNTimes ; 3a87 (0:3a87) ; add bc to hl a times
    call CheckFlyingMonSprite
    ld b,h
    ld c,l
    pop hl ; Restore wLocationMonOvSprInstruction
    ld a,c
    ld [hli],a
    ld a,b
    ld [hli],a

    pop hl ; Restore location id Pokemon n-esimo
    inc e
    dec d
    jr nz,.NextPartyPokemon
    pop af ; Restore numero di Pokemon nel party
    and a
.EmptyParty
    jr nz,.Done
    inc a
.Done
    call CheckBaloonRule ; ld hl,wLocationMonOvSprInstruction
    call nz,AddTradeBaloonRule
    ret

AddTradeBaloonRule:
    push af
    push hl
    ;dw BaloonSprites
    ;db $80 / $10 ; $40 bytes
    ;db BANK(BaloonSprites)
    ;dw $8380
    ld bc,$06
    call AddNTimes ; 3a87 (0:3a87) ; add bc to hl a times
    ld a,(BaloonSprites) % $100
    ld [hli],a
    ld a,(BaloonSprites) / $100
    ld [hli],a
    ld a,$80 / $10 ; $80 bytes
    ld [hli],a
    ld a,BANK(BaloonSprites)
    ld [hli],a
    ld a,$80
    ld [hli],a
    ld a,$83
    ld [hli],a
    pop hl
    pop af
    inc a
    inc a
    ret

