FlashSprite:
    ld b,6
.loop
    ld a,[rOBP0]
    xor d
    ld [rOBP0],a
    ld c,7
    call DelayFrames
    dec b
    jr nz,.loop
    ret

GetHealthBarColorWithGhostCheck_:
    ld a,e
    cp $1e
    ld hl,W_PLAYERMONTYPES
    jr nz,.front
    ld hl,W_ENEMYMONTYPES
.front
    call CheckGhostType
    ld h,d
    ld l,e
    jr nz,.NoGhost
    ld [hl],PAL_GASTLY - PAL_GREENBAR
    ret
.NoGhost
    ld a,[wBackupHealthBarWidth]
    ld e,a
    jp GetHealthBarColor

; Funzione per cambiare lo sprite utilizzato dalle ball durante la ricarica al centro pokemon
LoadAlternateBallPic: ; Denim
    ld hl,wFlagFlashingHealBallBit7
    bit 7,[hl]
    jr z,.Flash
    jr .Restore
.Flash
    set 7,[hl]
    ld de,PokeCenterFlashingHealBall ; $44b7
    ld bc,(BANK(PokeCenterFlashingHealBall) << 8) + $03
    jr .Done
.Restore
    res 7,[hl]
    ld de,PokeCenterHealBall
    ld bc,(BANK(PokeCenterHealBall) << 8) + $03
.Done
    ld hl,$87c0
    jp CopyVideoData
