    call SaveScreenTilesToBuffer1
    call Func_74183

    ; display the next monster from CreditsMons
    ld hl,$CD3E
    ld c,[hl] ; how many monsters have we displayed so far?
    inc [hl]
    ld b,0
    ld hl,CreditsMons
    add hl,bc ; go that far in the list of monsters and get the next one
    ld a,[hl]
    ld [$CF91],a
    ld [$D0B5],a
    FuncCoord 8,6 ; $c420
    ld hl,Coord
    call CreditsMons_HandleAlternative ; call GetMonHeader
    call LoadFrontSpriteByMonIndex
    ld hl,$980C
    call Func_74164
    xor a
    ld [H_AUTOBGTRANSFERENABLED],a
    call LoadScreenTilesFromBuffer1
    ld hl,$9800
    call Func_74164
    ld a,$A7
    ld [$FF4B],a
    ld hl,$9C00
    call Func_74164
    call Func_74183
    ld a,$FC
    ld [$FF47],a
    ld bc,7
.next
    call Func_74140
    dec c
    jr nz,.next
    ld c,$14
.next2
    call Func_74140
    ld a,[$FF4B]
    sub 8
    ld [$FF4B],a
    dec c
    jr nz,.next2
    xor a
    ld [$FFB0],a
    ld a,$C0
    ld [$FF47],a
    ret

