SECTION "GaryScript2",ROMX[$5f6a],BANK[$1d]

GaryScript2: ; 75f6a (1d:5f6a)
    ld a,[$cd38]
    and a
    ret nz
    call Delay3
    xor a
    ld [wJoypadForbiddenButtonsMask],a
    ld hl,$d355
    res 7,[hl]
    ld a,$1
    ld [$ff00+$8c],a
    call DisplayTextID
    call Delay3
    ld hl,$d72d
    set 6,[hl]
    set 7,[hl]
    ld hl,UnnamedText_760f9
    ld de,UnnamedText_760fe
    call PreBattleSaveRegisters
    ld a,SONY3
    ld [W_CUROPPONENT],a ; $d059

    ; select which team to use during the encounter
    ld a,[W_RIVALSTARTER]
    cp SQUIRTLE
    jr nz,.NotSquirtle ; 0x75f9f $4
    ld a,$1
    jr .done
.NotSquirtle
    cp BULBASAUR
    jr nz,.Charmander ; 0x75fa7 $4
    ld a,$2
    jr .done
.Charmander
    ld a,$3
.done
    ld [W_TRAINERNO],a

    xor a
    ld [H_CURRENTPRESSEDBUTTONS],a
    ld a,$3
    ld [W_GARYCURSCRIPT],a
    ret

GaryScript3: ; 75fbb (1d:5fbb)
    ld a,[W_ISINBATTLE]
    cp $ff
    jp z,GaryScript_75f29
    call UpdateSprites ; move sprites
    ld hl,$d867
    set 1,[hl]
    ld a,$f0
    ld [wJoypadForbiddenButtonsMask],a
    ld a,$1
    ld [$ff00+$8c],a
    call GaryScript_760c8
    ld a,$1
    ld [$ff00+$8c],a
    call SetSpriteMovementBytesToFF
    ld a,$4
    ld [W_GARYCURSCRIPT],a
    ret

