; ─────────────────────────────────────────

PKMNLeaguePC:
    ld hl,.UnnamedText_76683
    call PrintText
    ld hl,$D730
    set 6,[hl]
    push hl
    ld a,[$CFCB]
    push af
    ld a,[$FF00+$D7]
    push af
    xor a
    ld [$FF00+$D7],a
    ld [W_SPRITEFLIPPED],a
    ld [$CFCB],a
    ld [$CD41],a
    ld [$CD42],a
    ld a,[$D5A2]
    ld b,a
    cp $33
    jr c,.loop1
; If the total number of hall of fame teams is greater than the storage
; capacity, then calculate the number of the first team that is still recorded.
    ld b,$32
    sub b
    ld [$CD42],a
.loop1
    ld hl,$CD42
    inc [hl]
    push bc
    ld a,[$CD41]
    ld [$CD3D],a
    BANKSWITCH LoadHallOfFameTeams
    call .LeaguePCShowTeam
    pop bc
    jr c,.doneShowingTeams
    ld hl,$CD41
    inc [hl]
    ld a,[hl]
    cp b
    jr nz,.loop1
.doneShowingTeams
    pop af
    ld [$FF00+$D7],a
    pop af
    ld [$CFCB],a
    pop hl
    res 6,[hl]
    call GBPalWhiteOutWithDelay3
    call ClearScreen
    call GoPAL_SET_CF1C
    jp GBPalNormal
.UnnamedText_76683
    TX_FAR _UnnamedText_76683
    db "@"

.LeaguePCShowTeam
    ld c,6
.loop2
    push bc
    call .LeaguePCShowMon
;    call WaitForTextScrollButtonPress
;    ld a,[H_CURRENTPRESSEDBUTTONS] ; ▼▲◄►StSeBA
.wait
    call GetJoypadStateLowSensitivity
    ld a,[$ffb5]
    and %00001011 ; ▼▲◄►StSeBA
    and a ; was a key pressed?
    jr z,.wait
    bit 1,a ; B Pressed?
    jr nz,.exit
    bit 3,a ; Start Pressed?
    jr nz,.NextTeam
    ld hl,$CC6B
    ld de,$CC5B
    ld bc,$0050
    call CopyData
    pop bc
    ld a,[$CC5B]
    cp $FF
    jr z,.done
    dec c
    jr nz,.loop2
.done
    and a
    ret
.exit
    pop bc
    scf
    ret
.NextTeam
    pop bc
    and a
    ret

.LeaguePCShowMon
    call GBPalWhiteOutWithDelay3
    call ClearScreen
    ld hl,$CC5B
    ld a,[hli]
    ld [$CD3D],a
    ld [$CF91],a
    ld [$D0B5],a
    ld [$CFD9],a
    ld [$CF1D],a
    ld a,[hli]
    ld [$CD3F],a
    ld de,$CD6D
    ld bc,$000B
    call CheckShinyAndAlternativeFromHallOfFameData ; call CopyData
    call GetMonHeader
    ld b,$0B
    ld c,0
    call GoPAL_SET
    FuncCoord 12,5 ; $c410
