; prints a pokemon's status condition
; INPUT:
; de = address of status condition
; hl = destination address
; bc = battle status 1 address (if 0 Not Battle HUD)
PrintStatusAilment:
    ld a,[de]
    bit FRZ_Bit,a
    call nz,.Frz
    jr nz,.FrzThenSkipSlpBrn
    and %00000111 ; slp
    call nz,.Slp
    ld a,[de]
    bit 4,a
    call nz,.Brn
.FrzThenSkipSlpBrn
    bit 3,a
    call nz,.Psn
    ld a,[de]
    bit 6,a
    call nz,.Par
    call .CheckBattleHud
    ret z  ; End If Not Battle Hud
    ld a,[bc]
    bit CONFUSED,a
    call nz,.Confused
    inc bc
    ld a,[bc]
    bit SEEDED,a
    call nz,.Seeded
    ret
.Slp
    ld [hl],$CA
    inc hl ; jr .NextVideoSlot
    ret
.Psn
    call .CheckBattleHud
    jr z,.NormalPoison
    inc bc
    inc bc
    ld a,[bc]
    dec bc
    dec bc
    bit BADLY_POISONED,a
    jr nz,.BadlyPoisoned
.NormalPoison
    ld [hl],$CB
    inc hl ; jr .NextVideoSlot
    ret
.Brn
    ld [hl],$CC
    inc hl ; jr .NextVideoSlot
    ret
.Frz
    ld [hl],$CD
    inc hl ; jr .NextVideoSlot
    ret
.Par
    ld [hl],$CE
    inc hl ; jr .NextVideoSlot
    ret
.Confused
    ld [hl],$DE
    inc hl ; jr .NextVideoSlot
    ret
.Seeded
    ld [hl],$DC
    inc hl ; jr .NextVideoSlot
    ret
.BadlyPoisoned
    ld [hl],$DD
    inc hl ; jr .NextVideoSlot
    ret
.CheckBattleHud
    push bc
    push af
    ld a,b ; Check Battle Hud
    or c   ; ...
    pop bc
    ld a,b
    pop bc
    ret
;.NextVideoSlot
;    call .CheckBattleHud
;    inc hl
;    ret z
;    ;push bc
;    ;ld bc,-02
;    ;add hl,bc
;    ;pop bc
;    ret

