SECTION "bank1E",ROMX,BANK[$1E]

; Draws a "frame block". Frame blocks are blocks of tiles that are put
; together to form frames in battle animations.
DrawFrameBlock: ; 78000 (1e:4000)
    ld l,c
    ld h,b
    ld a,[hli]
    ld [W_NUMFBTILES],a
    ld a,[W_FBDESTADDR + 1]
    ld e,a
    ld a,[W_FBDESTADDR]
    ld d,a
    xor a
    ld [W_FBTILECOUNTER],a ; loop counter
.loop
    ld a,[W_FBTILECOUNTER]
    inc a
    ld [W_FBTILECOUNTER],a
    ld a,[W_SUBANIMTRANSFORM]
    dec a
    jr z,.flipHorizontalAndVertical   ; 1
    dec a
    jp z,.flipHorizontalTranslateDown ; 2
    dec a
    jr z,.flipBaseCoords              ; 3
.noTransformation
    ld a,[W_BASECOORDY]
    add [hl]
    ld [de],a ; store Y
    inc hl
    inc de
    ld a,[W_BASECOORDX]
    jr .finishCopying
.flipBaseCoords
    ld a,[W_BASECOORDY]
    ld b,a
    ld a,136
    sub b ; flip Y base coordinate
    add [hl] ; Y offset
    ld [de],a ; store Y
    inc hl
    inc de
    ld a,[W_BASECOORDX]
    ld b,a
    ld a,168
    sub b ; flip X base coordinate
.finishCopying ; finish copying values to OAM (when [W_SUBANIMTRANSFORM] not 1 or 2)
    add [hl] ; X offset
    ld [de],a ; store X
    inc hl
    inc de
    ld a,[hli]
    add a,$31 ; base tile ID for battle animations
    ld [de],a ; store tile ID
    inc de
    ld a,[hli]
    ld [de],a ; store flags
    nop ; Denim (CaptureBall) ; inc de
    jp .nextTile
.flipHorizontalAndVertical
    ld a,[W_BASECOORDY]
    add [hl] ; Y offset
    ld b,a
    ld a,136
    sub b ; flip Y coordinate
    ld [de],a ; store Y
    inc hl
    inc de
    ld a,[W_BASECOORDX]
    add [hl] ; X offset
    ld b,a
    ld a,168
    sub b ; flip X coordinate
    ld [de],a ; store X
    inc hl
    inc de
    ld a,[hli]
    add a,$31 ; base tile ID for battle animations
    ld [de],a ; store tile ID
    inc de
; toggle horizontal and vertical flip
    ld a,[hli] ; flags
    and a
    ld b,OAM_VFLIP | OAM_HFLIP
    jr z,.storeFlags1
    cp OAM_HFLIP
    ld b,OAM_VFLIP
    jr z,.storeFlags1
    cp OAM_VFLIP
    ld b,OAM_HFLIP
    jr z,.storeFlags1
    ld b,0
.storeFlags1
    ld a,b
    ld [de],a
    nop ; Denim (CaptureBall) ; inc de
    jp .nextTile
.flipHorizontalTranslateDown
    ld a,[W_BASECOORDY]
    add [hl]
    add a,40 ; translate Y coordinate downwards
    ld [de],a ; store Y
    inc hl
    inc de
    ld a,[W_BASECOORDX]
    add [hl]
    ld b,a
    ld a,168
    sub b ; flip X coordinate
    ld [de],a ; store X
    inc hl
    inc de
    ld a,[hli]
    add a,$31 ; base tile ID for battle animations
    ld [de],a ; store tile ID
    inc de
    ld a,[hli]
    bit 5,a ; is horizontal flip enabled?
    jr nz,.disableHorizontalFlip
.enableHorizontalFlip
    set 5,a
    jr .storeFlags2
.disableHorizontalFlip
    res 5,a
.storeFlags2
    ld [de],a
    nop ; Denim (CaptureBall) ; inc de
.nextTile
    call CheckCaptureAnimAndStoreFlag ; Denim (CaptureBall) ; ld a,[W_FBTILECOUNTER]
    ld c,a
    ld a,[W_NUMFBTILES]
    cp c
    jp nz,.loop ; go back up if there are more tiles to draw
.afterDrawingTiles
    ld a,[W_FBMODE]
    cp 2
    jr z,.advanceFrameBlockDestAddr; skip delay and don't clean OAM buffer
    ld a,[W_SUBANIMFRAMEDELAY]
    ld c,a
    call DelayFrames
    ld a,[W_FBMODE]
    cp 3
    jr z,.advanceFrameBlockDestAddr ; skip cleaning OAM buffer
    cp 4
    jr z,.done ; skip cleaning OAM buffer and don't advance the frame block destination address
    ld a,[W_ANIMATIONID]
    cp GROWL
    jr z,.resetFrameBlockDestAddr
    call AnimationCleanOAM
.resetFrameBlockDestAddr
    ld hl,wOAMBuffer ; OAM buffer
    ld a,l
    ld [W_FBDESTADDR + 1],a
    ld a,h
    ld [W_FBDESTADDR],a ; set destination address to beginning of OAM buffer
    ret
.advanceFrameBlockDestAddr
    ld a,e
    ld [W_FBDESTADDR + 1],a
    ld a,d
    ld [W_FBDESTADDR],a
.done
    ret

PlayAnimation: ; 780f1 (1e:40f1)
    xor a
    ld [$FF8B],a
    ld [W_SUBANIMTRANSFORM],a
    ld a,[W_ANIMATIONID] ; get animation number
    dec a
    ld l,a
    ld h,0
    add hl,hl
    ld de,AttackAnimationPointers  ; $607d ; animation command stream pointers
    add hl,de
    call GetAttackAnimationPointers
    ;ld a,[hli]
    ;ld h,[hl]
    ;ld l,a
.animationLoop
    ld a,[hli]
    cp $FF
    jr z,.AnimationOver
    cp $C0 ; is this subanimation or a special effect?
    jr c,.playSubanimation
.doSpecialEffect
    ld c,a
    ld de,SpecialEffectPointers
.searchSpecialEffectTableLoop
    ld a,[de]
    cp c
    jr z,.foundMatch
    inc de
    inc de
    inc de
    jr .searchSpecialEffectTableLoop
.foundMatch
    ld a,[hli]
    cp $FF ; is there a sound to play?
    jr z,.skipPlayingSound
    ld [wAnimSoundID],a ; store sound
    push hl
    push de
    call Func_7986f
    call PlaySound
    pop de
    pop hl
.skipPlayingSound
    push hl
    inc de
    ld a,[de]
    ld l,a
    inc de
    ld a,[de]
    ld h,a
    ld de,.nextAnimationCommand
    push de
    jp hl ; jump to special effect function
.playSubanimation
    ld c,a
    and a,%00111111
    ld [W_SUBANIMFRAMEDELAY],a
    xor a
    sla c
    rla
    sla c
    rla
    ld [$D09F],a ; tile select
    ld a,[hli] ; sound
    ld [wAnimSoundID],a ; store sound
    ld a,[hli] ; subanimation ID
    ld c,l
    ld b,h
    ld l,a
    ld h,0
    add hl,hl
    ld de,SubanimationPointers
    add hl,de
    ld a,l
    ld [W_SUBANIMADDRPTR],a
    ld a,h
    ld [W_SUBANIMADDRPTR + 1],a
    ld l,c
    ld h,b
    push hl
    ld a,[rOBP0]
    push af
    ld a,[$CC79]
    ld [rOBP0],a
    call LoadAnimationTileset
    call LoadSubanimation
    call PlaySubanimation
    pop af
    ld [rOBP0],a
.nextAnimationCommand
    pop hl
    jr .animationLoop
.AnimationOver ; 417B
    ret

LoadSubanimation: ; 7817c (1e:417c)
    ld a,[W_SUBANIMADDRPTR + 1]
    ld h,a
    ld a,[W_SUBANIMADDRPTR]
    ld l,a
    ld a,[hli]
    ld e,a
    ld a,[hl]
    ld d,a ; de = address of subanimation
    ld a,[de]
    ld b,a
    and a,31
    ld [W_SUBANIMCOUNTER],a ; number of frame blocks
    ld a,b
    and a,%11100000
    cp 5 << 5 ; is subanimation type 5?
    jr nz,.isNotType5
.isType5
    call GetSubanimationTransform2
    jr .saveTransformation
.isNotType5
    call GetSubanimationTransform1
.saveTransformation
; place the upper 3 bits of a into bits 0-2 of a before storing
    srl a
    swap a
    ld [W_SUBANIMTRANSFORM],a
    cp 4 ; is the animation reversed?
    ld hl,0
    jr nz,.storeSubentryAddr
; if the animation is reversed,then place the initial subentry address at the end of the list of subentries
    ld a,[W_SUBANIMCOUNTER]
    dec a
    ld bc,3
.loop
    add hl,bc
    dec a
    jr nz,.loop
.storeSubentryAddr
    inc de
    add hl,de
    ld a,l
    ld [W_SUBANIMSUBENTRYADDR],a
    ld a,h
    ld [W_SUBANIMSUBENTRYADDR + 1],a
    ret

; called if the subanimation type is not 5
; sets the transform to 0 (i.e. no transform) if it's the player's turn
; sets the transform to the subanimation type if it's the enemy's turn
GetSubanimationTransform1: ; 781c2 (1e:41c2)
    ld b,a
    ld a,[H_WHOSETURN]
    and a
    ld a,b
    ret nz
    xor a
    ret

; called if the subanimation type is 5
; sets the transform to 2 (i.e. horizontal and vertical flip) if it's the player's turn
; sets the transform to 0 (i.e. no transform) if it's the enemy's turn
GetSubanimationTransform2: ; 781ca (1e:41ca)
    ld a,[H_WHOSETURN]
    and a
    ld a,2 << 5
    ret z
    xor a
    ret

; loads tile patterns for battle animations
LoadAnimationTileset: ; 781d2 (1e:41d2)
    ld a,[$D09F] ; tileset select
    add a
    add a
    ld hl,AnimationTilesetPointers
    ld e,a
    ld d,0
    add hl,de
    ld a,[hli]
    ld [$D07D],a ; number of tiles
    ld a,[hli]
    ld e,a
    ld a,[hl]
    ld d,a ; de = address of tileset
    ld hl,$8310 ; destination address in VRAM
    ld b,$1E ; ROM bank
    ld a,[$D07D]
    ld c,a ; number of tiles
    jp CopyVideoData ; load tileset

AnimationTilesetPointers: ; 781f2 (1e:41f2)
    db 79 ; number of tiles
    dw AnimationTileset1
    db $FF

    db 79 ; number of tiles
    dw AnimationTileset2
    db $FF

    db 64 ; number of tiles
    dw AnimationTileset1
    db $FF

AnimationTileset1: ; 781fe (1e:41fe)
    INCBIN "gfx/attack_anim_1.2bpp"

AnimationTileset2: ; 786ee (1e:46ee)
    INCBIN "gfx/attack_anim_2.2bpp"

SlotMachineTiles2: ; 78bde (1e:4bde)
    INCBIN "gfx/red/slotmachine2.2bpp"

MoveAnimation: ; 78d5e (1e:4d5e)
    push hl
    push de
    push bc
    push af
    call WaitForSoundToFinish
    call MoveAnimationPalette
    ld a,[W_ANIMATIONID]
    and a
    jr z,.AnimationFinished

    ; if throwing a Poké Ball,skip the regular animation code
    cp TOSS_ANIM
    jr nz,.MoveAnimation
    ld de,.AnimationFinished
    push de
    jp TossBallAnimation

.MoveAnimation
    ; check if battle animations are disabled in the options
    ld a,[$D355]
    bit 7,a
    jr nz,.AnimationsDisabled
    call ShareMoveAnimations
    call PlayAnimation
    jr .next4
.AnimationsDisabled
    ld c,30
    call DelayFrames
.next4
    call PlayApplyingAttackAnimation ; reload pic and flash the pic in and out (to show damage)
.AnimationFinished
    call WaitForSoundToFinish
    xor a
    ld [$D096],a
    ld [$D09B],a
    ld [$D08B],a
    dec a
    ld [$CF07],a
    pop af
    pop bc
    pop de
    pop hl
    ret

ShareMoveAnimations: ; 78da6 (1e:4da6)
; some moves just reuse animations from status conditions
    ld a,[H_WHOSETURN]
    and a
    ret z

    ; opponent’s turn

    ld a,[W_ANIMATIONID]

    cp AMNESIA
    ld b,CONF_ANIM
    jr z,.Replace

    cp REST
    ld b,SLP_ANIM
    ret nz

.Replace
    ld a,b
    ld [W_ANIMATIONID],a
    ret

PlayApplyingAttackAnimation: ; 78dbd (1e:4dbd)
; Generic animation that shows after the move's individual animation
; Different animation depending on whether the move has an additional effect and on whose turn it is
    ld a,[$CC5B]
    and a
    ret z
    dec a
    add a
    ld c,a
    ld b,0
    ld hl,.AnimationTypePointerTable
    add hl,bc
    ld a,[hli]
    ld h,[hl]
    ld l,a
    jp hl

.AnimationTypePointerTable
    dw .ShakeScreenVertically        ; enemy mon has used a damaging move without a side effect
    dw .ShakeScreenHorizontallyHeavy ; enemy mon has used a damaging move with a side effect
    dw .ShakeScreenHorizontallySlow  ; enemy mon has used a non-damaging move
    dw .BlinkEnemyMonSprite          ; player mon has used a damaging move without a side effect
    dw .ShakeScreenHorizontallyLight ; player mon has used a damaging move with a side effect
    dw .ShakeScreenHorizontallySlow2 ; player mon has used a non-damaging move

.ShakeScreenVertically
    call PlayApplyingAttackSound
    ld b,$8
.AnimationShakeScreenVertically
    jp AnimationShakeScreenVertically

.ShakeScreenHorizontallyHeavy
    call PlayApplyingAttackSound
    ld b,$8
    jr .AnimationShakeScreenHorizontallyFast

.ShakeScreenHorizontallySlow
    ld bc,$602
    jr .AnimationShakeScreenHorizontallySlow

.BlinkEnemyMonSprite
    call PlayApplyingAttackSound
    ;jp AnimationBlinkEnemyMon
    ld b,$2
    jr .AnimationShakeScreenVertically

.ShakeScreenHorizontallyLight
    call PlayApplyingAttackSound
    ld b,$2
.AnimationShakeScreenHorizontallyFast
    jp AnimationShakeScreenHorizontallyFast

.ShakeScreenHorizontallySlow2
    ld bc,$302

.AnimationShakeScreenHorizontallySlow
    push bc
    push bc
.asm_78e03
    ld a,[rWX] ; $FF00+$4b
    inc a
    ld [rWX],a ; $FF00+$4b
    ld c,$2
    call DelayFrames
    dec b
    jr nz,.asm_78e03
    pop bc
.asm_78e11
    ld a,[rWX] ; $FF00+$4b
    dec a
    ld [rWX],a ; $FF00+$4b
    ld c,$2
    call DelayFrames
    dec b
    jr nz,.asm_78e11
    pop bc
    dec c
    jr nz,.AnimationShakeScreenHorizontallySlow
    ret

SECTION "MoveAnimationPalette",ROMX[$4e23],BANK[$1e]

MoveAnimationPalette: ; 78e23 (1e:4e23) ; Denim
    ld a,[wRunningOnSGB]
    and a
    jr z,.noSGB
    ld a,%11110000
    ld [$cc79],a
    ld a,[W_ANIMATIONID]
    cp TOSS_ANIM
    ld a,%11110000
    jr nz,.Done
    ld a,%11100100
.Done
    ld [rOBP0],a ; $FF00+$48
    ret
.noSGB
    ld a,%11100100
    ld [$cc79],a
    ld [rOBP0],a ; $FF00+$48
    ret

CheckCaptureAnimAndStoreFlag: ; Denim ; 13 BYTE
    ld a,[W_ANIMATIONID]
    cp SHAKE_ANIM
    jr nz,.Done
    ld a,[de]
    inc a
    ld [de],a ; Palette OBJ1 (Enemy Pkmn)
.Done
    inc de
    ld a,[W_FBTILECOUNTER]
    ret

SECTION "PlaySubanimation",ROMX[$4e53],BANK[$1e] ; Denim

PlaySubanimation: ; 78e53 (1e:4e53)
    ld a,[wAnimSoundID]
    cp $FF
    jr z,.skipPlayingSound
    call Func_7986f
    call PlaySound ; play sound effect
.skipPlayingSound
    ld hl,wOAMBuffer ; base address of OAM buffer
    ld a,l
    ld [W_FBDESTADDR + 1],a
    ld a,h
    ld [W_FBDESTADDR],a
    ld a,[W_SUBANIMSUBENTRYADDR + 1]
    ld h,a
    ld a,[W_SUBANIMSUBENTRYADDR]
    ld l,a
.loop
    push hl
    ld c,[hl] ; frame block ID
    ld b,0
    ld hl,FrameBlockPointers
    add hl,bc
    add hl,bc
    ld a,[hli]
    ld c,a
    ld a,[hli]
    ld b,a
    pop hl
    inc hl
    push hl
    ld e,[hl] ; base coordinate ID
    ld d,0
    ld hl,FrameBlockBaseCoords  ; $7c85 ; base coordinate table
    add hl,de
    add hl,de
    ld a,[hli]
    ld [W_BASECOORDY],a
    ld a,[hl]
    ld [W_BASECOORDX],a
    pop hl
    inc hl
    ld a,[hl] ; frame block mode
    ld [W_FBMODE],a
    call DrawFrameBlock
    call DoSpecialEffectByAnimationId ; run animation-specific function (if there is one)
    ld a,[W_SUBANIMCOUNTER]
    dec a
    ld [W_SUBANIMCOUNTER],a
    ret z
    ld a,[W_SUBANIMSUBENTRYADDR + 1]
    ld h,a
    ld a,[W_SUBANIMSUBENTRYADDR]
    ld l,a
    ld a,[W_SUBANIMTRANSFORM]
    cp 4 ; is the animation reversed?
    ld bc,3
    jr nz,.nextSubanimationSubentry
    ld bc,-3
.nextSubanimationSubentry
    add hl,bc
    ld a,h
    ld [W_SUBANIMSUBENTRYADDR + 1],a
    ld a,l
    ld [W_SUBANIMSUBENTRYADDR],a
    jp .loop

AnimationCleanOAM: ; 78ec8 (1e:4ec8)
    push hl
    push de
    push bc
    push af
    call DelayFrame
    call CleanLCD_OAM
    pop af
    pop bc
    pop de
    pop hl
    ret

; this runs after each frame block is drawn in a subanimation
; it runs a particular special effect based on the animation ID
DoSpecialEffectByAnimationId: ; 78ed7 (1e:4ed7)
    push hl
    push de
    push bc
    ld a,[W_ANIMATIONID]
    ld hl,AnimationIdSpecialEffects
    ld de,3
    call IsInArray
    jr nc,.done
    inc hl
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ld de,.done
    push de
    jp hl
.done
    pop bc
    pop de
    pop hl
    ret

; Format: Animation ID (1 byte),Address (2 bytes)
AnimationIdSpecialEffects: ; 78ef5 (1e:4ef5)
    db MEGA_PUNCH
    dw AnimationFlashScreen

    db GUILLOTINE
    dw AnimationFlashScreen

    db MEGA_KICK
    dw AnimationFlashScreen

    db HEADBUTT
    dw AnimationFlashScreen

    db TAIL_WHIP
    dw Func_790d0

    db GROWL
    dw DoGrowlSpecialEffects

    db DISABLE
    dw AnimationFlashScreen

    db BLIZZARD
    dw DoBlizzardSpecialEffects

    db BUBBLEBEAM
    dw AnimationFlashScreen

    db HYPER_BEAM
    dw FlashScreenEveryFourFrameBlocks

    db THUNDERBOLT
    dw FlashScreenEveryEightFrameBlocks

    db REFLECT
    dw AnimationFlashScreen

    db SELFDESTRUCT
    dw DoExplodeSpecialEffects

    db SPORE
    dw AnimationFlashScreen

    db EXPLOSION
    dw DoExplodeSpecialEffects

    db ROCK_SLIDE
    dw DoRockSlideSpecialEffects

    db $AA
    dw Func_79041

    db $AB
    dw Func_7904c

    db $AC
    dw Func_7907c

    db TOSS_ANIM
    dw DoBallTossSpecialEffects

    db SHAKE_ANIM
    dw DoBallShakeSpecialEffects

    db POOF_ANIM
    dw DoPoofSpecialEffects

    db GREATTOSS_ANIM
    dw DoBallTossSpecialEffects

    db ULTRATOSS_ANIM
    dw DoBallTossSpecialEffects

    db $FF ; terminator

DoBallTossSpecialEffects: ; 78f3e (1e:4f3e)
    ld a,[$CF91]
    cp 3 ; is it a Master Ball or Ultra Ball?
    jr nc,.skipFlashingEffect
.flashingEffect ; do a flashing effect if it's Master Ball or Ultra Ball
    ld a,[rOBP0]
    xor a,%00111100 ; complement colors 1 and 2
    ld [rOBP0],a
.skipFlashingEffect
    ld a,[W_SUBANIMCOUNTER]
    cp 11 ; is it the beginning of the subanimation?
    jr nz,.skipPlayingSound
; if it is the beginning of the subanimation,play a sound
    ld a,$91
    call PlaySound ; play sound
.skipPlayingSound
    ld a,[W_ISINBATTLE]
    cp 02 ; is it a trainer battle?
    jr z,.isTrainerBattle
    ld a,[$d11e]
    cp $10 ; is the enemy pokemon the Ghost Marowak?
    ret nz
; if the enemy pokemon is the Ghost Marowak,make it dodge during the last 3 frames
    ld a,[W_SUBANIMCOUNTER]
    cp 3
    jr z,.moveGhostMarowakLeft
    cp 2
    jr z,.moveGhostMarowakLeft
    cp 1
    ret nz
.moveGhostMarowakLeft
    FuncCoord 17,0
    ld hl,Coord
    ld de,20
    ld bc,$0707 ; 7 rows and 7 columns
.loop
    push hl
    push bc
    call Func_79862 ; move row of tiles left
    pop bc
    pop hl
    add hl,de
    dec b
    jr nz,.loop
    ld a,%00001000
    ld [$ff10],a ; Channel 1 sweep register
    ret
.isTrainerBattle ; if it's a trainer battle,shorten the animation by one frame
    ld a,[W_SUBANIMCOUNTER]
    cp 3
    ret nz
    dec a
    ld [W_SUBANIMCOUNTER],a
    ret

DoBallShakeSpecialEffects: ; 78f96 (1e:4f96)
    ld a,[W_SUBANIMCOUNTER]
    cp 4 ; is it the beginning of a shake?
    jr nz,.skipPlayingSound
; if it is the beginning of a shake,play a sound and wait 2/3 of a second
    ld a,$8c
    call PlaySound ; play sound
    ld c,40
    call DelayFrames
.skipPlayingSound
    ld a,[W_SUBANIMCOUNTER]
    dec a
    ret nz
; if it's the end of the ball shaking subanimation,check if more shakes are left and restart the subanimation
    ld a,[$cd3d] ; number of shakes
    dec a ; decrement number of shakes
    ld [$cd3d],a
    ret z
; if there are shakes left,restart the subanimation
    ld a,[W_SUBANIMSUBENTRYADDR]
    ld l,a
    ld a,[W_SUBANIMSUBENTRYADDR + 1]
    ld h,a
    ld de,-(4 * 3) ; 4 subentries and 3 bytes per subentry
    add hl,de
    ld a,l
    ld [W_SUBANIMSUBENTRYADDR],a
    ld a,h
    ld [W_SUBANIMSUBENTRYADDR + 1],a
    ld a,5 ; number of subentries in the ball shaking subanimation plus one
    ld [W_SUBANIMCOUNTER],a
    ret

; plays a sound after the second frame of the poof animation
DoPoofSpecialEffects: ; 78fce (1e:4fce)
    ld a,[W_SUBANIMCOUNTER]
    cp 5
    ret nz
    ld a,$93
    jp PlaySound

DoRockSlideSpecialEffects: ; 78fd9 (1e:4fd9)
    ld a,[W_SUBANIMCOUNTER]
    cp 12
    ret nc
    cp 8
    jr nc,.shakeScreen
    cp 1
    jp z,AnimationFlashScreen ; if it's the end of the subanimation,flash the screen
    ret
; if the subaninmation counter is between 8 and 11,shake the screen horizontally and vertically
.shakeScreen
    ld b,1
    PREDEF ShakeScreenHorizontally ; shake horizontally
    ld b,1
    PREDEF_JUMP Func_480ff ; shake vertically

FlashScreenEveryEightFrameBlocks: ; 78ff7 (1e:4ff7)
    ld a,[W_SUBANIMCOUNTER]
    and a,7 ; is the subanimation counter exactly 8?
    call z,AnimationFlashScreen ; if so,flash the screen
    ret

; flashes the screen if the subanimation counter is divisible by 4
FlashScreenEveryFourFrameBlocks: ; 79000 (1e:5000)
    ld a,[W_SUBANIMCOUNTER]
    and a,3
    call z,AnimationFlashScreen
    ret

; used for Explosion and Selfdestruct
DoExplodeSpecialEffects: ; 79009 (1e:5009)
    ld a,[W_SUBANIMCOUNTER]
    cp 1 ; is it the end of the subanimation?
    jr nz,FlashScreenEveryFourFrameBlocks
; if it's the end of the subanimation,make the attacking pokemon disappear
    FuncCoord 1,5 ; $c405
    ld hl,Coord
    jp AnimationHideMonPic ; make pokemon disappear

; flashes the screen when subanimation counter is 1 modulo 4
DoBlizzardSpecialEffects: ; 79016 (1e:5016)
    ld a,[W_SUBANIMCOUNTER]
    cp 13
    jp z,AnimationFlashScreen
    cp 9
    jp z,AnimationFlashScreen
    cp 5
    jp z,AnimationFlashScreen
    cp 1
    jp z,AnimationFlashScreen
    ret

; flashes the screen at 3 points in the subanimation
; XXX is this unused?
Func_7902e: ; 7902e (1e:502e)
    ld a,[W_SUBANIMCOUNTER]
    cp 14
    jp z,AnimationFlashScreen
    cp 9
    jp z,AnimationFlashScreen
    cp 2
    jp z,AnimationFlashScreen
    ret

; function to make the pokemon disappear at the beginning of the animation
; XXX probably a trade-related animation
Func_79041: ; 79041 (1e:5041)
    ld a,[W_SUBANIMCOUNTER]
    cp 6
    ret nz
    ld a,$2F
    jp Func_7980c ; make pokemon disappear

; function to make a shaking pokeball jump up at the end of the animation
; XXX probably a trade-related animation
Func_7904c: ; 7904c (1e:504c)
    ld a,[W_SUBANIMCOUNTER]
    cp 1
    ret nz
; if it's the end of the animation,make the ball jump up
    ld de,BallMoveDistances1
.loop
    ld hl,wOAMBuffer ; OAM buffer
    ld bc,4
.innerLoop
    ld a,[de]
    cp $ff
    jr z,.done
    add [hl] ; add to Y value of OAM entry
    ld [hl],a
    add hl,bc
    ld a,l
    cp 4 * 4 ; there are 4 entries,each 4 bytes
    jr nz,.innerLoop
    inc de
    push bc
    call Delay3
    pop bc
    jr .loop
.done
    call AnimationCleanOAM
    ld a,$98
    jp PlaySound ; play sound

BallMoveDistances1: ; 79078 (1e:5078)
    db -12,-12,-8
    db $ff ; terminator

; function to make the pokeball jump up
; XXX probably a trade-related animation
Func_7907c ; 507C
    ld de,BallMoveDistances2
.loop
    ld hl,wOAMBuffer ; OAM buffer
    ld bc,4
.innerLoop
    ld a,[de]
    cp $ff
    jp z,ClearScreen
    add [hl]
    ld [hl],a
    add hl,bc
    ld a,l
    cp 4 * 4 ; there are 4 entries,each 4 bytes
    jr nz,.innerLoop
    inc de
    push de
    ld a,[de]
    cp 12
    jr z,.playSound
    cp $ff
    jr nz,.skipPlayingSound
.playSound ; play sound if next move distance is 12 or this is the last one
    ld a,$ae
    call PlaySound
.skipPlayingSound
    push bc
    ld c,5
    call DelayFrames
    pop bc
    ld a,[$ffae] ; background scroll X
    sub a,8 ; scroll to the left
    ld [$ffae],a
    pop de
    jr .loop

BallMoveDistances2: ; 790b3 (1e:50b3)
    db 11,12,-12,-7,7,12,-8,8
    db $ff ; terminator

; this function copies the current musical note graphic
; so that there are two musical notes flying towards the defending pokemon
DoGrowlSpecialEffects: ; 790bc (1e:50bc)
    ld hl,wOAMBuffer ; OAM buffer
    ld de,$c310
    ld bc,$10
    call CopyData ; copy the musical note graphic
    ld a,[W_SUBANIMCOUNTER]
    dec a
    call z,AnimationCleanOAM ; clean up at the end of the subanimation
    ret

; this is associated with Tail Whip,but Tail Whip doesn't use any subanimations
Func_790d0: ; 790d0 (1e:50d0)
    ld a,1
    ld [W_SUBANIMCOUNTER],a
    ld c,20
    jp DelayFrames

; Format: Special Effect ID (1 byte),Address (2 bytes)
SpecialEffectPointers: ; 790da (1e:50da)
    db SE_DARK_SCREEN_FLASH ; $FE
    dw AnimationFlashScreen
    db SE_DARK_SCREEN_PALETTE ; $FD
    dw AnimationDarkScreenPalette
    db SE_RESET_SCREEN_PALETTE ; $FC
    dw AnimationResetScreenPalette
    db SE_SHAKE_SCREEN ; $FB
    dw AnimationShakeScreen
    db SE_WATER_DROPLETS_EVERYWHERE ; $FA
    dw AnimationWaterDropletsEverywhere
    db SE_DARKEN_MON_PALETTE ; $F9
    dw AnimationDarkenMonPalette
    db SE_FLASH_SCREEN_LONG ; $F8
    dw AnimationFlashScreenLong
    db SE_SLIDE_MON_UP ; $F7
    dw AnimationSlideMonUp
    db SE_SLIDE_MON_DOWN ; $F6
    dw AnimationSlideMonDown
    db SE_FLASH_MON_PIC ; $F5
    dw AnimationFlashMonPic
    db SE_SLIDE_MON_OUT ; $F4
    dw AnimationSlideMonOut
    db SE_BLINK_MON ; $F3
    dw AnimationBlinkMon
    db SE_MOVE_MON_HORIZONTALLY ; $F2
    dw AnimationMoveMonHorizontally
    db SE_RESET_MON_POSITION ; $F1
    dw AnimationResetMonPosition
    db SE_LIGHT_SCREEN_PALETTE ; $F0
    dw AnimationLightScreenPalette
    db SE_HIDE_MON_PIC ; $EF
    dw AnimationHideMonPic
    db SE_SQUISH_MON_PIC ; $EE
    dw AnimationSquishMonPic
    db SE_SHOOT_BALLS_UPWARD ; $ED
    dw AnimationShootBallsUpward
    db SE_SHOOT_MANY_BALLS_UPWARD ; $EC
    dw AnimationShootManyBallsUpward
    db SE_BOUNCE_UP_AND_DOWN ; $EB
    dw AnimationBoundUpAndDown
    db SE_MINIMIZE_MON ; $EA
    dw AnimationMinimizeMon
    db SE_SLIDE_MON_DOWN_AND_HIDE ; $E9
    dw AnimationSlideMonDownAndHide
    db SE_TRANSFORM_MON ; $E8
    dw AnimationTransformMon
    db SE_LEAVES_FALLING ; $E7
    dw AnimationLeavesFalling
    db SE_PETALS_FALLING ; $E6
    dw AnimationPetalsFalling
    db SE_SLIDE_MON_HALF_LEFT ; $E5
    dw AnimationSlideMonHalfLeft
    db SE_SHAKE_ENEMY_HUD ; $E4
    dw AnimationShakeEnemyHUD
    db SE_SHAKE_ENEMY_HUD_2 ; unused--same pointer as SE_SHAKE_ENEMY_HUD ($E4)
    dw AnimationShakeEnemyHUD
    db SE_SPIRAL_BALLS_INWARD ; $E2
    dw AnimationSpiralBallsInward
    db SE_DELAY_ANIMATION_10 ; $E1
    dw AnimationDelay10
    db SE_FLASH_ENEMY_MON_PIC ; unused--same as SE_FLASH_MON_PIC ($F5),but for the enemy mon
    dw AnimationFlashEnemyMonPic
    db SE_HIDE_ENEMY_MON_PIC ; $DF
    dw AnimationHideEnemyMonPic
    db SE_BLINK_ENEMY_MON ; $DE
    dw AnimationBlinkEnemyMon
    db SE_SHOW_MON_PIC ; $DD
    dw AnimationShowMonPic
    db SE_SHOW_ENEMY_MON_PIC ; $DC
    dw AnimationShowEnemyMonPic
