    ret

; flashes the screen for an extended period (48 frames)
AnimationFlashScreenLong: ; 79165 (1e:5165)
    ld a,3 ; cycle through the palettes 3 times
    ld [$D08A],a
    ld a,[wRunningOnSGB] ; running on SGB?
    and a
    ld hl,FlashScreenLongMonochrome
    jr z,.loop
    ld hl,FlashScreenLongSGB
.loop
    push hl
.innerLoop
    ld a,[hli]
    cp $01 ; is it the end of the palettes?
    jr z,.endOfPalettes
    ld [rBGP],a
    call FlashScreenLongDelay
    jr .innerLoop
.endOfPalettes
    ld a,[$D08A]
    dec a
    ld [$D08A],a
    pop hl
    jr nz,.loop
    ret

; BG palettes
FlashScreenLongMonochrome: ; 7918e (1e:518e)
    db %11111001 ; 3,3,2,1
    db %11111110 ; 3,3,3,2
    db %11111111 ; 3,3,3,3
    db %11111110 ; 3,3,3,2
    db %11111001 ; 3,3,2,1
    db %11100100 ; 3,2,1,0
    db %10010000 ; 2,1,0,0
    db %01000000 ; 1,0,0,0
    db %00000000 ; 0,0,0,0
    db %01000000 ; 1,0,0,0
    db %10010000 ; 2,1,0,0
    db %11100100 ; 3,2,1,0
    db $01 ; terminator

; BG palettes
FlashScreenLongSGB: ; 7919b (1e:519b)
    db %11111000 ; 3,3,2,0
    db %11111100 ; 3,3,3,0
    db %11111111 ; 3,3,3,3
    db %11111100 ; 3,3,3,0
    db %11111000 ; 3,3,2,0
    db %11100100 ; 3,2,1,0
    db %10010000 ; 2,1,0,0
    db %01000000 ; 1,0,0,0
    db %00000000 ; 0,0,0,0
    db %01000000 ; 1,0,0,0
    db %10010000 ; 2,1,0,0
    db %11100100 ; 3,2,1,0
    db $01 ; terminator

; causes a delay of 2 frames for the first cycle
; causes a delay of 1 frame for the second and third cycles
FlashScreenLongDelay: ; 791a8 (1e:51a8)
    ld a,[$D08A]
    cp 4 ; never true since [$D08A] starts at 3
    ld c,4
    jr z,.delayFrames
    cp 3
    ld c,2
    jr z,.delayFrames
    cp 2 ; nothing is done with this
    ld c,1
.delayFrames
    jp DelayFrames

AnimationFlashScreen: ; 791be (1e:51be)
