    push af ; save initial palette
    ld a,%00011011 ; 0,1,2,3 (inverted colors)
    ld [rBGP],a
    ld c,2
    call DelayFrames
    xor a ; white out background
    ld [rBGP],a
    ld c,2
    call DelayFrames
    pop af
    ld [rBGP],a ; restore initial palette
    ret

