    ld a,$e0
    ld b,$ff
    ld c,$b0
    jr nc,.asm_79e8b
    ld a,$50
    ld b,$1
    ld c,$a7
.asm_79e8b
    ld [$c0f1],a
    ld a,b
    ld [$c0f2],a
    ld a,c
    jp PlaySound

