    jr nz,.asm_7bee4
    pop bc
    add hl,de
    dec b
    jr nz,.asm_7bee3
    ld a,$1
    ld [H_AUTOBGTRANSFERENABLED],a ; $FF00+$ba
    call Delay3
    pop bc
    ret

Evolution_CheckForCancel: ; 7befa (1e:7efa)
    call DelayFrame
