Func_7d13b: ; 7d13b (1f:513b)
    ld a,[$FF00+$dc]
    ld c,$0
    ld hl,OwnedMonValues
.getSfxPointer
    cp [hl]
    jr c,.gotSfxPointer
    inc c
    inc hl
    jr .getSfxPointer
.gotSfxPointer
    push bc
    ld a,$ff
    ld [$c0ee],a
    call PlaySoundWaitForCurrent
    pop bc
    ld b,$0
    ld hl,PokedexRatingSfxPointers
    add hl,bc
    add hl,bc
    ld a,[hli]
    ld c,[hl]
    call PlayMusic
    jp PlayDefaultMusic

PokedexRatingSfxPointers: ; 7d162 (1f:5162)
    db (SFX_1f_51 - $4000) / 3
    db BANK(SFX_1f_51)
    db (SFX_02_41 - $4000) / 3
    db BANK(SFX_02_41)
    db (SFX_02_3a - $4000) / 3
    db BANK(SFX_02_3a)
    db (SFX_08_46 - $4000) / 3
    db BANK(SFX_08_46)
