    db BANK(SFX_02_3b)

OwnedMonValues: ; 7d170 (1f:5170)
    db 10,40,60,90,120,150,$ff

Func_7d177: ; 7d177 (1f:5177)
    ld c,CH0
.loop
    ld b,$0
    ld hl,$c026
    add hl,bc
    ld a,[hl]
    and a
    jr z,.nextChannel
    ld a,c
    cp CH4
    jr nc,.applyAffects ; if sfx channel
    ld a,[$c002]
    and a
    jr z,.applyAffects
    bit 7,a
    jr nz,.nextChannel
    set 7,a
    ld [$c002],a
    xor a
    ld [$FF00+$25],a
    ld [$FF00+$1a],a
    ld a,$80
    ld [$FF00+$1a],a
    jr .nextChannel
.applyAffects
    call Music1f_Music2_ApplyMusicAffects
.nextChannel
    ld a,c
    inc c ; inc channel number
    cp CH7
    jr nz,.loop
    ret

; this routine checks flags for music effects currently applied
; to the channel and calls certain functions based on flags.
; known flags for $c02e:
;    1: call has been used
;    3: a toggle used only by this routine for vibrato
;    4: pitchbend flag
;    6: dutycycle flag
Music1f_Music2_ApplyMusicAffects: ; 7d1ac (1f:51ac)
    ld b,$0
    ld hl,$c0b6 ; delay until next note
    add hl,bc
    ld a,[hl]
    cp $1 ; if delay is 1,play next note
    jp z,Music1f_Music2_PlayNextNote
    dec a ; otherwise,decrease the delay timer
    ld [hl],a
    ld a,c
    cp CH4
    jr nc,.startChecks ; if a sfx channel
    ld hl,$c02a
    add hl,bc
    ld a,[hl]
    and a
    jr z,.startChecks
    ret
.startChecks
    ld hl,$c02e
    add hl,bc
    bit 6,[hl] ; dutycycle
    jr z,.checkForExecuteMusic
    call Music1f_ApplyDutyCycle
.checkForExecuteMusic
    ld b,$0
    ld hl,$c036
    add hl,bc
    bit 0,[hl]
    jr nz,.checkForPitchBend
    ld hl,$c02e
    add hl,bc
    bit 2,[hl]
    jr nz,.disablePitchBendVibrato
.checkForPitchBend
    ld hl,$c02e
    add hl,bc
    bit 4,[hl] ; pitchbend
    jr z,.checkVibratoDelay
    jp Music1f_ApplyPitchBend
.checkVibratoDelay
    ld hl,$c04e ; vibrato delay
    add hl,bc
    ld a,[hl]
    and a ; check if delay is over
    jr z,.checkForVibrato
    dec [hl] ; otherwise,dec delay
.disablePitchBendVibrato
    ret
.checkForVibrato
    ld hl,$c056 ; vibrato rate
    add hl,bc
    ld a,[hl]
    and a
    jr nz,.vibrato
    ret ; no vibrato
.vibrato
    ld d,a
    ld hl,$c05e
    add hl,bc
    ld a,[hl]
    and $f
    and a
    jr z,.vibratoAlreadyDone
    dec [hl] ; apply vibrato pitch change
    ret
.vibratoAlreadyDone
    ld a,[hl]
    swap [hl]
    or [hl]
    ld [hl],a ; reset the vibrato value and start again
    ld hl,$c066
    add hl,bc
    ld e,[hl] ; get note pitch
    ld hl,$c02e
    add hl,bc
    bit 3,[hl] ; this is the only code that sets/resets bit three so
    jr z,.unset ; it continuously alternates which path it takes
    res 3,[hl]
    ld a,d
    and $f
    ld d,a
    ld a,e
    sub d
    jr nc,.noCarry
    ld a,$0
.noCarry
    jr .done
.unset
    set 3,[hl]
    ld a,d
    and $f0
    swap a
    add e
    jr nc,.done
    ld a,$ff
.done
    ld d,a
    ld b,$3
    call Func_7d8ac
    ld [hl],d
    ret

; this routine executes all music commands that take up no time,
; like tempo changes,duty changes etc. and doesn't return
; until the first note is reached
Music1f_Music2_PlayNextNote: ; 7d244 (1f:5244)
    ld hl,$c06e
    add hl,bc
    ld a,[hl]
    ld hl,$c04e
    add hl,bc
    ld [hl],a
    ld hl,$c02e
    add hl,bc
    res 4,[hl]
    res 5,[hl]
    call Music1f_endchannel
    ret

Music1f_endchannel: ; 7d25a (1f:525a)
    call Music1f_GetNextMusicByte
    ld d,a
    cp $ff ; is this command an endchannel?
    jp nz,Music1f_callchannel ; no
    ld b,$0 ; yes
    ld hl,$c02e
    add hl,bc
    bit 1,[hl]
    jr nz,.returnFromCall
    ld a,c
    cp CH3
    jr nc,.noiseOrSfxChannel
    jr .asm_7d2b3
.noiseOrSfxChannel
    res 2,[hl]
    ld hl,$c036
    add hl,bc
    res 0,[hl]
    cp CH6
    jr nz,.notSfxChannel3
    ld a,$0
    ld [$FF00+$1a],a
    ld a,$80
    ld [$FF00+$1a],a
.notSfxChannel3
    jr nz,.asm_7d296
    ld a,[$c003]
    and a
    jr z,.asm_7d296
    xor a
    ld [$c003],a
    jr .asm_7d2b3
.asm_7d296
    jr .asm_7d2bc
.returnFromCall
    res 1,[hl]
    ld d,$0
    ld a,c
    add a
    ld e,a
    ld hl,$c006
    add hl,de
    push hl ; store current channel address
    ld hl,$c016
    add hl,de
    ld e,l
    ld d,h
    pop hl
    ld a,[de]
    ld [hli],a
    inc de
    ld a,[de]
    ld [hl],a ; loads channel address to return to
    jp Music1f_endchannel
.asm_7d2b3
    ld hl,Unknown_7db93
    add hl,bc
    ld a,[$FF00+$25]
    and [hl]
    ld [$FF00+$25],a
.asm_7d2bc
    ld a,[$c02a]
    cp $14
    jr nc,.asm_7d2c5
    jr .asm_7d2e2
.asm_7d2c5
    ld a,[$c02a]
    cp $86
    jr z,.asm_7d2e2
    jr c,.asm_7d2d0
    jr .asm_7d2e2
.asm_7d2d0
    ld a,c
    cp CH4
    jr z,.asm_7d2d9
    call Func_7d73b
    ret c
.asm_7d2d9
    ld a,[$c005]
    ld [$FF00+$24],a
    xor a
    ld [$c005],a
.asm_7d2e2
    ld hl,$c026
    add hl,bc
    ld [hl],b
    ret

Music1f_callchannel: ; 7d2e8 (1f:52e8)
    cp $fd ; is this command a callchannel?
    jp nz,Music1f_loopchannel ; no
    call Music1f_GetNextMusicByte ; yes
    push af
    call Music1f_GetNextMusicByte
    ld d,a
    pop af
    ld e,a
    push de ; store pointer
    ld d,$0
    ld a,c
    add a
    ld e,a
    ld hl,$c006
    add hl,de
    push hl
    ld hl,$c016
    add hl,de
    ld e,l
    ld d,h
    pop hl
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[hld]
    ld [de],a ; copy current channel address
    pop de
    ld [hl],e
    inc hl
    ld [hl],d ; overwrite current address with pointer
    ld b,$0
    ld hl,$c02e
    add hl,bc
    set 1,[hl] ; set the call flag
    jp Music1f_endchannel

Music1f_loopchannel: ; 7d31d (1f:531d)
    cp $fe ; is this command a loopchannel?
    jp nz,Music1f_notetype ; no
    call Music1f_GetNextMusicByte ; yes
    ld e,a
    and a
    jr z,.infiniteLoop
    ld b,$0
    ld hl,$c0be
    add hl,bc
    ld a,[hl]
    cp e
    jr nz,.loopAgain
    ld a,$1 ; if no more loops to make
    ld [hl],a
    call Music1f_GetNextMusicByte ; skip pointer
    call Music1f_GetNextMusicByte
    jp Music1f_endchannel
.loopAgain ; inc loop count
    inc a
    ld [hl],a
    ; ft
.infiniteLoop ; overwrite current address with pointer
    call Music1f_GetNextMusicByte
    push af
    call Music1f_GetNextMusicByte
    ld b,a
    ld d,$0
    ld a,c
    add a
    ld e,a
    ld hl,$c006
    add hl,de
    pop af
    ld [hli],a
    ld [hl],b
    jp Music1f_endchannel

Music1f_notetype: ; 7d358 (1f:5358)
    and $f0
    cp $d0 ; is this command a notetype?
    jp nz,Music1f_togglecall ; no
    ld a,d ; yes
    and $f
    ld b,$0
    ld hl,$c0c6
    add hl,bc
    ld [hl],a ; store low nibble as speed
    ld a,c
    cp CH3
    jr z,.noiseChannel ; noise channel has 0 params
    call Music1f_GetNextMusicByte
    ld d,a
    ld a,c
    cp CH2
    jr z,.musicChannel3
    cp CH6
    jr nz,.notChannel3
    ld hl,$c0e7
    jr .sfxChannel3
.musicChannel3
    ld hl,$c0e6
.sfxChannel3
    ld a,d
    and $f
    ld [hl],a ; store low nibble of param as duty
    ld a,d
    and $30
    sla a
    ld d,a
    ; ft

    ; if channel 3,store high nibble as volume
    ; else,store volume (high nibble) and fade (low nibble)
.notChannel3
    ld b,$0
    ld hl,$c0de
    add hl,bc
    ld [hl],d
.noiseChannel
    jp Music1f_endchannel

Music1f_togglecall: ; 7d397 (1f:5397)
    ld a,d
    cp $e8 ; is this command an togglecall?
    jr nz,Music1f_vibrato ; no
    ld b,$0 ; yes
    ld hl,$c02e
    add hl,bc
    ld a,[hl]
    xor $1
    ld [hl],a ; flip bit 0 of $c02e (toggle returning from call)
    jp Music1f_endchannel

Music1f_vibrato: ; 7d3a9 (1f:53a9)
    cp $ea ; is this command a vibrato?
    jr nz,Music1f_pitchbend ; no
    call Music1f_GetNextMusicByte ; yes
    ld b,$0
    ld hl,$c04e
    add hl,bc
    ld [hl],a ; store delay
    ld hl,$c06e
    add hl,bc
    ld [hl],a ; store delay
    call Music1f_GetNextMusicByte
    ld d,a
    and $f0
    swap a
    ld b,$0
    ld hl,$c056
    add hl,bc
    srl a
    ld e,a
    adc b
    swap a
    or e
    ld [hl],a ; store rate as both high and low nibbles
    ld a,d
    and $f
    ld d,a
    ld hl,$c05e
    add hl,bc
    swap a
    or d
    ld [hl],a ; store depth as both high and low nibbles
    jp Music1f_endchannel

Music1f_pitchbend: ; 7d3e1 (1f:53e1)
    cp $eb ; is this command a pitchbend?
    jr nz,Music1f_duty ; no
    call Music1f_GetNextMusicByte ; yes
    ld b,$0
    ld hl,$c076
    add hl,bc
    ld [hl],a ; store first param
    call Music1f_GetNextMusicByte
    ld d,a
