SECTION "InizializzaParametriGBC",ROMX[$4400],BANK[$30]

InizializzaParametriGBC:

;    Imposta velocita' GBC a 1
    ld a,1
    ld [$FF00+$4D],a ; Speed Switch
    stop
    nop

;    Svuota 6 banchi di WRAM
    ld d,6
    ld hl,$d000
    ld bc,$1000
.Loop
    ld a,d
    inc a
    ld [$FF00+$70],a ; WRAM Bank
    push bc
    push hl
    xor a
    call FillMemory
    pop hl
    pop bc
    dec d
    jr nz,.Loop

;    Svuota WRAM1
    ld a,1
    ld [$FF00+$70],a ; WRAM Bank
    dec bc ; svuoto $999 byte per conservare il byte di scelta gameboy
    xor a
    call FillMemory

;    Svuota WRAM0
    ld hl,$c000
    ld bc,$1000
    call FillMemory

;    Imposta tutte le palette a nero
    ld a,2
    ld de,0
    ld hl,$ff68 ; BCPS/BGPI - CGB Mode Only - Background Palette Index
.LoopBgSprite
    push af
    ld a,$80
    ld b,8
    add hl,de
    ld [hli],a
.LoopAll8LeftPalette
    ld c,4
.LoopAll4Color
    xor a
    call FF47BlackOrWhite
    dec c
    jr nz,.LoopAll4Color
    dec b
    jr nz,.LoopAll8LeftPalette
    pop af
    dec a
    inc de
    jr nz,.LoopBgSprite
    ret

SECTION "FF47toColor",ROMX[$4800],BANK[$30]

FF47toColor:
    push bc
    push de
    push hl
    ld a,$02
    ld [H_LOADEDWRAMBANK],a
    ld a,[rBGP] ; $FF00+$47
    ld b,a
    ld a,[wLastrBGPUsed]
    cp b
    jr z,.rBGPNotChange
    ld a,$80
    ld b,$00
    ld hl,$ff68 ; BCPS/BGPI - CGB Mode Only - Background Palette Index
    ld [hli],a
.LoopAll8LeftPalette ; counter b
    ld c,$00
.LoopAll4Color ; counter c
    ld a,[rBGP] ; $FF00+$47
    push bc ; Store counter
    and a
    jr nz,.notWhite
    call FF47BlackOrWhite
    jr .Done
.notWhite
    cp $ff
    jr nz,.notBlack
    call FF47BlackOrWhite
    jr .Done
.notBlack
    xor a
    cp c
    ld a,[rBGP] ; $FF00+$47
    call nz,func4894
    call func48a2
.Done
    pop bc ; Restore counter
    inc c
    ld a,c
    cp $04
    jr nz,.LoopAll4Color
    inc b
    ld a,b
    cp $04
    jr nz,.LoopAll8LeftPalette
    ld a,[rBGP] ; $FF00+$47
    ld [wLastrBGPUsed],a
.rBGPNotChange
    ld a,[rOBP0] ; $FF00+$48
    ld b,a
    ld a,[wLastrOBP0Used]
    cp b
    jr z,.rOBP0NotChange
    ld a,$80
    ld b,0 ; ld b,$08
    ld hl,$ff6a ; OCPS/OBPI - CGB Mode Only - Sprite Palette Index
    ld [hli],a
.LoopAll8RightPalette
    ld c,$00
.LoopAll4RightColor
    ld a,[rOBP0] ; $FF00+$48
    push bc
    and a
    jr nz,.notRightWhite
    call FF47BlackOrWhite
    jr .DoneRight
.notRightWhite
    cp $ff
    jr nz,.notRightBlack
    call FF47BlackOrWhite
    jr .DoneRight
.notRightBlack
    xor a
    cp c
    ld a,[rOBP0] ; $FF00+$48
    call nz,func4894
    call func48a2
.DoneRight
    pop bc
    inc c
    ld a,c
    cp $04
    jr nz,.LoopAll4RightColor
    inc b
    ld a,b
    cp $4
    jr nz,.LoopAll8RightPalette
    ld a,[rOBP0] ; $FF00+$48
    ld [wLastrOBP0Used],a
.rOBP0NotChange
    call WriteVRAM2
    xor a
    ld [H_LOADEDWRAMBANK],a
    pop hl
    pop de
    pop bc
    ret

func4894:
.func4894
    rrca ; rlca
    rrca ; rlca
    dec c
    jr nz,.func4894
    ret

func48a2:
    and a,%00000011
    add a
    ld d,a
    ld a,b
    add a
    add a
    add a
    add d
    ld d,$d0
    ld e,a
    ld a,[de]
    push hl
    ld hl,H_LCDC_STATUS
.point48b9
    bit 1,[hl]
    jr nz,.point48b9
    pop hl
    ld [hl],a
    inc e
    ld a,[de]
    push hl
    ld hl,H_LCDC_STATUS
.point48c5
    bit 1,[hl]
    jr nz,.point48c5
    pop hl
    ld [hl],a
    ret

FF47BlackOrWhite:
    push hl
    ld hl,H_LCDC_STATUS
.WaitForBlack
    bit 1,[hl]
    jr nz,.WaitForBlack
    pop hl
    xor $FF
    ld [hl],a
    ld [hl],a
    ret

WriteVRAM2:
    ld a,[wForceVRAM2Writing]
    and a
    ret z
    xor a
    ld [wForceVRAM2Writing],a
    ld a,1
    ld [H_LOADEDVRAMBANK],a ; VRAM Bank 1 ($FF4F)

    ld bc,1024
    ld hl,wPreLoadOfVRAM2

    ld a,[wExceptionPaletteGbc]
    and a
    jr z,.NoException
    xor a
    ld [wExceptionPaletteGbc],a
    push hl
    ld h,b
    ld l,c
    ld de,-(32*10)
    add hl,de
    ld b,h
    ld c,l
    pop hl
    ld de,+(32*10)
    add hl,de

.NoException
    ld de,$9c00
.Loop9C
    ld a,[hli]
    push hl
    ld hl,H_LCDC_STATUS
.WaitForWrite9C
    bit 1,[hl]
    jr nz,.WaitForWrite9C
    ld [de],a
    inc de
    pop hl
    dec bc
    ld a,b
    or c
    jr nz,.Loop9C

    ld bc,1024
    ld hl,wPreLoadOfVRAM2
    ld de,$9800
.Loop98
    ld a,[hli]
    push hl
    ld hl,H_LCDC_STATUS
.WaitForWrite98
    bit 1,[hl]
    jr nz,.WaitForWrite98
    ld [de],a
    inc de
    pop hl
    dec bc
    ld a,b
    or c
    jr nz,.Loop98

    xor a
    ld [H_LOADEDVRAMBANK],a ; VRAM Bank 0 ($FF4F)
    ret

SECTION "DebugStoreColour",ROMX[$4A00],BANK[$30]

DebugStoreColour: ; 4c:4a8a (2015/09/29)
    ld a,$90
    ld [$d08f],a
    ld hl,$d000
    ld b,16
.LoopColour
    ld a,[hli]
    ld e,a
    ld a,[hli]
    ld d,a
    push hl
    push de
    ld a,[$d08f]
    ld l,a
    ld a,$d0
    ld h,a
    ld a,e
    and a,%00011111 ; RED
    call Conversion
    pop de
    push de
    ld a,d
    and a,%00000011
    sla a
    sla a
    sla a
    ld d,a
    ld a,e
    swap a
    srl a
    and a,%0000111
    add a,d ; GREEN
    call Conversion
    pop de
    push de
    ld a,d
    srl a
    srl a
    and a,%00011111 ; BLUE
    call Conversion
    ld a,l
    ld [$d08f],a
    pop de
    pop hl
    dec b
    jr nz,.LoopColour

    ld hl,$d090
    ld b,16
    ld e,0
.Loop3ByteColour
    ld a,[hli] ; red
    ld d,a
    ld a,[hli] ; green
    ld c,a
    and a,%00000111
    swap a
    sla a
    add d ; 1st Byte
    call StoreNewColour
    ld a,c
    sla a
    swap a
    and a,%00000011
    ld c,a
    ld a,[hli] ; blue
    sla a
    sla a
    add c ; 2nd Byte
    call StoreNewColour
    dec b
    jr nz,.Loop3ByteColour

    ld hl,$d000
    ld a,[hli]
    ld b,a
    ld a,[hld]
    ld c,a
    ld de,8
    ld a,3
.LoopCopyColor0
    push af
    add hl,de
    ld a,b
    ld [hli],a
    ld a,c
    ld [hld],a
    pop af
    dec a
    jr nz,.LoopCopyColor0

    ret

StoreNewColour:
    push hl
    ld h,$d0
    ld l,e
    ld [hl],a
    pop hl
    inc e
    ret

TableConversion:
    db 00,00,00,00,00,01,01,01,02,02,04,05,06,08,11,11,11,12,12,12,13,15,16,18,20,22,25,31,31,31,31,31
Conversion:
    push hl
    ld hl,TableConversion - 1
    inc a
.LoopTable
    inc hl
    dec a
    jr nz,.LoopTable
    ld a,[hl]
    pop hl
    ld [hli],a
    ret

SECTION "bank31",ROMX,BANK[$31]

SuperPalettes:
    INCLUDE "constants/SuperPalettes.asm"

; ─────────────────────────────────────────

BorderPalettes:
    INCBIN "gfx/red/sgbborder.map"

    ds $AA+$56

    RGB 30,29,29 ; PAL_SGB1
    RGB 25,22,25
    RGB 25,17,21
    RGB 24,14,12

    ds $18

    RGB 30,29,29 ; PAL_SGB2
    RGB 22,31,16
    RGB 27,20,6
    RGB 15,15,15

    ds $18

    RGB 30,29,29 ; PAL_SGB3
    RGB 31,31,17
    RGB 18,21,29
    RGB 15,15,15

    ds $18

; ─────────────────────────────────────────

SelectInOverWorld:
    ld hl,wSelectInOverworldOnBit6
    set 6,[hl]
    xor a
    ld [wSkillMonID],a
    PREDEF Func_c586 ; Update Next Tile
    scf ; set carry flag
    ld a,[H_CURRENTPRESSEDBUTTONS] ; ▼▲◄►StSeBA
    bit 0,a ; A button (carry flag not affected)
    jr nz,.SelectPlusA
    bit 1,a ; B button (carry flag not affected)
    jr nz,.SelectPlusB
    ; ft
.Select
    call c,.TryFishing
    call c,.TryBike
    jr .end
.SelectPlusA
    call c,.TryItemFinder
    jr .end
.SelectPlusB
    call c,.TryLight
    call c,.TryCut
    call c,.TryFloat
    call c,.TryStrength
    ; ft
.end
    xor a
    ld [wSkillMonID],a
    ld hl,wSelectInOverworldOnBit6
    res 6,[hl]
    ret

.TryCut
    ; ──────────────────────────────────── Cut
    BANKSWITCH CheckCutTile
    jr nz,.noCut
    ld a,[W_CURMAPTILESET]
    cp 23 ; plateau
    jr z,.noCut
    ld hl,CUT_FLAG_BYTE
    bit CUT_FLAG_BIT,[hl]
    jr z,.noCut
    ld b,CUT_SKILL_SORT
    call SearchSkillInParty
    jr nc,.noCut
.canCut
    call .PlayCry
    call .StartCustomSelectFunction
    BANKSWITCH CanCut
    jp .EndCustomSelectFunction
.noCut
    scf ; set carry flag
    ret

.TryFloat
    ; ──────────────────────────────────── Float
    ld a,[$d700]
    ld [$d11a],a
    cp 2 ; is the player surfing?
    jp z,.noFloat
    BANKSWITCH IsSurfingAllowed
    ld hl,$d728
    bit 1,[hl]
    res 1,[hl]
    jp z,.noFloat
    call IsNextTileShoreOrWater
    jp c,.noFloat
    ld d,%00000100 ; CanSurfing
    call CheckExceptionTilePassable
    jp c,.noFloat
    ld hl,wCollisionWithSpriteBit5
    bit 5,[hl]
    jr nz,.noFloat
    ld b,SURFBOARD
    call .IsItemInBag
    ld a,0 ; wSurfingMonID
    jr nz,.canFloatNoCry
    ld hl,FLOAT_FLAG_BYTE
    bit FLOAT_FLAG_BIT,[hl]
    jr z,.noFloat
    call CheckLaprasInPartyWithEnergy
    jr c,.canFloat
    ld b,FLOAT_SKILL_SORT
    call SearchSkillInParty
    jr nc,.noFloat
.canFloat
    call .PlayCry
    ld a,[wWhichPokemon]
    ld hl,W_PARTYMON1
    ld b,0
    ld c,a
    add hl,bc
    ld a,[hl]
.canFloatNoCry
    ld [wSurfingMonID],a
    call .StartCustomSelectFunction
    ld a,SURFBOARD
    ld [$cf91],a
    ld [$d152],a
    call UseItem
    jp .EndCustomSelectFunction
.noFloat
    scf ; set carry flag
    ret

.TryLight
    ; ──────────────────────────────────── Light
    ld a,[$d35d]
    and a
    jr z,.noLight
    ; Check Surfing
    ld a,[$d700]
    cp 2 ; Surfing?
    jr nz,.SurfingCheckOK
    call IsSurfingOnLapras
    jr nz,.noLight
.SurfingCheckOK
    ld b,BENGAL
    call .IsItemInBag
    jr nz,.canLightNoCry
    ld hl,LIGHT_FLAG_BYTE
    bit LIGHT_FLAG_BIT,[hl]
    jr z,.noLight
    ld b,LIGHT_SKILL_SORT
    call SearchSkillInParty
    jr nc,.noLight
.canLight
    call .PlayCry
    jr .ContinueLight
.canLightNoCry
    ld hl,wOverworlLightSoundBit4
    set 4,[hl]
.ContinueLight
    call .StartCustomSelectFunction
    ld hl,wOverworlNoTextBit2
    set 2,[hl]
    ld a,BENGAL
    ld [$cf91],a
    ld [$d152],a
    call UseItem
    jp .EndCustomSelectFunction
.noLight
    scf ; set carry flag
    ret

.TryStrength
    ; ──────────────────────────────────── Strength
    ld hl,$d728
    bit 0,[hl]
    jr nz,.noStrength
    ld a,[$d700]
    cp 2 ; is the player surfing?
    jp z,.noStrength
    ld hl,STRENGTH_FLAG_BYTE
    bit STRENGTH_FLAG_BIT,[hl]
    jr z,.noStrength
    ld b,STRENGTH_SKILL_SORT
    call SearchSkillInParty
    jr nc,.noStrength
.canStrength
    call .PlayCry
    call .StartCustomSelectFunction
    ld hl,$d728
    set 0,[hl]
    ld hl,wOverworlStrengthAnimBit1
    set 1,[hl]
    ld hl,wOverworlNoTextBit2
    set 2,[hl]
    jp .EndCustomSelectFunction
.noStrength
    scf ; set carry flag
    ret

.TryFishing
    ; ──────────────────────────────────── Fishing
    ld a,[$d700]
    cp 2 ; is the player surfing?
    jp z,.noFishing
    call IsNextTileShoreOrWater ; unsets carry if player is facing water or shore
    jr c,.noFishing
    ld d,%00000100 ; CanSurfing
    call CheckExceptionTilePassable
    jr c,.noFishing
    ;are rods in the bag?
    ld hl,wNumBagItems
    ld a,[hli]
    and a
    jr z,.noFishing
    ld c,a
.SearchFishingLoop
    ld a,[hli]
    ld b,a
    cp $ff
    jr z,.noFishing
    cp SUPER_ROD
    jr z,.Fishing
    cp GOOD_ROD
    jr z,.Fishing
    cp OLD_ROD
    jr z,.Fishing
    inc hl
    dec c
    jr nz,.SearchFishingLoop
    jr .noFishing
.Fishing
    call .StartCustomSelectFunction
    ld a,b
    ld [$cf91],a ; load item to be used
    ld [$d11e],a ; load item so its name can be grabbed
    call GetItemName ; get the item name into de register
    call CopyStringToCF4B ; copy name from de to wcf4b so it shows up in text
    call UseItem
    jp .EndCustomSelectFunction
.noFishing
    scf ; set carry flag
    ret

.TryBike
    ; ──────────────────────────────────── Bike
    ld b,BICYCLE
    call .IsItemInBag
    jr z,.noBike
    ld a,[$d732] ; Force to Ride Bike
    bit 5,a      ; ...
    jr nz,.noBike
    call IsBikeRidingAllowed
    jp nc,.noBike
    ld a,[$d700]
    cp 2 ; is the player surfing?
    jp z,.noBike
.BikeOrWalk
    push af
    call .StartCustomSelectFunction
    call UpdateSprites
    pop af
    dec a ; is player already bicycling?
    jr nz,.tryToGetOnBike
.getOffBike
    xor a
    jr .doneBike
.tryToGetOnBike
    ld a,1
.doneBike
    ld [$d700],a ; change player state to bicycling
    jp .EndCustomSelectFunction
.noBike
    scf ; set carry flag
    ret

.TryItemFinder
    ; ──────────────────────────────────── ItemFinder
    ld b,ITEMFINDER
    call .IsItemInBag
    jr z,.noItemFinder
.ItemFinder
    call .StartCustomSelectFunction
    ld a,b
    ld [$cf91],a ; load item to be used
    ld [$d11e],a ; load item so its name can be grabbed
    call GetItemName ; get the item name into de register
    call CopyStringToCF4B ; copy name from de to wcf4b so it shows up in text
    call UseItem
    jp .EndCustomSelectFunction
.noItemFinder
    scf ; set carry flag
    ret

.IsItemInBag
    push bc
    call IsItemInBag
    pop bc
    ret

.StartCustomSelectFunction
    push bc
    call .InitializeTextBox
    pop bc
    ret

.EndCustomSelectFunction
    call .DisplayNothing
    xor a ; reset carry flag
    ret

.PlayCry
    ld a,[wWhichPokemon]
    push af
    ld hl,W_PARTYMON1NAME ; $d2b5
    call GetPartyMonName
    pop af
    ld hl,W_PARTYMON1
    ld b,0
    ld c,a
    add hl,bc
    ld a,[hl]
    call GetCryData ; get cry data
    jp PlaySound ; play sound

.InitializeTextBox
    ; initialize a text box without drawing anything special
    ld a,1
    ld [$cf0c],a
    BANKSWITCH_JUMP DisplayTextIDInit ; initialization

.DisplayNothing
    ;use $ff value loaded into $FF8C to make DisplayTextID display nothing and close any text
    ld a,$ff
    ld [$FF8C],a
    jp DisplayTextID

CheckLaprasInPartyWithEnergy:
    ld hl,W_NUMINPARTY
    ld a,[hli]
    and a
    jr z,.NotFound
    ld b,a
    ld c,0
.Loop
    ld a,[hli]
    cp $FF
    jr z,.NotFound
    cp LAPRAS
    jr z,.Found
.Next
    inc c
    dec b
    jr nz,.Loop
.NotFound
    xor a ; rcf
    ret
.Found ; LAPRAS Learn SKILL_FLOAT at Level 1
    ld a,c
    ld [wWhichPokemon],a
    call .CheckAndDecreaseSkillEnergy
    jr c,.Next
    call SetSkillMonID
    scf
    ret
.CheckAndDecreaseSkillEnergy
    push hl
    push bc
    BANKSWITCH CheckAndDecreaseSkillEnergy
    pop bc
    pop hl
    ret

; INPUT  : b = Skill
; OUTPUT : carry flag -> set found | reset not found
SearchSkillInParty:
    ld a,[W_NUMINPARTY]
    and a
    jr z,.notfound
    ld d,a
    ld c,0
.LoopMon
    ld a,c
    ld [wWhichPokemon],a
    call .GetMonSkill
    ld a,[wNumSkill]
    and a
    jr z,.NextMon
    ld e,a ; NumSkill
    ld hl,wSkill
.LoopSkill
    ld a,[hli]
    cp b ; Skill
    jr z,.found
    dec e
    jr nz,.LoopSkill
.NextMon
    inc c
    dec d
    jr nz,.LoopMon
.notfound
    xor a ; rcf
    ret
.found
    ld hl,wDontCheckEnergySkillBit0
    bit 0,[hl]
    jr nz,.SkipCheckEnergy
    call .CheckAndDecreaseSkillEnergy
    jr c,.NextMon
.SkipCheckEnergy
    ld hl,wDontCheckEnergySkillBit0
    bit 0,[hl]
    call z,SetSkillMonID
    scf
    ret
.GetMonSkill
    push bc
    push de
    BANKSWITCH GetMonSkill
    pop de
    pop bc
    ret
.CheckAndDecreaseSkillEnergy
    push bc
    BANKSWITCH CheckAndDecreaseSkillEnergy
    pop bc
    ret

SetSkillMonID:
    ld a,[wWhichPokemon]
    ld hl,W_PARTYMON1
    ld b,0
    ld c,a
    add hl,bc
    ld a,[hl]
    ld [wSkillMonID],a
    ret

; ──────────────────────────────────────────────────────────────────────

; Input 
; b = XXX_SKILL_SORT
LearnSkill:
    call Load16BitRegisters
    push bc
    call .Animation
    ld hl,.LearnSkill
    call PrintText
    pop bc
    ld hl,wDontCheckEnergySkillBit0
    set 0,[hl]
    call SearchSkillInParty
    ld hl,wDontCheckEnergySkillBit0
    res 0,[hl]
    ret
.LearnSkill
    TX_FAR _LearnSkillText
    db $10,$0,$58,"@"

.Animation
    call GBFadeOut2
    call ReloadMapData
    ld a,[$C0EF]
    cp BANK(Music_PkmnHealed)
    ld [$C0F0],a
    jr z,.skip
    ld a,$ff
    ld [$C0EE],a
    call PlaySound
    ld a,BANK(Music_PkmnHealed)
    ld [$C0EF],a
.skip
    ld a,$E8
    ld [$C0EE],a
    call PlaySound ; play sound?
.WaitLoop
    ld a,[$C026]
    cp $E8
    jr z,.WaitLoop
    ld a,[$C0F0]
    ld [$C0EF],a
    ld a,[$D35B]
    ld [$C0EE],a
    call PlaySound
    jp GBFadeIn2

