; INPUT
; e = Low Bit Return Pointer
_HackItemInBattle:
    ld hl,.Table
.Loop
    ld a,[hli]
    cp $ff
    jr z,.End
    cp e
    jr z,.Found
    inc hl
    inc hl
    jr .Loop
.Found
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ld a,[W_ISINBATTLE]
    and a
    jp hl
.End
    ret
.Step1:
    ld a,$0d ; list menu text box ID
    jr z,.Step1Done
    ld a,$77 ; list menu text box ID
.Step1Done
    ld [$d125],a ; $2c16
    ret
.Step2:
    FuncCoord 4,2 ; coordinates of upper left corner of menu text box
    ld de,Coord
    ret z
    FuncCoord 4,7 ; coordinates of upper left corner of menu text box
    ld de,Coord ; $2c1f
    ret
.Step3
    ld a,4
    jr z,.Step3Done
    ld a,9
.Step3Done
    ld [wTopMenuItemY],a ; $2c41
    ret
.Step4
    FuncCoord 5,3 ; $c3e1
    ld de,Coord
    ret z
    FuncCoord 5,8 ; $c3e1
    ld de,Coord ; $2e5a
    ret
.Step5
    FuncCoord 6,4 ; coordinates of first list entry name
    ld de,Coord
    ret z
    FuncCoord 6,9 ; coordinates of first list entry name
    ld de,Coord ; $2e82
    ret
.Table
    db $17 + 3
    dw .Step1
    db $20 + 3
    dw .Step2
    db $41 + 3
    dw .Step3
    db $5a + 3
    dw .Step4
    db $82 + 3
    dw .Step5
    db $ff

SECTION "bank33",ROMX,BANK[$33] ; Denim,GENDER

_DrawCatchGender: ; Denim
; catch
    call IsGhostBattle
    jp z,.Ghost ; No Gender,Pokedex or Debug If Ghost Battle
    call .CheckEnemyOwned
    jr z,.SkipCatchFlagIcon
    ld a,[W_ISINBATTLE] ; trainer battle,this is 2
    dec a
    dec a
    jr z,.SkipCatchFlagIcon
    FuncCoord 1,1
    ld hl,Coord
    ld de,.PokeBallCatchFlagIcon
    call .PlaceIcon
.SkipCatchFlagIcon
    ld hl,W_ENEMYMONATKDEFIV ; .FrontSpriteInBattle
    call CheckShiny
    call SetTempIV
    jr nz,.NoShiny
    FuncCoord 1,1
    ld hl,Coord
    ld de,.ShinyStarIcon
    call .PlaceIcon
.NoShiny
    call .CheckEnemyOwned
    ld a,[W_ENEMYMON_START]
    ld [$d11e],a
    jr z,.Genderless
    call GetGender
    jr c,.Genderless
    push af
    ld a,[W_ENEMYMONLEVEL]
    cp 10
    FuncCoord 05,01
    ld hl,Coord
    jr nc,.GreaterThen9
    dec hl
.GreaterThen9
    pop af
    ld de,.MaleIcon
    jr nz,.PrintGender
    ld de,.FemaleIcon
.PrintGender
    call .PlaceIcon
.Genderless
    call DebugStats
    jp ResetTempIV
.Ghost
    ld hl,W_ENEMYMONATKDEFIV ; .FrontSpriteInBattle
    call SetTempIV
    jr .Genderless
.CheckEnemyOwned
    ld a,[W_ENEMYMON_START]
    ld [$d11e],a
    PREDEF IndexToPokedex
    ld a,[$d11e]
    ld hl,wPokedexOwned
    ld c,a
    ld b,2
    PREDEF HandleBitArray ; IsPokemonBitSet_bankF
    ld a,c
    and a
    ret
.PlaceIcon
    ld a,[de]
    ld [hl],a
    ret
.PokeBallCatchFlagIcon:
    db $C9
.MaleIcon
    db $EF
.FemaleIcon
    db $F5
.ShinyStarIcon
    db $D1

_DrawCurrentMonGenderInBattle:
    ld hl,W_PLAYERMONIVS ; .BackSpriteInBattle
    call SetTempIV
    ld a,[W_PLAYERMONID]
    ld [$d11e],a
    call GetGender
    jr c,.Genderless
    push af
    ld a,[W_PLAYERMONLEVEL]
    cp 10
    FuncCoord 13,08 ; Player Gender in Battle
    ld hl,Coord
    jr nc,.GreaterThen9
    dec hl
.GreaterThen9
    pop af
    ld de,.MaleIcon
    jr nz,.Male
    ld de,.FemaleIcon
.Male
    call .PlaceIcon
.Genderless
    call ResetTempIV
    ret
.PlaceIcon
    ld a,[de]
    ld [hl],a
    ret
.MaleIcon
    db $EF
.FemaleIcon
    db $F5

DebugStats:
    and a ; rcf
    ld a,[H_CURRENTPRESSEDBUTTONS]
    bit 2,a ; was the select button pressed?
    ret z
    ; ──────────────────────────
    ; ENEMY
    ; ──────────────────────────
    ; Clear Screen Area
    FuncCoord 00,00
    ld hl,Coord
    ld bc,$040B
    call ClearScreenArea
    ; Print IV
    FuncCoord 00,00
    ld hl,Coord
    ld de,wDVForShinyAtkDef
    call .Print4IV
    ; Print Stat Mod
    FuncCoord 06,00
    ld hl,Coord
    ld de,wEnemyMonStatMods
    call .PrintStatMod
    ; Print ATK/DEF/SPD/SPC
    FuncCoord 03,00
    ld hl,Coord
    ld de,W_ENEMYMONATTACK
    call .Print4Stat
    ; Print Current HP / Max HP
    FuncCoord 07,00
    ld hl,Coord
    ld de,W_ENEMYMONMAXHP
    call .PrintStat
    ld de,W_ENEMYMONCURHP
    call .PrintStat
    ; Print Energy & Alternate Form ID
    ld de,W_ENEMYMONENERGY ; W_ENEMYMONALTFORM
    call .Print2Stat1Byte
    ; ──────────────────────────
    ; PLAYER
    ; ──────────────────────────
    ; Clear Screen Area
    FuncCoord 10,07
    ld hl,Coord
    ld bc,$050A
    call ClearScreenArea
    ; Print IV
    FuncCoord 10,08
    ld hl,Coord
    ld de,W_PLAYERMONIVS
    call .Print4IV
    ; Print Stat Mod
    FuncCoord 16,08
    ld hl,Coord
    ld de,wPlayerMonStatMods
    call .PrintStatMod
    ; Print ATK/DEF/SPD/SPC
    FuncCoord 13,08
    ld hl,Coord
    ld de,W_PLAYERMONATK
    call .Print4Stat
    ; Print Current HP / Max HP
    FuncCoord 17,08
    ld hl,Coord
    ld de,W_PLAYERMONMAXHP
    call .PrintStat
    ld de,W_PLAYERMONCURHP
    call .PrintStat
    ; Print Energy & Alternate Form ID
    ld de,W_PLAYERMONENERGY ; W_PLAYERMONALTFORM
    call .Print2Stat1Byte
    ; End
    scf
    ret

.Print4IV
    push de
    call .Print2IV
    pop de
    inc de
.Print2IV
    ld a,[de]
    call .PrintIV
    swap a
.PrintIV
    push af
    srl a
    srl a
    srl a
    srl a
    ld [$d11e],a
    ld de,$d11e
    ld bc,(%10000001<<8)+2 ; two digits
    call PrintNumber
    ld de,18
    add hl,de
    pop af
    ret
.Print4Stat
    call .PrintStat
    call .PrintStat
.Print2Stat
    call .PrintStat
.PrintStat
    push de
    ld bc,$0203 ; three digits
    call PrintNumber
    ld de,17
    add hl,de
    pop de
    inc de
    inc de
    ret
.Print2Stat1Byte
    call .PrintStat1Byte
.PrintStat1Byte
    push de
    ld bc,$0103 ; three digits
    call PrintNumber
    ld de,17
    add hl,de
    pop de
    inc de
    ret
.PrintStatMod
    ld c,4
.loop
    push bc
    ld a,[de]
    inc de
    cp 7
    ld [hl],$7F ; neutral
    jr z,.next
    cp 8
    ld [hl],$D2 ; plus
    jr nc,.next
    ld [hl],$E3 ; minus
.next
    ld bc,20
    add hl,bc
    pop bc
    dec c
    jr nz,.loop
    ret

