    ld a,[wDVForShinyAtkDef]
    call .PrintIV
    swap a
    call .PrintIV
    ld a,[wDVForShinySpdSpc]
    call .PrintIV
    swap a
    call .PrintIV
    ; Print exp point
    ld bc,$0205 ; five digits
    ; Print HP exp point
    FuncCoord 14,7
    ld hl,Coord
    ld de,$cfa9
    call .PrintStatBR
    ; Print ATK/DEF exp point
    FuncCoord 14,9
    ld hl,Coord
    ld de,$cfab
    call .PrintStatBR
    ld de,$cfad
    call .PrintStatBR
    ; Print SPD/SPC exp point
    ld de,$cfaf
    call .PrintStatBR
    ld de,$cfb1
    call .PrintStatBR
    ; Clear Screen for Exclusive & Type
    FuncCoord 00,07
    ld hl,Coord
    ld bc,$0609
    call ClearScreenArea
    ; Print Exclusive Moves Flag
    FuncCoord 00,07
    ld hl,Coord
    ld de,$cf9d ; type1
