    ld bc,$0103
    call PrintNumber
    FuncCoord 00,10
    ld hl,Coord
    ld de,wTempExclusiveByte02
    ld bc,$0103
    call PrintNumber
    FuncCoord 00,11
    ld hl,Coord
    ld de,wTempExclusiveByte03
    ld bc,$0103
    call PrintNumber
    FuncCoord 00,12
    ld hl,Coord
    ld de,$cfb7 ; ex pp 3
    ld bc,$0103
    call PrintNumber
    ; Print Ex PP
    FuncCoord 04,09
    ld hl,Coord
