.PrintIV
    push af
    srl a
    srl a
    srl a
    srl a
    ld [$d11e],a
    ld de,$d11e
    ld c,2
    ld b,%10000001
    call PrintNumber
    ld de,18+20
    add hl,de
    pop af
    ret
.PrintStatBR
    push bc
    push hl
    push de
    ld bc,$0105
    call ClearScreenArea
    pop de
    pop hl
    pop bc
    call PrintNumber
    ld de,15+20
    add hl,de
    ret
.DebugStatsText
