    db "   ",$4e
    db "   ",$4e
    db "   ",$4e
    db "   @"

; INPUT :
; $d11e = Pokemon ID
; wDVForShinyAtkDef = ATK/DEF
; wDVForShinySpdSpc = SPD/SPC
GetGender:
    ld a,[$d11e]
    and a
    jr z,.Genderless
    cp CHARIZARD_M
    jr nz,.NoCharizardM
    ld a,CHARIZARD
.NoCharizardM
    ld b,a
    ld hl,Genderless
    call IsInTable
    jr nz,.Genderless
    ld hl,OnlyMale
    call IsInTable
    jr nz,.Male
    ld hl,OnlyFemale
    call IsInTable
    jr nz,.Female
    ld a,b
    ld [$d11e],a
    PREDEF IndexToPokedex
    ld a,[$d11e]
    and a
    jr z,.Genderless ; MissingNo
    ;ds 1 ; dec a ; 00MOD
    ld b,a
    srl a
    srl a
    ld e,a
    ld d,0
    ld hl,GenderTable
    add hl,de
    ld a,b
    and a,%00000011
    ld b,[hl]
.LoopCycle
    cp 3
    jr z,.EndCycle
    srl b
    srl b
    inc a
    jr .LoopCycle
.EndCycle
    ld a,b
    and a,%00000011
    ld hl,GenderConstant
    ld e,a
    ld d,0
    add hl,de
    ld a,[hl]
    push af
    ld hl,wDVForShinyAtkDef
    ld a,[hli]
    and a,$F0
    ld b,a
    ld a,[hl]
    and a,$F0
    swap a
    add b
    ld b,a
    pop af
    cp b
    jr c,.Male
.Female
    xor a
    ret
.Male
    ld a,1
    and a
    ret
.Genderless
    scf
    ret

IsInTable:
.Loop
    ld a,[hli]
    cp b
    jr z,.Found
    inc a ; Compare $FF
    jr nz,.Loop
    ret ; z notFound
.Found
    xor a
    inc a
    ret ; nz Found

