_CheckDarkMap:
    call Load16BitRegisters
    push bc
    push de
    push hl
    call .Main
    pop hl
    pop de
    pop bc
    ret
.Main
    call GetCurrentOldAdventureMap
    ld hl,.DarkMapList
    ld de,1
    call IsInArray
    ld hl,$d35d
    jr c,.Dark
.Light
    xor a
    cp [hl]
    ld [hl],a
    ret nz ; from dark to light
    jr .TryGBFadeIn1
.Dark
    ld a,$06
    cp [hl]
    ld [hl],a
    ret z ; from dark to dark
.TryGBFadeIn1
    ld a,[$d732] ; fall in hole
    bit 4,a      ; ...
    ret nz
    ld a,[wOverworldGoToDarkBit4] ; Force Go To Dark
    bit 4,a                       ; ...
    ret nz
    jp GBFadeIn1
.DarkMapList
    db ROCK_TUNNEL_1
    db ROCK_TUNNEL_2
    db VICTORY_ROAD_1
    db VICTORY_ROAD_2
    db VICTORY_ROAD_3
    db SEAFOAM_ISLANDS_1
    db SEAFOAM_ISLANDS_2
    db SEAFOAM_ISLANDS_3
    db SEAFOAM_ISLANDS_4
    db SEAFOAM_ISLANDS_5
    db UNKNOWN_DUNGEON_1
    db UNKNOWN_DUNGEON_2
    db UNKNOWN_DUNGEON_3
    db UNKNOWN_DUNGEON_4
    db POKEMONTOWER_3
    db POKEMONTOWER_4
    db POKEMONTOWER_5
    db POKEMONTOWER_6
    db POKEMONTOWER_7
    db DRATINI_CAVE
    db $FF

