DecAttackPlayer:
    push hl
    ld hl,$d06a ; PlayerNumAttacksLeft
    jr DecAttack
DecAttackEnemy:
    push hl
    ld hl,$d06f ; EnemyNumAttacksLeft
    ; ft
DecAttack:
    dec [hl]
    pop hl
    ret

;Battle status2 in "a"
;resets the rage bit in "a" if zero flag is set
DeactivateRageInA:
    ret nz
    res 6,a ; USING_RAGE
    ret

HandlePlayerRageAndThrashing:
    ; decrement the rage counter
    ld a,[W_PLAYERBATTSTATUS2]
    bit 6,a ; USING_RAGE
    jr z,.not_raging
    call DecAttackPlayer
    call DeactivateRageInA
    ld [W_PLAYERBATTSTATUS2],a
    ; if raging, reset rage's accuracy here to prevent degradation
    ld a,$FF
    ld [W_PLAYERMOVEACCURACY],a
.not_raging
    ; if thrashing, reset the move accuracy here to prevent degradation
    ld a,[W_PLAYERBATTSTATUS1]
    bit 1,a ; THRASHING_ABOUT
    jr z,.not_thrashing
    ld a,$FF
    ld [W_PLAYERMOVEACCURACY],a
.not_thrashing
    ret

HandleEnemyRageAndThrashing:
    ; decrement the rage counter
    ld a,[W_ENEMYBATTSTATUS2]
    bit 6,a ; USING_RAGE
    jr z,.not_raging
    call DecAttackEnemy
    call DeactivateRageInA
    ld [W_ENEMYBATTSTATUS2],a
    ; if raging, reset rage's accuracy here to prevent degradation
    ld a,$FF
    ld [W_ENEMYMOVEACCURACY],a
.not_raging
    ; if thrashing, reset the move accuracy here to prevent degradation
    ld a,[W_ENEMYBATTSTATUS1]
    bit 1,a ; THRASHING_ABOUT
    jr z,.not_thrashing
    ld a,$FF
    ld [W_ENEMYMOVEACCURACY],a
.not_thrashing
    ret

; ───────────────────────────────────────
; HandlePoisonBurnLeechSeed_
; ───────────────────────────────────────

HandlePoisonBurnLeechSeed_:
    ld hl,W_PLAYERMONCURHP
    ld de,W_PLAYERBATTSTATUS2
    ld bc,W_PLAYERMONSTATUS
    ld a,[H_WHOSETURN]
    and a
    jr z,.playersTurn
    ld hl,W_ENEMYMONCURHP
    ld de,W_ENEMYBATTSTATUS2
    ld bc,W_ENEMYMONSTATUS
.playersTurn
    call .IsFainted
    jp z,.Faintened
    ld a,[bc]
    bit FRZ_Bit,a
    jp nz,.Frozen
    push hl
    ld a,[H_WHOSETURN]
    and a
    ld hl,W_ENEMYMONCURHP
    jr z,.playersTurn2
    ld hl,W_PLAYERMONCURHP
.playersTurn2
    call .IsFainted
    pop hl
    jr z,.notLeechSeeded
    ld a,[de]
    bit SEEDED,a
    jr z,.notLeechSeeded
    push bc
    push hl
    push hl
    ld hl,.HurtByLeechSeedText
    call PrintText
    pop hl
    ld a,[H_WHOSETURN]
    push af
    xor $1
    ld [H_WHOSETURN],a
    xor a
    ld [$cc5b],a
    ld a,ABSORB
    call .PlayMoveAnimation ; play leech seed animation (from opposing mon)
    pop af
    ld [H_WHOSETURN],a
    pop hl
    call PoisonBurnLeechSeed_DecreaseOwnHP
    call LeechSeed_IncreaseEnemyHP
    call .WaitForTextScrollButtonPress
    pop bc
    call .IsFainted
    jr z,.Faintened
.notLeechSeeded
    ld a,[bc]
    bit PSN_Bit,a
    jr z,.notPoisoned
    push bc
    push hl
    push hl
    ld hl,.HurtByPoisonText
    call PrintText
    pop hl
    xor a
    ld [$cc5b],a
    ld a,$BA
    call .PlayMoveAnimation ; play poison animation
    pop hl
    ld a,[wUnusedC000]
    set 6,a ; set the bit that indicates poison is being handled
    ld [wUnusedC000],a
    call PoisonBurnLeechSeed_DecreaseOwnHP
    ld a,[wUnusedC000]
    res 6,a ; reset the bit that indicates poison is being handled
    ld [wUnusedC000],a
    call .WaitForTextScrollButtonPress
    pop bc
    call .IsFainted
    jr z,.Faintened
.notPoisoned
    ld a,[bc]
    bit BRN_Bit,a
    jr z,.notBurned
    push bc
    push hl
    push hl
    ld hl,.HurtByBurnText
    call PrintText
    pop hl
    xor a
    ld [$cc5b],a
    ld a,[H_WHOSETURN]
    push af
    xor $1
    ld [H_WHOSETURN],a
    ld a,EMBER
    call .PlayMoveAnimation ; play burn animation (from opposing mon)
    pop af
    ld [H_WHOSETURN],a
    pop hl
    call PoisonBurnLeechSeed_DecreaseOwnHP
    call .WaitForTextScrollButtonPress
    pop bc
    call .IsFainted
    jr z,.Faintened
.notBurned
.Frozen
    call .IsFainted
    jr z,.Faintened
.NotFaintened
    ld a,1 ; rzf
    and a  ; ...
    ret
.Faintened
    ld c,20
    call DelayFrames
    xor a ; szf
    ret
.HurtByPoisonText
    TX_FAR _HurtByPoisonText
    db "@"
.HurtByBurnText
    TX_FAR _HurtByBurnText
    db "@"
.HurtByLeechSeedText
    TX_FAR _HurtByLeechSeedText
    db "@"
.PlayMoveAnimation
    ld [$D07C],a
    call Delay3
    PREDEF_JUMP MoveAnimation
.WaitForTextScrollButtonPress
    push hl
    ld a,[H_WHOSETURN]
    and a
    push af
    PREDEF_Z DrawPlayerHUDAndHPBar
    pop af
    PREDEF_NZ DrawEnemyHUDAndHPBar
    ld a,$EE
    FuncCoord 18,16 ; $c4f2
    ld [Coord],a
    call WaitForTextScrollButtonPress
    pop hl
    ret
.IsFainted
    ld a,[hli]      ; Test If Fainted
    or [hl]         ; ...
    dec hl          ; ...
    ret

; decreases the mon's current HP by 1/16 of the Max HP (multiplied by number of toxic ticks if active)
; hl: HP pointer
PoisonBurnLeechSeed_DecreaseOwnHP:
    push hl
    push hl
    call HPDiv16
    ld hl,W_PLAYERBATTSTATUS3 ; $d064
    ld de,W_PLAYERTOXICCOUNTER ; $d06c
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.playersTurn
    ld hl,W_ENEMYBATTSTATUS3 ; $d069
    ld de,W_ENEMYTOXICCOUNTER ; $d071
.playersTurn
    ld a,[wUnusedC000]
    bit 6,a ; check if this is for leech seed
    jr z,.noToxic
    bit BADLY_POISONED,[hl]
    jr z,.noToxic
.Toxic
    ld a,[de]    ; increment toxic counter
    inc a
    ld [de],a
    ld hl,$0000
.toxicTicksLoop
    add hl,bc
    dec a
    jr nz,.toxicTicksLoop
    ld b,h       ; bc = damage * toxic counter
    ld c,l
.noToxic
    pop hl
    inc hl
    ld a,[hl]    ; subtract total damage from current HP
    ld [wHPBarOldHP],a
    sub c
    ld [hld],a
    ld [wHPBarNewHP],a
    ld a,[hl]
    ld [wHPBarOldHP+1],a
    sbc b
    ld [hl],a
    ld [wHPBarNewHP+1],a
    jr nc,.noOverkill
    xor a         ; overkill: zero HP
    ld [hli],a
    ld [hl],a
    ld [wHPBarNewHP],a
    ld [wHPBarNewHP+1],a
.noOverkill
    ld d,b
    ld e,c
    BANKSWITCH SetDamageDuringPoisonBurnLeechSeed
    pop hl
    ret

; adds HP/16 to enemy HP
LeechSeed_IncreaseEnemyHP:
    push hl
    call HPDiv16
    push bc
    ld hl,W_ENEMYMONMAXHP ; $cff4
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    jr z,.playersTurn
    ld hl,W_PLAYERMONMAXHP ; $d023
.playersTurn
    ld a,[hli]
    ld [wHPBarMaxHP+1],a
    ld a,[hl]
    ld [wHPBarMaxHP],a
    ld de,$fff2
    add hl,de           ; skip back fomr max hp to current hp
    ld a,[hl]
    ld [wHPBarOldHP],a ; add bc to current HP
    add c
    ld [hld],a
    ld [wHPBarNewHP],a
    ld a,[hl]
    ld [wHPBarOldHP+1],a
    adc b
    ld [hli],a
    ld [wHPBarNewHP+1],a
    ld a,[wHPBarMaxHP]
    ld c,a
    ld a,[hld]
    sub c
    ld a,[wHPBarMaxHP+1]
    ld b,a
    ld a,[hl]
    sbc b
    jr c,.noOverfullHeal
    ld a,b                ; overfull heal,set HP to max HP
    ld [hli],a
    ld [wHPBarNewHP+1],a
    ld a,c
    ld [hl],a
    ld [wHPBarNewHP],a
.noOverfullHeal
    ld a,[H_WHOSETURN] ; $FF00+$f3
    xor $1
    ld [H_WHOSETURN],a ; $FF00+$f3
    pop bc
    ld d,b
    ld e,c
    BANKSWITCH SetCureDuringLeechSeed
    ld a,[H_WHOSETURN] ; $FF00+$f3
    xor $1
    ld [H_WHOSETURN],a ; $FF00+$f3
    pop hl
    ret

HPDiv16:
    ld bc,$e ; skip to max HP
    add hl,bc
    ld a,[hli] ; load max HP
    ld [wHPBarMaxHP+1],a
    ld b,a
    ld a,[hl]
    ld [wHPBarMaxHP],a
    ld c,a
    srl b
    rr c
    srl b
    rr c
    srl c
    srl c ; c = max HP/16 (assumption: HP < 1024)
    ld a,c
    and a
    ret nz ; nonZeroDamage
    inc c ; damage is at least 1
    ret

_RockDamage:
    ld hl,W_ENEMYMONCURHP
    call PoisonBurnLeechSeed_DecreaseOwnHP ; ~TODO:HandleFaintened
    PREDEF_JUMP DrawEnemyHUDAndHPBar

_BaitHealth:
    ld hl,W_ENEMYMONCURHP
    call LeechSeed_IncreaseEnemyHP
    PREDEF_JUMP DrawEnemyHUDAndHPBar

