    ; PrintCurrentItem
    ld a,[wCurrentMenuItem]
    ld c,a
    ld a,[wListScrollOffset]
    add c
    inc a
    ld de,$d11e
    ld [de],a
    ld a,[W_ISINBATTLE]
    and a
    FuncCoord 14,03
    ld hl,Coord
    jr z,.done
    FuncCoord 14,08
    ld hl,Coord
.done
