_IsItemInBagOrBox:
    call Load16BitRegisters
    push bc
    call IsItemInBag2
    pop bc
    ret nz ; ret if item in bag
    push de
    push hl
    ld hl,wNumBoxItems
    jr SearchItemInList

_IsItemInBag:
    call Load16BitRegisters
IsItemInBag2:
    push de
    push hl
    ld hl,wNumBagItems
SearchItemInList:
    ld a,[hl]
    and a
    jr z,.NotFought
    ld d,a
.loop
    inc hl
    ld a,[hli]
    cp $FF
    jr z,.NotFought
    cp b
    jr z,.Fought
    dec d
    jr nz,.loop
.NotFought
    ld b,0
    jr .end
.Fought
    ld a,[hl]
    ld b,a
.end
    ld a,b
    and a
    pop hl
    pop de
    ret

; ──────────────────────────────────────────────────────────────────────

SECTION "bank36",ROMX,BANK[$36]

GetWildDataCurrentMap:
    call GetWildDataPointers ; ld hl,WildDataPointers
    ld a,[W_CURMAP]
    ; get wild data for current map
    ld c,a
    ld b,0
    add hl,bc
    add hl,bc
    ld a,[hli]
    ld h,[hl]
    ld l,a ; hl now points to wild data for current map
    ret

LoadWildData:
    call GetWildDataCurrentMap
    ld a,[hli]
    ld [W_GRASSRATE],a
    and a
    jr z,.NoGrassData ; if no grass data,skip to surfing data
    push hl
    ld de,W_GRASSMONS ; otherwise,load grass data
    ld bc,$0014
    call CopyData
    pop hl
    ld bc,$0014
    add hl,bc
.NoGrassData
    ld a,[hli]
    ld [W_WATERRATE],a
    and a
    ret z        ; if no water data,we're done
    ld de,W_WATERMONS  ; otherwise,load surfing data
    ld bc,$0014
    jp CopyData

