; creates a list at wBuffer of maps where the mon in [wd11e] can be found.
; this is used by the pokedex to display locations the mon can be found on the map.
FindWildLocationsOfMon:
    call GetWildDataPointers ; ld hl,WildDataPointers
    ld de,$cee9
    ld c,$0
.loop
    inc hl
    ld a,[hld]
    inc a
    jr z,.done
    push hl
    ld a,[hli]
    ld h,[hl]
    ld l,a
    call SearchWildMon
    pop hl
    inc hl
    inc hl
    inc c
    jr .loop
.done
    ld a,$ff ; list terminator
    ld [de],a
    ; Search Current Map to sort it first in list
    ld hl,$cee9
    ld d,h
    ld e,l
    ld a,[W_CURMAP]
    ld b,a
.LoopSort
    ld a,[hl]
    cp $ff ; list terminator
    ret z
    cp b
    jr nz,.NextSort
    ld a,[de]
    ld [hl],a
    ld a,b
    ld [de],a
    ret
.NextSort
    inc hl
    jr .LoopSort

; Input
; • hl point to Map "WildDataPointers"
; • de point to current "Map Slot"
; • c = current map id
; • [$d11e] = Mon ID
SearchWildMon:
    ld a,[hli]
    and a
    call nz,CheckMapForMon ; land
    ret c ; found
    ld a,[hli]
    and a
    call nz,CheckMapForMon ; water
    ret c ; found
    call GetSuperRodData ; ld hl,SuperRodData
    call FindFishingLocationsOfMon ; fishing super rod
    ret c ; found
    call GetGoodRodData ; ld hl,GoodRodData
    call FindFishingLocationsOfMon ; fishing good rod
    ret c ; found
    PREDEF CheckWildSubGroup
    ret ; carry set = found

; Input
; • hl pointer to "Catch" Ball in Pokedex
; • [$d11e] = Mon ID
IsMonInCurrentMap:
    call Load16BitRegisters
    ; Start
    push af
    push hl
    ; Backup
    ld de,$d11e
    ld a,[de]
    push de
    push af
    ; Code
    dec hl
    push hl
    BANKSWITCH PokedexToIndex
    call GetWildDataCurrentMap
    ld de,$d11e
    call SearchWildMon ; carry set = found
    ld a," "
    jr nc,.done
    ld a,$73 ; MonNestIcon
.done
    pop hl
    ld [hl],a
    ; Restore
    pop af
    pop de
    ld [de],a
    ; End
    pop hl
    pop af
    ret

FindFishingLocationsOfMon:
    push bc
    push de
    ld a,c
    ld de,3
    call IsInArray
    pop de
    pop bc
    push bc
    call c,CheckFishingForMon
    pop bc
    ret

CheckMapForMon:
    inc hl
    ld b,10
.loop
    push bc
    ld a,[$d11e]
    ld b,a
    ld a,[hl]
    cp $FF
    call z,SearchSpecialFF
    cp b
    jr nz,.nextEntry
    ld a,c
    ld [de],a
    inc de
    scf
    pop bc
    ret
.nextEntry
    inc hl
    inc hl
    pop bc
    dec b
    jr nz,.loop
    dec hl
    and a ; Reset Carry Flag
    ret

CheckFishingForMon:
    ; hl points to the fishing group entry in the index
    inc hl ; skip map id
    ld a,[hli] ; read fishing group address
    ld h,[hl]
    ld l,a
    ld b,[hl] ; how many mons in group
    inc hl
    inc hl ; point to data
.Loop
    ld a,[$d11e]
    cp [hl]
    jr nz,.nextEntry
    ld a,c
    ld [de],a
    inc de
    scf
    ret
.nextEntry
    inc hl
    inc hl
    dec b
    jr nz,.Loop
    and a ; Reset Carry Flag
    ret

