; ───────────────────────────────────────
; Handle New Adventure Pointer Conversion (BANK $36)
; ───────────────────────────────────────

GetWildDataPointers:
    ld hl,WildDataPointers
    call CheckNewAdventureFlag
    ret z
    ld hl,WildDataPointersNew
    ret

GetGoodRodData:
    ld hl,GoodRodData
    call CheckNewAdventureFlag
    ret z
    ld hl,GoodRodDataNew
    ret

GetSuperRodData:
    ld hl,SuperRodData
    call CheckNewAdventureFlag
    ret z
    ld hl,SuperRodDataNew
    ret

; ──────────────────────────────────────────────────────────────────────

; Input
; e = Encounter Slot
WildSubGroup:
    call GetCurrentOldAdventureMap
    ld b,a
    call GetWildSubGroupTable
.loop
    ld a,[hli]
    cp $FF
    jr z,.NotEncounter
    cp b
    jr nz,.next1
    FuncCoord 9,9 ; Tile Near Player
    ld a,[Coord]  ; ...
    bit 7,[hl]
    jr z,.CheckLand
.CheckWatr
    cp $14
    jr nz,.next1
    jr .done
.CheckLand
    cp $14
    jr z,.next1
.done
    ld a,[hli]
    and %01111111 ; ignore bit land/watr
    cp e
    jr nz,.next2
.found
    ld a,[hli]
    ld h,[hl]
    ld l,a
    call GenRandom
    ld c,a
.loop2
    ld a,[hli]
    cp c
    jr nc,.MonIdentified
    inc hl
    inc hl
    jr .loop2
.next1
    inc hl
.next2
    inc hl
    inc hl
    jr .loop
.MonIdentified
    ld a,[hli]
    ld [W_CURENEMYLVL],a
    ld a,[hl]
    ld [W_ENEMYMONID],a
    cp $FF
    BANKSWITCH_NZ GetWildEnemyLevel
    scf ; WillEncounter
    ret
.NotEncounter
    and a ; Reset Carry Flag ; NotEncounter
    ret

WildUnknownDungeon:
    call GenRandom
    ld e,a
    dec d ; Exception ID (1 or 2)
    ld hl,UnknownDungeonLandPkmnList
    jr z,.Done
    ld hl,UnknownDungeonWaterPkmnList
    srl e
.Done
    ld d,0
    add hl,de
    ld a,[hl]
    ld [W_ENEMYMONID],a
    ld [$d11e],a
    call IndexToPokedexAndRestoreD11E
    ld hl,UnknownDungeonPkmnMinLevel
    ld e,a
    ld d,0
    add hl,de
    ld a,[hl]
    ld d,a
    call GenRandom
    ld a,[H_RAND2]
    and a,%00001111 ; 0-15
    add d
    ld [W_CURENEMYLVL],a
    scf ; WillEncounter
    ret

WildDockMew:
    ld hl,$d728 ; Strength
    bit 0,[hl]
    jr z,.NotEncounter
    ld hl,wEventEncounterMewBit7
    bit 7,[hl]
    set 7,[hl]
    jr nz,.NotEncounter
.MewFirstEncounter
    ld a,70
    ld [W_CURENEMYLVL],a
    ld a,MEW ; Entry Point
    ld [W_ENEMYMONID],a
    scf ; WillEncounter
    ret
.NotEncounter
    and a ; Reset Carry Flag ; NotEncounter
    ret

WildPikachu:
    call WildPikachuConditions
    ret nc ; NotEncounter
    ld a,2 ; RedsHouse2FScript2_AfterPikachu
    ld [W_REDSHOUSE2CURSCRIPT],a
    ld a,PIKACHU ; Entry Point
    ld [W_ENEMYMONID],a
    ld a,1
    ld [W_CURENEMYLVL],a
    scf ; WillEncounter
    ret

WildPikachuConditions:
    ld a,[W_NUMINPARTY]
    and a
    jr z,.NotEncounter
    ld hl,wDisableEncounterBit1
    bit 1,[hl]
    jr nz,.NotEncounter
    call .Own
    jr nz,.NotEncounter
    scf ; WillEncounter
    ret
.NotEncounter
    and a ; Reset Carry Flag ; NotEncounter
    ret
.Own
    push hl
    push bc
    ld hl,wPokedexOwned
    ld bc,(2 << 8) + DEX_PIKACHU ; 2 = read bit
    PREDEF HandleBitArray
    ld a,c
    and a
    pop bc
    pop hl
    ret

WildEevee:
    call WildEeveeConditions
    ret nc ; NotEncounter
    ld a,1 ; MuseumF2Script1_AfterEevee
    ld [W_MUSEUM2FCURSCRIPT],a
    ld a,EEVEE ; Entry Point
    ld [W_ENEMYMONID],a
    ld a,1
    ld [W_CURENEMYLVL],a
    scf ; WillEncounter
    ret

WildEeveeConditions:
    ld a,[W_NUMINPARTY]
    and a
    jr z,.NotEncounter
    ld hl,wDisableEncounterBit3
    bit 3,[hl]
    jr nz,.NotEncounter
    call .Own
    jr nz,.NotEncounter
    scf ; WillEncounter
    ret
.NotEncounter
    and a ; Reset Carry Flag ; NotEncounter
    ret
.Own
    push hl
    push bc
    ld hl,wPokedexOwned
    ld bc,(2 << 8) + DEX_EEVEE ; 2 = read bit
    PREDEF HandleBitArray
    ld a,c
    and a
    pop bc
    pop hl
    ret

GetLegendaryLevel:
    ld hl,.WildLegendaryLevelTable
    call GenRandom
    ld c,a
.loop
    ld a,[hli]
    cp c
    jr nc,.found
    inc hl
    jr .loop
.found
    ld a,[hl]
    ret
.WildLegendaryLevelTable
    db $32,15 ; 20%
    db $65,20 ; 20%
    db $8C,25 ; 15%
    db $A5,30 ; 10%
    db $BE,35 ; 10%
    db $D7,10 ; 10%
    db $E4,40 ;  5%
    db $F1,45 ;  5%
    db $FC,50 ;  4%
    db $FF,55 ;  1%

WildArticuno:
    call WildArticunoConditions
    ret nc ; NotEncounter
    ld a,ARTICUNO
    ld [W_ENEMYMONID],a
    call GetLegendaryLevel
    ld [W_CURENEMYLVL],a
    scf ; WillEncounter
    ret

