WildSubGroupTableNew:
    db $FF

GetWildSubGroupTable:
    ld hl,WildSubGroupTable
    call CheckNewAdventureFlag
    ret z
    ld hl,WildSubGroupTableNew
    ret

; Input
; c = Town ID
; [d11e] = Mon ID
; de = Pointer to Current Search Map Slot
CheckWildSubGroup:
    call Load16BitRegisters
    call GetWildSubGroupTable
.loop
    ld a,[hli]
    cp $FF
    jr z,.NotFound
    cp c
    jr nz,.next1
    inc hl
    push hl
    ld a,[hli]
    ld h,[hl]
    ld l,a
.loop2
    ld a,[hli]
    cp $FF
    jr z,.LastRow
    call .CompareMon
    jr nz,.loop2
    jr .Found
.LastRow
    call .CompareMon
    jr nz,.NextEntry
    jr .Found
.NextEntry
    pop hl
    jr .next2
.next1
    inc hl
.next2
    inc hl
    inc hl
    jr .loop
.NotFound
    and a ; Reset Carry Flag
    ret
.CompareMon
    inc hl
    ld a,[$d11e]
    ld b,a
    ld a,[hl]
    cp $FF
    call z,SearchSpecialFF
    cp b
    inc hl
    ret
.Found
    pop hl
    ld a,c
    ld [de],a
    inc de
    scf
    ret

; ──────────────────────────────────────────────────────────────────────

SearchSpecialFF:
    push hl
    push bc
    dec hl
    ld a,[hl]
    ld b,a
    ld hl,.TableExceptionFF
.Loop
    ld a,[hli]
    cp $FF
    jr z,.NotFound
    cp b
    jr z,.Found
    inc hl
    inc hl
    jr .Loop
.Found
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ld bc,.End
    push bc
    jp hl
.NotFound
    ld a,$FF
.End
    pop bc
    pop hl
    ret

.TableExceptionFF
    dbw W_PIKACHU,.Pikachu
    dbw W_EEVEE,.Eevee
    dbw W_ARTICUNO,.Articuno
    dbw W_ZAPDOS,.Zapdos
    dbw W_MOLTRES,.Moltres
    db $FF

.Pikachu
    call WildPikachuConditions
    ld a,$FF
    ret nc ; NotEncounter
    ld a,PIKACHU
    ret

.Eevee
    call WildEeveeConditions
    ld a,$FF
    ret nc ; NotEncounter
    ld a,EEVEE
    ret

.Articuno
    call WildArticunoConditions
    ld a,$FF
    ret nc ; NotEncounter
    ld a,ARTICUNO
    ret

.Zapdos
    call WildZapdosConditions
    ld a,$FF
    ret nc ; NotEncounter
    ld a,ZAPDOS
    ret

.Moltres
    call WildMoltresConditions
    ld a,$FF
    ret nc ; NotEncounter
    ld a,MOLTRES
    ret

