    db 1,3,4,0    ; GIOVANNI
    db 1,4,0      ; ROCKET
    db 1,3,4,0    ; COOLTRAINER_M
    db 1,3,4,0    ; COOLTRAINER_F
    db 1,3,4,0    ; BRUNO
    db 1,3,4,0    ; BROCK
    db 1,3,4,0    ; MISTY
    db 1,2,3,0    ; LT_SURGE
    db 1,3,4,0    ; ERIKA
    db 1,2,3,4,0  ; KOGA
    db 1,3,4,0    ; BLAINE
    db 1,2,3,4,0  ; SABRINA
    db 1,2,3,4,0  ; GENTLEMAN
    db 1,3,4,0    ; SONY2
    db 1,3,4,0    ; SONY3
    db 1,2,3,4,0  ; LORELEI
    db 1,2,3,4,0  ; CHANNELER
    db 1,2,3,4,0  ; AGATHA
    db 1,3,4,0    ; LANCE

WildAI:
    db ABRA
    db KADABRA
    db ALAKAZAM
    db MACHAMP
    db GOLEM
    db GENGAR
    db AERODACTYL
    db SNORLAX
    db ARTICUNO
    db ZAPDOS
    db MOLTRES
    db DRAGONITE
    db MEWTWO
    db MEW
    db $FF

; creates a set of moves that may be used and returns its address in hl
; unused slots are filled with 0,all used slots may be chosen with equal probability
AIEnemyTrainerChooseMoves:
    ld a,$a
    ld bc,4
    ld hl,wBackupAIMoveChoice
    call FillMemory
    ld a,[W_ISINBATTLE]
    dec a
    jr nz,.notwildbattle
    ;wild battle confirmed at this point
    ld a,[W_ENEMYMONID]
    ld hl,WildAI
    ld de,$0001
    call IsInArray
    ld hl,W_ENEMYMONMOVES ;restore this address which was clobbered by Bankswitch
    ret nc
    ;load the Sailor class since it only uses AI routines 1 and 3
    ld a,SAILOR
    ld [W_TRAINERCLASS],a
    ;should be fine to let AIEnemyTrainerChooseMoves run at this point
.notwildbattle
    call GetCurrentOldAdventureMap
    ld hl,.VictoryRoadMapList
    ld de,1
    call IsInArray
    jr nc,.NotVictoryRoad
    ld a,BRUNO
    ld [W_TRAINERCLASS],a
.NotVictoryRoad
    ld a,$a
    ld hl,$cee9  ; init temporary move selection array. Only the moves with the lowest numbers are chosen in the end
    ld [hli],a   ; move 1
    ld [hli],a   ; move 2
    ld [hli],a   ; move 3
    ld [hl],a    ; move 4
    ld a,[$ccd5]
    and a
    jr z,.FirstActiveEnemyPokemonTurn
    ld a,[W_ENEMYMOVEPOWER] ;joenote - backup the power of the last moved used
    jr .done
.FirstActiveEnemyPokemonTurn
    inc a ; a = 1
.done
    ld [wAILastMovePower],a

; PP ► ENERGY - DONE
    ; highly discourage not enough energy move
    ld a,[wCurrentMenuItem] ; Backup Current Menu Item
    push af                 ; ...
    ld hl,W_ENEMYMONMOVES
    ld d,h
    ld e,l
    ld bc,$00FF ; b = 0 | c = -1
.searchNext
    inc c
    ld a,c
    cp 4
    jr z,.ppdone
    ld [wCurrentMenuItem],a
    ld a,[hli]
    and a
    jr z,.searchNext
    push hl
    push bc
    BANKSWITCH CheckEnoughEnergy
    pop bc
    pop hl
    jr nc,.searchNext
    push hl
    ld hl,$cee9
    add hl,bc    ; advance pointer to zero pp move
    ld [hl],$50  ; forbid (highly discourage) zero pp move
    pop hl
    jr .searchNext
.ppdone
    pop af                  ; Restore Current Menu Item
    ld [wCurrentMenuItem],a ; ...

    ld a,[W_ENEMYDISABLEDMOVE] ; forbid disabled move (if any)
    swap a
    and $f
    jr z,.noMoveDisabled
    ld hl,$cee9
    dec a
    ld c,a
    ld b,$0
    add hl,bc    ; advance pointer to forbidden move
    ld [hl],$50  ; forbid (highly discourage) disabled move
.noMoveDisabled
    ld hl,TrainerClassMoveChoiceModifications ; 589B
    ld a,[W_TRAINERCLASS]
    ld b,a
.loopTrainerClasses
    dec b
    jr z,.readTrainerClassData
.loopTrainerClassData
    ld a,[hli]
    and a
    jr nz,.loopTrainerClassData
    jr .loopTrainerClasses
.readTrainerClassData
    ld a,[hl]
    and a
    jp z,.useOriginalMoveSet
    push hl
.nextMoveChoiceModification
    pop hl
    ld a,[hli]
    and a
    jr z,.BackupChoice
    push hl
    ld hl,AIMoveChoiceModificationFunctionPointers ; $57a3
    dec a
    add a
    ld c,a
    ld b,$0
    add hl,bc    ; skip to pointer
    ld a,[hli]   ; read pointer into hl
    ld h,[hl]
    ld l,a
    ld de,.nextMoveChoiceModification  ; set return address
    push de
    jp hl       ; execute modification function
.BackupChoice
    ld hl,$cee9
    ld de,wBackupAIMoveChoice
    ld bc,4
    call CopyData
.loopFindMinimumEntries ; all entries will be decremented sequentially until one of them is zero
    ld hl,$cee9  ; temp move selection array
    ld de,W_ENEMYMONMOVES  ; enemy moves
    ld c,$4
.loopDecrementEntries
    ld a,[de]
    inc de
    and a
    jr z,.loopFindMinimumEntries
    dec [hl]
    jr z,.minimumEntriesFound
    inc hl
    dec c
    jr z,.loopFindMinimumEntries
    jr .loopDecrementEntries
.minimumEntriesFound
    ld a,c
.loopUndoPartialIteration ; undo last (partial) loop iteration
    inc [hl]
    dec hl
    inc a
    cp $5
    jr nz,.loopUndoPartialIteration
    ld hl,$cee9  ; temp move selection array
    ld de,W_ENEMYMONMOVES  ; enemy moves
    ld c,$4
.filterMinimalEntries ; all minimal entries now have value 1. All other slots will be disabled (move set to 0)
    ld a,[de]
    and a
    jr nz,.moveExisting ; 0x3978a $1
    ld [hl],a
.moveExisting
    ld a,[hl]
    dec a
    jr z,.slotWithMinimalValue
    xor a
    ld [hli],a     ; disable move slot
    jr .next
.slotWithMinimalValue
    ld a,[de]
    ld [hli],a     ; enable move slot
.next
    inc de
    dec c
    jr nz,.filterMinimalEntries
    ld hl,$cee9    ; use created temporary array as move set
    ret
.useOriginalMoveSet
    ld hl,W_ENEMYMONMOVES    ; use original move set
    ret
.VictoryRoadMapList
    db VICTORY_ROAD_1
    db VICTORY_ROAD_2
    db VICTORY_ROAD_3
    db $FF

AIMoveChoiceModificationFunctionPointers:
    dw AIMoveChoiceModification1
    dw AIMoveChoiceModification2
    dw AIMoveChoiceModification3
    dw AIMoveChoiceModification4

INCLUDE "shin/Shin_AIMoveChoiceModification.asm"

ReadMove:
    push hl
    push de
    push bc
    dec a
    ld hl,Moves
    ld bc,6
    call AddNTimes
    ld a,[wBuffer] ; Backup First Byte Because used By FarCopyData
    push af
    ld de,$CFCC
    ld a,BANK(Moves)
    call FarCopyData
    pop af
    ld [wBuffer],a ; Restore First Byte Because used By FarCopyData
    pop bc
    pop de
    pop hl
    ret

ModulateExpForMonsThatFought: ; 4/5 TOTAL (80%)
    push bc
    ld hl,$d002
    ld c,$7
.NextStat
    xor a
    ld [H_MULTIPLICAND],a
    ld [H_MULTIPLICAND+1],a
    ld a,[hl]
    ld [H_MULTIPLICAND+2],a
    ld a,4 ; Multiply 4
    ld [H_MULTIPLIER],a
    call Multiply
    ld a,5 ; Divide 5
    ld [H_DIVISOR],a
    ld b,4 ; 4 bytes
    call Divide
    ld a,[$FF00+$98]
    inc a ; Add 1 Point to Limit Approx Error
    ld [hli],a
    dec c
    jr nz,.NextStat
    pop bc
    ret

ModulateExpForMonsThatNotFought: ; 4/5 : 4 = 1/5 TOTAL (20%)
    push bc
    call UndoDivisionExp
    ld hl,$d002
    ld c,$7
.NextStat
    xor a
    ld [H_DIVIDEND],a
    ld a,[hl]
    ld [H_DIVIDEND+1],a
    ld a,4 ; Divide 4
    ld [H_DIVISOR],a
    ld b,2 ; 2 bytes
    call Divide
    ld a,[$FF00+$98]
    inc a ; Add 1 Point to Limit Approx Error
    ld [hli],a
    dec c
    jr nz,.NextStat
    pop bc
    jp DefineMonsThatNotFoughtFlag

UndoDivisionExp:
    ld hl,$d002
    ld b,$7
.exp_stat_loop
    call GetNumOfFought
    ld c,a              ; get number of participating pkmn into c
    xor a               ; clear a to zero
.exp_adder_loop
    add [hl]            ; add the value of the current exp stat to 'a'
    dec c               ; decrement participating pkmn
    jr nz, .exp_adder_loop
    ld [hl],a           ; stick the exp values, now multiplied by the number of participating pkmn, back into the stat address
    inc hl              ; get next stat
    dec b
    jr nz, .exp_stat_loop
    ret

GetNumOfFought:
    push bc
    push de
    ld a,[wBackupFlagGainingExp]
    ld b,a
    xor a
    ld c,$8
    ld d,$0
.Next
    xor a
    srl b
    adc d
    ld d,a
    dec c
    jr nz,.Next
    pop de
    pop bc
    ret

DefineMonsThatNotFoughtFlag:
    call DefineMonLiveFlag ; ► d = flag mon live
    call DefinePartyFlag   ; ► e = party
    ld a,[wBackupFlagGainingExp]   ; ► a = flag has just gain experience
    xor e ; If a mon has just gain experience xor turn into 0
    and d ; If a mon is faintened turn into 0
    ld hl,wNoExpToLastPartyMonBit1
    bit 1,[hl]
    jr z,.Skip
    ld hl,W_NUMINPARTY
    ld b,[hl]
    ld c,b ; Backup b
    call .loop1
    res 7,a ; remove last caught party mon
    ld b,c ; Restore b
    call .loop2
.Skip
    ld [W_PLAYERMONSALIVEFLAGS],a
    ret
.loop1
    rrc a
    dec b
    jr nz,.loop1
    ret
.loop2
    rlc a
    dec b
    jr nz,.loop2
    ret

DefineMonLiveFlag:
    ld a,8
    ld d,0
    ld e,a
    ld hl,W_PARTYMON1_HP ; $d16c
    ld bc,W_PARTYMON2DATA - W_PARTYMON1DATA - 1
.partyMonsLoop8Byte
    xor a
    or [hl]
    inc hl
    or [hl] ; reset carry flag
    jr z,.Fainted
    scf ; set carry flag
.Fainted
    rr d
    add hl,bc
    dec e
    jr nz,.partyMonsLoop8Byte
    ld a,d
    and %00111111 ; Reset fist 2 Byte because only 6 mons
    ld d,a
    ret

DefinePartyFlag:
    ld a,[W_NUMINPARTY] ; $d163
    ld e,0
.LoopParty1
    scf
    rl e
    dec a
    jr nz,.LoopParty1
    ret

