WaitButtonPressed_:
    call GetJoypadStateLowSensitivity
    ld a,[$ffb5]
    and a ; was a key pressed?
    jr z,WaitButtonPressed_
    ret

; copies HP bar and status display tile patterns into VRAM
LoadHpBarAndStatusTilePatterns_:
    ld de,HpBarAndStatusGraphics
    ld hl,$9620
    ld bc,(BANK(HpBarAndStatusGraphics) << 8 | $1e)
    jp GoodCopyVideoData

; INPUT
; d = High Bit Return Pointer
; e = Low Bit Return Pointer
_HackFromBank0:
    ld hl,.Table
.Loop
    ld a,[hli]
    cp $ff
    ret z
    cp d
    jr z,.Found1
    inc hl
.Next2
    inc hl
    inc hl
    jr .Loop
.Found1
    ld a,[hli]
    cp e
    jr nz,.Next2
.Found2
    ld a,[hli]
    ld h,[hl]
    ld l,a
    jp hl
.Table
    dw $3043
    dw _OverworldHackRoutine
    dw $3047
    dw _RestoreFaintenedWith1HP
    dw $304b
    dw _BugFixWarpDuringJump
    db $ff

_OverworldHackRoutine:
    call BackupDarkMapState
    call HandleLightAnimation
    call HandleStrengthAnimation
    call HandleGoToDark
    ; ft

BugFixLongRangeTrainer:
    ld hl,W_FLAGS_D733 ; check if trainer is wanting to battle
    bit 3,[hl]
    ld hl,$d732
    jr z,.End
    res 3,[hl] ; cancel fly/teleport warp
.End
    ld d,[hl] ; Output d -> a
    ret

_RestoreFaintenedWith1HP:
    ld hl,W_PARTYMON1_HP ; $d173
    ld a,[W_NUMINPARTY]
    ld e,a
    ld a,[wExplodeFlag]
    ld d,a
.Loop
    srl d
    jr c,.Next
    ld a,[hli]
    ld b,a
    ld a,[hld]
    or b
    jr nz,.Next
    push hl
    ld bc,W_PARTYMON1_MOVE1PP-W_PARTYMON1_HP
    add hl,bc
    ld a,[hl] ; Read stored Energy
    cp 60 ; Check If Old stored Energy is at least 60
    jr c,.NoEnergy
    push af
    srl [hl] ; Halve stored Energy
    pop af
.NoEnergy
    pop hl
    jr c,.Next
    inc hl
    inc [hl] ; 1 HP
    dec hl ; Restore Pointer to PARTYMON_HP
.Next
    ld bc,$2c
    add hl,bc
    dec e
    jr nz,.Loop
    xor a
    ld [wExplodeFlag],a
    ret

BackupDarkMapState:
    ld a,[$d35d]
    ld [wBackupDarkMap],a
    ret

HandleLightAnimation:
    ld hl,wOverworlLightAnimBit0
    bit 0,[hl]
    res 0,[hl]
    ret z
    xor a
    ld [$d35d],a
    call LoadGBPal
    ld hl,wOverworlLightSoundBit4
    bit 4,[hl]
    res 4,[hl]
    jr z,.SkipSound
    ld a,MAGNEMITE
    call GetCryData
    call PlaySound
.SkipSound
    ld b,5
    call .FlashScreenBTimes
    ld c,20
    call DelayFrames
    ld hl,wOverworlNoTextBit2
    bit 2,[hl]
    res 2,[hl]
    ret nz
    call EnableAutoTextBoxDrawing
    ld a,$fe ; .FlashLightText
    ld [H_DOWNARROWBLINKCNT2],a ; $FF00+$8c
    jp DisplayTextID
.FlashScreenBTimes
    call .FlashScreen
    dec b
    jr nz,.FlashScreenBTimes
    ret
.FlashScreen
    ld a,[rBGP]
    push af ; save initial palette
    ld a,%00011011 ; 0,1,2,3 (inverted colors)
    ld [rBGP],a
    ld c,2
    call DelayFrames
    xor a ; white out background
    ld [rBGP],a
    ld c,2
    call DelayFrames
    pop af
    ld [rBGP],a ; restore initial palette
    ret

HandleStrengthAnimation:
    ld hl,wOverworlStrengthAnimBit1
    bit 1,[hl]
    res 1,[hl]
    ret z
    call .Animation
    ld c,20
    call DelayFrames
    ld hl,wOverworlNoTextBit2
    bit 2,[hl]
    res 2,[hl]
    ret nz
    call EnableAutoTextBoxDrawing
    ld a,$fd ; .StrengthText
    ld [H_DOWNARROWBLINKCNT2],a ; $FF00+$8c
    jp DisplayTextID
.Animation
    ld b,5
.loop
    push bc
    ld a,-01
    call .SlideScreen
    ld a,+01
    call .SlideScreen
    ld a,+01
    call .SlideScreen
    ld a,-01
    call .SlideScreen
    pop bc
    dec b
    jr nz,.loop
    xor a
    ld [$c105],a ; delta X
    ld [wWalkCounter],a
    ret
.SlideScreen
    ld [$c105],a ; delta X
    ld a,8
    ld [wWalkCounter],a
    call AdvancePlayerSprite
    call AdvancePlayerSprite
    jp DelayFrame

HandleGoToDark:
    ld hl,wOverworldGoToDarkBit4
    bit 4,[hl]
    ret z
    call CheckDarkMap
    ld hl,wOverworldGoToDarkBit4
    res 4,[hl]
    ret

_BugFixWarpDuringJump:
    ld hl,_BugFixWarpDuringJump
    push hl ; Set Return Pointer
    call DelayFrame
    call DelayFrame
    call LoadGBPal
    ld a,[$d736]
    bit 6,a ; jumping down a ledge?
    jp nz,HandleMidJump
    pop hl ; Delete Useless Return Pointer
    ; Handle original code
    ld a,[$d3ae] ; number of warps
    ld d,a
    ret

