ForceShinyOrRandom_:
    ld a,[W_SAFARIZONECURSCRIPT]
    cp 1 ; Safari's Lapras
    jp z,.Lapras
    ld a,[W_VICTORYROAD2CURSCRIPT]
    cp 3 ; Shiny Onix
    jp z,.Onix
    call CheckNewAdventureFlag
    jr nz,.NewAdventure
    ld a,[W_CURMAP]
    cp DRATINI_CAVE
    jr z,.ShinyRandom
    cp SAFARI_ZONE_WEST
    jp z,.Safari
    cp POKEMONTOWER_6
    jp z,.Tower6
    cp REDS_HOUSE_2F
    jp z,.PalletTown
    cp MUSEUM_2F
    jp z,.PewterCity
    ; ft
.Random
    call .GenRandomInBattle
    jr .End
.NewAdventure
    jr .Random
.ShinyRandom
    call .GenRandomInBattle
.ShinyCommon
    or %00100000
    and $F0
    add $A
    ld e,$AA
.End
    ld d,a
    ret
.GenRandomInBattle
    BANKSWITCH GenRandomInBattleFromOtherBANK
    ld a,d
    ret

.PalletTown
    ld a,[$cf91]
    cp PIKACHU
    jr nz,.Random
    ld a,[wPalletPikachuIV_AtkDef]
    and a
    jr nz,.GetPikachuStoredIV
    ld a,e
    or $88 ; Speed > 7 ; Special > 7
    ld e,a
    ld [wPalletPikachuIV_SpdSpc],a
    call .GenRandomInBattle
    or $18 ; Attack ODD ; Defense > 7 ; HP > 7
    ld [wPalletPikachuIV_AtkDef],a
    jr .End
.GetPikachuStoredIV
    ld a,[wPalletPikachuIV_SpdSpc]
    ld e,a
    ld a,[wPalletPikachuIV_AtkDef]
    jr .End

.PewterCity
    ld a,[$cf91]
    cp EEVEE
    jr nz,.Random
    ld a,[wPewterEeveeIV_AtkDef]
    and a
    jr nz,.GetEeveeStoredIV
    ld a,e
    or $88 ; Speed > 7 ; Special > 7
    ld e,a
    ld [wPewterEeveeIV_SpdSpc],a
    call .GenRandomInBattle
    or $18 ; Attack ODD ; Defense > 7 ; HP > 7
    ld [wPewterEeveeIV_AtkDef],a
    jr .End
.GetEeveeStoredIV
    ld a,[wPewterEeveeIV_SpdSpc]
    ld e,a
    ld a,[wPewterEeveeIV_AtkDef]
    jr .End

.Lapras
    call .GenRandomInBattle
    or $81 ; Attack > 7 ; Defense ODD (NO Shiny)
    jr .End

.Onix
    call .GenRandomInBattle
    or $80 ; Attack > 7
    jr .ShinyCommon

.Tower6
    ld a,[$cf91]
    cp MAROWAK
    jp nz,.Random
    call .GenRandomInBattle
    and $7F ; Attack < 8
    jr .End

.Safari
    ld a,[W_CUROPPONENT] ; $d059
    cp MAGIKARP
    jp nz,.Random
    ld a,[W_CURENEMYLVL]
    cp 26 ; Shiny If Level 26 in SAFARI_ZONE_WEST
    jp nz,.Random
    jp .ShinyRandom

