SetExplodeFlag_:
    xor a ; Reset Carry Flag
    ld a,[wPlayerMonNumber]
    ld e,%00000001 ; 1 bit to rotate
.Loop
    and a
    jr z,.EndLoop
    rl e
    dec a
    jr .Loop
.EndLoop
    ld a,[wExplodeFlag]
    or e
    ld [wExplodeFlag],a
    ret

SetExplodeFlagBecauseStatusAfterFainted_:
    ld a,[W_PLAYERMONSTATUS]
    and PSN | BRN | FRZ | PAR | SLP
    call nz,SetExplodeFlag_
    ;xor a ; Don't Remove STATUS when faintened
    ;ld [W_PLAYERMONSTATUS],a ; $d018
    ret

InitExplodeFlag:
    ld hl,W_PARTYMON1_HP ; $d173
    ld a,8;[W_NUMINPARTY]
    ld e,a
    ld d,0
.Loop
    ld a,[hli]
    ld b,a
    ld a,[hld]
    or b
    jr nz,.Zero
    scf
    jr .One
.Zero
    xor a ; Reset Carry Flag
.One
    rr d ; Set 1 to all Faintened (EXPLOSION)
    ld bc,$2c
    add hl,bc
    dec e
    jr nz,.Loop
    ld a,d
    and %00111111 ; Only 6 Pkmn
    ld [wExplodeFlag],a
    ret

; Set Carry Flag if Focus in Bag or All Pkmn Fought
IsFocusInBagOrAllFought_:
    ld b,FOCUS
    call IsItemInBag ; set z if item isn't in player's bag
    jr nz,.focus
    call CheckIfAllFought ; set z if all Pkmn Fought
    jr z,.focus
    xor a ; Reset Carry Flag
    ret
.focus
    scf ; Set Carry Flag
    ret

CheckIfAllFought:
    call DefineMonLiveFlag        ; ► d = flag mon live
    call DefinePartyFlag          ; ► e = party
    ld a,d
    and e
    ld d,a
    ld a,[W_PLAYERMONSALIVEFLAGS] ; ► a = flag has fought
    cp d
    ret

