InitializeChooseQuantityMenu:
    ld hl,wWaitReleaseJoyBit5
    set 5,[hl]
; text box dimensions/coordinates for just quantity
    FuncCoord 14,09
    ld hl,Coord
    ld b,01 ; height
    ld c,04 ; width
    ld a,[wListMenuID]
    cp PRICEDITEMLISTMENU
    jr nz,.drawTextBox
; text box dimensions/coordinates for quantity and price
    FuncCoord 06,09
    ld hl,Coord
    ld a,[$ff8e]
    and a ; should the price be halved (for selling items)?
    ld b,01  ; height
    jr nz,.SellOnly1Row
    ld a,[$cf91] ; selected item ID
    cp TM_01
    jr nc,.SellOnly1Row
    ld b,03  ; height
.SellOnly1Row
    ld c,12 ; width
.drawTextBox
    call TextBoxBorder
    FuncCoord 15,10
    ld hl,Coord
    ld a,[wListMenuID]
    cp PRICEDITEMLISTMENU
    jr nz,.printInitialQuantity
    ld a,[$ff8e]
    and a ; should the price be halved (for selling items)?
    jr nz,.SkipShowBagInfo
    ld a,[$cf91] ; selected item ID
    cp TM_01
    call c,.PrintBagInfo
.SkipShowBagInfo
    ld a,[$cf91] ; selected item ID
    sub TM_01
    call nc,.PrintMoveDetails
    FuncCoord 07,10
    ld hl,Coord
.printInitialQuantity
    ld de,.InitialQuantityText
    call PlaceString
    xor a
    ld [$cf96],a ; initialize current quantity to 0 (then increase)
    ret
.InitialQuantityText
    db "×001@"

.PrintMoveDetails
    inc a
    ld [$d11e],a
    PREDEF TMToMove
    ld a,[$d11e]
    ld [wPlayerSelectedMove],a
    FuncCoord 10,12
    ld de,Coord
    ld hl,wHyperBeamUnknownTypeBit4
    set 4,[hl]
    PREDEF_JUMP PrintMoveDetailsBox

.PrintBagInfo
    ld b,a
    ld hl,0
    ld de,wNumBagItems
    ld a,[de]
    and a
    jr z,.BagItemCountDone
    inc de
    ld c,a
.BagItemCountLoop
    ld a,[de]
    cp $FF
    jr z,.BagItemCountDone
    inc de
    cp b
    jr nz,.BagItemCountSkip
    ld a,[de]
    push bc
    ld b,0
    ld c,a
    add hl,bc ; add found item qty to hl
    pop bc
.BagItemCountSkip
    inc de
    dec c
    jr nz,.BagItemCountLoop
.BagItemCountDone
    ld a,h
    ld [wBufferPointerByte1],a
    ld a,l
    ld [wBufferPointerByte2],a
    FuncCoord 15,12
    ld hl,Coord
    ld de,wBufferPointerByte1 ; quantity
    ld bc,((%10000000|02)<<8|04) ; print leading zeroes,2 byte,4 digits
    call PrintNumber
    FuncCoord 10,12
    ld hl,Coord
    ld de,.PackText
    jp PlaceString
.PackText
    db "BAG ×@"

