HalvePrice:
    ld a,2
    ld [$ff8e],a ; halve unit prices when selling
    ld a,[$ff8b]
    ld [$ff9f],a
    ld a,[$ff8c]
    ld [$ffa0],a
    ld a,[$ff8d]
    ld [$ffa1],a
    xor a
    ld [$ffa2],a
    ld [$ffa3],a
    ld a,$02
    ld [$ffa4],a
    PREDEF Func_f71e ; halves the unit price
; store the halved unit price
    ld a,[$ffa2]
    ld [$ff8b],a
    ld a,[$ffa3]
    ld [$ff8c],a
    ld a,[$ffa4]
    ld [$ff8d],a
    ret

PrintPrice:
    ld c,$03
    ld a,[$cf96]
    ld b,a
    ld hl,$ff9f ; total price
; initialize total price to 0
    xor a
    ld [hli],a
    ld [hli],a
    ld [hl],a
.addLoop ; loop to multiply the individual price by the quantity to get the total price
    ld de,$ffa1
    ld hl,$ff8d
    push bc
    PREDEF Func_f81d ; add the individual price to the current sum
    pop bc
    dec b
    jr nz,.addLoop
    FuncCoord 12,10
    ld hl,Coord
    ld de,.SpacesBetweenQuantityAndPriceText
    call PlaceString
    ld de,$ff9f ; total price
    ld c,$a3
    jp PrintBCDNumber
.SpacesBetweenQuantityAndPriceText
    db "      @"

