_CheckNotEscapeWildPokemon:
    ld a,[W_BATTLETYPE]
    cp $2 ; is safari?
    jr z,.Safari ; notSafariZone
    ld a,[W_PLAYERMONSTATUS]
    and FRZ | SLP
    jr nz,.NotEscape
    ld a,[W_ENEMYMONID]
    ld b,a
    ld hl,.NotEscapeWildPokemon
.Loop
    ld a,[hli]
    cp $FF
    jr z,.NotInList
    cp b
    jr nz,.Loop
.NotEscape
    scf ; set carry flag
    ret
.NotInList
.CheckShiny
    ld hl,W_ENEMYBATTSTATUS3
    bit TRANSFORMED,[hl]
    ld hl,W_ENEMYMONATKDEFIV
    jr z,.NotTransformed
    ld hl,$cceb
.NotTransformed
    call CheckShiny
    jr z,.NotEscape
.End
    ld a,[W_BATTLETYPE] ; $d05a
    cp $2
    jp z,.skip
    ld a,[$d120]
    inc a
    ld [$d120],a
.skip
    ld a,[W_ENEMYMONSTATUS]
    and FRZ | SLP ; reset carry flag
    ret
.Safari
    ld a,[W_ENEMYMONID]
    cp LAPRAS
    jr z,.NotEscape
    jr .CheckShiny

.NotEscapeWildPokemon
    db VOLTORB
    db ELECTRODE
    db ALAKAZAM
    db MACHAMP
    db GOLEM
    db GENGAR
    db AERODACTYL
    db SNORLAX
    db ARTICUNO
    db ZAPDOS
    db MOLTRES
    db DRAGONITE
    db MEWTWO
    db MEW
    db $FF

PrintStatsBox:
    ld a,d
    and a ; a is 0 from the status screen
    jr nz,.DifferentBox ; 0x12ae6 $12
    FuncCoord 19,7
    ld hl,Coord
    ld bc,$0a07
    call DrawLineBox2
    FuncCoord 11,7 ; Start printing stats from here
    ld hl,Coord
    ld bc,$0019 ; Number offset
    jr .PrintStats ; 0x12af8 $10
.DifferentBox
    call DetermineCoordinateStatsBox
.PrintStats
    push bc
    push hl
    ld de,StatsText
    call PlaceString
    pop hl
    pop bc
    add hl,bc
    jp CalcStatNoStatExp

StatsText:
    db "Health",$4e
    db "Attack",$4e
    db "Defense",$4e
    db "Speed",$4e
    db "Special@"

DetermineCoordinateStatsBox:
    ld a,[W_ISINBATTLE] ; no battle,this is 0
    and a
    jr z,.OutOfBattleBattle
.InBattle
    FuncCoord 00,06
    ld hl,Coord
    ld b,$a
    ld c,$8
    call TextBoxBorder
    FuncCoord 01,07
    ld hl,Coord
    ld bc,$0019
    ret
.OutOfBattleBattle
    FuncCoord 10,2
    ld hl,Coord
    ld b,$a
    ld c,$8
    call TextBoxBorder
    FuncCoord 11,3 ; $c3e7
    ld hl,Coord
    ld bc,$0019
    ret

CalcStatNoStatExp:
    ld de,$cfba ; hp actual stat
    ld a,[$cfb9] ; copy actual pokemon level to enemy mon level used in CalcStat
    ld [$d127],a ; ...
    ld b,0 ; NOT consider stat exp
    ld c,0 ; Start with HP
.statsLoop
    inc c ; Start with Atk
    push hl
    ld hl,$cfa8 ; actual mon stat exp - 1
    ld a,[H_CURRENTPRESSEDBUTTONS]
    bit 3,a ; was the start button pressed?
    push af
    call nz,CalcStat
    pop af
    pop hl
    call .PrintSingleStat
    ld a,c
    cp $5
    jr nz,.statsLoop
    xor a
    ld [wTempStatHI],a
    ld [wTempStatLO],a
    ret

.PrintSingleStat
    push bc
    push de

    jr nz,.ShowDetailedStat

    ; Print Actual Stat
    push bc
    ld a,[de]
    ld [wTempStatHI],a
    inc de
    ld a,[de]
    ld [wTempStatLO],a
    dec de
    ld bc,$0203 ; three digits
    call .PrintStat
    pop bc
    jr .done2

.ShowDetailedStat

    ; [de] : actual stat
    ; [H_MULTIPLICAND+1] : stat without stat exp
    call .GetBaseAndActualStatIn_DEBC
    ; de : actual stat
    ; bc : stat without stat exp

    ; de : actual stat
    ; bc : stat without stat exp
    call .GetDeltaStatIn_DE
    ; de : delta
    ; bc : stat without stat exp

    ; if delta <=9 shift right
    ld a,d
    and a
    jr nz,.done1
    ld a,e
    cp 10
    jr nc,.done1 ; >=10
    inc hl
.done1

    ; Print stat without stat exp
    push bc
    ld bc,-3;+20
    add hl,bc
    pop bc
    ld a,c
    ld [wTempStatLO],a
    ld a,b
    ld [wTempStatHI],a
    ld bc,$0203 ; three digits
    call .PrintStat

    ; Print Delta
    ld bc,+4
    add hl,bc
    ld a,e
    ld [wTempStatLO],a
    ld a,d
    ld [wTempStatHI],a
    ld bc,$6203 ; three digits ; print leading zeroes
    call .PrintStat

    dec hl
    ld [hl],$D2 ; plus

    ; if delta <=9 shift left
    ld a,d
    and a
    jr nz,.done2
    ld a,e
    cp 10
    jr nc,.done2 ; >=10
    dec hl
.done2

    pop de
    inc de
    inc de
    ld bc,40
    add hl,bc
    pop bc
    ret

.PrintStat
    push hl
    push de
    ld de,wTempStatHI
    call PrintNumber
    pop de
    pop hl
    ret

.GetBaseAndActualStatIn_DEBC
    ; [de] : actual stat
    ; [H_MULTIPLICAND+1] : stat without stat exp
    ld a,[de]
    ld b,a
    inc de
    ld a,[de]
    ld e,a
    ld d,b
    ld a,[H_MULTIPLICAND+1]
    ld b,a
    ld a,[H_MULTIPLICAND+2]
    ld c,a
    ; de : actual stat
    ; bc : stat without stat exp
    ret

.GetDeltaStatIn_DE
    ; de : actual stat
    ; bc : stat without stat exp
    ld a,e
    sub c
    ld e,a
    ld a,d
    sbc b
    ld d,a
    ; de : delta
    ; bc : stat without stat exp
    ret

; Draws a line starting from hl high b and wide c
DrawLineBox2:
    ld de,$0014 ; New line
.PrintVerticalLine
    ld [hl],$78 ; │
    add hl,de
    dec b
    jr nz,.PrintVerticalLine ; 0x12ace $fa
    ld [hl],$77 ; ┘
    dec hl
.PrintHorizLine
    ld [hl],$76 ; ─
    dec hl
    dec c
    jr nz,.PrintHorizLine ; 0x12ad7 $fa
    ld [hl],$6f ; ← (halfarrow ending)
    ret

