UpgradeTrainerSet_:
    ld a,[wEngagedTrainerClass]
    ld hl,.EliteFourList
    ld de,1
    call IsInArray
    jr c,.EliteFour
    ld a,[wEngagedTrainerClass]
    ld b,a
    ld hl,.Gym
.loop
    ld a,[hli]
    cp $FF
    jr z,.end
    cp b
    jr nz,.next
    ld b,[hl] ; Read Mask
    ld a,[W_OBTAINEDBADGES]
    and b ; Apply Mask
    ld b,a
    ld c,8
    ld a,[wEngagedTrainerSet] ; Gym Leader Team
.CheckBadge
    srl b
    jr nc,.NextBadge
    inc a
.NextBadge
    dec c
    jr nz,.CheckBadge
    ld hl,wEngagedTrainerSet ; Gym Leader Team
    ld [hl],a
    call CheckHallOfFameWin
    jr z,.end
.add1
    inc [hl] ; add 1 if after hall of fame
    jr .end
.next
    inc hl
    jr .loop
.EliteFour
    ld hl,wFlagsGymLeaderAfterHoFWin
    ld b,1
    call CountSetBits
    cp 7
    ld hl,wEngagedTrainerSet ; Elite Four Team
    jr nc,.add1
.end
    jp PlayTrainerMusic
.Gym
    db BROCK    , %11111110
    db MISTY    , %11111100
    db LT_SURGE , %11111000
    db ERIKA    , %11110000
    db KOGA     , %11000000
    db SABRINA  , %11000000
    db BLAINE   , %10000000
    db $FF
.EliteFourList
    db BRUNO
    db AGATHA
    db LORELEI
    db LANCE
    db $FF

