; Input d = Gym ID
TryGymLeaderRematch_:
    ld e,d
    ld a,[wGymLeaderRematch]
    ld c,a
.loop
    srl c
    dec d ; C - Not affected.
    jr nz,.loop
    ret nc ; rcf
    push de ; Backup Gym ID
    ld hl,GymLeaderRematchText1
    call PrintText
    call YesNoChoice ; yes/no textbox
    ld a,[$CC26] ; yes/no answer (Y=0,N=1)
    and a
    jr nz,.Fail
    ld hl,GymLeaderRematchText2
    call PrintText
    ld hl,$d72d
    set 6,[hl]
    set 7,[hl]
    ld hl,NoCommentText58
    ld d,h
    ld e,l
    call PreBattleSaveRegisters
    ldh a,[$8c]  ; Map Sprite ID
    ld [$cf13],a ; ...
    call EngageMapTrainer
    call InitBattleEnemyParameters
    pop de ; Restore Gym ID
    ld a,e               ; Gym Leader ID
    ld [W_GYMLEADERNO],a ; ...
    xor a       ; ??? hJoyHeld
    ldh [$b4],a ; ...
    call .SetNextScript
    scf
    ret
.Fail
    pop de ; Restore Gym ID
    xor a ; rcf
    ret
.SetNextScript
    ld hl,.MapScriptPointers
    ld d,0
    dec e
    add hl,de
    add hl,de
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ld a,$4
    ld [hl],a
    ld [W_CURMAPSCRIPT],a
    ret
.MapScriptPointers
    dw W_PEWTERGYMCURSCRIPT
    dw W_CERULEANGYMCURSCRIPT
    dw W_VERMILIONGYMCURSCRIPT
    dw W_CELADONGYMCURSCRIPT
    dw W_FUCHSIAGYMCURSCRIPT
    dw W_SAFFRONGYMCURSCRIPT
    dw W_CINNABARGYMCURSCRIPT
    dw W_VIRIDIANGYMCURSCRIPT

; ──────────────────────────────────────────────────────────────────────

GymLeaderAfterRematch_:
    ld hl,.MapScriptPointers
    call GetCurrentOldAdventureMap
    ld b,a
    ld c,1 ; First Gym
.loop
    ld a,[hli]
    cp $FF
    ret z
    cp b
    jr z,.done
    inc hl
    inc hl
    inc c
    jr .loop
.done
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ld a,[W_ISINBATTLE] ; $d057
    cp $ff
    jr z,.reset
    push hl
    ; c = Gym ID (1...7)
    call CheckHallOfFameWin
    call nz,.SetBeatGymAfterHoFWin
    call .ResetGymLeaderRematchFlag
    pop hl
.reset
    xor a
    ld [hl],a
    ld [wJoypadForbiddenButtonsMask],a
    ld [W_CURMAPSCRIPT],a
    ret
.MapScriptPointers
    dbw PEWTER_GYM    , W_PEWTERGYMCURSCRIPT
    dbw CERULEAN_GYM  , W_CERULEANGYMCURSCRIPT
    dbw VERMILION_GYM , W_VERMILIONGYMCURSCRIPT
    dbw CELADON_GYM   , W_CELADONGYMCURSCRIPT
    dbw FUCHSIA_GYM   , W_FUCHSIAGYMCURSCRIPT
    dbw SAFFRON_GYM   , W_SAFFRONGYMCURSCRIPT
    dbw CINNABAR_GYM  , W_CINNABARGYMCURSCRIPT
    dbw VIRIDIAN_GYM  , W_VIRIDIANGYMCURSCRIPT
    db $FF
.SetBeatGymAfterHoFWin
    ld hl,wFlagsGymLeaderAfterHoFWin
    call .Read
    ret nz ; return if just set
    set 7,a
    jr .Store
.ResetGymLeaderRematchFlag
    ld hl,wGymLeaderRematch
    call .Read
    ret z ; return if just reset
    res 7,a
    ; ft
.Store
    ld b,c
    call .loop2
    ld [hl],a ; Store
    ret
.loop1
    rrc a
    dec b
    jr nz,.loop1
    ret
.loop2
    rlc a
    dec b
    jr nz,.loop2
    ret
.Read
    ld a,[hl] ; Read
    ld b,c
    call .loop1
    bit 7,a
    ret

