_DrawBadges:
; Draw 4x2 gym leader badges
; Used in the player status screen.
; In Japanese versions,names are displayed above faces.
; Instead of removing relevant code,the name graphics were erased.

; Tile ids for badge graphics.
    ld de,$cd3f
    ld hl,.BadgeTiles
    ld bc,8
    call CopyData

; Booleans for each badge.
    ld hl,$cd49
    ld bc,8
    xor a
    call FillMemory

; Alter these based on owned badges.
    ld hl,$cd49
    ld a,[W_OBTAINEDBADGES]
    ld b,a
    ld a,[wGymLeaderRematch]
    ld d,a
    ld a,[wFlagsGymLeaderAfterHoFWin]
    ld e,a
    ld c,8
.CheckBadge
    srl b
    jr nc,.NextBadge
    set 0,[hl]
    srl d
    jr nc,.CheckFlagsGymLeaderAfterHoFWin
    set 1,[hl]
.CheckFlagsGymLeaderAfterHoFWin
    srl e
    jr nc,.NextBadge2
    set 2,[hl]
    jr .NextBadge2
.NextBadge
    srl d
    srl e
.NextBadge2
    inc hl
    dec c
    jr nz,.CheckBadge

    FuncCoord 03,12
    ld hl,Coord
    ld de,$cd49
    ld c,8 ; Draw 8 badges.
    ld b,0 ; num of Badge Printed
.loop
    push de
    push hl

; Badges are printed if the badge is owned.
    ld a,[de]
    bit 0,a
    jr z,.SkipBadge
    push af
    ld a,[$cd3f]
    call .PlaceTiles
    ld de,20 - 1
    add hl,de
    call .PlaceTiles
    pop af
    bit 1,a
    jr z,.skip1
    ld [hl],$D0 ; Mail Icon
.skip1
    bit 2,a
    jr z,.skip2
    inc hl
    ld [hl],$D1 ; Star Icon
    dec hl
.skip2

    inc b ; increase num of Badge Printed
    ld a,b
    cp 4

    pop hl
    ld de,4
    jr nz,.skip
    ld de,20*3-12
.skip
    add hl,de
    push hl

.SkipBadge

; Shift badge array back one byte.
    push bc
    ld hl,$cd3f + 1
    ld de,$cd3f
    ld bc,8
    call CopyData
    pop bc

    pop hl
    pop de
    inc de
    dec c
    jr nz,.loop
    ret

.PlaceTiles
    ld [hli],a
    inc a
    ld [hl],a
    inc a
    ret

.BadgeTiles
    db $24,$2C,$34,$3C,$44,$4C,$54,$5C

