DebugNPC:

    ; Standard CableClubNPC
    ld a,[H_CURRENTPRESSEDBUTTONS] ; ▼▲◄►StSeBA
    bit 1,a
    BANKSWITCH_JUMP_NZ CableClubNPC

    ; Backup
    ld a,[$cf92]
    push af
    ld a,[$cc49]
    push af

    ld a,[H_CURRENTPRESSEDBUTTONS] ; ▼▲◄►StSeBA
    bit 2,a ; was the select button pressed?
    jr nz,.select
    bit 3,a ; was the start button pressed?
    jr nz,.start
    jp .standard

.select
    bit 6,a ; was the up button pressed?
    jr nz,.selectUP
    ld hl,W_NUMINPARTY
    ld a,[hli]
    ld b,a
.loop0
    ld a,[hli]
    push bc
    push hl
    ld [$d11e],a
    call IndexToPokedexAndRestoreD11E
    ld b,1 ; set
    ld c,a
    push bc
    ld hl,wPokedexSeen
    call .HandleBit
    pop bc
    ld hl,wPokedexOwned
    call .HandleBit
    pop hl
    pop bc
    dec b
    jr nz,.loop0
    ld hl,.DoneTextSelect
    jp .end
.HandleBit
    PREDEF_JUMP HandleBitArray
.DoneTextSelect
    db 0,"Done! (Pokedex)",$57,"@"

.selectUP
    ld hl,W_PARTYMON1_MOVE2PP
    inc [hl]
    ld hl,.DoneTextSelectUP
    jp .end
.DoneTextSelectUP
    db 0,"Done! (Alt.Form)",$57,"@"

.start
    bit 6,a ; was the up button pressed?
    jr nz,.startUP
    ld hl,W_PARTYMON1_TYPE1
    xor a
    ld [hli],a ; Zero Type 1/2
    ld [hl],a  ; ...
    ld hl,W_PARTYMON1OT+8
    ld [hli],a ; Mon OT + 8
    ld [hli],a ; Mon OT + 9
    ld [hl],a  ; Mon OT + 10
    ld hl,W_PARTYMON1_MOVE3PP
    ld [hl],a  ; Ex Move 3 PP
    ld hl,.DoneTextStart
    jp .end
.DoneTextStart
    db 0,"Done! (Reset TM)",$57,"@"

.startUP
    ld hl,W_PARTYMON1_MOVE4PP
    call .LoopAndDestroyLastRecord
    ld hl,W_PARTYMON1_MOVE4
    call .LoopAndDestroyLastRecord
    ld hl,.UPText
    jr .end
.LoopAndDestroyLastRecord
    ld b,4
.LoopUP
    ld a,[hld]
    and a
    jr nz,.foundUP
    dec b
    jr nz,.LoopUP
.foundUP
    inc hl
    xor a
    ld [hl],a
    ret
.UPText
    db 0,"Done! (0 PP Move)",$57,"@"

.standard
    ld a,[W_NUMINPARTY]
    ld b,a
    ld c,0
.loop2
    push bc
    ld a,[$FF00+$e4]
    push af
    ld a,c
    inc a
    ld [$FF00+$e4],a ; Mon Id +1
    BANKSWITCH AddPokemonToParty_TryToAddExclusiveMove_
    pop af
    ld [$FF00+$e4],a
    pop bc
    inc c
    dec b
    jr nz,.loop2
    ld hl,.DoneText
    jr .end
.DoneText
    db 0,"Done!",$57,"@"

.end
    call PrintText
    ; Restore
    pop af
    ld [$cc49],a
    pop af
    ld [$cf92],a
    jp TextScriptEnd

