GetPredefPointer:
; stores hl in $CC4F,$CC50
; stores de in $CC51,$CC52
; stores bc in $CC53,$CC54
; grabs a byte "n" from $CC4E,
;    and gets the nth (3-byte) pointer in PredefPointers
; stores the bank of said pointer in [$D0B7]
; stores the pointer in hl and returns
    ; ld $CC4F,hl
    ld a,h
    ld [$CC4F],a
    ld a,l
    ld [$CC50],a

    ; ld $CC51,de
    ld hl,$CC51
    ld a,d
    ld [hli],a
    ld a,e
    ld [hli],a

    ; ld $CC53,bc
    ld a,b
    ld [hli],a
    ld [hl],c

    ld hl,PredefPointers
    ld de,0

    push af ; Backup F Flags
    ; de = 3 * [$CC4E]
    ld a,[$CC4E]
    ld e,a
    add a,a
    add a,e
    ld e,a
    jr nc,.next
    inc d

.next
    add hl,de
    ld d,h
    ld e,l
    pop af ; Restore F Flags

    ; get bank of predef routine
    ld a,[de]
    ld [$D0B7],a
    push af

    ; get pointer
    inc de
    ld a,[de]
    ld l,a
    inc de
    ld a,[de]
    ld h,a

    pop af
    ret

