_SynchronizeParty:
    ld hl,W_NUMINPARTY
    ld a,[hl]
    and a
    ld d,h
    ld e,l
    inc de
    ld c,0
    jr z,.loop2
    cp 6 + 1
    jr c,.continue
    ld a,6
    ld [hl],a
.continue
    ld hl,W_PARTYMON1DATA
    ld b,a
.loop
    ld a,[hl]
    ld [de],a
    push de
    ld de,W_PARTYMON2DATA-W_PARTYMON1DATA
    add hl,de
    pop de
    inc de
    inc c
    dec b
    jr nz,.loop
.loop2
    ld a,$FF
    ld [de],a
    inc de
    inc c
    ld a,c
    cp 6 + 1
    ret z
    jr .loop2

; ──────────────────────────────────────────────────────────────────────

_SynchronizeBox:
    ld hl,W_NUMINBOX
    ld a,[hl]
    and a
    ld d,h
    ld e,l
    inc de
    ld c,0
    jr z,.loop2
    cp 20 + 1
    jr c,.continue
    ld a,20
    ld [hl],a
.continue
    ld hl,W_BOXMON1DATA
    ld b,a
.loop
    ld a,[hl]
    ld [de],a
    push de
    ld de,W_BOXMON2DATA-W_BOXMON1DATA
    add hl,de
    pop de
    inc de
    inc c
    dec b
    jr nz,.loop
.loop2
    ld a,$FF
    ld [de],a
    inc de
    inc c
    ld a,c
    cp 20 + 1
    ret z
    jr .loop2

