UpdatePartyStats:
    ld a,[W_CURENEMYLVL]
    push af
    ld a,[W_NUMINPARTY]
    ld b,a
    ld hl,W_PARTYMON1_NUM
.loop
    push bc
    push hl
    ld a,[hl]
    ld [$D0B5],a
    ld bc,W_PARTYMON1_MOVE2PP-W_PARTYMON1_NUM
    add hl,bc
    ld a,[hl]
    ld [wAlternateFormIndex],a
    call GetMonHeader
    ld bc,W_PARTYMON1_LEVEL-W_PARTYMON1_MOVE2PP
    add hl,bc
    ld a,[hli] ; hl = W_PARTYMON1_MAXHP
    ld [W_CURENEMYLVL],a
    ld d,h
    ld e,l
    ld bc,(W_PARTYMON1_EVHP-1)-W_PARTYMON1_MAXHP
    add hl,bc
    ld b,1
    call CalcStats
    pop hl
    ld bc,W_PARTYMON2DATA-W_PARTYMON1DATA
    add hl,bc
    pop bc
    dec b
    jr nz,.loop
    pop af
    ld [W_CURENEMYLVL],a
    ret

; ──────────────────────────────────────────────────────────────────────

UpdatePartyStats_DEBUG:
    ld a,[W_CURENEMYLVL]
    push af
    ld a,[W_NUMINPARTY]
    and a
    jr z,.end
    ld b,a
    ld c,0
    ld hl,W_PARTYMON1_LEVEL
.loop
    push bc
    push hl
    ld a,c
    ld [wWhichPokemon],a
    xor a
    ld [$cc49],a
    call LoadMonData
    BANKSWITCH CalcLevelFromExperience
    pop hl
    push hl
    ld a,d
    ld [hli],a ; Store Level from EXP
    ld [W_CURENEMYLVL],a
    ; hl = W_PARTYMON1_MAXHP
    ld d,h
    ld e,l
    ld bc,(W_PARTYMON1_EVHP-1)-W_PARTYMON1_MAXHP
    add hl,bc
    ld b,1
    call CalcStats
    pop hl
    push hl
    inc hl ; hl = W_PARTYMON1_MAXHP
    ld a,[hli]
    ld d,a
    ld e,[hl] ; hl = W_PARTYMON1_MAXHP+1
    ld bc,(W_PARTYMON1_HP)-(W_PARTYMON1_MAXHP+1)
    add hl,bc
    ld a,[hli]
    ld b,a
    ld c,[hl]
    ; de = MaxHP
    ; bc = HP
    ld a,d
    cp b
    jr z,.CompareHpLSB ; jump if d = b
    jr nc,.done ; jump if d > b
    ; d < b
.SetHpToMax
    ld [hl],e
    dec hl
    ld [hl],d
    jr .done
.CompareHpLSB
    ld a,e
    cp c
    jr c,.SetHpToMax ; jump if e < c
.done
    pop hl
    ld bc,W_PARTYMON2DATA-W_PARTYMON1DATA
    add hl,bc
    pop bc
    inc c
    dec b
    jr nz,.loop
.end
    pop af
    ld [W_CURENEMYLVL],a
    ret

