KANTO    EQU 0
NEWWORLD EQU 1

GRAPHICAL_SCRIPT: MACRO
    db \1
    db \2
    db BANK(\3)
    dw \3
    ENDM

RunMapGraphicalScript:
    ld a,[wAdventureMap]
    ld b,a
    ld a,[W_CURMAP]
    ld c,a
    ld hl,.Table
.next
    ld a,[hli]
    cp $FF
    ret z
    cp b
    jr nz,.next1
    ld a,[hli]
    cp c
    jr nz,.next2
    ld a,[hli]
    ld b,a ; BANK
    ld a,[hli]
    ld h,[hl]
    ld l,a
    jp Bankswitch
.next1
    inc hl
.next2
    inc hl
    inc hl
    inc hl
    jr .next
.Table
