GenRandom_:
    push hl
    push bc
    push de
    call UpdateDividerCounters
    ld hl,wRNGState
    ld a,[hli]
    ld b,a
    ld a,[hli]
    ld c,a
    ld a,[hli]
    ld d,a
    ld e,[hl]
    ld a,e
    add a,a
    xor b
    ld b,a
    ld a,d
    rla
    ld l,c
    rl l
    ld h,b
    rl h
    sbc a
    and 1
    xor c
    ld c,a
    ld a,h
    xor d
    ld d,a
    ld a,l
    xor e
    ld e,a
    ld h,b
    ld l,c
    push hl
    ld h,d
    ld a,e
    rept 2
        sla e
        rl d
        rl c
        rl b
    endr
    xor e
    ld e,a
    ld a,h
    xor d
    ld d,a
    pop hl
    ld a,l
    xor c
    ld c,a
    ld a,h
    xor b
    ld hl,wRNGState
    ld [hli],a
    ld a,c
    ld [hli],a
    ld a,d
    ld [hli],a
    ld [hl],e
    ld a,[rDIV]
    add a,[hl]
    ld [H_RAND1],a
    ld a,[hli]
    inc hl
    inc hl
    sub [hl]
    ld [H_RAND2],a
    pop de
    pop bc
    pop hl
    ret

UpdateDividerCounters::
    ld a,[rDIV]
    ld hl,wRNGCumulativeDividerMinus
    sbc [hl]
    ld [hld],a
    ld a,[rDIV]
    adc [hl]
    ld [hld],a
    ret nc
    inc [hl]
    ret

AdvanceRNGState::
    ld hl,wRNGState
    ld a,[hli]
    ld b,a
    ld a,[hli]
    ld c,a
    ld a,[hli]
    ld d,a
    ld a,[hli]
    ld e,a
    ld a,[hli]
    ld l,[hl]
    ld h,a
    ld a,[rDIV]
    rra
    jr nc,.try_upper
.try_lower
    ld a,h
    cp d
    ld a,l
    jr nz,.lower
    cp e
    jr nz,.lower
.upper
    xor c
    ld c,a
    ld a,h
    xor b
    jr .done
.try_upper
    ld a,h
    cp b
    ld a,l
    jr nz,.upper
    cp c
    jr nz,.upper
.lower
    xor e
    ld e,a
    ld a,h
    xor d
    ld d,a
    ld a,b
.done
    ld hl,wRNGState
    ld [hli],a
    ld a,c
    ld [hli],a
    ld a,d
    ld [hli],a
    ld [hl],e
    ret

GenRandomInBattle_CH:
    push bc
    BANKSWITCH GenRandomInBattleFromOtherBANK
    ld a,d
    pop bc
    ret

; high critical hit moves
HighCriticalMoves:
    db KARATE_CHOP
    db RAZOR_LEAF
    db HAMMER
    db SLASH
    db $FF

_CriticalHitTest_NoBug:
    xor a
    ld [wCriticalHitOrOHKO],a
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    ld a,[W_ENEMYMONALTFORM]
    ld b,a
    ld a,[W_ENEMYMON_START]
    jr nz,.handleEnemy
    ld a,[W_PLAYERMONALTFORM]
    ld b,a
    ld a,[W_PLAYERMONID]
.handleEnemy
    ld [$d0b5],a
    ld a,b
    ld [wAlternateFormIndex],a
    call GetMonHeader
    ld a,[W_MONHBASESPEED]
    ld b,a
    srl b                        ; /2 for regular move (effective (base speed / 2)) --> base crit rate
    ld a,[H_WHOSETURN] ; $FF00+$f3
    and a
    ld a,[W_PLAYERMOVEEFFECT]    ; joenote - begin storing player move effect
    ld hl,W_PLAYERMOVEPOWER ; $cfd4
    ld de,W_PLAYERBATTSTATUS2 ; $d063
    jr z,.calcCriticalHitProbability
    ld a,[W_ENEMYMOVEEFFECT]     ; joenote - begin storing enemy move effect
    ld hl,W_ENEMYMOVEPOWER ; $cfce
    ld de,W_ENEMYBATTSTATUS2 ; $d068
.calcCriticalHitProbability      ; 0x3e04f
;normal hit is (base speed) / 2
;focus energy is 2*(base speed) for a 4x crit rate
;high crit move is 4*(base speed) for a 8x crit rate
;;;;;;;;;;;;
;joenote - do not do a critical hit if a special damage move is being used (dragon rage, seismic toss, etc)
    cp SPECIAL_DAMAGE_EFFECT
    ret z
;;;;;;;;;;;;
    ld a,[hld]                   ; read base power from RAM
    and a
    ret z                        ; do nothing if zero
    dec hl
    ld c,[hl]                    ; read move id
    ld a,[de]
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
    bit 2,a                      ; test for focus energy
    jr z,.noFocusEnergyUsed      ;if getting pumped bit not set, then focus energy not used
    ;else focus energy was used
    sla b                        ;*2 for focus energy (effective +2x crit rate)
    jr c,.capcritical
    sla b                        ;*2 again for focus energy (effective +4x crit rate)
    jr c,.capcritical
.noFocusEnergyUsed
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
    ld hl,HighCriticalMoves      ; table of high critical hit moves
.Loop
    ld a,[hli]                   ; read move from move table
    cp c                         ; does it match the move about to be used?
    jr z,.HighCritical           ; if so, the move about to be used is a high critical hit ratio move
    inc a                        ; move on to the next move, FF terminates loop
    jr nz,.Loop                  ; check the next move in HighCriticalMoves
    jr .finishcalc               ; continue as a normal move
.HighCritical
    sla b                        ; *2 for high critical hit moves (effective +2x crit rate)
    jr c,.capcritical
    sla b                        ; *2 again for high critical hit moves (effective +4x crit rate)
    jr c,.capcritical
    sla b                        ; *2 again for high critical hit moves (effective +8x crit rate)
    jr nc,.finishcalc
.capcritical
    ld b,$ff                     ; cap at 255/256
.finishcalc
    call GenRandomInBattle_CH    ; generates a random value, in "a"
    rlc a
    rlc a
    rlc a
    cp b                         ; check a against calculated crit rate
    ret nc                       ; no critical hit if no borrow
    ld a,$1
    ld [wCriticalHitOrOHKO],a                 ; set critical hit flag
    ret

