PrintEXPBar_StatusScreen:
    call CalcEXPBarPixelLength_StatusScreen
    ld a,[H_QUOTIENT + 3] ; pixel length
    ld [wEXPBarPixelLength],a
    ld b,a
    ld c,$08
    ld d,$08
    FuncCoord 17,5
    ld hl,Coord
.loop
    ld a,b
    sub c
    jr nc,.skip
    ld c,b
    jr .loop
.skip
    ld b,a
    ld a,$c0
    add c
.loop2
    ld [hld],a
    dec d
    ret z
    ld a,b
    and a
    jr nz,.loop
    ld a,$c0
    jr .loop2

CalcEXPBarPixelLength_StatusScreen:
    ; get the base exp needed for the current level
    ld a,[$cfb9] ; Level
    call CalcEXPBarPixelLength_.Start
    ; get the exp needed to gain a level
    ld a,[$cfb9] ; Level
    call GetTheExpNeededToGainALevel
    ; get the address of the active Pokemon's current experience
    ld hl,$cfa6
    jp CalcEXPBarPixelLength_.Common

