; Print a box with selected/current move details
; input : [wPlayerSelectedMove] = Move ID
;         [de] = Upper left Corner Coord
PrintMoveDetailsBox:
    call Load16BitRegisters

    ; Get Current Move
    push de
    ld a,[wPlayerSelectedMove]
    dec a
    ld hl,Moves ; $4000
    ld bc,$6
    call AddNTimes
    ld a,BANK(Moves)
    ld de,W_PLAYERMOVENUM
    call FarCopyData
    pop de

    ; Init Screen Location
    ld h,d
    ld l,e

    ; Print Border
    ld bc,$0408
    call TextBoxBorder

    ; Move_Accuracy
    ld de,20*(-2)+(-8)
    add hl,de
    ld de,.AccrText
    call PlaceString
    push hl
    ld hl,$FF95
    xor a
    ld [hli],a
    ld [hli],a
    ld [hli],a
    ld a,[W_PLAYERMOVEACCURACY]
    ld [hli],a
    ld a,100
    ld [hl],a
    call Multiply
    ld a,255
    ld [$FF99],a
    ld b,4
    call Divide
    pop hl
    ld de,20*(+0)+(+4)
    add hl,de
    ld de,$FF98
    ld b,%00000001
    ld c,3
    call PrintNumber

    ; Move_Power
    ld de,20*(-1)+(-7)
    add hl,de
    ld de,.PwrText
    call PlaceString
    ld de,20*(+0)+(+4)
    add hl,de
    ld a,[W_PLAYERMOVEPOWER]
    and a
    jr z,.Power0
    dec a
    jr z,.Power1
    push hl
    call CheckSTAB
    ld a,10
    jr nz,.NoSTAB
    ld a,15
.NoSTAB
    ld [H_MULTIPLIER],a
    xor a
    ld [H_MULTIPLICAND],a
    ld [H_MULTIPLICAND+1],a
    ld a,[W_PLAYERMOVEPOWER]
    ld [H_MULTIPLICAND+2],a
    call Multiply
    ld a,10
    ld [H_DIVISOR],a
    ld b,4 ; number of bytes in dividend
    call Divide
    ld hl,wTempMovePowerHI
    ld a,[H_QUOTIENT+2]
    ld [hli],a
    ld a,[H_QUOTIENT+3]
    ld [hld],a
    ld d,h
    ld e,l
    pop hl
    ld bc,$0203
    call PrintNumber
    jr .PowerDone
.Power0
    inc hl
    inc hl
    ld [hl],"/"
    inc hl
    jr .PowerDone
.Power1
    inc hl
    inc hl
    ld [hl],"?"
    inc hl
.PowerDone

    ; Print Phi/Spc Symbols
    push hl
    ld hl,wHyperBeamUnknownTypeBit4
    bit 4,[hl]
    res 4,[hl]
    pop hl
    jr z,.skipHyperBeamException
    ld a,[W_PLAYERMOVENUM]
    ld de,.HyperBeamExceptionText
    cp HYPER_BEAM
    jr z,.PhiSpcPrint
    cp STRUGGLE
    jr z,.PhiSpcPrint
    cp TRI_ATTACK
    jr z,.PhiSpcPrint
    cp SWIFT
    jr z,.PhiSpcPrint
.skipHyperBeamException
    ld a,[W_PLAYERMOVEPOWER]
    and a
    jr z,.PhiSpcDone
    dec a
    jr z,.PhiSpcDone
    push hl
    call .GetMonAtk
    ld hl,W_PLAYERMOVENUM
    call TestPhysicalSpecial
    pop hl
    ld de,.PhiText
    jr z,.PhiSpcPrint
    ld de,.SpcText
.PhiSpcPrint
    call PlaceString
.PhiSpcDone

    ; PrintMoveType
    ld de,20*(-1)+(-7)
    add hl,de
    PREDEF PrintMoveType

    ; Print STAB
    ld de,20*(+0)+(+7)
    add hl,de
    ld a,[W_PLAYERMOVEPOWER]
    cp 2 ; 0 or 1
    jr c,.STABDone
    push hl
    call CheckSTAB
    pop hl
    jr nz,.STABDone
    ld [hl],$D4 ; Up Arrow Symbol
.STABDone

    ; Move_Energy
    ld de,20*(+3)+(-7)
    add hl,de
    ld de,.EneText
    call PlaceString
    ld de,20*(+0)+(+4)
    add hl,de
    ld de,W_PLAYERMOVEMAXPP
    ld b,%00000001
    ld c,3
    jp PrintNumber

.GetMonAtk
    ld a,[wWhichPokemon]
    ld hl,W_PARTYMON1_ATTACK ; monatk
    ld bc,44
    call AddNTimes
    ld d,h
    ld e,l
    ret

.AccrText
    db "ACR",$D3,"   ",$D9,"@"
.PwrText
    db "PWR",$D3,"@"
.EneText
    db "ENE",$D3,"   ",$DA,"@"
.PhiText
    db $D7,"@"
.SpcText
    db $D8,"@"
.HyperBeamExceptionText
    db "?@"

