CheckSTAB:
    ld a,[W_PLAYERMOVETYPE]
    and a ; TYPE_NA?
    jr z,.NoStab
    ld hl,$d11e ; Backup
    ld a,[hl]   ; ...
    push af     ; ...
    push hl     ; ...
    ld a,[W_PLAYERMOVETYPE]
    ld [hl],a
    ld a,[$cf91]
    ld b,a
    ld a,[W_PLAYERMOVENUM]
    ld c,a
    ld hl,wMoveDetBoxActualMonBit5
    bit 5,[hl]
    ld hl,W_MONHTYPES
    jr z,.done
    ld hl,W_PLAYERMONTYPES
.done
    PREDEF GetAttackerType_
    pop hl    ; Restore
    pop af    ; ...
    ld [hl],a ; ...
    ld a,[W_PLAYERMOVETYPE]
    ld hl,wTmpAttackerTypes
    ld b,4
.loop
    cp [hl] ; does the move type match type of the attacker?
    ret z
    inc hl
    dec b
    jr nz,.loop
.NoStab
    ld a,1 ; reset all flag
    or a   ; ...
    ret

