CheckSpecialWild_:
    push de
    ld hl,.SpecialWild
.LoopMon
    ld a,[$cf91]
    ld b,a
    ld a,[hli]
    cp $FF
    jr z,.NormalWild
    cp b
    jr z,.MonFound
    inc hl
.next
    inc hl
    inc hl
    inc hl
.next2
    inc hl
    inc hl
    jr .LoopMon
.NormalWild
    pop de
    xor a ; rcf
    ret
.MonFound
    ld a,[W_ENEMYMONLEVEL]
    ld b,a
    ld a,[hli] ; Table Level
    inc b
    cp b ; Enemy's Level +1
    jr nc,.next
    ; LevelFound ; if Enemy's Level >= Table Level
    call GetCurrentOldAdventureMap
    cp [hl]
    jr nz,.next
    ; MapFound
    inc hl
    ld a,[hli]
    ld b,a ; b = Y
    ld a,[hli]
    ld c,a ; c = X
    or b ; both 0?
    jr z,.SkipCheckPosition
    ld a,[$c214]
    cp b
    jr nz,.next2
    ld a,[$c215]
    cp c
    jr nz,.next2
.SkipCheckPosition
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ld b,4
    pop de
.Loop4Moves
    ld a,[hli]
    ld [de],a
    inc de
    dec b
    jr nz,.Loop4Moves
    scf
    ret

SPECIALWILD: MACRO
    db \1,\2,\3
