; ──────────────────────────────────────────────────────────────────────

; PP ► ENERGY - DONE
DecrementPP: ; 68000 (1a:4000)
; after using a move,decrement pp in battle and (if not transformed?) in party
    ld a,[de]
    cp STRUGGLE
    ret z                ; if the pokemon is using "struggle",there's nothing to do
                         ; we don't decrement PP for "struggle"
    ld hl,W_PLAYERBATTSTATUS1
    ld a,[hli]          ; load the W_PLAYERBATTSTATUS1 pokemon status flags and increment hl to load the
                         ; W_PLAYERBATTSTATUS2 status flags later
    and a,7             ; check to see if bits 0,1,or 2 are set
    ret nz               ; if any of these statuses are true,don't decrement PP
    bit 6,[hl]          ; check 6th bit status flag on W_PLAYERBATTSTATUS2
    ret nz               ; and return if it is set
    ld hl,W_PLAYERMONENERGY ; Energy (in battle)
    call .DecrementPP
    ld hl,W_PARTYMON1_MOVE1PP ; PP of first move (in party)
    ld a,[wPlayerMonNumber] ; which mon in party is active
    ld bc,$2C           ; XXX probably size of party pokemon's data structure
    call AddNTimes       ; calculate address of the mon to modify
.DecrementPP
    ld a,[W_PLAYERMOVEMAXPP] ; Energy
    ld b,a
    ld a,[hl]
    sub b ; dec [hl]     ; Decrement Energy
    ld [hl],a
    ret

; PP ► ENERGY - DONE
DecrementEnemyPP_:
; after using a move,decrement pp in battle and (if not transformed?) in party
    ld a,[de]
    cp STRUGGLE
    ret z                ; if the pokemon is using "struggle",there's nothing to do
                         ; we don't decrement PP for "struggle"
    ld hl,W_ENEMYBATTSTATUS1
    ld a,[hli]          ; load the W_ENEMYBATTSTATUS1 pokemon status flags and increment hl to load the
                         ; W_ENEMYBATTSTATUS2 status flags later
    and a,7             ; check to see if bits 0,1,or 2 are set
    ret nz               ; if any of these statuses are true,don't decrement PP
    bit 6,[hl]          ; check 6th bit status flag on W_ENEMYBATTSTATUS2
    ret nz               ; and return if it is set
    ld hl,W_ENEMYMONENERGY ; Energy (in battle)
    call .DecrementPP

    ld a,[W_ISINBATTLE] ; $d057
    cp $2
    ret nz              ; Update Party only in enemy battle

    ld hl,wEnemyMon1 + (W_PARTYMON1_MOVE1PP-W_PARTYMON1DATA) ; $CFFE
                        ; PP of first move (in party)
    ld a,[W_ENEMYMONNUMBER] ; which mon in party is active
    ld bc,$2C           ; XXX probably size of party pokemon's data structure
    call AddNTimes       ; calculate address of the mon to modify
.DecrementPP
    ld a,[W_ENEMYMOVEMAXPP] ; Energy
    ld b,a
    ld a,[hl]
    sub b ; dec [hl]     ; Decrement Energy
    ld [hl],a
    ret

; ──────────────────────────────────────────────────────────────────────

; input hl = pointer to move id
; input de = pointer to mon attack
; output b = table byte with mask, need to test zero
TestPhysicalSpecial_:
    call Load16BitRegisters
    ld a,[hl] ; carico in a l'id dell'attacco
    cp HYPER_BEAM
    jr z,.SpecialSplit
    cp STRUGGLE
    jr z,.SpecialSplit
    cp TRI_ATTACK
    jr z,.SpecialSplit
    cp SWIFT
    jr z,.SpecialSplit
    srl a
    srl a
    srl a ; divido l'id dell'attacco per 8 per individuare il byte corretto nella tabella associativa (1 bit per attacco)
    ld e,a
    ld d,0 ; memorizzo in de l'offset per individuare il byte corretto
    ld a,[hl] ; ricarico in a l'id dell'attacco
    and a,%00000111 ; isolo in a i primi 3 bit meno significativi per individuare il bit del byte corretto
    ld b,%10000000
.CicloExp ; Ciclo di Creazione maschera
    and a
    jr z,.CicloExpEnd
    srl b ; b = b / 2
    dec a
    jr .CicloExp
.CicloExpEnd
    ld hl,.AttackTypeTable
    add hl,de ; punto il byte corretto
    ld a,[hl] ; leggo il byte corretto
    and b ; applico la maschera per isolare il bit corretto,il bit viene così testato
.end
    ld b,a
    ret
.SpecialSplit
    push hl
    ld h,d
    ld l,e
    ld a,[hli]
    ld b,a
    ld a,[hli]
    ld c,a
    inc hl
    inc hl
    inc hl
    inc hl
    ld a,[hli]
    ld d,a
    ld a,[hli]
    ld e,a
    pop hl
    ; bc = attack
    ; de = special
    ld a,b
    cp d
    jr c,.special ; if d > b ► special
    jr nz,.phisical ; if b > d ► phisical
    ; if d = b
    ld a,c
    cp e
    jr c,.special ; if e > c ► special
    ; if c >= e ► phisical
.phisical
    xor a
    jr .end
.special
    ld a,1
    and a
    jr .end
; tabella associativa attacco/tipologia di danno
.AttackTypeTable
db %00000000    ; Zero,Pound,Karate Chop*,Double Slap,Comet Punch,Mega Punch,Pay Day,Fire Punch
db %00000100    ; Ice Punch,Thunder Punch,Scratch,Vice Grip,Guillotine,Razor Wind,Swords Dance,Cut
db %10100000    ; Gust*,Wing Attack,Whirlwind,Fly,Bind,Slam,Vine Whip,Stomp
db %00000000    ; Double Kick,Mega Kick,Jump Kick,Rolling Kick,Sand Attack*,Headbutt,Horn Attack,Fury Attack
db %00000000    ; Horn Drill,Tackle,Body Slam,Wrap,Take Down,Thrash,Double-Edge,Tail Whip
db %00100000    ; Poison Sting,Twineedle,Pin Missile,Leer,Bite*,Growl,Roar,Sing
db %01001101    ; Supersonic,Sonic Boom,Disable,Acid,Ember,Flamethrower,Mist,Water Gun
db %11111110    ; Hydro Pump,Surf,Ice Beam,Blizzard,Psybeam,Bubble Beam,Aurora Beam,Hyper Beam
db %00000001    ; Peck,Drill Peck,Submission,Low Kick,Counter,Seismic Toss,Strength,Absorb
db %10001000    ; Mega Drain,Leech Seed,Growth,Razor Leaf,Solar Beam,Poison Powder,Stun Spore,Sleep Powder
db %10111101    ; Petal Dance,String Shot,Dragon Rage,Fire Spin,Thunder Shock,Thunderbolt,Thunder Wave,Thunder
db %00000110    ; Rock Throw,Earthquake,Fissure,Dig,Toxic,Confusion,Psychic,Hypnosis
db %00000100    ; Meditate,Agility,Quick Attack,Rage,Teleport,Night Shade,Mimic,Screech
db %00000000    ; Double Team,Recover,Harden,Minimize,Smokescreen,Confuse Ray,Withdraw,Defense Curl
db %00000000    ; Barrier,Light Screen,Haze,Reflect,Focus Energy,Bide,Metronome,Mirror Move
db %00010010    ; Self-Destruct,Egg Bomb,Lick,Smog,Sludge,Bone Club,Fire Blast,Waterfall
db %01000000    ; Clamp,Swift,Skull Bash,Spike Cannon,Constrict,Amnesia,Kinesis,Soft-Boiled
db %00100000    ; High Jump Kick,Flare,Dream Eater,Poison Gas,Barrage,Leech Life,Lovely Kiss,Sky Attack
db %01000100    ; Transform,Bubble,Dizzy Punch,Spore,Flash,Psywave,Splash,Acid Armor
db %00000000    ; Hammer,Explosion,Fury Swipes,Bonemerang,Rest,Rock Slide,Hyper Fang,Sharpen
db %01000000    ; Conversion,Tri Attack,Super Fang,Slash,Substitute,Struggle,???,???

; ──────────────────────────────────────────────────────────────────────
; STATUS SCREEN START
; ──────────────────────────────────────────────────────────────────────

; Predef 0x37
StatusScreen:
    ; Disable Quick Menu
    ld hl,$ffb7
    ld a,[hl]
    push af ; Backup Quick Menu
    xor a
    ld [hl],a
    ; Disable Update Sprites Flag
    ld hl,$cfcb
    ld a,[hl]
    push af ; Backup Update Sprites Flag
    ld a,$ff
    ld [hl],a
    ; prevent audio fade out
    ld hl,$d72c
    set 1,[hl]
    ld a,$33
    ld [$ff00+$24],a ; Reduce the volume
    ; Clear Screen & Update Sprites
    call GBPalWhiteOutWithDelay3
    call UpdateSprites ; move sprites (?)
    ; water/flower tile animation
    ld a,[$ff00+$d7]
    push af
    xor a
    ld [$ff00+$d7],a
    call LoadStatusScreenGenericTile ; Load Generic Tile
    ld a,[wRunningOnSGB]
    and a
    call nz,LoadFontTilePatternsWithWall ; Load Custom Tile

; STATUSSCREEN 1
    jr .skipOnlyFirstTime
.Status1
    call WaitForSoundToFinish
.Status1NoWaitSound
    call GBPalWhiteOutWithDelay3
.skipOnlyFirstTime
    call ClearScreen
    call CleanLCD_OAM ; Remove Mini Sprite
    ; Recalculate stats
    call .LoadMonData
    call HandleStatusScreen1
.getJoypadStateLoop1
    call .GetJoy
    and %11010011 ; ▼▲◄►StSeBA
    jr z,.getJoypadStateLoop1
    bit 1,a ; b pressed?
    jr nz,.end
    bit 7,a ; down pressed?
    jr nz,.downFromStatus1
    bit 6,a ; up pressed?
    jr nz,.upFromStatus1
    ; ft (a/right)

; STATUSSCREEN 2
    jr .skipIfDirectlyFromStatus1
    ; Recalculate stats
.Status2
    call .LoadMonData
.skipIfDirectlyFromStatus1
    call GBPalWhiteOutWithDelay3
    call ClearScreen
    call CleanLCD_OAM ; Remove Mini Sprite
    call HandleStatusScreen2
.getJoypadStateLoop2
    call .HandleMiniSprite
    call .GetJoy
    and %11100011 ; ▼▲◄►StSeBA
    jr z,.getJoypadStateLoop2
    bit 5,a ; left pressed?
    jr nz,.Status1NoWaitSound
    bit 7,a ; down pressed?
    jr nz,.downFromStatus2
    bit 6,a ; up pressed?
    jr nz,.upFromStatus2

    ; ft (a/b)

.end
    ; Update Selected Pokemon Menù ID
    ld a,[$cf92]
    ld [wPartyAndBillsPCSavedMenuItem],a
    call .ResetFlagStatusScreenJustLoad
    ; water/flower tile animation
    pop af
    ld [$ff00+$d7],a
    ; prevent audio fade out
    ld hl,$d72c
    res 1,[hl]
    ld a,$77
    ld [$ff00+$24],a
    ; Restore Tile & Remove Mini Sprite
    call GBPalWhiteOut
    call CleanLCD_OAM
    call LoadFontTilePatterns
    ld de,FontGraphics+(6*16*16)+(9*16) ; EmptyTile
    ld hl,$97F0
    ld bc,(BANK(FontGraphics) << 8 | $1)
    call GoodCopyVideoData
    ; Restore Update Sprites Flag
    pop af
    ld [$cfcb],a
    ; Restore Quick Menu
    pop af
    ld hl,$ffb7
    ld [hl],a
    ; END
    jp Delay3

.ResetFlagStatusScreenJustLoad
    ld hl,wStatusScreenJustLoadBit6
    res 6,[hl]
    ret

.downFromStatus1
    ld a,[$cf92]
    inc a
.commonFromStatus1
    call .CompareWithCurrentPartyBoxNum ; cp 6
    jr nc,.getJoypadStateLoop1 ; valid only between 0 and [W_NUMINPARTY]/[W_NUMINBOX]
    ld [$cf92],a
    call .ResetFlagStatusScreenJustLoad
    jp .Status1
.upFromStatus1
    ld a,[$cf92]
    dec a
    jr .commonFromStatus1
.downFromStatus2
    ld a,[$cf92]
    inc a
.commonFromStatus2
    call .CompareWithCurrentPartyBoxNum ; cp 6
    jr nc,.getJoypadStateLoop2 ; valid only between 0 and [W_NUMINPARTY]/[W_NUMINBOX]
    ld [$cf92],a
    call .ResetFlagStatusScreenJustLoad
    jp .Status2
.upFromStatus2
    ld a,[$cf92]
    dec a
    jr .commonFromStatus2
.GetJoy
    call GetJoypadStateLowSensitivity
    ld a,[$ffb5]
    ret

.LoadMonData
    call LoadMonData
    ;ld hl,wStatusScreenJustLoadBit6
    ;bit 6,[hl]
    ;ret nz ; Don't Recalculate
    ld a,[$cc49]
    cp $2 ; 2 means we're in a PC box
    ret c ;  Don't Recalculate
    ld a,[$cf9b]
    ld [$cfb9],a
    ld [$d127],a
    ld hl,$cfa8
    ld de,$cfba
    ld b,$1
    jp CalcStats ; Recalculate stats

.HandleMiniSprite
    ld a,[wCurrentMenuItem]
    push af
    BANKSWITCH Func_716f7
    pop af
    ld [wCurrentMenuItem],a
    ret

.CompareWithCurrentPartyBoxNum
    push af
    ld a,[$cc49] ; (0=Party|2=Box)
    and a
    ld hl,W_NUMINPARTY
    jr z,.party
.box
    ld hl,W_NUMINBOX
.party
    ld a,[hl]
    ld b,a
    pop af
    cp b
    ret

