.PlaceStatusScreenShinyGenderEtc
    BANKSWITCH PrintEXPBar_StatusScreen
    BANKSWITCH PrintStatsBox
    ld hl,$cfb3 ; .OutOfBattle
    call SetTempIV
    ; ────────────────────────────────── Gender
    BANKSWITCH GetGenderOutOfBattle
    jr c,.Genderless
    push af
    ld a,[$cfb9] ; .OutOfBattleLevel
    cp 10
    FuncCoord 13,02
    ld hl,Coord
    jr nc,.GreaterThen9
    dec hl
.GreaterThen9
    pop af
    ld de,.MaleIcon
    jr nz,.Male
    ld de,.FemaleIcon
.Male
    call PlaceString
.Genderless
    ; ────────────────────────────────── Debug DV/StatExp
