    ld a,[$cf98] ; Pokemon ID
    and a
    jr z,.noShiny
    cp $FF
    jr z,.noShiny
    ld hl,$cfb3 ; .OutOfBattle
    call CheckShiny
    jr nz,.noShiny
    FuncCoord 19,6
