.ExperienceSection
    FuncCoord 0,14
    ld hl,Coord
    ld de,.EXPPointsText
    call PlaceString
    ld de,$cfa6
    FuncCoord 0,15
    ld hl,Coord
    ld bc,$0308
    call PrintNumber ; exp
    call .asm_12c86
    ld hl,$cfa6
    ld a,[hli]
    ld b,a
    ld a,[hli]
    ld c,a
    ld a,[hl]
    or b
    or c
    and a
    ret z ; skipExpLevelUp
    FuncCoord 8,16
    ld hl,Coord
    ld de,.LevelUpText
    call PlaceString
    ld de,$cfa6
    FuncCoord 0,16
    ld hl,Coord
    ld bc,$0308
    jp PrintNumber
.asm_12c86 ; This does some magic with lvl/exp?
    ld a,[$cfb9] ; Load level
    cp $64
    jr z,.asm_12ca7 ; 0x12c8b $1a ; If 100
    inc a
    ld d,a
    BANKSWITCH CalcExperience
    ld hl,$cfa8
    ld a,[$ff00+$98]
    sub [hl]
    ld [hld],a
    ld a,[$ff00+$97]
    sbc [hl]
    ld [hld],a
    ld a,[$ff00+$96]
    sbc [hl]
    ld [hld],a
    ret
.asm_12ca7
    ld hl,$cfa6
    xor a
    ld [hli],a
    ld [hli],a
    ld [hl],a
    ret
