    ld bc,40+10
    add hl,bc
    call PlaceString

.Text3
    ld de,.EneText
    pop hl
    ld bc,40+1
    add hl,bc
    call PlaceString

.PlaceMoveName
    ld a,$2c
    ld [$d0b7],a
    ld a,MOVE_NAME
    ld [W_LISTTYPE],a
    call GetName
    ld de,$cd6d
    pop hl
    call PlaceString

.PlaceMoveType
    pop hl
    ld bc,20+1
    add hl,bc
    PREDEF PrintMoveType

.PlaceMoveAcr
    ; ─────── Move_Accuracy
    ld hl,$FF95
    xor a
    ld [hli],a
    ld [hli],a
    ld [hli],a
    ld a,[W_PLAYERMOVEACCURACY]
    ld [hli],a
    ld a,100
    ld [hl],a
    call Multiply
    ld a,255
    ld [$FF99],a
    ld b,4
    call Divide
    ; ───────
    ld de,$FF98
    pop hl
    ld bc,40+14
    add hl,bc
    ld bc,$0103
    call PrintNumber

.PlaceMovePwr
    pop hl
    ld bc,20+14
    add hl,bc
    ld a,[W_PLAYERMOVEPOWER]
    and a
    jr z,.Power0
    dec a
    jr z,.Power1
    push hl
    call CheckSTAB
    ld a,10
    jr nz,.NoSTAB
    ld a,15
.NoSTAB
    ld [H_MULTIPLIER],a
    xor a
    ld [H_MULTIPLICAND],a
    ld [H_MULTIPLICAND+1],a
    ld a,[W_PLAYERMOVEPOWER]
    ld [H_MULTIPLICAND+2],a
    call Multiply
    ld a,10
    ld [H_DIVISOR],a
    ld b,4 ; number of bytes in dividend
    call Divide
    ld hl,wTempMovePowerHI
    ld a,[H_QUOTIENT+2]
    ld [hli],a
    ld a,[H_QUOTIENT+3]
    ld [hld],a
    ld d,h
    ld e,l
    pop hl
    ld bc,$0203
    call PrintNumber
    ; Print Phi/Spc Symbols
    push hl
    call .GetMonAtk
    ld hl,W_PLAYERMOVENUM
    call TestPhysicalSpecial
    pop hl
    ld de,.PhiText
    jr z,.PhiSpcPrint
    ld de,.SpcText
.PhiSpcPrint
    call PlaceString
    jr .PowerDone
.Power0
    inc hl
    inc hl
    ld [hl],"/"
    inc hl
    jr .PowerDone
.Power1
    inc hl
    inc hl
    ld [hl],"?"
    inc hl
.PowerDone

.PlaceMoveEne
    ld de,W_PLAYERMOVEMAXPP
    pop hl
    ld bc,40+5
    add hl,bc
    ld bc,$0103
    call PrintNumber

.PlaceMoveSTAB
    ld a,[W_PLAYERMOVEPOWER]
    cp 2 ; 0 or 1
    jr c,.NoSTAB2
    call CheckSTAB
    ld d,$D4 ; Up Arrow Symbol
    jr z,.PrintSTAB
.NoSTAB2
    ld d," "
.PrintSTAB
    pop hl
    ld bc,00+17
    add hl,bc
    ld [hl],d

.end
    pop de
    pop bc
    pop af
    ret

.GetMonAtk
    ld a,[wWhichPokemon]
    ld hl,W_PARTYMON1_ATTACK ; monatk
    ld bc,44
    call AddNTimes
    ld d,h
    ld e,l
    ret

.MovesText
    db "'s Moves@"
.AccrText
    db "ACR",$D3,"   ",$D9,"@"
.PwrText
    db "PWR",$D3,"@"
.EneText
    db "ENE",$D3,"   ",$DA,"@"
.PhiText
    db $D7,"@"
.SpcText
    db $D8,"@"

