    add hl,de
    dec b
    jr nz,.PrintVerticalLine ; 0x12ace $fa
    ld [hl],$77 ; ┘
    dec hl
.PrintHorizLine
    ld [hl],$76 ; ─
    dec hl
    dec c
    jr nz,.PrintHorizLine ; 0x12ad7 $fa
    ld [hl],$6f ; ← (halfarrow ending)
    ret

unk_12a7e: ; I don't know what this does,iterates over pointers?
