; fill an area of the screen with blank tile
; INPUT:
; hl = address of upper left corner of the area
; b = height
; c = width
FillBlankArea:
    ld a,$E9 ; Blank Tile
    ld de,20 ; screen width
.loop
    push hl
    push bc
.innerLoop
    ld [hli],a
    dec c
    jr nz,.innerLoop
    pop bc
    pop hl
    add hl,de
    dec b
    jr nz,.loop
    ret

