ItemInBattleFinalCheck:
    ld a,[W_BATTLETYPE] ; $d05a
    and a
    jr nz,.safariOrOldMan
    ld a,[$d11c] ; checkIfMonCaptured
    and a
    push af
    jr z,.NoCapture
    call .PrintMonBackAndPlayerHUDAndHPBarAndMoney
    jr .done1
.NoCapture
    call LoadScreenTilesFromBuffer1DisableBGTransfer
    call .DrawHUDsAndHPBars
.done1
    call GBPalNormal
    call IfGBCDelay3
    pop af
    jr z,.EndNoCapture
    call .HackGainExpAfterCatch
    ld hl,wNoExpToLastPartyMonBit1
    res 1,[hl]
    call .HandlePlayerAliveAndApplyPoisonBurn
.EndCapture
    xor a
    ld [$d11c],a
    ld a,$2
    ld [wBattleResult],a
    scf
    ret
.safariOrOldMan
    call LoadScreenTilesFromBuffer1
    call GBPalNormal
    ld a,[$d11c] ; checkIfMonCaptured
    and a
    jr nz,.EndCapture
.EndNoCapture
    and a
    ret
.PrintMonBackAndPlayerHUDAndHPBarAndMoney
    call DisableAutoBgTransfer
    ld a,[W_PLAYERMONID]
