; Input
; de = Pointer to First Move
; wCurrentMenuItem = Move Index (0,1,2,3)
; Output
; carry flag, set = not enough energy or no move
CheckEnoughEnergy:
    push de
    ld h,d
    ld l,e
    push hl
    ld a,[wCurrentMenuItem]
    ld c,a
    ld b,$0
    add hl,bc
    ld a,[hl] ; Move ID
    and a
    jr z,.NoMove
    ld d,a
    call GetMoveEnergy ; d = Move Selected Energy
    pop hl
    push hl
    ld bc,W_PLAYERMONENERGY-W_PLAYERMONMOVES
    add hl,bc
    ld a,[hl] ; Mon Energy
    sub d
.end
    pop hl
    pop de
    ret
.NoMove
    scf
    jr .end

; Input : a = move ID
; Output : [wTempMoveEnergy] = Move Energy
GetMoveEnergy_:
    dec a
    ld hl,Moves+5 ; Move Energy
    ld bc,6
    call AddNTimes
    ld a,[$cee9]
    push af
    ld a,BANK(Moves)
    ld de,wTempMoveEnergy
    ld bc,1
    call FarCopyData
    pop af
    ld [$cee9],a
    ret

; Input : d = move ID
; Output : d = Move Energy
GetMoveEnergy:
    ld a,d
    call GetMoveEnergy_
    ld a,[wTempMoveEnergy]
    ld d,a
    xor a
    ld [wTempMoveEnergy],a
    ret

; ──────────────────────────────────────────────────────────────────────
; DisplayDepositWithdrawMenu
; ──────────────────────────────────────────────────────────────────────

DisplayDepositWithdrawMenu_:
    ; Emulate Move Relearner Status Only to Animate Mini Sprite
    ld hl,wFlagMoveRelearnEngagedBit7
    set 7,[hl]
    ; Quick Joypad
    ld a,1
    ld [$ffb7],a
    ; Disable Update Sprites Flag
    ld hl,$cfcb
    ld a,[hl]
    push af ; Backup Update Sprites Flag
    ld a,$ff
    ld [hl],a
    call .DepositWithdrawBorder
    ld a,[$ccd3]
    and a
    ld de,.DepositPCText
    jr nz,.asm_21761
    ld de,.WithdrawPCText
.asm_21761
    FuncCoord 11,09
    ld hl,Coord
    call PlaceString
    FuncCoord 11,11
    ld hl,Coord
    ld de,.StatsPCText
    call PlaceString
    ld hl,wTopMenuItemY ; $cc24
    ld a,09
    ld [hli],a ; wTopMenuItemY
    ld a,10
    ld [hli],a ; wTopMenuItemX
    xor a
    ld [hli],a ; wCurrentMenuItem
    inc hl
    inc a ; a = 1
    ld [hli],a ; wMaxMenuItem
    inc hl
    xor a
    ld [hl],a ; wLastMenuItem
    ld hl,wListScrollOffset ; $cc36
    ld [hli],a
    ld [hl],a
    ld [wPlayerMonNumber],a ; $cc2f
    ld [wPartyAndBillsPCSavedMenuItem],a
.LoopMenu3
    ld hl,wWaitReleaseJoyBit5
    set 5,[hl]
.StartOrShiftMon
    call .DepositWithdrawMonTitle
    xor a        ; counter for pokemon shaking animation
    ld [$d08b],a ; ...
.LoopMenu2
    call PlaceMenuCursor
    call Delay3
.LoopMenu
    BANKSWITCH ShakeMiniSprite ; shake mini sprite of selected pokemon
    call GetJoypadStateLowSensitivityWaitReleaseJoy
    jr nz,.LoopMenu
    ld b,a ; ▼▲◄►StSeBA
    ld a,[wWhichPokemon]
    bit 1,b
    jr nz,.BPressed
    bit 0,b
    jr nz,.APressed
    bit 6,b
    jr nz,.UpPressed
    bit 7,b
    jr nz,.DownPressed
    bit 4,b
    jr nz,.RightPressed
    bit 5,b
    jr nz,.LeftPressed
    jr .LoopMenu
.UpPressed
    ld a,[wCurrentMenuItem]
    and a
    jr z,.LoopMenu ; already at the top?
    dec a
    ld [wCurrentMenuItem],a
    jr .LoopMenu2
.DownPressed
    ld a,[wCurrentMenuItem]
    inc a
    ld c,a
    ld a,[wMaxMenuItem]
    cp c
    jr c,.LoopMenu ; already at the bottom?
    ld a,c
    ld [wCurrentMenuItem],a
    jr .LoopMenu2
.APressed
    ld a,[wCurrentMenuItem]
    and a
    jr z,.choseDepositWithdraw
    dec a
    jr z,.viewStats
.BPressed
    ; Restore Update Sprites Flag
    pop bc
    call .ResetConditions
    and a ; rcf
    ret
.RightPressed
    FuncCoord 18,04
    ld hl,Coord
    inc a
    jr .RightLeftCommon
.LeftPressed
    FuncCoord 05,04
    ld hl,Coord
    dec a
.RightLeftCommon
    call .GetNumberOfMon
    cp b
    jr nc,.WrapRightLeftCommon
    ld [hl]," "
.GoToDifferentPage
    ld [wWhichPokemon],a
    call Delay3
    jp .StartOrShiftMon
.WrapRightLeftCommon
    ld b,a
    ld a,[H_NEWLYPRESSEDBUTTONS]
    and a
    jp z,.LoopMenu
    inc b
    ld a,0
    jr nz,.GoToDifferentPage
    call .GetNumberOfMon
    ld a,b
    dec a
    jr .GoToDifferentPage
.choseDepositWithdraw
    call PlaceUnfilledArrowMenuCursor
    ld a,[$ccd3] ; 0 = withdraw | 1 = Deposit
    and a
    jr z,.Withdraw
.Deposit
    call .TryDeposit
    jr .end
.Withdraw
    call .TryWithdraw
.end
    call c,.RemoveLevel
    ; Restore Update Sprites Flag
    pop bc
    call .ResetConditions
    ret
.viewStats
    call SaveScreenTilesToBuffer1
    ld a,[$ccd3]
    and a
    ld a,$0
    jr nz,.asm_217b0
    ld a,$2
.asm_217b0
    ld [$cc49],a
    PREDEF StatusScreen
    call LoadScreenTilesFromBuffer1
    call ReloadTilesetTilePatterns
    call GoPAL_SET_CF1C
    call LoadGBPal
    jp .LoopMenu3
.ResetConditions ; carry flag contains function result, don't override it!
    ; Restore Update Sprites Flag
    ld a,b
    ld [$cfcb],a
    ; Reset Move Relearner Status
    ld hl,wFlagMoveRelearnEngagedBit7
    res 7,[hl]
    ; Quick Joypad
    ld a,0
    ld [$ffb7],a
    ret
.GetNumberOfMon
    push af
    ld a,[$ccd3]
    and a
    ld a,[W_NUMINPARTY]
    jr nz,.getNumber
    ld a,[W_NUMINBOX]
.getNumber
    ld b,a
    pop af
    ret

.DepositPCText
    db "DEPOSIT@"
.WithdrawPCText
    db "WITHDRAW@"
.StatsPCText
    db "STATS@"

.DepositWithdrawBorder
    FuncCoord 4,2
    ld hl,Coord
    ld b,9
    ld c,14
    jp TextBoxBorder

.RemoveLevel
    push af
    FuncCoord 05,09
    ld bc,$0104 ; 01,04
    ld hl,Coord
    call ClearScreenArea
    pop af
    ret

.DepositWithdrawMonTitle
    ; Clear Title Area
    FuncCoord 05,03
    ld bc,(04<<8|14)
    ld hl,Coord
    call ClearScreenArea
    FuncCoord 05,06
    ld bc,(06<<8|04)
    ld hl,Coord
    call ClearScreenArea
    ; Arrow
    ld a,[$cf92]
    push af ; current list id
    and a
    jr z,.skipLeftArrow
    FuncCoord 05,04
    ld a,$D6 ; Left Arrow
    ld [Coord],a
.skipLeftArrow
    call .GetNumberOfMon
    pop af ; current list id
    inc a
    cp b
    jr z,.skipRightArrow
    FuncCoord 18,04
    ld a,$ED ; Right Arrow
    ld [Coord],a
.skipRightArrow
    ; Box Slot
    FuncCoord 15,06
    ld hl,Coord
    ld [hl],"/"
    call .GetNumberOfMon
    ld a,b
    ld [wTempBoxSlot],a
    FuncCoord 16,06
    ld hl,Coord
    ld de,wTempBoxSlot
    ld bc,$102
    call PrintNumber
    ld a,[wWhichPokemon]
    inc a
    ld [wTempBoxSlot],a
    FuncCoord 13,06
    ld hl,Coord
    ld de,wTempBoxSlot
    ld bc,$102
    call PrintNumber
    ; Level
    call LoadMonData
    ld a,[$cc49]
    cp $2 ; 2 means we're in a PC box
    jr nz,.skip
    ld a,[$cf9b] ; box level
    ld [$cfb9],a ; real level
.skip
    FuncCoord 05,09
    ld hl,Coord
    call PrintLevel ; Pokémon level
    ; Gender
    push hl
    ld a,[$cf91]
    ld [$d11e],a
    ld hl,$cfb3 ; .OutOfBattle
    call SetTempIV
    BANKSWITCH GetGender
    call ResetTempIV
    pop hl
    jr c,.Genderless
    ld de,.MaleIcon
    jr nz,.Male
    ld de,.FemaleIcon
.Male
    call PlaceString
.Genderless
    ; Name
    ld a,[$ccd3]
    and a
    ld hl,W_PARTYMON1NAME
    jr nz,.getPokemonName
    ld hl,$de06 ; box pokemon names
.getPokemonName
    ld a,[$cf92]
    call GetPartyMonName
    call CopyStringToCF4B
    ld de,$cf4b
    FuncCoord 07,04
    ld hl,Coord
    call PlaceString
    ; Mini Sprite
    ld hl,wSpriteOAMBySpeciesBit7
    set 7,[hl]
    inc hl
    ld a,[$cf91]
    ld [$cd5d],a
    ld [hl],a ; wSpriteOAMBySpeciesId
    BANKSWITCH LoadMonPartySpriteGfx
    ld hl,wStatusScreen2OAMBit0
    set 0,[hl]
    ld de,$3E44
    BANKSWITCH WriteMonPartySpriteOAMBySpecies
    ld hl,wStatusScreen2OAMBit0
    res 0,[hl]
    ret
.MaleIcon
    db $EF,$50
.FemaleIcon
    db $F5,$50

.TryWithdraw
    ld a,[W_NUMINPARTY]
    cp 6
    jr nz,.Continue
    ld hl,.CantTakeMonText
    jp .Error
.Continue
    ld a,[wWhichPokemon]
    ld hl,$de06
    call GetPartyMonName
    ld a,[$cf91]
    call GetCryData
    call PlaySoundWaitForCurrent
    scf
    ret
.CantTakeMonText
    TX_FAR _CantTakeMonText
    db "@"

.TryDeposit
    ld a,[W_NUMINPARTY]
    dec a
    jr nz,.partyLargeEnough
    ld hl,.CantDepositLastMonText
    jp .Error
.partyLargeEnough
    ld a,[W_NUMINBOX]
    cp $14
    jr nz,.boxNotFull
    ld hl,.BoxFullText
    jp .Error
.boxNotFull
    ld a,[$cf91]
    call GetCryData
    call PlaySoundWaitForCurrent
    scf
    ret
.CantDepositLastMonText
    TX_FAR _CantDepositLastMonText
    db "@"
.BoxFullText
    TX_FAR _BoxFullText
    db "@"

.Error
    push hl
    ld a,$a5 ; Error
    call PlaySoundWaitForCurrent ; play sound
    pop hl
    call PrintText
    and a ; rcf
    ret

; ────────────────────────────────────────────────────────────────
; PRINT DAMAGE
; ────────────────────────────────────────────────────────────────

PrintBattleValueNearMon_:
    ld hl,wPrintBattleValueBit0
    bit 0,[hl]
    ret z
    call .GetHlPointerToTextArea
    push hl
    call .ClearScreenArea
    pop hl
    inc hl ; Sign Space
    ld de,wBattleValueToPrint
    ld bc,$0205 ; %00000010 | 05
    call PrintNumber
    call .PrintSign
    ; Initialize Counter
    ld b,12
    jr nz,.StoreCounter ; flag obtained in ".PrintSign"
    ld a,[$fff3] ; whose turn?
    and a
    ld a,[W_PLAYERMOVEEFFECT]
    jr z,.effect
    ld a,[W_ENEMYMOVEEFFECT]
.effect
    cp TWO_TO_FIVE_ATTACKS_EFFECT
    ld b,4
    jr z,.StoreCounter
    cp TRAPPING_EFFECT
    ld b,6
    jr z,.StoreCounter
    cp ATTACK_TWICE_EFFECT
    ld b,10
    jr z,.StoreCounter
    cp TWINEEDLE_EFFECT
    ld b,10
    jr z,.StoreCounter
    ld b,20
.StoreCounter
    ld hl,wBattleValueCounter
    ld [hl],b
    ret

.ClearScreenArea
    ld bc,$0106 ; 01 | 06
    jp ClearScreenArea

.GetHlPointerToTextArea
    bit 1,[hl] ; wFlagValueToPlayerBit1
    res 1,[hl] ; ...
    FuncCoord 06,04 ; Damage to Enemy
    ld hl,Coord
    ret z
    FuncCoord 03,05 ; Damage to Player
    ld hl,Coord
    ret

.CheckCure
    push hl
    ld hl,wFlagBattleCureBit7
    bit 7,[hl]
    res 7,[hl]
    pop hl
    ret

.PrintSign
    dec hl
    ld a,[hl]
    cp $7F ; Empty Space
    jr nz,.PrintSign
    call .CheckCure
    ld a,$D2 ; Plus Symbol
    jr nz,.SignDone
    ld a,$E3 ; Minus Symbol
.SignDone
    ld [hl],a
    ret

RemoveBattleValue_:
    ld hl,wPrintBattleValueBit0
    bit 0,[hl]
    res 0,[hl]
    ret z
    ld hl,wBattleValueCounter
.loop
    call Delay3
    ld a,[hl]
    and a
    jr z,.skip
    dec [hl]
    jr nz,.loop
.skip
    FuncCoord 00,04
    ld hl,Coord
    ld bc,$020C ; 02 | 12
    ld a,[W_BATTLETYPE]
    cp 2 ; safari?
    jr nz,.continue
    dec b
.continue
    jp ClearScreenArea

; ──────────────────────────────────────────────────────────────────────
; Type Effects
; ──────────────────────────────────────────────────────────────────────

TypeEffects:
; format: attacking type,defending type,damage multiplier
; the multiplier is a (decimal) fixed-point number:
;     20 is ×2.0
;     05 is ×0.5
;     00 is ×0

    INCLUDE "constants/type_effect.asm"
    db $FF

GetTypeEffects_:
    ld a,[$d11e]
    ld b,a
    ld hl,TypeEffects
    ld de,wBufferTypeEffects
.loop
    ld a,[hli]
    cp $FF
    jr z,.end
    cp b
    jr nz,.next
    ld [de],a
    inc de
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[hli]
    ld [de],a
    inc de
    jr .loop
.next
    inc hl
    inc hl
    jr .loop
.end
    ld [de],a ; $FF
    ret

; ──────────────────────────────────────────────────────────────────────
; PlayTrainerMusic
; ──────────────────────────────────────────────────────────────────────

PlayTrainerMusic_:
    xor a
    ld [wMusicHeaderPointer],a
    ld a,$ff
    call PlaySound      ; stop music
    ld a,BANK(Music_MeetEvilTrainer)
    ld [$c0ef],a
    ld [$c0f0],a
    ld a,[wEngagedTrainerSet] ; If Special Wild Play "Male Music"
    cp OPP_LVL_OFFSET         ; ...
    jr nc,.maleTrainer        ; ...
    ld a,[wEngagedTrainerClass]
    ld b,a
    ld hl,.EvilTrainerList
.evilTrainerListLoop
    ld a,[hli]
    cp $ff
    jr z,.noEvilTrainer
    cp b
    jr nz,.evilTrainerListLoop
    ld a,(Music_MeetEvilTrainer - $4000) / 3
    jr .PlaySound
.noEvilTrainer
    ld hl,.FemaleTrainerList
.femaleTrainerListLoop
    ld a,[hli]
    cp $ff
    jr z,.maleTrainer
    cp b
    jr nz,.femaleTrainerListLoop
    ld a,(Music_MeetFemaleTrainer - $4000) / 3
    jr .PlaySound
.maleTrainer
    ld a,(Music_MeetMaleTrainer - $4000) / 3
.PlaySound
    ld [$c0ee],a
    jp PlaySound
.FemaleTrainerList
    db LASS
    db JR__TRAINER_F
    db BEAUTY
    db COOLTRAINER_F
    db $FF
.EvilTrainerList
    db JUGGLER_X
    db GAMBLER
    db ROCKER
    db JUGGLER
    db CHIEF
    db SCIENTIST
    db GIOVANNI
    db ROCKET
    db $FF

; ──────────────────────────────────────────────────────────────────────
QuarterSpeedDueToParalysisOrHalveAttackDueToBurn_Down_:
; ──────────────────────────────────────────────────────────────────────

; These where probably added given that a stat-down move affecting speed or attack will override
; the stat penalties from paralysis and burn respectively.
; But they are always called regardless of the stat affected by the stat-down move.
    ;call QuarterSpeedDueToParalysis ; apply speed penalty to the player whose turn is not, if it's paralyzed
    ;jp HalveAttackDueToBurn ; apply attack penalty to the player whose turn is not, if it's burned
;joenote - now to fix this to properly apply the BRN and PAR stat penalties.
;In pokemon generation 1, stat-downs are always dealt to an opponent during the active pkmn's turn.
;So the penalty functions have the correct assumption that whoever is getting a stat-down is not their turn
;The correct function needs to be called depending on the stat-down being applied
    push de                               ; preserve de on the stack
    ld de,W_PLAYERMOVEEFFECT              ; get the player move effect
    ld a,[H_WHOSETURN]                    ; load the turn
    and a                                 ; check the turn
    jr z,.skip1                           ; if it is not the player's turn...
    ld de,W_ENEMYMOVEEFFECT               ; ...then it's the enemy's turn - load enemy move effect
.skip1
    ld a,[de]                             ; get the move effect into a
    cp ATTACK_DOWN1_EFFECT
    jr z,.skip_brn                        ; attack effect. skip to brn penalty
    cp ATTACK_DOWN2_EFFECT
    jr z,.skip_brn                        ; attack effect. skip to brn penalty
    cp ATTACK_DOWN_SIDE1_EFFECT
    jr z,.skip_brn                        ; attack effect. skip to brn penalty
    cp SPEED_DOWN1_EFFECT
    jr z,.skip_par                        ; speed effect. skip to par penalty.
    cp SPEED_DOWN2_EFFECT
    jr z,.skip_par                        ; speed effect. skip to par penalty.
    cp SPEED_DOWN_SIDE1_EFFECT
    jr z,.skip_par                        ; speed effect. skip to par penalty.
    jr .skip_end                          ; no attack or speed effect if at this line. skip to end.
.skip_brn
    BANKSWITCH HalveAttackDueToBurn       ; the non-active pkmn has a new recalculated attack. the active pkmn applies brn penalty to its opponent.
    jr .skip_end
.skip_par
    BANKSWITCH QuarterSpeedDueToParalysis ; the non-active pkmn has a new recalculated speed. the active pkmn applies par penalty to its opponent.
.skip_end
    pop de                                ; restore de from the stack
    ret                                   ; remember to return

; ──────────────────────────────────────────────────────────────────────
QuarterSpeedDueToParalysisOrHalveAttackDueToBurn_Up_:
; ──────────────────────────────────────────────────────────────────────

; these shouldn't be here
    ;call QuarterSpeedDueToParalysis ; apply speed penalty to the player whose turn is not, if it's paralyzed
    ;jp HalveAttackDueToBurn ; apply attack penalty to the player whose turn is not, if it's burned
;joenote - now to fix this to properly apply the BRN and PAR stat penalties.
;In pokemon generation 1, stat-ups are always dealt to a pkmn's self on its own turn.
;But the default penalty functions are written to apply penalties to the opponent of whoever's turn it is.
;So if speed or attack rises: invert H_WHOSETURN, call the appropriate function, when revert H_WHOSETURN.
;This make it so the penalties are applied to the self of whoever's turn it is.
;All that remains is to check which stat-up is applied and call the appropriate function.
    push de                               ; preserve de on the stack
    ld de,W_PLAYERMOVEEFFECT              ; get the player move effect
    ld a,[H_WHOSETURN]                    ; load the turn
    and a                                 ; check the turn
    jr z,.skip1                           ; if it is not the player's turn...
    ld de,W_ENEMYMOVEEFFECT               ; ...then it's the enemy's turn - load enemy move effect
.skip1
    xor $1                                ; invert the turn
    ld [H_WHOSETURN],a                    ; store the inverted turn
    ld a,[de]                             ; get the move effect into a
    cp ATTACK_UP1_EFFECT
    jr z,.skip_brn                        ; attack effect. skip to brn penalty
    cp ATTACK_UP2_EFFECT
    jr z,.skip_brn                        ; attack effect. skip to brn penalty
    cp ATTACK_UP3_EFFECT
    jr z,.skip_brn                        ; attack effect. skip to brn penalty
    cp SPEED_UP1_EFFECT
    jr z,.skip_par                        ; speed effect. skip to par penalty.
    cp SPEED_UP2_EFFECT
    jr z,.skip_par                        ; speed effect. skip to par penalty.
    cp SPEED_UP3_EFFECT
    jr z,.skip_par                        ; speed effect. skip to par penalty.
    jr .skip_end                          ; no attack or speed effect if at this line. skip to end.
.skip_brn
    BANKSWITCH HalveAttackDueToBurn       ; the active pkmn has a new recalculated attack. the non-active pkmn applies brn penalty to its opponent.
    jr .skip_end
.skip_par
    BANKSWITCH QuarterSpeedDueToParalysis ; the active pkmn has a new recalculated speed. the non-active pkmn applies par penalty to its opponent.
.skip_end
    ld a,[H_WHOSETURN]                    ; load the inverted turn
    xor $1                                ; revert the turn back to normal
    ld [H_WHOSETURN],a                    ; store the normal turn
    pop de                                ; restore de from the stack
    ret                                   ; remember to return

; ──────────────────────────────────────────────────────────────────────
; CalcEXPBarPixelLength_
; ──────────────────────────────────────────────────────────────────────

CalcEXPBarPixelLength_:
; get the base exp needed for the current level
    ld a,[W_PLAYERBATTSTATUS3]
    ld hl,W_PLAYERMONID
    bit 3,a
    jr z,.skip
    ld hl,W_PARTYMON1_NUM
    call BattleMonPartyAttr
.skip
    ld a,[hl]
    ld [$d0b5],a
    ld hl,W_PARTYMON1_MOVE2PP ; move2pp
    call BattleMonPartyAttr
    ld a,[hl]
    ld [wAlternateFormIndex],a
    call GetMonHeader
    ld a,[W_PLAYERMONLEVEL]
    call CalcEXPBarPixelLength_.Start

    ; get the exp needed to gain a level
    ld a,[W_PLAYERMONLEVEL]
    call GetTheExpNeededToGainALevel

    ; get the address of the active Pokemon's current experience
    ld hl,W_PARTYMON1_EXP
    call BattleMonPartyAttr

CalcEXPBarPixelLength_.Common:

    ; current exp - base exp
    ld b,h
    ld c,l
    ld hl,wEXPBarBaseEXP
    ld de,wEXPBarCurEXP
    call SubThreeByteNum

    ; exp needed - base exp
    ld bc,H_MULTIPLICAND
    ld hl,wEXPBarBaseEXP
    ld de,wEXPBarNeededEXP
    call SubThreeByteNum

    ; make the divisor an 8-bit number
    ld hl,wEXPBarNeededEXP
    ld de,wEXPBarCurEXP + 1
    ld a,[hli]
    and a
    jr z,.twoBytes
    ld a,[hli]
    ld [hld],a
    dec hl
    ld a,[hli]
    ld [hld],a
    ld a,[de]
    inc de
    ld [de],a
    dec de
    dec de
    ld a,[de]
    inc de
    ld [de],a
    dec de
    xor a
    ld [hli],a
    ld [de],a
    inc de
.twoBytes
    ld a,[hl]
    and a
    jr z,.oneByte
    srl a
    ld [hli],a
    ld a,[hl]
    rr a
    ld [hld],a
    ld a,[de]
    srl a
    ld [de],a
    inc de
    ld a,[de]
    rr a
    ld [de],a
    dec de
    jr .twoBytes
.oneByte

    ; current exp * (8 tiles * 8 pixels)
    ld hl,H_MULTIPLICAND
    ld de,wEXPBarCurEXP
    ld a,[de]
    inc de
    ld [hli],a
    ld a,[de]
    inc de
    ld [hli],a
    ld a,[de]
    ld [hl],a
    ld a,$40
    ld [H_MULTIPLIER],a
    call Multiply

    ; product / needed exp = pixel length
    ld a,[wEXPBarNeededEXP + 2]
    ld [H_DIVISOR],a
    ld b,$04
    call Divide
    ret

CalcEXPBarPixelLength_.Start:
    ld d,a
    BANKSWITCH CalcExperience
    ld hl,H_MULTIPLICAND
    ld de,wEXPBarBaseEXP
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[hli]
    ld [de],a
    inc de
    ld a,[hl]
    ld [de],a
    ret

GetTheExpNeededToGainALevel:
    ; get the exp needed to gain a level
    ld d,a
    inc d
    BANKSWITCH_JUMP CalcExperience

; calculates the three byte number starting at [bc]
; minus the three byte number starting at [hl]
; and stores it into the three bytes starting at [de]
; assumes that [hl] is smaller than [bc]
SubThreeByteNum:
    call .subByte
    call .subByte
.subByte
    ld a,[bc]
    inc bc
    sub [hl]
    inc hl
    ld [de],a
    jr nc,.noCarry
    dec de
    ld a,[de]
    dec a
    ld [de],a
    inc de
.noCarry
    inc de
    ret

; return the address of the BattleMon's party struct attribute in hl
BattleMonPartyAttr:
    ld a,[wPlayerMonNumber]
    ld bc,W_PARTYMON2DATA - W_PARTYMON1DATA
    jp AddNTimes

; ──────────────────────────────────────────────────────────────────────
; SpecialTrainerAlternateForm
; ──────────────────────────────────────────────────────────────────────

SpecialTrainerAlternateForm:
    ld a,[W_CUROPPONENT]
    cp SONY2
    jr nz,.skip1
    ld a,SONY1
.skip1
    cp SONY3
    jr nz,.skip2
    ld a,SONY1
.skip2
    ld b,a
    ld a,[$cf91]
    ld c,a
    ld a,[$FF00+$e4] ; NewPartyLength
    ld e,a
    ld hl,.CustomTrainer
.loop
    ld a,[hli]
    cp $FF
    jr z,.NotFound
    cp b
    jr nz,.next3
    ld a,[hli]
    cp c
    jr nz,.next2
    ld a,[hli]
    and a
    jr z,.found
    cp e
    jr nz,.next1
.found
    ld a,[hl]
    ld d,a
    ret
.next3
    inc hl
.next2
    inc hl
.next1
    inc hl
    jr .loop
.NotFound
    ld d,0
    ret

.CustomTrainer

    ; Green1
    db SONY1,SQUIRTLE,0,$01
    db SONY1,WARTORTLE,0,$01
    db SONY1,BLASTOISE,0,$01
    db SONY1,BULBASAUR,0,$01
    db SONY1,IVYSAUR,0,$01
    db SONY1,VENUSAUR,0,$01
    db SONY1,CHARMANDER,0,$01
    db SONY1,CHARMELEON,0,$01
    db SONY1,CHARIZARD,0,$01

    ; Bruno
    db BRUNO,ONIX,6,$01

    ; Agatha
    db AGATHA,MAROWAK,6,$01

    ; Lorelei
    db LORELEI,NINETALES,6,$01

    ; Lance
    db LANCE,AERODACTYL,6,$01

    db $FF

; ──────────────────────────────────────────────────────────────────────
; GenerateRandomEnemyTrainerIV_
; ──────────────────────────────────────────────────────────────────────

GenerateRandomEnemyTrainerIV_:

    call .HandleCustomTrainer
    ret c

.Random
    call .GetTrainerMinMaxValue

    ; Generate Random IV
    call GenRandom
    push af
    push af
    call GenRandom
    push af
    push af

    ; Read random IVs Atk
    ld a,[wTempEnemyMinMaxIVAtk]
    ld [wTempEnemyMinMaxIV],a
    pop af
    swap a
    call .BalanceValue
    ld b,a ; b = Atk

    ; Read random IVs Def
    ld a,[wTempEnemyMinMaxIVDef]
    ld [wTempEnemyMinMaxIV],a
    pop af
    call .BalanceValue
    ld c,a ; c = Def

    ; Read random IVs Spd
    ld a,[wTempEnemyMinMaxIVSpd]
    ld [wTempEnemyMinMaxIV],a
    pop af
    swap a
    call .BalanceValue
    ld d,a ; d = Spd

    ; Read random IVs Spc
    ld a,[wTempEnemyMinMaxIVSpc]
    ld [wTempEnemyMinMaxIV],a
    pop af
    call .BalanceValue
    ld e,a ; e = Spc

    ; combine bc|de (Atk/Def|Spd/Spc) to (c|b)
    ld a,b
    swap a
    add c
    ld b,a ; b = Atk/Def
    ld a,d
    swap a
    add e
    ld e,a ; e = Spd/Spc
    ld d,b ; d = Atk/Def

.End
    ret

.GetTrainerMinMaxValue
    ld hl,.TrainerMinMaxValueTable
    ld a,[W_CUROPPONENT] ; $d059
    dec a ; sub $C9 ; Convert Generic Id to Trainer ID
    add a ; x2
    add a ; x4
    ld e,a
    ld d,0
    jr nc,.noCarry
    inc d
.noCarry
    add hl,de
    ld de,wTempEnemyMinMaxIVAtk
    call .Read ; wTempEnemyMinMaxIVAtk
    call .Read ; wTempEnemyMinMaxIVDef
    call .Read ; wTempEnemyMinMaxIVSpd
    call .Read ; wTempEnemyMinMaxIVSpc
    ret
.Read
    ld a,[hli]
    ld [de],a
    inc de
    ret

; ARROTONDA.DIFETTO.MAT((MAX-MIN)*RND/15+MIN)
; a = RND
; [wTempEnemyMinMaxIV] = MIN|MAX
.BalanceValue
    push bc
    push de
    and %00001111 ; LSB
    push af ; Backup RND
    call .GetMIN
    ld b,a ; b = MIN
    call .GetMAX ; a = MAX
    sub b ; a = (MAX-MIN)
    cp 15
    jr z,.NotNeedBalance
    ld [H_MULTIPLIER],a     ; (MAX-MIN)
    xor a
    ld [H_MULTIPLICAND+1],a ; 0
    ld [H_MULTIPLICAND],a   ; 0
    pop af ; Restore RND
    ld [H_MULTIPLICAND+2],a ; RND
    call Multiply ; (MAX-MIN)*RND
    ld a,15
    ld [H_DIVISOR],a
    ld b,4 ; 4 bytes
    call Divide ; (MAX-MIN)*RND/15
    ld a,[H_MULTIPLICAND+2] ; a = (MAX-MIN)*RND/15
    ld b,a
    call .GetMIN ; a = MIN
    add b ; a = (MAX-MIN)*RND/15+MIN
    pop de
    pop bc
    ret
.NotNeedBalance
    pop af ; Restore RND
    pop de
    pop bc
    ret
.GetMIN
    ld a,[wTempEnemyMinMaxIV]
    swap a
    and %00001111
    ret
.GetMAX
    ld a,[wTempEnemyMinMaxIV]
    and %00001111
    ret

; db $MinMaxAtk,$MinMaxDef,....
.TrainerMinMaxValueTable
    db $0F,$0F,$0F,$0F ; dw $0000 ; YOUNGSTER     ; $01 ; (08*01*01*01)/(16^4)*100 = 0.012%
    db $0F,$0F,$0F,$0F ; dw $0000 ; BUG_CATCHER   ; $02 ; (08*01*01*01)/(16^4)*100 = 0.012%
