    db $0F,$0F,$0F,$AF ; dw $988A ; JUGGLER_X     ; $0D ; (08*01*01*03)/(16^4)*100 = 0.037%
    db $2F,$0F,$0F,$6F ; dw $9828 ; FISHER        ; $0E ; (09*01*01*02)/(16^4)*100 = 0.027%
