    and a
    jr z,.outOfBattle
    cp 2
    jr z,.TrainerBattle
.WildBattle
    call .CheckGhostMarowak
    jr z,.AltForm1
    call .CheckPalletPikachu
    jr z,.AltForm1
    call .CheckPewterEevee
    jr z,.AltForm1
    ; ft
.WildStandard
    xor a ; ~TODO
    jr .end
.AltForm1
    ld a,1
    ld [wTempAlternateFormIndex],a
    jr .end
.outOfBattle
    ld a,[wTempAlternateFormIndex]
    jr .end
.TrainerBattle
    ld hl,wEnemyMon1+(W_PARTYMON1_MOVE2PP-W_PARTYMON1_NUM) ; move2pp
    ld a,[wWhichPokemon]
    ld bc,44
    call AddNTimes
    ld a,[hl]
.end
    ld [wAlternateFormIndex],a
    ret
.CheckGhostMarowak
