PlayerBideAccum_:
    ld hl,W_PLAYERBATTSTATUS1
    bit 0,[hl] ; is mon using bide?
    ret z
    xor a
    ld [W_PLAYERMOVENUM],a
    ld hl,W_DAMAGE
    ld a,[hli]
    ld b,a
    ld c,[hl]
    ld hl,$d074 + 1 ; PlayerBideAccumulatedDamage
    ld a,[hl]
    add c ; accumulate damage taken
    ld [hld],a
    ld a,[hl]
    adc b
    ld [hl],a
    ret

EnemyBideAccum_:
    ld hl,W_ENEMYBATTSTATUS1
    bit 0,[hl] ; is mon using bide?
    ret z
    xor a
    ld [W_ENEMYMOVENUM],a
    ld hl,W_DAMAGE
    ld a,[hli]
    ld b,a
    ld c,[hl]
    ld hl,$cd05 + 1 ; EnemyBideAccumulatedDamage
    ld a,[hl]
    add c ; accumulate damage taken
    ld [hld],a
    ld a,[hl]
    adc b
    ld [hl],a
    ret

