_LoadBattlePokedex:
    ld hl,wForceShowPokedexBit5 ; wSkipTextInPokedexBit7
    bit 5,[hl]
    jr z,.end
    ld a,[$d74b]
    bit 5,a ; does the player have the pokedex?
    jr z,.end
    call IsGhostBattle
    jr z,.end
    bit 7,[hl]
    ld hl,.LoadPokedexText
    call z,PrintText
    ld a,[W_ENEMYMONID]
    ld [$d11e],a
    PREDEF ShowPokedexData
    call .LoadMonFrontSprite
    call CleanLCD_OAM
    call GBPalWhiteOut
    BANKSWITCH LoadHudAndHpBarAndStatusTilePatterns
    call LoadScreenTilesFromBuffer1
    call GoPAL_SET_CF1C
    call GBPalNormal
    ld c,25
    call DelayFrames
.end
    ld hl,wForceShowPokedexBit5 ; wSkipTextInPokedexBit7
    res 5,[hl]
    res 7,[hl]
    ret
.LoadMonFrontSprite
    ld a,[W_ENEMYBATTSTATUS2]
    bit 4,a
    BANKSWITCH_JUMP_NZ AnimationSubstitute
    ld a,[W_ENEMYMON_START]
    ld [$d0b5],a
    ld a,[W_ENEMYMONALTFORM]
    ld [wAlternateFormIndex],a ; Save AlternateFormIndex
    call GetMonHeader
    ld de,$9000
    jp LoadMonFrontSprite
.LoadPokedexText
    TX_FAR _ItemUseBallText06
    db $13,$06
    db "@"

