    ld b,$0
    call GoPAL_SET
    ld hl,.PlayerBlackedOutText2
    ld a,[W_ISLINKBATTLE] ; $d12b
    cp $4
    jr nz,.noLinkBattle
    ld hl,.LinkBattleLostText
.noLinkBattle
    call PrintText
    ld a,[$d732]
    res 5,a
    ld [$d732],a
    call ClearScreen
    scf
    ret
