AdjustDamageForMoveType_GetInput:
; values for player turn
    ld a,[H_WHOSETURN]
    and a
    jr nz,.ValuesForEnemyTurn

.ValuesForPlayerTurn
    ld a,[W_PLAYERMOVETYPE]
    ld [$d11e],a
    and a ; TYPE_NA?
    push af
    ld a,[W_PLAYERMONID]
    ld b,a
    ld a,[W_PLAYERMOVENUM]
    ld c,a
    ld hl,W_PLAYERMONTYPES
    call GetAttackerType
    ld a,[W_ENEMYMON_START]
    ld b,a
    ld hl,W_ENEMYMONTYPES
    call GetDefenderType
    pop af
    ret

.ValuesForEnemyTurn
    ld a,[W_ENEMYMOVETYPE]
    ld [$d11e],a
    and a ; TYPE_NA?
    push af
    ld a,[W_ENEMYMON_START]
    ld b,a
    ld a,[W_ENEMYMOVENUM]
    ld c,a
    ld hl,W_ENEMYMONTYPES
    call GetAttackerType
    ld a,[W_PLAYERMONID]
    ld b,a
    ld hl,W_PLAYERMONTYPES
    call GetDefenderType
    pop af
    ret

