; Input
; [$d11e] = Attacker Move Type
; [hl/hl+1] = Attacker Mon Types
; b = Attacker Mon ID
; c = Attacker Move ID
; Output
; [wTmpAttackerTypes] = types of attacker
GetAttackerType_:
    call Load16BitRegisters
GetAttackerType:
    push hl ; Backup Attacker Mon Types
    ld a,[$d11e]
    cp IVORY
    jr z,.TryToForceIvory
    ld hl,.CustomForceMoveTable
.loop
    ld a,[hli]
    cp $FF
    jr z,.done
    ld e,a
    ld a,[hli]
    ld d,a
    push hl
    ld h,d ; hl = Pointer to Move List
    ld l,e ; ...
    ld a,c ; a = Move ID
    call .IsInArray
    pop hl
    jr nc,.next1
    ld a,[hli]
    ld e,a
    ld a,[hli]
    ld d,a
    push hl
    ld h,d ; hl = Pointer to Mon List
    ld l,e ; ...
    ld a,b ; a = Mon ID
    call .IsInArray
    pop hl
    jr nc,.next2
    ; ft
.Custom
    pop hl ; Restore Attacker Mon Types
    ld a,[$d11e]
    ld hl,wTmpAttackerTypes
    ld [hli],a
    ld [hli],a
    ld [hli],a
    ld [hl],a
    ret
.next1
    inc hl
    inc hl
.next2
    jr .loop
.done
    ; ft
.Standard
    pop hl ; Restore Attacker Mon Types
    ld de,wTmpAttackerTypes
    ld bc,4
    jp CopyData

.CustomForceMoveTable
    dw .SlashMoveTable     , .SlashMonTable
    dw .ExplosionMoveTable , .ExplosionMonTable
    dw .QuickMoveTable     , .QuickMonTable
    dw .TriAttMoveTable    , .TriAttMonTable
    dw .EggMoveTable       , .EggMonTable
    dw .SkullMoveTable     , .SkullMonTable
    dw .StompMoveTable     , .StompMonTable
    dw .HeadButtMoveTable  , .HeadButtMonTable
    dw .HyperBeamMoveTable , .HyperBeamMonTable
    dw .RageMoveTable      , .RageMonTable
    dw .LickMoveTable      , .LickMonTable
    dw .SwiftMoveTable     , .SwiftMonTable
    dw .PinMissMoveTable   , .PinMissMonTable
    dw .BladeMoveTable     , .BladeMonTable
    db $FF

.TryToForceIvory
    ld a,b ; a = Mon ID
    ld hl,.ForceIvoryTable
    call .IsInArray
    jr nc,.Standard
    jr .Custom

.IsInArray
    push bc
    ld de,1
    call IsInArray
    pop bc
    ret

