; Swap pointer bytes, than first byte cannot be 0
dl: MACRO
    dw ((\1 % $100) << 8) | (\1 / $100)
ENDM

PokemonBaseStats:
INCLUDE "constants/pokemon_header.asm"
INCLUDE "constants/pokemon_header_alternate_forms.asm"
