; ──────────────────────────────────────────────────────────────────────

_GetEvos:
    call Load16BitRegisters ; Input de
    push de
    ld hl,W_MONHLEARNSETPOINTER ; pointer to learnset
    ld a,[hli]
    ld h,[hl]
    ld l,a
.loop
    ld a,[hli]
    and a
    jr z,.end
    ld [de],a
    inc de
    jr .loop
.end
    ld [de],a
    pop hl
    ret

; Input de = Buffer Pointer
;       b  = Mon Level
GetMoves:
    call Load16BitRegisters
    ld a,[$d11e] ; Backup
    push af      ; ...
    ld a,b ; Mon Level
    ld [$d11e],a
    ld hl,W_MONHLEARNSETPOINTER ; pointer to learnset
    ld a,[hli]
    ld h,[hl]
    ld l,a
.skipEvoEntriesLoop
    ld a,[hli]
    and a
    jr nz,.skipEvoEntriesLoop
.Loop1
    ld a,[hl]
    and a
    jr z,.EndLoop1
    push hl
    ld a,[hli]
    ld l,[hl]
    ld h,a
.Loop2
    ld a,[hli]
    and a
    jr z,.EndLoop2
    ld b,a ; b = Move Level
    ld a,[hli]
    ld c,a ; c = Move ID
    call CheckSkillInList
    call nz,IsSkill
    jr c,.Loop2
    ld a,[$d11e] ; Mon Level
    cp b
    jr c,.EndAllLoop ; end if next move level is too high
    ld a,c
    ld [de],a
    inc de
    push hl
    ld hl,wMaxNotExclMoveSlotId
    inc [hl]
    pop hl
    jr .Loop2
.EndLoop2
    pop hl
    inc hl
    inc hl
    jr .Loop1
.EndLoop1
    xor a     ; 0 = end learnset
    ld [de],a ; ...
    pop af       ; Restore
    ld [$d11e],a ; ...
    ret
.EndAllLoop
    pop hl
    jr .EndLoop1

; ──────────────────────────────────────────────────────────────────────

GetMonSkill:
    xor a ; player party
    ld [$cc49],a
    call LoadMonData
    ld a,[$cfb9] ; Level
    ld b,a       ; ...
    PREDEF GetMonPotentialMoveList
    call .FillMemory
    ld de,wSkill
    ld c,1 ; skill sort
    ld b,0
    ld hl,.SkillConfigTable
.loop
    ld a,[hli]
    cp $FF
    jr z,.EndLoop
    ld [$d0e0],a ; Move to Search
    push hl
    call .CheckSkill
    call nz,.CheckMonAlreadyKnowSkill
    pop hl
    inc hl
    inc hl
    inc hl
    inc c
    jr .loop
.EndLoop
    ld a,b ; num of founded skill
    ld [wNumSkill],a ; store num of founded skill in wNumSkill
    ret

.CheckSkill
    push de
    push bc
    ld a,[hli]
    ld e,a
    ld a,[hli]
    ld d,a
    or e
    jr z,.CheckSkill_Success ; Both pointer Byte zero
    ld c,[hl] ; c = Skill Bit
    ld h,d
    ld l,e ; [hl] = Skill Byte
    ld b,2
    PREDEF HandleBitArray
    ld a,c
    and a
.CheckSkill_End
    pop bc
    pop de
    ret
.CheckSkill_Success
    ld a,1
    or a ; reset all flag
    jr .CheckSkill_End

.SkillConfigTable
    SCT Skill__FLY      , FLY_FLAG_BYTE      , FLY_FLAG_BIT
    SCT TELEPORT        , TELEPORT_FLAG_BYTE , TELEPORT_FLAG_BIT
    SCT Skill__DIG      , DIG_FLAG_BYTE      , DIG_FLAG_BIT
    SCT Skill__CUT      , CUT_FLAG_BYTE      , CUT_FLAG_BIT
    SCT Skill__FLOAT    , FLOAT_FLAG_BYTE    , FLOAT_FLAG_BIT
    SCT Skill__STRENGTH , STRENGTH_FLAG_BYTE , STRENGTH_FLAG_BIT
    SCT Skill__LIGHT    , LIGHT_FLAG_BYTE    , LIGHT_FLAG_BIT
    SCT Skill__HEAL     , HEAL_FLAG_BYTE     , HEAL_FLAG_BIT
    db $FF

.FillMemory
    xor a
    ld [wNumSkill],a
    ld hl,wSkill
    ld bc,8+1
    jp FillMemory

.CheckMonAlreadyKnowSkill
    push de
    push bc
    BANKSWITCH CheckMonAlreadyKnowMoveQuick
    pop bc
    pop de
    ret nc
    inc b ; num of founded skill
    ld a,c ; skill sort
    ld [de],a ; store skill id in wSkill vector
    inc de
    ret

