GetMapHeaderPointers:
    ld hl,MapHeaderPointers
    call CheckNewAdventureFlag
    ret z
    ld hl,MapHeaderPointersNew
    ret

GetPointerToBaseOfMapHeader:
    call GetMapHeaderPointers ; ld hl,MapHeaderPointers
    ld a,[W_CURMAP]
    sla a
    jr nc,.noCarry1
    inc h
.noCarry1
    add l
    ld l,a
    jr nc,.noCarry2
    inc h
.noCarry2
    ld a,[hli]
    ld h,[hl]
    ld l,a ; hl = base of map header
    ret

