PortRoyal_h:
    db $00 ; tileset
    db PORT_ROYAL_HEIGHT,PORT_ROYAL_WIDTH ; dimensions
    dw PortRoyalBlocks,PortRoyalTextPointers,PortRoyalScript
    db EAST ; connections
    EAST_MAP_CONNECTION ROUTE_D1,ROUTE_D1_WIDTH,0,0,ROUTE_D1_HEIGHT,RouteD1Blocks,PORT_ROYAL_WIDTH
    dw PortRoyalObject

PortRoyalObject:
    db $f ; border tile

    db 2 ; warps
    db 05,05,0,PORT_ROYAL_POKECENTER
    db 05,09,0,PORT_ROYAL_MART

    db 2 ; signs
    db 05,06,3 ; PokeCenterSignText
    db 05,10,4 ; MartSignText


    db $2 ; people
    db SPRITE_LASS,08 + 4,03 + 4,$fe,$00,$00+1 ; person
    db SPRITE_BALL,10 + 4,05 + 4,$ff,$ff,$80+2,RARE_CANDY ; item

    ; warp-to
    EVENT_DISP PORT_ROYAL_WIDTH,05,05 ; PORT_ROYAL_POKECENTER
    EVENT_DISP PORT_ROYAL_WIDTH,05,09 ; PORT_ROYAL_MART

PortRoyalBlocks:
    INCBIN "maps/portroyal.blk"

PortRoyalTextPointers:
    dw PortRoyalText1
    dw PickupItemText
    dw PokeCenterSignText
    dw MartSignText

PortRoyalText1:
    TX_FAR _PortRoyalText1
    db "@"

_PortRoyalText1:
    db $08 ; asm
    ld hl,$d803
    bit 2,[hl]
    res 2,[hl]
    ld hl,.ShipReturnedText
    jr nz,.done
    ld hl,.LikeShipText
.done
    call PrintText
    jp TextScriptEnd
.ShipReturnedText
    TX_FAR _ShipReturned
    db "@"
.LikeShipText
    TX_FAR _LikeShipText
    db "@"

PortRoyalScript:
    jp EnableAutoTextBoxDrawing

