SwapMap_h:
    db $10 ; tileset
    db SWAP_MAP_1_HEIGHT,SWAP_MAP_1_WIDTH ; dimensions
    dw SwapMapBlocks,SwapMapTextPointers,SwapMapScript ; blocks,texts,scripts
    db 0 ; connections
    dw SwapMapObject

SwapMapBlocks:
    INCBIN "maps/swapmap.blk"

SwapMapObject:
    db $d ; border tile

    db 2 ; warp
    db 00,07,1,$FF
    db 08,09,2,BILLS_HOUSE

    db 0 ; sign

    db 0 ; people

    ; warp-to
    EVENT_DISP SWAP_MAP_1_WIDTH,00,07
    EVENT_DISP SWAP_MAP_1_WIDTH,08,09

SwapMapTextPointers:
    db "@"

SwapMapScript:
    ld hl,.OldCoord
    call ArePlayerCoordsInArray
    jr c,.old
    ld hl,.NewCoord
    call ArePlayerCoordsInArray
    jr c,.new
    ret
.old
    xor a
    ld [wAdventureMap],a
    ld a,ROUTE_25
    ld [wLastMap],a
    ret
.new
    ld a,1
    ld [wAdventureMap],a
    ld a,ROUTE_D1
    ld [wLastMap],a
    ret
.OldCoord
    db 07,08
    db 07,09
    db 07,10
    db 08,08
    db 08,09
    db 08,10
    db 09,08
    db 09,09
    db 09,10
    db $FF
.NewCoord
    db 01,06
    db 01,07
    db 01,08
    db 02,07
    db $FF

