TestMap1_h:
    db $11 ; tileset
    db TEST_MAP_1_HEIGHT,TEST_MAP_1_WIDTH ; dimensions
    dw TestMap1Blocks,TestMap1TextPointers,TestMap1Script ; blocks,texts,scripts
    db 0 ; connections
    dw TestMap1Object
TestMap1Object:
    db $3 ; border tile

    db 3 ; warp
    db 29,06,0,$FF
    db 29,07,0,$FF
    db 01,01,0,TEST_MAP_2

    db 0 ; sign

    db 6 ; people
    db SPRITE_BOULDER,04 + 4,19 + 4,$ff,$10,1 ; person
    db SPRITE_BOULDER,17 + 4,04 + 4,$ff,$10,2 ; person
    db SPRITE_BOULDER,23 + 4,01 + 4,$ff,$10,3 ; person
    db SPRITE_BOULDER,27 + 4,06 + 4,$ff,$10,4 ; person
    db SPRITE_BOULDER,01 + 4,27 + 4,$ff,$10,5 ; person
    db SPRITE_BOULDER,06 + 4,06 + 4,$ff,$10,6 ; person

    ; warp-to
    EVENT_DISP TEST_MAP_1_WIDTH,29,06
    EVENT_DISP TEST_MAP_1_WIDTH,29,07
    EVENT_DISP TEST_MAP_1_WIDTH,01,01

TestMap1TextPointers:
    dw BoulderText
    dw BoulderText
    dw BoulderText
    dw BoulderText
    dw BoulderText
    dw BoulderText

TestMap1Script:
    call EnableAutoTextBoxDrawing
    call RemoveHiddenBoulderFromScreen
    jp TestMap1HoleAndBoulderScript

RemoveHiddenBoulderFromScreen:
    ld hl,$d126
    bit 6,[hl]
    res 6,[hl]
    ret z
    ld c,-1
.loop
    inc c
    ld a,c
    cp 4
    ret z
    push bc

    ; Check Current Boulder
    add 1 ; Hidden Object of this Map start at "1"
    ld c,a
    ld b,2
    ld hl,W_MISSABLEOBJECTFLAGS_NEW
    PREDEF HandleBitArray
    ld a,c
    and a

    pop bc
    call nz,.remove

    jr .loop
.remove
    push bc
    ld a,c
    ld hl,$c215 ; first sprite position
    ld bc,16
    call AddNTimes
    ld [hl],$A0
    pop bc
    ret

TestMap1HoleAndBoulderScript:
    ld a,[$d736]
    bit 6,a ; jump hole
    ret nz
    ld hl,.Coord
    call ArePlayerCoordsInArray
    jr nc,.CheckBoulder

    ; Check Player
    FuncCoord 8,9 ; tile the player is on
    ld a,[Coord]
    cp TILE_11_CAV_HOLE
    call nz,RevealHoleCoord
.FallInHole
    ; Start Warp
    ld a,[$cd3d] ; Warp ID
    ld [$d71e],a
    ld hl,$d72d
    set 4,[hl]
    ld hl,$d732
    set 4,[hl]
    ld a,TEST_MAP_2
    ld [$d71d],a
    xor a
    ld [wJoypadForbiddenButtonsMask],a ; Enable Joy
    ret

.Coord
    db 28,01
    db 28,02
    db 21,04
    db 02,29
    db 25,02
    db 23,03
    db 28,25
    db $FF

    ; Check Boulder
.CheckBoulder
    ld hl,wFlags_0xcd60
    bit 7,[hl]
    res 7,[hl]
    ret z
    ld hl,.Coord
    call CheckBoulderCoords
    ret nc

    ; Reveal Hidden Hole Under Boulder?
    ld a,[$cd3d] ; Get Coord Occurrency
    ld [wWhichTrade],a
    PREDEF GetTileTwoStepsInFrontOfPlayer
    ld a,[$d71c] ; Tile Hole or Hidden Hole
    cp TILE_11_CAV_HOLE
    jr z,.skipRevealHole
    call Delay3
    call RevealHoleCoord
    call Delay3
.skipRevealHole

    ; Hide Boulder
    ld a,[$ff00+$8c]
    dec a
    add 1 ; Hidden Object of this Map start at "1"
    ld [$cc4d],a
    PREDEF RemoveMissableObject

    ; Remove Hidden Boulder from Screen
    ld hl,$c215 ; first sprite position
    ld a,[$ff00+$8c]
    dec a
    ld bc,16
    call AddNTimes
    ld [hl],$A0
    ret

RevealHoleA:
    call GetDirectionOffset
    call GetTileOffset
    cp TILE_11_CAV_HOLE
    ret z
    ld a,[$cd3f]
    jr RevealHoleCommon

RevealHoleCoord:
    ld a,[wWhichTrade]
    dec a
RevealHoleCommon:
    ld bc,3
    ld hl,.Table
    call AddNTimes
    ld a,[hli]
    ld b,a ; Y
    ld a,[hli]
    ld c,a ; X
    ld a,[hli]
    ld [$d09f],a; ID
    PREDEF ReplaceTileBlock
    ld a,$ac
    call PlaySound
    FuncCoord 8,9 ; tile the player is on
    ld a,[Coord]
    cp TILE_11_CAV_HOLE
    ret nz
    ld a,$FF
    ld [wJoypadForbiddenButtonsMask],a ; Disable Joy
    call Delay3
    ; EmotionBubble
    ld hl,$cd4f
    xor a
    ld [hli],a
    ld [hl],a
    PREDEF EmotionBubble
    jp Delay3
.Table
   ;db YY,XX,$ID
    db 14,00,$78
    db 14,01,$77
    db 10,02,$68
    db 01,14,$78

TestMap1Blocks:
    INCBIN "maps/devmap1.blk"

