SECTION "Bank3d",ROMX,BANK[$3D]

; ──────────────────────────────────────────────────────────────────────

EmotionBubbles:
    INCBIN "gfx/emotion_bubbles.2bpp"

TreeOAM:
    INCBIN "gfx/denim/tree.2bpp"

; ──────────────────────────────────────────────────────────────────────

ReadTrainer:

; don't change any moves in a link battle
    ld a,[W_ISLINKBATTLE]
    and a
    ret nz

; set [wEnemyPartyCount] to 0,[$D89D] to FF
; XXX first is total enemy pokemon?
; XXX second is species of first pokemon?
    ld hl,wEnemyPartyCount
    xor a
    ld [hli],a
    dec a
    ld [hl],a

; get the pointer to trainer data for this class
    ld a,[W_TRAINERCLASS]
    dec a
    add a,a
    ld hl,TrainerDataPointers
    ld c,a
    ld b,0
    add hl,bc ; hl points to trainer class
    ld a,[hli]
    ld h,[hl]
    ld l,a
    ld a,[W_TRAINERNO]
    ld b,a
; At this point b contains the trainer number,
; and hl points to the trainer class.
; Our next task is to iterate through the trainers,
; decrementing b each time,until we get to the right one.
.outer
    dec b
    jr z,.IterateTrainer
.inner
    ld a,[hli]
    and a
    jr nz,.inner
    jr .outer

; if the first byte of trainer data is FF,
; - each pokemon has a specific level
;      (as opposed to the whole team being of the same level)
; - if [W_LONEATTACKNO] != 0,one pokemon on the team has a special move (not applicable to the Yellow method)
; else the first byte is the level of every pokemon on the team
.IterateTrainer
    ld a,[hli]
    cp $FF ; is the trainer special?
    jr z,.SpecialTrainer ; if so,check for special moves
    ld [W_CURENEMYLVL],a
.LoopTrainerData
    ld a,[hli]
    and a ; have we reached the end of the trainer data?
    jr z,.AddAdditionalMoveData ; jr z,.FinishUp
    ld [$CF91],a ; write species somewhere (XXX why?)
    ld a,1
    ld [$CC49],a
    push hl
    call AddPokemonToParty
    pop hl
    jr .LoopTrainerData
.SpecialTrainer
; if this code is being run:
; - each pokemon has a specific level
;      (as opposed to the whole team being of the same level)
; - if [W_LONEATTACKNO] != 0,one pokemon on the team has a special move (not applicable to the Yellow method)
    ld a,[hli]
    and a ; have we reached the end of the trainer data?
    jr z,.AddAdditionalMoveData ; jr z,.AddLoneMove
    ld [W_CURENEMYLVL],a
    ld a,[hli]
    ld [$CF91],a
    ld a,1
    ld [$CC49],a
    push hl
    call AddPokemonToParty
    pop hl
    jr .SpecialTrainer
.AddAdditionalMoveData
; does the trainer have additional move data?
    ld a,[W_TRAINERCLASS]
    ld b,a
    ld a,[W_TRAINERNO]
    ld c,a
    ld hl,SpecialTrainerMoves
.loopAdditionalMoveData
    ld a,[hli]
    cp $ff
    jr z,.FinishUp
    cp b
    jr nz,.NextSpecialTrainer1
    ld a,[hli]
    cp c
    jr nz,.NextSpecialTrainer2
    ld a,[hli]
    ld d,[hl]
    ld e,a
    call LoadSpecialTrainerMoves
    jr .FinishUp
.NextSpecialTrainer1
    inc hl
.NextSpecialTrainer2
    inc hl
    inc hl
    jr .loopAdditionalMoveData
.FinishUp ; XXX this needs documenting
    xor a       ; clear D079-D07B
    ld de,$D079
    ld [de],a
    inc de
    ld [de],a
    inc de
    ld [de],a
    ld a,[W_CURENEMYLVL]
    ld b,a
.LastLoop
    ld hl,$D047
    ld c,2
    push bc
    PREDEF Func_f81d
    pop bc
    inc de
    inc de
    dec b
    jr nz,.LastLoop
    ret

; ──────────────────────────────────────────────────────────────────────

LoadSpecialTrainerMoves:
    ld h,d
    ld l,e
    ld b,0
.writeAdditionalMoveDataLoop
    ld a,[hl]
    and a
    jr z,.FinishUp
    ld a,b
    push bc
    push hl
    ld hl,W_ENEMYMON1MOVE3-2 ; W_ENEMYMON1MOVE1
    ld bc,44
    call AddNTimes
    ld d,h
    ld e,l
    pop hl
    ld bc,4
    call CopyData ; copy bc bytes of data from hl to de
;    call .WritePP
    pop bc
    inc b
    jr .writeAdditionalMoveDataLoop
.FinishUp
    ret
